window.onPoCustomerChange = function() {
    if (window.isPoLoading) return;
    if (typeof window.updatePOVendorFieldVisibility === 'function') {
        window.updatePOVendorFieldVisibility();
    }
    if (typeof window.populateFjwInhouseDropdown === 'function') {
        window.populateFjwInhouseDropdown();
    }
    if (typeof window.populateFjwVendorPoDropdown === 'function') {
        window.populateFjwVendorPoDropdown();
    }
};

window.populateFjwInhouseDropdown = function() {
    const selectEl = document.getElementById('po-fjw-inhouse-select');
    if (!selectEl) return;
    
    const currentSelectedVal = selectEl.value;

    const typeVal = document.getElementById('po-type')?.value;
    if (typeVal !== 'finishing_jw') return;
    
    const custId = document.getElementById('po-customer')?.value;

    const isInhousePO = function(p) {
        if (!p || p.status === 'Cancelled') return false;
        const pType = (p.poType || p.po_type || '').toLowerCase();
        const pNum = (p.number || p.poNo || '').toUpperCase();
        return pType === 'inhouse' || pType === 'inhouse_po' || pType === 'po_inhouse' || pNum.startsWith('PO/INH') || pNum.includes('/INH');
    };
    
    let targetEditPoId = document.getElementById('po-edit-id')?.value || '';
    let linkedIdVal = currentSelectedVal || '';
    if (targetEditPoId) {
        const editPo = (db.pos || []).find(p => String(p.id) === String(targetEditPoId));
        if (editPo) {
            const meta = typeof parseMetadataFromRemarks === 'function' ? parseMetadataFromRemarks(editPo.remarks, '__FJW_META__') : null;
            const fjwMeta = (meta && meta.links) ? meta.links : (meta || {});
            linkedIdVal = linkedIdVal || editPo.linkedPoId || editPo.linked_po_id || fjwMeta.linkedPoId || fjwMeta.linkedPoNumber || (editPo.items && editPo.items[0] && (editPo.items[0].linkedVendorPoId || editPo.items[0].linkedPoId)) || '';
        }
    }

    let inhousePOs = (db.pos || []).filter(p => {
        if (!isInhousePO(p)) return false;
        if (linkedIdVal && (String(p.id) === String(linkedIdVal) || String(p.number || '').toUpperCase() === String(linkedIdVal).toUpperCase())) return true;
        if (custId) {
            const pCustId = p.customerId || p.customer_id || p.customer || '';
            if (pCustId && String(pCustId) === String(custId)) return true;
            const selectedCust = (db.customers || []).find(c => String(c.id) === String(custId));
            const selectedCustName = selectedCust ? (selectedCust.name || '').trim().toLowerCase() : '';
            const pCustName = String(p.customerName || p.customer_name || '').trim().toLowerCase();
            if (selectedCustName && pCustName && pCustName === selectedCustName) return true;
            return false;
        }
        return true;
    });

    if (inhousePOs.length === 0) {
        inhousePOs = (db.pos || []).filter(p => isInhousePO(p));
    }
    
    selectEl.innerHTML = '<option value="">-- Select In-house PO --</option>';

    inhousePOs.forEach(p => {
        const option = document.createElement('option');
        option.value = p.id;
        option.dataset.poNumber = p.number || '';
        const pCustId = p.customerId || p.customer_id || p.customer || '';
        const custName = p.customerName || (db.customers ? db.customers.find(c => String(c.id) === String(pCustId))?.name : null) || '';
        
        let itemNames = [];
        if (p.items && Array.isArray(p.items)) {
            itemNames = p.items.map(it => it.processName || it.itemName || it.item_name || it.finishedItemName || it.design).filter(Boolean);
        }
        if (itemNames.length === 0) {
            const fallbackItem = p.finishedItemName || p.itemName || p.design || '';
            if (fallbackItem && fallbackItem !== '-') itemNames.push(fallbackItem);
        }
        const uniqueItems = Array.from(new Set(itemNames)).join(', ');
        const itemStr = uniqueItems ? ` [Item: ${uniqueItems}]` : '';

        option.textContent = `${p.number} ${custName ? `(${custName})` : ''}${itemStr} - Qty: ${p.qty || 0}m`;
        selectEl.appendChild(option);
    });

    if (linkedIdVal) {
        const matchedOpt = Array.from(selectEl.options).find(opt => 
            String(opt.value) === String(linkedIdVal) || 
            String(opt.dataset?.poNumber || '').toUpperCase() === String(linkedIdVal).toUpperCase()
        );
        if (matchedOpt) {
            selectEl.value = matchedOpt.value;
        } else {
            const targetPoObj = (db.pos || []).find(p => String(p.id) === String(linkedIdVal) || String(p.number || '').toUpperCase() === String(linkedIdVal).toUpperCase());
            if (targetPoObj) {
                const option = document.createElement('option');
                option.value = targetPoObj.id;
                option.dataset.poNumber = targetPoObj.number || '';
                const pCustId = targetPoObj.customerId || targetPoObj.customer_id || targetPoObj.customer || '';
                const custName = targetPoObj.customerName || (db.customers ? db.customers.find(c => String(c.id) === String(pCustId))?.name : null) || '';
                option.textContent = `${targetPoObj.number} ${custName ? `(${custName})` : ''} - Qty: ${targetPoObj.qty || 0}m`;
                selectEl.appendChild(option);
                selectEl.value = targetPoObj.id;
            }
        }
    }

    if (typeof reinitSearchableSelect === 'function') reinitSearchableSelect(selectEl);
};

window.isVendorPoLinkedToCustomer = function(p, custId) {
    if (!custId) return true;
    const cleanCustId = String(custId).trim().toLowerCase();
    
    // Find customer object
    const selectedCust = (db.customers || []).find(c => String(c.id).trim().toLowerCase() === cleanCustId);
    const selectedCustName = selectedCust ? (selectedCust.name || '').trim().toLowerCase() : '';

    // 1. Direct customer check on PO
    const pCustId = String(p.customerId || p.customer_id || p.customer || '').trim().toLowerCase();
    if (pCustId && pCustId === cleanCustId) return true;

    const pCustName = String(p.customerName || p.customer_name || '').trim().toLowerCase();
    if (selectedCustName && pCustName && pCustName === selectedCustName) return true;

    // 2. Linked SO check on PO
    const pSoId = String(p.soId || p.so_id || p.linkedSoId || p.linked_so_id || '').trim().toLowerCase();
    const pSoNo = String(p.soNo || p.so_no || p.linkedSoNumber || p.soNumber || '').trim().toUpperCase();

    if (pSoId || pSoNo) {
        const matchedSo = (db.salesOrders || []).find(s => 
            (pSoId && String(s.id).trim().toLowerCase() === pSoId) ||
            (pSoNo && String(s.soNo || s.number || '').trim().toUpperCase() === pSoNo)
        );
        if (matchedSo) {
            const sCustId = String(matchedSo.customerId || matchedSo.customer_id || matchedSo.customer || '').trim().toLowerCase();
            if (sCustId && sCustId === cleanCustId) return true;
            const sCustName = String(matchedSo.customerName || matchedSo.customer_name || matchedSo.customer || '').trim().toLowerCase();
            if (selectedCustName && sCustName && sCustName === selectedCustName) return true;
        }
    }

    return false;
};

