// ===== STATE =====
let db = {};
let masterDB = {};
let currentUser = null;

window.resolveRecordItemName = function(rec) {
    if (!rec) return '-';
    if (rec.isPlaceholder) return '-';

    const resolveFromSingleObj = (obj) => {
        if (!obj) return null;
        let names = [];
        
        let itemsArr = obj.items;
        if ((!itemsArr || !itemsArr.length) && obj.remarks && typeof obj.remarks === 'string' && obj.remarks.includes('__ITEMS__:')) {
            try {
                const match = obj.remarks.match(/__ITEMS__:(\[.*?\])/);
                if (match) itemsArr = JSON.parse(match[1]);
            } catch (e) {}
        }
        
        if (itemsArr && Array.isArray(itemsArr) && itemsArr.length > 0) {
            itemsArr.forEach(it => {
                if (!it) return;
                if (typeof it === 'string' && it !== '-') {
                    names.push(it);
                    return;
                }
                const itId = it.itemId || it.item_id || it.designId || it.design_id;
                if (itId) {
                    const itemObj = (db.items || []).find(x => String(x.id) === String(itId)) || ((rawDB && rawDB.items) || []).find(x => String(x.id) === String(itId));
                    if (itemObj && (itemObj.name || itemObj.itemName || itemObj.item_name || itemObj.title)) {
                        names.push(itemObj.name || itemObj.itemName || itemObj.item_name || itemObj.title);
                        return;
                    }
                }
                const rawName = it.name || it.itemName || it.item_name || it.processName || it.designNumber || it.designName || it.fabricType || '';
                if (rawName && rawName !== '-') {
                    names.push(rawName);
                }
            });
        }

        if (names.length === 0) {
            const directItemId = obj.itemId || obj.item_id || obj.designId || obj.design_id || obj.finishedItemId || obj.finished_item_id;
            if (directItemId) {
                const itemObj = (db.items || []).find(x => String(x.id) === String(directItemId)) || ((rawDB && rawDB.items) || []).find(x => String(x.id) === String(directItemId));
                if (itemObj && (itemObj.name || itemObj.itemName || itemObj.item_name || itemObj.title)) {
                    names.push(itemObj.name || itemObj.itemName || itemObj.item_name || itemObj.title);
                }
            }
        }
        
        if (names.length === 0) {
            const directName = obj.name || obj.itemName || obj.item_name || obj.designNumber || obj.design_number || obj.design || obj.designName || obj.design_name || obj.finishedItemName || obj.finished_item_name || obj.fabricType || obj.fabric_type || obj.processName || obj.process_name || obj.title || '';
            if (directName && directName !== '-') {
                names.push(directName);
            }
        }

        if (names.length === 0 && (obj.bomId || obj.bom_id)) {
            const bomObj = (db.boms || []).find(b => b.id === (obj.bomId || obj.bom_id));
            if (bomObj && (bomObj.finishedItemName || bomObj.name)) {
                names.push(bomObj.finishedItemName || bomObj.name);
            }
        }
        
        const unique = [...new Set(names.map(s => String(s || '').trim()).filter(Boolean))];
        return unique.length > 0 ? (window.formatUniqueItemNames ? window.formatUniqueItemNames(unique) : unique.join(', ')) : null;
    };

    // 1. If record links to a PO (e.g. FJW PO linked to In-House PO / Vendor PO), resolve item name from the linked PO first!
    let fjwMeta = {};
    if (rec.remarks && typeof rec.remarks === 'string' && rec.remarks.includes('__FJW_META__')) {
        const meta = typeof parseMetadataFromRemarks === 'function' ? parseMetadataFromRemarks(rec.remarks, '__FJW_META__') : null;
        if (meta) fjwMeta = meta.links || meta;
    }
    const linkedPoId = rec.linkedPoId || rec.linked_po_id || fjwMeta.linkedPoId || (rec.items && rec.items[0] && rec.items[0].linkedVendorPoId);
    const linkedPoNum = rec.linkedPoNumber || rec.linked_po_number || fjwMeta.linkedPoNumber;
    if (linkedPoId || linkedPoNum) {
        const pos = (db.pos || []).concat((rawDB && rawDB.pos) || []);
        const targetPo = pos.find(p => String(p.id) !== String(rec.id) && ((linkedPoId && (String(p.id) === String(linkedPoId) || String(p.number || '').toUpperCase() === String(linkedPoId).toUpperCase())) || (linkedPoNum && String(p.number || '').toUpperCase() === String(linkedPoNum).toUpperCase())));
        if (targetPo) {
            const nameFromPo = resolveFromSingleObj(targetPo);
            if (nameFromPo && nameFromPo !== '-') return nameFromPo;

            const targetPoSoId = targetPo.linkedSoId || targetPo.linked_so_id || targetPo.soRef || targetPo.soRefId;
            const targetPoSoNum = targetPo.linkedSoNumber || targetPo.linked_so_number || targetPo.soNumber || targetPo.soNo;
            if (targetPoSoId || targetPoSoNum) {
                const sos = (db.salesOrders || []).concat((rawDB && rawDB.salesOrders) || []);
                const targetSo = sos.find(s => (targetPoSoId && s.id === targetPoSoId) || (targetPoSoNum && s.number === targetPoSoNum));
                if (targetSo) {
                    const nameFromSo = resolveFromSingleObj(targetSo);
                    if (nameFromSo && nameFromSo !== '-') return nameFromSo;
                }
            }
        }
    }

    // 2. If PO / Outward / GRN links to a Sales Order, try resolving item name from the linked Sales Order!
    const linkedSoId = rec.linkedSoId || rec.linked_so_id || rec.soRef || rec.soRefId;
    const linkedSoNum = rec.linkedSoNumber || rec.linked_so_number || rec.soNumber || rec.soNo || rec.so_number;
    if (linkedSoId || linkedSoNum) {
        const sos = (db.salesOrders || []).concat((rawDB && rawDB.salesOrders) || []);
        const targetSo = sos.find(s => (linkedSoId && s.id === linkedSoId) || (linkedSoNum && s.number === linkedSoNum));
        if (targetSo) {
            const nameFromSo = resolveFromSingleObj(targetSo);
            if (nameFromSo && nameFromSo !== '-') return nameFromSo;
        }
    }

    // 3. Otherwise resolve directly from rec
    const nameFromSelf = resolveFromSingleObj(rec);
    if (nameFromSelf && nameFromSelf !== '-') return nameFromSelf;

    return '-';
};

window.getSoDesignOrItemDisplay = function(so) {
    if (!so) return '-';
    const res = window.resolveRecordItemName(so);
    return (res && res !== '-') ? res : 'Pending';
};

window.getPoDesignDisplay = function(po) {
    if (!po) return '';
    const res = window.resolveRecordItemName(po);
    return (res && res !== '-') ? res : '';
};

window.resolveRecordUnit = function(rec) {
    if (!rec) return 'm';
    if (rec.isPlaceholder) return 'm';

    const pNum = (rec.number || rec.poNumber || rec.soNumber || '').toUpperCase().trim();
    const pType = (rec.poType || rec.po_type || '').toLowerCase().trim();

    const formatUnit = (u) => {
        if (!u) return '';
        const norm = String(u).trim().toLowerCase();
        if (norm === 'm' || norm === 'mtr' || norm === 'mtr.' || norm === 'met' || norm === 'metre' || norm === 'meter') return 'm';
        if (typeof window.getItemUnitSymbol === 'function') {
            const sym = window.getItemUnitSymbol({ unit: u });
            if (sym && sym !== 'Meter') return sym;
            if (sym === 'Meter') return 'm';
        }
        return u.trim();
    };

    // 1. Direct unit on record
    if (rec.unit && typeof rec.unit === 'string' && rec.unit.trim()) {
        return formatUnit(rec.unit);
    }
    if (rec.unitName && typeof rec.unitName === 'string' && rec.unitName.trim()) {
        return formatUnit(rec.unitName);
    }

    // 2. Check items array
    let itemsArr = rec.items;
    if ((!itemsArr || !itemsArr.length) && rec.remarks && typeof rec.remarks === 'string' && rec.remarks.includes('__ITEMS__:')) {
        try {
            const match = rec.remarks.match(/__ITEMS__:(\[.*?\])/);
            if (match) itemsArr = JSON.parse(match[1]);
        } catch (e) {}
    }

    const dbItems = (window.db && window.db.items) || (typeof db !== 'undefined' && db && db.items) || ((typeof rawDB !== 'undefined' && rawDB && rawDB.items) || []);

    if (itemsArr && Array.isArray(itemsArr) && itemsArr.length > 0) {
        const units = [];
        itemsArr.forEach(it => {
            if (!it) return;
            let u = it.unit || it.unitName || it.uom || it.unit_symbol || '';
            if (!u) {
                const itId = it.itemId || it.item_id || it.designId || it.design_id;
                let itemObj = null;
                if (itId) {
                    itemObj = dbItems.find(x => String(x.id) === String(itId));
                }
                if (!itemObj) {
                    const rawName = it.name || it.itemName || it.item_name || it.processName || it.designNumber || it.designName || '';
                    if (rawName) {
                        const rawLower = String(rawName).trim().toLowerCase();
                        itemObj = dbItems.find(x => x.name && String(x.name).trim().toLowerCase() === rawLower);
                    }
                }
                if (itemObj) {
                    u = itemObj.unit || itemObj.base_unit || itemObj.uom || '';
                }
            }
            if (u) {
                units.push(formatUnit(u));
            }
        });

        const uniqueUnits = [...new Set(units.map(u => String(u).trim()).filter(Boolean))];
        if (uniqueUnits.length > 0) {
            return uniqueUnits.join(', ');
        }
    }

    // 3. Fallback check for single item on record root
    const directItemId = rec.itemId || rec.item_id || rec.designId || rec.design_id;
    let rootItemObj = null;
    if (directItemId) {
        rootItemObj = dbItems.find(x => String(x.id) === String(directItemId));
    }
    if (!rootItemObj) {
        const directName = rec.name || rec.itemName || rec.item_name || rec.processName || rec.designNumber || rec.design || '';
        if (directName) {
            const rawLower = String(directName).trim().toLowerCase();
            rootItemObj = dbItems.find(x => x.name && String(x.name).trim().toLowerCase() === rawLower);
        }
    }
    if (rootItemObj && (rootItemObj.unit || rootItemObj.base_unit || rootItemObj.uom)) {
        return formatUnit(rootItemObj.unit || rootItemObj.base_unit || rootItemObj.uom);
    }

    // 4. Default fallback:
    if (pType === 'consumable' || pNum.startsWith('PO/CON')) {
        return 'Kg';
    }

    return 'm';
};

window.getOutwardFabricConsumed = function(o) {
    if (!o) return 0;
    
    // 1. Check packageSlips, embroideryItems, or items arrays (used for embroidery fabric consumed / item details)
    const slips = (Array.isArray(o.packageSlips) && o.packageSlips.length > 0) ? o.packageSlips :
                  (Array.isArray(o.embroideryItems) && o.embroideryItems.length > 0) ? o.embroideryItems :
                  (Array.isArray(o.items) && o.items.length > 0) ? o.items : null;
                  
    if (slips && slips.length > 0) {
        const slipSum = slips.reduce((sum, s) => {
            const q = parseFloat(s.qty || s.consumedQty || s.fabricConsumed || s.invoicedQty || 0) || 0;
            return sum + q;
        }, 0);
        if (slipSum > 0) return slipSum;
    }
    
    // 2. Check direct fabric consumed properties
    const directConsumed = parseFloat(o.fabricConsumed || o.consumedQty || o.fabric_consumed || o.consumed_qty || 0);
    if (directConsumed > 0) return directConsumed;
    
    // 3. Fallback to o.qty / o.meters
    return parseFloat(o.qty || o.meters || o.totalMeters || 0);
};

window.getOutwardEmbQty = function(o) {
    if (!o) return 0;
    const slips = (Array.isArray(o.packageSlips) && o.packageSlips.length > 0) ? o.packageSlips :
                  (Array.isArray(o.embroideryItems) && o.embroideryItems.length > 0) ? o.embroideryItems :
                  (Array.isArray(o.items) && o.items.length > 0) ? o.items : null;
    if (slips && slips.length > 0) {
        const slipSum = slips.reduce((sum, s) => {
            const q = parseFloat(s.embroideryQty || s.embQty || s.workQty || s.stiches || s.qty || 0) || 0;
            return sum + q;
        }, 0);
        if (slipSum > 0) return slipSum;
    }
    return parseFloat(o.embroideryQty || o.embQty || o.qty || o.meters || 0);
};

window.getLinkedSalesInvoiceForOutward = function(o) {
    if (!o) return '-';
    const invNo = o.salesInvoiceNo || o.invoiceNo || o.linkedInvoiceNo || o.invoice_no;
    const invDate = o.salesInvoiceDate || o.invoiceDate || o.linkedInvoiceDate || o.invoice_date;
    if (invNo) {
        return (invDate && invDate !== '-') ? `${invNo} (${typeof formatDate === 'function' ? formatDate(invDate) : invDate})` : invNo;
    }
    if (typeof window.getRamaInvoiceInfo === 'function') {
        const ramaInfo = window.getRamaInvoiceInfo(o);
        if (ramaInfo && ramaInfo.invoiceNo && ramaInfo.invoiceNo !== '-') {
            return (ramaInfo.invoiceDate && ramaInfo.invoiceDate !== '-')
                ? `${ramaInfo.invoiceNo} (${typeof formatDate === 'function' ? formatDate(ramaInfo.invoiceDate) : ramaInfo.invoiceDate})`
                : ramaInfo.invoiceNo;
        }
    }
    const oId = String(o.id || '');
    const oNum = String(o.number || o.grnNo || '').toLowerCase();
    const matchedInv = (db.invoices || []).find(inv => {
        if ((inv.status || '').toLowerCase() === 'cancelled') return false;
        const links = [];
        if (Array.isArray(inv.linkedOrderIds)) links.push(...inv.linkedOrderIds);
        if (inv.items && Array.isArray(inv.items)) {
            inv.items.forEach(it => {
                if (it.orderId) links.push(it.orderId);
                if (it.voucherId) links.push(it.voucherId);
                if (it.voucherNo) links.push(it.voucherNo);
            });
        }
        const lowerLinks = links.map(x => String(x || '').toLowerCase().trim());
        return (oId && lowerLinks.includes(oId.toLowerCase())) || (oNum && lowerLinks.includes(oNum));
    });
    if (matchedInv) {
        const dStr = matchedInv.date ? (typeof formatDate === 'function' ? formatDate(matchedInv.date) : matchedInv.date) : '';
        return dStr ? `${matchedInv.number} (${dStr})` : matchedInv.number;
    }
    return '-';
};

window.getSoDispatchedQty = function(so) {
    if (!so) return 0;
    const soId = String(so.id || '');
    const soNum = String(so.number || '').trim().toLowerCase();

    // Find linked PO IDs for this SO to catch outwards linked via PO
    const linkedPOIds = (db.pos || []).filter(p =>
        (p.status || '').toLowerCase() !== 'cancelled' && (
            p.soRef === so.id || p.linkedSoId === so.id || (so.number && (p.linkedSoNumber === so.number || p.soRef === so.number))
        )
    ).map(p => String(p.id));

    let outwardDispatchedQty = 0;

    (db.outwards || []).forEach(o => {
        if ((o.status || '').toLowerCase() === 'cancelled') return;
        const oNum = String(o.number || '').trim().toUpperCase();
        const isNonCustomerIssue = oNum.startsWith('FI/INH') || oNum.startsWith('FI/V') || o.type === 'inhouse' || o.subType === 'inhouse' || o.poType === 'inhouse' || o.po_type === 'inhouse' || o.source === 'vendor' || o.subType === 'vendor';
        if (isNonCustomerIssue) return;

        const targetSoId = o.linkedSoId || o.linked_so_id || o.soRef || o.soRefId;
        const targetSoNum = o.linkedSoNumber || o.linked_so_number || o.soNumber || o.soNo || o.so_number;
        const targetPoId = String(o.poRefId || o.linked_po_id || o.poRef || '');

        const isLinkedToSo = (targetSoId && String(targetSoId) === soId) || 
                             (targetSoNum && String(targetSoNum).trim().toLowerCase() === soNum) ||
                             (targetPoId && linkedPOIds.includes(targetPoId));
        if (isLinkedToSo) {
            const consumedQty = window.getOutwardFabricConsumed(o);
            outwardDispatchedQty += consumedQty;
        }
    });

    return Math.max(0, outwardDispatchedQty);
};
