window.getOrderPendencyAdjustment = function(record) {
    if (!record || !record.remarks) return { type: 'None', qty: 0, reason: '' };
    if (typeof parseMetadataFromRemarks === 'function') {
        const meta = parseMetadataFromRemarks(record.remarks, '__PENDENCY_ADJUSTMENT__');
        if (meta && (meta.type || meta.qty)) {
            return {
                type: meta.type || 'Round Off',
                qty: parseFloat(meta.qty) || 0,
                reason: meta.reason || ''
            };
        }
    }
    return { type: 'None', qty: 0, reason: '' };
};

window.parseGrnTransportState = function(grn) {
    if (!grn) return { freightPaymentType: 'To Pay', isTransporter: 'No', hasTransporter: 'No', isLocalFreight: 'No', hasLocalFreight: 'No' };
    const remarks = (typeof grn === 'string') ? grn : (grn.remarks || grn.Remarks || '');
    const match = typeof remarks === 'string' ? remarks.match(/\[TRANSPORT:(\{.*?\})\]/) : null;
    let parsed = {};
    if (match) {
        try {
            parsed = JSON.parse(match[1]) || {};
        } catch (e) {}
    }

    let isTrans = parsed.isTransporter || parsed.hasTransporter || (typeof grn === 'object' ? (grn.hasTransporter || grn.isTransporter) : null);
    if (isTrans === true || isTrans === 'true') isTrans = 'Yes';
    if (isTrans === false || isTrans === 'false') isTrans = 'No';
    if (!isTrans || isTrans === 'No') {
        const hasTDetails = !!(typeof grn === 'object' && (grn.transporterId || grn.transporterName || grn.transporter || grn.lrNo || grn.lrNumber) || parsed.transporterId || parsed.transporterName || parsed.lrNo);
        if (hasTDetails) isTrans = 'Yes';
        else if (!isTrans) isTrans = 'No';
    }

    let isLocal = parsed.isLocalFreight || parsed.hasLocalFreight || (typeof grn === 'object' ? (grn.isLocalFreight || grn.hasLocalFreight) : null);
    if (isLocal === true || isLocal === 'true') isLocal = 'Yes';
    if (isLocal === false || isLocal === 'false') isLocal = 'No';
    if (!isLocal || isLocal === 'No') {
        const hasLDetails = !!(typeof grn === 'object' && (grn.taxiName || grn.vehicleNo || grn.vehicleNumber) || parsed.taxiName || parsed.vehicleNo);
        if (hasLDetails) isLocal = 'Yes';
        else if (!isLocal) isLocal = 'No';
    }

    if (!parsed.freightPaymentType) parsed.freightPaymentType = 'To Pay';

    return {
        ...parsed,
        isTransporter: isTrans,
        hasTransporter: isTrans,
        isLocalFreight: isLocal,
        hasLocalFreight: isLocal,
        transporterName: parsed.transporterName || (typeof grn === 'object' ? (grn.transporterName || grn.transporter || '') : ''),
        transporterId: parsed.transporterId || (typeof grn === 'object' ? (grn.transporterId || grn.transporter_id || '') : ''),
        lrNo: parsed.lrNo || (typeof grn === 'object' ? (grn.lrNo || grn.lrNumber || grn.lr_number || '') : ''),
        taxiName: parsed.taxiName || (typeof grn === 'object' ? (grn.taxiName || '') : ''),
        vehicleNo: parsed.vehicleNo || (typeof grn === 'object' ? (grn.vehicleNo || grn.vehicleNumber || '') : '')
    };
};
if (typeof parseGrnTransportState === 'undefined') {
    var parseGrnTransportState = window.parseGrnTransportState;
}


window.grnWizardState = window.grnWizardState || { type: 'fabric', source: 'customer', subType: 'plain' };
if (typeof grnWizardState === 'undefined') {
    var grnWizardState = window.grnWizardState;
}

window.parseGrnWizardState = function(grn) {
    if (!grn) return { type: 'fabric', source: 'customer', subType: 'plain' };
    if (typeof parseGrnWizardStateForSync === 'function') {
        const syn = parseGrnWizardStateForSync(grn);
        if (syn && syn.type) return syn;
    }
    const remarks = (typeof grn === 'string') ? grn : (grn.remarks || grn.Remarks || '');
    const match = typeof remarks === 'string' ? remarks.match(/\[WIZARD:(\{.*?\})\]/) : null;
    let wizardMeta = null;
    if (match) {
        try {
            wizardMeta = JSON.parse(match[1]);
        } catch (e) {}
    }
    const num = ((typeof grn === 'object' && (grn.number || grn.grnNo)) ? (grn.number || grn.grnNo) : (typeof grn === 'string' ? grn : '')).trim().toUpperCase();
    let prefixState = null;
    if (num.includes('GRN/C/PF') || num.includes('GRN/C/PL')) prefixState = { type: 'fabric', source: 'customer', subType: 'plain' };
    else if (num.includes('GRN/C/EM') || num.includes('GRN/C/EMB')) prefixState = { type: 'fabric', source: 'customer', subType: 'embroidered' };
    else if (num.includes('GRN/V/PF') || num.includes('GRN/V/PL')) prefixState = { type: 'fabric', source: 'vendor', subType: 'plain' };
    else if (num.includes('GRN/V/EM') || num.includes('GRN/V/EMB')) prefixState = { type: 'fabric', source: 'vendor', subType: 'embroidered' };
    else if (num.includes('GRN/CON') || num.includes('/CON/')) prefixState = { type: 'consumable', source: 'vendor', subType: '' };
    else if (num.includes('GRN/OTH') || num.includes('/OTH/')) prefixState = { type: 'other', source: 'vendor', subType: '' };

    if (prefixState) {
        return Object.assign({}, wizardMeta || {}, prefixState);
    }
    if (wizardMeta) return wizardMeta;
    return { type: 'fabric', source: 'customer', subType: 'plain' };
};


let currentFinancialYear = '2026-27';

const financialYears = {
    '2024-25': { start: '2024-04-01', end: '2025-03-31', suffix: '/24-25' },
    '2025-26': { start: '2025-04-01', end: '2026-03-31', suffix: '/25-26' },
    '2026-27': { start: '2026-04-01', end: '2027-03-31', suffix: '/26-27' },
    '2027-28': { start: '2027-04-01', end: '2028-03-31', suffix: '/27-28' }
};

let rawDB = {
    grns: [],
    pos: [],
    productionLogs: [],
    purchases: [],
    salesOrders: [],
    outwards: [],
    productionSlips: [],
    genericTransactions: [],
    requisitionSlips: [],
    gatePasses: []
};

function isDateInCurrentFY(dateStr, number) {
    const fyConfig = (typeof financialYears !== 'undefined' && typeof currentFinancialYear !== 'undefined') ? financialYears[currentFinancialYear] : null;
    if (!fyConfig) return true;

    const targetSuffix = (fyConfig.suffix || '').replace('/', '').toLowerCase();
    const shortTargetSuffix = targetSuffix.replace(/^20/, '');

    if (number) {
        const formattedNum = window.formatStandardDocNumber ? window.formatStandardDocNumber(number) : String(number);
        const numLower = String(formattedNum).toLowerCase();
        
        // Extract explicit FY pattern if present in doc number (e.g. 24-25, 25-26, 26-27, 27-28)
        const fyMatch = numLower.match(/\b(20\d{2}-\d{2}|\d{2}-\d{2})\b/);
        if (fyMatch) {
            const numFy = fyMatch[1].replace(/^20/, '');
            // If the document number explicitly specifies an FY, it MUST match the selected FY's suffix
            if (numFy !== shortTargetSuffix) {
                return false;
            }
        }
    }

    if (!dateStr) return true;

    const isoDate = window.parseDateToISO ? window.parseDateToISO(dateStr) : dateStr;
    if (!isoDate || isoDate.length < 10) return false;

    const cleanDate = isoDate.substring(0, 10);
    return cleanDate >= fyConfig.start && cleanDate <= fyConfig.end;
}

function validateTransactionDate(dateStr) {
    if (!isDateInCurrentFY(dateStr)) {
        const fyConfig = (typeof financialYears !== 'undefined' && typeof currentFinancialYear !== 'undefined') ? financialYears[currentFinancialYear] : { start: '2026-04-01', end: '2027-03-31' };
        const label = currentFinancialYear || 'Selected FY';
        showToast(`Transaction date must fall within the selected Financial Year (${label}: ${fyConfig.start} to ${fyConfig.end})`, 'error');
        return false;
    }
    
    // Enforce back-date restriction guardrail
    if (window.isBackDateRestricted && window.isBackDateRestricted()) {
        const maxDays = window.getBackDateDaysAllowed ? window.getBackDateDaysAllowed() : 0;
        const today = new Date();
        today.setHours(0,0,0,0);
        
        const limitDate = new Date(today.getTime());
        limitDate.setDate(limitDate.getDate() - maxDays);
        
        const limitDateStr = limitDate.getFullYear() + '-' + String(limitDate.getMonth() + 1).padStart(2, '0') + '-' + String(limitDate.getDate()).padStart(2, '0');
        
        if (dateStr < limitDateStr) {
            if (maxDays === 0) {
                showToast(`Back-dated entries are restricted for your user account. Please select today's date or contact your administrator.`, 'error');
            } else {
                showToast(`Back-dated entries are restricted beyond ${maxDays} days for your user account. Selected date is too far in the past.`, 'error');
            }
            return false;
        }
    }
    return true;
}

window.parseVoucherSeqNumber = function(numStr) {
    if (!numStr) return 0;
    const str = String(numStr).trim();
    // 1. Format: NUM/FY (e.g. "1/2026-27" or "1/26-27")
    const numFyMatch = str.match(/^(\d+)\/(?:\d{4}-\d{2}|\d{2}-\d{2})$/i);
    if (numFyMatch) return parseInt(numFyMatch[1], 10);
    
    // 2. Format: PREFIX/FY/NUM (e.g. "INV/26-27/005" or "SO/26-27/001")
    const prefFyNumMatch = str.match(/(?:[A-Z0-9_\-\/]+)\/(?:\d{4}-\d{2}|\d{2}-\d{2})\/(\d+)/i);
    if (prefFyNumMatch) return parseInt(prefFyNumMatch[1], 10);

    // 3. Format: PREFIX/NUM (e.g. "INV/5")
    const prefNumMatch = str.match(/(?:[A-Z0-9_\-]+)\/(\d+)$/i);
    if (prefNumMatch) return parseInt(prefNumMatch[1], 10);

    // 4. Fallback: Pure number
    const pureNumMatch = str.match(/^(\d+)$/);
    if (pureNumMatch) return parseInt(pureNumMatch[1], 10);

    // 5. General fallback: Match digits before trailing non-digits or end
    const lastDigits = str.match(/(\d+)(?:\D*)$/);
    if (lastDigits) return parseInt(lastDigits[1], 10);
    
    return 0;
};

window.validateDocumentDateChronology = function(tableKey, docNumber, dateStr, editId = null) {
    if (!docNumber || !dateStr) return true;

    // Standardize input date to YYYY-MM-DD
    const inputIsoDate = window.parseDateToISO ? window.parseDateToISO(dateStr) : dateStr;
    if (!inputIsoDate || inputIsoDate.length < 10) return true;
    const cleanInputIsoDate = inputIsoDate.substring(0, 10);

    // Standardize document number
    const stdDocNum = window.formatStandardDocNumber ? window.formatStandardDocNumber(docNumber) : String(docNumber).trim();
    const currentSeq = window.parseVoucherSeqNumber ? window.parseVoucherSeqNumber(stdDocNum) : 0;
    if (!currentSeq || currentSeq <= 0) return true;

    // Parse series prefix
    const parts = stdDocNum.split('/');
    if (parts.length < 2) return true;
    const currentPrefix = parts.slice(0, parts.length - 1).join('/').toUpperCase();

    // Determine target records array
    let records = [];
    if (Array.isArray(tableKey)) {
        records = tableKey;
    } else if (typeof tableKey === 'string') {
        const k = tableKey.toLowerCase();
        const getMergedList = (rawKey, dbKey) => {
            const rawList = (window.rawDB && window.rawDB[rawKey]) || [];
            const dbList = (window.db && (window.db[dbKey] || window.db[rawKey])) || [];
            const combined = [...rawList];
            dbList.forEach(item => {
                if (item && item.id && !combined.some(x => String(x.id) === String(item.id))) {
                    combined.push(item);
                }
            });
            return combined;
        };

        if (k === 'outwards' || k === 'outward') records = getMergedList('outwards', 'outwards');
        else if (k === 'grns' || k === 'grn') records = getMergedList('grns', 'grns');
        else if (k === 'pos' || k === 'po' || k === 'purchase_orders') records = getMergedList('pos', 'pos');
        else if (k === 'sales_orders' || k === 'salesorders' || k === 'so') records = getMergedList('salesOrders', 'sales_orders');
        else if (k === 'production_plans' || k === 'productionplans') records = getMergedList('productionPlans', 'production_plans');
        else if (k === 'production_slips' || k === 'productionslips') records = getMergedList('productionSlips', 'production_slips');
        else if (k === 'requisition_slips' || k === 'requisitions') records = getMergedList('requisitionSlips', 'requisition_slips');
        else if (k === 'generic_transactions' || k === 'generictransactions') records = getMergedList('genericTransactions', 'generic_transactions');
        else if (k === 'gate_passes' || k === 'gatepasses') records = getMergedList('gatePasses', 'gate_passes');
    }

    if (!records || records.length === 0) return true;

    let prevRecord = null;
    let prevSeq = -1;
    let nextRecord = null;
    let nextSeq = Infinity;

    for (let i = 0; i < records.length; i++) {
        const r = records[i];
        if (!r) continue;

        // Skip current record if editing
        if (editId && (String(r.id) === String(editId) || String(r._id) === String(editId))) continue;

        // Skip cancelled records
        if (r.status && String(r.status).trim().toLowerCase() === 'cancelled') continue;

        const recDocNumRaw = r.number || r.outwardNo || r.grnNo || r.poNo || r.soNo || r.voucherNo || r.gatepassNo || r.slipNo || r.reqNo || r.challanNo || '';
        if (!recDocNumRaw) continue;

        const recStdDocNum = window.formatStandardDocNumber ? window.formatStandardDocNumber(recDocNumRaw) : String(recDocNumRaw).trim();
        const recParts = recStdDocNum.split('/');
        if (recParts.length < 2) continue;

        const recPrefix = recParts.slice(0, recParts.length - 1).join('/').toUpperCase();
        if (recPrefix !== currentPrefix) continue;

        const recSeq = window.parseVoucherSeqNumber ? window.parseVoucherSeqNumber(recStdDocNum) : 0;
        if (!recSeq || recSeq <= 0) continue;

        if (recSeq < currentSeq && recSeq > prevSeq) {
            prevSeq = recSeq;
            prevRecord = r;
        }

        if (recSeq > currentSeq && recSeq < nextSeq) {
            nextSeq = recSeq;
            nextRecord = r;
        }
    }

    if (prevRecord) {
        const prevRawDate = prevRecord.date || prevRecord.chalan_date || prevRecord.chalanDate || prevRecord.poDate || prevRecord.soDate || prevRecord.entryDate || '';
        const prevIsoDate = window.parseDateToISO ? window.parseDateToISO(prevRawDate) : prevRawDate;
        const cleanPrevIsoDate = prevIsoDate ? prevIsoDate.substring(0, 10) : '';
        if (cleanPrevIsoDate && cleanInputIsoDate < cleanPrevIsoDate) {
            const displayInputDate = typeof formatDate === 'function' ? formatDate(cleanInputIsoDate) : cleanInputIsoDate;
            const displayPrevDate = typeof formatDate === 'function' ? formatDate(cleanPrevIsoDate) : cleanPrevIsoDate;
            const prevNum = window.formatStandardDocNumber ? window.formatStandardDocNumber(prevRecord.number || prevRecord.outwardNo || prevRecord.grnNo || prevRecord.poNo || prevRecord.soNo || prevRecord.voucherNo || '') : '';
            
            showToast(`Voucher Date Restriction: Selected date (${displayInputDate}) cannot be older than preceding voucher ${prevNum} date (${displayPrevDate}).`, 'error');
            return false;
        }
    }

    if (nextRecord) {
        const nextRawDate = nextRecord.date || nextRecord.chalan_date || nextRecord.chalanDate || nextRecord.poDate || nextRecord.soDate || nextRecord.entryDate || '';
        const nextIsoDate = window.parseDateToISO ? window.parseDateToISO(nextRawDate) : nextRawDate;
        const cleanNextIsoDate = nextIsoDate ? nextIsoDate.substring(0, 10) : '';
        if (cleanNextIsoDate && cleanInputIsoDate > cleanNextIsoDate) {
            const displayInputDate = typeof formatDate === 'function' ? formatDate(cleanInputIsoDate) : cleanInputIsoDate;
            const displayNextDate = typeof formatDate === 'function' ? formatDate(cleanNextIsoDate) : cleanNextIsoDate;
            const nextNum = window.formatStandardDocNumber ? window.formatStandardDocNumber(nextRecord.number || nextRecord.outwardNo || nextRecord.grnNo || nextRecord.poNo || nextRecord.soNo || nextRecord.voucherNo || '') : '';
            
            showToast(`Voucher Date Restriction: Selected date (${displayInputDate}) cannot be later than subsequent voucher ${nextNum} date (${displayNextDate}).`, 'error');
            return false;
        }
    }

    return true;
};


function getDocumentNumber(prefix, count) {
    const cleanPrefix = (prefix === 'invoice') ? 'INV' : prefix;
    const fySuffix = (financialYears[currentFinancialYear] || {}).suffix || '/26-27';
    const cleanSuffix = fySuffix.startsWith('/') ? fySuffix.substring(1) : fySuffix;
    const padding = 3;
    return `${cleanPrefix}/${cleanSuffix}/${String(count).padStart(padding, '0')}`;
}

window.formatStandardDocNumber = function(numStr) {
    if (!numStr) return '';
    let str = String(numStr).trim();
    const parts = str.split('/').map(p => p.trim());
    if (parts.length >= 3) {
        const last = parts[parts.length - 1];
        let secondLast = parts[parts.length - 2];
        if (secondLast && secondLast.length === 7 && /^20\d\d-\d\d$/.test(secondLast)) {
            secondLast = secondLast.substring(2);
        }
        if (/^\d+$/.test(last) && (/^\d{2}-\d{2}$/.test(secondLast) || /^\d{4}-\d{2}$/.test(secondLast))) {
            const prefix = parts.slice(0, parts.length - 2).join('/');
            str = prefix ? (prefix + '/' + secondLast + '/' + last) : (secondLast + '/' + last);
        } else if (/^\d+$/.test(secondLast) && (/^\d{2}-\d{2}$/.test(last) || /^\d{4}-\d{2}$/.test(last))) {
            let cleanLast = last;
            if (cleanLast.length === 7 && /^20\d\d-\d\d$/.test(cleanLast)) cleanLast = cleanLast.substring(2);
            const prefix = parts.slice(0, parts.length - 2).join('/');
            str = prefix ? (prefix + '/' + cleanLast + '/' + secondLast) : (cleanLast + '/' + secondLast);
        }
    } else if (parts.length === 2) {
        let [p1, p2] = parts;
        if (/^20\d\d-\d\d$/.test(p1)) p1 = p1.substring(2);
        if (/^20\d\d-\d\d$/.test(p2)) p2 = p2.substring(2);
        str = `${p1}/${p2}`;
    }
    str = str.replace(/\/20(\d\d-\d\d)(\/|$)/g, '/$1$2');
    return str;
};

window.ensureUniqueDocumentNumber = async function(tableName, numberColumn, currentNumber) {
    if (!currentNumber || !window.supabase) return currentNumber;
    
    if (window.formatStandardDocNumber) {
        currentNumber = window.formatStandardDocNumber(currentNumber);
    }
    
    // Parse prefix, suffix, and count
    const parts = currentNumber.split('/');
    if (parts.length < 3) return currentNumber;
    
    const countPart = parts[parts.length - 1];
    let suffixPart = parts[parts.length - 2];
    if (suffixPart && suffixPart.length === 7 && /^20\d\d-\d\d$/.test(suffixPart)) {
        suffixPart = suffixPart.substring(2);
    }
    const prefixPart = parts.slice(0, parts.length - 2).join('/');
    
    const cleanNumber = `${prefixPart}/${suffixPart}/${countPart}`;
    
    // 1. Live Check if cleanNumber already exists in Supabase
    const { data: dupCheck } = await window.supabase
        .from(tableName)
        .select(numberColumn)
        .or(`${numberColumn}.eq.${cleanNumber},${numberColumn}.eq.${prefixPart}/20${suffixPart}/${countPart}`)
        .limit(1);
        
    if (!dupCheck || dupCheck.length === 0) {
        return cleanNumber;
    }
    
    // 2. Fetch matching prefix/suffix numbers to find actual max value (checks both 2-digit and 4-digit FY)
    const { data: records } = await window.supabase
        .from(tableName)
        .select(numberColumn)
        .or(`${numberColumn}.like.${prefixPart}/${suffixPart}/%,${numberColumn}.like.${prefixPart}/20${suffixPart}/%`);
        
    let maxVal = 0;
    if (records) {
        records.forEach(r => {
            const val = r[numberColumn];
            if (!val) return;
            const p = val.split('/');
            const numVal = parseInt(p[p.length - 1]);
            if (!isNaN(numVal) && numVal > maxVal) {
                maxVal = numVal;
            }
        });
    }
    
    const nextNum = maxVal + 1;
    const newNumber = `${prefixPart}/${suffixPart}/${String(nextNum).padStart(3, '0')}`;
    
    console.log(`[Unique Number Generator] Duplicate found for ${currentNumber} in ${tableName}. Assigned new number: ${newNumber}`);
    if (typeof showToast === 'function') {
        showToast(`Duplicate number detected. Auto-assigned: ${newNumber}`, 'warning');
    }
    return newNumber;
};

function getNextSalesOrderNumber() {
    const list = db.salesOrders || [];
    if (list.length === 0) return 1;
    const numbers = list.map(so => {
        const num = so.number;
        if (!num) return 0;
        const parts = num.split('/');
        if (parts.length < 3) return 0;
        const val = parseInt(parts[parts.length - 1]);
        return isNaN(val) ? 0 : val;
    });
    let next = 1;
    while (numbers.includes(next)) {
        next++;
    }
    return next;
}

window.getNextSalesInvoiceNumber = function() {
    const list = (db.invoices || []).concat((rawDB.genericTransactions || []).filter(x => x.type === 'invoice'));
    if (!list || list.length === 0) return 1;
    let max = 0;
    list.forEach(inv => {
        if (!inv) return;
        const num = inv.number || inv.invoiceNo;
        if (!num) return;
        
        const val = window.parseVoucherSeqNumber ? window.parseVoucherSeqNumber(num) : 0;
        if (!isNaN(val) && val > max) {
            max = val;
        }
    });
    return max + 1;
};

window.getSalesInvoiceNumber = function() {
    const nextNum = window.getNextSalesInvoiceNumber();
    const cleanFY = currentFinancialYear || '2026-27';
    const fySuffix = (financialYears[cleanFY] || {}).suffix || '/26-27';
    const cleanSuffix = fySuffix.startsWith('/') ? fySuffix.substring(1) : fySuffix;
    const rawVal = `INV/${cleanSuffix}/${String(nextNum).padStart(3, '0')}`;
    return window.formatStandardDocNumber ? window.formatStandardDocNumber(rawVal) : rawVal;
};

window.changeFinancialYear = function(fy) {
    if (!financialYears[fy]) return;
    currentFinancialYear = fy;
    
    // Sync the topbar select dropdown just in case
    const topSelect = document.getElementById('topbar-fy-select');
    if (topSelect && topSelect.value !== fy) {
        topSelect.value = fy;
    }
    
    applyFinancialYearFilters();
    renderAllTables();
    showToast(`Switched to Financial Year ${fy}`, 'info');
};

function recalculateGRNIssuedMeters() {
    (rawDB.grns || []).forEach(g => {
        g.issuedMeters = 0;
    });
    (rawDB.outwards || []).forEach(o => {
        if (o.status === 'Cancelled') return;
        
        // Skip calculations if the outward voucher is embroidered
        const oNum = String(o.number || o.outwardNo || '').toUpperCase();
        if (oNum.startsWith('FI/C/EM') || oNum.startsWith('FI/V/EM') || oNum.startsWith('GRN/C/EM') || oNum.startsWith('GRN/V/EM')) return;
        
        const oState = parseOutwardWizardState(o);
        if (oState && oState.subType === 'embroidered') return;

        if (o.grnLinks && Array.isArray(o.grnLinks)) {
            o.grnLinks.forEach(link => {
                if (link.grnRefId) {
                    const grn = rawDB.grns.find(g => g.id === link.grnRefId);
                    if (grn) {
                        grn.issuedMeters = (grn.issuedMeters || 0) + (parseFloat(link.qty) || 0);
                    }
                }
            });
        } else if (o.grnRefId) {
            const grn = rawDB.grns.find(g => g.id === o.grnRefId);
            if (grn) {
                grn.issuedMeters = (grn.issuedMeters || 0) + (parseFloat(o.qty) || 0);
            }
        }
    });
}

function getRecordPermissionModule(rec) {
    if (!rec) return '';
    const number = String(rec.number || rec.grnNo || rec.outwardNo || rec.requisitionNo || rec.planNo || rec.purchaseNo || rec.soNumber || '').toUpperCase();
    
    // 1. Requisition Slip (Check first to avoid overlaps with /CON/, /INH/, etc. suffixes)
    if (number.includes('/REQ/') || number.startsWith('REQ/') || rec.requisitionNo !== undefined) {
        return 'requisition';
    }
    
    // 2. Sales Order
    if (number.includes('/SO/') || number.startsWith('SO/') || rec.partyOrderNo !== undefined) {
        return 'so';
    }
    // 3. Purchase Order
    if (number.includes('/PO/') || number.includes('/VEN/') || number.includes('/INH/') || number.includes('/CON/') || number.includes('/OTH/') || rec.poType !== undefined) {
        const poType = rec.poType || (number.includes('/VEN/') ? 'vendor' : number.includes('/INH/') ? 'inhouse' : number.includes('/CON/') ? 'consumable' : number.includes('/OTH/') ? 'other' : 'vendor');
        return 'po_' + poType;
    }
    // 4. GRN
    if (number.includes('/GRN/') || number.startsWith('GRN/') || rec.grnNo !== undefined) {
        return typeof window.getGrnPermissionModule === 'function' ? window.getGrnPermissionModule(rec) : 'grn_cust_plain';
    }
    // 5. Outward / Challan
    if (number.includes('/CH/') || number.includes('/OUT/') || number.startsWith('OUT/') || rec.outwardNo !== undefined || rec.dispatchedPackages !== undefined) {
        return 'outward';
    }
    // 6. Production Plan
    if (number.includes('/PLAN/') || rec.planDate !== undefined) {
        return 'prod_plan';
    }
    // 7. Purchase GR
    if (number.includes('/PUR/') || number.startsWith('PUR/') || rec.purchaseNo !== undefined) {
        return 'purchases';
    }
    // 8. Production Log / Slip
    if (rec.machineId !== undefined || rec.operator !== undefined || rec.stitchCount !== undefined) {
        return 'prod';
    }
    
    return '';
}

window.isRecordVisibleToCurrentUser = function(rec) {
    if (!currentUser) return true;
    if (currentUser.isSuperAdmin) return true;

    // First check granular read permission for the module type
    const module = getRecordPermissionModule(rec);
    if (module && !checkPermission(module, 'read')) {
        return false;
    }

    return true;
};

function applyFinancialYearFilters() {
    if (rawDB.grns) {
        rawDB.grns.forEach(g => {
            let customerName = g.customerName || g.customer_name || '';
            let customerId = g.customerId || g.customer_id || '';
            if (customerId && db.customers) {
                const c = db.customers.find(x => x.id === customerId);
                if (c && !customerName) customerName = c.name;
            }

            let vendorName = g.vendorName || g.vendor_name || '';
            let vendorId = g.vendorId || g.vendor_id || '';
            if (vendorId && db.vendors) {
                const v = db.vendors.find(x => x.id === vendorId);
                if (v && !vendorName) vendorName = v.name;
            }

            const poIdVal = g.poRefId || g.linked_po_id || g.poRef || g.po_ref || '';
            let poObj = null;
            if (poIdVal && rawDB.pos) {
                poObj = rawDB.pos.find(p => p.id === poIdVal || p.number === poIdVal);
            }
            if (!poObj && rawDB.pos) {
                const poNumVal = g.poNumber || g.linked_po_number || '';
                if (poNumVal) {
                    poObj = rawDB.pos.find(p => p.number === poNumVal);
                }
            }
            if (!poObj && rawDB.pos) {
                const state = parseGrnWizardState(g);
                if (state.source !== 'customer') {
                    let linkedSoIds = [];
                    let linkedSoNums = [];
                    if (g.soRefId) linkedSoIds.push(g.soRefId);
                    if (g.soNumber) linkedSoNums.push(g.soNumber);
                    if (g.linked_so_number) linkedSoNums.push(g.linked_so_number);
                    if (g.soLinks && g.soLinks.length > 0) {
                        g.soLinks.forEach(link => {
                            if (typeof link === 'string') {
                                if (link.startsWith('manual:')) {
                                    linkedSoNums.push(link.substring(7));
                                } else {
                                    linkedSoIds.push(link);
                                }
                            }
                        });
                    }
                    const linkedPOs = rawDB.pos.filter(po => {
                        return (po.linkedSoId && linkedSoIds.includes(po.linkedSoId)) ||
                               (po.soNumber && linkedSoNums.includes(po.soNumber)) ||
                               (po.linkedSoId && (rawDB.salesOrders || []).some(s => s.number && linkedSoNums.includes(s.number) && s.id === po.linkedSoId));
                    });
                    if (linkedPOs.length > 0) {
                        poObj = linkedPOs.find(p => p.poType === 'vendor' || p.po_type === 'vendor') || linkedPOs[0];
                    }
                }
            }
             if (poObj) {
                if (!customerId) {
                    customerId = poObj.customerId || poObj.customer || '';
                }
                if (db.customers) {
                    const c = db.customers.find(x => x.id === customerId || x.name === customerId || (poObj.customerName && x.name === poObj.customerName));
                    if (c) customerName = c.name;
                }
                if (!customerName) {
                    customerName = poObj.customerName || (poObj.customer && !poObj.customer.includes('imported_') ? poObj.customer : '');
                }

                if (!vendorId) {
                    vendorId = poObj.vendorId || poObj.vendor || '';
                }
                if (db.vendors) {
                    const v = db.vendors.find(x => x.id === vendorId || x.name === vendorId || (poObj.vendorName && x.name === poObj.vendorName));
                    if (v) vendorName = v.name;
                }
                if (!vendorName) {
                    vendorName = poObj.vendorName || (poObj.vendor && !poObj.vendor.includes('imported_') ? poObj.vendor : '');
                }
            }

            if (g.vendor_id === 'inhouse' || (poObj && poObj.poType === 'inhouse')) {
                vendorName = 'In House';
            }

            const state = parseGrnWizardState(g);
            if (state && state.source === 'customer') {
                vendorId = '';
                vendorName = '';
            }

            if (customerId) g.customerId = customerId;
            if (customerName) g.customerName = customerName;
            if (vendorId) g.vendorId = vendorId;
            if (vendorName) g.vendorName = vendorName;
        });
    }

    recalculateGRNIssuedMeters();

    const sortBySeqNumber = (arr, key = 'number', desc = true) => {
        return arr.sort((a, b) => {
            const valA = String(a[key] || a.number || '');
            const valB = String(b[key] || b.number || '');
            const numA = window.parseVoucherSeqNumber ? window.parseVoucherSeqNumber(valA) : 0;
            const numB = window.parseVoucherSeqNumber ? window.parseVoucherSeqNumber(valB) : 0;
            if (numA !== numB) return desc ? (numB - numA) : (numA - numB);
            const dateA = a.date ? new Date(a.date).getTime() : 0;
            const dateB = b.date ? new Date(b.date).getTime() : 0;
            return desc ? (dateB - dateA) : (dateA - dateB);
        });
    };

    db.grns = sortBySeqNumber(rawDB.grns.filter(g => isDateInCurrentFY(g.date, g.number) && window.isRecordVisibleToCurrentUser(g)), 'number');
    db.pos = sortBySeqNumber(rawDB.pos.filter(po => isDateInCurrentFY(po.date, po.number) && window.isRecordVisibleToCurrentUser(po)), 'number');
    db.productionLogs = rawDB.productionLogs.filter(p => isDateInCurrentFY(p.date, p.number) && window.isRecordVisibleToCurrentUser(p)); // Logs don't have standard sequential number keys
    db.purchases = rawDB.purchases.filter(p => isDateInCurrentFY(p.date, p.number) && window.isRecordVisibleToCurrentUser(p));
    db.salesOrders = sortBySeqNumber(rawDB.salesOrders.filter(so => isDateInCurrentFY(so.date, so.number) && window.isRecordVisibleToCurrentUser(so)), 'number');
    db.outwards = sortBySeqNumber(rawDB.outwards.filter(o => isDateInCurrentFY(o.date, o.number) && window.isRecordVisibleToCurrentUser(o)), 'number');
    db.productionSlips = sortBySeqNumber(rawDB.productionSlips.filter(p => isDateInCurrentFY(p.date, p.number) && window.isRecordVisibleToCurrentUser(p)), 'number');
    db.requisitionSlips = sortBySeqNumber(rawDB.requisitionSlips.filter(r => isDateInCurrentFY(r.date, r.number) && window.isRecordVisibleToCurrentUser(r)), 'number');
    db.productionPlans = sortBySeqNumber((rawDB.productionPlans || []).filter(p => isDateInCurrentFY(p.planDate || p.date, p.number) && window.isRecordVisibleToCurrentUser(p)), 'number');
    
    const filteredGeneric = rawDB.genericTransactions.filter(gtx => isDateInCurrentFY(gtx.date, gtx.number) && window.isRecordVisibleToCurrentUser(gtx));
    db.genericTransactions = sortBySeqNumber(filteredGeneric, 'number');
    db.invoices = sortBySeqNumber(filteredGeneric.filter(x => x.type === 'invoice'), 'number');
    db.vouchers = sortBySeqNumber(filteredGeneric.filter(x => x.type === 'voucher'), 'number');
    db.salesReturns = sortBySeqNumber(filteredGeneric.filter(x => x.type === 'salesreturn'), 'number');
    db.purchaseReturns = sortBySeqNumber(filteredGeneric.filter(x => x.type === 'purchasereturn'), 'number');
    db.receipts = sortBySeqNumber(filteredGeneric.filter(x => x.type === 'receipt'), 'number');
    db.payments = sortBySeqNumber(filteredGeneric.filter(x => x.type === 'payment'), 'number');
    db.journals = sortBySeqNumber(filteredGeneric.filter(x => x.type === 'journal'), 'number');
    db.contras = sortBySeqNumber(filteredGeneric.filter(x => x.type === 'contra'), 'number');
    
    // Auto-refresh all views and dashboard stats
    if (typeof renderAllTables === 'function') renderAllTables();
    if (typeof renderDashboard === 'function') renderDashboard();
}

