// ===== MASTER DB FUNCTIONS =====
async function loadMasterDB() {
    // First, perform data migration: if old embroideryflow_db exists and co1 key doesn't,
    // migrate the old data to co1.
    try {
        const oldData = localStorage.getItem(OLD_DB_KEY);
        if (oldData && !localStorage.getItem(COMPANY_DB_PREFIX + 'co1')) {
            // Migrate: strip users/userLogs from old data, save to co1
            try {
                const parsed = JSON.parse(oldData);
                const companyData = {
                    customers: parsed.customers || defaultDB.customers,
                    vendors: parsed.vendors || defaultDB.vendors,
                    transporters: parsed.transporters || defaultDB.transporters,
                    designs: parsed.designs || defaultDB.designs,
                    grns: parsed.grns || [],
                    pos: parsed.pos || [],
                    productionLogs: parsed.productionLogs || [],
                    items: parsed.items || [],
                    purchases: parsed.purchases || [],
                    salesOrders: parsed.salesOrders || defaultDB.salesOrders,
                    units: parsed.units || defaultDB.units
                };
                localStorage.setItem(COMPANY_DB_PREFIX + 'co1', JSON.stringify(companyData));
            } catch(e) {}
        }
    } catch(e) {}

    try {
        const saved = localStorage.getItem(MASTER_KEY);
        if (saved) {
            const parsed = JSON.parse(saved);
            masterDB = {
                companies: (parsed && Array.isArray(parsed.companies)) ? parsed.companies : defaultMasterDB.companies,
                users: (parsed && Array.isArray(parsed.users)) ? parsed.users : defaultMasterDB.users,
                userLogs: (parsed && Array.isArray(parsed.userLogs)) ? parsed.userLogs : [],
                departments: (parsed && Array.isArray(parsed.departments)) ? parsed.departments : [],
                dashboardLayouts: (parsed && parsed.dashboardLayouts) ? parsed.dashboardLayouts : null
            };
        } else {
            masterDB = JSON.parse(JSON.stringify(defaultMasterDB));
            masterDB.departments = [];
            masterDB.dashboardLayouts = null;
        }
    } catch(e) {
        masterDB = JSON.parse(JSON.stringify(defaultMasterDB));
        masterDB.departments = [];
        masterDB.dashboardLayouts = null;
    }

    window.isSupabaseOffline = false;
    // Load users from Supabase globally if available
    if (window.supabase) {
        try {
            const fetchPromise = window.supabase.from('users').select('*');
            const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), 10000));
            const { data, error } = await Promise.race([fetchPromise, timeoutPromise]);
            if (error) {
                console.error("Failed to load users from Supabase:", error.message);
                window.isSupabaseOffline = true;
            } else if (data && data.length > 0) {
                masterDB.users = data.map(u => {
                    const companyAccess = u.company_access || {};
                    return {
                        id: u.id,
                        username: u.username,
                        password: u.password,
                        displayName: u.display_name || '',
                        email: u.email || '',
                        phone: u.phone || '',
                        role: u.role,
                        isSuperAdmin: u.is_super_admin || false,
                        companyAccess: companyAccess,
                        department: companyAccess.__department || '',
                        reportingManager: companyAccess.__reportingManager || '',
                        rules: companyAccess.__rules || ''
                    };
                });

                const systemUser = masterDB.users.find(u => u.username === '__system_company_settings__');
                if (systemUser && systemUser.companyAccess) {
                    masterDB.departments = systemUser.companyAccess.__departments || [];
                    const sysLayouts = systemUser.companyAccess.__dashboardLayouts || {};
                    masterDB.dashboardLayouts = Object.assign({}, sysLayouts, masterDB.dashboardLayouts || {});
                    if (systemUser.companyAccess.companies) {
                        systemUser.companyAccess.companies.forEach(co => {
                            let localCo = masterDB.companies.find(c => c.id === co.id);
                            if (!localCo) {
                                localCo = { id: co.id, name: co.name, code: co.code, color: co.color, active: true };
                                masterDB.companies.push(localCo);
                            }
                            localCo.address = co.address || '';
                            localCo.logo = co.logo || '';
                            localCo.gst = co.gst || '';
                            localCo.phone = co.phone || '';
                            localCo.email = co.email || '';
                            localCo.name = co.name || localCo.name;
                            localCo.code = co.code || localCo.code;
                            localCo.color = co.color || localCo.color;
                            localCo.enabledMasters = co.enabledMasters || null;
                            localCo.enabledTransactions = co.enabledTransactions || null;
                        });
                    }
                }
            }
        } catch(e) {
            console.error("Supabase user load exception:", e);
            window.isSupabaseOffline = true;
        }

        if (!window.isSupabaseOffline) {
            // Load company settings from Supabase company_detail table globally if available
            try {
                const fetchPromise = window.supabase.from('company_detail').select('*');
                const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), 10000));
                const { data: coSettings, error: coErr } = await Promise.race([fetchPromise, timeoutPromise]);
                if (!coErr && coSettings && coSettings.length > 0) {
                    coSettings.forEach(settingsRec => {
                        const localCo = masterDB.companies.find(c => c.id === settingsRec.company_id);
                        if (localCo) {
                            localCo.address = settingsRec.address || '';
                            localCo.logo = settingsRec.email || '';
                            localCo.gst = settingsRec.gst || '';
                            localCo.name = settingsRec.name || localCo.name;
                            localCo.code = settingsRec.code || localCo.code;
                            localCo.color = settingsRec.mobile || localCo.color;
                            localCo.pincode = settingsRec.designation || '';
                        }
                    });
                }
            } catch(e) {
                console.error("Failed to load company detail from company_detail:", e);
            }
        }
    }

    // Ensure default admin user is always present in masterDB.users
    if (!masterDB.users.find(u => u.username === 'admin')) {
        masterDB.users.unshift(JSON.parse(JSON.stringify(defaultMasterDB.users[0])));
    }

    // Ensure admin companyAccess is complete and missing companies are merged
    defaultMasterDB.companies.forEach(defaultCo => {
        if (!masterDB.companies.find(c => c.id === defaultCo.id)) {
            masterDB.companies.push(defaultCo);
        }
    });

    masterDB.users.forEach(u => {
        if (!u.companyAccess) u.companyAccess = {};
        if (u.isSuperAdmin) {
            masterDB.companies.forEach(co => {
                if (!u.companyAccess[co.id]) {
                    u.companyAccess[co.id] = { enabled: true, isAdmin: true, permissions: Object.assign({}, ALL_PERMS) };
                }
            });
        }
    });
    try {
        localStorage.setItem(MASTER_KEY, JSON.stringify(masterDB));
    } catch(e) {
        console.error("Failed to save masterDB to localStorage in loadMasterDB", e);
    }
}

async function saveMasterDB(syncUsersToSupabase = false) {
    let adminUser = masterDB.users.find(u => u.username === 'admin');
    if (!adminUser) {
        adminUser = JSON.parse(JSON.stringify(defaultMasterDB.users[0]));
        masterDB.users.unshift(adminUser);
    }
    let systemUser = masterDB.users.find(u => u.username === '__system_company_settings__');
    if (!systemUser) {
        systemUser = {
            id: 'system_co_settings',
            username: '__system_company_settings__',
            password: 'system_no_login_possible_random_12345',
            role: 'System',
            isSuperAdmin: false,
            companyAccess: {}
        };
        masterDB.users.push(systemUser);
    }
    systemUser.companyAccess = {
        companies: masterDB.companies,
        __departments: masterDB.departments || [],
        __dashboardLayouts: masterDB.dashboardLayouts || {}
    };

    try {
        localStorage.setItem(MASTER_KEY, JSON.stringify(masterDB));
    } catch (e) {
        if (e.name === 'QuotaExceededError' || e.code === 22 || e.message.includes('quota')) {
            console.warn("localStorage quota exceeded. Truncating user logs to free up space...");
            if (masterDB.userLogs && masterDB.userLogs.length > 500) {
                masterDB.userLogs = masterDB.userLogs.slice(0, 500);
                try {
                    localStorage.setItem(MASTER_KEY, JSON.stringify(masterDB));
                    console.log("Successfully saved masterDB after truncating user logs.");
                } catch (retryErr) {
                    console.error("Failed to save masterDB even after truncating logs:", retryErr);
                }
            } else {
                console.error("localStorage quota exceeded and userLogs are already small:", e);
            }
        } else {
            console.error("Failed to save to localStorage:", e);
        }
    }

    if (syncUsersToSupabase && window.supabase) {
        try {
            // Upsert all current users to Supabase users table
            for (const u of masterDB.users) {
                const dbRecord = {
                    id: u.id,
                    username: u.username,
                    password: u.password,
                    role: u.role,
                    display_name: u.displayName || u.display_name || '',
                    email: u.email || '',
                    phone: u.phone || '',
                    is_super_admin: u.isSuperAdmin || false,
                    company_access: u.companyAccess || {}
                };
                const { error: upsertErr } = await window.supabase.from('users').upsert(dbRecord);
                if (upsertErr) {
                    console.error(`Failed to upsert user ${u.username}:`, upsertErr);
                    if (typeof showToast === 'function') {
                        showToast(`Failed to sync user ${u.username} to database: ${upsertErr.message}`, 'error');
                    }
                }
            }
        } catch(e) {
            console.error("Failed to sync users list to Supabase:", e);
        }
    }
}

function getBaseNumberFromGrn(numberStr, currentPrefix) {
    if (!numberStr) return null;
    const parts = String(numberStr).split('/').map(p => p.trim());
    // Traverse backwards to find the first purely numeric segment (ignores year part like '26-27')
    for (let i = parts.length - 1; i >= 0; i--) {
        const p = parts[i];
        if (/^\d+$/.test(p)) {
            return parseInt(p, 10);
        }
    }
    // Fallback digit matches if structure is legacy or non-standard
    const matchDigits = numberStr.match(/\d+$/);
    if (matchDigits) return parseInt(matchDigits[0], 10);
    return null;
}

function getBaseNumberFromOutward(numberStr, currentPrefix) {
    if (!numberStr) return null;
    const parts = String(numberStr).split('/').map(p => p.trim());
    // Traverse backwards to find the first purely numeric segment (ignores year part like '26-27')
    for (let i = parts.length - 1; i >= 0; i--) {
        const p = parts[i];
        if (/^\d+$/.test(p)) {
            return parseInt(p, 10);
        }
    }
    // Fallback digit matches if structure is legacy or non-standard
    const matchDigits = numberStr.match(/\d+$/);
    if (matchDigits) return parseInt(matchDigits[0], 10);
    return null;
}

async function migrateDatabaseSeries() {
    if (!currentCompany) return;
    let grnsUpdated = false;
    let outwardsUpdated = false;
    let sosUpdated = false;
    let posUpdated = false;
    let prodsUpdated = false;
    let plansUpdated = false;
    let reqsUpdated = false;
    let gtxsUpdated = false;

    // Helper for SO/PO parsing
    function getBaseNumberFromSoPo(numberStr) {
        if (!numberStr) return null;
        const parts = String(numberStr).split('/').map(p => p.trim());
        for (let i = parts.length - 1; i >= 0; i--) {
            if (/^\d+$/.test(parts[i])) return parseInt(parts[i], 10);
        }
        let newMatch = numberStr.match(/(?:SO|PO)\/?(?:VEN|INH|CON|OTH|FJW)?\/(?:\d{4}-\d{2}|\d{2}-\d{2})\/(\d+)/i);
        if (newMatch) return parseInt(newMatch[1], 10);
        let matchDigits = numberStr.match(/\d+$/);
        if (matchDigits) return parseInt(matchDigits[0], 10);
        return null;
    }

    // Helper for other prefixes
    function getBaseNumberFromOthers(numberStr, currentPrefix) {
        if (!numberStr) return null;
        const parts = String(numberStr).split('/').map(p => p.trim());
        for (let i = parts.length - 1; i >= 0; i--) {
            if (/^\d+$/.test(parts[i])) return parseInt(parts[i], 10);
        }
        const escapedPrefix = currentPrefix.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
        const newRegex = new RegExp(`^${escapedPrefix}/(?:\\d{4}-\\d{2}|\\d{2}-\\d{2})/(\\d+)`, 'i');
        const newMatch = numberStr.match(newRegex);
        if (newMatch) return parseInt(newMatch[1], 10);
        
        let matchDigits = numberStr.match(/\d+$/);
        if (matchDigits) return parseInt(matchDigits[0], 10);
        return null;
    }

    // Helper to sort by current base sequence parsed from the document number
    function sortByCurrentNumber(arr, parseFn, prefix) {
        return [...arr].sort((a, b) => {
            const valA = a.number || a.grnNo || '';
            const valB = b.number || b.grnNo || '';
            const numA = parseFn(valA, prefix) || 0;
            const numB = parseFn(valB, prefix) || 0;
            if (numA !== numB) return numA - numB;
            const timeA = a.entryTimestamp || a.id || '';
            const timeB = b.entryTimestamp || b.id || '';
            return String(timeA).localeCompare(String(timeB));
        });
    }

    // 1. Migrate Sales Orders & Cascade to POs/GRNs
    if (rawDB.salesOrders) {
        const sorted = sortByCurrentNumber(rawDB.salesOrders, getBaseNumberFromSoPo, 'SO');
        let count = 1;
        for (const so of sorted) {
            const correctNo = getDocumentNumber('SO', count++);
            if (so.number !== correctNo) {
                const oldNo = so.number;
                so.number = correctNo;
                await saveToSupabase('sales_orders', so);
                sosUpdated = true;

                // Update POs referencing this SO number
                if (rawDB.pos) {
                    for (const po of rawDB.pos) {
                        let poChanged = false;
                        if (po.linkedSoNumber === oldNo) {
                            po.linkedSoNumber = correctNo;
                            poChanged = true;
                        }
                        if (po.soRef === oldNo) {
                            po.soRef = correctNo;
                            poChanged = true;
                        }
                        if (poChanged) {
                            await saveToSupabase('purchase_orders', po);
                        }
                    }
                }

                // Update GRNs referencing this SO number
                if (rawDB.grns) {
                    for (const g of rawDB.grns) {
                        let grnChanged = false;
                        if (g.linked_so_number === oldNo) {
                            g.linked_so_number = correctNo;
                            grnChanged = true;
                        }
                        if (g.soRefId === oldNo) {
                            g.soRefId = correctNo;
                            grnChanged = true;
                        }
                        if (g.soRef === oldNo) {
                            g.soRef = correctNo;
                            grnChanged = true;
                        }
                        if (g.soLinks && g.soLinks.includes(oldNo)) {
                            g.soLinks = g.soLinks.map(id => id === oldNo ? correctNo : id);
                            grnChanged = true;
                        }
                        if (grnChanged) {
                            await saveToSupabase('grns', g);
                        }
                    }
                }
            }
        }
    }

    // 2. Migrate Purchase Orders & Cascade to GRNs
    if (rawDB.pos) {
        const sorted = sortByCurrentNumber(rawDB.pos, getBaseNumberFromSoPo, 'PO');
        const poCounters = {};
        for (const po of sorted) {
            const poType = po.poType || 'vendor';
            const prefix = poType === 'inhouse' ? 'PO/INH' : poType === 'consumable' ? 'PO/CON' : poType === 'other' ? 'PO/OTH' : 'PO/VEN';
            if (!poCounters[prefix]) poCounters[prefix] = 1;
            const correctNo = getDocumentNumber(prefix, poCounters[prefix]++);
            
            if (po.number !== correctNo) {
                const oldNo = po.number;
                po.number = correctNo;
                await saveToSupabase('purchase_orders', po);
                posUpdated = true;

                // Update GRNs referencing this PO number
                if (rawDB.grns) {
                    for (const g of rawDB.grns) {
                        let grnChanged = false;
                        if (g.linked_po_number === oldNo) {
                            g.linked_po_number = correctNo;
                            grnChanged = true;
                        }
                        if (g.soRefId === oldNo) {
                            g.soRefId = correctNo;
                            grnChanged = true;
                        }
                        if (grnChanged) {
                            await saveToSupabase('grns', g);
                        }
                    }
                }
            }
        }
    }

    // 3. Migrate GRNs & Cascade to Outwards
    if (rawDB.grns) {
        const sorted = sortByCurrentNumber(rawDB.grns, getBaseNumberFromGrn, 'GRN');
        const grnCounters = {};
        for (const g of sorted) {
            const state = parseGrnWizardState(g);
            let prefix = 'GRN';
            if (state.type === 'fabric') {
                if (state.source === 'customer') {
                    prefix = state.subType === 'plain' ? 'GRN/C/PF' : 'GRN/C/EM';
                } else {
                    prefix = state.subType === 'plain' ? 'GRN/V/PF' : 'GRN/V/EM';
                }
            } else if (state.type === 'consumable') {
                prefix = 'GRN/CON';
            } else if (state.type === 'other') {
                prefix = 'GRN/OTH';
            }

            if (!grnCounters[prefix]) grnCounters[prefix] = 1;
            const correctNo = getDocumentNumber(prefix, grnCounters[prefix]++);
            
            if (g.grnNo !== correctNo || g.number !== correctNo) {
                const oldNo = g.grnNo || g.number;
                g.grnNo = correctNo;
                g.number = correctNo;
                await saveToSupabase('grns', g);
                grnsUpdated = true;

                // Update Outwards referencing this GRN number
                if (rawDB.outwards) {
                    for (const o of rawDB.outwards) {
                        if (o.grnNo === oldNo) {
                            o.grnNo = correctNo;
                            await saveToSupabase('outwards', o);
                            outwardsUpdated = true;
                        }
                    }
                }
            }
        }
    }

    // 4. Migrate Outwards
    if (rawDB.outwards) {
        const sorted = sortByCurrentNumber(rawDB.outwards, getBaseNumberFromOutward, 'JW');
        const outCounters = {};
        for (const o of sorted) {
            const state = parseOutwardWizardState(o);
            let prefix = 'JW';
            if (state.type === 'fabric_issue_challan') {
                if (state.source === 'customer') {
                    prefix = state.subType === 'plain' ? 'FI/C/PF' : 'FI/C/EM';
                } else {
                    prefix = state.subType === 'plain' ? 'FI/V/PF' : 'FI/V/EM';
                }
            } else if (state.type === 'inhouse') {
                prefix = 'FI/INH';
            } else if (state.type === 'jobworker') {
                prefix = 'FI/JW';
            }

            if (!outCounters[prefix]) outCounters[prefix] = 1;
            const correctNo = getDocumentNumber(prefix, outCounters[prefix]++);

            if (o.number !== correctNo) {
                o.number = correctNo;
                await saveToSupabase('outwards', o);
                outwardsUpdated = true;
            }
        }
    }

    // 5. Migrate Production Slips
    if (rawDB.productionSlips) {
        const sorted = sortByCurrentNumber(rawDB.productionSlips, (num, pref) => getBaseNumberFromOthers(num, pref), 'PRD');
        let count = 1;
        for (const slip of sorted) {
            const correctNo = getDocumentNumber('PRD', count++);
            if (slip.number !== correctNo) {
                slip.number = correctNo;
                await saveToSupabase('production_slips', slip);
                prodsUpdated = true;
            }
        }
    }

    // 6. Migrate Production Plans
    if (rawDB.productionPlans) {
        const sorted = sortByCurrentNumber(rawDB.productionPlans, (num, pref) => getBaseNumberFromOthers(num, pref), 'PP');
        let count = 1;
        for (const plan of sorted) {
            const correctNo = getDocumentNumber('PP', count++);
            if (plan.number !== correctNo) {
                plan.number = correctNo;
                await saveToSupabase('production_plans', plan);
                plansUpdated = true;
            }
        }
    }

    // 7. Migrate Requisitions
    if (rawDB.requisitionSlips) {
        const sorted = sortByCurrentNumber(rawDB.requisitionSlips, (num, pref) => getBaseNumberFromOthers(num, pref), 'REQ');
        let count = 1;
        for (const req of sorted) {
            const correctNo = getDocumentNumber('REQ', count++);
            if (req.number !== correctNo) {
                req.number = correctNo;
                await saveToSupabase('requisition_slips', req);
                reqsUpdated = true;
            }
        }
    }

    // 8. Migrate Generic Transactions (Billing / Accounts)
    if (rawDB.genericTransactions) {
        const sorted = sortByCurrentNumber(rawDB.genericTransactions, (num, pref) => getBaseNumberFromOthers(num, pref), 'INV');
        const gtxCounters = {};
        for (const gtx of sorted) {
            const type = gtx.type || 'invoice';
            const prefix = type === 'invoice' ? 'INV' : type === 'voucher' ? 'VOUCH' : type === 'salesreturn' ? 'SR' : 'PR';
            if (!gtxCounters[prefix]) gtxCounters[prefix] = 1;
            const correctNo = getDocumentNumber(prefix, gtxCounters[prefix]++);
            
            if (gtx.number !== correctNo) {
                gtx.number = correctNo;
                await saveToSupabase('generic_transactions', gtx);
                gtxsUpdated = true;
            }
        }
    }

    // Auto-link synchronization: sync SO-to-GRN links back to GRNs
    try {
        let countSync = 0;
        for (const so of (rawDB.salesOrders || [])) {
            if (so.grnLinks && Array.isArray(so.grnLinks) && so.grnLinks.length > 0) {
                for (const grnRef of so.grnLinks) {
                    let grn = null;
                    if (typeof grnRef === 'string' && grnRef.startsWith('manual:')) {
                        const cleanNum = grnRef.substring(7).trim().toLowerCase();
                        grn = (rawDB.grns || []).find(g => (g.grnNo || g.number || '').trim().toLowerCase() === cleanNum);
                    } else {
                        grn = (rawDB.grns || []).find(g => g.id === grnRef);
                    }
                    if (grn) {
                        grn.soLinks = grn.soLinks || [];
                        const isLinked = grn.soLinks.includes(so.id) || (so.number && grn.soLinks.includes('manual:' + so.number));
                        if (!isLinked) {
                            grn.soLinks.push(so.id);
                            await saveToSupabase('grns', grn);
                            grnsUpdated = true;
                            countSync++;
                        }
                    }
                }
            }
        }
        if (countSync > 0) {
            console.log(`Auto-synchronized ${countSync} missing GRN-to-SO reverse links to database.`);
        }
    } catch (e) {
        console.error("Failed to run reverse link migration:", e);
    }

    if (grnsUpdated || outwardsUpdated || sosUpdated || posUpdated || prodsUpdated || plansUpdated || reqsUpdated || gtxsUpdated) {
        console.log("Database series successfully migrated!");
    }
}

function sortMachines() {
    db.machines = db.machines || [];
    db.machines.sort((a, b) => {
        const valA = String(a.machineNo || a.name || '');
        const valB = String(b.machineNo || b.name || '');
        return valA.localeCompare(valB, undefined, { numeric: true, sensitivity: 'base' });
    });
}


