            customerName: r.customer_name || r.customerName || '',
            destinationParty: r.destination_party || r.destinationParty || '',
            billingMode: r.billing_mode || r.billingMode || 'Per KM',
            ratePerKm: parseFloat(r.rate_per_km || r.ratePerKm || 0),
            fixedDistance: (r.fixed_distance || r.fixedDistance) === 'User Defined' ? 'User Defined' : (parseFloat(r.fixed_distance || r.fixedDistance || 0)),
            dailyFixedRate: parseFloat(r.daily_fixed_rate || r.dailyFixedRate || 0),
            minCharge: parseFloat(r.min_charge || r.minCharge || 0),
            vehicleType: r.vehicle_type || r.vehicleType || 'All / Standard',
            effectiveFrom: window.parseDateToISO(r.effective_from || r.effectiveFrom || ''),
            remarks: r.remarks || '',
            status: r.status || 'Active'
