function cleanRemarksForDatabaseSave(remarksVal) {
    if (!remarksVal) return '';
    let cleaned = remarksVal;
    let ramaTag = '';

    if (cleaned.includes('[RAMA_SYNCED:')) {
        const m = cleaned.match(/\[RAMA_SYNCED:[\s\S]*?\]/);
        if (m) ramaTag = m[0];
    }
    
    // 1. Remove __USER_LOG__: and everything after it
    const userLogPrefix = '__USER_LOG__:';
    const userLogIdx = cleaned.indexOf(userLogPrefix);
    if (userLogIdx !== -1) {
        cleaned = cleaned.substring(0, userLogIdx);
    }

    // 2. Remove other __METADATA__ prefixes from the remaining text (line by line)
    const lines = cleaned.split('\n');
    const filteredLines = lines.filter(line => {
        const trimmed = line.trim();
        if (/^__[A-Z0-9_]+__\s*:?/.test(trimmed)) return false;
        return !trimmed.startsWith('__SO_LINKS__:') &&
               !trimmed.startsWith('__REQ_METADATA__:') &&
               !trimmed.startsWith('__RECONCILED_VOUCHER_ID__:') &&
               !trimmed.startsWith('__RECONCILED_VOUCHER_NO__:') &&
               !trimmed.startsWith('__GRN_LINKS__:') &&
               !trimmed.startsWith('__MATERIAL_TYPE__:') &&
               !trimmed.startsWith('__ITEMS__:') &&
               !trimmed.startsWith('__CONVERTED_LOG__:') &&
               !trimmed.startsWith('__MACHINE_METADATA__:') &&
               !trimmed.startsWith('__PACKAGE_SLIPS__:') &&
               !trimmed.startsWith('__RECONCILED_SHIPMENTS__:') &&
               !trimmed.startsWith('__LINKED_ORDER_IDS__:') &&
               !trimmed.startsWith('__GTX_ITEMS__:') &&
               !trimmed.startsWith('__PERIOD_FROM__:') &&
               !trimmed.startsWith('__PERIOD_TO__:') &&
               !trimmed.startsWith('__IS_LOGISTICS__:') &&
               !trimmed.startsWith('__SLIP_METADATA__:') &&
               !trimmed.startsWith('__FJW_META__:') &&
               !trimmed.startsWith('__PO_ALLOTTED_QTYS__:') &&
               !trimmed.startsWith('__SO_ALLOTTED_QTYS__:') &&
               !trimmed.startsWith('__USER_LOG__:');
    });

    let res = filteredLines.join('\n').trim();
    if (ramaTag && !res.includes('[RAMA_SYNCED:')) {
        res = res ? (res + '\n' + ramaTag) : ramaTag;
    }
    return res;
}

async function saveToSupabase(table, data) {
    const targetCompId = (currentCompany && currentCompany.id) || (data && data.company_id) || 'co4';
    
    const mappedVoucherType = table === 'sales_orders' ? 'sales_order' :
                              table === 'purchase_orders' ? (data.type === 'inhouse' ? 'inhouse_po' : 'purchase_order') :
                              table === 'requisition_slips' ? (
                                  (data.type || 'Fabric') === 'Fabric' ? 'requisition_slip_fabric' :
                                  (data.type || 'Fabric') === 'Consumable' ? 'requisition_slip_consumable' :
                                  (data.type || 'Fabric') === 'FabricReturn' ? 'requisition_slip_fabric_return' :
                                  (data.type || 'Fabric') === 'ConsumableReturn' ? 'requisition_slip_consumable_return' : 'requisition_slip_fabric'
                              ) :
                              table === 'production_slips' ? (window.currentProductionMode === 'sampling' ? 'sampling_slip' : 'production_slip') :
                              table === 'outwards' ? 'job_work_issue' :
                              table === 'grns' ? 'job_work_receipt' :
                              table === 'generic_transactions' ? (
                                  data.type === 'invoice' ? 'sales_invoice' :
                                  data.type === 'voucher' ? 'purchase_invoice' :
                                  data.type === 'salesreturn' ? 'sales_return' :
                                  data.type === 'purchasereturn' ? 'purchase_return' :
                                  data.type === 'receipt' ? 'receipt_voucher' :
                                  data.type === 'payment' ? 'payment_voucher' :
                                  data.type === 'journal' ? 'journal_voucher' :
                                  data.type === 'contra' ? 'contra_voucher' : null
                              ) : null;

    if (mappedVoucherType && window.supabase) {
        const config = await window.getVoucherApprovalConfig(mappedVoucherType);
        if (config && config.approval_levels_required > 0) {
            if (!window.isUserInApprovalList(currentUser, config.level1_roles, targetCompId)) {
                showToast("You are not authorized as a Maker for this document type.", "error");
                throw new Error("User is not an authorized Maker");
            }
        }
    }

    // Check if voucher is fully approved and locked
    const isEdit = !!data.id;
    if (isEdit && mappedVoucherType && window.supabase) {
        try {
            const { data: appRec } = await window.supabase
                .from('voucher_approvals')
                .select('approval_status')
                .eq('company_id', targetCompId)
                .eq('voucher_type', mappedVoucherType)
                .eq('voucher_id', data.id)
                .maybeSingle();
            if (appRec && appRec.approval_status === 'approved') {
                const isSuper = currentUser && currentUser.isSuperAdmin;
                const access = currentUser && currentUser.companyAccess && currentUser.companyAccess[targetCompId];
                const isAdmin = isSuper || (access && access.isAdmin);
                if (!isAdmin) {
                    showToast("This voucher is fully approved and locked. Only administrators can modify approved vouchers.", "error");
                    throw new Error("Voucher is fully approved and locked");
                }
            }
        } catch(e) {
            if (e.message === "Voucher is fully approved and locked") {
                throw e;
            }
        }
    }
    // Global protection: Preserve RAMA_SYNCED tag and syncedToRama flag across ALL tables on edit
    if (data.id) {
        const localList = (db && db[table]) ? db[table] : ((rawDB && rawDB[table]) ? rawDB[table] : []);
        const existingRec = Array.isArray(localList) ? localList.find(r => r && String(r.id) === String(data.id)) : null;
        if (existingRec) {
            if (existingRec.remarks && existingRec.remarks.includes('[RAMA_SYNCED:')) {
                const matchSync = existingRec.remarks.match(/\[RAMA_SYNCED:[\s\S]*?\]/);
                if (matchSync && (!data.remarks || !data.remarks.includes('[RAMA_SYNCED:'))) {
                    data.remarks = data.remarks ? (data.remarks + '\n' + matchSync[0]) : matchSync[0];
                }
            }
            if (existingRec.syncedToRama === true && !data.syncedToRama) {
                data.syncedToRama = true;
            }
        }
    }

    if (['grns', 'requisition_slips', 'outwards', 'production_slips', 'production_plans', 'generic_transactions'].includes(table)) {
        const existing = getExistingUserLog(table, data.id, data.remarks);
        const newLog = generateNewUserLog(existing);
        data.remarks = cleanRemarksForDatabaseSave(data.remarks) + (cleanRemarksForDatabaseSave(data.remarks) ? '\n' : '') + '__USER_LOG__:' + JSON.stringify(newLog);
    }
    
    let record = { ...data, company_id: data.company_id || targetCompId };
    
    if (table === 'grns') {
        record.remarks = encodeMetadataToRemarks(record.remarks, '__SO_LINKS__', record.soLinks);
        record.remarks = encodeMetadataToRemarks(record.remarks, '__SO_ALLOTTED_QTYS__', record.soAllottedQtys || data.soAllottedQtys || {});
        record.remarks = encodeMetadataToRemarks(record.remarks, '__RECONCILED_VOUCHER_ID__', record.reconciledVoucherId);
        record.remarks = encodeMetadataToRemarks(record.remarks, '__RECONCILED_VOUCHER_NO__', record.reconciledVoucherNumber);
        record.remarks = encodeMetadataToRemarks(record.remarks, '__PACKAGE_SLIPS__', record.packageSlips || data.packageSlips || []);
        data.remarks = record.remarks;
    }
    if (table === 'outwards') {
        record.remarks = encodeMetadataToRemarks(record.remarks, '__RECONCILED_VOUCHER_ID__', record.reconciledVoucherId);
        record.remarks = encodeMetadataToRemarks(record.remarks, '__RECONCILED_VOUCHER_NO__', record.reconciledVoucherNumber);
        record.remarks = encodeMetadataToRemarks(record.remarks, '__PACKAGE_SLIPS__', record.packageSlips || data.packageSlips || []);
        const consumableMeta = {
            materialSourceType: record.materialSourceType || data.materialSourceType || 'customer',
            consumableItemId: record.consumableItemId || data.consumableItemId || '',
            consumableQty: record.consumableQty || data.consumableQty || 0
        };
        record.remarks = encodeMetadataToRemarks(record.remarks, '__CONSUMABLE_METADATA__', consumableMeta);
        data.remarks = record.remarks;
    }
    if (table === 'generic_transactions') {
        record.remarks = encodeMetadataToRemarks(record.remarks, '__RECONCILED_SHIPMENTS__', record.reconciledShipments);
        record.remarks = encodeMetadataToRemarks(record.remarks, '__LINKED_ORDER_IDS__', record.linkedOrderIds || data.linkedOrderIds || []);
        record.remarks = encodeMetadataToRemarks(record.remarks, '__GTX_ITEMS__', record.items || data.items || []);
        record.remarks = encodeMetadataToRemarks(record.remarks, '__PERIOD_FROM__', record.periodFrom || data.periodFrom);
        record.remarks = encodeMetadataToRemarks(record.remarks, '__PERIOD_TO__', record.periodTo || data.periodTo);
        record.remarks = encodeMetadataToRemarks(record.remarks, '__IS_LOGISTICS__', record.isLogistics !== undefined ? record.isLogistics : data.isLogistics);
        data.remarks = record.remarks;
        delete record.amount;
        delete record.qty;
        delete record.packageSlips;
        delete record.items;
        delete record.linkedOrderIds;
        delete record.periodFrom;
        delete record.periodTo;
        delete record.isLogistics;
    }
    if (table === 'purchases') {
        delete record.items;
        delete record.packageSlips;
        delete record.number;
    }
    if (table === 'requisition_slips') {
        const extraMeta = {
            type: record.type || '',
            machineId: record.machineId || '',
            machineNo: record.machineNo || '',
            inhousePoId: record.inhousePoId || '',
            inhousePoNumber: record.inhousePoNumber || '',
            linkedChallanIds: record.linkedChallanIds || []
        };
        record.remarks = encodeMetadataToRemarks(record.remarks, '__REQ_METADATA__', extraMeta);
        data.remarks = record.remarks;
    }
    if (table === 'production_slips') {
        const links = data.links || record.links || [];
        let metadataList = [];
        if (links && links.length > 0) {
            metadataList = links.map(lnk => ({
                machineId: lnk.machineId || data.machineId || record.machineId || '',
                machineNo: lnk.machineNo || data.machineNo || record.machineNo || '',
                poId: lnk.poId || '',
                poNumber: lnk.poNumber || '',
                than: lnk.than || 0,
                conversion: lnk.conversion || 0,
                embroideryMtr: lnk.embroideryMtr || 0,
                qty: lnk.qty || 0,
                fabricConsumption: lnk.fabricConsumption || 0,
                planId: lnk.planId || data.planId || record.planId || null,
                planItemId: lnk.planItemId || data.planItemId || record.planItemId || null,
                planNumber: lnk.planNumber || data.planNumber || record.planNumber || null,
                mendingPerMeter: lnk.mendingPerMeter !== undefined ? lnk.mendingPerMeter : (data.mendingPerMeter !== undefined ? data.mendingPerMeter : record.mendingPerMeter || 0),
                distributeInProd: lnk.distributeInProd !== undefined ? lnk.distributeInProd : (data.distributeInProd !== undefined ? data.distributeInProd : record.distributeInProd !== undefined ? record.distributeInProd : true),
                mendingCharges: lnk.mendingCharges !== undefined ? lnk.mendingCharges : (data.mendingCharges !== undefined ? data.mendingCharges : record.mendingCharges || 0),
                otherJwPerMeter: lnk.otherJwPerMeter !== undefined ? lnk.otherJwPerMeter : (data.otherJwPerMeter !== undefined ? data.otherJwPerMeter : record.otherJwPerMeter || 0),
                otherJwDistribute: lnk.otherJwDistribute !== undefined ? lnk.otherJwDistribute : (data.otherJwDistribute !== undefined ? data.otherJwDistribute : record.otherJwDistribute !== undefined ? record.otherJwDistribute : true),
                otherJwCharges: lnk.otherJwCharges !== undefined ? lnk.otherJwCharges : (data.otherJwCharges !== undefined ? data.otherJwCharges : record.otherJwCharges || 0)
            }));
        } else {
            metadataList = [{
                machineId: data.machineId || record.machineId || '',
                machineNo: data.machineNo || record.machineNo || '',
                poId: data.poId || record.poId || '',
                poNumber: data.poNumber || record.poNumber || '',
                than: data.than || record.than || 0,
                conversion: data.conversion || record.conversion || 0,
                embroideryMtr: data.embroideryMtr || record.embroideryMtr || 0,
                qty: data.qty || record.qty || 0,
                fabricConsumption: data.fabricConsumption || record.fabricConsumption || 0,
                planId: data.planId || record.planId || null,
                planItemId: data.planItemId || record.planItemId || null,
                planNumber: data.planNumber || record.planNumber || null,
                mendingPerMeter: data.mendingPerMeter !== undefined ? data.mendingPerMeter : (record.mendingPerMeter || 0),
                distributeInProd: data.distributeInProd !== undefined ? data.distributeInProd : (record.distributeInProd !== undefined ? record.distributeInProd : true),
                mendingCharges: data.mendingCharges !== undefined ? data.mendingCharges : (record.mendingCharges || 0),
                otherJwPerMeter: data.otherJwPerMeter !== undefined ? data.otherJwPerMeter : (record.otherJwPerMeter || 0),
                otherJwDistribute: data.otherJwDistribute !== undefined ? data.otherJwDistribute : (record.otherJwDistribute !== undefined ? record.otherJwDistribute : true),
                otherJwCharges: data.otherJwCharges !== undefined ? data.otherJwCharges : (record.otherJwCharges || 0)
            }];
        }
        record.remarks = encodeMetadataToRemarks(record.remarks, '__SLIP_METADATA__', metadataList);
        data.remarks = record.remarks;
    }
    
    if (table === 'sales_orders') {
        const soItems = record.items || [];
        const firstItem = soItems[0] || {};
        const computedTotal = record.totalValue || soItems.reduce((s, it) => s + (it.amount || 0), 0);
        const existing = getExistingUserLog('sales_orders', record.id, record.remarks);
        const newLog = generateNewUserLog(existing);
        let remarksWithMetadata = cleanRemarksForDatabaseSave(record.remarks) + '\n__USER_LOG__:' + JSON.stringify(newLog);
        remarksWithMetadata = encodeMetadataToRemarks(remarksWithMetadata, '__GRN_LINKS__', record.grnLinks);
        remarksWithMetadata = encodeMetadataToRemarks(remarksWithMetadata, '__MATERIAL_TYPE__', record.materialType || 'without_material');

        // Encode items in remarks as JSON backup (prefix __ITEMS__:)
        const itemsBackup = soItems.length > 0 ? '__ITEMS__:' + JSON.stringify(soItems) + (remarksWithMetadata ? '\n' + remarksWithMetadata : '') : (remarksWithMetadata || null);
        const computedTotalSanitized = Number(computedTotal) || 0;
        const baseRecord = {
            id: record.id,
            company_id: record.company_id,
            number: record.number,
            date: record.date,
            entry_timestamp: record.entryTimestamp || null,
            customer_id: record.customerId,
            customer_name: record.customerName,
            item_id: record.designId || firstItem.itemId || null,
            item_name: record.designNumber || null,
            item_group: record.designGroup || null,
            party_order_no: record.partyOrderNo || null,
            party_order_date: record.partyOrderDate || null,
            qty: Number(record.qty || firstItem.qty) || 0,
            rate: Number(record.rate || firstItem.price) || 0,
            amount: computedTotalSanitized,
            delivery_date: record.deliveryDate || null,
            delivery_days: record.deliveryDays || null,
            status: record.status || 'Pending',
            remarks: remarksWithMetadata || null
        };
        // Save using baseRecord with itemsBackup in remarks to prevent 400 Bad Request errors from missing columns
        const fallbackRecord = { ...baseRecord, remarks: itemsBackup };
        const { error: errBase } = await supabase.from('sales_orders').upsert(fallbackRecord);
        if (errBase) {
            console.error("Error saving sales_order:", errBase);
            throw errBase;
        }
        if (mappedVoucherType) {
            await window.updateVoucherApprovalOnSave(mappedVoucherType, data.id);
        }
        return; // handled above, skip the default upsert below
    } else if (table === 'purchase_orders') {
        const existing = getExistingUserLog('purchase_orders', record.id, null);
        const newLog = generateNewUserLog(existing);

        const extraData = {
            entry_timestamp: record.entryTimestamp || null,
            vendor_name: record.vendorName,
            design_id: record.designId || record.items?.[0]?.itemId || null,
            design_number: record.design || record.designNumber || null,
            design_group: record.designGroup || null,
            qty: record.qty || record.items?.[0]?.qty || 0,
            rate: record.rate || record.items?.[0]?.rate || record.items?.[0]?.price || 0,
            amount: record.amount || record.items?.[0]?.amount || 0,
            delivery_date: record.returnDate || record.deliveryDate || null,
            returnDate: record.returnDate || null,
            delivery_days: record.deliveryDays || null,
            remarks: record.remarks || null,
            items: record.items || [],
            totalValue: record.totalValue || 0,
            realStatus: record.status || 'Pending',
            vendorJobWorkChallanNo: record.vendorJobWorkChallanNo || '',
            poType: record.poType || 'vendor',
            linkedSoId: record.linkedSoId || '',
            linkedSoNumber: record.linkedSoNumber || '',
            soRef: record.soRef || record.linkedSoId || '',
            customerId: record.customerId || '',
            customerName: record.customerName || '',
            bomId: record.bomId || null,
            bomNumber: record.bomNumber || null,
            materialType: record.materialType || 'without_material',
            consumable_type: record.consumable_type || record.consumableType || '',
            consumableType: record.consumable_type || record.consumableType || '',
            userLog: newLog
        };

        record = {
            id: record.id,
            company_id: record.company_id,
            number: record.number,
            date: record.date,
            vendor_id: record.poType === 'inhouse' ? null : (record.vendor || record.vendorId || null),
            expected_days: record.deliveryDays || null,
            status: 'METADATA:' + JSON.stringify(extraData),
            customer_id: record.customerId || null,
            customer_name: record.customerName || null,
            linked_so_id: record.linkedSoId || null,
            linked_so_number: record.linkedSoNumber || null,
            items: record.items || [],
            po_type: record.poType || 'vendor',
            qty: parseFloat(record.qty || record.items?.[0]?.qty || 0),
            rate: parseFloat(record.rate || record.items?.[0]?.rate || record.items?.[0]?.price || 0),
            amount: parseFloat(record.amount || record.items?.[0]?.amount || 0),
            vendor_job_work_challan_no: record.vendorJobWorkChallanNo || '',
            consumable_type: record.consumable_type || record.consumableType || ''
        };
        
        // Save locally immediately to avoid RLS blocker issues
        let localPOs = [];
        try {
            localPOs = JSON.parse(localStorage.getItem('local_purchase_orders_' + currentCompany.id) || '[]');
        } catch (e) {}
        localPOs = localPOs.filter(x => x.id !== data.id);
        localPOs.push(data);
        localStorage.setItem('local_purchase_orders_' + currentCompany.id, JSON.stringify(localPOs));
    } else if (table === 'machines') {
        let localMachines = [];
        try {
            localMachines = JSON.parse(localStorage.getItem('local_machines_' + currentCompany.id) || '[]');
        } catch (e) {}
        localMachines = localMachines.filter(x => x.id !== data.id);
        localMachines.push(data);
        localStorage.setItem('local_machines_' + currentCompany.id, JSON.stringify(localMachines));
    } else if (table === 'requisition_slips') {
        let localReqs = [];
        try {
            localReqs = JSON.parse(localStorage.getItem('local_requisition_slips_' + currentCompany.id) || '[]');
        } catch (e) {}
        localReqs = localReqs.filter(x => x.id !== data.id);
        localReqs.push(data);
        localStorage.setItem('local_requisition_slips_' + currentCompany.id, JSON.stringify(localReqs));
    } else if (table === 'production_plans') {
        let localPlans = [];
        try {
            localPlans = JSON.parse(localStorage.getItem('local_production_plans_' + currentCompany.id) || '[]');
        } catch (e) {}
        localPlans = localPlans.filter(x => x.id !== data.id);
        localPlans.push(data);
        localStorage.setItem('local_production_plans_' + currentCompany.id, JSON.stringify(localPlans));
    } else if (table === 'outwards') {
        let localOutwards = [];
        try {
            localOutwards = JSON.parse(localStorage.getItem('local_outwards_' + currentCompany.id) || '[]');
        } catch (e) {}
        localOutwards = localOutwards.filter(x => x.id !== data.id);
        localOutwards.push(data);
        localStorage.setItem('local_outwards_' + currentCompany.id, JSON.stringify(localOutwards));
    } else if (table === 'gate_passes') {
        let localGPs = [];
        try {
            localGPs = JSON.parse(localStorage.getItem('local_gate_passes_' + currentCompany.id) || '[]');
        } catch (e) {}
        localGPs = localGPs.filter(x => x.id !== data.id);
        localGPs.push(data);
        localStorage.setItem('local_gate_passes_' + currentCompany.id, JSON.stringify(localGPs));
    } else if (table === 'generic_transactions') {
        let localGtx = [];
        try {
            localGtx = JSON.parse(localStorage.getItem('local_generic_transactions_' + currentCompany.id) || '[]');
        } catch (e) {}
        localGtx = localGtx.filter(x => x.id !== data.id);
        localGtx.push(data);
        localStorage.setItem('local_generic_transactions_' + currentCompany.id, JSON.stringify(localGtx));
    }
    
    try {
        const sbClient = window.supabase || (typeof supabase !== 'undefined' && typeof supabase.from === 'function' ? supabase : null);
        const cleanRecord = typeof cleanRecordForSupabase === 'function' ? cleanRecordForSupabase(table, record) : record;
        console.log(`[saveToSupabase] Upserting to ${table}:`, cleanRecord);
        let error = null;
        if (sbClient) {
            const timeoutPromise = new Promise((_, reject) => 
                setTimeout(() => reject(new Error('Supabase network request timed out (8s limit)')), 8000)
            );
            try {
                const res = await Promise.race([
                    sbClient.from(table).upsert(cleanRecord),
                    timeoutPromise
                ]);
                error = res ? res.error : null;
            } catch(err) {
                error = err;
            }
        } else {
            console.warn(`[saveToSupabase] Supabase client offline. Saving ${table} locally.`);
        }
        let retries = 0;
        while (error && sbClient && retries < 10 && (
            error.code === 'PGRST204' ||
            error.code === '42703' ||
            (error.message && (
                error.message.includes('schema cache') ||
                error.message.includes('Could not find') ||
                error.message.includes('column')
            ))
        )) {
            retries++;
            const errMsg = error.message || (typeof error === 'string' ? error : '');
            const colMatch = errMsg.match(/Could not find the '([^']+)' column/i) ||
                             errMsg.match(/column ["']([^"']+)["'] of relation/i) ||
                             errMsg.match(/column ["']([^"']+)["']/i);
            const missingCol = colMatch ? colMatch[1] : null;
            if (missingCol && cleanRecord[missingCol] !== undefined) {
                console.warn(`[Auto-Heal] Column '${missingCol}' not found in Supabase table '${table}' schema cache. Retrying upsert without '${missingCol}' (Attempt ${retries})...`);
                delete cleanRecord[missingCol];
                try {
                    const timeoutPromise = new Promise((_, reject) => 
                        setTimeout(() => reject(new Error('Supabase network request timed out (8s limit)')), 8000)
                    );
                    const retryRes = await Promise.race([
                        sbClient.from(table).upsert(cleanRecord),
                        timeoutPromise
                    ]);
                    error = retryRes ? retryRes.error : null;
                    if (!error) {
                        console.log(`[saveToSupabase] Auto-heal succeeded! Saved to ${table} without missing column '${missingCol}'.`);
                    }
                } catch(retryErr) {
                    error = retryErr;
                }
            } else {
                break;
            }
        }

        if (error) {
            console.error(`[saveToSupabase] Error upserting to ${table}:`, error);
        } else {
            console.log(`[saveToSupabase] Successfully saved to ${table}!`);
        }

        if (error) {
            if (table === 'customers' || table === 'vendors') {
                console.warn(`Supabase ${table} full upsert failed: ${error.message}. Attempting fallback base upsert...`);
                let baseRecord = {};
                if (table === 'customers') {
                    baseRecord = {
                        id: record.id,
                        company_id: record.company_id,
                        code: record.code,
                        name: record.name,
                        gst: record.gst,
                        contact: record.contact || '',
                        email: record.email || '',
                        contactPerson: record.contactPerson || '',
                        designation: record.designation || '',
                        city: record.city || '',
                        state: record.state || '',
                        address: record.address || '',
                        pincode: record.pincode || null,
                        distance: record.distance !== undefined ? record.distance : null,
                        pan: record.pan || '',
                        gst_type: record.gst_type || 'Regular',
                        tds_applicable: record.tds_applicable || false,
                        tds_policy: record.tds_policy || null
                    };
                } else if (table === 'vendors') {
                    baseRecord = {
                        id: record.id,
                        company_id: record.company_id,
                        code: record.code,
                        name: record.name,
                        gst: record.gst,
                        contact: record.contact || '',
                        email: record.email || '',
                        contactPerson: record.contactPerson || '',
                        designation: record.designation || '',
                        city: record.city || '',
                        spec: record.spec || '',
                        address: record.address || '',
                        group: record.group || '',
                        state: record.state || '',
                        pincode: record.pincode || null,
                        distance: record.distance !== undefined ? record.distance : null,
                        pan: record.pan || '',
                        gst_type: record.gst_type || 'Regular',
                        tds_applicable: record.tds_applicable || false,
                        tds_policy: record.tds_policy || null
                    };
                }
                if (sbClient) {
                    const { error: baseErr } = await sbClient.from(table).upsert(baseRecord);
                    if (baseErr) {
                        console.warn(`Supabase ${table} base upsert also failed: ${baseErr.message}. Keeping local record.`);
                        showToast(`${table === 'customers' ? 'Customer' : 'Vendor'} saved locally (Offline mode)`, "warning");
                    } else {
                        console.log(`[saveToSupabase] Saved ${table} using base fields fallback successfully.`);
                    }
                }
                return;
            }
            if (table === 'purchase_orders') {
                console.warn("Supabase PO upsert failed (RLS Restriction), fallback used:", error.message);
                showToast("PO Draft saved locally (Offline mode)", "warning");
                return;
            }
            if (table === 'outwards') {
                console.warn("Supabase Outward upsert failed (RLS Restriction), fallback used:", error.message);
                showToast("Challan saved locally (Offline mode)", "warning");
                return;
            }
            if (table === 'gate_passes') {
                console.warn("Supabase gate_passes upsert failed:", error.message);
                showToast("Gate Pass saved locally (Offline mode)", "warning");
                return;
            }
            if (table === 'machines' || table === 'items') {
                console.warn(`Supabase ${table} upsert failed (fallback used):`, error.message);
                showToast(`${table === 'items' ? 'Item' : 'Machine'} saved locally (Offline mode)`, "warning");
                return;
            }
            if (table === 'requisition_slips') {
                console.warn("Supabase requisition_slips upsert failed:", error.message);
                showToast("Requisition saved locally (Offline mode)", "warning");
                return;
            }
            if (table === 'production_plans') {
                console.warn("Supabase production_plans upsert failed:", error.message);
                showToast(`Production Plan save warning: ${error.message}`, "warning");
                // Don't throw so local storage retains fallback, but warn user
                return;
            }
            if (table === 'generic_transactions') {
                console.warn("Supabase generic_transactions upsert failed (fallback used):", error.message);
                showToast("Voucher saved locally (Offline mode)", "warning");
                return;
            }
            showToast(`Save to ${table} failed: ${error.message}`, 'error');
            throw error;
        }
        
        // Log transaction edits/creations in Global Audit Logs
        if (['sales_orders', 'purchase_orders', 'grns', 'requisition_slips', 'outwards', 'production_slips', 'production_plans', 'generic_transactions', 'boms'].includes(table)) {
            const action = isEdit ? 'Modified' : 'Created';
            let moduleName = 'Transactions';
            if (table === 'sales_orders') moduleName = 'Sales Orders';
            else if (table === 'purchase_orders') moduleName = 'Purchase Orders';
            else if (table === 'grns') moduleName = 'GRN';
            else if (table === 'requisition_slips') moduleName = 'Requisitions';
            else if (table === 'outwards') moduleName = 'Outward';
            else if (table === 'production_slips') moduleName = 'Production';
            else if (table === 'production_plans') moduleName = 'Production';
            else if (table === 'generic_transactions') {
                if (data.type === 'invoice') moduleName = 'Invoices';
                else if (data.type === 'voucher') moduleName = 'Vouchers';
                else if (data.type === 'salesreturn') moduleName = 'Sales Return';
                else if (data.type === 'purchasereturn') moduleName = 'Purchase Return';
                else if (data.type === 'receipt') moduleName = 'Receipts';
                else if (data.type === 'payment') moduleName = 'Payments';
                else if (data.type === 'journal') moduleName = 'Journal';
                else if (data.type === 'contra') moduleName = 'Contra';
                else moduleName = 'Accounting';
            }
            else if (table === 'boms') moduleName = 'BOM';

            const docNo = data.number || data.grnNo || data.outwardNo || data.reqNo || data.prodNo || data.voucherNo || data.bomNo || data.planNo || data.name || data.id || '';
            const detailPrefix = isEdit ? 'Updated' : 'Created';
            const docTypeLabel = table === 'sales_orders' ? 'sales order' :
                                 table === 'purchase_orders' ? 'purchase order' :
                                 table === 'grns' ? 'GRN' :
                                 table === 'requisition_slips' ? 'requisition' :
                                 table === 'outwards' ? 'outward' :
                                 table === 'production_slips' ? 'production slip' :
                                 table === 'production_plans' ? 'production plan' :
                                 table === 'boms' ? 'BOM' : 'transaction';
            
            logUserAction(moduleName, action, `${detailPrefix} ${docTypeLabel}: ${docNo}`);
        }

        if (mappedVoucherType) {
            await window.updateVoucherApprovalOnSave(mappedVoucherType, data.id);
        }
    } catch (e) {
        if (table === 'purchase_orders') {
            console.warn("Supabase PO upsert failed, fallback used:", e.message);
            showToast("PO Draft saved locally (Offline mode)", "warning");
            return;
        }
        if (table === 'outwards') {
            console.warn("Supabase Outward upsert failed, fallback used:", e.message);
            showToast("Challan saved locally (Offline mode)", "warning");
            return;
        }
        if (table === 'machines') {
            console.warn("Supabase machines upsert failed, fallback used:", e.message);
            return;
        }
        if (table === 'requisition_slips') {
            console.warn("Supabase requisition_slips upsert failed, fallback used:", e.message);
            return;
        }
        if (table === 'production_plans') {
            console.warn("Supabase production_plans upsert failed, fallback used:", e.message);
            return;
        }
        if (table === 'generic_transactions') {
            console.warn("Supabase generic_transactions upsert failed, fallback used:", e.message);
            showToast("Voucher saved locally (Offline mode)", "warning");
            return;
        }
        throw e;
    }
}

async function deleteFromSupabase(table, id) {
    if (!currentCompany) return;
    
    if (table === 'purchase_orders') {
        let localPOs = [];
        try {
            localPOs = JSON.parse(localStorage.getItem('local_purchase_orders_' + currentCompany.id) || '[]');
        } catch (e) {}
        localPOs = localPOs.filter(x => x.id !== id);
        localStorage.setItem('local_purchase_orders_' + currentCompany.id, JSON.stringify(localPOs));
    } else if (table === 'machines') {
        let localMachines = [];
        try {
            localMachines = JSON.parse(localStorage.getItem('local_machines_' + currentCompany.id) || '[]');
        } catch (e) {}
        localMachines = localMachines.filter(x => x.id !== id);
        localStorage.setItem('local_machines_' + currentCompany.id, JSON.stringify(localMachines));
    } else if (table === 'requisition_slips') {
        let localReqs = [];
        try {
            localReqs = JSON.parse(localStorage.getItem('local_requisition_slips_' + currentCompany.id) || '[]');
        } catch (e) {}
        localReqs = localReqs.filter(x => x.id !== id);
        localStorage.setItem('local_requisition_slips_' + currentCompany.id, JSON.stringify(localReqs));
    } else if (table === 'production_plans') {
        let localPlans = [];
        try {
            localPlans = JSON.parse(localStorage.getItem('local_production_plans_' + currentCompany.id) || '[]');
        } catch (e) {}
        localPlans = localPlans.filter(x => x.id !== id);
        localStorage.setItem('local_production_plans_' + currentCompany.id, JSON.stringify(localPlans));
    } else if (table === 'outwards') {
        let localOutwards = [];
        try {
            localOutwards = JSON.parse(localStorage.getItem('local_outwards_' + currentCompany.id) || '[]');
        } catch (e) {}
        localOutwards = localOutwards.filter(x => x.id !== id);
        localStorage.setItem('local_outwards_' + currentCompany.id, JSON.stringify(localOutwards));
    } else if (table === 'gate_passes') {
        let localGPs = [];
        try {
            localGPs = JSON.parse(localStorage.getItem('local_gate_passes_' + currentCompany.id) || '[]');
        } catch (e) {}
        localGPs = localGPs.filter(x => x.id !== id);
        localStorage.setItem('local_gate_passes_' + currentCompany.id, JSON.stringify(localGPs));
    } else if (table === 'generic_transactions') {
        let localGtx = [];
        try {
            localGtx = JSON.parse(localStorage.getItem('local_generic_transactions_' + currentCompany.id) || '[]');
        } catch (e) {}
        localGtx = localGtx.filter(x => x.id !== id);
        localStorage.setItem('local_generic_transactions_' + currentCompany.id, JSON.stringify(localGtx));
    }
    
    try {
        const { error } = await window.supabase.from(table).delete().eq('id', id).eq('company_id', currentCompany.id);
        if (error) {
            if (table === 'purchase_orders') {
                console.warn("Supabase PO delete failed (RLS Restriction):", error.message);
                return;
            }
            if (table === 'outwards') {
                console.warn("Supabase Outward delete failed (RLS Restriction):", error.message);
                return;
            }
            if (table === 'machines') {
                console.warn("Supabase machines delete failed:", error.message);
                return;
            }
            if (table === 'requisition_slips') {
                console.warn("Supabase requisition_slips delete failed:", error.message);
                return;
            }
            if (table === 'production_plans') {
                console.warn("Supabase production_plans delete failed:", error.message);
                return;
            }
            showToast(`Delete from ${table} failed: ${error.message}`, 'error');
            throw error;
        }
    } catch (e) {
        if (table === 'purchase_orders') {
            console.warn("Supabase PO delete failed:", e.message);
            return;
        }
        if (table === 'outwards') {
            console.warn("Supabase Outward delete failed:", e.message);
            return;
        }
        if (table === 'machines') {
            console.warn("Supabase machines delete failed:", e.message);
            return;
        }
        if (table === 'requisition_slips') {
            console.warn("Supabase requisition_slips delete failed:", e.message);
            return;
        }
        if (table === 'production_plans') {
            console.warn("Supabase production_plans delete failed:", e.message);
            return;
        }
        throw e;
    }
}

// ===== AUTHENTICATION & ACCESS RIGHTS =====

async function checkSession() {
    const sessionUser = sessionStorage.getItem('embroideryflow_current_user');
    const sessionCompany = sessionStorage.getItem('embroideryflow_current_company');

    if (sessionUser) {
        try {
            const parsedUser = JSON.parse(sessionUser);
            // Refresh from masterDB to get latest permissions
            const latest = (masterDB && Array.isArray(masterDB.users))
                ? masterDB.users.find(u => u.id === parsedUser.id || (u.username && u.username === parsedUser.username))
                : null;
            currentUser = latest || parsedUser;

            // Freshly pull from Supabase to bypass any local storage sync lag/cache
            if (window.supabase) {
                try {
                    const fetchPromise = window.supabase.from('users').select('*').eq('username', currentUser.username).maybeSingle();
                    const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), 10000));
                    const { data, error } = await Promise.race([fetchPromise, timeoutPromise]);
                    if (data && !error) {
                        const companyAccess = data.company_access || {};
                        currentUser = {
                            id: data.id,
                            username: data.username,
                            password: data.password,
                            displayName: data.display_name || '',
                            email: data.email || '',
                            phone: data.phone || '',
                            role: data.role,
                            isSuperAdmin: data.is_super_admin || false,
                            companyAccess: companyAccess,
                            department: companyAccess.__department || '',
                            reportingManager: companyAccess.__reportingManager || '',
                            rules: companyAccess.__rules || ''
                        };
                        const idx = masterDB.users.findIndex(u => u.id === currentUser.id || u.username === currentUser.username);
                        if (idx !== -1) {
                            masterDB.users[idx] = currentUser;
                        } else {
                            masterDB.users.push(currentUser);
                        }
                        localStorage.setItem(MASTER_KEY, JSON.stringify(masterDB));
                    }
                } catch(e) {
                    console.error("Failed to fetch fresh user permissions in checkSession:", e);
                    window.isSupabaseOffline = true;
                }
            }

            sessionStorage.setItem('embroideryflow_current_user', JSON.stringify(currentUser));
        } catch(e) {
            currentUser = null;
        }
    }

    if (!currentUser) {
        showLoginOverlay();
        return;
    }

    if (sessionCompany) {
        try {
            const parsedCompany = JSON.parse(sessionCompany);
            // Refresh from masterDB to get latest company settings/enabled actions
            const latestCo = masterDB.companies.find(c => c.id === parsedCompany.id);
            currentCompany = latestCo || parsedCompany;
            sessionStorage.setItem('embroideryflow_current_company', JSON.stringify(currentCompany));
            // Verify this company is still accessible
            const access = getUserCompanyAccess(currentUser, currentCompany.id);
            if (!access || !access.enabled) {
                currentCompany = null;
                sessionStorage.removeItem('embroideryflow_current_company');
            }
        } catch(e) {
            currentCompany = null;
        }
    }

    if (!currentCompany) {
        hideLoginOverlay();
        showCompanySelection();
        return;
    }

    // Both user and company set - load and show dashboard
    await loadCompanyDB(currentCompany.id);
    hideLoginOverlay();
    hideCompanySelection();
    updateTopbarCompany();
    if (currentUser) {
        document.getElementById('sessionUsername').textContent = `${currentUser.username} (${currentUser.role || 'User'})`;
    }
    updateTabVisibility();
    switchModuleTab('dashboard');
}

function getUserCompanyAccess(user, companyId) {
    if (!user) return null;
    if (user.isSuperAdmin) {
        return { enabled: true, isAdmin: true, permissions: Object.assign({}, ALL_PERMS) };
    }
    return (user.companyAccess || {})[companyId] || null;
}

function showLoginOverlay() {
    const loginUserEl = document.getElementById('login-username');
    if (loginUserEl) loginUserEl.value = '';
    document.getElementById('login-password').value = '';
    const overlay = document.getElementById('login-overlay');
    if (overlay) {
        overlay.classList.add('open');
        overlay.style.setProperty('opacity', '1', 'important');
        overlay.style.setProperty('pointer-events', 'auto', 'important');
        overlay.style.setProperty('display', 'flex', 'important');
    }
    hideCompanySelection();
}

function hideLoginOverlay() {
    const overlay = document.getElementById('login-overlay');
    if (overlay) {
        overlay.classList.remove('open');
        overlay.style.setProperty('opacity', '0', 'important');
        overlay.style.setProperty('pointer-events', 'none', 'important');
        overlay.style.setProperty('display', 'none', 'important');
    }
}

function showCompanySelection() {
    const overlay = document.getElementById('company-select-overlay');
    if (!overlay || !currentUser) return;

    // Update welcome text
    document.getElementById('co-select-welcome').textContent = `=K Welcome, ${currentUser.username}`;

    // Show/hide create company button for super admin, admins, and owners
    const createBtn = document.getElementById('co-select-create-btn');
    if (createBtn) {
        const activeUser = (typeof currentUser !== 'undefined' ? currentUser : null) || JSON.parse(sessionStorage.getItem('embroideryflow_current_user') || 'null');
        const isAllowedToCreate = activeUser && (
            activeUser.isSuperAdmin ||
            (activeUser.role || '').toLowerCase().includes('admin') ||
            (activeUser.role || '').toLowerCase().includes('owner')
        );
        createBtn.style.display = isAllowedToCreate ? 'block' : 'none';
    }

    // Build company cards
    const grid = document.getElementById('company-cards-grid');
    const companies = masterDB.companies;
    const accessibleCompanies = companies.filter(co => {
        if (!co.active) return false;
        const access = getUserCompanyAccess(currentUser, co.id);
        return access && access.enabled;
    });

    if (!accessibleCompanies.length) {
        grid.innerHTML = `<div style="text-align:center; color:var(--text-muted); padding:40px;">No companies assigned to your account. Contact your administrator.</div>`;
    } else {
        grid.innerHTML = accessibleCompanies.map(co => {
            // Compute glow color from hex
            const hex = co.color;
            const r = parseInt(hex.slice(1,3), 16);
            const g = parseInt(hex.slice(3,5), 16);
            const b = parseInt(hex.slice(5,7), 16);
            const glow = `rgba(${r},${g},${b},0.15)`;
            
            let logoHTML = co.code;
            if (co.logo) {
                if (co.logo.trim().startsWith('<svg') || co.logo.trim().startsWith('<?xml')) {
                    logoHTML = co.logo;
                } else if (co.logo.trim().startsWith('data:image') || co.logo.trim().startsWith('http://') || co.logo.trim().startsWith('https://')) {
                    logoHTML = `<img src="${co.logo}" style="width:100%; height:100%; object-fit:contain; border-radius:12px;">`;
                } else {
                    logoHTML = co.logo.substring(0, 3).toUpperCase();
                }
            }

            return `
                <div class="company-card" onclick="selectCompany('${co.id}')"
                     style="--co-color: ${co.color}; --co-color-glow: ${glow};">
                    <div class="company-card-badge" style="display:flex; align-items:center; justify-content:center;">${logoHTML}</div>
                    <div class="company-card-name">${co.name}</div>
                    <div class="company-card-sub">${co.id.toUpperCase()} � Active</div>
                    <div class="company-card-arrow">&rarr;</div>
                </div>
            `;
        }).join('');
    }

    overlay.classList.add('open');
    overlay.style.setProperty('opacity', '1', 'important');
    overlay.style.setProperty('pointer-events', 'auto', 'important');
    overlay.style.setProperty('display', 'flex', 'important');
}

function hideCompanySelection() {
    const overlay = document.getElementById('company-select-overlay');
    if (overlay) {
        overlay.classList.remove('open');
        overlay.style.setProperty('opacity', '0', 'important');
        overlay.style.setProperty('pointer-events', 'none', 'important');
        overlay.style.setProperty('display', 'none', 'important');
    }
}

