async function loginUser() {
    const username = document.getElementById('login-username').value.trim().toLowerCase();
    const password = document.getElementById('login-password').value;

    if (!username) { showToast('Please enter username', 'error'); return; }
    if (!password) { showToast('Please enter password', 'error'); return; }

    let user = null;
    let isOffline = false;

    if (window.supabase) {
        showImportLoadingOverlay();
        try {
            const fetchPromise = window.supabase.from('users').select('*').eq('username', username).maybeSingle();
            const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), 10000));
            const { data, error } = await Promise.race([fetchPromise, timeoutPromise]);
            if (error) throw error;
            if (data) {
                const companyAccess = data.company_access || {};
                user = {
                    id: data.id,
                    username: data.username,
                    password: data.password,
                    displayName: data.display_name || '',
                    email: data.email || '',
                    phone: data.phone || '',
                    role: data.role,
                    isSuperAdmin: data.is_super_admin || false,
                    companyAccess: companyAccess,
                    department: companyAccess.__department || '',
                    reportingManager: companyAccess.__reportingManager || '',
                    rules: companyAccess.__rules || ''
                };
                const idx = masterDB.users.findIndex(u => u.username === username || u.id === data.id);
                if (idx !== -1) {
                    masterDB.users[idx] = user;
                } else {
                    masterDB.users.push(user);
                }
                try {
                    localStorage.setItem(MASTER_KEY, JSON.stringify(masterDB));
                } catch (e) {}
            }
        } catch (err) {
            console.error("Failed to fetch user from Supabase during login:", err);
            isOffline = true;
        }
        hideImportLoadingOverlay();
    }

    if (!user) {
        user = masterDB.users.find(u => u.username === username);
    }

    if (!user) {
        showToast('User profile not found in local records.', 'error');
        return;
    }

    if (window.supabase && !isOffline) {
        showImportLoadingOverlay();
        let loginEmail = user.email || `${username}@girisons.com`;
        let authSuccess = false;
        try {
            const authPromise = window.supabase.auth.signInWithPassword({
                email: loginEmail,
                password: password
            });
            const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout')), 10000));
            let { data, error } = await Promise.race([authPromise, timeoutPromise]);
            
            // If sign-in fails with invalid credentials and user.email was a custom email, fallback to username@girisons.com
            if (error && user.email && user.email !== `${username}@girisons.com`) {
                const fallbackEmail = `${username}@girisons.com`;
                const retryPromise = window.supabase.auth.signInWithPassword({
                    email: fallbackEmail,
                    password: password
                });
                const retryRes = await Promise.race([retryPromise, timeoutPromise]);
                if (!retryRes.error) {
                    error = null;
                    data = retryRes.data;
                }
            }

            if (!error) {
                authSuccess = true;
            } else {
                console.error("Supabase authentication failed:", error.message);
            }
        } catch (err) {
            console.error("Supabase authentication timed out or network error:", err);
        }
        hideImportLoadingOverlay();

        if (!authSuccess) {
            // Offline fallback / local credential verification when Supabase Auth fails or is unreachable
            if (user.password !== password) {
                showToast('Incorrect password!', 'error');
                return;
            }
            showToast('Cloud connection unavailable. Logged in locally.', 'warning');
        }
    } else {
        // Fallback for offline or local-only mode
        if (user.password !== password) {
            showToast('Incorrect password!', 'error');
            return;
        }
    }

    currentUser = user;
    sessionStorage.setItem('embroideryflow_current_user', JSON.stringify(currentUser));
    hideLoginOverlay();
    logUserAction('Authentication', 'Login', 'Logged in successfully');
    showCompanySelection();
}

function logoutUser() {
    if (!confirm("Are you sure you want to logout?")) {
        return;
    }
    if (currentUser) {
        logUserAction('Authentication', 'Logout', 'Logged out');
    }
    currentUser = null;
    currentCompany = null;
    db = {};
    sessionStorage.removeItem('embroideryflow_current_user');
    sessionStorage.removeItem('embroideryflow_current_company');
    hideCompanySelection();
    showLoginOverlay();
}

function checkPermission(module, action) {
    const user = currentUser || window.currentUser;
    const comp = currentCompany || window.currentCompany;
    if (!user || !comp) return false;
    if (user.isSuperAdmin) return true;

    const access = getUserCompanyAccess(user, comp.id);
    if (!access || !access.enabled) return false;
    if (access.isAdmin) return true;

    const p = access.permissions || {};

    if (module.startsWith('module_')) {
        // Dashboard and Reports tabs are ALWAYS accessible to any enabled user in the company
        if (module === 'module_dashboard' || module === 'module_reports') return true;
        if (p[module] === true) {
            return true;
        }
        if (module === 'module_masters') {
            if (!!p.masters_read) return true;
            const subMasters = ['customers', 'vendors', 'items', 'bom', 'transporters', 'units', 'hsn', 'itemgroups', 'vendorgroups', 'doctypes', 'fabrictypes', 'packingtypes', 'taxinames', 'machines', 'salestypes', 'purchasetypes', 'tdspolicies', 'gstnatures', 'jobworktypes', 'salesaccounts', 'purchaseaccounts'];
            return subMasters.some(s => !!p[`masters_${s}_read`]);
        }
        if (module === 'module_transactions') {
            if (p.module_transactions === true || p.module_transactions_read === true) return true;
            const txs = ['so', 'po', 'grn', 'outward', 'invoice', 'voucher', 'salesreturn', 'purchasereturn', 'gate_pass', 'receipt', 'payment', 'journal', 'contra', 'purchases'];
            return txs.some(t => !!p[`${t}_read`] || (t === 'po' && (!!p.po_vendor_read || !!p.po_finishing_jw_read || !!p.po_inhouse_read || !!p.po_consumable_read || !!p.po_other_read)) || (t === 'grn' && (!!p.grn_cust_plain_read || !!p.grn_vend_emb_read || !!p.grn_consumable_read)));
        }
        if (module === 'module_production') {
            return !!p.prod_read || !!p.prod_plan_read || !!p.sampling_read || !!p.sampling_plan_read || !!p.requisition_read;
        }
        if (module === 'module_inventory') {
            return !!p.purchases_read || !!p.grn_cust_plain_read || !!p.grn_vend_emb_read || !!p.grn_consumable_read || !!p.outward_read;
        }
        if (module === 'module_reports') return true;
        if (module === 'module_utilities') return !!p.manageUsers;
        return false;
    }

    // Specific Granular Module Check & Inheritances
    if (module === 'reports') return true;

    const hasTxModuleAccess = p.module_transactions === true || p.module_transactions_read === true || (module !== 'module_transactions' && checkPermission('module_transactions', 'read'));
    const hasInvModuleAccess = p.module_inventory === true || (module !== 'module_inventory' && checkPermission('module_inventory', 'read'));
    const hasProdModuleAccess = p.module_production === true || (module !== 'module_production' && checkPermission('module_production', 'read'));

    if (module === 'po') {
        const types = ['vendor', 'inhouse', 'consumable', 'finishing_jw', 'other'];
        if (p[`po_${action}`] !== undefined) return !!p[`po_${action}`];
        if (types.some(t => p[`po_${t}_${action}`] === true)) return true;
        return hasTxModuleAccess;
    }
    if (module === 'grn') {
        const types = ['cust_plain', 'vend_emb', 'consumable'];
        if (p[`grn_${action}`] !== undefined) return !!p[`grn_${action}`];
        if (types.some(t => p[`grn_${t}_${action}`] === true)) return true;
        return hasTxModuleAccess || hasInvModuleAccess;
    }
    if (module === 'outward') {
        if (p[`outward_${action}`] !== undefined) return !!p[`outward_${action}`];
        return hasTxModuleAccess || hasInvModuleAccess;
    }
    if (module === 'voucher' || module === 'purchases') {
        if (p[`voucher_${action}`] !== undefined) return !!p[`voucher_${action}`];
        if (p[`purchases_${action}`] !== undefined) return !!p[`purchases_${action}`];
        return hasTxModuleAccess || hasInvModuleAccess;
    }
    if (module === 'so') {
        if (p[`so_${action}`] !== undefined) return !!p[`so_${action}`];
        return hasTxModuleAccess;
    }
    if (module === 'invoice') {
        if (p[`invoice_${action}`] !== undefined) return !!p[`invoice_${action}`];
        return hasTxModuleAccess;
    }
    if (module === 'salesreturn') {
        if (p[`salesreturn_${action}`] !== undefined) return !!p[`salesreturn_${action}`];
        return hasTxModuleAccess;
    }
    if (module === 'purchasereturn') {
        if (p[`purchasereturn_${action}`] !== undefined) return !!p[`purchasereturn_${action}`];
        return hasTxModuleAccess;
    }
    if (module.startsWith('po_')) {
        const type = module.substring(3);
        const specificKey = `po_${type}_${action}`;
        if (p[specificKey] !== undefined && p[specificKey] !== false) return !!p[specificKey];
        if (type === 'finishing_jw') {
            if (p.po_vendor_read || p.po_inhouse_read || p.po_read || hasTxModuleAccess) return true;
        }
        if (p[`po_${action}`] !== undefined) return !!p[`po_${action}`];
        return hasTxModuleAccess;
    }
    if (module === 'prod') {
        const subMods = ['plan', 'sampling', 'sampling_plan'];
        if (p[`prod_${action}`] !== undefined) return !!p[`prod_${action}`];
        if (subMods.some(s => p[`${s === 'plan' ? 'prod_plan' : s}_${action}`] === true)) return true;
        return hasProdModuleAccess;
    }
    if (module === 'prod_plan' || module === 'sampling' || module === 'sampling_plan') {
        const specificKey = `${module}_${action}`;
        if (p[specificKey] !== undefined) return !!p[specificKey];
        if (p[`prod_${action}`] !== undefined) return !!p[`prod_${action}`];
        return hasProdModuleAccess;
    }

    if (module.startsWith('requisition_slip_') || module === 'requisition') {
        const specificKey = `${module}_${action}`;
        if (p[specificKey] !== undefined) return !!p[specificKey];
        if (p[`requisition_${action}`] !== undefined) return !!p[`requisition_${action}`];
        return hasProdModuleAccess || hasTxModuleAccess;
    }

    if (module === 'manageUsers') return !!p.manageUsers;
    if (module === 'reports' && action === 'view') return !!p.reports_view;
    if (module === 'gate_pass' || module === 'gatepass') {
        const key1 = `gate_pass_${action}`;
        const key2 = `gatepass_${action}`;
        if (p[key1] !== undefined) return !!p[key1];
        if (p[key2] !== undefined) return !!p[key2];
        return hasTxModuleAccess;
    }

    if (module === 'masters' || module.startsWith('masters_')) {
        const sub = module === 'masters' ? currentMasterSubtab : module.substring(8);
        if (sub) {
            const specificKey = `masters_${sub}_${action}`;
            if (p[specificKey] !== undefined) {
                return !!p[specificKey];
            }
            if (['salestypes', 'purchasetypes', 'tdspolicies', 'gstnatures', 'jobworktypes', 'salesaccounts', 'purchaseaccounts'].includes(sub)) {
                return p.module_masters === true || !!p.masters_read || !!p.masters_write || checkPermission('module_masters', 'read');
            }
            if (sub === 'vendorgroups') {
                return checkPermission('masters_vendors', action);
            }
        }
        // General fallback or tab check
        if (action === 'read') {
            if (!!p.masters_read || p.module_masters === true) return true;
            const subMasters = ['customers', 'vendors', 'items', 'bom', 'transporters', 'units', 'hsn', 'itemgroups', 'vendorgroups', 'doctypes', 'fabrictypes', 'packingtypes', 'taxinames', 'machines', 'salestypes', 'purchasetypes', 'tdspolicies', 'gstnatures', 'jobworktypes', 'salesaccounts', 'purchaseaccounts'];
            return subMasters.some(s => !!p[`masters_${s}_read`]);
        }
        return !!p[`masters_${action}`] || p.module_masters === true;
    }

    const permKey = `${module}_${action}`;
    if (p[permKey] !== undefined) {
        return !!p[permKey];
    }
    if (module === 'grn_cust_plain' || module === 'grn_vend_emb' || module === 'grn_consumable') {
        const legacyKey = `grn_${action}`;
        if (p[legacyKey] !== undefined) {
            return !!p[legacyKey];
        }
    }
    return !!p[permKey];
}



function hasOperationalPermission(controlKey) {
    if (!currentUser || !currentCompany) {
        if (controlKey.startsWith('allow_')) return true;
        return false; 
    }
    if (currentUser.isSuperAdmin) {
        if (controlKey.startsWith('allow_')) return true;
        return false;
    }

    const access = getUserCompanyAccess(currentUser, currentCompany.id);
    if (!access || !access.enabled) {
        if (controlKey.startsWith('allow_')) return false;
        return true;
    }
    if (access.isAdmin) {
        if (controlKey.startsWith('allow_')) return true;
        return false;
    }

    const p = access.permissions || {};
    return !!p[controlKey];
}

window.allowPriceChange = function() { return hasOperationalPermission('allow_price_change'); };
window.allowDiscountChange = function() { return hasOperationalPermission('allow_discount_change'); };
window.isBackDateRestricted = function() { return hasOperationalPermission('restrict_back_date'); };
window.getBackDateDaysAllowed = function() {
    if (!currentUser || !currentCompany) return 0;
    if (currentUser.isSuperAdmin) return 99999;
    const access = getUserCompanyAccess(currentUser, currentCompany.id);
    if (!access || !access.enabled || access.isAdmin) return 99999;
    const p = access.permissions || {};
    if (!p.restrict_back_date) return 99999;
    return p.restrict_back_date_days !== undefined ? Number(p.restrict_back_date_days) : 0;
};
window.shouldHideValueVouchers = function() { return hasOperationalPermission('hide_value_vouchers'); };
window.shouldHideValueReports = function() { return hasOperationalPermission('hide_value_reports'); };
window.allowNegativeInventory = function() { return hasOperationalPermission('allow_negative_inventory'); };
window.allowExportReports = function() { return hasOperationalPermission('allow_export'); };
window.allowEwayBill = function() { return hasOperationalPermission('allow_eway_bill'); };
window.allowEinvoice = function() { return hasOperationalPermission('allow_einvoice'); };

window.validateNegativeInventory = function(updatedTable, updatedData, editId) {
    if (updatedTable === 'productionSlips') return { valid: true };
    if (window.allowNegativeInventory()) return { valid: true };

    // Clone db structure lightly
    const tempDb = {};
    for (const key in window.db) {
        if (Array.isArray(window.db[key])) {
            tempDb[key] = [...window.db[key]];
        } else {
            tempDb[key] = window.db[key];
        }
    }

    // Insert or replace updatedData in the temporary table
    if (tempDb[updatedTable]) {
        if (editId) {
            const idx = tempDb[updatedTable].findIndex(item => item.id === editId);
            if (idx !== -1) {
                tempDb[updatedTable][idx] = updatedData;
            } else {
                tempDb[updatedTable].push(updatedData);
            }
        } else {
            tempDb[updatedTable].push(updatedData);
        }
    }

    // Run simulation
    const originalDb = window.db;
    window.db = tempDb;
    try {
        const { fabricPlainStock, fabricEmbStock, consumableStock } = window.calculateInventoryLedger();
        
        // 1. Check Plain Fabric Stock
        for (const key in fabricPlainStock) {
            const row = fabricPlainStock[key];
            const balWarehouse = row.inward - row.outward - (row.requisition || 0);
            const balMachine = row.requisition || 0;
            if (balWarehouse < -0.001) {
                return { valid: false, error: `Saving this voucher will cause Plain Fabric "${row.fabricType}" (GRN: ${row.grnNumber}) warehouse stock to go negative (Balance: ${balWarehouse.toFixed(2)}). Entry is not allowed.` };
            }
            if (balMachine < -0.001) {
                return { valid: false, error: `Saving this voucher will cause Plain Fabric "${row.fabricType}" (GRN: ${row.grnNumber}) machine stock to go negative (Balance: ${balMachine.toFixed(2)}). Entry is not allowed.` };
            }
        }
        
        // 2. Check Embroidered Fabric Stock
        for (const key in fabricEmbStock) {
            const row = fabricEmbStock[key];
            const balWarehouse = row.inward - row.outward - (row.requisition || 0);
            const balMachine = row.requisition || 0;
            if (balWarehouse < -0.001) {
                return { valid: false, error: `Saving this voucher will cause Embroidered Fabric "${row.fabricType}" (GRN: ${row.grnNumber}) warehouse stock to go negative (Balance: ${balWarehouse.toFixed(2)}). Entry is not allowed.` };
            }
            if (balMachine < -0.001) {
                return { valid: false, error: `Saving this voucher will cause Embroidered Fabric "${row.fabricType}" (GRN: ${row.grnNumber}) machine stock to go negative (Balance: ${balMachine.toFixed(2)}). Entry is not allowed.` };
            }
        }
        
        // 3. Check Consumables Stock
        for (const key in consumableStock) {
            const row = consumableStock[key];
            const balWarehouse = row.inward - row.outward;
            const balMachine = row.outward - row.consumed;
            if (balWarehouse < -0.001) {
                return { valid: false, error: `Saving this voucher will cause Consumable "${row.itemName}" warehouse stock to go negative (Balance: ${balWarehouse.toFixed(2)}). Entry is not allowed.` };
            }
            if (balMachine < -0.001) {
                return { valid: false, error: `Saving this voucher will cause Consumable "${row.itemName}" machine stock to go negative (Balance: ${balMachine.toFixed(2)}). Entry is not allowed.` };
            }
        }
    } finally {
        window.db = originalDb;
    }

    return { valid: true };
};

let pricingPrivacyObserver = null;
window.enforcePricingPrivacy = function() {
    const hideVouchers = window.shouldHideValueVouchers();
    const hideReports = window.shouldHideValueReports();

    if (!hideVouchers && !hideReports) return;

    if (pricingPrivacyObserver) {
        pricingPrivacyObserver.disconnect();
    }

    // 1. Hide price inputs in voucher forms
    if (hideVouchers) {
        document.querySelectorAll('.so-price-in, .po-rate-in').forEach(el => {
            if (el.value && el.value !== '***') {
                el.dataset.origVal = el.value;
            }
            if (el.type === 'number') {
                el.type = 'text';
            }
            el.value = '***';
            el.disabled = true;
            el.style.background = '#f1f5f9';
            el.style.color = '#94a3b8';
        });
        document.querySelectorAll('.row-amt-lbl, #so-total-value, #po-total-value, .so-total-lbl, .po-total-lbl, #so-total-display, #po-total-display').forEach(el => {
            el.textContent = '***';
        });
    }

    // 2. Hide currency values in DOM text nodes
    const rupeeRegex = /(?:�|\\u20B9|Rs\.)\s*[\d,]+(?:\.\d+)?/gi;
    
    function walkAndMask(node) {
        if (node.nodeType === Node.TEXT_NODE) {
            if (rupeeRegex.test(node.nodeValue)) {
                let isReport = node.parentElement.closest('.reports-section, .reports-container, #reports-tab, .report-card, .table-card, .data-table, #dashboard-tab, #costing-modal') !== null;
                let isVoucher = node.parentElement.closest('#so-modal, #po-modal, #grn-modal, .voucher-modal, .print-preview') !== null;
                
                if ((isReport && hideReports) || (isVoucher && hideVouchers)) {
                    node.nodeValue = node.nodeValue.replace(rupeeRegex, '� ***');
                }
            }
        } else {
            if (node.nodeName !== 'SCRIPT' && node.nodeName !== 'STYLE' && node.nodeName !== 'INPUT') {
                for (let child of node.childNodes) {
                    walkAndMask(child);
                }
            }
        }
    }
    
    walkAndMask(document.body);

    if (pricingPrivacyObserver) {
        pricingPrivacyObserver.observe(document.body, { childList: true, subtree: true });
    }
};

// Initialize MutationObserver
window.addEventListener('DOMContentLoaded', () => {
    pricingPrivacyObserver = new MutationObserver(() => {
        window.enforcePricingPrivacy();
    });
    pricingPrivacyObserver.observe(document.body, { childList: true, subtree: true });
    window.enforcePricingPrivacy();
});

// ===== TAB VISIBILITY (replaces updateSidebarVisibility) =====
function updateSidebarVisibility() { updateTabVisibility(); } // backward compat alias

window.hasAnyPermission = function(module) {
    if (typeof currentUser === 'undefined' || !currentUser || !currentCompany) return false;
    if (currentUser.isSuperAdmin) return true;
    return checkPermission(module, 'read') || 
           checkPermission(module, 'write') || 
           checkPermission(module, 'delete') || 
           checkPermission(module, 'edit_cancelled');
};

function updateTabVisibility() {
    const hasAnyPermission = window.hasAnyPermission;

    // If currentMasterSubtab is not visible or not enabled in company, switch to first visible & enabled
    const subtabs = ['customers', 'vendors', 'items', 'bom', 'transporters', 'units', 'hsn', 'itemgroups', 'vendorgroups', 'doctypes', 'fabrictypes', 'packingtypes', 'taxinames', 'machines', 'salestypes', 'purchasetypes', 'tdspolicies', 'gstnatures', 'jobworktypes'];
    const visibleSub = subtabs.find(s => hasAnyPermission(`masters_${s}`) && isMasterEnabledInCompany(s));
    if (visibleSub && (!currentMasterSubtab || !hasAnyPermission(`masters_${currentMasterSubtab}`) || !isMasterEnabledInCompany(currentMasterSubtab))) {
        currentMasterSubtab = visibleSub;
    }

    const showTab = (id, hasAccess) => {
        const el = document.getElementById('mtab-' + id);
        if (el) el.style.display = hasAccess ? '' : 'none';
    };
    showTab('dashboard', checkPermission('module_dashboard', 'read'));
    showTab('masters', checkPermission('module_masters', 'read'));
    showTab('transactions', checkPermission('module_transactions', 'read'));
    showTab('production', checkPermission('module_production', 'read') && !isLogisticsCompany() && (hasAnyPermission('prod') || hasAnyPermission('prod_plan') || hasAnyPermission('sampling') || hasAnyPermission('sampling_plan') || isTxEnabledInCompany('requisition')));
    showTab('inventory', checkPermission('module_inventory', 'read') && !isLogisticsCompany());
    showTab('freight', checkPermission('module_freight', 'read'));
    showTab('costing', checkPermission('module_costing', 'read'));
    showTab('reports', checkPermission('module_reports', 'read') && checkPermission('reports', 'view') && !isLogisticsCompany());
    showTab('utilities', checkPermission('module_utilities', 'read') && checkPermission('manageUsers'));

    // Master sub-tabs
    const showMstab = (id, hasAccess) => {
        const el = document.getElementById('mstab-' + id);
        if (el) el.style.display = (hasAccess && isMasterEnabledInCompany(id)) ? '' : 'none';
    };
    showMstab('customers', hasAnyPermission('masters_customers'));
    showMstab('vendors', hasAnyPermission('masters_vendors'));
    showMstab('items', hasAnyPermission('masters_items'));
    showMstab('bom', hasAnyPermission('masters_bom'));
    showMstab('transporters', hasAnyPermission('masters_transporters'));
    showMstab('units', hasAnyPermission('masters_units'));
    showMstab('hsn', hasAnyPermission('masters_hsn'));
    showMstab('itemgroups', hasAnyPermission('masters_itemgroups'));
    showMstab('vendorgroups', hasAnyPermission('masters_vendorgroups'));
    showMstab('doctypes', hasAnyPermission('masters_doctypes'));
    showMstab('fabrictypes', hasAnyPermission('masters_fabrictypes'));
    showMstab('packingtypes', hasAnyPermission('masters_packingtypes'));
    showMstab('taxinames', hasAnyPermission('masters_taxinames'));
    showMstab('machines', hasAnyPermission('masters_machines'));
    showMstab('salestypes', hasAnyPermission('masters_salestypes'));
    showMstab('purchasetypes', hasAnyPermission('masters_purchasetypes'));
    showMstab('tdspolicies', hasAnyPermission('masters_tdspolicies'));
    showMstab('gstnatures', hasAnyPermission('masters_gstnatures'));
    showMstab('jobworktypes', hasAnyPermission('masters_jobworktypes'));

    // Masters Dashboard Grid Cards
    const masterCards = document.querySelectorAll('#module-masters .utility-card[onclick*="openMasterTab"]');
    masterCards.forEach(card => {
        const onclickAttr = card.getAttribute('onclick') || '';
        const match = onclickAttr.match(/openMasterTab\(['"]([^'"]+)['"]\)/);
        if (match) {
            const tabId = match[1];
            const hasPerm = hasAnyPermission(`masters_${tabId}`);
            const isEnabled = isMasterEnabledInCompany(tabId) && hasPerm;
            card.style.display = isEnabled ? '' : 'none';
        }
    });

    // Transaction sub-tabs
    const showTstab = (id, hasAccess) => {
        const el = document.getElementById('tstab-' + id);
        if (el) el.style.display = hasAccess ? '' : 'none';
    };
    const txTabs = ['so', 'po', 'grn', 'outward', 'invoice', 'voucher', 'salesreturn', 'purchasereturn', 'gatepass', 'receipt', 'payment', 'journal', 'contra'];
    
    const getTxTabPermission = (tabId) => {
        if (!currentUser) return false;
        if (currentUser.isSuperAdmin) return true;
        const access = getUserCompanyAccess(currentUser, currentCompany ? currentCompany.id : 'co4');
        if (access && access.isAdmin) return true;
        
        // If user has read access to module_transactions or any transaction right, show transaction options by default
        if (checkPermission('module_transactions', 'read')) {
            return true;
        }

        if (tabId === 'so') return hasAnyPermission('so');
        if (tabId === 'po') return hasAnyPermission('po') || hasAnyPermission('po_vendor') || hasAnyPermission('po_finishing_jw') || hasAnyPermission('po_inhouse') || hasAnyPermission('po_consumable') || hasAnyPermission('po_other');
        if (tabId === 'grn') return hasAnyPermission('grn') || hasAnyPermission('grn_cust_plain') || hasAnyPermission('grn_vend_emb') || hasAnyPermission('grn_consumable');
        if (tabId === 'outward') return hasAnyPermission('outward');
        if (tabId === 'invoice') return hasAnyPermission('invoice');
        if (tabId === 'voucher') return hasAnyPermission('voucher') || hasAnyPermission('purchases');
        if (tabId === 'salesreturn') return hasAnyPermission('salesreturn');
        if (tabId === 'purchasereturn') return hasAnyPermission('purchasereturn');
        if (tabId === 'gatepass' || tabId === 'gate_pass') return hasAnyPermission('gate_pass') || hasAnyPermission('gatepass');
        return hasAnyPermission(tabId);
    };

    txTabs.forEach(t => {
        const hasPerm = getTxTabPermission(t);
        showTstab(t, isTxEnabledInCompany(t) && hasPerm);
    });

    // Hide/show dashboard utility cards based on permissions
    const txCards = document.querySelectorAll('#transactions-dashboard-grid .utility-card[onclick*="openTxTab"]');
    txCards.forEach(card => {
        const onclickAttr = card.getAttribute('onclick') || '';
        const match = onclickAttr.match(/openTxTab\(['"]([^'"]+)['"]\)/);
        if (match) {
            const tabId = match[1];
            const hasPerm = getTxTabPermission(tabId);
            const isEnabled = isTxEnabledInCompany(tabId) && hasPerm;
            card.style.display = isEnabled ? '' : 'none';
        }
    });

    // Production subtabs permission checks
    const showPstab = (id, hasAccess) => {
        const el = document.getElementById('pstab-' + id);
        if (el) el.style.display = hasAccess ? '' : 'none';
    };
    showPstab('logs', hasAnyPermission('prod'));
    showPstab('plan', hasAnyPermission('prod_plan'));
    const reqEnabled = isTxEnabledInCompany('requisition') && (hasAnyPermission('requisition') || hasAnyPermission('prod'));
    showPstab('requisition', reqEnabled);

    // Production Dashboard Grid Cards
    const prodCards = document.querySelectorAll('#module-production .utility-card[onclick*="openProdTab"]');
    prodCards.forEach(card => {
        const onclickAttr = card.getAttribute('onclick') || '';
        const match = onclickAttr.match(/openProdTab\(['"]([^'"]+)['"]\)/);
        if (match) {
            const tabId = match[1];
            let hasPerm = true;
            if (tabId === 'logs') hasPerm = hasAnyPermission('prod');
            else if (tabId === 'sampling') hasPerm = hasAnyPermission('sampling');
            else if (tabId === 'plan') hasPerm = hasAnyPermission('prod_plan');
            else if (tabId === 'sampplan') hasPerm = hasAnyPermission('sampling_plan');
            else if (tabId === 'requisition') hasPerm = reqEnabled;
            
            card.style.display = hasPerm ? '' : 'none';
        }
    });

    // Show/hide PO classification wizard buttons based on permissions
    const poWizardBtns = document.querySelectorAll('#po-step-1 .wizard-btn');
    poWizardBtns.forEach(btn => {
        const onclickAttr = btn.getAttribute('onclick') || '';
        const match = onclickAttr.match(/selectPoType\(['"]([^'"]+)['"]\)/);
        if (match) {
            const type = match[1];
            let hasPerm = hasAnyPermission('po_' + type) || hasAnyPermission('po');
            if (type === 'finishing_jw') {
                hasPerm = hasPerm || hasAnyPermission('po_vendor') || hasAnyPermission('po_inhouse') || checkPermission('module_transactions', 'read');
            }
            btn.style.display = hasPerm ? '' : 'none';
        }
    });

    // Show/hide GRN classification wizard buttons based on permissions
    const grnStep1Btns = document.querySelectorAll('#grn-step-1 .wizard-btn');
    grnStep1Btns.forEach(btn => {
        const onclickAttr = btn.getAttribute('onclick') || '';
        const match = onclickAttr.match(/selectGrnType\(['"]([^'"]+)['"]\)/);
        if (match) {
            const type = match[1];
            let hasPerm = true;
            if (type === 'fabric') hasPerm = hasAnyPermission('grn_cust_plain') || hasAnyPermission('grn_vend_emb');
            else if (type === 'consumable') hasPerm = hasAnyPermission('grn_consumable');
            else if (type === 'other') hasPerm = hasAnyPermission('grn_consumable');
            btn.style.display = hasPerm ? '' : 'none';
        }
    });

    const grnStep2Btns = document.querySelectorAll('#grn-step-2 .wizard-btn');
    grnStep2Btns.forEach(btn => {
        const onclickAttr = btn.getAttribute('onclick') || '';
        const match = onclickAttr.match(/selectFabricSource\(['"]([^'"]+)['"]\)/);
        if (match) {
            const source = match[1];
            let hasPerm = true;
            if (source === 'customer') hasPerm = hasAnyPermission('grn_cust_plain');
            else if (source === 'vendor') hasPerm = hasAnyPermission('grn_vend_emb');
            btn.style.display = hasPerm ? '' : 'none';
        }
    });

    const grnStep3Btns = document.querySelectorAll('#grn-step-3 .wizard-btn');
    grnStep3Btns.forEach(btn => {
        const onclickAttr = btn.getAttribute('onclick') || '';
        const match = onclickAttr.match(/selectFabricSubType\(['"]([^'"]+)['"]\)/);
        if (match) {
            const subType = match[1];
            let hasPerm = true;
            if (subType === 'plain') hasPerm = hasAnyPermission('grn_cust_plain');
            else if (subType === 'embroidered') hasPerm = hasAnyPermission('grn_vend_emb');
            btn.style.display = hasPerm ? '' : 'none';
        }
    });

    // Utilities Dashboard Grid Cards
    const utilityCards = document.querySelectorAll('#module-utilities .utility-card[onclick*="openUtilityTab"]');
    utilityCards.forEach(card => {
        const onclickAttr = card.getAttribute('onclick') || '';
        const match = onclickAttr.match(/openUtilityTab\(['"]([^'"]+)['"]\)/);
        if (match) {
            const tabId = match[1];
            let hasPerm = false;
            if (['companies', 'wipe-data', 'maintenance'].includes(tabId)) {
                hasPerm = currentUser && currentUser.isSuperAdmin;
            } else {
                hasPerm = checkPermission('manageUsers');
            }
            card.style.display = hasPerm ? '' : 'none';
        }
    });

    // Hide Busy Sync Logs card in Masters or Utilities if they can't manage users
    const busySyncCards = document.querySelectorAll('.utility-card[onclick*="openBusySyncLogsModal"]');
    busySyncCards.forEach(card => {
        card.style.display = checkPermission('manageUsers') ? '' : 'none';
    });

    // If currentTxSubtab is not enabled or not allowed, switch to first allowed
    const visibleTx = txTabs.find(t => {
        let hasPerm = true;
        if (t === 'so') hasPerm = checkPermission('so', 'read');
        else if (t === 'po') hasPerm = checkPermission('po', 'read');
        else if (t === 'grn') hasPerm = (checkPermission('grn_cust_plain', 'read') || checkPermission('grn_vend_emb', 'read') || checkPermission('grn_consumable', 'read'));
        else if (t === 'outward') hasPerm = checkPermission('outward', 'read');
        else if (t === 'invoice') hasPerm = checkPermission('invoice', 'read');
        else if (t === 'voucher') hasPerm = checkPermission('voucher', 'read');
        else if (t === 'salesreturn') hasPerm = checkPermission('salesreturn', 'read');
        else if (t === 'purchasereturn') hasPerm = checkPermission('purchasereturn', 'read');
        else if (t === 'gatepass') hasPerm = checkPermission('gate_pass', 'read') || checkPermission('gatepass', 'read');
        return isTxEnabledInCompany(t) && hasPerm;
    });
    if (visibleTx && (!currentTxSubtab || !isTxEnabledInCompany(currentTxSubtab) || (() => {
        let currentPerm = true;
        if (currentTxSubtab === 'so') currentPerm = checkPermission('so', 'read');
        else if (currentTxSubtab === 'po') currentPerm = checkPermission('po', 'read');
        else if (currentTxSubtab === 'grn') currentPerm = (checkPermission('grn_cust_plain', 'read') || checkPermission('grn_vend_emb', 'read') || checkPermission('grn_consumable', 'read'));
        else if (currentTxSubtab === 'outward') currentPerm = checkPermission('outward', 'read');
        else if (currentTxSubtab === 'invoice') currentPerm = checkPermission('invoice', 'read');
        else if (currentTxSubtab === 'voucher') currentPerm = checkPermission('voucher', 'read');
        else if (currentTxSubtab === 'salesreturn') currentPerm = checkPermission('salesreturn', 'read');
        else if (currentTxSubtab === 'purchasereturn') currentPerm = checkPermission('purchasereturn', 'read');
        else if (currentTxSubtab === 'gatepass') currentPerm = checkPermission('gate_pass', 'read') || checkPermission('gatepass', 'read');
        return !currentPerm;
    })())) {
        switchTxSubtab(visibleTx);
    }
}

function logUserAction(module, action, details) {
    if (!currentUser) return;
    const logEntry = {
        timestamp: currentTimestamp(),
        username: currentUser.username,
        module: module,
        action: action,
        details: details
    };
    masterDB.userLogs = masterDB.userLogs || [];
    masterDB.userLogs.unshift(logEntry);
    saveMasterDB();
}


function currentTimestamp() {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    return `${day}/${month}/${year} ${hours}:${minutes}`;
}

