    // Dynamic sub-modal creation helper for simultaneous multi-window support
    window.getOrCreateSubModal = function(type, tabId) {
        const modalId = `${type}-submodal-${tabId}`;
        let subModal = document.getElementById(modalId);
        if (subModal) return subModal;

        const templateId = (type === 'masters' || type === 'utilities') ? `${type}-content-wrapper` : 'masters-content-wrapper';
        const template = document.getElementById(templateId);
        if (!template) return null;

        // Clone template structure
        subModal = template.cloneNode(true);
        subModal.id = modalId;

        // Clean up minimize state and structure from clone so it gets fresh button
        delete subModal.dataset.minimizeBtnInjected;
        const closeBtn = subModal.querySelector('.modal-close');
        if (closeBtn) {
            // Remove any existing .modal-minimize-btn
            const existingMinBtn = subModal.querySelector('.modal-minimize-btn');
            if (existingMinBtn) {
                existingMinBtn.remove();
            }
            // If closeBtn is inside a modal-minimize-btn-group wrapper, pull it back out and remove the wrapper
            const parent = closeBtn.parentNode;
            if (parent && (parent.classList.contains('modal-minimize-btn-group') || parent.className === 'modal-minimize-btn-group')) {
                const originalContainer = parent.parentNode;
                if (originalContainer) {
                    originalContainer.insertBefore(closeBtn, parent);
                    parent.remove();
                }
            }
        }

        // Clear out the template body to insert only the target view
        const modalBody = subModal.querySelector('.modal-body');
        if (modalBody) {
            modalBody.innerHTML = '';
            
            if (type === 'masters') {
                const originalToolbar = document.getElementById('master-action-toolbar');
                if (originalToolbar) {
                    const clonedToolbar = originalToolbar.cloneNode(true);
                    if (tabId !== 'items') {
                        clonedToolbar.querySelectorAll('#item-category-filter, #item-subcategory-filter').forEach(el => {
                            el.style.setProperty('display', 'none', 'important');
                            el.value = '';
                            const w = el.closest('.searchable-select-wrapper');
                            if (w) w.style.setProperty('display', 'none', 'important');
                        });
                    }
                    if (tabId !== 'vendors') {
                        clonedToolbar.querySelectorAll('#vendor-group-filter').forEach(el => {
                            el.style.setProperty('display', 'none', 'important');
                            el.value = '';
                            const w = el.closest('.searchable-select-wrapper');
                            if (w) w.style.setProperty('display', 'none', 'important');
                        });
                    }
                    clonedToolbar.querySelectorAll('#cust-freeze-toolbar-toggle').forEach(el => {
                        el.style.setProperty('display', ['customers', 'vendors'].includes(tabId) ? 'inline-flex' : 'none', 'important');
                        const chk = el.querySelector('input[type="checkbox"]');
                        if (chk) chk.checked = (localStorage.getItem('freeze_first_4_customer') === 'true');
                    });
                    clonedToolbar.querySelectorAll('#item-freeze-toolbar-toggle').forEach(el => {
                        el.style.setProperty('display', tabId === 'items' ? 'inline-flex' : 'none', 'important');
                        const chk = el.querySelector('input[type="checkbox"]');
                        if (chk) chk.checked = (localStorage.getItem('freeze_first_4_item') === 'true');
                    });
                    clonedToolbar.querySelectorAll('#btn-master-print').forEach(el => {
                        el.style.setProperty('display', 'none', 'important');
                    });
                    modalBody.appendChild(clonedToolbar);
                }
            }
            
            // Relocate subview
            let subviewId = '';
            if (type === 'masters') {
                subviewId = `master-view-${tabId}`;
            } else if (type === 'utilities') {
                subviewId = tabId === 'users' ? 'user-list-section' :
                            tabId === 'logs' ? 'user-logs-section' :
                            tabId === 'backups' ? 'user-backups-section' :
                            tabId === 'import-centre' ? 'user-import-centre-section' :
                            tabId === 'companies' ? 'user-companies-section' :
                            tabId === 'wipe-data' ? 'user-wipe-data-section' :
                            tabId === 'sheets-sync' ? 'user-sheets-sync-section' :
                            tabId === 'maintenance' ? 'user-maintenance-section' :
                            tabId === 'reconciliation' ? 'user-reconciliation-section' :
                            tabId === 'departments' ? 'user-departments-section' :
                            tabId === 'vouchering' ? 'user-vouchering-section' : '';
            } else if (type === 'transactions') {
                subviewId = `tx-view-${tabId}`;
            } else if (type === 'production') {
                subviewId = `prod-view-${tabId}`;
            } else if (type === 'inventory') {
                subviewId = `inv-view-${tabId}`;
            } else if (type === 'costing') {
                subviewId = 'costing-ledger-section';
            } else if (type === 'reports') {
                subviewId = 'report-output';
            }

            const originalSubview = document.getElementById(subviewId);
            if (originalSubview) {
                modalBody.appendChild(originalSubview);
                originalSubview.style.display = 'block';
                originalSubview.classList.add('active');
            }
        }

        // Adjust close button
        if (closeBtn) {
            closeBtn.removeAttribute('onclick');
            closeBtn.addEventListener('click', () => {
                window.closeModal(modalId);
            });
        }

        // Mousedown focusing logic to update current active global tab indices
        subModal.addEventListener('mousedown', () => {
            if (type === 'masters') {
                currentMasterSubtab = tabId;
            } else if (type === 'utilities') {
                currentUserMgmtTab = tabId;
            } else if (type === 'transactions') {
                window.currentTxSubtab = tabId;
            } else if (type === 'production') {
                window.currentProdSubtab = tabId;
            } else if (type === 'inventory') {
                window.currentInvSubtab = tabId;
            }
        });

        document.body.appendChild(subModal);
        
        // Inject minimize button
        if (typeof injectMinimizeButton === 'function') {
            injectMinimizeButton(modalId);
        }

        return subModal;
    };

window.openUtilityTab = function(tabId) {
    let targetTab = tabId;
    let innerTab = 'users';
    if (tabId === 'departments') {
        targetTab = 'users';
        innerTab = 'depts';
    }

    const modalId = `utilities-submodal-${targetTab}`;
    const subModal = window.getOrCreateSubModal('utilities', targetTab);
    if (!subModal) return;

    // Set modal title
    const titleEl = subModal.querySelector('#utility-modal-title');
    if (titleEl) {
        titleEl.innerHTML = targetTab === 'users' ? '= User Rights & Org Hierarchy' : (utilityTitles[targetTab] || 'System Utility');
    }

    currentUserMgmtTab = targetTab;

    // Show modal wrapper via openModal
    openModal(modalId);
    
    // Switch to that sub-tab
    switchUserMgmtTab(targetTab);

    // If we redirected, select the inner tab
    if (tabId === 'departments') {
        setTimeout(() => {
            window.switchMergedViewTab(innerTab);
        }, 50);
    } else if (targetTab === 'users') {
        // Default to users inner subtab when opened directly
        setTimeout(() => {
            window.switchMergedViewTab('users');
        }, 50);
    }
};

window.switchMergedViewTab = function(subTab) {
    // Toggle active state on buttons
    const btnUsers = document.getElementById('btn-merged-tab-users');
    const btnDepts = document.getElementById('btn-merged-tab-depts');
    const btnChart = document.getElementById('btn-merged-tab-chart');
    const btnDashboard = document.getElementById('btn-merged-tab-dashboard');
    
    if (btnUsers) btnUsers.className = subTab === 'users' ? 'btn btn-sm btn-primary' : 'btn btn-sm btn-secondary';
    if (btnDepts) btnDepts.className = subTab === 'depts' ? 'btn btn-sm btn-primary' : 'btn btn-sm btn-secondary';
    if (btnChart) btnChart.className = subTab === 'chart' ? 'btn btn-sm btn-primary' : 'btn btn-sm btn-secondary';
    if (btnDashboard) btnDashboard.className = subTab === 'dashboard-layout' ? 'btn btn-sm btn-primary' : 'btn btn-sm btn-secondary';
    
    // Toggle sub-view visibility
    const viewUsers = document.getElementById('merged-view-users');
    const viewDepts = document.getElementById('merged-view-depts');
    const viewChart = document.getElementById('merged-view-chart');
    const viewDashboard = document.getElementById('merged-view-dashboard-layout');
    
    if (viewUsers) viewUsers.style.display = subTab === 'users' ? 'block' : 'none';
    if (viewDepts) viewDepts.style.display = subTab === 'depts' ? 'block' : 'none';
    if (viewChart) viewChart.style.display = subTab === 'chart' ? 'block' : 'none';
    if (viewDashboard) viewDashboard.style.display = subTab === 'dashboard-layout' ? 'block' : 'none';
    
    // Toggle action buttons in header
    const btnAddUser = document.getElementById('btn-merged-add-user');
    const btnAddDept = document.getElementById('btn-merged-add-dept');
    
    if (btnAddUser) btnAddUser.style.display = subTab === 'users' ? 'block' : 'none';
    if (btnAddDept) btnAddDept.style.display = subTab === 'depts' ? 'block' : 'none';
    
    // Trigger render logic
    if (subTab === 'users') {
        renderUserTable();
    } else if (subTab === 'depts') {
        window.renderDepartmentsTable();
    } else if (subTab === 'chart') {
        window.renderDepartmentsOrgChart();
    } else if (subTab === 'dashboard-layout') {
        renderDashboardCustomizer(true);
    }
};

