function switchUserMgmtTab(tab) {
    if (tab === 'departments') {
        tab = 'users';
    }
    currentUserMgmtTab = tab;
    
    // Ensure dashboard is hidden (unless minimized!)
    const activeSubModal = document.getElementById(`utilities-submodal-${tab}`);
    const wrapper = activeSubModal || document.getElementById('utilities-content-wrapper');
    const isMinimized = wrapper && wrapper.classList.contains('minimized');
    const grid = document.getElementById('utilities-dashboard-grid');
    if (grid) {
        if (isMinimized) {
            grid.style.setProperty('display', 'block', 'important');
        } else {
            grid.style.setProperty('display', 'none', 'important');
        }
    }

    const tabs = ['users', 'logs', 'backups', 'import-centre', 'companies', 'wipe-data', 'sheets-sync', 'maintenance', 'reconciliation', 'vouchering'];
    tabs.forEach(t => {
        const btn = document.getElementById('btn-tab-' + t);
        if (btn) btn.classList.toggle('active', t === tab);
    });

    const sections = {
        'users': 'user-list-section',
        'logs': 'user-logs-section',
        'backups': 'user-backups-section',
        'import-centre': 'user-import-centre-section',
        'companies': 'user-companies-section',
        'wipe-data': 'user-wipe-data-section',
        'sheets-sync': 'user-sheets-sync-section',
        'maintenance': 'user-maintenance-section',
        'reconciliation': 'user-reconciliation-section',
        'vouchering': 'user-vouchering-section'
    };

    for (const [k, v] of Object.entries(sections)) {
        const sec = document.getElementById(v);
        if (sec) {
            const isInSubModal = sec.closest('[id^="utilities-submodal-"]');
            if (isInSubModal) {
                sec.style.display = 'block';
            } else {
                sec.style.display = k === tab ? 'block' : 'none';
            }
        }
    }

    const btnAddUser = wrapper ? wrapper.querySelector('#btnAddUser') : document.getElementById('btnAddUser');
    if (btnAddUser) btnAddUser.style.display = 'none'; // Merged panel has its own buttons

    const btnClearLogs = wrapper ? wrapper.querySelector('#btnClearLogs') : document.getElementById('btnClearLogs');
    if (btnClearLogs) btnClearLogs.style.display = (tab === 'logs' && checkPermission('manageUsers')) ? 'block' : 'none';

    if (tab === 'users') {
        // Run default inner sub-tab initialization
        const viewUsers = document.getElementById('merged-view-users');
        const viewDepts = document.getElementById('merged-view-depts');
        const viewChart = document.getElementById('merged-view-chart');
        
        let currentSub = 'users';
        if (viewDepts && viewDepts.style.display === 'block') currentSub = 'depts';
        else if (viewChart && viewChart.style.display === 'block') currentSub = 'chart';
        
        window.switchMergedViewTab(currentSub);
    }
    else if (tab === 'logs') renderUserLogsTable();
    else if (tab === 'companies') renderCompaniesSettingsList();
    else if (tab === 'sheets-sync') {
        window.loadSheetsSyncConfig();
    } else if (tab === 'reconciliation') {
        window.initReconciliation();
    } else if (tab === 'vouchering') {
        if (typeof window.populateVoucheringConfigTable === 'function') {
            window.populateVoucheringConfigTable();
        }
    }
}

window.wipeModuleData = async function(module, label) {
    if (!currentCompany) {
        showToast('Please select a company first', 'error');
        return;
    }

    const confirmFirst = await window.showSmartConfirm('Danger', `DANGER: Are you absolutely sure you want to delete ALL ${label} records for the company "${currentCompany.name}"?\nThis cannot be undone!`);
    if (!confirmFirst) return;
    
    const confirmSecond = await window.showSmartConfirm('Proceed with Caution', `PROCEED WITH CAUTION: This will permanently wipe all ${label} database records from Supabase and clear them from your screen. Click OK to verify.`);
    if (!confirmSecond) return;

    showToast(`Wiping ${label} data, please wait...`, 'info');
    
    try {
        if (module === 'sales_orders' || module === 'all_transactions') {
            await supabase.from('sales_orders').delete().eq('company_id', currentCompany.id);
            rawDB.salesOrders = [];
            db.salesOrders = [];
        }
        if (module === 'items') {
            await supabase.from('items').delete().eq('company_id', currentCompany.id);
            db.items = [];
        }
        if (module === 'customers') {
            await supabase.from('customers').delete().eq('company_id', currentCompany.id);
            db.customers = [];
        }
        if (module === 'vendors') {
            await supabase.from('vendors').delete().eq('company_id', currentCompany.id);
            db.vendors = [];
        }
        if (module === 'transporters') {
            await supabase.from('transporters').delete().eq('company_id', currentCompany.id).neq('contactPerson', '__CO_SETTINGS__').neq('contactPerson', '__CUSTOM_MASTERS__');
            db.transporters = db.transporters.filter(t => t.contactPerson === '__CO_SETTINGS__' || t.contactPerson === '__CUSTOM_MASTERS__');
        }
        if (module === 'grns' || module === 'all_transactions') {
            await supabase.from('grns').delete().eq('company_id', currentCompany.id);
            rawDB.grns = [];
            db.grns = [];
        }
        if (module === 'purchase_orders' || module === 'all_transactions') {
            await supabase.from('purchase_orders').delete().eq('company_id', currentCompany.id);
            localStorage.removeItem('local_purchase_orders_' + currentCompany.id);
            rawDB.pos = [];
            db.pos = [];
        }
        if (module === 'all_transactions') {
            await supabase.from('outwards').delete().eq('company_id', currentCompany.id);
            await supabase.from('production_slips').delete().eq('company_id', currentCompany.id);
            await supabase.from('generic_transactions').delete().eq('company_id', currentCompany.id);
            await supabase.from('requisition_slips').delete().eq('company_id', currentCompany.id);
            
            rawDB.outwards = [];
            rawDB.productionSlips = [];
            rawDB.genericTransactions = [];
            rawDB.requisitionSlips = [];
            
            db.outwards = [];
            db.productionSlips = [];
            db.genericTransactions = [];
            db.invoices = [];
            db.vouchers = [];
            db.salesReturns = [];
            db.purchaseReturns = [];
            db.requisitionSlips = [];
        }

        applyFinancialYearFilters();
        renderAllTables();
        
        logUserAction('Database Management', 'Bulk Wipe Data', `Wiped module: ${label}`);
        showToast(`${label} successfully wiped!`, 'success');
    } catch (err) {
        console.error("Wipe failed:", err);
        showToast(`Wipe failed: ${err.message}`, 'error');
    }
};

function renderCompaniesSettingsList() {
    const listContainer = document.getElementById('companies-settings-list');
    if (!listContainer) return;

    const companies = masterDB.companies || [];
    listContainer.innerHTML = companies.map(co => {
        const logoHTML = co.logo ? (
            co.logo.trim().startsWith('<svg') || co.logo.trim().startsWith('<?xml') ? co.logo :
            co.logo.trim().startsWith('data:image') || co.logo.trim().startsWith('http') ? `<img src="${co.logo}" style="width:40px; height:40px; object-fit:contain; border-radius:4px;">` :
            `<div style="width:40px; height:40px; border-radius:8px; background:${co.color || '#6366f1'}; color:#fff; display:flex; align-items:center; justify-content:center; font-weight:800; font-size:14px;">${co.logo.substring(0,3).toUpperCase()}</div>`
        ) : `<div style="width:40px; height:40px; border-radius:8px; background:${co.color || '#6366f1'}; color:#fff; display:flex; align-items:center; justify-content:center; font-weight:800; font-size:14px;">${(co.code || 'CO').substring(0,3).toUpperCase()}</div>`;

        return `
            <div style="background:var(--bg-card); border:1px solid var(--border); border-radius:12px; padding:18px; display:flex; flex-direction:column; gap:12px; position:relative;">
                <div style="display:flex; align-items:center; gap:12px;">
                    <div style="flex-shrink:0; display:flex; align-items:center; justify-content:center;">${logoHTML}</div>
                    <div>
                        <div style="font-weight:700; font-size:14px; color:var(--text-primary); line-height:1.2;">${co.name}</div>
                        <div style="font-size:11px; color:var(--text-muted); margin-top:2px;">Code: <strong>${co.code}</strong> | ID: ${co.id}</div>
                    </div>
                </div>
                <div style="font-size:12px; color:var(--text-secondary); border-top:1px solid rgba(255,255,255,0.04); padding-top:10px;">
                    <div><strong>GST:</strong> ${co.gst || '-'}</div>
                    <div style="margin-top:4px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${co.address || ''}"><strong>Address:</strong> ${co.address || '-'}</div>
                </div>
                <div style="margin-top:auto; display:flex; justify-content:flex-end;">
                    <button class="btn btn-secondary btn-sm" onclick="openCompanyModal('${co.id}')" style="padding:6px 12px; font-size:11px;">=' Edit Detail</button>
                </div>
            </div>
        `;
    }).join('');
}

