function isLogisticsCompany(co) {
    if (co !== undefined && co !== null) {
        let company = co;
        if (typeof co === 'string' || typeof co === 'number') {
            const coStr = String(co).trim();
            if (!coStr) return false;
            const compList = [
                ...(typeof masterDB !== 'undefined' && masterDB && Array.isArray(masterDB.companies) ? masterDB.companies : []),
                ...(window.crossCompanyCompanies || [])
            ];
            company = compList.find(c => String(c.id).trim() === coStr || String(c.company_id || '').trim() === coStr);
            if (!company) {
                const lower = coStr.toLowerCase();
                return lower.includes('rama') || lower.includes('logistics') || lower.includes('transport');
            }
        }
        if (typeof company === 'object' && company !== null) {
            const name = (company.name || company.company_name || '').toLowerCase();
            return name.includes('logistics') || name.includes('transport') || name.includes('rama');
        }
        return false;
    }
    if (typeof currentCompany !== 'undefined' && currentCompany) {
        const name = (currentCompany.name || '').toLowerCase();
        return name.includes('logistics') || name.includes('transport') || name.includes('rama');
    }
    return false;
}
window.isLogisticsCompany = isLogisticsCompany;

function isMasterEnabledInCompany(masterKey) {
    if (!currentCompany) return true;
    if (isLogisticsCompany()) {
        if (masterKey === 'rateagreements') return true;
        const disabledMastersForLogistics = ['items', 'bom', 'itemgroups', 'fabrictypes', 'packingtypes', 'machines'];
        if (disabledMastersForLogistics.includes(masterKey)) {
            return false;
        }
    } else {
        if (masterKey === 'rateagreements') return false;
    }
    if (masterKey === 'vendorgroups') return true;
    if (!currentCompany.enabledMasters) return true;
    return currentCompany.enabledMasters[masterKey] !== false;
}

function isTxEnabledInCompany(txKey) {
    if (!currentCompany) return true;
    if (isLogisticsCompany()) {
        const disabledTxForLogistics = ['so', 'po', 'grn', 'outward', 'voucher', 'salesreturn', 'purchasereturn', 'gatepass', 'production', 'requisition'];
        if (disabledTxForLogistics.includes(txKey)) {
            return false;
        }
    }
    if (!currentCompany.enabledTransactions) return true;
    return currentCompany.enabledTransactions[txKey] !== false;
}

function openCompanyModal(coId = null) {
    try {
        const preview = document.getElementById('edit-company-logo-preview');
        const urlInput = document.getElementById('edit-company-logo-url');
        document.getElementById('edit-company-logo-file').value = '';

        if (!coId) {
            // Create Mode
            document.getElementById('company-modal-title').innerText = 'Create New Company';
            document.getElementById('edit-company-id').value = '';
            document.getElementById('edit-company-name').value = '';
            document.getElementById('edit-company-code').value = '';
            document.getElementById('edit-company-gst').value = '';
            document.getElementById('edit-company-address').value = '';
            document.getElementById('edit-company-pincode').value = '';
            document.getElementById('edit-company-phone').value = '';
            document.getElementById('edit-company-email').value = '';
            document.getElementById('edit-company-color').value = '#6366f1';
            preview.style.display = 'none';
            urlInput.value = '';

            renderModalChecklists(null);
        } else {
            // Edit Mode
            const co = masterDB.companies.find(c => c.id === coId);
            if (!co) return;

            document.getElementById('company-modal-title').innerText = 'Edit Company Detail';
            document.getElementById('edit-company-id').value = coId;
            document.getElementById('edit-company-name').value = co.name || '';
            document.getElementById('edit-company-code').value = co.code || '';
            document.getElementById('edit-company-gst').value = co.gst || '';
            document.getElementById('edit-company-address').value = co.address || '';
            document.getElementById('edit-company-pincode').value = co.pincode || '';
            document.getElementById('edit-company-phone').value = co.phone || '';
            document.getElementById('edit-company-email').value = co.email || '';
            document.getElementById('edit-company-color').value = co.color || '#6366f1';

            if (co.logo) {
                if (co.logo.startsWith('data:image') || co.logo.startsWith('http')) {
                    preview.src = co.logo;
                    preview.style.display = 'block';
                    urlInput.value = co.logo.startsWith('data:image') ? '' : co.logo;
                } else {
                    preview.style.display = 'none';
                    urlInput.value = co.logo;
                }
            } else {
                preview.style.display = 'none';
                urlInput.value = '';
            }

            renderModalChecklists(co);
        }

        openModal('company-modal');
    } catch (err) {
        console.error("Error in openCompanyModal:", err);
        window.showSmartAlert("Error", "Error opening company modal: " + err.message);
    }
}

function renderModalChecklists(co) {
    const mastersContainer = document.getElementById('company-masters-checklist');
    const txContainer = document.getElementById('company-transactions-checklist');
    if (!mastersContainer || !txContainer) return;

    mastersContainer.innerHTML = COMPANY_MASTERS_LIST.map(m => {
        const checked = co && co.enabledMasters ? (co.enabledMasters[m.key] !== false) : true;
        return `<label style="display:flex; align-items:center; gap:6px; font-weight:normal; cursor:pointer; color:var(--text-primary);">
            <input type="checkbox" class="co-master-chk" data-key="${m.key}" ${checked ? 'checked' : ''} style="width:14px; height:14px; margin:0;">
            ${m.label}
        </label>`;
    }).join('');

    txContainer.innerHTML = COMPANY_TRANSACTIONS_LIST.map(t => {
        const checked = co && co.enabledTransactions ? (co.enabledTransactions[t.key] !== false) : true;
        return `<label style="display:flex; align-items:center; gap:6px; font-weight:normal; cursor:pointer; color:var(--text-primary);">
            <input type="checkbox" class="co-tx-chk" data-key="${t.key}" ${checked ? 'checked' : ''} style="width:14px; height:14px; margin:0;">
            ${t.label}
        </label>`;
    }).join('');
}

function previewCompanyLogo(event) {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = function(e) {
        if (file.type === 'image/svg+xml') {
            const preview = document.getElementById('edit-company-logo-preview');
            preview.src = e.target.result;
            preview.style.display = 'block';
            document.getElementById('edit-company-logo-url').value = '';
            return;
        }

        const img = new Image();
        img.onload = function() {
            const canvas = document.createElement('canvas');
            const maxDim = 150; // Max size for logo since it's displayed small
            let width = img.width;
            let height = img.height;
            
            if (width > height) {
                if (width > maxDim) {
                    height = Math.round((height * maxDim) / width);
                    width = maxDim;
                }
            } else {
                if (height > maxDim) {
                    width = Math.round((width * maxDim) / height);
                    height = maxDim;
                }
            }
            
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0, width, height);
            
            const compressedBase64 = canvas.toDataURL('image/png');
            const preview = document.getElementById('edit-company-logo-preview');
            preview.src = compressedBase64;
            preview.style.display = 'block';
            document.getElementById('edit-company-logo-url').value = '';
        };
        img.src = e.target.result;
    };
    reader.readAsDataURL(file);
}

async function saveCompanySettings(event) {
    event.preventDefault();
    const coId = document.getElementById('edit-company-id').value;
    let co;
    let isNew = false;

    if (!coId) {
        isNew = true;
        const newCoId = 'co_' + Date.now();
        co = {
            id: newCoId,
            active: true
        };
    } else {
        co = masterDB.companies.find(c => c.id === coId);
        if (!co) return;
    }

    co.name = document.getElementById('edit-company-name').value.trim();
    co.code = document.getElementById('edit-company-code').value.trim();
    co.gst = document.getElementById('edit-company-gst').value.trim();
    co.address = document.getElementById('edit-company-address').value.trim();
    co.pincode = document.getElementById('edit-company-pincode').value.trim();
    co.phone = document.getElementById('edit-company-phone').value.trim();
    co.email = document.getElementById('edit-company-email').value.trim();
    co.color = document.getElementById('edit-company-color').value;

    const fileInput = document.getElementById('edit-company-logo-file');
    const urlInput = document.getElementById('edit-company-logo-url');

    if (fileInput.files.length > 0) {
        co.logo = document.getElementById('edit-company-logo-preview').src;
    } else if (urlInput.value.trim() !== '') {
        co.logo = urlInput.value.trim();
    } else if (document.getElementById('edit-company-logo-preview').style.display === 'none') {
        co.logo = '';
    }

    // Save module configuration
    co.enabledMasters = {};
    document.querySelectorAll('.co-master-chk').forEach(chk => {
        co.enabledMasters[chk.getAttribute('data-key')] = chk.checked;
    });

    co.enabledTransactions = {};
    document.querySelectorAll('.co-tx-chk').forEach(chk => {
        co.enabledTransactions[chk.getAttribute('data-key')] = chk.checked;
    });

    if (isNew) {
        masterDB.companies.push(co);
        // Grant Super Admins immediate access
        masterDB.users.forEach(u => {
            if (u.isSuperAdmin) {
                if (!u.companyAccess) u.companyAccess = {};
                u.companyAccess[co.id] = { enabled: true, isAdmin: true, permissions: Object.assign({}, ALL_PERMS) };
            }
        });

        // Also grant access to the creator if they are Admin or Owner
        const activeUser = (typeof currentUser !== 'undefined' ? currentUser : null) || JSON.parse(sessionStorage.getItem('embroideryflow_current_user') || 'null');
        if (activeUser && !activeUser.isSuperAdmin) {
            const u = masterDB.users.find(x => x.id === activeUser.id || x.username === activeUser.username);
            if (u) {
                if (!u.companyAccess) u.companyAccess = {};
                u.companyAccess[co.id] = { enabled: true, isAdmin: true, permissions: Object.assign({}, ALL_PERMS) };
            }
            if (!activeUser.companyAccess) activeUser.companyAccess = {};
            activeUser.companyAccess[co.id] = { enabled: true, isAdmin: true, permissions: Object.assign({}, ALL_PERMS) };
            sessionStorage.setItem('embroideryflow_current_user', JSON.stringify(activeUser));
            if (typeof currentUser !== 'undefined' && currentUser) {
                currentUser.companyAccess = activeUser.companyAccess;
            }
        }
    }

    // Also save to company_settings table
    if (window.supabase) {
        try {
            const settingsRec = {
                id: 'co_settings_' + co.id,
                company_id: co.id,
                name: co.name,
                gst: co.gst,
                address: co.address,
                email: co.logo,
                mobile: co.color,
                designation: co.pincode
            };
            
            if (currentCompany && currentCompany.id === co.id) {
                if (!db.company_detail) db.company_detail = [];
                let localSettings = db.company_detail.find(s => s.id === 'co_settings_' + co.id);
                if (!localSettings) {
                    localSettings = { id: 'co_settings_' + co.id, company_id: co.id };
                    db.company_detail.push(localSettings);
                }
                Object.assign(localSettings, settingsRec);
            }
            
            const { error } = await window.supabase.from('company_detail').upsert(settingsRec, { onConflict: 'id' });
            if (error) throw error;

            // Also upsert to open_companies table to satisfy foreign key constraints on other tables
            const openCompanyRec = {
                id: co.id,
                name: co.name,
                code: co.code,
                color: co.color,
                active: co.active !== undefined ? co.active : true
            };
            const { error: openCoErr } = await window.supabase.from('open_companies').upsert(openCompanyRec, { onConflict: 'id' });
            if (openCoErr) throw openCoErr;
        } catch (e) {
            console.error("Failed to save company detail/open_companies:", e);
            showToast("Failed to save company detail: " + (e.message || JSON.stringify(e)), 'error');
        }
    }

    await saveMasterDB();
    closeModal('company-modal', true);
    renderCompaniesSettingsList();
    showToast(isNew ? 'Company created successfully' : 'Company settings updated successfully', 'success');
    
    if (currentCompany && currentCompany.id === co.id) {
        currentCompany = co;
        document.getElementById('company-topbar-name').innerText = co.name;
        document.getElementById('company-topbar-dot').style.backgroundColor = co.color;
        updateTabVisibility();
    }

    if (document.getElementById('company-select-overlay').classList.contains('open')) {
        showCompanySelection();
    }
}

function openUserModal(editId = null) {
    if (!checkPermission('manageUsers')) {
        showToast('Permission Denied', 'error');
        return;
    }
    document.getElementById('user-edit-id').value = editId || '';
    document.getElementById('user-username').readOnly = !!editId;
    if (document.getElementById('user-rules')) {
        document.getElementById('user-rules').value = '';
    }

    // Populate Department & Manager select options
    const deptSelect = document.getElementById('user-department');
    if (deptSelect) {
        deptSelect.innerHTML = '<option value="">-- None / No Department --</option>';
        (masterDB.departments || []).forEach(d => {
            const opt = document.createElement('option');
            opt.value = d.code;
            opt.textContent = `${d.name} (${d.code})`;
            deptSelect.appendChild(opt);
        });
    }

    const mgrSelect = document.getElementById('user-reporting-manager');
    if (mgrSelect) {
        mgrSelect.innerHTML = '<option value="">-- None / No Manager --</option>';
        (masterDB.users || [])
            .filter(u => u.username !== '__system_company_settings__' && u.id !== editId)
            .forEach(u => {
                const opt = document.createElement('option');
                opt.value = u.username;
                opt.textContent = u.displayName || u.username;
                mgrSelect.appendChild(opt);
            });
    }

    // Populate Allowed Departments checkboxes
    const allowedDeptContainer = document.getElementById('user-allowed-departments-list');
    if (allowedDeptContainer) {
        allowedDeptContainer.innerHTML = '';
        (masterDB.departments || []).forEach(d => {
            const label = document.createElement('label');
            label.style.display = 'flex';
            label.style.alignItems = 'center';
            label.style.gap = '8px';
            label.style.fontSize = '13.5px';
            label.style.color = 'var(--text-primary)';
            label.style.cursor = 'pointer';
            label.style.fontWeight = '500';
            
            const chk = document.createElement('input');
            chk.type = 'checkbox';
            chk.value = d.code;
            chk.className = 'user-allowed-dept-checkbox';
            chk.style.width = '16px';
            chk.style.height = '16px';
            chk.style.cursor = 'pointer';
            
            label.appendChild(chk);
            label.appendChild(document.createTextNode(`${d.name} (${d.code})`));
            allowedDeptContainer.appendChild(label);
        });
    }

    // Render company permissions container
    renderCompanyPermissionsUI(editId);

    const compPermContainer = document.getElementById('company-permissions-container');
    if (compPermContainer) {
        // Remove existing listener if any, or just add a new one
        if (!compPermContainer.dataset.listenerAdded) {
            compPermContainer.dataset.listenerAdded = 'true';
            compPermContainer.addEventListener('change', (e) => {
                if (e.target && e.target.classList.contains('co-perm-chk')) {
                    // Extract company id from the element's id or classes
                    // ID format: perm-${co.id}-${key}
                    const parts = e.target.id.split('-');
                    if (parts.length >= 3) {
                        const coId = parts[1];
                        const enabledEl = document.getElementById(`co-enabled-${coId}`);
                        if (e.target.checked && enabledEl && !enabledEl.checked) {
                            enabledEl.checked = true;
                            toggleCompanySection(coId);
                        }
                    }
                }
            });
        }
    }

    if (editId) {
        const u = masterDB.users.find(x => x.id === editId);
        if (!u) return;
        document.getElementById('user-modal-title').textContent = 'Edit User Access';
        document.getElementById('user-username').value = u.username;
        document.getElementById('user-password').value = u.password || '';
        document.getElementById('user-display-name').value = u.displayName || u.display_name || '';
        document.getElementById('user-email').value = u.email || '';
        document.getElementById('user-phone').value = u.phone || '';
        document.getElementById('user-role').value = u.role || '';
        document.getElementById('user-is-admin').checked = !!u.isSuperAdmin;

        if (deptSelect) deptSelect.value = u.department || '';
        if (mgrSelect) mgrSelect.value = u.reportingManager || '';

        // Populate allowed departments
        const allowedDepts = u.companyAccess?.__allowedDepartments || [];
        const chks = allowedDeptContainer?.querySelectorAll('.user-allowed-dept-checkbox') || [];
        chks.forEach(chk => {
            chk.checked = allowedDepts.includes(chk.value);
        });

        // Populate allowed employees
        if (document.getElementById('user-allowed-employees')) {
            document.getElementById('user-allowed-employees').value = u.companyAccess?.__allowedEmployees || '';
        }

        // Populate access rules
        if (document.getElementById('user-rules')) {
            document.getElementById('user-rules').value = u.rules || u.companyAccess?.__rules || '';
        }

        // Populate company permissions
        masterDB.companies.forEach(co => {
            const access = (u.companyAccess || {})[co.id] || {};
            const enabledEl = document.getElementById(`co-enabled-${co.id}`);
            const isAdminEl = document.getElementById(`co-isadmin-${co.id}`);
            if (enabledEl) enabledEl.checked = !!access.enabled;
            if (isAdminEl) isAdminEl.checked = !!access.isAdmin;
            if (access.permissions) {
                const perms = access.permissions;
                const permKeys = Object.keys(ALL_PERMS);
                permKeys.forEach(key => {
                    const el = document.getElementById(`perm-${co.id}-${key}`);
                    if (el) el.checked = !!perms[key];
                });
                const daysEl = document.getElementById(`perm-${co.id}-restrict_back_date_days`);
                if (daysEl) {
                    daysEl.value = perms['restrict_back_date_days'] || 0;
                }
                const container = document.querySelector(`.back-date-days-container-${co.id}`);
                if (container) {
                    container.style.display = perms['restrict_back_date'] ? 'inline-flex' : 'none';
                }
            }
            toggleCompanySection(co.id);
        });
    } else {
        document.getElementById('user-modal-title').textContent = 'Create User Account';
        document.getElementById('user-username').value = '';
        document.getElementById('user-password').value = '';
        document.getElementById('user-display-name').value = '';
        document.getElementById('user-email').value = '';
        document.getElementById('user-phone').value = '';
        document.getElementById('user-role').value = '';
        document.getElementById('user-is-admin').checked = false;
        if (deptSelect) deptSelect.value = '';
        if (mgrSelect) mgrSelect.value = '';

        const chks = allowedDeptContainer?.querySelectorAll('.user-allowed-dept-checkbox') || [];
        chks.forEach(chk => {
            chk.checked = false;
        });
        if (document.getElementById('user-allowed-employees')) {
            document.getElementById('user-allowed-employees').value = '';
        }
        masterDB.companies.forEach(co => {
            const dashChk = document.getElementById(`perm-${co.id}-module_dashboard`);
            if (dashChk) dashChk.checked = true;
            const daysEl = document.getElementById(`perm-${co.id}-restrict_back_date_days`);
            if (daysEl) daysEl.value = 0;
            const container = document.querySelector(`.back-date-days-container-${co.id}`);
            if (container) container.style.display = 'none';
        });
    }

    if (document.getElementById('user-employee-input')) {
        document.getElementById('user-employee-input').value = '';
    }
    if (window.updateUserEmployeesChips) {
        window.updateUserEmployeesChips();
    }

    window.userHasManuallyEditedUsername = false;
    toggleAdminPermissions();
    openModal('user-modal');
}

window.onUserDisplayNameInput = function() {
    const editId = document.getElementById('user-edit-id').value;
    if (editId) return; // Only suggest username for NEW users
    
    if (window.userHasManuallyEditedUsername) return; // Don't override manual edits
    
    const displayName = document.getElementById('user-display-name').value;
    const usernameInput = document.getElementById('user-username');
    if (usernameInput) {
        // Clean display name to generate username: lowercase, replace spaces with dot, remove special characters
        const suggested = displayName
            .trim()
            .toLowerCase()
            .replace(/\s+/g, '.')
            .replace(/[^a-z0-9._-]/g, '');
        usernameInput.value = suggested;
    }
};

window.onUserUsernameInput = function() {
    window.userHasManuallyEditedUsername = true;
};

