function switchModuleTab(tab) {
    currentModuleTab = tab;
    currentView = tab;

    document.querySelectorAll('.module-tab').forEach(t => t.classList.remove('active'));
    document.querySelectorAll('.module-container').forEach(c => c.classList.remove('active'));

    const tabEl = document.getElementById('mtab-' + tab);
    if (tabEl) tabEl.classList.add('active');
    const containerEl = document.getElementById('module-' + tab);
    if (containerEl) containerEl.classList.add('active');

    const titles = {
        dashboard: 'Dashboard', 
        masters: 'Masters', 
        transactions: 'Transactions',
        production: 'Production',
        inventory: 'Inventory',
        reports: 'Reports', 
        utilities: 'Utilities'
    };
    document.getElementById('pageTitle').textContent = titles[tab] || (tab.charAt(0).toUpperCase() + tab.slice(1));

    if (tab === 'dashboard') renderDashboard();
    if (tab === 'masters') window.showMastersDashboard();
    if (tab === 'transactions') window.showTransactionsDashboard();
    if (tab === 'production') window.showProductionDashboard();
    if (tab === 'inventory') window.showInventoryDashboard();
    if (tab === 'costing') window.showCostingDashboard();
    if (tab === 'freight') window.openFreightTab('dashboard');
    if (tab === 'reports') window.showReportsDashboard();
    if (tab === 'admin') switchUserMgmtTab(currentUserMgmtTab);
    if (tab === 'utilities') window.showUtilitiesDashboard();
    
    if (window.enforcePricingPrivacy) window.enforcePricingPrivacy();
    if (window.syncModuleIconSizes) window.syncModuleIconSizes();
}
