                description: cleanDesc,
                salesAccount: item.salesAccount || item.sales_account || '',
                purchaseAccount: item.purchaseAccount || item.purchase_account || '',
                hasAlt: hasAltStr,
                altUnit: item.altUnit || item.alt_unit || '',
                conversionFactor: item.conversionFactor !== undefined ? item.conversionFactor : (item.conversion_factor || 0),
                conversionType: item.conversionType || item.conversion_type || 'multiply',
                openingStockQty: item.openingStockQty !== undefined ? item.openingStockQty : (item.opening_stock || 0),
                hasThresh: hasThreshStr,
                minLevel: item.minLevel !== undefined ? item.minLevel : (item.min_level || 0),
                minLeadDays: item.minLeadDays !== undefined ? item.minLeadDays : (item.min_days || item.minLeadDays || 0),
                reorderLevel: item.reorderLevel !== undefined ? item.reorderLevel : (item.reorder || 0),
                procurementDays: item.procurementDays !== undefined ? item.procurementDays : (item.reorder_days || item.procurementDays || 0),
                maxLevel: item.maxLevel !== undefined ? item.maxLevel : (item.max_level || 0),
                overstockDays: item.overstockDays !== undefined ? item.overstockDays : (item.max_days || item.overstockDays || 0),
                status: item.status || 'Active',

                'Code': item.code || '',
                'Item Name': item.name || '',
                'Category': item.category || '',
                'Base Unit': item.unit || item.base_unit || '',
                'Tax Category': taxCategoryStr,
                'Busy Tax Category': busyTaxCategoryStr,
                'HSN Code': item.hsn || '',
                'Description': cleanDesc,
                'Sales Account': item.salesAccount || item.sales_account || '',
                'Purchase Account': item.purchaseAccount || item.purchase_account || '',
                'Has Alternate Unit': hasAltStr,
                'Alternate Unit': item.altUnit || item.alt_unit || '',
                'Conversion Factor': item.conversionFactor !== undefined ? item.conversionFactor : (item.conversion_factor || 0),
                'Conversion Type': item.conversionType || item.conversion_type || 'multiply',
                'Opening Stock Qty': item.openingStockQty !== undefined ? item.openingStockQty : (item.opening_stock || 0),
                'Has Critical Thresholds': hasThreshStr,
