                'Min Safety Lead Time (Days)': item.minLeadDays !== undefined ? item.minLeadDays : (item.min_days || item.minLeadDays || 0),
                'Reorder Level (Qty)': item.reorderLevel !== undefined ? item.reorderLevel : (item.reorder || 0),
                'Procurement Turnaround (Days)': item.procurementDays !== undefined ? item.procurementDays : (item.reorder_days || item.procurementDays || 0),
                'Max Level (Qty)': item.maxLevel !== undefined ? item.maxLevel : (item.max_level || 0),
