window.buildOutwardExportRows = function(outwardList, seriesType) {
    db.pos = db.pos || [];
    db.grns = db.grns || [];
    db.customers = db.customers || [];
    db.vendors = db.vendors || [];

    const filtered = (outwardList || []).filter(o => {
        const state = typeof parseOutwardWizardState === 'function' ? parseOutwardWizardState(o) : {};
        if (seriesType === 'outward_c_pf') return state.type === 'fabric_issue_challan' && state.source === 'customer' && state.subType === 'plain';
        if (seriesType === 'outward_c_em') return state.type === 'fabric_issue_challan' && state.source === 'customer' && state.subType === 'embroidered';
        if (seriesType === 'outward_v_pf') return state.type === 'fabric_issue_challan' && state.source === 'vendor' && state.subType === 'plain';
        if (seriesType === 'outward_v_em') return state.type === 'fabric_issue_challan' && state.source === 'vendor' && state.subType === 'embroidered';
        if (seriesType === 'outward_inh') return state.type === 'inhouse';
        if (seriesType === 'outward_jw') return state.type === 'jobworker';
        return true;
    });

    let prefix = 'JW';
    if (seriesType === 'outward_c_pf') prefix = 'FI/C/PF';
    else if (seriesType === 'outward_c_em') prefix = 'FI/C/EM';
    else if (seriesType === 'outward_v_pf') prefix = 'FI/V/PF';
    else if (seriesType === 'outward_v_em') prefix = 'FI/V/EM';
    else if (seriesType === 'outward_inh') prefix = 'FI/INH';
    else if (seriesType === 'outward_jw') prefix = 'FI/JW';

    filtered.sort((a, b) => {
        const numA = typeof getBaseNumberFromOutward === 'function' ? (getBaseNumberFromOutward(a.number, prefix) || 0) : (parseInt(String(a.number || '').split('/').pop()) || 0);
        const numB = typeof getBaseNumberFromOutward === 'function' ? (getBaseNumberFromOutward(b.number, prefix) || 0) : (parseInt(String(b.number || '').split('/').pop()) || 0);
        if (numA !== numB) return numA - numB;
        return String(a.number || '').localeCompare(String(b.number || ''));
    });

    return filtered.map(o => {
        let poNum = o.poNumber || o.poNo || o.linked_po_number || '';
        if (!poNum) {
            const poId = o.poRefId || o.po_ref_id || o.linked_po_id;
            if (poId) {
                const foundPo = db.pos.find(p => p.id === poId || p.number === poId);
                if (foundPo) poNum = foundPo.number;
                else if (typeof poId === 'string' && (poId.includes('/') || poId.includes('-'))) poNum = poId;
            }
        }
        if (!poNum || poNum === '-') poNum = '-';

        let grnNum = o.grnNo || o.grnNumber || o.linked_grn_number || '';
        if (!grnNum && o.grnRefId) {
            const foundGrn = db.grns.find(g => g.id === o.grnRefId || g.grnNo === o.grnRefId || g.number === o.grnRefId);
            if (foundGrn) grnNum = foundGrn.grnNo || foundGrn.number;
            else if (typeof o.grnRefId === 'string' && (o.grnRefId.includes('/') || o.grnRefId.includes('-'))) grnNum = o.grnRefId;
        }
        if (!grnNum && o.grnLinks && Array.isArray(o.grnLinks) && o.grnLinks.length > 0) {
            const grnNums = o.grnLinks.map(l => {
                const gid = typeof l === 'object' ? (l.grnRefId || l.id) : l;
                const foundG = db.grns.find(g => g.id === gid || g.grnNo === gid || g.number === gid);
                return foundG ? (foundG.grnNo || foundG.number) : (typeof gid === 'string' && gid.includes('/') ? gid : null);
            }).filter(Boolean);
            if (grnNums.length > 0) grnNum = [...new Set(grnNums)].join(', ');
        }
        if (!grnNum || grnNum === '-') grnNum = '-';

        const partyName = window.getOutwardPartyName ? window.getOutwardPartyName(o) : (o.vendorName || o.partyName || '-');
        let customerName = o.customerName || o.customer_name || '';
        if (!customerName && o.customerId) {
            const custObj = (db.customers || []).find(c => c.id === o.customerId);
            if (custObj) customerName = custObj.name;
        }
        if (!customerName) customerName = '-';

        const itemName = window.getOutwardItemName ? window.getOutwardItemName(o) : (o.itemName || '-');
        const fabricName = window.getOutwardFabricName ? window.getOutwardFabricName(o) : (o.fabricType || '-');

        const wizard = typeof parseOutwardWizardState === 'function' ? parseOutwardWizardState(o) : {};
        let seriesLabel = 'Fabric Issue';
        if (wizard.type === 'inhouse') seriesLabel = 'In House (FI/INH)';
        else if (wizard.type === 'jobworker') seriesLabel = 'Job Worker (FI/JW)';
        else if (wizard.source === 'customer') seriesLabel = wizard.subType === 'plain' ? 'Cust Plain (FI/C/PF)' : 'Cust Emb (FI/C/EM)';
        else if (wizard.source === 'vendor') seriesLabel = wizard.subType === 'plain' ? 'Vend Plain (FI/V/PF)' : 'Vend Emb (FI/V/EM)';

        const docNum = window.formatStandardDocNumber ? window.formatStandardDocNumber(o.number || o.challanNo) : (o.number || '-');
        const dateVal = o.date ? (typeof formatDate === 'function' ? formatDate(o.date) : o.date) : '-';
        const itemFabCombined = (itemName && itemName !== '-') ? itemName : fabricName;

        return {
            'Challan Number': docNum,
            'Date': dateVal,
            'Series Type': seriesLabel,
            'Vendor / Job Worker': partyName,
            'Customer Name': customerName,
            'Linked PO': poNum,
            'Item / Design Name': itemName,
            'Fabric Quality': fabricName,
            'Item / Fabric Name': itemFabCombined,
            'Linked GRN': grnNum,
            'Meters Issued': parseFloat(o.qty || o.consumableQty || 0),
            'Vehicle No': o.vehicleNo || o.taxiName || '-',
            'Status': o.status || 'Active',
            'Remarks': typeof cleanRemarks === 'function' ? cleanRemarks(o.remarks) : (o.remarks || ''),

            number: docNum,
            date: dateVal,
            vendorName: partyName,
            customerName: customerName,
            poNumber: poNum,
            itemName: itemFabCombined,
            fabricType: fabricName,
            designNumber: itemName,
            grnNo: grnNum,
            qty: parseFloat(o.qty || o.consumableQty || 0),
            vehicleNo: o.vehicleNo || o.taxiName || '-',
            status: o.status || 'Active',
            remarks: typeof cleanRemarks === 'function' ? cleanRemarks(o.remarks) : (o.remarks || '')
        };
    });
};

