function exportToCSV(headers, data, filename) {
    if (window.allowExportReports && !window.allowExportReports()) {
        showToast('Export of reports is disabled for your user account. Please contact your administrator.', 'error');
        return;
    }
    const targetFilename = filename.toLowerCase().endsWith('.xlsx') ? filename : filename.replace(/\.csv$/i, '.xlsx');

    if (typeof XLSX !== 'undefined') {
        const rows = data.map(row => {
            const rowObj = {};
            headers.forEach(h => {
                let val = row[h] !== undefined && row[h] !== null ? row[h] : (row[h.toLowerCase()] !== undefined ? row[h.toLowerCase()] : '');
                if (h && h.toLowerCase() === 'remarks') val = typeof cleanRemarks === 'function' ? cleanRemarks(val) : val;
                
                const isDateHeader = h && (h.toLowerCase().includes('date') || h.toLowerCase() === 'dt');
                if (isDateHeader && val && val !== '-') {
                    val = formatDate(val);
                }
                
                rowObj[h] = val;
            });
            return rowObj;
        });

        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.json_to_sheet(rows, { header: headers, cellDates: false, raw: true });

        // Post-process date columns to ensure text string 's' format with DD/MM/YYYY
        Object.keys(ws).forEach(cellKey => {
            if (cellKey.startsWith('!')) return;
            const cell = ws[cellKey];
            if (cell && cell.v !== undefined && cell.v !== null) {
                const colLetter = cellKey.replace(/\d+/g, '');
                const headerCell = ws[`${colLetter}1`];
                const headerStr = headerCell && headerCell.v ? String(headerCell.v).toLowerCase().trim() : '';
                const isDateHeader = headerStr.includes('date') || headerStr === 'dt' || headerStr.includes('day') || headerStr.includes('dated');
                const valStr = String(cell.v).trim();
                const isIsoDate = /^\d{4}[-\/]\d{1,2}[-\/]\d{1,2}/.test(valStr) || /^\d{1,2}[-\/]\d{1,2}[-\/]\d{4}/.test(valStr);

                if (isDateHeader || isIsoDate) {
                    const formatted = formatDate(valStr);
                    if (formatted && formatted !== '-') {
                        cell.t = 's';
                        cell.v = formatted;
                        delete cell.z;
                        delete cell.w;
                    }
                }
            }
        });

        const colWidths = headers.map(h => {
            let maxLen = String(h).length;
            rows.forEach(r => {
                const valStr = String(r[h] || '');
                if (valStr.length > maxLen) maxLen = valStr.length;
            });
            return { wch: Math.min(Math.max(maxLen + 3, 12), 55) };
        });
        ws['!cols'] = colWidths;

        XLSX.utils.book_append_sheet(wb, ws, "Sheet1");
        XLSX.writeFile(wb, targetFilename);
        showToast('Export successful (.xlsx)', 'success');
        return;
    }

    let csv = headers.join(',') + '\n';
    data.forEach(row => {
        csv += headers.map(header => {
            let val = row[header] !== undefined && row[header] !== null ? row[header] : (row[header.toLowerCase()] !== undefined ? row[header.toLowerCase()] : '');
            if (header && header.toLowerCase() === 'remarks') {
                val = typeof cleanRemarks === 'function' ? cleanRemarks(val) : val;
            }
            const isDateHeader = header && (header.toLowerCase().includes('date') || header.toLowerCase() === 'dt' || header.toLowerCase().includes('day') || header.toLowerCase().includes('dated'));
            const isIsoDate = /^\d{4}[-\/]\d{1,2}[-\/]\d{1,2}/.test(String(val).trim()) || /^\d{1,2}[-\/]\d{1,2}[-\/]\d{4}/.test(String(val).trim());
            if ((isDateHeader || isIsoDate) && val && val !== '-') {
                val = formatDate(val);
            }
            return `"${val.toString().replace(/"/g, '""')}"`;
        }).join(',') + '\n';
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = targetFilename.replace(/\.xlsx$/i, '.csv');
    a.click();
    showToast('Export successful', 'success');
}

function masterImport() {
    const activeSubModal = document.getElementById(`masters-submodal-${currentMasterSubtab}`);
    const input = activeSubModal ? activeSubModal.querySelector('#master-import-input') : document.getElementById('master-import-input');
    if (input) input.click();
}

async function masterImportFile(event) {
    const sub = currentMasterSubtab;
    const file = event.target.files[0];
    if (!file) return;
    event.target.value = '';

    const reader = new FileReader();
    const fileName = file.name.toLowerCase();

    reader.onload = async function(e) {
        showImportLoadingOverlay();
        try {
            let rows = [];
            if (fileName.endsWith('.csv')) {
                const text = e.target.result;
                rows = parseCSV(text);
            } else if (fileName.endsWith('.xlsx') || fileName.endsWith('.xls')) {
                if (typeof XLSX === 'undefined') {
                    showToast('Excel library not loaded.', 'error');
                    hideImportLoadingOverlay();
                    return;
                }
                                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                const sheetName = workbook.SheetNames[0] === 'READ FIRST' && workbook.SheetNames[1] ? workbook.SheetNames[1] : workbook.SheetNames[0];
                const worksheet = workbook.Sheets[sheetName];
                rows = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: "" });
            } else {
                showToast('Unsupported file format.', 'error');
                hideImportLoadingOverlay();
                return;
            }

            if (rows.length < 2) {
                showToast('No data rows found', 'error');
                hideImportLoadingOverlay();
                return;
            }

            const headers = rows[0].map(h => h ? h.toString().trim() : '');
            const records = [];
            for (let i = 1; i < rows.length; i++) {
                const row = rows[i];
                if (!row || row.every(c => c === null || c === undefined || c === "")) continue;
                const rec = {};
                headers.forEach((h, colIdx) => {
                    if (h) rec[h] = row[colIdx] !== undefined ? row[colIdx] : '';
                });
                records.push(rec);
            }

            await saveImportedMasters(sub, records);
        } catch (err) {
            console.error(err);
            showToast('Import failed: ' + err.message, 'error');
            hideImportLoadingOverlay();
        }
    };

    if (fileName.endsWith('.csv')) {
        reader.readAsText(file);
    } else {
        reader.readAsArrayBuffer(file);
    }
}

