            if (!name) continue;
            const code = (rec.code || rec.Code || rec['Item Code'] || rec['Design Number'] || ('ITM-' + Math.floor(100+Math.random()*900))).toString().trim();
            
            // Validate category, unit, and HSN against masters - skip specific field values (put '-') if not found
            let itemWarnings = [];
            let categoryVal = (rec.category || rec.Category || rec['Item Group / Category'] || rec.group || rec.Group || '').toString().trim();
            if (categoryVal) {
                const categoryExists = (db.itemGroups || []).some(g => g.name.toLowerCase() === categoryVal.toLowerCase());
                if (!categoryExists) {
                    itemWarnings.push(`Category "${categoryVal}" not found (replaced with "-")`);
                    categoryVal = '-';
                }
            } else {
                categoryVal = '-';
            }

            let unitVal = (rec.unit || rec.Unit || rec['Base Unit'] || '').toString().trim();
            if (unitVal) {
                const unitExists = (db.units || []).some(u => (u.symbol || '').toLowerCase() === unitVal.toLowerCase() || (u.name || '').toLowerCase() === unitVal.toLowerCase());
                if (!unitExists) {
                    itemWarnings.push(`Base Unit "${unitVal}" not found (replaced with "-")`);
                    unitVal = '-';
                }
            } else {
                unitVal = '-';
            }

            let hsnVal = (rec.hsn || rec.Hsn || rec['HSN Code'] || rec['HSN/Tax'] || '').toString().trim();
            if (hsnVal) {
                const hsnExists = (db.hsnCodes || []).some(h => (h.code || '').toLowerCase() === hsnVal.toLowerCase());
                if (!hsnExists) {
                    itemWarnings.push(`HSN Code "${hsnVal}" not found (replaced with "-")`);
                    hsnVal = '-';
                }
            } else {
                hsnVal = '-';
            }

            if (itemWarnings.length > 0) {
                errorLogs.push(`Row ${records.indexOf(rec) + 2} (${name}): ` + itemWarnings.join(', '));
            }

            const existing = db.items.find(x => x.code.toLowerCase() === code.toLowerCase() || x.name.toLowerCase() === name.toLowerCase());
