function exportHSNCSV() {
    db.hsnCodes = db.hsnCodes || [];
    let csv = 'HSN Code,Description,Tax Category,CGST%,SGST%,IGST%\n';
    db.hsnCodes.forEach(h => {
        csv += `"${h.code}","${h.description}","${h.taxCategory}","${h.cgst}","${h.sgst}","${h.igst}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = 'hsn_master.csv'; a.click();
    showToast('HSN codes exported', 'success');
}

function exportItemGroupsCSV() {
    db.itemGroups = db.itemGroups || [];
    db.hsnCodes = db.hsnCodes || [];
    let csv = 'Group Name,Primary Group,Under Group,HSN Code,CGST%,SGST%,IGST%\n';
    db.itemGroups.forEach(g => {
        let parentName = '-';
        if (!g.isPrimary && g.underGroupId) {
            const p = db.itemGroups.find(x => x.id === g.underGroupId);
            parentName = p ? p.name : '-';
        }
        let hsnCode = '-';
        let cgst = '-';
        let sgst = '-';
        let igst = '-';
        if (g.specifyHsn && g.hsnId) {
            const h = db.hsnCodes.find(x => x.id === g.hsnId);
            if (h) {
                hsnCode = h.code;
                cgst = h.cgst !== undefined ? h.cgst + '%' : '-';
                sgst = h.sgst !== undefined ? h.sgst + '%' : '-';
                igst = h.igst !== undefined ? h.igst + '%' : '-';
            }
        }
        csv += `"${g.name}","${g.isPrimary ? 'Y' : 'N'}","${parentName}","${hsnCode}","${cgst}","${sgst}","${igst}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a'); a.href = url; a.download = 'item_groups_master.csv'; a.click();
    showToast('Item groups exported', 'success');
}

// Sales / GRN / Production sub-tab switchers
function switchSalesSubtab(sub) {
    ['so','pur','purinv'].forEach(s => {
        const el = document.getElementById('sales-view-' + s);
        const btn = document.getElementById('stab-' + s);
        if (el) el.classList.toggle('active', s === sub);
        if (btn) {
            if (s === sub) { btn.classList.add('btn-add'); btn.classList.remove('action-btn'); btn.classList.add('action-btn'); }
            else { btn.style.background = ''; btn.style.color = ''; btn.style.borderColor = ''; }
        }
    });
    const activeBtn = document.getElementById('stab-' + sub);
    if (activeBtn) { activeBtn.style.background='linear-gradient(135deg,var(--accent-blue),var(--accent-purple))'; activeBtn.style.color='white'; activeBtn.style.borderColor='transparent'; }
    ['so','pur','purinv'].filter(s=>s!==sub).forEach(s => {
        const btn = document.getElementById('stab-' + s);
        if (btn) { btn.style.background=''; btn.style.color=''; btn.style.borderColor=''; }
    });
    ['so','pur','purinv'].forEach(s => {
        const el = document.getElementById('sales-view-' + s);
        if (el) el.style.display = s === sub ? 'block' : 'none';
    });
    if (sub === 'so') renderSalesOrderTable();
    if (sub === 'pur') { populatePurchaseDropdowns(); renderPurchaseTable(); }
    if (sub === 'purinv') renderPurchaseInventoryTable();
}

function switchGrnSubtab(sub) {
    ['grn','inv'].forEach(s => {
        const el = document.getElementById('grn-view-' + s);
        const btn = document.getElementById('gtab-' + s);
        if (el) el.style.display = s === sub ? 'block' : 'none';
        if (btn) {
            if (s === sub) { btn.style.background='linear-gradient(135deg,var(--accent-blue),var(--accent-purple))'; btn.style.color='white'; btn.style.borderColor='transparent'; }
            else { btn.style.background=''; btn.style.color=''; btn.style.borderColor=''; }
        }
    });
    if (sub === 'grn') renderGRNTable();
    if (sub === 'inv') renderInventoryTable();
}

function switchProdSubtab(sub, isRefresh = false) {
    currentProdSubtab = sub;
    const activeSubModal = document.getElementById(`production-submodal-${sub}`);
    const isOpen = activeSubModal && activeSubModal.classList.contains('open');
    const isMinimized = activeSubModal && activeSubModal.classList.contains('minimized');
    
    const grid = document.getElementById('production-dashboard-grid');
    if (grid) {
        if (!isOpen || isMinimized) {
            grid.style.setProperty('display', 'block', 'important');
        } else {
            grid.style.setProperty('display', 'none', 'important');
        }
    }
    
    ['logs','plan','sampling','sampplan','requisition','finishing','semifinished'].forEach(s => {
        const el = document.getElementById('prod-view-' + s);
        const btn = document.getElementById('pstab-' + s);
        if (el) el.style.display = s === sub ? 'block' : 'none';
        if (btn) {
            if (s === sub) { 
                btn.style.background='linear-gradient(135deg,var(--accent-blue),var(--accent-purple))'; 
                btn.style.color='white'; 
                btn.style.borderColor='transparent'; 
            }
            else { 
                btn.style.background=''; 
                btn.style.color=''; 
                btn.style.borderColor=''; 
            }
        }
    });
    if (sub === 'logs') {
        renderProductionLogsTable();
        if (typeof renderProductionTable === 'function') renderProductionTable();
    }
    if (sub === 'sampling') {
        if (typeof renderSamplingTable === 'function') renderSamplingTable();
    }
    if (sub === 'requisition') {
        if (!isRefresh && typeof window.showReqWizardStep === 'function') {
            window.showReqWizardStep(1);
        } else {
            renderRequisitionTable();
        }
    }
    if (sub === 'plan') {
        const activeNestedBtn = document.querySelector('#prod-view-plan .nested-tab-bar .action-btn.active');
        const activeNested = activeNestedBtn ? activeNestedBtn.id.replace('pptab-', '') : 'docs';
        window.switchProdPlanSubtab(activeNested);
    }
    if (sub === 'sampplan') {
        const activeNestedBtn = document.querySelector('#prod-view-sampplan .nested-tab-bar .action-btn.active');
        const activeNested = activeNestedBtn ? activeNestedBtn.id.replace('spptab-', '') : 'docs';
        window.switchSampPlanSubtab(activeNested);
    }
    if (sub === 'finishing') {
        if (typeof renderFinishingTable === 'function') renderFinishingTable();
    }
    if (sub === 'semifinished') {
        if (typeof window.renderSemiFinishedTable === 'function') window.renderSemiFinishedTable();
    }
}

window.switchSampPlanSubtab = function(sub) {
    ['docs', 'expected'].forEach(s => {
        const el = document.getElementById('samp-plan-view-' + s);
        const btn = document.getElementById('spptab-' + s);
        if (el) el.style.display = s === sub ? 'block' : 'none';
        if (btn) {
            if (s === sub) {
                btn.style.background = 'linear-gradient(135deg,var(--accent-blue),var(--accent-purple))';
                btn.style.color = 'white';
                btn.style.borderColor = 'transparent';
                btn.classList.add('active');
            } else {
                btn.style.background = '';
                btn.style.color = '';
                btn.style.borderColor = '';
                btn.classList.remove('active');
            }
        }
    });
    if (sub === 'docs') renderSamplingPlanTable();
    if (sub === 'expected') window.renderExpectedSamplingTable();
};

// backward compat for navigateTo used elsewhere
function navigateTo(view) {
    const moduleMap = {
        dashboard: 'dashboard', 'sales-orders': 'sales', grn: 'grn',
        'fabric-issue': 'production', production: 'production', designs: 'admin',
        inventory: 'grn', reports: 'reports', customers: 'masters', vendors: 'masters',
        transporters: 'masters', units: 'masters', items: 'masters',
        purchases: 'sales', 'purchase-inventory': 'sales', 'user-management': 'admin'
    };
    const tab = moduleMap[view] || 'masters';
    switchModuleTab(tab);
    if (tab === 'masters') {
        const subMap = { customers:'customers', vendors:'vendors', transporters:'transporters', units:'units', items:'items' };
        if (subMap[view]) switchMasterSubtab(subMap[view]);
    }
    if (tab === 'sales') {
        if (view === 'purchases') switchSalesSubtab('pur');
        if (view === 'purchase-inventory') switchSalesSubtab('purinv');
    }
    if (tab === 'production') {
        if (view === 'production') switchProdSubtab('prod');
    }
}

