window.getSidebarConfig = function() {
    let cfg = localStorage.getItem('sidebar_preferences');
    if (cfg) {
        try {
            return JSON.parse(cfg);
        } catch(e) {}
    }
    return {
        iconsOnly: false,
        visibleIds: ALL_SHORTCUT_ITEMS.map(item => item.id)
    };
};

window.saveSidebarConfig = function(config) {
    localStorage.setItem('sidebar_preferences', JSON.stringify(config));
    window.refreshAllModalSidebars();
};

window.initModalSidebars = function() {
    const modalIds = [
        'bom-modal', 'outward-modal', 'production-modal', 'requisition-modal',
        'generic-tx-modal', 'grn-modal', 'po-modal', 'design-modal',
        'so-modal', 'cust-modal', 'vend-modal', 'item-modal'
    ];
    
    const config = window.getSidebarConfig();

    modalIds.forEach(id => {
        const overlay = document.getElementById(id);
        if (!overlay) return;
        const modal = overlay.querySelector('.modal');
        if (!modal) return;

        // Apply flex styles to modal
        modal.style.display = 'flex';
        modal.style.flexDirection = 'column';
        modal.style.overflow = 'hidden';
        
        // Ensure standard modals have enough width to fit sidebar + forms beautifully
        if (!modal.classList.contains('modal-large') && !modal.classList.contains('modal-full')) {
            modal.style.maxWidth = '780px';
            modal.style.width = '780px';
        } else if (modal.classList.contains('modal-large') && !modal.classList.contains('modal-full')) {
            modal.style.maxWidth = '940px';
            modal.style.width = '940px';
        }

        const header = modal.querySelector('.modal-header');
        const body = modal.querySelector('.modal-body');
        const footer = modal.querySelector('.modal-footer');

        // Create or find the flex container
        let flexContainer = modal.querySelector('.modal-flex-container');
        let sidebar = modal.querySelector('.modal-entry-sidebar');
        let rightContent = modal.querySelector('.modal-right-content');

        if (!flexContainer) {
            flexContainer = document.createElement('div');
            flexContainer.className = 'modal-flex-container';
            flexContainer.style.display = 'flex';
            flexContainer.style.flexDirection = 'row';
            flexContainer.style.alignItems = 'stretch';
            flexContainer.style.overflow = 'hidden';
            flexContainer.style.flex = '1';
            flexContainer.style.width = '100%';

            rightContent = document.createElement('div');
            rightContent.className = 'modal-right-content';
            rightContent.style.flex = '1';
            rightContent.style.display = 'flex';
            rightContent.style.flexDirection = 'column';
            rightContent.style.overflowY = 'auto';

            sidebar = document.createElement('div');
            sidebar.className = 'modal-entry-sidebar';

            if (body) rightContent.appendChild(body);
            if (footer) rightContent.appendChild(footer);

            flexContainer.appendChild(sidebar);
            flexContainer.appendChild(rightContent);
            modal.appendChild(flexContainer);
        }

        // Apply Icons Only Mode class
        if (config.iconsOnly) {
            sidebar.classList.add('icons-only');
        } else {
            sidebar.classList.remove('icons-only');
        }

        // Build sidebar content dynamically based on visibility config
        let mastersHtml = '';
        let txHtml = '';

        ALL_SHORTCUT_ITEMS.forEach(item => {
            if (!config.visibleIds.includes(item.id)) return;

            const onclick = item.target 
                ? `window.openShortcutModal('${item.target}', '${item.type}')` 
                : `window.openShortcutModal('${item.id}')`;

            const btnHtml = `
                <button class="po-sidebar-tab" onclick="${onclick}" title="${item.text}">
                    <span class="tab-icon">${item.icon}</span>
                    <span class="tab-text">${item.text}</span>
                </button>
            `;

            if (item.group === 'masters') {
                mastersHtml += btnHtml;
            } else {
                txHtml += btnHtml;
            }
        });

        let sidebarHtml = '';
        if (mastersHtml) {
            sidebarHtml += `
                <h4 style="margin: 0 0 5px 0; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; opacity: 0.6; color: var(--text-muted, #8b9cc8);">Masters</h4>
                ${mastersHtml}
            `;
        }
        if (txHtml) {
            sidebarHtml += `
                <h4 style="margin: 15px 0 5px 0; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; opacity: 0.6; color: var(--text-muted, #8b9cc8);">Transactions</h4>
                ${txHtml}
            `;
        }

        // Add Customize button at the bottom
        sidebarHtml += `
            <div style="margin-top: auto; padding-top: 15px; border-top: 1px solid var(--border, rgba(255,255,255,0.08));">
                <button class="po-sidebar-tab" onclick="window.openCustomizeSidebarModal()" title="Customize Shortcuts" style="color: var(--accent-orange, #f59e0b);">
                    <span class="tab-icon">�</span>
                    <span class="tab-text" style="font-weight: 600;">Customize</span>
                </button>
            </div>
        `;

        sidebar.innerHTML = sidebarHtml;
    });
};

window.openShortcutModal = function(id, type = null) {
    if (id === 'generic-tx-modal' && type) {
        const select = document.getElementById('gtx-type');
        if (select) {
            select.value = type;
            select.dispatchEvent(new Event('change'));
        }
        openModal(id);
    } else if (id === 'po-modal' && type) {
        window.currentPoWizardType = type;
        if (typeof openPOModal === 'function') openPOModal();
    } else if (id === 'grn-modal' && type) {
        if (type === 'fabric-customer-plain') {
            grnWizardState.type = 'fabric';
            grnWizardState.source = 'customer';
            grnWizardState.subType = 'plain';
        } else if (type === 'fabric-customer-embroidered') {
            grnWizardState.type = 'fabric';
            grnWizardState.source = 'customer';
            grnWizardState.subType = 'embroidered';
        } else if (type === 'fabric-vendor-plain') {
            grnWizardState.type = 'fabric';
            grnWizardState.source = 'vendor';
            grnWizardState.subType = 'plain';
        } else if (type === 'fabric-vendor-embroidered') {
            grnWizardState.type = 'fabric';
            grnWizardState.source = 'vendor';
            grnWizardState.subType = 'embroidered';
        } else if (type === 'consumable') {
            grnWizardState.type = 'consumable';
            grnWizardState.source = 'vendor';
            grnWizardState.subType = null;
        }
        if (typeof openGRNModal === 'function') openGRNModal();
    } else if (id === 'outward-modal' && type) {
        if (type === 'customer-plain') {
            outwardWizardState.type = 'fabric_issue_challan';
            outwardWizardState.source = 'customer';
            outwardWizardState.subType = 'plain';
        } else if (type === 'customer-embroidered') {
            outwardWizardState.type = 'fabric_issue_challan';
            outwardWizardState.source = 'customer';
            outwardWizardState.subType = 'embroidered';
        } else if (type === 'vendor-plain') {
            outwardWizardState.type = 'fabric_issue_challan';
            outwardWizardState.source = 'vendor';
            outwardWizardState.subType = 'plain';
        } else if (type === 'vendor-embroidered') {
            outwardWizardState.type = 'fabric_issue_challan';
            outwardWizardState.source = 'vendor';
            outwardWizardState.subType = 'embroidered';
        } else if (type === 'inhouse') {
            outwardWizardState.type = 'inhouse';
            outwardWizardState.source = null;
            outwardWizardState.subType = null;
        } else if (type === 'jobworker') {
            outwardWizardState.type = 'jobworker';
            outwardWizardState.source = null;
            outwardWizardState.subType = null;
        }
        if (typeof openOutwardModal === 'function') openOutwardModal();
    } else {
        // Open the appropriate modal based on its ID
        if (id === 'cust-modal' && typeof openCustomerModal === 'function') {
            openCustomerModal();
        } else if (id === 'vend-modal' && typeof openVendorModal === 'function') {
            openVendorModal();
        } else if (id === 'item-modal' && typeof openItemModal === 'function') {
            openItemModal();
        } else if (id === 'design-modal' && typeof openDesignModal === 'function') {
            openDesignModal();
        } else if (id === 'bom-modal' && typeof openBOMModal === 'function') {
            openBOMModal();
        } else if (id === 'so-modal' && typeof openSOModal === 'function') {
            openSOModal();
        } else if (id === 'production-modal' && typeof openProductionModal === 'function') {
            openProductionModal();
        } else if (id === 'requisition-modal' && typeof openRequisitionModal === 'function') {
            openRequisitionModal();
        } else {
            openModal(id);
        }
    }
};

window.refreshAllModalSidebars = function() {
    window.initModalSidebars();
    document.querySelectorAll('.modal-overlay.open').forEach(el => {
        if (typeof window.updateModalSidebarActiveTab === 'function') {
            let typeVal = null;
            if (el.id === 'generic-tx-modal') {
                typeVal = document.getElementById('gtx-type').value;
            }
            window.updateModalSidebarActiveTab(el.id, typeVal);
        }
    });
};

