// ===== SALES ORDER FUNCTIONS =====
function getNextSONumber() {
    const fySuffix = (financialYears[currentFinancialYear] || {}).suffix || '/26-27';
    const cleanSuffix = fySuffix.startsWith('/') ? fySuffix.substring(1) : fySuffix;
    const numbers = [];
    (rawDB.salesOrders || []).forEach(so => {
        const num = so.number || '';
        const m1 = num.match(/^SO\/([\d]+)\//);            // e.g. SO/122/26-27
        const m2 = num.match(/^SO\/[^/]+\/([\d]+)$/);      // e.g. SO/26-27/122
        const seq = m1 ? parseInt(m1[1]) : (m2 ? parseInt(m2[1]) : 0);
        if (seq > 0) numbers.push(seq);
    });
    let next = 1;
    while (numbers.includes(next)) {
        next++;
    }
    return getDocumentNumber('SO', next);
}



