function renderSalesOrderTable() {
    const search = (document.getElementById('so-search')?.value || '').toLowerCase();
    const statusFilter = document.getElementById('so-status-filter')?.value || '';
    const tbody = document.getElementById('so-table-body');
    if (!tbody) return;

    let data = db.salesOrders.filter(s => {
        const itemResolved = window.resolveRecordItemName(s).toLowerCase();
        const matchSearch = s.number.toLowerCase().includes(search) ||
            (s.customerName || '').toLowerCase().includes(search) ||
            itemResolved.includes(search) ||
            (s.partyOrderNo || '').toLowerCase().includes(search);
        const matchStatus = !statusFilter || s.status === statusFilter;
        return matchSearch && matchStatus;
    });

    if (!data.length) {
        tbody.innerHTML = '<tr><td colspan="11" class="empty-row">No Sales Orders found. Click "+ New Sales Order" to add.</td></tr>';
        return;
    }

    const canWrite = checkPermission('so', 'write');
    const canDelete = checkPermission('so', 'delete');

    tbody.innerHTML = data.map(s => {
        let itemName = window.resolveRecordItemName(s);

        let displayQty = s.qty || 0;
        let displayRate = s.rate || 0;
        let displayAmount = s.amount || (displayQty * displayRate) || 0;

        if (displayQty === 0 && s.items && s.items.length > 0) {
            displayQty = s.items.reduce((sum, it) => sum + (parseFloat(it.qty) || 0), 0);
            displayAmount = s.items.reduce((sum, it) => sum + (parseFloat(it.amount) || ((parseFloat(it.qty) || 0) * (parseFloat(it.price) || 0))), 0);
            displayRate = displayQty > 0 ? displayAmount / displayQty : 0;
        }

        const isCancelled = window.isRecordCancelled ? window.isRecordCancelled(s) : (s.status || '').toLowerCase() === 'cancelled';

        return `
            <tr class="${isCancelled ? 'row-cancelled' : ''}">
                <td><strong style="${isCancelled ? 'color: #b91c1c; text-decoration: line-through;' : ''}">${s.number}</strong></td>
                <td><span style="${isCancelled ? 'color: #b91c1c; text-decoration: line-through;' : ''}">${s.partyOrderNo || '-'}</span></td>
                <td><span style="${isCancelled ? 'color: #b91c1c; text-decoration: line-through;' : ''}">${formatDate(s.date)}</span></td>
                <td><span style="${isCancelled ? 'color: #b91c1c; text-decoration: line-through;' : ''}">${s.customerName}</span></td>
                <td><strong style="${isCancelled ? 'color: #b91c1c; text-decoration: line-through;' : ''}">${itemName}</strong></td>
                <td><strong style="${isCancelled ? 'color: #b91c1c; text-decoration: line-through;' : ''}">${displayQty.toLocaleString('en-IN', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</strong> m</td>
                <td><span style="${isCancelled ? 'color: #b91c1c; text-decoration: line-through;' : ''}">\u20B9${displayRate.toFixed(2)}</span></td>
                <td><strong style="${isCancelled ? 'color: #b91c1c; text-decoration: line-through;' : ''}">\u20B9${displayAmount.toLocaleString('en-IN', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</strong></td>
                <td>${s.deliveryDate ? formatDate(s.deliveryDate) : '-'}</td>
                <td>${getStatusBadge(s.status)}</td>
                <td>
                    <div class="table-actions">
                        <button class="btn btn-sm btn-secondary" onclick="printSO('${s.id}')">=�</button>
                        ${canWrite ? `<button class="btn btn-sm btn-secondary" onclick="openSOModal('${s.id}')"></button>` : ''}
                        ${canDelete ? `<button class="btn btn-sm btn-danger" onclick="deleteSO('${s.id}')">=�</button>` : ''}
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}





// ===== GRN FUNCTIONS =====
let grnCounter = 0;

function getNextGRNNumber() {
    const numbers = (db.grns || []).map(g => {
        if (!g.number) return 0;
        const parts = g.number.split('/');
        if (parts.length < 3) return 0;
        const val = parseInt(parts[parts.length - 1]);
        return isNaN(val) ? 0 : val;
    });
    let next = 1;
    while (numbers.includes(next)) {
        next++;
    }
    return getDocumentNumber('GRN', next);
}



