// ===== FABRIC BALANCE HELPER =====
function getFabricBalance(grnId) {
    const grn = db.grns.find(g => g.id === grnId);
    if (!grn) return 0;
    return Math.max(0, (grn.qty || 0) - (grn.issuedMeters || 0));
}

// ===== PO FUNCTIONS =====
function getNextPONumber() {
    const numbers = (db.pos || []).map(p => {
        if (!p.number) return 0;
        const parts = p.number.split('/');
        if (parts.length < 3) return 0;
        const val = parseInt(parts[parts.length - 1]);
        return isNaN(val) ? 0 : val;
    });
    let next = 1;
    while (numbers.includes(next)) {
        next++;
    }
    return getDocumentNumber('PO', next);
}



