// ===== PRODUCTION LOG FUNCTIONS =====


function fillProdFromPO() {
    const poEl = document.getElementById('prod-log-po') || document.getElementById('prod-po');
    const poId = poEl ? poEl.value : '';
    const po = db.pos.find(p => p.id === poId);
    if (po) {
        const vEl = document.getElementById('prod-log-vendor') || document.getElementById('prod-vendor');
        const dEl = document.getElementById('prod-log-design') || document.getElementById('prod-design');
        if (vEl) vEl.value = po.vendorName || '';
        if (dEl) dEl.value = po.design || '';
    }
}

async function saveProduction() {
    if (!checkPermission('prod', 'write')) {
        showToast('Permission Denied', 'error');
        return;
    }
    const poEl = document.getElementById('prod-log-po') || document.getElementById('prod-po');
    const qtyEl = document.getElementById('prod-log-qty') || document.getElementById('prod-qty');
    const dateEl = document.getElementById('prod-log-date') || document.getElementById('prod-date');
    const editIdEl = document.getElementById('prod-log-edit-id') || document.getElementById('prod-edit-id');
    const vendorEl = document.getElementById('prod-log-vendor') || document.getElementById('prod-vendor');
    const designEl = document.getElementById('prod-log-design') || document.getElementById('prod-design');
    const qualityEl = document.getElementById('prod-log-quality') || document.getElementById('prod-quality');
    const remarksEl = document.getElementById('prod-log-remarks') || document.getElementById('prod-remarks');

    const poId = poEl ? poEl.value : '';
    const qty = parseFloat(qtyEl ? qtyEl.value : 0);
    const date = dateEl ? dateEl.value : '';
    if (!poId) { showToast('Please select a PO reference', 'error'); return; }
    if (!qty || qty <= 0) { showToast('Please enter quantity completed', 'error'); return; }
    if (!validateTransactionDate(date)) return;
    const editId = editIdEl ? editIdEl.value : '';
    const existing = editId ? db.productionLogs.find(l => l.id === editId) : null;
    const prodNum = existing ? existing.number : `LOG-${(db.productionLogs || []).length + 1}`;
    if (!window.validateDocumentDateChronology('production_plans', prodNum, date, editId)) return;

    const logData = {
        id: editId || uid(),
        number: existing ? existing.number : `LOG-${db.productionLogs.length + 1}`,
        date: date,
        entryTimestamp: existing ? (existing.entryTimestamp || currentTimestamp()) : currentTimestamp(),
        poId: poId,
        poNumber: po ? po.number : '',
        vendorName: vendorEl ? vendorEl.value : '',
        design: designEl ? designEl.value : '',
        qty: qty,
        quality: qualityEl ? qualityEl.value : 'OK',
        remarks: remarksEl ? remarksEl.value.trim() : ''
    };

    try {
        await saveToSupabase('production_logs', logData);
        if (editId) {
            const idxRaw = rawDB.productionLogs.findIndex(l => l.id === editId);
            if (idxRaw !== -1) rawDB.productionLogs[idxRaw] = logData;
            logUserAction('Production', 'Modified', `Updated Production Log ${logData.number}`);
            showToast('Production log updated', 'success');
        } else {
            rawDB.productionLogs.unshift(logData);
            logUserAction('Production', 'Created', `Created Production Log ${logData.number}`);
            showToast('Production logged', 'success');
        }
        applyFinancialYearFilters();
        closeModal('prod-modal', true);
        renderProductionLogsTable();
    } catch(e) {
        console.error("Failed to save production log:", e);
        showToast("Save failed: " + (e.message || e), "error");
    }
}

async function deleteProduction(id) {
    if (!checkPermission('prod', 'delete')) {
        showToast('Permission Denied', 'error');
        return;
    }
    const log = db.productionLogs.find(l => l.id === id);
    const num = log ? log.number : '';
    if (!(await window.showSmartConfirm('Delete Log', 'Are you sure you want to delete this production log?'))) return;
    try {
        await deleteFromSupabase('production_logs', id);
        rawDB.productionLogs = rawDB.productionLogs.filter(l => l.id !== id);
        applyFinancialYearFilters();
        renderProductionLogsTable();
        logUserAction('Production', 'Deleted', `Deleted Production Log ${num}`);
        showToast('Production log deleted', 'info');
    } catch(e) {}
}

