// ===== INVENTORY =====
function renderInventoryTable() {
    const search = (document.getElementById('inv-search')?.value || '').toLowerCase();
    const typeFilter = document.getElementById('inv-type-filter')?.value || '';
    const tbody = document.getElementById('inv-table-body');
    if (!tbody) return;

    let data = db.grns.filter(g => {
        const matchSearch = g.number.toLowerCase().includes(search) ||
            g.customerName.toLowerCase().includes(search) ||
            g.item.toLowerCase().includes(search);
        const matchType = !typeFilter || g.packingType === typeFilter;
        return matchSearch && matchType;
    });

    if (!data.length) {
        tbody.innerHTML = '<tr><td colspan="9" class="empty-row">No inventory data. Create GRNs first.</td></tr>';
        return;
    }

    tbody.innerHTML = data.map(g => {
        const issued = g.qty - getFabricBalance(g.id);
        const balance = getFabricBalance(g.id);
        const statusClass = balance <= 0 ? 'badge-red' : balance < g.qty ? 'badge-orange' : 'badge-green';
        const statusText = balance <= 0 ? 'Fully Used' : balance < g.qty ? 'Partial' : 'Available';
        return `
            <tr>
                <td><strong>${g.number}</strong></td>
                <td>${g.customerName}</td>
                <td>${g.item}${g.color ? ` (${g.color})` : ''}</td>
                <td>${getPackingBadge(g.packingType)}</td>
                <td>${g.pkgNo || '-'}</td>
                <td>${g.qty} m</td>
                <td>${issued.toFixed(2)} m</td>
                <td><strong>${balance.toFixed(2)} m</strong></td>
                <td><span class="badge ${statusClass}">${statusText}</span></td>
            </tr>
        `;
    }).join('');
}

function getNextCustomerCode() {
    const list = db.customers || [];
    let maxNum = 0;
    list.forEach(c => {
        if (c.code) {
            const m = String(c.code).match(/CUST[-_]?(\d+)/i);
            if (m) {
                const num = parseInt(m[1], 10);
                if (!isNaN(num) && num > maxNum) {
                    maxNum = num;
                }
            }
        }
    });
    const nextNum = maxNum + 1;
    return `CUST-${String(nextNum).padStart(3, '0')}`;
}
window.getNextCustomerCode = getNextCustomerCode;

function getNextVendorCode() {
    const list = db.vendors || [];
    let maxNum = 0;
    list.forEach(v => {
        if (v.code) {
            const m = String(v.code).match(/VEN[-_]?(\d+)/i);
            if (m) {
                const num = parseInt(m[1], 10);
                if (!isNaN(num) && num > maxNum) {
                    maxNum = num;
                }
            }
        }
    });
    const nextNum = maxNum + 1;
    return `VEN-${String(nextNum).padStart(3, '0')}`;
}
window.getNextVendorCode = getNextVendorCode;

function openCustomerModal(editId = null) {
    if (!checkPermission('masters', 'read') && !checkPermission('masters', 'write')) {
        showToast('Permission Denied', 'error');
        return;
    }
    let c = null;
    if (editId) {
        const allCusts = [...(db.customers || []), ...(window.crossCompanyCustomers || [])];
        c = allCusts.find(x => 
            String(x.id).trim() === String(editId).trim() || 
            (x.code && String(x.code).trim().toLowerCase() === String(editId).trim().toLowerCase()) ||
            (x.name && String(x.name).trim().toLowerCase() === String(editId).trim().toLowerCase())
        );
        if (c) editId = c.id;
    }
    document.getElementById('cust-edit-id').value = editId || '';
    
    const deleteBtn = document.getElementById('cust-btn-delete');
    const cancelRecBtn = document.getElementById('cust-btn-cancel-record');
    
    if (editId && c) {
        if (deleteBtn) deleteBtn.style.display = 'block';
        if (cancelRecBtn) {
            cancelRecBtn.style.display = 'block';
            if (c.status === 'Cancelled') {
                cancelRecBtn.textContent = '=� Reactivate Customer';
                cancelRecBtn.style.background = 'rgba(46, 204, 113, 0.1)';
                cancelRecBtn.style.color = '#2ecc71';
                cancelRecBtn.style.border = '1px solid rgba(46, 204, 113, 0.3)';
            } else {
                cancelRecBtn.textContent = '=� Cancel Customer';
                cancelRecBtn.style.background = 'rgba(230, 126, 34, 0.1)';
                cancelRecBtn.style.color = '#d35400';
                cancelRecBtn.style.border = '1px solid rgba(230, 126, 34, 0.3)';
            }
        }
        document.getElementById('cust-modal-title').textContent = 'Edit Customer';
        const gstType = c.gst_type || parseMetadataFromAddress(c.address, 'GST_TYPE') || ((c.gst && c.gst.trim().toUpperCase() !== 'NA' && c.gst.trim().toUpperCase() !== 'URP') ? 'Regular' : 'Unregistered');
        const gstTypeEl = document.getElementById('cust-gst-type');
        if (gstTypeEl) gstTypeEl.value = gstType;
        if (typeof window.handleCustomerGstTypeChange === 'function') {
            window.handleCustomerGstTypeChange(gstType);
        }
        document.getElementById('cust-code').value = c.code || '';
        document.getElementById('cust-name').value = c.name || '';
        document.getElementById('cust-gst').value = c.gst || '';
        document.getElementById('cust-pan').value = c.pan || parseMetadataFromAddress(c.address, 'PAN') || ((c.gst && c.gst.length >= 12) ? c.gst.substring(2, 12).toUpperCase() : '');
        document.getElementById('cust-contact').value = c.contact || '';
        document.getElementById('cust-email').value = c.email || '';
        document.getElementById('cust-contact-person').value = c.contactPerson || '';
        document.getElementById('cust-designation').value = c.designation || '';
        document.getElementById('cust-city').value = (c.city || '').toUpperCase();
        document.getElementById('cust-state').value = (c.state || '').toUpperCase();
        let custPin = (c.pincode && c.pincode !== 'null') ? String(c.pincode).trim() : (parseMetadataFromAddress(c.address, 'PINCODE') || resolveSmartPincode(c.address, c.city, c.state));
        document.getElementById('cust-pincode').value = custPin || '';
        let custDist = (c.distance !== undefined && c.distance !== null && c.distance !== '' && c.distance !== 'null') ? c.distance : (parseMetadataFromAddress(c.address, 'DISTANCE') || '');
        document.getElementById('cust-distance').value = custDist || '';
        document.getElementById('cust-address').value = cleanAddressStatus(c.address || '');

        if (typeof window.populateCustomDropdowns === 'function') window.populateCustomDropdowns();
        const custTdsAppEl = document.getElementById('cust-tds-applicable');
        const rawTdsPol = c.tds_policy || c.tdsPolicy || c.tds_policy_id || parseMetadataFromAddress(c.address, 'TDS_POLICY') || '';
        const resolvedTdsPol = window.resolveTdsPolicy ? window.resolveTdsPolicy(rawTdsPol) : null;
        if (custTdsAppEl) {
            custTdsAppEl.checked = (c.tds_applicable === true || c.tds_applicable === 'true' || parseMetadataFromAddress(c.address, 'TDS_APPLICABLE') === 'true' || !!resolvedTdsPol);
        }
        const custTdsSel = document.getElementById('cust-tds-policy');
        if (custTdsSel) {
            if (resolvedTdsPol) {
                custTdsSel.value = resolvedTdsPol.id;
            } else if (rawTdsPol) {
                custTdsSel.value = rawTdsPol;
            } else {
                custTdsSel.value = '';
            }
            if (custTdsSel.value === '' && (custTdsAppEl?.checked || rawTdsPol) && custTdsSel.options.length > 1) {
                const fallbackOpt = Array.from(custTdsSel.options).find(opt => opt.value !== '');
                if (fallbackOpt) custTdsSel.value = fallbackOpt.value;
            }
        }
    } else {
        if (deleteBtn) deleteBtn.style.display = 'none';
        if (cancelRecBtn) cancelRecBtn.style.display = 'none';
        document.getElementById('cust-modal-title').textContent = 'Add Customer';
        const gstTypeEl = document.getElementById('cust-gst-type');
        if (gstTypeEl) gstTypeEl.value = 'Regular';
        const code = getNextCustomerCode();
        document.getElementById('cust-code').value = code;
        document.getElementById('cust-name').value = '';
        document.getElementById('cust-gst').value = '';
        document.getElementById('cust-pan').value = '';
        document.getElementById('cust-contact').value = '';
        document.getElementById('cust-email').value = '';
        document.getElementById('cust-contact-person').value = '';
        document.getElementById('cust-designation').value = '';
        document.getElementById('cust-city').value = '';
        document.getElementById('cust-state').value = '';
        document.getElementById('cust-pincode').value = '';
        document.getElementById('cust-distance').value = '';
        document.getElementById('cust-address').value = '';
        const custTdsAppEl = document.getElementById('cust-tds-applicable');
        if (custTdsAppEl) custTdsAppEl.checked = false;
        document.getElementById('cust-tds-policy').value = '';
        if (typeof window.handleCustomerGstTypeChange === 'function') {
            window.handleCustomerGstTypeChange('Regular');
        }
    }
    openModal('cust-modal');
}

async function saveCustomer() {
    console.log('[CUSTOMER_SAVE] Initiated saveCustomer()');
    if (!checkPermission('masters', 'write')) {
        showToast('Permission Denied', 'error');
        return;
    }
    window._isSavingMaster = true;
    const name = document.getElementById('cust-name').value.trim();
    let gstType = document.getElementById('cust-gst-type')?.value || 'Regular';
    let gst = (document.getElementById('cust-gst').value || '').trim().replace(/\s+/g, '').toUpperCase();
    const editId = (document.getElementById('cust-edit-id')?.value || '').trim();
    const editCode = (document.getElementById('cust-code')?.value || '').trim();

    if (!name) { 
        window._isSavingMaster = false;
        showToast('Customer name is required', 'error'); 
        return; 
    }

    let panVal = (document.getElementById('cust-pan')?.value || '').trim().toUpperCase();

    if (gstType === 'Unregistered') {
        gst = (gst && gst !== 'NA' && gst !== 'URP') ? gst : 'NA';
    } else {
        if (!gst || gst === 'NA' || gst === 'URP') {
            window._isSavingMaster = false;
            showToast(`GST Number is required when GST Registration Type is ${gstType}`, 'error');
            return;
        }
        if (gst.length !== 15) {
            window._isSavingMaster = false;
            showToast(`GST Number must be a valid 15-digit GSTIN for ${gstType} GST Registration Type.`, 'error');
            return;
        }
        if (!panVal && gst.length === 15) {
            panVal = gst.substring(2, 12).toUpperCase();
            const panInput = document.getElementById('cust-pan');
            if (panInput) panInput.value = panVal;
        }
    }

    db.customers = db.customers || [];
    const allCusts = [...(db.customers || []), ...(window.crossCompanyCustomers || [])];
    const existingCust = editId ? allCusts.find(c => String(c.id).trim() === String(editId).trim()) : null;
    
    const targetEditId = existingCust ? existingCust.id : editId;
    const currentStatus = existingCust ? (existingCust.status || 'Active') : 'Active';

    const nameLower = name.toLowerCase();
    const gstLower = gst.toLowerCase();

    const curCompId = (existingCust && existingCust.company_id) || (currentCompany ? currentCompany.id : 'co4');
    const isSameCompany = (c) => !curCompId || !c.company_id || String(c.company_id) === String(curCompId);

    const isSelfRecord = (c) => {
        if (!targetEditId) return false;
        return String(c.id).trim() === String(targetEditId).trim();
    };

    const dupNameCust = allCusts.find(c => 
        !isSelfRecord(c) && 
        isSameCompany(c) && 
        c.name && c.name.trim().toLowerCase() === nameLower
    );

    const dupGstCust = (gstLower && gstLower !== 'na' && gstLower !== 'urp') ? allCusts.find(c => 
        !isSelfRecord(c) && 
        isSameCompany(c) && 
        c.gst && c.gst.trim().toLowerCase() === gstLower
    ) : null;

    if (dupNameCust) {
        window._isSavingMaster = false;
        showToast(`A customer with this Name already exists: ${dupNameCust.code ? dupNameCust.code + ' (' : ''}${dupNameCust.name}${dupNameCust.code ? ')' : ''}`, 'error');
        return;
    }
    if (dupGstCust) {
        window._isSavingMaster = false;
        showToast(`A customer with this GST Number already exists: ${dupGstCust.code ? dupGstCust.code + ' (' : ''}${dupGstCust.name}${dupGstCust.code ? ')' : ''}`, 'error');
        return;
    }
    
    let pinVal = document.getElementById('cust-pincode')?.value.trim() || '';
    const tdsApp = document.getElementById('cust-tds-applicable')?.checked || false;
    const tdsPol = document.getElementById('cust-tds-policy')?.value || '';
    let cleanAddr = cleanAddressStatus((document.getElementById('cust-address')?.value || '').trim());

    if (!pinVal && cleanAddr) {
        pinVal = resolveSmartPincode(cleanAddr, document.getElementById('cust-city')?.value.trim(), document.getElementById('cust-state')?.value.trim());
    }

    let custDistVal = document.getElementById('cust-distance')?.value.trim() || '';

    const taggedAddr = buildTaggedAddress({
        address: cleanAddr,
        status: currentStatus,
        gst_type: gstType,
        pan: panVal,
        pincode: pinVal,
        distance: custDistVal,
        tds_applicable: tdsApp,
        tds_policy: tdsPol
    });

    const data = {
        id: targetEditId || uid(),
        company_id: curCompId,
        code: editCode || (existingCust ? existingCust.code : getNextCustomerCode()),
        name,
        gst,
        pan: panVal,
        contact: (document.getElementById('cust-contact')?.value || '').trim(),
        email: (document.getElementById('cust-email')?.value || '').trim(),
        contactPerson: (document.getElementById('cust-contact-person')?.value || '').trim(),
        designation: (document.getElementById('cust-designation')?.value || '').trim(),
        city: (document.getElementById('cust-city')?.value || '').trim().toUpperCase(),
        state: (document.getElementById('cust-state')?.value || '').trim().toUpperCase(),
        pincode: pinVal,
        distance: custDistVal === '' ? null : (parseFloat(custDistVal) || 0),
        address: taggedAddr,
        tds_applicable: tdsApp,
        tds_policy: tdsPol || null,
        status: currentStatus,
        gst_type: gstType
    };

    console.log('[CUSTOMER_SAVE] Saving customer payload to Supabase:', data);

    try {
        await saveToSupabase('customers', data);
        console.log('[CUSTOMER_SAVE] saveToSupabase successful for customer ID:', data.id);
        const memData = { ...data, address: cleanAddr };

        if (targetEditId && existingCust) {
            const oldName = existingCust.name;
            const idx = db.customers.findIndex(c => String(c.id).trim() === String(targetEditId).trim());
            if (idx !== -1) {
                db.customers[idx] = memData;
            } else if (currentCompany && String(curCompId) === String(currentCompany.id)) {
                db.customers.push(memData);
            }
            if (window.crossCompanyCustomers) {
                const xIdx = window.crossCompanyCustomers.findIndex(c => String(c.id).trim() === String(targetEditId).trim());
                if (xIdx !== -1) window.crossCompanyCustomers[xIdx] = memData;
            }

            if (oldName && oldName.trim().toLowerCase() !== name.trim().toLowerCase()) {
                const oldLower = oldName.trim().toLowerCase();
                const cascadePromises = [];
                (db.salesOrders || []).forEach(so => {
                    if (String(so.customer) === String(targetEditId) || String(so.customerId) === String(targetEditId) || String(so.customer_id) === String(targetEditId) || (so.customerName && so.customerName.trim().toLowerCase() === oldLower)) {
                        so.customerName = name;
                        so.customer_name = name;
                        cascadePromises.push(saveToSupabase('sales_orders', so).catch(console.error));
                    }
                });
                (db.outwards || []).forEach(out => {
                    if (String(out.customerId) === String(targetEditId) || String(out.customer_id) === String(targetEditId) || (out.customerName && out.customerName.trim().toLowerCase() === oldLower)) {
                        out.customerName = name;
                        out.customer_name = name;
                    }
                });
                (db.grns || []).forEach(grn => {
                    if (String(grn.customerId) === String(targetEditId) || String(grn.customer) === String(targetEditId) || (grn.customerName && grn.customerName.trim().toLowerCase() === oldLower)) {
                        grn.customerName = name;
                        cascadePromises.push(saveToSupabase('grns', grn).catch(console.error));
                    }
                });
                (db.genericTransactions || []).forEach(gtx => {
                    if (String(gtx.partyId) === String(targetEditId) || (gtx.partyName && gtx.partyName.trim().toLowerCase() === oldLower)) {
                        gtx.partyName = name;
                    }
                });
                if (cascadePromises.length > 0) {
                    await Promise.all(cascadePromises);
                }
            }

            logUserAction('Masters', 'Modified', `Updated customer: ${name}`);
            showToast('Customer updated successfully', 'success');
        } else {
            db.customers = db.customers || [];
            const existingIdx = db.customers.findIndex(c => String(c.id).trim() === String(memData.id).trim() || (c.code && String(c.code).trim().toLowerCase() === memData.code.toLowerCase()));
            if (existingIdx !== -1) {
                db.customers[existingIdx] = memData;
            } else {
                db.customers.push(memData);
            }
            logUserAction('Masters', 'Created', `Created customer: ${name}`);
            showToast('Customer added successfully', 'success');
        }

        closeModal('cust-modal', true);
        renderCustomerTable();
        populateAllDropdowns();
        if (typeof window.updateLocalDBCache === 'function') {
            await window.updateLocalDBCache();
        }
    } catch(e) {
        console.error("[CUSTOMER_SAVE] Error saving customer:", e);
        showToast('Failed to save customer: ' + (e.message || e), 'error');
    } finally {
        window._isSavingMaster = false;
    }
}
window.saveCustomer = saveCustomer;
window.openCustomerModal = openCustomerModal;

window.migrateMasterAddressTagsToColumns = async function migrateMasterAddressTagsToColumns() {
    if (window._hasRunAddressTagMigration) return;
    window._hasRunAddressTagMigration = true;
    console.log('[MIGRATION] Cleaning local customer and vendor address tags...');

    const customers = db.customers || [];
    for (let c of customers) {
        if (c.address && c.address.includes('[')) {
            const parsedGstType = c.gst_type || parseMetadataFromAddress(c.address, 'GST_TYPE') || ((c.gst && c.gst !== 'NA' && c.gst !== 'URP') ? 'Regular' : 'Unregistered');
            const parsedPan = c.pan || parseMetadataFromAddress(c.address, 'PAN') || ((c.gst && c.gst.length >= 12) ? c.gst.substring(2, 12).toUpperCase() : '');
            const parsedTdsApp = (c.tds_applicable === true || c.tds_applicable === 'true' || parseMetadataFromAddress(c.address, 'TDS_APPLICABLE') === 'true');
            const parsedTdsPol = c.tds_policy || c.tdsPolicy || parseMetadataFromAddress(c.address, 'TDS_POLICY') || null;
            const parsedPin = (c.pincode && c.pincode !== 'null') ? String(c.pincode).trim() : (parseMetadataFromAddress(c.address, 'PINCODE') || '');
            const parsedDist = (c.distance !== undefined && c.distance !== null && c.distance !== '' && c.distance !== 'null') ? c.distance : (parseMetadataFromAddress(c.address, 'DISTANCE') || null);
            const parsedStatus = c.status || parseMetadataFromAddress(c.address, 'STATUS') || 'Active';
            const cleanAddr = cleanAddressStatus(c.address);

            c.gst_type = parsedGstType;
            c.pan = parsedPan;
            c.tds_applicable = parsedTdsApp;
            c.tds_policy = parsedTdsPol;
            if (parsedPin) c.pincode = parsedPin;
            if (parsedDist !== null && parsedDist !== undefined && parsedDist !== '') c.distance = parseFloat(parsedDist) || null;
            c.status = parsedStatus;
            c.address = cleanAddr;
        }
    }

    const vendors = db.vendors || [];
    for (let v of vendors) {
        if (v.address && v.address.includes('[')) {
            const parsedGstType = v.gst_type || parseMetadataFromAddress(v.address, 'GST_TYPE') || ((v.gst && v.gst !== 'NA' && v.gst !== 'URP') ? 'Regular' : 'Unregistered');
            const parsedPan = v.pan || parseMetadataFromAddress(v.address, 'PAN') || ((v.gst && v.gst.length >= 12) ? v.gst.substring(2, 12).toUpperCase() : '');
            const parsedTdsApp = (v.tds_applicable === true || v.tds_applicable === 'true' || parseMetadataFromAddress(v.address, 'TDS_APPLICABLE') === 'true');
            const parsedTdsPol = v.tds_policy || v.tdsPolicy || parseMetadataFromAddress(v.address, 'TDS_POLICY') || null;
            const parsedPin = (v.pincode && v.pincode !== 'null') ? String(v.pincode).trim() : (parseMetadataFromAddress(v.address, 'PINCODE') || '');
            const parsedDist = (v.distance !== undefined && v.distance !== null && v.distance !== '' && v.distance !== 'null') ? v.distance : (parseMetadataFromAddress(v.address, 'DISTANCE') || null);
            const parsedStatus = v.status || parseMetadataFromAddress(v.address, 'STATUS') || 'Active';
            const cleanAddr = cleanAddressStatus(v.address);

            v.gst_type = parsedGstType;
            v.pan = parsedPan;
            v.tds_applicable = parsedTdsApp;
            v.tds_policy = parsedTdsPol;
            if (parsedPin) v.pincode = parsedPin;
            if (parsedDist !== null && parsedDist !== undefined && parsedDist !== '') v.distance = parseFloat(parsedDist) || null;
            v.status = parsedStatus;
            v.address = cleanAddr;
        }
    }
};

setTimeout(() => {
    if (typeof window.migrateMasterAddressTagsToColumns === 'function') {
        window.migrateMasterAddressTagsToColumns().catch(console.error);
    }
}, 3000);
window.openCustomerModalByName = function(nameOrId) {
    if (!nameOrId) return;
    const c = (db.customers || []).find(x => 
        String(x.id) === String(nameOrId) || 
        (x.name && x.name.trim().toLowerCase() === String(nameOrId).trim().toLowerCase()) || 
        (x.code && x.code.trim().toLowerCase() === String(nameOrId).trim().toLowerCase())
    );
    if (c) {
        openCustomerModal(c.id);
    } else {
        showToast(`Customer details for "${nameOrId}" not found`, 'info');
    }
};

window.deleteCustomerFromModal = async function() {
    const editId = document.getElementById('cust-edit-id').value;
    if (!editId) return;
    const ok = await deleteCustomer(editId);
    if (ok) {
        closeModal('cust-modal', true);
    }
};

window.cancelCustomerFromModal = async function() {
    const editId = document.getElementById('cust-edit-id').value;
    if (!editId) return;
    const c = db.customers.find(x => x.id === editId);
    if (!c) return;
    
    const newStatus = c.status === 'Cancelled' ? 'Active' : 'Cancelled';
    if (newStatus === 'Cancelled') {
        const refs = window.getPartyReferences(editId, 'Customer');
        if (refs.length > 0) {
            window.showReferenceResolutionModal(editId, 'Customer', 'cancel', () => cancelCustomerFromModal());
            return;
        }
    }

    const confirmMsg = newStatus === 'Cancelled' 
        ? 'Cancel this customer? The customer code series will not be disturbed.' 
        : 'Reactivate this customer?';
    if (!(await window.showSmartConfirm('Confirm Saving', confirmMsg))) return;
    
    c.status = newStatus;
    
    const cleanAddr = cleanAddressStatus(document.getElementById('cust-address').value.trim());
    let rawAddress = cleanAddr;
    if (newStatus !== 'Active') {
        rawAddress += `\n[STATUS:${newStatus}]`;
    }
    const gstType = document.getElementById('cust-gst-type') ? document.getElementById('cust-gst-type').value : (c.gst_type || 'Regular');
    const panVal = document.getElementById('cust-pan') ? document.getElementById('cust-pan').value.trim().toUpperCase() : (c.pan || '');
    const pinVal = document.getElementById('cust-pincode')?.value.trim() || c.pincode || '';
    
    const data = {
        id: c.id,
        code: c.code,
        name: document.getElementById('cust-name').value.trim() || c.name,
        gst: document.getElementById('cust-gst').value.trim(),
        pan: panVal,
        contact: document.getElementById('cust-contact').value.trim(),
        email: document.getElementById('cust-email').value.trim(),
        contactPerson: document.getElementById('cust-contact-person').value.trim(),
        designation: document.getElementById('cust-designation').value.trim(),
        city: document.getElementById('cust-city').value.trim().toUpperCase(),
        state: document.getElementById('cust-state').value.trim().toUpperCase(),
        pincode: pinVal,
        distance: parseFloat(document.getElementById('cust-distance').value) || null,
        address: rawAddress,
        tds_applicable: document.getElementById('cust-tds-applicable')?.checked || false,
        tds_policy: document.getElementById('cust-tds-policy').value || null,
        status: newStatus,
        gst_type: gstType
    };
    
    try {
        await saveToSupabase('customers', data);
        data.address = cleanAddr;
        const idx = db.customers.findIndex(x => x.id === editId);
        if (idx !== -1) {
            db.customers[idx] = data;
        }
        logUserAction('Masters', 'Modified', `Customer status changed to ${newStatus}: ${c.name}`);
        showToast(`Customer status changed to ${newStatus}`, 'success');
        closeModal('cust-modal', true);
        renderCustomerTable();
    } catch(e) {
        showToast('Operation failed', 'error');
    }
};

// window.autoCalculatePincodeDistance defined globally near calcAndCachePincodeDistance

window.getPartyReferences = function(partyId, partyType) {
    const list = [];
    const isDifferentCompany = (doc) => {
        if (!doc) return true;
        const coId = doc.company_id || doc.companyId;
        if (coId && typeof currentCompany !== 'undefined' && currentCompany && coId !== currentCompany.id) {
            return true;
        }
        return false;
    };

    if (partyType === 'Item') {
        const item = (db.items || []).find(x => x.id === partyId);
        if (!item) return list;
        const lowerName = item.name.trim().toLowerCase();
        const lowerCode = item.code ? item.code.trim().toLowerCase() : '';
        
        // 1. Sales Orders
        (db.salesOrders || []).forEach(so => {
            if (so.status === 'Cancelled') return;
            if (isDifferentCompany(so)) return;
            const hasItem = so.designId === partyId || (so.items || []).some(it => it.itemId === partyId);
            if (hasItem) {
                list.push({
                    type: 'Sales Order',
                    id: so.id,
                    number: so.number || 'Unnamed SO',
                    date: so.date || '',
                    editFn: `openSOModal('${so.id}')`
                });
            }
        });

        // 2. Purchase Orders
        (db.pos || []).forEach(po => {
            if (po.status === 'Cancelled') return;
            if (isDifferentCompany(po)) return;
            const hasItem = po.designId === partyId || (po.items || []).some(it => it.itemId === partyId);
            if (hasItem) {
                list.push({
                    type: 'Purchase Order',
                    id: po.id,
                    number: po.number || 'Unnamed PO',
                    date: po.date || '',
                    editFn: `openPOModal('${po.id}')`
                });
            }
        });

        // 3. GRNs
        (db.grns || []).forEach(grn => {
            if (grn.status === 'Cancelled') return;
            if (isDifferentCompany(grn)) return;
            const hasItem = grn.designNumber === item.name || (lowerCode && grn.designNumber === item.code) ||
                            (grn.packages || []).some(pkg => pkg.design === item.name || (lowerCode && pkg.design === item.code)) ||
                            (grn.packageSlips || []).some(s => s.fabricType === item.name || (lowerCode && s.fabricType === item.code));
            if (hasItem) {
                list.push({
                    type: 'GRN',
                    id: grn.id,
                    number: grn.grnNo || grn.number || 'Unnamed GRN',
                    date: grn.date || '',
                    editFn: `openGRNModal('${grn.id}')`
                });
            }
        });

        // 4. BOMs
        (db.boms || []).forEach(bom => {
            if (isDifferentCompany(bom)) return;
            const hasItem = bom.finishedItemId === partyId || (bom.ingredients || []).some(ing => ing.itemId === partyId);
            if (hasItem) {
                list.push({
                    type: 'BOM Blueprint',
                    id: bom.id,
                    number: bom.code || 'Unnamed BOM',
                    date: '',
                    editFn: `openBOMModal('${bom.id}')`
                });
            }
        });
        
        return list;
    }
    
    const party = (partyType === 'Customer') 
        ? (db.customers || []).find(c => c.id === partyId)
        : (db.vendors || []).find(v => v.id === partyId);
    if (!party) return list;

    const lowerName = party.name.trim().toLowerCase();

    // 1. Sales Orders
    if (partyType === 'Customer') {
        (db.salesOrders || []).forEach(so => {
            if (so.status === 'Cancelled') return;
            if (isDifferentCompany(so)) return;
            if (so.customer === partyId || so.customerId === partyId || (so.customerName && so.customerName.trim().toLowerCase() === lowerName)) {
                list.push({
                    type: 'Sales Order',
                    id: so.id,
                    number: so.number || 'Unnamed SO',
                    date: so.date || '',
                    editFn: `openSOModal('${so.id}')`
                });
            }
        });
    }

    // 2. Purchase Orders
    if (partyType === 'Vendor') {
        (db.pos || []).forEach(po => {
            if (po.status === 'Cancelled') return;
            if (isDifferentCompany(po)) return;
            const poVendId = po.vendorId || po.vendor_id || po.vendor || '';
            const poVendObj = (db.vendors || []).find(v => v.id === poVendId);
            const resolvedVendId = poVendObj ? poVendObj.id : poVendId;
            const resolvedVendName = poVendObj ? poVendObj.name : (po.vendorName || po.vendor_name || '');

            if (resolvedVendId === partyId || (resolvedVendName && resolvedVendName.trim().toLowerCase() === lowerName)) {
                list.push({
                    type: 'Purchase Order',
                    id: po.id,
                    number: po.number || 'Unnamed PO',
                    date: po.date || '',
                    editFn: `openPOModal('${po.id}')`
                });
            }
        });
    }

    // 3. GRNs
    (db.grns || []).forEach(grn => {
        if (grn.status === 'Cancelled') return;
        if (isDifferentCompany(grn)) return;
        let belongs = false;
        const docNo = String(grn.grnNo || grn.number || grn.partyDocNo || '').toUpperCase();
        const grnType = String(grn.type || grn.grnType || grn.source || '').toLowerCase();
        const isVendorSource = docNo.includes('/V/') || docNo.startsWith('GRN/V') || grnType === 'vendor' || grnType.includes('vend') || grn.source === 'vendor' || grnType.includes('con') || grnType.includes('oth') || docNo.startsWith('GRN/CON') || docNo.startsWith('GRN/OTH');
        const isCustomerSource = docNo.includes('/C/') || docNo.startsWith('GRN/C') || grnType === 'customer' || grnType.includes('cust') || grn.source === 'customer';

        if (partyType === 'Customer') {
            if (isCustomerSource) {
                belongs = grn.customerId === partyId || (grn.customerName && grn.customerName.trim().toLowerCase() === lowerName);
            }
        } else {
            if (isVendorSource) {
                belongs = grn.vendorId === partyId || (grn.vendorName && grn.vendorName.trim().toLowerCase() === lowerName);
            }
        }
        if (belongs) {
            list.push({
                type: 'GRN',
                id: grn.id,
                number: grn.grnNo || grn.number || 'Unnamed GRN',
                date: grn.date || '',
                editFn: `openGRNModal('${grn.id}')`
            });
        }
    });

    // 4. Outwards
    (db.outwards || []).forEach(out => {
        if (out.status === 'Cancelled') return;
        if (isDifferentCompany(out)) return;
        let belongs = false;

        let outCustId = out.customerId || out.customer_id || '';
        let outCustName = out.customerName || out.customer_name || '';
        let outVendId = out.vendorId || out.vendor_id || '';
        let outVendName = out.vendorName || out.vendor_name || '';

        if (out.remarks) {
            const match = out.remarks.match(/\[WIZARD:(\{.*?\})\]/);
            if (match) {
                try {
                    const wiz = JSON.parse(match[1]);
                    if (wiz.customerId) outCustId = wiz.customerId;
                    if (wiz.customerName) outCustName = wiz.customerName;
                    if (wiz.vendorId) outVendId = wiz.vendorId;
                    if (wiz.vendorName) outVendName = wiz.vendorName;
                } catch(e){}
            }
        }

        const soId = out.linked_so_id || out.linkedSoId || out.soRefId || out.soRef;
        if (soId && db.salesOrders) {
            const so = db.salesOrders.find(s => s.id === soId || s.number === soId);
            if (so) {
                if (so.customerId || so.customer_id) outCustId = so.customerId || so.customer_id;
                if (so.customerName || so.customer_name) outCustName = so.customerName || so.customer_name;
            }
        }

        const poId = out.linked_po_id || out.poRefId || out.po_ref;
        if (poId && db.pos) {
            const po = db.pos.find(p => p.id === poId || p.number === poId);
            if (po) {
                if (po.vendorId || po.vendor) outVendId = po.vendorId || po.vendor;
                if (po.vendorName) outVendName = po.vendorName;
            }
        }

        const outNum = (out.number || '').toUpperCase();
        const isVendorChallan = outNum.startsWith('FI/V') || outNum.includes('/V/') || out.type === 'vendor' || out.source === 'vendor';
        const isCustomerChallan = outNum.startsWith('FI/C') || outNum.includes('/C/') || out.type === 'customer' || out.source === 'customer';

        const isValidNameMatch = (nameStr) => {
            if (!nameStr) return false;
            const n = nameStr.trim().toLowerCase();
            return n !== '' && n !== '-' && n !== 'customer' && n !== 'vendor' && n !== 'none' && n !== 'n/a';
        };

        if (partyType === 'Customer') {
            if (isCustomerChallan || (!isVendorChallan && outCustId)) {
                belongs = (outCustId && outCustId === partyId) || 
                          (isValidNameMatch(lowerName) && isValidNameMatch(outCustName) && outCustName.trim().toLowerCase() === lowerName);
            }
        } else if (partyType === 'Vendor') {
            if (isVendorChallan || (!isCustomerChallan && outVendId)) {
                const vObj = outVendId && db.vendors ? db.vendors.find(v => v.id === outVendId) : null;
                const resVendId = vObj ? vObj.id : outVendId;
                const resVendName = vObj ? vObj.name : outVendName;
                belongs = (resVendId && resVendId === partyId) || 
                          (isValidNameMatch(lowerName) && isValidNameMatch(resVendName) && resVendName.trim().toLowerCase() === lowerName);
            }
        }
        if (belongs) {
            list.push({
                type: 'Outward (Job Work)',
                id: out.id,
                number: out.number || 'Unnamed Outward',
                date: out.date || '',
                editFn: `openOutwardModal('${out.id}')`
            });
        }
    });

    // 5. Generic Transactions (Invoice, Voucher, Sales Return, Purchase Return)
    (db.genericTransactions || []).forEach(gt => {
        if (gt.status === 'Cancelled') return;
        if (isDifferentCompany(gt)) return;
        let isMatch = false;
        if (gt.partyId === partyId) {
            if (partyType === 'Customer' && (gt.type === 'invoice' || gt.type === 'salesreturn' || gt.type === 'voucher')) {
                isMatch = true;
            } else if (partyType === 'Vendor' && (gt.type === 'purchasereturn' || gt.type === 'voucher')) {
                isMatch = true;
            }
        } else if (gt.partyName && gt.partyName.trim().toLowerCase() === lowerName) {
            if (partyType === 'Customer') {
                if (gt.type === 'invoice' || gt.type === 'salesreturn' || gt.type === 'voucher') {
                    isMatch = true;
                }
            } else if (partyType === 'Vendor') {
                if (gt.type === 'purchasereturn' || gt.type === 'voucher') {
                    isMatch = true;
                }
            }
        }
        if (isMatch) {
            let editFn = '';
            let label = 'Voucher';
            if (gt.type === 'invoice') { label = 'Invoice'; editFn = `openInvoiceModal('${gt.id}')`; }
            else if (gt.type === 'voucher') { label = 'Payment Voucher'; editFn = `openVoucherModal('${gt.id}')`; }
            else if (gt.type === 'salesreturn') { label = 'Sales Return'; editFn = `openSalesReturnModal('${gt.id}')`; }
            else if (gt.type === 'purchasereturn') { label = 'Purchase Return'; editFn = `openPurchaseReturnModal('${gt.id}')`; }
            else { editFn = `openGenericTxModal('${gt.type}', '${gt.id}')`; }
            
            list.push({
                type: label,
                id: gt.id,
                number: gt.number || 'Unnamed Tx',
                date: gt.date || '',
                editFn: editFn
            });
        }
    });

    return list;
};

window.showReferenceResolutionModal = function(partyId, partyType, actionType, onProceed) {
    const party = (partyType === 'Customer') 
        ? (db.customers || []).find(c => c.id === partyId)
        : ((partyType === 'Vendor') ? (db.vendors || []).find(v => v.id === partyId) : (db.items || []).find(i => i.id === partyId));
    if (!party) return;

    const refs = window.getPartyReferences(partyId, partyType);
    if (refs.length === 0) {
        onProceed();
        return;
    }

    let modal = document.getElementById('ref-resolution-modal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'ref-resolution-modal';
        modal.className = 'modal-overlay';
        modal.setAttribute('style', 'display:none; position:fixed; z-index:999999; left:0; top:0; width:100vw; height:100vh; overflow:auto; background-color:rgba(0,0,0,0.5); justify-content:center; align-items:center;');
        document.body.appendChild(modal);
    }

    const rowsHtml = refs.map(r => `
        <tr style="border-bottom: 1px solid var(--border);">
            <td style="padding: 10px; font-weight: 600; color: var(--text-primary);">${r.type}</td>
            <td style="padding: 10px; font-family: monospace; font-weight: 700; color: var(--text-accent);">${r.number}</td>
            <td style="padding: 10px; color: var(--text-secondary);">${r.date}</td>
            <td style="padding: 10px; text-align: center;">
                <button class="btn btn-sm btn-secondary" onclick="document.getElementById('ref-resolution-modal').style.display='none'; ${r.editFn}" style="padding: 4px 8px; font-size: 11px;"> Edit</button>
            </td>
        </tr>
    `).join('');

    modal.innerHTML = `
        <div class="card" style="width:500px; background:var(--bg-primary); border-radius:12px; box-shadow:0 10px 25px rgba(0,0,0,0.25); border:1px solid var(--border); overflow:hidden; display:flex; flex-direction:column; padding:20px;">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:15px; border-bottom:1px solid var(--border); padding-bottom:10px;">
                <h3 style="margin:0; font-size:14px; font-weight:700; color:var(--text-primary);">� Outstanding Vouchers Reference Alert</h3>
                <span style="font-size:20px; cursor:pointer; color:var(--text-secondary);" onclick="document.getElementById('ref-resolution-modal').style.display='none'">&times;</span>
            </div>
            <div style="font-size:12px; color:var(--text-secondary); margin-bottom:15px; line-height:1.5;">
                The ${partyType} <strong>${party.name}</strong> is referenced in the active vouchers below. You must edit or resolve these references first. If nothing is done, you cannot ${actionType} this ${partyType.toLowerCase()}.
            </div>
            <div style="max-height: 250px; overflow-y: auto; border: 1px solid var(--border); border-radius: 6px; margin-bottom: 15px;">
                <table style="width:100%; border-collapse:collapse; text-align:left; font-size:11px;">
                    <thead>
                        <tr style="background:var(--bg-secondary); border-bottom:1px solid var(--border);">
                            <th style="padding:8px 10px;">Type</th>
                            <th style="padding:8px 10px;">Voucher No</th>
                            <th style="padding:8px 10px;">Date</th>
                            <th style="padding:8px 10px; text-align:center;">Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        ${rowsHtml}
                    </tbody>
                </table>
            </div>
            <div style="display:flex; justify-content:flex-end; gap:8px; border-top:1px solid var(--border); padding-top:12px;">
                <button class="btn btn-ghost" onclick="document.getElementById('ref-resolution-modal').style.display='none'" style="font-size:12px; padding:6px 12px;">Cancel</button>
                <button class="btn btn-primary" onclick="window.recheckRefResolution('${partyId}', '${partyType}', '${actionType}', ${onProceed.toString()})" style="font-size:12px; padding:6px 12px;">= Re-check & Proceed</button>
            </div>
        </div>
    `;
    modal.style.display = 'flex';
};

window.recheckRefResolution = function(partyId, partyType, actionType, onProceed) {
    const refs = window.getPartyReferences(partyId, partyType);
    if (refs.length === 0) {
        document.getElementById('ref-resolution-modal').style.display = 'none';
        onProceed();
    } else {
        showToast(`Cannot proceed. Outstanding references still exist.`, 'error');
        window.showReferenceResolutionModal(partyId, partyType, actionType, onProceed);
    }
};

function checkCustomerReferences(customerId) {
    const cust = db.customers.find(x => x.id === customerId);
    if (!cust) return null;
    const lowerName = cust.name.trim().toLowerCase();
    
    if ((db.salesOrders || []).some(so => so.customer === customerId || so.customerId === customerId || String(so.customerName).toLowerCase() === lowerName)) {
        return 'Sales Orders';
    }
    if ((db.grns || []).some(grn => {
        if (grn.status === 'Cancelled') return false;
        const docNo = String(grn.grnNo || grn.number || grn.partyDocNo || '').toUpperCase();
        const grnType = String(grn.type || grn.grnType || grn.source || '').toLowerCase();
        const isCustomerSource = docNo.includes('/C/') || docNo.startsWith('GRN/C') || grnType === 'customer' || grnType.includes('cust') || grn.source === 'customer';
        if (isCustomerSource) {
            return grn.customerId === customerId || (grn.customerName && grn.customerName.trim().toLowerCase() === lowerName);
        }
    })) {
        return 'GRNs';
    }
    if ((db.outwards || []).some(out => {
        if (out.status === 'Cancelled') return false;
        let outCustId = out.customerId || out.customer_id || '';
        let outCustName = out.customerName || out.customer_name || '';
        if (out.remarks) {
            const match = out.remarks.match(/\[WIZARD:(\{.*?\})\]/);
            if (match) {
                try {
                    const wiz = JSON.parse(match[1]);
                    if (wiz.customerId) outCustId = wiz.customerId;
                    if (wiz.customerName) outCustName = wiz.customerName;
                } catch(e){}
            }
        }
        const soId = out.linked_so_id || out.linkedSoId || out.soRefId || out.soRef;
        if (soId && db.salesOrders) {
            const so = db.salesOrders.find(s => s.id === soId || s.number === soId);
            if (so) {
                if (so.customerId || so.customer_id) outCustId = so.customerId || so.customer_id;
                if (so.customerName || so.customer_name) outCustName = so.customerName || so.customer_name;
            }
        }
        return (outCustId && outCustId === customerId) || 
               (outCustName && outCustName.trim().toLowerCase() === lowerName && outCustName.toLowerCase() !== 'customer' && outCustName.toLowerCase() !== 'vendor');
    })) {
        return 'Outwards / Fabric Issue Challans';
    }
    if ((db.genericTransactions || []).some(gt => {
        if (gt.status === 'Cancelled') return false;
        if (gt.partyId === customerId && (gt.type === 'invoice' || gt.type === 'salesreturn' || gt.type === 'voucher')) {
            return true;
        }
        if (gt.partyName && gt.partyName.trim().toLowerCase() === lowerName && (gt.type === 'invoice' || gt.type === 'salesreturn' || gt.type === 'voucher')) {
            return true;
        }
        return false;
    })) {
        return 'Invoices/Vouchers/Returns';
    }
    return null;
}
window.checkCustomerReferences = checkCustomerReferences;

async function deleteCustomer(id) {
    if (!checkPermission('masters', 'delete')) {
        showToast('Permission Denied', 'error');
        return false;
    }
    const c = db.customers.find(x => x.id === id);
    if (!c) return false;
    const name = c.name;
    
    const refs = window.getPartyReferences(id, 'Customer');
    if (refs.length > 0) {
        window.showReferenceResolutionModal(id, 'Customer', 'delete', () => deleteCustomer(id));
        return false;
    }

    if (!(await window.showSmartConfirm('Delete Customer', 'Are you sure you want to delete this customer?'))) return false;
    try {
        await deleteFromSupabase('customers', id);
        db.customers = db.customers.filter(c => c.id !== id);
        renderCustomerTable();
        logUserAction('Masters', 'Deleted', `Deleted customer: ${name}`);
        showToast('Customer deleted', 'info');
        return true;
    } catch(e) {
        showToast(`Delete failed: ${e.message || e}`, 'error');
        return false;
    }
}

function renderCustomerTable() {
    db.customers = db.customers || [];
    renderDynamicHeader('customer', 'cust-table-head');

    // Ensure item category/subcategory filters are hidden on Customer master across all toolbars
    document.querySelectorAll('#item-category-filter, #item-subcategory-filter').forEach(el => {
        el.style.setProperty('display', 'none', 'important');
        el.value = '';
        const w = el.closest('.searchable-select-wrapper');
        if (w) w.style.setProperty('display', 'none', 'important');
    });

    document.querySelectorAll('#btn-master-print').forEach(btn => {
        btn.style.setProperty('display', 'none', 'important');
    });

    const custTableEl = document.getElementById('cust-table') || document.querySelector('#cust-table-head')?.closest('table');
    const isFreezeCustomer = localStorage.getItem('freeze_first_4_customer') === 'true';
    if (custTableEl) {
        custTableEl.classList.remove('freeze-first-3');
        if (isFreezeCustomer) {
            custTableEl.classList.add('freeze-customer-4');
        } else {
            custTableEl.classList.remove('freeze-customer-4');
        }
    }

    const config = window.getTableColumnConfig('customer');
    const isVis = (k) => { const col = config.find(c => c.key === k); return col ? col.visible !== false : true; };
    const search = getMasterSearchQuery() || (document.getElementById('cust-search')?.value || '').toLowerCase();
    const tbody = document.getElementById('cust-table-body');
    if (!tbody) return;

    let data = db.customers.filter(c =>
        String(c.name || '').toLowerCase().includes(search) ||
        String(c.code || '').toLowerCase().includes(search) ||
        String(c.city || '').toLowerCase().includes(search) ||
        String(c.email || '').toLowerCase().includes(search) ||
        String(c.contactPerson || '').toLowerCase().includes(search) ||
        String(c.gst || '').toLowerCase().includes(search) ||
        String(c.mobile || '').toLowerCase().includes(search) ||
        String(c.phone || '').toLowerCase().includes(search) ||
        String(c.address || '').toLowerCase().includes(search) ||
        String(c.state || '').toLowerCase().includes(search)
    );

    const sortState = window.masterSortState?.customers || { col: 'name', dir: 'asc' };
    data.sort((a, b) => {
        let valA = (a[sortState.col] || '').toString().trim().toLowerCase();
        let valB = (b[sortState.col] || '').toString().trim().toLowerCase();
        return sortState.dir === 'asc' 
            ? valA.localeCompare(valB, undefined, { numeric: true, sensitivity: 'base' })
            : valB.localeCompare(valA, undefined, { numeric: true, sensitivity: 'base' });
    });

    const codeIcon = document.getElementById('sort-icon-cust-code');
    const nameIcon = document.getElementById('sort-icon-cust-name');
    if (codeIcon) codeIcon.innerHTML = sortState.col === 'code' ? (sortState.dir === 'asc' ? '&#9650;' : '&#9660;') : '&#8645;';
    if (nameIcon) nameIcon.innerHTML = sortState.col === 'name' ? (sortState.dir === 'asc' ? '&#9650;' : '&#9660;') : '&#8645;';

    if (!data.length) {
        tbody.innerHTML = '<tr><td colspan="11" class="empty-row">No customers found.</td></tr>';
        return;
    }

    const canWrite = checkPermission('masters', 'write');
    const canDelete = checkPermission('masters', 'delete');

    tbody.innerHTML = data.map((c, i) => {
        const rawGst = String(c.gst || '').trim();
        const hasValidGstNo = rawGst.length >= 5 && rawGst.toUpperCase() !== 'NA' && rawGst.toUpperCase() !== 'URP' && rawGst.toUpperCase() !== 'NONE' && rawGst.toUpperCase() !== 'UNREGISTERED';
        let gstTypeStr = c.gst_type || c.gstType || parseMetadataFromAddress(c.address, 'GST_TYPE');
        if (!gstTypeStr || (gstTypeStr === 'Unregistered' && hasValidGstNo)) {
            gstTypeStr = hasValidGstNo ? 'Regular' : 'Unregistered';
        }
        const panStr = c.pan || parseMetadataFromAddress(c.address, 'PAN') || (rawGst.length >= 12 ? rawGst.substring(2, 12).toUpperCase() : '-');
        const coPin = (currentCompany && currentCompany.pincode) ? String(currentCompany.pincode).trim() : '302001';
        const rawPin = c.pincode || c.pin_code || c.pinCode || parseMetadataFromAddress(c.address, 'PINCODE') || resolveSmartPincode(c.address, c.city, c.state);
        const pinStr = (rawPin && rawPin !== 'null') ? String(rawPin).trim() : '-';
        let rawDist = (c.distance !== undefined && c.distance !== null && c.distance !== '' && c.distance !== 'null') ? c.distance : (parseMetadataFromAddress(c.address, 'DISTANCE') || null);
        if ((rawDist === null || rawDist === undefined || rawDist === '') && pinStr !== '-' && /^\d{6}$/.test(pinStr)) {
            const cacheKey = coPin ? `${coPin}_${pinStr}` : pinStr;
            if (window.pincodeDistanceCache && (window.pincodeDistanceCache[cacheKey] || window.pincodeDistanceCache[pinStr])) {
                rawDist = window.pincodeDistanceCache[cacheKey] || window.pincodeDistanceCache[pinStr];
            } else if (window.calcAndCachePincodeDistance) {
                window.calcAndCachePincodeDistance(pinStr, coPin, cleanAddressStatus(c.address), c.city);
            }
        }
        const distStr = (rawDist !== null && rawDist !== undefined && rawDist !== '') ? `${rawDist} km` : '-';
        const tdsAppStr = (c.tds_applicable || c.tdsApplicable) ? 'Yes' : 'No';
        const tdsPolId = c.tds_policy || c.tdsPolicy;
        const tdsPolObj = window.resolveTdsPolicy ? window.resolveTdsPolicy(tdsPolId) : null;
        const tdsPolStr = tdsPolObj ? `${tdsPolObj.name} (${tdsPolObj.rate || 0}%)` : (tdsPolId || '-');

        return `
        <tr ondblclick="openCustomerModal('${c.id}')" title="Double-click to edit ${c.name}" style="${c.status === 'Cancelled' ? 'opacity: 0.6; background-color: rgba(225, 82, 65, 0.05);' : ''}">
            <td><input type="checkbox" class="chk-select-mst" value="${c.id}" onchange="toggleBulkDeleteButton('mst')"></td>
            <td>${i + 1}</td>
            ${isVis('code') ? `<td><span class="badge ${c.status === 'Cancelled' ? 'badge-red' : 'badge-blue'}">${c.code || '-'}</span></td>` : ''}
            ${isVis('name') ? `<td><strong onclick="openCustomerModal('${c.id}')" style="cursor: pointer; color: var(--primary, #4f7df5); text-decoration: underline;" title="Click to view details of ${c.name}">${c.name || '-'}</strong>${c.status === 'Cancelled' ? ' <span class="badge badge-red" style="font-size:10px; padding:2px 6px;">Cancelled</span>' : ''}</td>` : ''}
            ${isVis('gstType') ? `<td><span class="badge ${gstTypeStr === 'Regular' ? 'badge-green' : 'badge-amber'}">${gstTypeStr}</span></td>` : ''}
            ${isVis('gstin') ? `<td>${c.gst || '-'}</td>` : ''}
            ${isVis('pan') ? `<td>${panStr}</td>` : ''}
            ${isVis('address') ? `<td class="wrap-text">${cleanAddressStatus(c.address) || '-'}</td>` : ''}
            ${isVis('city') ? `<td>${c.city ? String(c.city).toUpperCase() : '-'}</td>` : ''}
            ${isVis('state') ? `<td>${c.state ? String(c.state).toUpperCase() : '-'}</td>` : ''}
            ${isVis('pincode') ? `<td><span style="font-weight: 600; color: var(--primary);">${pinStr}</span></td>` : ''}
            ${isVis('distance') ? `<td>${distStr}</td>` : ''}
            ${isVis('email') ? `<td>${c.email || '-'}</td>` : ''}
            ${isVis('phone') ? `<td>${c.contact || c.phone || c.mobile || '-'}</td>` : ''}
            ${isVis('contactPerson') ? `<td>${c.contactPerson || '-'}</td>` : ''}
            ${isVis('designation') ? `<td>${c.designation || '-'}</td>` : ''}
            ${isVis('tdsApplicable') ? `<td><span class="badge ${tdsAppStr === 'Yes' ? 'badge-purple' : 'badge-gray'}">${tdsAppStr}</span></td>` : ''}
            ${isVis('tdsPolicy') ? `<td>${tdsPolStr}</td>` : ''}
            <td>
                <div class="table-actions">
                    ${canWrite ? `<button class="btn btn-sm btn-secondary" onclick="openCustomerModal('${c.id}')"></button>` : ''}
                    ${canDelete ? `<button class="btn btn-sm btn-danger" onclick="deleteCustomer('${c.id}')">=�</button>` : ''}
                </div>
            </td>
        </tr>
        `;
    }).join('');
}

function openVendorModal(editId = null) {
    if (!checkPermission('masters', 'read') && !checkPermission('masters', 'write')) {
        showToast('Permission Denied', 'error');
        return;
    }
    populateVendorGroupDropdown();
    let v = null;
    if (editId) {
        v = (db.vendors || []).filter(x => x.id !== 'inhouse').find(x => String(x.id) === String(editId) || (x.name && x.name.trim().toLowerCase() === String(editId).trim().toLowerCase()) || (x.code && x.code.trim().toLowerCase() === String(editId).trim().toLowerCase()));
        if (v) editId = v.id;
    }
    document.getElementById('vend-edit-id').value = editId || '';
    
    const deleteBtn = document.getElementById('vend-btn-delete');
    const cancelRecBtn = document.getElementById('vend-btn-cancel-record');
    
    if (editId) {
        if (!v) v = db.vendors.find(x => String(x.id) === String(editId));
        if (v) {
            if (deleteBtn) deleteBtn.style.display = 'block';
            if (cancelRecBtn) {
                cancelRecBtn.style.display = 'block';
                if (v.status === 'Cancelled') {
                    cancelRecBtn.textContent = '=� Reactivate Vendor';
                    cancelRecBtn.style.background = 'rgba(46, 204, 113, 0.1)';
                    cancelRecBtn.style.color = '#2ecc71';
                    cancelRecBtn.style.border = '1px solid rgba(46, 204, 113, 0.3)';
                } else {
                    cancelRecBtn.textContent = '=� Cancel Vendor';
                    cancelRecBtn.style.background = 'rgba(230, 126, 34, 0.1)';
                    cancelRecBtn.style.color = '#d35400';
                    cancelRecBtn.style.border = '1px solid rgba(230, 126, 34, 0.3)';
                }
            }
            document.getElementById('vend-modal-title').textContent = 'Edit Vendor';
            const gstType = v.gst_type || parseMetadataFromAddress(v.address, 'GST_TYPE') || ((v.gst && v.gst.trim().toUpperCase() !== 'NA' && v.gst.trim().toUpperCase() !== 'URP') ? 'Regular' : 'Unregistered');
            const gstTypeEl = document.getElementById('vend-gst-type');
            if (gstTypeEl) gstTypeEl.value = gstType;
            if (typeof window.handleVendorGstTypeChange === 'function') {
                window.handleVendorGstTypeChange(gstType);
            }
            document.getElementById('vend-code').value = v.code;
            document.getElementById('vend-name').value = v.name;
            const groupEl = document.getElementById('vend-group');
            if (groupEl) groupEl.value = v.group || '';
            document.getElementById('vend-gst').value = v.gst || '';
            document.getElementById('vend-pan').value = v.pan || parseMetadataFromAddress(v.address, 'PAN') || ((v.gst && v.gst.length >= 12) ? v.gst.substring(2, 12).toUpperCase() : '');
            document.getElementById('vend-state').value = (v.state || '').toUpperCase();
            document.getElementById('vend-contact').value = v.contact || '';
            document.getElementById('vend-email').value = v.email || '';
            document.getElementById('vend-contact-person').value = v.contactPerson || '';
            document.getElementById('vend-designation').value = v.designation || '';
            document.getElementById('vend-city').value = (v.city || '').toUpperCase();
            let vendPin = (v.pincode && v.pincode !== 'null') ? String(v.pincode).trim() : (parseMetadataFromAddress(v.address, 'PINCODE') || resolveSmartPincode(v.address, v.city, v.state));
            document.getElementById('vend-pincode').value = vendPin;
            let vendDist = (v.distance !== undefined && v.distance !== null && v.distance !== '' && v.distance !== 'null') ? v.distance : '';
            if (!vendDist && v.address) {
                const tagDist = parseMetadataFromAddress(v.address, 'DISTANCE');
                if (tagDist) vendDist = tagDist;
            }
            if (!vendDist && vendPin && /^\d{6}$/.test(vendPin)) {
                const coPin = (currentCompany && currentCompany.pincode) ? String(currentCompany.pincode).trim() : '302001';
                const cacheKey = coPin ? `${coPin}_${vendPin}` : vendPin;
                if (window.pincodeDistanceCache && (window.pincodeDistanceCache[cacheKey] || window.pincodeDistanceCache[vendPin])) {
                    vendDist = window.pincodeDistanceCache[cacheKey] || window.pincodeDistanceCache[vendPin];
                } else if (window.calcAndCachePincodeDistance) {
                    window.calcAndCachePincodeDistance(vendPin, coPin, cleanAddressStatus(v.address), v.city);
                }
            }
            document.getElementById('vend-distance').value = vendDist;
            document.getElementById('vend-address').value = cleanAddressStatus(v.address || '');
            
            if (typeof window.populateCustomDropdowns === 'function') window.populateCustomDropdowns();
            const vendTdsAppEl = document.getElementById('vend-tds-applicable');
            const rawTdsPol = v.tds_policy || v.tdsPolicy || v.tds_policy_id || parseMetadataFromAddress(v.address, 'TDS_POLICY') || '';
            const resolvedTdsPol = window.resolveTdsPolicy ? window.resolveTdsPolicy(rawTdsPol) : null;
            if (vendTdsAppEl) {
                vendTdsAppEl.checked = (v.tds_applicable === true || v.tds_applicable === 'true' || parseMetadataFromAddress(v.address, 'TDS_APPLICABLE') === 'true' || !!resolvedTdsPol);
            }
            const vendTdsSel = document.getElementById('vend-tds-policy');
            if (vendTdsSel) {
                if (resolvedTdsPol) {
                    vendTdsSel.value = resolvedTdsPol.id;
                } else if (rawTdsPol) {
                    vendTdsSel.value = rawTdsPol;
                } else {
                    vendTdsSel.value = '';
                }
                if (vendTdsSel.value === '' && (vendTdsAppEl?.checked || rawTdsPol) && vendTdsSel.options.length > 1) {
                    const fallbackOpt = Array.from(vendTdsSel.options).find(opt => opt.value !== '');
                    if (fallbackOpt) vendTdsSel.value = fallbackOpt.value;
                }
            }
        }
    } else {
        if (deleteBtn) deleteBtn.style.display = 'none';
        if (cancelRecBtn) cancelRecBtn.style.display = 'none';
        document.getElementById('vend-modal-title').textContent = 'Add Vendor';
        const gstTypeEl = document.getElementById('vend-gst-type');
        if (gstTypeEl) gstTypeEl.value = 'Regular';
        const code = getNextVendorCode();
        document.getElementById('vend-code').value = code;
        document.getElementById('vend-name').value = '';
        const groupEl = document.getElementById('vend-group');
        if (groupEl) groupEl.value = '';
        document.getElementById('vend-gst').value = '';
        document.getElementById('vend-pan').value = '';
        document.getElementById('vend-state').value = '';
        document.getElementById('vend-contact').value = '';
        document.getElementById('vend-email').value = '';
        document.getElementById('vend-contact-person').value = '';
        document.getElementById('vend-designation').value = '';
        document.getElementById('vend-city').value = '';
        if (document.getElementById('vend-spec')) document.getElementById('vend-spec').value = '';
        document.getElementById('vend-pincode').value = '';
        document.getElementById('vend-distance').value = '';
        document.getElementById('vend-address').value = '';
        const vendTdsAppEl = document.getElementById('vend-tds-applicable');
        if (vendTdsAppEl) vendTdsAppEl.checked = false;
        document.getElementById('vend-tds-policy').value = '';
        if (typeof window.handleVendorGstTypeChange === 'function') {
            window.handleVendorGstTypeChange('Regular');
        }
    }
    const sel = document.getElementById('vend-group');
    if (sel) {
        reinitSearchableSelect(sel);
    }
    openModal('vend-modal');
}

async function saveVendor() {
    if (!checkPermission('masters', 'write')) {
        showToast('Permission Denied', 'error');
        return;
    }
    const name = document.getElementById('vend-name').value.trim();
    let gstType = document.getElementById('vend-gst-type')?.value || 'Regular';
    let gst = (document.getElementById('vend-gst')?.value || '').trim().replace(/\s+/g, '').toUpperCase();
    let panVal = (document.getElementById('vend-pan')?.value || '').trim().toUpperCase();
    const editId = (document.getElementById('vend-edit-id')?.value || '').trim();
    const editCode = (document.getElementById('vend-code')?.value || '').trim();

    if (!name) { 
        window._isSavingMaster = false;
        showToast('Vendor name is required', 'error'); 
        return; 
    }

    if (gstType === 'Unregistered') {
        gst = (gst && gst !== 'NA' && gst !== 'URP') ? gst : 'NA';
    } else {
        if (!gst || gst === 'NA' || gst === 'URP') {
            window._isSavingMaster = false;
            showToast(`GST Number is required when GST Registration Type is ${gstType}`, 'error');
            return;
        }
        if (gst.length !== 15) {
            window._isSavingMaster = false;
            showToast(`GST Number must be a valid 15-digit GSTIN for ${gstType} GST Registration Type.`, 'error');
            return;
        }
        if (!panVal && gst.length === 15) {
            panVal = gst.substring(2, 12).toUpperCase();
            const panInput = document.getElementById('vend-pan');
            if (panInput) panInput.value = panVal;
        }
    }

    db.vendors = db.vendors || [];
    const existingVend = editId ? db.vendors.find(v => 
        String(v.id).trim() === editId || 
        (editCode && v.code && String(v.code).trim().toLowerCase() === editCode.toLowerCase())
    ) : null;

    const targetEditId = existingVend ? existingVend.id : editId;
    const currentStatus = existingVend ? (existingVend.status || 'Active') : 'Active';

    const nameLower = name.toLowerCase();
    const gstLower = gst.toLowerCase();

    const curCompId = (existingVend && existingVend.company_id) || (currentCompany ? currentCompany.id : 'co4');
    const isSameCompany = (v) => !curCompId || !v.company_id || String(v.company_id) === String(curCompId);

    const isSelfRecord = (v) => {
        if (!targetEditId) return false;
        return String(v.id).trim() === String(targetEditId).trim();
    };

    const isNameChanged = existingVend ? ((existingVend.name || '').trim().toLowerCase() !== nameLower) : true;
    const isGstChanged = existingVend ? ((existingVend.gst || '').trim().toUpperCase() !== gst.toUpperCase()) : true;

    const dupNameVend = isNameChanged ? (db.vendors || []).find(v => 
        !isSelfRecord(v) && 
        isSameCompany(v) && 
        v.name && v.name.trim().toLowerCase() === nameLower
    ) : null;

    const dupGstVend = isGstChanged && (gstLower && gstLower !== 'na' && gstLower !== 'urp') ? (db.vendors || []).find(v => 
        !isSelfRecord(v) && 
        isSameCompany(v) && 
        v.gst && v.gst.trim().toLowerCase() === gstLower
    ) : null;

    if (dupNameVend) {
        showToast(`A vendor with this Name already exists: ${dupNameVend.code ? dupNameVend.code + ' (' : ''}${dupNameVend.name}${dupNameVend.code ? ')' : ''}`, 'error');
        return;
    }
    if (dupGstVend) {
        showToast(`A vendor with this GST Number already exists: ${dupGstVend.code ? dupGstVend.code + ' (' : ''}${dupGstVend.name}${dupGstVend.code ? ')' : ''}`, 'error');
        return;
    }
    
    let pinVal = document.getElementById('vend-pincode')?.value.trim() || '';
    let cleanAddr = cleanAddressStatus((document.getElementById('vend-address')?.value || '').trim());

    let vendDistVal = document.getElementById('vend-distance')?.value.trim() || '';
    if (vendDistVal === '' && pinVal && /^\d{6}$/.test(pinVal)) {
        const coPin = (currentCompany && currentCompany.pincode) ? String(currentCompany.pincode).trim() : '302001';
        const vendCity = document.getElementById('vend-city') ? document.getElementById('vend-city').value.trim() : '';
        await window.calcAndCachePincodeDistance(pinVal, coPin, cleanAddr, vendCity);
        const cacheKey = coPin ? `${coPin}_${pinVal}` : pinVal;
        const calcDist = window.pincodeDistanceCache ? (window.pincodeDistanceCache[cacheKey] || window.pincodeDistanceCache[pinVal]) : null;
        if (calcDist !== null && calcDist !== undefined) {
            vendDistVal = String(calcDist);
            const distEl = document.getElementById('vend-distance');
            if (distEl) distEl.value = vendDistVal;
        }
    }
    const tdsApp = document.getElementById('vend-tds-applicable')?.checked || false;
    const tdsPol = document.getElementById('vend-tds-policy')?.value || '';

    const taggedAddr = buildTaggedAddress({
        address: cleanAddr,
        status: currentStatus,
        gst_type: gstType,
        pan: panVal,
        pincode: pinVal,
        distance: vendDistVal,
        tds_applicable: tdsApp,
        tds_policy: tdsPol
    });

    const data = {
        id: targetEditId || uid(),
        company_id: curCompId,
        code: editCode || (existingVend ? existingVend.code : getNextVendorCode()),
        name,
        gst,
        group: document.getElementById('vend-group') ? document.getElementById('vend-group').value : '',
        contact: (document.getElementById('vend-contact')?.value || '').trim(),
        email: (document.getElementById('vend-email')?.value || '').trim(),
        contactPerson: (document.getElementById('vend-contact-person')?.value || '').trim(),
        designation: (document.getElementById('vend-designation')?.value || '').trim(),
        city: (document.getElementById('vend-city')?.value || '').trim().toUpperCase(),
        spec: (document.getElementById('vend-spec')?.value || '').trim(),
        pincode: pinVal,
        distance: vendDistVal === '' ? null : (parseFloat(vendDistVal) || 0),
        address: taggedAddr,
        tds_applicable: tdsApp,
        tds_policy: tdsPol || null,
        state: (document.getElementById('vend-state')?.value || '').trim().toUpperCase(),
        pan: panVal,
        gst_type: gstType,
        status: currentStatus
    };

    try {
        await saveToSupabase('vendors', data);
        const memData = { ...data, address: cleanAddr };

        if (targetEditId && existingVend) {
            const oldName = existingVend ? existingVend.name : '';
            const idx = db.vendors.findIndex(v => String(v.id).trim() === String(targetEditId).trim() || (v.code && String(v.code).trim().toLowerCase() === memData.code.toLowerCase()));
            if (idx !== -1) {
                db.vendors[idx] = memData;
            } else {
                db.vendors.push(memData);
            }

            if (oldName && oldName.trim().toLowerCase() !== name.trim().toLowerCase()) {
                const oldLower = oldName.trim().toLowerCase();
                const cascadePromises = [];
                (db.pos || []).forEach(po => {
                    if (String(po.vendorId) === String(targetEditId) || String(po.vendor) === String(targetEditId) || (po.vendorName && po.vendorName.trim().toLowerCase() === oldLower)) {
                        po.vendorName = name;
                        cascadePromises.push(saveToSupabase('purchase_orders', po).catch(console.error));
                    }
                });
                (db.outwards || []).forEach(out => {
                    if (String(out.vendorId) === String(targetEditId) || String(out.vendor_id) === String(targetEditId) || (out.vendorName && out.vendorName.trim().toLowerCase() === oldLower)) {
                        out.vendorName = name;
                        out.vendor_name = name;
                    }
                });
                (db.grns || []).forEach(grn => {
                    if (String(grn.vendorId) === String(targetEditId) || String(grn.vendor) === String(targetEditId) || (grn.vendorName && grn.vendorName.trim().toLowerCase() === oldLower)) {
                        grn.vendorName = name;
                    }
                });
                (db.purchases || []).forEach(pur => {
                    if (String(pur.vendorId) === String(targetEditId) || (pur.vendorName && pur.vendorName.trim().toLowerCase() === oldLower)) {
                        pur.vendorName = name;
                    }
                });
                (db.genericTransactions || []).forEach(gtx => {
                    if (String(gtx.partyId) === String(targetEditId) || (gtx.partyName && gtx.partyName.trim().toLowerCase() === oldLower)) {
                        gtx.partyName = name;
                    }
                });
                if (cascadePromises.length > 0) {
                    await Promise.all(cascadePromises);
                }
            }

            logUserAction('Masters', 'Modified', `Updated vendor: ${name}`);
            showToast('Vendor updated successfully', 'success');
        } else {
            db.vendors = db.vendors || [];
            const existingIdx = db.vendors.findIndex(v => String(v.id).trim() === String(memData.id).trim() || (v.code && String(v.code).trim().toLowerCase() === memData.code.toLowerCase()));
            if (existingIdx !== -1) {
                db.vendors[existingIdx] = memData;
            } else {
                db.vendors.push(memData);
            }
            logUserAction('Masters', 'Created', `Created vendor: ${name}`);
            showToast('Vendor added successfully', 'success');
        }
        closeModal('vend-modal', true);
        renderVendorTable();
        populateAllDropdowns();
        if (typeof window.updateLocalDBCache === 'function') {
            window.updateLocalDBCache();
        }
    } catch(e) {
        console.error("Error saving vendor:", e);
        showToast('Failed to save vendor: ' + (e.message || e), 'error');
    }
}
window.saveVendor = saveVendor;
window.openVendorModal = openVendorModal;
window.openVendorModalByName = function(nameOrId) {
    if (!nameOrId) return;
    const v = (db.vendors || []).filter(x => x.id !== 'inhouse').find(x => 
        String(x.id) === String(nameOrId) || 
        (x.name && x.name.trim().toLowerCase() === String(nameOrId).trim().toLowerCase()) || 
        (x.code && x.code.trim().toLowerCase() === String(nameOrId).trim().toLowerCase())
    );
    if (v) {
        openVendorModal(v.id);
    } else {
        showToast(`Vendor details for "${nameOrId}" not found`, 'info');
    }
};

window.handleVendorGstInput = function(val) {
    if (!val) {
        document.getElementById('vend-pan').value = '';
        document.getElementById('vend-state').value = '';
        return;
    }
    const cleanGst = val.trim().toUpperCase();
    
    // Extract PAN (characters 3 to 12)
    if (cleanGst.length >= 10) {
        const pan = cleanGst.substring(2, 12);
        // Standard PAN format: 5 letters, 4 digits, 1 letter
        if (/^[A-Z]{5}[0-9]{4}[A-Z]{1}$/.test(pan)) {
            document.getElementById('vend-pan').value = pan;
        } else {
            document.getElementById('vend-pan').value = cleanGst.length >= 12 ? pan : '';
        }
    } else {
        document.getElementById('vend-pan').value = '';
    }

    // Extract State Code (first 2 digits)
    if (cleanGst.length >= 2) {
        const stateCode = cleanGst.substring(0, 2);
        const GST_STATE_CODES = {
            "01": "JAMMU & KASHMIR", "02": "HIMACHAL PRADESH", "03": "PUNJAB", "04": "CHANDIGARH", "05": "UTTARAKHAND",
            "06": "HARYANA", "07": "DELHI", "08": "RAJASTHAN", "09": "UTTAR PRADESH", "10": "BIHAR",
            "11": "SIKKIM", "12": "ARUNACHAL PRADESH", "13": "NAGALAND", "14": "MANIPUR", "15": "MIZORAM",
            "16": "TRIPURA", "17": "MEGHALAYA", "18": "ASSAM", "19": "WEST BENGAL", "20": "JHARKHAND",
            "21": "ODISHA", "22": "CHHATTISGARH", "23": "MADHYA PRADESH", "24": "GUJARAT", "26": "DADRA AND NAGAR HAVELI AND DAMAN AND DIU",
            "27": "MAHARASHTRA", "29": "KARNATAKA", "30": "GOA", "31": "LAKSHADWEEP", "32": "KERALA",
            "33": "TAMIL NADU", "34": "PUDUCHERRY", "35": "ANDAMAN & NICOBAR ISLANDS", "36": "TELANGANA", "37": "ANDHRA PRADESH",
            "38": "LADAKH", "97": "OTHER TERRITORY"
        };
        const stateName = GST_STATE_CODES[stateCode];
        if (stateName) {
            document.getElementById('vend-state').value = stateName.toUpperCase();
        }
    } else {
        document.getElementById('vend-state').value = '';
    }
};

window.deleteVendorFromModal = async function() {
    const editId = document.getElementById('vend-edit-id').value;
    if (!editId) return;
    const ok = await deleteVendor(editId);
    if (ok) {
        closeModal('vend-modal', true);
    }
};

window.cancelVendorFromModal = async function() {
    const editId = document.getElementById('vend-edit-id').value;
    if (!editId) return;
    const v = db.vendors.find(x => x.id === editId);
    if (!v) return;
    
    const newStatus = v.status === 'Cancelled' ? 'Active' : 'Cancelled';
    if (newStatus === 'Cancelled') {
        const refs = window.getPartyReferences(editId, 'Vendor');
        if (refs.length > 0) {
            window.showReferenceResolutionModal(editId, 'Vendor', 'cancel', () => cancelVendorFromModal());
            return;
        }
    }

    const confirmMsg = newStatus === 'Cancelled' 
        ? 'Cancel this vendor? The vendor code series will not be disturbed.' 
        : 'Reactivate this vendor?';
    if (!(await window.showSmartConfirm('Confirm Saving', confirmMsg))) return;
    
    v.status = newStatus;
    
    const cleanAddr = cleanAddressStatus(document.getElementById('vend-address').value.trim());
    let rawAddress = cleanAddr;
    if (newStatus !== 'Active') {
        rawAddress += `\n[STATUS:${newStatus}]`;
    }
    const gstType = document.getElementById('vend-gst-type') ? document.getElementById('vend-gst-type').value : (v.gst_type || 'Regular');
    const panVal = document.getElementById('vend-pan').value.trim() || v.pan || '';
    let pinVal = document.getElementById('vend-pincode')?.value.trim() || v.pincode || resolveSmartPincode(cleanAddr, document.getElementById('vend-city')?.value.trim() || v.city, document.getElementById('vend-state')?.value.trim() || v.state);
    const tdsApp = document.getElementById('vend-tds-applicable') ? document.getElementById('vend-tds-applicable').checked : (v.tds_applicable || false);
    const tdsPol = document.getElementById('vend-tds-policy') ? document.getElementById('vend-tds-policy').value : (v.tds_policy || '');
    
    const data = {
        id: v.id,
        code: v.code,
        name: document.getElementById('vend-name').value.trim() || v.name,
        gst: document.getElementById('vend-gst').value.trim(),
        group: document.getElementById('vend-group') ? document.getElementById('vend-group').value : '',
        contact: document.getElementById('vend-contact').value.trim(),
        email: document.getElementById('vend-email').value.trim(),
        contactPerson: document.getElementById('vend-contact-person').value.trim(),
        designation: document.getElementById('vend-designation').value.trim(),
        city: document.getElementById('vend-city').value.trim().toUpperCase(),
        spec: (document.getElementById('vend-spec')?.value || '').trim(),
        pincode: pinVal,
        distance: parseFloat(document.getElementById('vend-distance').value) || null,
        address: rawAddress,
        tds_applicable: tdsApp,
        tds_policy: tdsPol || null,
        state: document.getElementById('vend-state').value.trim().toUpperCase(),
        pan: panVal,
        gst_type: gstType
    };
    
    try {
        await saveToSupabase('vendors', data);
        const idx = db.vendors.findIndex(x => x.id === editId);
        if (idx !== -1) {
            data.status = newStatus;
            data.gst_type = gstType;
            data.pan = panVal;
            data.pincode = pinVal;
            data.address = cleanAddressStatus(rawAddress);
            db.vendors[idx] = data;
        }
        logUserAction('Masters', 'Modified', `Vendor status changed to ${newStatus}: ${v.name}`);
        showToast(`Vendor status changed to ${newStatus}`, 'success');
        closeModal('vend-modal', true);
        renderVendorTable();
    } catch(e) {
        showToast('Operation failed', 'error');
    }
};

function checkVendorReferences(vendorId) {
    const vend = db.vendors.find(x => x.id === vendorId);
    if (!vend) return null;
    const lowerName = vend.name.trim().toLowerCase();
    
    if ((db.pos || []).some(po => po.vendorId === vendorId || po.vendor === vendorId || String(po.vendorName).toLowerCase() === lowerName)) {
        return 'Purchase Orders';
    }
    if ((db.grns || []).some(grn => {
        if (grn.status === 'Cancelled') return false;
        const docNo = String(grn.grnNo || grn.number || grn.partyDocNo || '').toUpperCase();
        const grnType = String(grn.type || grn.grnType || grn.source || '').toLowerCase();
        const isVendorSource = docNo.includes('/V/') || docNo.startsWith('GRN/V') || grnType === 'vendor' || grnType.includes('vend') || grn.source === 'vendor' || grnType.includes('con') || grnType.includes('oth') || docNo.startsWith('GRN/CON') || docNo.startsWith('GRN/OTH');
        if (isVendorSource) {
            return grn.vendorId === vendorId || (grn.vendorName && grn.vendorName.trim().toLowerCase() === lowerName);
        }
        return false;
    })) {
        return 'GRNs';
    }
    if ((db.outwards || []).some(out => {
        if (out.status === 'Cancelled') return false;
        let outVendId = out.vendorId || out.vendor_id || '';
        let outVendName = out.vendorName || out.vendor_name || '';
        if (out.remarks) {
            const match = out.remarks.match(/\[WIZARD:(\{.*?\})\]/);
            if (match) {
                try {
                    const wiz = JSON.parse(match[1]);
                    if (wiz.vendorId) outVendId = wiz.vendorId;
                    if (wiz.vendorName) outVendName = wiz.vendorName;
                } catch(e){}
            }
        }
        const poId = out.linked_po_id || out.poRefId || out.po_ref;
        if (poId && db.pos) {
            const po = db.pos.find(p => p.id === poId || p.number === poId);
            if (po) {
                if (po.vendorId || po.vendor) outVendId = po.vendorId || po.vendor;
                if (po.vendorName) outVendName = po.vendorName;
            }
        }
        return (outVendId && outVendId === vendorId) || 
               (outVendName && outVendName.trim().toLowerCase() === lowerName && outVendName.toLowerCase() !== 'customer' && outVendName.toLowerCase() !== 'vendor');
    })) {
        return 'Outwards / Fabric Issue Challans';
    }
    if ((db.genericTransactions || []).some(gt => {
        if (gt.status === 'Cancelled') return false;
        if (gt.partyId === vendorId && (gt.type === 'purchasereturn' || gt.type === 'voucher')) {
            return true;
        }
        if (gt.partyName && gt.partyName.trim().toLowerCase() === lowerName && (gt.type === 'purchasereturn' || gt.type === 'voucher')) {
            return true;
        }
        return false;
    })) {
        return 'Invoices/Vouchers/Returns';
    }
    return null;
}
window.checkVendorReferences = checkVendorReferences;

async function deleteVendor(id) {
    if (!checkPermission('masters', 'delete')) {
        showToast('Permission Denied', 'error');
        return false;
    }
    const v = db.vendors.find(x => x.id === id);
    if (!v) return false;
    const name = v.name;
    
    const refs = window.getPartyReferences(id, 'Vendor');
    if (refs.length > 0) {
        window.showReferenceResolutionModal(id, 'Vendor', 'delete', () => deleteVendor(id));
        return false;
    }

    if (!(await window.showSmartConfirm('Delete Vendor', 'Are you sure you want to delete this vendor?'))) return false;
    try {
        await deleteFromSupabase('vendors', id);
        db.vendors = db.vendors.filter(v => v.id !== id);
        renderVendorTable();
        logUserAction('Masters', 'Deleted', `Deleted vendor: ${name}`);
        showToast('Vendor deleted', 'info');
        return true;
    } catch(e) {
        showToast(`Delete failed: ${e.message || e}`, 'error');
        return false;
    }
}

function renderVendorTable() {
    db.vendors = db.vendors || [];
    renderDynamicHeader('vendor', 'vend-table-head');

    const vendTableEl = document.getElementById('vend-table') || document.querySelector('#vend-table-head')?.closest('table');
    const isFreezeVendor = localStorage.getItem('freeze_first_4_customer') === 'true';
    if (vendTableEl) {
        vendTableEl.classList.remove('freeze-first-3');
        if (isFreezeVendor) {
            vendTableEl.classList.add('freeze-customer-4');
        } else {
            vendTableEl.classList.remove('freeze-customer-4');
        }
    }
    const config = window.getTableColumnConfig('vendor');
    const isVis = (k) => { const col = config.find(c => c.key === k); return col ? col.visible !== false : true; };
    const search = getMasterSearchQuery() || (document.getElementById('vend-search')?.value || '').toLowerCase();
    const tbody = document.getElementById('vend-table-body');
    if (!tbody) return;

    const activeSubModal = document.getElementById('masters-submodal-vendors');
    const filterEl = activeSubModal ? activeSubModal.querySelector('#vendor-group-filter') : document.getElementById('vendor-group-filter');
    const selectedGroup = filterEl ? (filterEl.value || '').trim().toLowerCase() : '';

    let data = db.vendors.filter(v => v.id !== 'inhouse' && v.status !== 'Cancelled').filter(v => {
        if (selectedGroup && String(v.group || '').trim().toLowerCase() !== selectedGroup) {
            return false;
        }
        return String(v.name || '').toLowerCase().includes(search) ||
            String(v.code || '').toLowerCase().includes(search) ||
            String(v.spec || '').toLowerCase().includes(search) ||
            String(v.email || '').toLowerCase().includes(search) ||
            String(v.city || '').toLowerCase().includes(search) ||
            String(v.mobile || '').toLowerCase().includes(search) ||
            String(v.phone || '').toLowerCase().includes(search) ||
            String(v.gst || '').toLowerCase().includes(search) ||
            String(v.address || '').toLowerCase().includes(search) ||
            String(v.state || '').toLowerCase().includes(search) ||
            String(v.contactPerson || '').toLowerCase().includes(search);
    });

    const sortState = window.masterSortState?.vendors || { col: 'name', dir: 'asc' };
    data.sort((a, b) => {
        let valA = (a[sortState.col] || '').toString().trim().toLowerCase();
        let valB = (b[sortState.col] || '').toString().trim().toLowerCase();
        return sortState.dir === 'asc' 
            ? valA.localeCompare(valB, undefined, { numeric: true, sensitivity: 'base' })
            : valB.localeCompare(valA, undefined, { numeric: true, sensitivity: 'base' });
    });

    const codeIcon = document.getElementById('sort-icon-vend-code');
    const nameIcon = document.getElementById('sort-icon-vend-name');
    if (codeIcon) codeIcon.innerHTML = sortState.col === 'code' ? (sortState.dir === 'asc' ? '&#9650;' : '&#9660;') : '&#8645;';
    if (nameIcon) nameIcon.innerHTML = sortState.col === 'name' ? (sortState.dir === 'asc' ? '&#9650;' : '&#9660;') : '&#8645;';

    if (!data.length) {
        tbody.innerHTML = '<tr><td colspan="11" class="empty-row">No vendors found.</td></tr>';
        return;
    }

    const canWrite = checkPermission('masters', 'write');
    const canDelete = checkPermission('masters', 'delete');

    tbody.innerHTML = data.map((v, i) => {
        const rawGst = String(v.gst || '').trim();
        const hasValidGstNo = rawGst.length >= 5 && rawGst.toUpperCase() !== 'NA' && rawGst.toUpperCase() !== 'URP' && rawGst.toUpperCase() !== 'NONE' && rawGst.toUpperCase() !== 'UNREGISTERED';
        let gstTypeStr = v.gst_type || v.gstType || parseMetadataFromAddress(v.address, 'GST_TYPE');
        if (!gstTypeStr || (gstTypeStr === 'Unregistered' && hasValidGstNo)) {
            gstTypeStr = hasValidGstNo ? 'Regular' : 'Unregistered';
        }
        const panStr = v.pan || parseMetadataFromAddress(v.address, 'PAN') || (rawGst.length >= 12 ? rawGst.substring(2, 12).toUpperCase() : '-');
        const coPin = (currentCompany && currentCompany.pincode) ? String(currentCompany.pincode).trim() : '302001';
        const rawPin = v.pincode || v.pin_code || v.pinCode || parseMetadataFromAddress(v.address, 'PINCODE') || resolveSmartPincode(v.address, v.city, v.state);
        const pinStr = (rawPin && rawPin !== 'null') ? String(rawPin).trim() : '-';
        let rawDist = (v.distance !== undefined && v.distance !== null && v.distance !== '' && v.distance !== 'null') ? v.distance : (parseMetadataFromAddress(v.address, 'DISTANCE') || null);
        if ((rawDist === null || rawDist === undefined || rawDist === '') && pinStr !== '-' && /^\d{6}$/.test(pinStr)) {
            const cacheKey = coPin ? `${coPin}_${pinStr}` : pinStr;
            if (window.pincodeDistanceCache && (window.pincodeDistanceCache[cacheKey] || window.pincodeDistanceCache[pinStr])) {
                rawDist = window.pincodeDistanceCache[cacheKey] || window.pincodeDistanceCache[pinStr];
            } else if (window.calcAndCachePincodeDistance) {
                window.calcAndCachePincodeDistance(pinStr, coPin, cleanAddressStatus(v.address), v.city);
            }
        }
        const distStr = (rawDist !== null && rawDist !== undefined && rawDist !== '') ? `${rawDist} km` : '-';
        const tdsAppStr = (v.tds_applicable || v.tdsApplicable) ? 'Yes' : 'No';
        const tdsPolId = v.tds_policy || v.tdsPolicy;
        const tdsPolObj = window.resolveTdsPolicy ? window.resolveTdsPolicy(tdsPolId) : null;
        const tdsPolStr = tdsPolObj ? `${tdsPolObj.name} (${tdsPolObj.rate || 0}%)` : (tdsPolId || '-');

        return `
        <tr ondblclick="openVendorModal('${v.id}')" title="Double-click to edit ${v.name}" style="${v.status === 'Cancelled' ? 'opacity: 0.6; background-color: rgba(225, 82, 65, 0.05);' : ''}">
            <td><input type="checkbox" class="chk-select-mst" value="${v.id}" onchange="toggleBulkDeleteButton('mst')"></td>
            <td>${i + 1}</td>
            ${isVis('code') ? `<td><span class="badge ${v.status === 'Cancelled' ? 'badge-red' : 'badge-green'}">${v.code || '-'}</span></td>` : ''}
            ${isVis('name') ? `<td><strong onclick="openVendorModal('${v.id}')" style="cursor: pointer; color: var(--primary, #4f7df5); text-decoration: underline;" title="Click to view details of ${v.name}">${v.name || '-'}</strong>${v.status === 'Cancelled' ? ' <span class="badge badge-red" style="font-size:10px; padding:2px 6px;">Cancelled</span>' : ''}</td>` : ''}
            ${isVis('group') ? `<td><span class="badge badge-purple">${v.group || '-'}</span></td>` : ''}
            ${isVis('gstType') ? `<td><span class="badge ${gstTypeStr === 'Regular' ? 'badge-green' : 'badge-amber'}">${gstTypeStr}</span></td>` : ''}
            ${isVis('gstin') ? `<td>${v.gst || '-'}</td>` : ''}
            ${isVis('pan') ? `<td>${panStr}</td>` : ''}
            ${isVis('address') ? `<td class="wrap-text">${cleanAddressStatus(v.address) || '-'}</td>` : ''}
            ${isVis('city') ? `<td>${v.city ? String(v.city).toUpperCase() : '-'}</td>` : ''}
            ${isVis('state') ? `<td>${v.state ? String(v.state).toUpperCase() : '-'}</td>` : ''}
            ${isVis('pincode') ? `<td><span style="font-weight: 600; color: var(--primary);">${pinStr}</span></td>` : ''}
            ${isVis('distance') ? `<td>${distStr}</td>` : ''}
            ${isVis('email') ? `<td>${v.email || '-'}</td>` : ''}
            ${isVis('phone') ? `<td>${v.contact || v.phone || v.mobile || '-'}</td>` : ''}
            ${isVis('contactPerson') ? `<td>${v.contactPerson || '-'}</td>` : ''}
            ${isVis('designation') ? `<td>${v.designation || '-'}</td>` : ''}
            ${isVis('tdsApplicable') ? `<td><span class="badge ${tdsAppStr === 'Yes' ? 'badge-purple' : 'badge-gray'}">${tdsAppStr}</span></td>` : ''}
            ${isVis('tdsPolicy') ? `<td>${tdsPolStr}</td>` : ''}
            <td>
                <div class="table-actions">
                    ${canWrite ? `<button class="btn btn-sm btn-secondary" onclick="openVendorModal('${v.id}')"></button>` : ''}
                    ${canDelete ? `<button class="btn btn-sm btn-danger" onclick="deleteVendor('${v.id}')">=�</button>` : ''}
                </div>
            </td>
        </tr>
        `;
    }).join('');
}

// ===== TRANSPORTER MASTER =====
function openTransporterModal(editId = null) {
    if (!checkPermission('masters', 'write')) {
        showToast('Permission Denied', 'error');
        return;
    }
    document.getElementById('trans-edit-id').value = editId || '';
    if (editId) {
        const t = db.transporters.find(x => x.id === editId);
        if (t) {
            document.getElementById('trans-modal-title').textContent = 'Edit Transporter';
            document.getElementById('trans-code').value = t.code || `TRN-${String(db.transporters.findIndex(x=>x.id===editId)+1).padStart(3,'0')}`;
            document.getElementById('trans-name').value = t.name;
            document.getElementById('trans-gst').value = t.gst || '';
            document.getElementById('trans-mobile').value = t.mobile || '';
            document.getElementById('trans-email').value = t.email || '';
            document.getElementById('trans-contact-person').value = t.contactPerson || '';
            document.getElementById('trans-designation').value = t.designation || '';
            
            // Extract distance, pincode, city, state from record & address
            let addr = t.address || '';
            let dist = (t.distance !== undefined && t.distance !== null && t.distance !== '' && t.distance !== 'null') ? t.distance : (parseMetadataFromAddress(addr, 'DISTANCE') || '');
            let pin = (t.pincode && t.pincode !== 'null') ? String(t.pincode).trim() : (parseMetadataFromAddress(addr, 'PINCODE') || resolveSmartPincode(addr, t.city, t.state));
            let city = t.city || parseMetadataFromAddress(addr, 'CITY') || '';
            let state = t.state || parseMetadataFromAddress(addr, 'STATE') || '';

            // Clean all metadata tags out of address display so text field shows clean address
            addr = addr.replace(/\[Distance:\s*(.*?)\s*\]/gi, '')
                       .replace(/\[DISTANCE:\s*(.*?)\s*\]/gi, '')
                       .replace(/\[PIN:\s*(.*?)\s*\]/gi, '')
                       .replace(/\[PINCODE:\s*(.*?)\s*\]/gi, '')
                       .replace(/\[CITY:\s*(.*?)\s*\]/gi, '')
                       .replace(/\[STATE:\s*(.*?)\s*\]/gi, '')
                       .replace(/\[STATUS:[^\]]+\]/gi, '')
                       .trim();

            document.getElementById('trans-address').value = addr;
            document.getElementById('trans-distance').value = dist || '';
            if (document.getElementById('trans-state')) document.getElementById('trans-state').value = (state || '').toUpperCase();
            if (document.getElementById('trans-city')) document.getElementById('trans-city').value = (city || '').toUpperCase();
            if (document.getElementById('trans-pincode')) {
                document.getElementById('trans-pincode').value = pin || '';
                if (pin && typeof window.handlePincodeAutoFetch === 'function') {
                    window.handlePincodeAutoFetch('trans', pin);
                }
            }
        }
    } else {
        document.getElementById('trans-modal-title').textContent = 'Add Transporter';
        document.getElementById('trans-code').value = `TRN-${String(db.transporters.length + 1).padStart(3,'0')}`;
        document.getElementById('trans-name').value = '';
        document.getElementById('trans-gst').value = '';
        document.getElementById('trans-mobile').value = '';
        document.getElementById('trans-email').value = '';
        document.getElementById('trans-contact-person').value = '';
        document.getElementById('trans-designation').value = '';
        document.getElementById('trans-address').value = '';
        document.getElementById('trans-distance').value = '';
        if (document.getElementById('trans-pincode')) document.getElementById('trans-pincode').value = '';
        if (document.getElementById('trans-state')) document.getElementById('trans-state').value = '';
        if (document.getElementById('trans-city')) document.getElementById('trans-city').value = '';
    }
    openModal('trans-modal');
}

window.onTransporterPincodeInput = async function(pinVal) {
    const cleanPin = (pinVal || '').trim();
    if (cleanPin.length === 6 && /^[1-9][0-9]{5}$/.test(cleanPin)) {
        const companies = [
            ...(typeof masterDB !== 'undefined' && masterDB?.companies || []),
            ...(typeof db !== 'undefined' && db?.companies || []),
            ...(window.crossCompanyCompanies || [])
        ];
        const sourceCompany = (typeof currentCompany !== 'undefined' && currentCompany) ? currentCompany : null;
        const coPin = sourceCompany && sourceCompany.pincode ? String(sourceCompany.pincode).trim() : '302022';
        
        if (coPin === cleanPin) {
            if (document.getElementById('trans-distance')) document.getElementById('trans-distance').value = '0';
            return;
        }

        const cacheKey = `${coPin}_${cleanPin}`;
        if (window.pincodeDistanceCache && window.pincodeDistanceCache[cacheKey]) {
            const cachedDist = parseFloat(window.pincodeDistanceCache[cacheKey]);
            if (!isNaN(cachedDist)) {
                if (document.getElementById('trans-distance')) document.getElementById('trans-distance').value = cachedDist;
                return;
            }
        }

        const addrVal = document.getElementById('trans-address') ? document.getElementById('trans-address').value : '';
        if (typeof window.calcAndCachePincodeDistance === 'function') {
            await window.calcAndCachePincodeDistance(cleanPin, coPin, addrVal);
            if (window.pincodeDistanceCache && window.pincodeDistanceCache[cacheKey]) {
                const distVal = parseFloat(window.pincodeDistanceCache[cacheKey]);
                if (!isNaN(distVal) && distVal > 0) {
                    if (document.getElementById('trans-distance')) document.getElementById('trans-distance').value = distVal;
                }
            }
        }
    }
};

async function saveTransporter() {
    if (!checkPermission('masters', 'write')) {
        showToast('Permission Denied', 'error');
        return;
    }
    const name = document.getElementById('trans-name').value.trim();
    const editId = document.getElementById('trans-edit-id').value;
    if (!name) { showToast('Transporter name is required', 'error'); return; }

    const nameLower = name.toLowerCase();
    const gstLower = document.getElementById('trans-gst').value.trim().toLowerCase();
    const duplicate = (db.transporters || []).some(t => t.id !== editId && (
        t.name.toLowerCase() === nameLower ||
        (gstLower && t.gst && t.gst.toLowerCase() === gstLower)
    ));
    if (duplicate) {
        showToast('A transporter with this Name or GST Number already exists.', 'error');
        return;
    }

    let address = document.getElementById('trans-address').value.trim();
    const distanceVal = document.getElementById('trans-distance').value.trim();
    const pincodeVal = document.getElementById('trans-pincode') ? document.getElementById('trans-pincode').value.trim() : '';
    const stateVal = document.getElementById('trans-state') ? document.getElementById('trans-state').value.trim() : '';
    const cityVal = document.getElementById('trans-city') ? document.getElementById('trans-city').value.trim() : '';

    address = address
        .replace(/\[Distance:\s*(.*?)\s*\]/gi, '')
        .replace(/\[DISTANCE:\s*(.*?)\s*\]/gi, '')
        .replace(/\[PIN:\s*(.*?)\s*\]/gi, '')
        .replace(/\[PINCODE:\s*(.*?)\s*\]/gi, '')
        .replace(/\[CITY:\s*(.*?)\s*\]/gi, '')
        .replace(/\[STATE:\s*(.*?)\s*\]/gi, '')
        .replace(/\[STATUS:[^\]]+\]/gi, '')
        .trim();

    if (pincodeVal) {
        address = address + (address ? ' ' : '') + `[PINCODE: ${pincodeVal}]`;
    }
    if (distanceVal) {
        address = address + (address ? ' ' : '') + `[DISTANCE: ${distanceVal}]`;
    }
    if (cityVal) {
        address = address + (address ? ' ' : '') + `[CITY: ${cityVal}]`;
    }
    if (stateVal) {
        address = address + (address ? ' ' : '') + `[STATE: ${stateVal}]`;
    }

    const data = {
        id: editId || uid(),
        company_id: (currentCompany ? currentCompany.id : 'co4'),
        code: document.getElementById('trans-code').value,
        name,
        gst: document.getElementById('trans-gst').value.trim(),
        mobile: document.getElementById('trans-mobile').value.trim(),
        email: document.getElementById('trans-email').value.trim(),
        contactPerson: document.getElementById('trans-contact-person').value.trim(),
        designation: document.getElementById('trans-designation').value.trim(),
        pincode: pincodeVal,
        distance: distanceVal ? (parseFloat(distanceVal) || null) : null,
        city: cityVal,
        state: stateVal,
        address: address
    };

    try {
        await saveToSupabase('transporters', data);
        if (editId) {
            const idx = db.transporters.findIndex(t => t.id === editId);
            if (idx !== -1) db.transporters[idx] = data;
            logUserAction('Masters', 'Modified', `Updated transporter: ${name}`);
            showToast('Transporter updated', 'success');
        } else {
            db.transporters.push(data);
            logUserAction('Masters', 'Created', `Created transporter: ${name}`);
            showToast('Transporter added', 'success');
        }
        if (typeof window.updateLocalDBCache === 'function') {
            await window.updateLocalDBCache();
        }
        closeModal('trans-modal', true);
        renderTransporterTable();
        populateAllDropdowns();
        if (typeof renderDashboard === 'function') renderDashboard();
    } catch(e) {
        console.error('Failed to save transporter:', e);
        showToast('Failed to save transporter: ' + (e.message || e), 'error');
    }
}

