window._doQuickAddTransporter = async function(targetSelectId) {
    const name = document.getElementById('qat-name')?.value.trim();
    if (!name) { showToast('Transporter name is required', 'error'); return; }
    const gst  = document.getElementById('qat-gst')?.value.trim() || '';
    const mob  = document.getElementById('qat-mobile')?.value.trim() || '';

    const dup = (db.transporters || []).some(t => t.name.toLowerCase() === name.toLowerCase() || (gst && t.gst && t.gst.toLowerCase() === gst.toLowerCase()));
    if (dup) { showToast('Transporter with this name/GST already exists', 'error'); return; }

    const btn = document.getElementById('qat-save-btn');
    if (btn) { btn.disabled = true; btn.textContent = 'Saving…'; }

    const data = { id: uid(), name, gst, mobile: mob, email:'', contactPerson:'', designation:'', address:'' };
    try {
        await saveToSupabase('transporters', data);
        db.transporters.push(data);
        populateAllDropdowns();

        // Select the new transporter in the target dropdown
        const sel = document.getElementById(targetSelectId);
        if (sel) {
            reinitSearchableSelect(sel);
            setTimeout(() => {
                sel.value = data.id;
                sel.dispatchEvent(new Event('change'));
            }, 150);
        }

        logUserAction('Masters', 'Created', `Quick-added transporter: ${name}`);
        showToast(`Transporter "${name}" added `, 'success');
        document.getElementById('quick-add-transporter-panel')?.remove();
        if (typeof renderTransporterTable === 'function') renderTransporterTable();
    } catch(e) {
        showToast('Error saving transporter: ' + e.message, 'error');
        if (btn) { btn.disabled = false; btn.textContent = ' Save Transporter'; }
    }
};

