function checkTransporterReferences(transporterId) {

    const trans = db.transporters.find(x => x.id === transporterId);
    if (!trans) return null;
    
    if ((db.grns || []).some(grn => String(grn.transporterName).toLowerCase() === trans.name.toLowerCase())) {
        return 'GRNs';
    }
    return null;
}
window.checkTransporterReferences = checkTransporterReferences;

async function deleteTransporter(id) {
    if (!checkPermission('masters', 'delete')) {
        showToast('Permission Denied', 'error');
        return;
    }
    const t = db.transporters.find(x => x.id === id);
    if (!t) return;
    const name = t.name;
    
    const reference = checkTransporterReferences(id);
    if (reference) {
        showToast(`Cannot delete transporter. It is referenced in ${reference}.`, 'error');
        return;
    }

    if (!(await window.showSmartConfirm('Delete Transporter', 'Are you sure you want to delete this transporter?'))) return;
    try {
        await deleteFromSupabase('transporters', id);
        db.transporters = db.transporters.filter(t => t.id !== id);
        renderTransporterTable();
        logUserAction('Masters', 'Deleted', `Deleted transporter: ${name}`);
        showToast('Transporter deleted', 'info');
    } catch(e) {
        showToast(`Delete failed: ${e.message || e}`, 'error');
    }
}

