// ===== ROBUST GLOBAL UNIT CASCADE SYSTEM =====
window.propagateUnitChangeGlobally = async function(oldUnitVal, newUnitVal, itemIdFilter = null, extraAliases = []) {
    if (!newUnitVal) return;
    const newStr = String(newUnitVal).trim();
    if (!newStr) return;

    // Build normalized search set of old unit strings / variations
    const searchTargets = new Set();
    if (oldUnitVal && String(oldUnitVal).trim()) searchTargets.add(String(oldUnitVal).trim().toLowerCase());
    if (Array.isArray(extraAliases)) {
        extraAliases.forEach(a => {
            if (a && String(a).trim()) searchTargets.add(String(a).trim().toLowerCase());
        });
    }

    if (!searchTargets.size) return;

    // Helper: matches any old unit variation
    function isMatch(val) {
        if (!val || typeof val !== 'string') return false;
        const v = val.trim().toLowerCase();
        return searchTargets.has(v);
    }

    function updateObjectUnit(obj) {
        if (!obj || typeof obj !== 'object') return false;
        let changed = false;

        if (itemIdFilter) {
            const isItemMatch = (obj.itemId === itemIdFilter || obj.item_id === itemIdFilter || obj.id === itemIdFilter);
            if (!isItemMatch) {
                for (let key in obj) {
                    if (Object.prototype.hasOwnProperty.call(obj, key)) {
                        const val = obj[key];
                        if (typeof val === 'object' && val !== null) {
                            if (updateObjectUnit(val)) changed = true;
                        }
                    }
                }
                return changed;
            }
        }

        for (let key in obj) {
            if (Object.prototype.hasOwnProperty.call(obj, key)) {
                const val = obj[key];
                if (typeof val === 'string') {
                    const kLower = key.toLowerCase();
                    if (kLower.includes('unit') || kLower === 'uom' || kLower === 'base_unit' || kLower === 'alt_unit') {
                        if (isMatch(val)) {
                            obj[key] = newStr;
                            changed = true;
                        }
                    }
                } else if (typeof val === 'object' && val !== null) {
                    if (updateObjectUnit(val)) {
                        changed = true;
                    }
                }
            }
        }
        return changed;
    }

    async function scanCollection(tableName, list) {
        if (!list || !Array.isArray(list)) return;
        for (const item of list) {
            if (updateObjectUnit(item)) {
                try {
                    await saveToSupabase(tableName, item);
                } catch (err) {
                    console.error(`Failed to propagate unit change in ${tableName} for ID ${item.id}:`, err);
                }
            }
        }
    }

    // 1. Force update all Item Master records in memory & DB
    if (db.items && Array.isArray(db.items)) {
        db.items.forEach(item => {
            if (isMatch(item.unit) || isMatch(item.base_unit) || isMatch(item.altUnit) || isMatch(item.uom)) {
                item.unit = newStr;
                item.base_unit = newStr;
                saveToSupabase('items', item).catch(() => {});
            }
        });
    }

    if (window.masterDB && window.masterDB.items && Array.isArray(window.masterDB.items)) {
        window.masterDB.items.forEach(item => {
            if (isMatch(item.unit) || isMatch(item.base_unit) || isMatch(item.altUnit) || isMatch(item.uom)) {
                item.unit = newStr;
                item.base_unit = newStr;
            }
        });
    }

    // 2. Scan all transaction collections
    const collections = [
        { table: 'items', list: db.items },
        { table: 'boms', list: db.boms },
        { table: 'purchase_orders', list: rawDB.pos || db.pos },
        { table: 'sales_orders', list: rawDB.salesOrders || db.salesOrders },
        { table: 'production_slips', list: rawDB.productionSlips || db.productionLogs },
        { table: 'requisition_slips', list: rawDB.requisitionSlips || db.requisitions },
        { table: 'grns', list: rawDB.grns || db.grns },
        { table: 'outwards', list: rawDB.outwards || db.outwards },
        { table: 'generic_transactions', list: rawDB.genericTransactions },
        { table: 'production_plans', list: rawDB.productionPlans }
    ];

    for (const col of collections) {
        await scanCollection(col.table, col.list);
    }
};

async function propagateUnitSymbolChange(oldSymbol, newSymbol, oldName = null, newName = null) {
    // Generate common aliases based on old symbol & name
    const aliases = [];
    if (oldSymbol) aliases.push(oldSymbol);
    if (oldName) aliases.push(oldName);

    const sLower = String(oldSymbol || oldName || '').toLowerCase().trim();
    if (['m', 'mtr', 'mtrs', 'meter', 'metre', 'meters', 'metres'].includes(sLower)) {
        aliases.push('m', 'mtr', 'mtrs', 'meter', 'metre', 'meters', 'metres');
    } else if (['pc', 'pcs', 'piece', 'pieces'].includes(sLower)) {
        aliases.push('pc', 'pcs', 'piece', 'pieces');
    } else if (['kg', 'kgs', 'kilogram', 'kilograms'].includes(sLower)) {
        aliases.push('kg', 'kgs', 'kilogram', 'kilograms');
    } else if (['yd', 'yds', 'yard', 'yards'].includes(sLower)) {
        aliases.push('yd', 'yds', 'yard', 'yards');
    }

    await window.propagateUnitChangeGlobally(oldSymbol || oldName, newSymbol || newName, null, aliases);
}


async function saveUnit() {
    if (!checkPermission('masters', 'write')) {
        showToast('Permission Denied', 'error');
        return;
    }
    const name = document.getElementById('unit-name').value.trim();
    const symbol = document.getElementById('unit-symbol').value.trim();
    const editId = document.getElementById('unit-edit-id').value;
    if (!name) { showToast('Unit name is required', 'error'); return; }
    if (!symbol) { showToast('Unit symbol/code is required', 'error'); return; }

    let oldSymbol = '';
    let oldName = '';
    if (editId) {
        const u = db.units.find(x => x.id === editId);
        if (u) {
            oldSymbol = u.symbol;
            oldName = u.name;
        }
    }

    const data = {
        id: editId || uid(),
        company_id: (currentCompany ? currentCompany.id : 'co4'),
        name,
        symbol
    };

    try {
        await saveToSupabase('units', data);
        if (editId) {
            const idx = db.units.findIndex(u => u.id === editId);
            if (idx !== -1) db.units[idx] = data;
            logUserAction('Masters', 'Modified', `Updated unit: ${name} (${symbol})`);
            showToast('Unit updated', 'success');

            if ((oldSymbol && oldSymbol !== symbol) || (oldName && oldName !== name)) {
                showToast('Propagating unit changes across all GRNs, Outwards, POs, SOs, Invoices & Masters...', 'info');
                await propagateUnitSymbolChange(oldSymbol, symbol, oldName, name);
                showToast('Unit changes propagated successfully across all vouchers & records!', 'success');
                if (typeof renderItemTable === 'function') renderItemTable();
                if (typeof renderBOMTable === 'function') renderBOMTable();
                if (typeof renderAllTables === 'function') renderAllTables();
            }
        } else {
            db.units.push(data);
            logUserAction('Masters', 'Created', `Created unit: ${name} (${symbol})`);
            showToast('Unit added', 'success');
        }
        closeModal('unit-modal', true);
        populateAllDropdowns();
        renderUnitTable();
    } catch(e) {}
}

async function deleteUnit(id) {
    if (!checkPermission('masters', 'delete')) {
        showToast('Permission Denied', 'error');
        return;
    }
    const u = db.units.find(x => x.id === id);
    const name = u ? u.name : '';
    if (!(await window.showSmartConfirm('Delete Unit', 'Are you sure you want to delete this unit?'))) return;
    try {
        await deleteFromSupabase('units', id);
        db.units = db.units.filter(x => x.id !== id);
        populateAllDropdowns();
        renderUnitTable();
        logUserAction('Masters', 'Deleted', `Deleted unit: ${name}`);
        showToast('Unit deleted', 'info');
    } catch(e) {
        showToast(`Delete failed: ${e.message || e}`, 'error');
    }
}

