function setItemHasAlt(state) {
    const btnY = document.getElementById('item-has-alt-y');
    const btnN = document.getElementById('item-has-alt-n');
    const wrap = document.getElementById('item-alt-unit-wrap');
    if (!btnY || !btnN || !wrap) return;
    if (state === 'Y') {
        btnY.classList.add('active');
        btnN.classList.remove('active');
        wrap.style.display = 'block';
    } else {
        btnY.classList.remove('active');
        btnN.classList.add('active');
        wrap.style.display = 'none';
    }
}
