function setSelectValueCaseInsensitive(selectEl, targetValue) {
    if (!selectEl) return;
    if (!targetValue) {
        selectEl.value = '';
        const wrapper = selectEl.closest('.searchable-select-wrapper');
        if (wrapper) {
            const input = wrapper.querySelector('.searchable-select-input');
            if (input) input.value = '';
        }
        return;
    }
    const cleanTarget = String(targetValue).trim();
    const cleanLower = cleanTarget.toLowerCase();
    
    const options = Array.from(selectEl.options);
    let matchedOpt = options.find(o => o.value === cleanTarget || o.textContent.trim() === cleanTarget);
    if (!matchedOpt) {
        matchedOpt = options.find(o => o.value.toLowerCase() === cleanLower || o.textContent.trim().toLowerCase() === cleanLower);
    }
    if (!matchedOpt) {
        const targetNormalized = cleanLower.replace(/[^a-z0-9]/g, '');
        matchedOpt = options.find(o => o.value.toLowerCase().replace(/[^a-z0-9]/g, '') === targetNormalized);
    }

    if (matchedOpt) {
        selectEl.value = matchedOpt.value;
    } else if (cleanTarget) {
        const newOpt = document.createElement('option');
        newOpt.value = cleanTarget;
        newOpt.textContent = cleanTarget;
        selectEl.appendChild(newOpt);
        selectEl.value = cleanTarget;
        reinitSearchableSelect(selectEl);
    }

    const wrapper = selectEl.closest('.searchable-select-wrapper');
    if (wrapper) {
        const input = wrapper.querySelector('.searchable-select-input');
        if (input) {
            const selectedOpt = selectEl.options[selectEl.selectedIndex];
            input.value = selectedOpt ? selectedOpt.text : cleanTarget;
        }
    }
}
window.setSelectValueCaseInsensitive = setSelectValueCaseInsensitive;

function populateSalesAndPurchaseAccountDropdowns() {
    window.customMasters = window.customMasters || {};
    
    // Default fallbacks if custom masters lists are empty
    if (!window.customMasters.salesaccounts || window.customMasters.salesaccounts.length === 0) {
        window.customMasters.salesaccounts = ['SALES (JOB WORK)', 'Sales Account', 'Sales - Cloth', 'Sales - Job Work'];
    }
    if (!window.customMasters.purchaseaccounts || window.customMasters.purchaseaccounts.length === 0) {
        window.customMasters.purchaseaccounts = ['PURCHASE (JOB WORK)', 'Purchase Account', 'Purchase - Cloth', 'Purchase - Job Work'];
    }
    
    // Custom sales accounts strictly from Sales Accounts master card
    const customSales = (window.customMasters.salesaccounts || []).map(s => typeof s === 'object' && s !== null ? s.name : s).filter(Boolean);
    
    const itemSalesSel = document.getElementById('item-sales-account');
    if (itemSalesSel) {
        const curVal = itemSalesSel.value;
        const salesOpts = customSales.map(s => `<option value="${s}">${s}</option>`);
        salesOpts.unshift('<option value="">-- Select Sales Account --</option>');
        itemSalesSel.innerHTML = salesOpts.join('');
        if (curVal) setSelectValueCaseInsensitive(itemSalesSel, curVal);
    }
    
    // Custom purchase accounts strictly from Purchase Accounts master card
    const customPurchase = (window.customMasters.purchaseaccounts || []).map(p => typeof p === 'object' && p !== null ? p.name : p).filter(Boolean);
    
    const itemPurSel = document.getElementById('item-purchase-account');
    if (itemPurSel) {
        const curVal = itemPurSel.value;
        const purOpts = customPurchase.map(p => `<option value="${p}">${p}</option>`);
        purOpts.unshift('<option value="">-- Select Purchase Account --</option>');
        itemPurSel.innerHTML = purOpts.join('');
        if (curVal) setSelectValueCaseInsensitive(itemPurSel, curVal);
    }
}
window.populateSalesAndPurchaseAccountDropdowns = populateSalesAndPurchaseAccountDropdowns;

