        const matchedAltUnit = (db.units || []).find(u => u.symbol === item.altUnit || u.name === item.altUnit || u.symbol === item.alt_unit || u.name === item.alt_unit);
        document.getElementById('item-alt-unit').value = matchedAltUnit ? matchedAltUnit.symbol : (item.altUnit || '');
        document.getElementById('item-conv-factor').value = item.conversionFactor || '';
