        document.getElementById('item-opening-stock').value = '';
        document.getElementById('item-min-level').value = '';
        document.getElementById('item-min-days').value = '';
        document.getElementById('item-reorder-level').value = '';
        document.getElementById('item-reorder-days').value = '';
        document.getElementById('item-max-level').value = '';
        document.getElementById('item-max-days').value = '';

        // Defaults to No for new items
