async function saveVendorGroup() {
    if (!checkPermission('masters', 'write')) { showToast('Permission Denied', 'error'); return; }
    const name = document.getElementById('vg-name').value.trim();
    const editId = document.getElementById('vendorgroup-edit-id').value;

    if (!name) { showToast('Group name is required', 'error'); return; }

    db.vendorGroups = db.vendorGroups || [];
    const duplicate = db.vendorGroups.some(g => g.name.toLowerCase() === name.toLowerCase() && g.id !== editId);
    if (duplicate) { showToast('Group name already exists', 'error'); return; }

    const companyId = currentCompany ? currentCompany.id : '';
    const data = {
        id: editId || uid(),
        name,
        company_id: companyId
    };

    try {
        await saveToSupabase('vendor_groups', data);
        
        try {
            const local = JSON.parse(localStorage.getItem('local_vendor_groups_' + companyId) || '[]');
            const idx = local.findIndex(x => x.id === data.id);
            if (idx !== -1) local[idx] = data;
            else local.push(data);
            localStorage.setItem('local_vendor_groups_' + companyId, JSON.stringify(local));
        } catch(e) {}

        if (editId) {
            const idx = db.vendorGroups.findIndex(g => g.id === editId);
            if (idx !== -1) db.vendorGroups[idx] = data;
            logUserAction('Masters', 'Modified', `Updated vendor group: ${name}`);
            showToast('Vendor group updated', 'success');
        } else {
            db.vendorGroups.push(data);
            logUserAction('Masters', 'Created', `Created vendor group: ${name}`);
            showToast('Vendor group added', 'success');
        }
        closeModal('vendorgroup-modal', true);
        renderVendorGroupTable();
        populateVendorGroupDropdown();
    } catch(e) {
        showToast('Error saving vendor group: ' + (e.message || e), 'error');
    }
}
window.saveVendorGroup = saveVendorGroup;

async function deleteVendorGroup(id) {
    if (!checkPermission('masters', 'delete')) { showToast('Permission Denied', 'error'); return; }
    db.vendorGroups = db.vendorGroups || [];
    const g = db.vendorGroups.find(x => x.id === id);
    if (!g) return;

    db.vendors = db.vendors || [];
    const hasVendors = db.vendors.some(v => v.group === g.name);
    if (hasVendors) {
        showToast('Cannot delete group as it is currently linked to one or more vendors', 'error');
        return;
    }

    if (!(await window.showSmartConfirm('Delete Group', `Are you sure you want to delete Vendor Group ${g.name}?`))) return;
    try {
        await deleteFromSupabase('vendor_groups', id);
        
        const companyId = currentCompany ? currentCompany.id : '';
        try {
            let local = JSON.parse(localStorage.getItem('local_vendor_groups_' + companyId) || '[]');
            local = local.filter(x => x.id !== id);
            localStorage.setItem('local_vendor_groups_' + companyId, JSON.stringify(local));
        } catch(e) {}

        db.vendorGroups = db.vendorGroups.filter(x => x.id !== id);
        renderVendorGroupTable();
        logUserAction('Masters', 'Deleted', `Deleted Vendor Group: ${g.name}`);
        showToast('Vendor group deleted', 'info');
        populateVendorGroupDropdown();
    } catch(e) {
        showToast(`Delete failed: ${e.message || e}`, 'error');
    }
}
window.deleteVendorGroup = deleteVendorGroup;

function populateVendorGroupDropdown() {
    const sel = document.getElementById('vend-group');
    if (!sel) return;
    sel.innerHTML = '<option value="">-- Select Vendor Group --</option>';
    db.vendorGroups = db.vendorGroups || [];
    db.vendorGroups.forEach(g => {
        sel.appendChild(new Option(g.name, g.name));
    });
    
    if (sel.dataset.searchableInitialized) {
        if (typeof reinitSearchableSelect === 'function') {
            reinitSearchableSelect(sel);
        } else {
            const wrapper = sel.parentNode;
            if (wrapper && wrapper.classList.contains('searchable-select-wrapper')) {
                const input = wrapper.querySelector('.searchable-select-input');
                if (input) {
                    const selectedOpt = sel.options[sel.selectedIndex];
                    input.value = selectedOpt ? selectedOpt.text : '';
                    input.placeholder = sel.options[0]?.text || 'Type to search...';
                }
            }
        }
    }
}
window.populateVendorGroupDropdown = populateVendorGroupDropdown;

// ===== PURCHASE GR FUNCTIONS =====
function getNextPurchaseGRNumber() {
    const list = db.purchases || [];
    if (list.length === 0) return getDocumentNumber('PUR', 1);
    const numbers = list.map(p => {
        const num = p.grNo;
        if (!num) return 0;
        const parts = num.split('/');
        if (parts.length < 3) return 0;
        const val = parseInt(parts[parts.length - 1]);
        return isNaN(val) ? 0 : val;
    });
    let next = 1;
    while (numbers.includes(next)) {
        next++;
    }
    return getDocumentNumber('PUR', next);
}

function populatePurchaseDropdowns() {
    db.items = db.items || [];
    db.purchases = db.purchases || [];

    // Populate item dropdown in modal
    const itemSel = document.getElementById('pur-item');
    if (itemSel) {
        itemSel.innerHTML = '<option value="">-- Select Item --</option>';
        db.items.filter(x => x.status === 'Active').forEach(item => {
            const opt = document.createElement('option');
            opt.value = item.id;
            opt.textContent = `${item.name} (${item.category})`;
            opt.dataset.unit = item.unit;
            itemSel.appendChild(opt);
        });
    }

    // Populate vendor dropdown in modal
    const venSel = document.getElementById('pur-vendor');
    if (venSel) {
        venSel.innerHTML = '<option value="">-- Select Vendor --</option>';
        db.vendors.filter(v => v.id !== 'inhouse').forEach(v => {
            const opt = document.createElement('option');
            opt.value = v.id;
            opt.textContent = v.name;
            venSel.appendChild(opt);
        });
    }

    // Populate TDS Policy select
    const tdsSel = document.getElementById('pur-tds-policy');
    if (tdsSel) {
        const tdsOptions = (window.customMasters.tdspolicies || []).map(p => {
            return `<option value="${p.id}">${p.name} (${p.rate}%, Sec ${p.section})</option>`;
        });
        tdsOptions.unshift('<option value="">-- No TDS --</option>');
        tdsSel.innerHTML = tdsOptions.join('');
    }

    // Populate vendor filter in view
    const filterSel = document.getElementById('pur-vendor-filter');
    if (filterSel) {
        const currentVal = filterSel.value;
        filterSel.innerHTML = '<option value="">All Vendors</option>';
        db.vendors.filter(v => v.id !== 'inhouse').forEach(v => {
            const opt = document.createElement('option');
            opt.value = v.id;
            opt.textContent = v.name;
            filterSel.appendChild(opt);
        });
        filterSel.value = currentVal;
    }
}

function fillPurchaseItemDetails() {
    const itemSel = document.getElementById('pur-item');
    const selectedOpt = itemSel.options[itemSel.selectedIndex];
    document.getElementById('pur-unit').value = selectedOpt?.dataset?.unit || '';
}

function calcPurchaseAmount() {
    const qty = parseFloat(document.getElementById('pur-qty').value) || 0;
    const rate = parseFloat(document.getElementById('pur-rate').value) || 0;
    document.getElementById('pur-amount').value = qty > 0 && rate > 0 ? '\u20B9' + (qty * rate).toLocaleString('en-IN', { minimumFractionDigits: 2 }) : '';
}

// ===== PURCHASE GR FUNCTIONS =====
let currentPurchaseGRNLinks = [];

window.updatePurchaseGRNOptions = function() {
    const selectedVendorId = document.getElementById('pur-vendor').value;
    const selectEl = document.getElementById('pur-link-grn-select');
    const checklistEl = document.getElementById('pur-grn-checklist');
    
    if (selectEl) {
        selectEl.innerHTML = '<option value="">-- Select GRN --</option>';
    }
    if (checklistEl) {
        checklistEl.innerHTML = '';
    }
    
    if (!selectedVendorId) {
        if (selectEl) reinitSearchableSelect(selectEl);
        if (checklistEl) {
            checklistEl.innerHTML = '<div style="grid-column: 1/-1; text-align: center; color: var(--text-muted); font-size: 12px; padding: 12px;">Please select a Vendor first</div>';
        }
        return;
    }
    
    const vendorGrns = (db.grns || []).filter(g => {
        const wState = parseGrnWizardState(g);
        const isVendor = (wState.source === 'vendor' || (g.grnNo || g.number || '').includes('/V/'));
        return isVendor && g.customerId === selectedVendorId && (g.status || '').toLowerCase() !== 'cancelled';
    });
    
    // Populate Select Dropdown
    const notLinked = vendorGrns.filter(g => !currentPurchaseGRNLinks.includes(g.id));
    if (selectEl) {
        notLinked.forEach(g => {
            const opt = document.createElement('option');
            opt.value = g.id;
            const grnNo = g.grnNo || g.number || 'GRN';
            const dateStr = g.date ? formatDate(g.date) : '';
            const qty = g.qty || 0;
            opt.textContent = `${grnNo} (${dateStr}, Qty: ${qty})`;
            selectEl.appendChild(opt);
        });
        reinitSearchableSelect(selectEl);
    }
    
    // Populate Checklist
    if (checklistEl) {
        if (vendorGrns.length === 0) {
            checklistEl.innerHTML = '<div style="grid-column: 1/-1; text-align: center; color: var(--text-muted); font-size: 12px; padding: 12px;">No GRNs found for this vendor</div>';
        } else {
            vendorGrns.forEach(g => {
                const isChecked = currentPurchaseGRNLinks.includes(g.id);
                const grnNo = g.grnNo || g.number || 'GRN';
                const dateStr = g.date ? formatDate(g.date) : '';
                const qty = g.qty || 0;
                
                const itemDiv = document.createElement('div');
                itemDiv.className = 'grn-checkbox-item';
                itemDiv.style.cssText = 'display: flex; align-items: center; gap: 8px; padding: 6px 10px; border-radius: 6px; background: var(--bg-input, #f8fafc); border: 1px solid var(--border, #cbd5e1); font-size: 12px; cursor: pointer; transition: background 0.15s ease;';
                
                // Add hover style
                itemDiv.onmouseover = () => { itemDiv.style.background = 'var(--bg-hover, #e2e8f0)'; };
                itemDiv.onmouseout = () => { itemDiv.style.background = 'var(--bg-input, #f8fafc)'; };
                
                itemDiv.innerHTML = `
                    <input type="checkbox" id="chk-pur-grn-${g.id}" style="cursor: pointer; transform: scale(1.15);" ${isChecked ? 'checked' : ''}>
                    <label for="chk-pur-grn-${g.id}" style="cursor: pointer; margin: 0; font-weight: 500; display: block; flex: 1; text-overflow: ellipsis; overflow: hidden; white-space: nowrap;">
                        <strong>${grnNo}</strong> <span style="color: var(--text-muted); font-size: 11px;">(${dateStr}, ${qty} m)</span>
                    </label>
                `;
                
                // Clicking the container or the label toggles the checkbox
                itemDiv.addEventListener('click', (e) => {
                    if (e.target.tagName !== 'INPUT') {
                        const chk = itemDiv.querySelector('input');
                        chk.checked = !chk.checked;
                        window.togglePurchaseGRNLink(g.id, chk.checked);
                    } else {
                        window.togglePurchaseGRNLink(g.id, e.target.checked);
                    }
                });
                
                checklistEl.appendChild(itemDiv);
            });
        }
    }
};

window.togglePurchaseGRNLink = function(grnId, isChecked) {
    if (isChecked) {
        if (currentPurchaseGRNLinks.includes(grnId)) return;
        const grn = db.grns.find(g => g.id === grnId);
        if (!grn) return;
        
        currentPurchaseGRNLinks.push(grnId);
        
        const tbody = document.getElementById('pur-items-grid-body');
        const emptyRow = tbody?.querySelector('.empty-row');
        if (emptyRow) emptyRow.remove();
        
        if (grn.packageSlips && grn.packageSlips.length > 0) {
            grn.packageSlips.forEach(slip => {
                window.addPurchaseItemRow({
                    sourceGrnId: grn.id,
                    sourceGrnNo: grn.grnNo || grn.number,
                    itemName: slip.fabricType || slip.itemName || grn.fabricType || 'Fabric',
                    qty: parseFloat(slip.qty) || 0,
                    rate: 0,
                    unit: slip.unit || grn.unit || 'Metre'
                });
            });
        } else {
            window.addPurchaseItemRow({
                sourceGrnId: grn.id,
                sourceGrnNo: grn.grnNo || grn.number,
                itemName: grn.fabricType || 'Fabric',
                qty: parseFloat(grn.qty) || 0,
                rate: 0,
                unit: grn.unit || 'Metre'
            });
        }
        
        window.renderPurchaseLinkedGRNs();
        window.updatePurchaseGRNOptions();
        window.recalculatePurchaseTotals();
        if (typeof window.autoDetectPurchaseTdsFromGRNs === 'function') {
            window.autoDetectPurchaseTdsFromGRNs();
        }
    } else {
        window.unlinkGRNFromPurchase(grnId);
    }
};

window.toggleAllPurchaseGRNs = function(selectAll) {
    const selectedVendorId = document.getElementById('pur-vendor').value;
    if (!selectedVendorId) {
        showToast('Please select a Vendor first', 'warning');
        return;
    }
    
    const vendorGrns = (db.grns || []).filter(g => {
        const wState = parseGrnWizardState(g);
        const isVendor = (wState.source === 'vendor' || (g.grnNo || g.number || '').includes('/V/'));
        return isVendor && g.customerId === selectedVendorId && (g.status || '').toLowerCase() !== 'cancelled';
    });
    
    if (selectAll) {
        vendorGrns.forEach(g => {
            if (!currentPurchaseGRNLinks.includes(g.id)) {
                window.togglePurchaseGRNLink(g.id, true);
            }
        });
    } else {
        // Unlink all currently linked vendor GRNs that match the current vendor
        const currentLinks = [...currentPurchaseGRNLinks];
        currentLinks.forEach(grnId => {
            const grn = db.grns.find(g => g.id === grnId);
            if (grn && grn.customerId === selectedVendorId) {
                window.togglePurchaseGRNLink(grnId, false);
            }
        });
    }
};

window.renderPurchaseLinkedGRNs = function() {
    const tbody = document.getElementById('pur-linked-grns-body');
    if (!tbody) return;
    
    if (currentPurchaseGRNLinks.length === 0) {
        tbody.innerHTML = `<tr><td colspan="4" class="empty-row" style="text-align:center; padding:8px; color:var(--text-muted);">No linked GRNs.</td></tr>`;
        return;
    }
    
    tbody.innerHTML = '';
    currentPurchaseGRNLinks.forEach(grnId => {
        const grn = db.grns.find(g => g.id === grnId);
        if (!grn) return;
        
        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td><strong>${grn.grnNo || grn.number}</strong></td>
            <td>${grn.partyDocNo || '-'}</td>
            <td>${grn.qty || 0}</td>
            <td style="text-align: center;"><button type="button" class="btn btn-sm btn-danger" onclick="window.unlinkGRNFromPurchase('${grn.id}')">=�</button></td>
        `;
        tbody.appendChild(tr);
    });
};

window.unlinkGRNFromPurchase = function(grnId) {
    currentPurchaseGRNLinks = currentPurchaseGRNLinks.filter(id => id !== grnId);
    
    const tbody = document.getElementById('pur-items-grid-body');
    const rows = Array.from(tbody.querySelectorAll('.pur-item-row'));
    rows.forEach(row => {
        if (row.querySelector('.pur-row-grn-id')?.value === grnId) {
            row.remove();
        }
    });
    
    if (tbody.rows.length === 0) {
        tbody.innerHTML = `<tr><td colspan="8" class="empty-row" style="text-align: center; padding: 15px; color: var(--text-muted);">Link GRN(s) or add items to record purchase.</td></tr>`;
    }
    
    window.renderPurchaseLinkedGRNs();
    window.updatePurchaseGRNOptions();
    window.recalculatePurchaseTotals();
};

window.linkGRNToPurchase = function() {
    const selectEl = document.getElementById('pur-link-grn-select');
    const grnId = selectEl.value;
    if (!grnId) {
        showToast('Please select a GRN to link', 'error');
        return;
    }
    
    if (currentPurchaseGRNLinks.includes(grnId)) {
        showToast('GRN is already linked', 'warning');
        return;
    }
    
    const grn = db.grns.find(g => g.id === grnId);
    if (!grn) {
        showToast('GRN not found', 'error');
        return;
    }
    
    currentPurchaseGRNLinks.push(grnId);
    
    const tbody = document.getElementById('pur-items-grid-body');
    const emptyRow = tbody.querySelector('.empty-row');
    if (emptyRow) emptyRow.remove();
    
    if (grn.packageSlips && grn.packageSlips.length > 0) {
        grn.packageSlips.forEach(slip => {
            window.addPurchaseItemRow({
                sourceGrnId: grn.id,
                sourceGrnNo: grn.grnNo || grn.number,
                itemName: slip.fabricType || slip.itemName || grn.fabricType || 'Fabric',
                qty: parseFloat(slip.qty) || 0,
                unit: slip.unit || grn.unit || 'm',
                rate: ''
            });
        });
    } else {
        window.addPurchaseItemRow({
            sourceGrnId: grn.id,
            sourceGrnNo: grn.grnNo || grn.number,
            itemName: grn.fabricType || 'Fabric',
            qty: parseFloat(grn.qty) || 0,
            unit: grn.unit || 'm',
            rate: ''
        });
    }
    
    window.renderPurchaseLinkedGRNs();
    window.updatePurchaseGRNOptions();
    if (typeof window.autoDetectPurchaseTdsFromGRNs === 'function') {
        window.autoDetectPurchaseTdsFromGRNs();
    }
};

window.addPurchaseItemRow = function(rowData = {}) {
    const tbody = document.getElementById('pur-items-grid-body');
    if (!tbody) return;
    
    const emptyRow = tbody.querySelector('.empty-row');
    if (emptyRow) emptyRow.remove();
    
    const tr = document.createElement('tr');
    tr.className = 'pur-item-row';
    
    let selectedItemId = rowData.itemId || '';
    if (!selectedItemId && rowData.itemName) {
        const matched = db.items.find(i => i.name.toLowerCase().trim() === rowData.itemName.toLowerCase().trim());
        if (matched) selectedItemId = matched.id;
    }
    
    const itemOptions = db.items.filter(x => x.status === 'Active' || x.id === selectedItemId).map(i => {
        return `<option value="${i.id}" ${i.id === selectedItemId ? 'selected' : ''} data-unit="${i.unit || 'm'}">${i.name}</option>`;
    }).join('');
    
    tr.innerHTML = `
        <td class="sn-cell" style="text-align: center; vertical-align: middle;"></td>
        <td style="vertical-align: middle;">
            <input type="hidden" class="pur-row-grn-id" value="${rowData.sourceGrnId || ''}">
            <span class="pur-row-grn-no" style="font-weight: 600;">${rowData.sourceGrnNo || 'Manual'}</span>
        </td>
        <td>
            <select class="form-input pur-row-item-select" onchange="window.updatePurchaseRowUnit(this)">
                <option value="">-- Select Item --</option>
                ${itemOptions}
            </select>
        </td>
        <td>
            <input type="number" class="form-input pur-row-qty" value="${rowData.qty !== undefined ? rowData.qty : ''}" placeholder="0.00" step="any" style="text-align: right;" oninput="window.recalculatePurchaseTotals()">
        </td>
        <td style="text-align: center; vertical-align: middle;">
            <span class="pur-row-unit-lbl">${rowData.unit || '-'}</span>
        </td>
        <td>
            <input type="number" class="form-input pur-row-rate" value="${rowData.rate !== undefined ? rowData.rate : ''}" placeholder="0.00" step="any" style="text-align: right;" oninput="window.recalculatePurchaseTotals()">
        </td>
        <td style="text-align: right; font-weight: 600; vertical-align: middle; padding-right: 12px;">
            <span class="pur-row-amount-lbl">�0.00</span>
        </td>
        <td style="text-align: center; vertical-align: middle;">
            <button type="button" class="btn btn-sm btn-danger" onclick="window.removePurchaseRow(this)">=�</button>
        </td>
    `;
    
    tbody.appendChild(tr);
    
    const selectEl = tr.querySelector('.pur-row-item-select');
    if (selectEl) {
        makeSelectElementSearchable(selectEl);
        window.updatePurchaseRowUnit(selectEl);
    }
    
    window.recalculatePurchaseTotals();
};

window.addManualPurchaseRow = function() {
    window.addPurchaseItemRow({
        sourceGrnId: '',
        sourceGrnNo: 'Manual',
        itemName: '',
        qty: '',
        rate: '',
        unit: ''
    });
};

window.removePurchaseRow = function(btn) {
    const row = btn.closest('tr');
    if (!row) return;
    
    const grnId = row.querySelector('.pur-row-grn-id')?.value;
    row.remove();
    
    if (grnId) {
        const tbody = document.getElementById('pur-items-grid-body');
        const otherGrnRow = tbody.querySelector(`.pur-row-grn-id[value="${grnId}"]`);
        if (!otherGrnRow) {
            currentPurchaseGRNLinks = currentPurchaseGRNLinks.filter(id => id !== grnId);
            window.renderPurchaseLinkedGRNs();
            window.updatePurchaseGRNOptions();
        }
    }
    
    const tbody = document.getElementById('pur-items-grid-body');
    if (tbody.rows.length === 0) {
        tbody.innerHTML = `<tr><td colspan="8" class="empty-row" style="text-align: center; padding: 15px; color: var(--text-muted);">Link GRN(s) or add items to record purchase.</td></tr>`;
    }
    
    window.recalculatePurchaseTotals();
};

window.updatePurchaseRowUnit = function(selectEl) {
    const row = selectEl.closest('tr');
    if (!row) return;
    const selectedOpt = selectEl.options[selectEl.selectedIndex];
    const unit = selectedOpt?.dataset?.unit || '';
    const unitLbl = row.querySelector('.pur-row-unit-lbl');
    if (unitLbl) unitLbl.textContent = unit || '-';
};

window.recalculatePurchaseTotals = function() {
    const tbody = document.getElementById('pur-items-grid-body');
    if (!tbody) return;
    
    let totalQty = 0;
    let grandTotal = 0;
    
    const rows = Array.from(tbody.querySelectorAll('.pur-item-row'));
    rows.forEach((row, index) => {
        const snCell = row.querySelector('.sn-cell');
        if (snCell) snCell.textContent = index + 1;
        
        const qty = parseFloat(row.querySelector('.pur-row-qty').value) || 0;
        const rate = parseFloat(row.querySelector('.pur-row-rate').value) || 0;
        const amt = qty * rate;
        
        totalQty += qty;
        grandTotal += amt;
        
        const amtLbl = row.querySelector('.pur-row-amount-lbl');
        if (amtLbl) {
            amtLbl.textContent = '�' + amt.toLocaleString('en-IN', { minimumFractionDigits: 2 });
        }
    });
    
    const totalQtyEl = document.getElementById('pur-total-qty');
    const grandTotalEl = document.getElementById('pur-grand-total');
    
    if (totalQtyEl) totalQtyEl.textContent = totalQty.toFixed(2);
    if (grandTotalEl) grandTotalEl.textContent = '�' + grandTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 });
    
    if (typeof window.recalculatePurchaseTDS === 'function') {
        window.recalculatePurchaseTDS();
    }
};

window.autoDetectPurchaseTdsFromGRNs = function() {
    if (typeof currentPurchaseGRNLinks === 'undefined' || currentPurchaseGRNLinks.length === 0) return;
    
    for (const grnId of currentPurchaseGRNLinks) {
        const grn = db.grns.find(g => g.id === grnId);
        if (grn && grn.linked_po_id) {
            const po = (rawDB.pos || []).find(p => p.id === grn.linked_po_id);
            if (po && po.remarks) {
                const match = po.remarks.match(/__PO_TDS_POLICY__:([a-zA-Z0-9_-]+)/);
                if (match) {
                    const policyId = match[1];
                    const selectEl = document.getElementById('pur-tds-policy');
                    if (selectEl) {
                        selectEl.value = policyId;
                        window.recalculatePurchaseTDS();
                    }
                    break;
                }
            }
        }
    }
};

window.recalculatePurchaseTDS = function() {
    const tdsPolicyId = document.getElementById('pur-tds-policy')?.value;
    const grandTotalEl = document.getElementById('pur-grand-total');
    if (!grandTotalEl) return;
    
    const totalText = grandTotalEl.textContent.replace(/[^\d.]/g, '');
    const grandTotal = parseFloat(totalText) || 0;
    
    let tdsAmount = 0;
    if (tdsPolicyId) {
        const policy = (window.customMasters.tdspolicies || []).find(p => p.id === tdsPolicyId);
        if (policy) {
            tdsAmount = (grandTotal * (policy.rate || 0)) / 100;
        }
    }
    
    const tdsAmtEl = document.getElementById('pur-tds-amount');
    if (tdsAmtEl) {
        tdsAmtEl.value = tdsAmount > 0 ? '�' + tdsAmount.toLocaleString('en-IN', { minimumFractionDigits: 2 }) : '';
    }
};

async function openPurchaseModal(editId = null) {
    if (!checkPermission('purchases', 'write')) { showToast('Permission Denied', 'error'); return; }
    db.purchases = db.purchases || [];
    populatePurchaseDropdowns();
    document.getElementById('pur-edit-id').value = editId || '';
    if (document.getElementById('pur-tds-policy')) {
        document.getElementById('pur-tds-policy').value = '';
    }
    const purPrintBtn = document.getElementById('pur-print-btn');
    if (purPrintBtn) purPrintBtn.style.display = editId ? 'inline-block' : 'none';
    
    const tbody = document.getElementById('pur-items-grid-body');
    if (tbody) tbody.innerHTML = `<tr><td colspan="8" class="empty-row" style="text-align: center; padding: 15px; color: var(--text-muted);">Link GRN(s) or add items to record purchase.</td></tr>`;
    
    currentPurchaseGRNLinks = [];
    
    if (editId) {
        const pur = db.purchases.find(p => p.id === editId);
        if (!pur) return;
        if ((pur.status || '').trim().toLowerCase() === 'cancelled') {
            if (await window.showSmartConfirm('Activate Voucher', 'This voucher is cancelled. Do you want to activate this voucher?')) {
                pur.status = 'Received';
                await saveToSupabase('purchases', pur);
                window.reactivatedVouchers = window.reactivatedVouchers || {};
                window.reactivatedVouchers['pur-modal'] = { table: 'purchases', localArray: 'purchases', id: pur.id };
                showToast('Voucher activated successfully!', 'success');
                if (typeof renderPurchaseTable === 'function') renderPurchaseTable();
            } else {
                return;
            }
        }
        document.getElementById('pur-modal-title').textContent = 'Edit Purchase Invoice Voucher';
        document.getElementById('pur-number').value = pur.grNo;
        document.getElementById('pur-date').value = pur.date;
        document.getElementById('pur-vendor').value = pur.vendorId || '';
        document.getElementById('pur-invoice').value = pur.invoiceNo || '';
        document.getElementById('pur-status').value = pur.status || 'Received';
        document.getElementById('pur-remarks').value = pur.remarks || '';
        if (document.getElementById('pur-tds-policy')) {
            document.getElementById('pur-tds-policy').value = pur.tdsPolicyId || '';
        }
        
        currentPurchaseGRNLinks = pur.grnLinks || [];
        window.renderPurchaseLinkedGRNs();
        window.updatePurchaseGRNOptions();
        
        if (tbody) tbody.innerHTML = '';
        const items = pur.items || [];
        if (items.length > 0) {
            items.forEach(item => {
                window.addPurchaseItemRow({
                    sourceGrnId: item.sourceGrnId || '',
                    sourceGrnNo: item.sourceGrnNo || 'Manual',
                    itemId: item.itemId,
                    itemName: item.itemName,
                    qty: item.qty,
                    rate: item.rate,
                    unit: item.unit
                });
            });
        } else {
            window.addPurchaseItemRow({
                sourceGrnId: '',
                sourceGrnNo: 'Manual',
                itemId: pur.itemId,
                itemName: pur.itemName,
                qty: pur.qty,
                rate: pur.rate,
                unit: pur.unit
            });
        }
    } else {
        document.getElementById('pur-modal-title').textContent = 'New Purchase Invoice Voucher';
        document.getElementById('pur-number').value = getNextPurchaseGRNumber();
        document.getElementById('pur-date').value = new Date().toISOString().split('T')[0];
        document.getElementById('pur-vendor').value = '';
        document.getElementById('pur-invoice').value = '';
        document.getElementById('pur-status').value = 'Received';
        document.getElementById('pur-remarks').value = '';
        
        window.renderPurchaseLinkedGRNs();
        window.updatePurchaseGRNOptions();
    }
    openModal('pur-modal');
}

async function savePurchase() {
    if (window.validateVoucherMaker && !(await window.validateVoucherMaker('pur-modal'))) return;
    if (window.reactivatedVouchers) delete window.reactivatedVouchers['pur-modal'];
    if (!checkPermission('purchases', 'write')) { showToast('Permission Denied', 'error'); return; }
    db.purchases = db.purchases || [];
    const vendorId = document.getElementById('pur-vendor').value;
    const editId = document.getElementById('pur-edit-id').value;

    if (!vendorId) { showToast('Please select a vendor', 'error'); return; }

    const tbody = document.getElementById('pur-items-grid-body');
    const rows = Array.from(tbody.querySelectorAll('.pur-item-row'));
    if (rows.length === 0) {
        showToast('Please add at least one item row', 'error');
        return;
    }

    const items = [];
    let totalQty = 0;
    let totalAmount = 0;
    let validationFailed = false;

    rows.forEach((row, idx) => {
        const itemId = row.querySelector('.pur-row-item-select').value;
        const qty = parseFloat(row.querySelector('.pur-row-qty').value) || 0;
        const rate = parseFloat(row.querySelector('.pur-row-rate').value) || 0;
        const sourceGrnId = row.querySelector('.pur-row-grn-id').value;
        const sourceGrnNo = row.querySelector('.pur-row-grn-no').textContent;

        if (!itemId) {
            showToast(`Please select an item for row #${idx + 1}`, 'error');
            validationFailed = true;
            return;
        }
        if (qty <= 0) {
            showToast(`Please enter a valid quantity for row #${idx + 1}`, 'error');
            validationFailed = true;
            return;
        }
        if (rate < 0) {
            showToast(`Please enter a valid rate for row #${idx + 1}`, 'error');
            validationFailed = true;
            return;
        }

        const itemObj = db.items.find(x => x.id === itemId);
        items.push({
            itemId,
            itemName: itemObj ? itemObj.name : '',
            qty,
            rate,
            amount: qty * rate,
            unit: row.querySelector('.pur-row-unit-lbl').textContent || (itemObj ? itemObj.unit : ''),
            sourceGrnId,
            sourceGrnNo
        });

        totalQty += qty;
        totalAmount += qty * rate;
    });

    if (validationFailed) return;

    const tdsPolicyId = document.getElementById('pur-tds-policy')?.value || '';
    const tdsAmountText = document.getElementById('pur-tds-amount')?.value || '';
    const tdsAmount = parseFloat(tdsAmountText.replace(/[^\d.]/g, '')) || 0;

    if (totalAmount > 30000 && !tdsPolicyId) {
        const proceed = await window.showSmartConfirm(
            'Proceed without TDS?',
            `Warning: Purchase Invoice total (�${totalAmount.toLocaleString('en-IN')}) exceeds the Section 194C statutory limit of �30,000. Are you sure you want to save this invoice without deducting TDS?`
        );
        if (!proceed) return;
    }

    let purDate = document.getElementById('pur-date').value;
    const purStatus = document.getElementById('pur-status').value;
    if (purStatus === 'Cancelled' && !purDate) {
        purDate = new Date().toISOString().split('T')[0];
    }

    const vendorObj = db.vendors.find(v => v.id === vendorId);
    const firstItem = items[0];
    const existing = editId ? db.purchases.find(p => p.id === editId) : null;

    const data = {
        id: editId || uid(),
        grNo: document.getElementById('pur-number').value,
        date: purDate,
        entryTimestamp: existing ? (existing.entryTimestamp || currentTimestamp()) : currentTimestamp(),
        vendorId,
        vendorName: vendorObj ? vendorObj.name : '',
        itemId: firstItem.itemId,
        itemName: firstItem.itemName,
        itemCategory: db.items.find(x => x.id === firstItem.itemId)?.category || '',
        unit: firstItem.unit,
        qty: totalQty,
        rate: items.length === 1 ? firstItem.rate : 0,
        amount: totalAmount,
        invoiceNo: document.getElementById('pur-invoice').value.trim(),
        status: document.getElementById('pur-status').value,
        remarks: document.getElementById('pur-remarks').value.trim(),
        items: items,
        grnLinks: currentPurchaseGRNLinks,
        tdsPolicyId,
        tdsAmount
    };

    try {
        await saveToSupabase('purchases', data);
        if (editId) {
            const idx = db.purchases.findIndex(p => p.id === editId);
            if (idx !== -1) db.purchases[idx] = data;
            logUserAction('Purchases', 'Modified', `Updated Purchase Invoice Voucher ${data.grNo}`);
            showToast('Purchase Invoice Voucher updated', 'success');
        } else {
            db.purchases.unshift(data);
            logUserAction('Purchases', 'Created', `Created Purchase Invoice Voucher ${data.grNo}`);
            showToast('Purchase Invoice Voucher saved', 'success');
        }
        closeModal('pur-modal', true);
        renderPurchaseTable();
        renderPurchaseInventoryTable();
        renderDashboard();
        
        setTimeout(async () => {
            if (await window.showSmartConfirm('Sync to Busy ERP', `Do you want to sync Purchase Voucher ${data.grNo} to Busy ERP now?`)) {
                try {
                    const { data: synced } = await supabase
                        .from('busy_sync_queue')
                        .select('id')
                        .eq('voucher_id', data.id)
                        .eq('status', 'success')
                        .limit(1);
                    const isEdit = synced && synced.length > 0;
                    await window.queuePurchaseVoucherForBusySync(data, isEdit);
                    showToast('Purchase Voucher queued for Busy sync!', 'success');
                    setTimeout(() => {
                        window.openBusySyncLogsModal();
                    }, 400);
                } catch (err) {
                    showToast('Failed to queue Purchase Voucher: ' + err.message, 'error');
                }
            }
        }, 300);
    } catch(e) {}
}

async function deletePurchase(id) {
    if (!checkPermission('purchases', 'delete')) { showToast('Permission Denied', 'error'); return; }
    const pur = (db.purchases || []).find(p => p.id === id);
    if (!pur) return;
    if (!(await window.showSmartConfirm('Delete Purchase Invoice Voucher', 'Are you sure you want to delete this purchase invoice voucher? This cannot be undone.'))) return;
    try {
        await deleteFromSupabase('purchases', id);
        db.purchases = db.purchases.filter(p => p.id !== id);
        logUserAction('Purchases', 'Deleted', `Deleted Purchase Invoice Voucher ${pur.grNo}`);
        renderPurchaseTable();
        renderPurchaseInventoryTable();
        showToast('Purchase Invoice Voucher deleted', 'info');
    } catch(e) {}
}

function renderPurchaseTable() {
    const search = (document.getElementById('pur-search')?.value || '').toLowerCase();
    const vendorFilter = document.getElementById('pur-vendor-filter')?.value || '';
    const tbody = document.getElementById('pur-table-body');
    if (!tbody) return;
    db.purchases = db.purchases || [];

    let data = db.purchases.filter(p => {
        const matchItems = p.items && p.items.length > 0
            ? p.items.some(it => (it.itemName || '').toLowerCase().includes(search))
            : (p.itemName || '').toLowerCase().includes(search);
            
        const matchSearch = (p.grNo || '').toLowerCase().includes(search) ||
            (p.vendorName || '').toLowerCase().includes(search) ||
            (p.invoiceNo || '').toLowerCase().includes(search) ||
            matchItems;
        const matchVendor = !vendorFilter || p.vendorId === vendorFilter;
        return matchSearch && matchVendor;
    });

    if (!data.length) {
        tbody.innerHTML = '<tr><td colspan="10" class="empty-row">No purchase invoice vouchers found. Click "+ New Purchase Invoice Voucher" to add.</td></tr>';
        return;
    }

    const canWrite = checkPermission('purchases', 'write');
    const canDelete = checkPermission('purchases', 'delete');

    tbody.innerHTML = data.map(p => {
        let itemDetailsHtml = '';
        if (p.items && p.items.length > 0) {
            itemDetailsHtml = p.items.map(it => {
                return `<div style="margin-bottom:4px;"><strong>${it.itemName}</strong><br><small style="color:var(--text-muted)">${it.qty} ${it.unit || ''} @ �${(it.rate || 0).toFixed(2)}</small></div>`;
            }).join('');
        } else {
            itemDetailsHtml = `<strong>${p.itemName}</strong><br><small style="color:var(--text-muted)">${p.itemCategory || ''}</small>`;
        }

        return `
        <tr>
            <td><strong>${p.grNo}</strong></td>
            <td>${formatDate(p.date)}</td>
            <td>${p.vendorName}</td>
            <td>${itemDetailsHtml}</td>
            <td><strong>${p.qty}</strong></td>
            <td>${p.unit || '-'}</td>
            <td>\u20B9${(p.rate || 0).toFixed(2)}</td>
            <td><strong>\u20B9${(p.amount || 0).toLocaleString('en-IN', { minimumFractionDigits: 2 })}</strong></td>
            <td>${p.invoiceNo || '-'}</td>
            <td>
                <div class="table-actions">
                    ${canWrite ? `<button class="btn btn-sm btn-secondary" onclick="openPurchaseModal('${p.id}')"></button>` : ''}
                    ${canDelete ? `<button class="btn btn-sm btn-danger" onclick="deletePurchase('${p.id}')">=�</button>` : ''}
                </div>
            </td>
        </tr>
    `;
    }).join('');
}

// ===== PURCHASE INVENTORY =====
function renderPurchaseInventoryTable() {
    const search = (document.getElementById('purinv-search')?.value || '').toLowerCase();
    const catFilter = document.getElementById('purinv-cat-filter')?.value || '';
    const tbody = document.getElementById('purinv-table-body');
    if (!tbody) return;
    db.items = db.items || [];
    db.purchases = db.purchases || [];

    // Build stock map per item
    let items = db.items.filter(item => {
        const matchSearch = item.name.toLowerCase().includes(search) ||
            item.code.toLowerCase().includes(search);
        const matchCat = !catFilter || item.category === catFilter;
        return matchSearch && matchCat;
    });

    if (!items.length && !db.purchases.length) {
        tbody.innerHTML = '<tr><td colspan="9" class="empty-row">No purchase inventory data. Add items and purchase invoice vouchers first.</td></tr>';
        return;
    }

    const catBadgeMap = {
        'Thread': 'badge-blue',
        'Accessories': 'badge-purple',
        'Packing Material': 'badge-orange',
        'Raw Material': 'badge-green',
        'Other': 'badge-gray'
    };

    // Only show items that have at least one purchase or all items if no filter
    const rows = items.map(item => {
        const purRows = [];
        db.purchases.forEach(p => {
            if (p.items && p.items.length > 0) {
                p.items.forEach(it => {
                    if (it.itemId === item.id) {
                        purRows.push({
                            date: p.date,
                            qty: it.qty || 0,
                            rate: it.rate || 0,
                            amount: (it.qty || 0) * (it.rate || 0)
                        });
                    }
                });
            } else if (p.itemId === item.id) {
                purRows.push({
                    date: p.date,
                    qty: p.qty || 0,
                    rate: p.rate || 0,
                    amount: p.amount || 0
                });
            }
        });

        const totalQty = purRows.reduce((sum, r) => sum + r.qty, 0);
        const totalValue = purRows.reduce((sum, r) => sum + r.amount, 0);
        const lastPur = purRows.sort((a, b) => new Date(b.date) - new Date(a.date))[0];
        const lastRate = lastPur ? lastPur.rate : 0;
        const lastDate = lastPur ? formatDate(lastPur.date) : '-';

        const stockStatus = totalQty <= 0 ? { cls: 'badge-red', label: 'Out of Stock' }
            : { cls: 'badge-green', label: 'In Stock' };

        return `
            <tr>
                <td><span class="badge badge-blue">${item.code}</span></td>
                <td><strong>${item.name}</strong></td>
                <td><span class="badge ${catBadgeMap[item.category] || 'badge-gray'}">${item.category}</span></td>
                <td>${item.unit}</td>
                <td><strong>${totalQty.toLocaleString('en-IN', { maximumFractionDigits: 2 })}</strong></td>
                <td>${lastDate}</td>
                <td>${lastRate ? '\u20B9' + lastRate.toFixed(2) : '-'}</td>
                <td><strong>${totalValue > 0 ? '\u20B9' + totalValue.toLocaleString('en-IN', { minimumFractionDigits: 2 }) : '-'}</strong></td>
                <td><span class="badge ${stockStatus.cls}">${stockStatus.label}</span></td>
            </tr>
        `;
    }).join('');

    tbody.innerHTML = rows || '<tr><td colspan="9" class="empty-row">No items matching search criteria.</td></tr>';
}

function exportPurchaseInventory() {
    db.items = db.items || [];
    db.purchases = db.purchases || [];
    let csv = 'Item Code,Item Name,Category,Unit,Total Received,Last Purchase Date,Last Rate,Stock Value\n';
    db.items.forEach(item => {
        const purRows = [];
        db.purchases.forEach(p => {
            if (p.items && p.items.length > 0) {
                p.items.forEach(it => {
                    if (it.itemId === item.id) {
                        purRows.push({
                            date: p.date,
                            qty: it.qty || 0,
                            rate: it.rate || 0,
                            amount: (it.qty || 0) * (it.rate || 0)
                        });
                    }
                });
            } else if (p.itemId === item.id) {
                purRows.push({
                    date: p.date,
                    qty: p.qty || 0,
                    rate: p.rate || 0,
                    amount: p.amount || 0
                });
            }
        });

        const totalQty = purRows.reduce((sum, r) => sum + r.qty, 0);
        const totalValue = purRows.reduce((sum, r) => sum + r.amount, 0);
        const lastPur = purRows.sort((a, b) => new Date(b.date) - new Date(a.date))[0];
        csv += `"${item.code}","${item.name}","${item.category}","${item.unit}",${totalQty},${lastPur ? formatDate(lastPur.date) : ''},${lastPur ? lastPur.rate : ''},${totalValue}\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'purchase_inventory.csv';
    a.click();
    showToast('Purchase inventory exported as CSV', 'success');
}

