function normalizeDateStr(dStr) {
    if (!dStr) return today();
    dStr = String(dStr).trim();
    // Excel serial date
    if (/^\d{5}$/.test(dStr)) {
        const serial = parseInt(dStr);
        const utc_days = serial - 25569;
        const d = new Date(utc_days * 86400 * 1000);
        return d.toISOString().split('T')[0];
    }
    // DD/MM/YYYY or DD-MM-YYYY
    const match = dStr.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})$/);
    if (match) return `${match[3]}-${match[2].padStart(2,'0')}-${match[1].padStart(2,'0')}`;
    // YYYY-MM-DD
    if (/^\d{4}-\d{2}-\d{2}$/.test(dStr)) return dStr;
    return today();
}

function importPurchaseFile(event) {
    const file = event.target.files[0];
    if (!file) return;
    event.target.value = '';
    const fileName = file.name.toLowerCase();
    const reader = new FileReader();

    const processRows = (rows) => {
        db.items = db.items || [];
        db.purchases = db.purchases || [];
        _purchaseImportPreviewRows = [];

        // Detect header row
        let start = 0;
        if (rows[0] && rows[0].some(c => typeof c === 'string' && isNaN(c) && c.trim() !== '')) {
            start = 1;
        }

        for (let i = start; i < rows.length; i++) {
            const row = rows[i];
            if (!row || row.every(c => c === null || c === undefined || String(c).trim() === '')) continue;

            const dateRaw = String(row[0] || '').trim();
            const vendorName = String(row[1] || '').trim();
            const itemName = String(row[2] || '').trim();
            const qty = parseFloat(row[3]) || 0;
            const unit = String(row[4] || '').trim();
            const rate = parseFloat(row[5]) || 0;
            const invoiceNo = String(row[6] || '').trim();
            const remarks = String(row[7] || '').trim();

            const date = normalizeDateStr(dateRaw);

            // Resolve vendor
            const vendorObj = db.vendors.find(v => v.name.toLowerCase() === vendorName.toLowerCase());
            // Resolve item
            const itemObj = db.items.find(x => x.name.toLowerCase() === itemName.toLowerCase());

            const errors = [];
            if (!vendorName) errors.push('Missing vendor');
            if (!itemName) errors.push('Missing item');
            if (!vendorObj) errors.push(`Vendor "${vendorName}" not in master`);
            if (!itemObj) errors.push(`Item "${itemName}" not in Item Master`);
            if (qty <= 0) errors.push('Invalid quantity');

            _purchaseImportPreviewRows.push({
                date, vendorName, vendorObj, itemName, itemObj,
                qty, unit: unit || (itemObj ? itemObj.unit : ''), rate, invoiceNo, remarks,
                amount: qty * rate,
                isValid: errors.length === 0,
                errorMsg: errors.join(', ')
            });
        }

        // Show preview modal
        const tbody = document.getElementById('pur-preview-body');
        const statsDiv = document.getElementById('pur-import-stats');
        const validRows = _purchaseImportPreviewRows.filter(r => r.isValid);
        const invalidRows = _purchaseImportPreviewRows.filter(r => !r.isValid);

        statsDiv.innerHTML = `
            <div style="background:rgba(34,197,94,0.1); border:1px solid var(--accent-green); padding:8px 14px; border-radius:6px; font-size:13px;">
                 <strong>${validRows.length}</strong> valid rows ready to import
            </div>
            ${invalidRows.length ? `<div style="background:rgba(239,68,68,0.1); border:1px solid #ef4444; padding:8px 14px; border-radius:6px; font-size:13px;">
                ⚠� <strong>${invalidRows.length}</strong> rows with errors (will be skipped)
            </div>` : ''}
        `;

        tbody.innerHTML = _purchaseImportPreviewRows.map((r, i) => `
            <tr style="${r.isValid ? '' : 'opacity:0.6; background:rgba(239,68,68,0.05);'}">
                <td>${i + 1}</td>
                <td>${formatDate(r.date)}</td>
                <td>${r.vendorName}${!r.vendorObj ? ' <span style="color:#ef4444">⚠�</span>' : ''}</td>
                <td>${r.itemName}${!r.itemObj ? ' <span style="color:#ef4444">⚠�</span>' : ''}</td>
                <td>${r.qty}</td>
                <td>${r.unit}</td>
                <td>\u20B9${r.rate.toFixed(2)}</td>
                <td>\u20B9${r.amount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
                <td>${r.invoiceNo || '-'}</td>
                <td>${r.isValid ? '<span class="badge badge-green">OK</span>' : `<span class="badge badge-red" title="${r.errorMsg}">Error</span>`}</td>
            </tr>
        `).join('');

        document.getElementById('pur-confirm-import-btn').disabled = validRows.length === 0;
        openModal('pur-import-modal');
    };

    if (fileName.endsWith('.csv')) {
        reader.onload = e => processRows(parseCSV(e.target.result));
        reader.readAsText(file);
    } else if (fileName.endsWith('.xlsx') || fileName.endsWith('.xls')) {
        reader.onload = e => {
            try {
                const wb = XLSX.read(new Uint8Array(e.target.result), { type: 'array' });
                processRows(XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1, defval: '' }));
            } catch(err) {
                showToast('Error reading Excel file: ' + err.message, 'error');
            }
        };
        reader.readAsArrayBuffer(file);
    } else {
        showToast('Unsupported file. Please use .xlsx or .csv', 'error');
    }
}

function confirmPurchaseImport() {
    if (!checkPermission('purchases', 'write')) return;
    db.purchases = db.purchases || [];
    const validRows = _purchaseImportPreviewRows.filter(r => r.isValid);
    let imported = 0;

    validRows.forEach(r => {
        const grNo = getNextPurchaseGRNumber();
        db.purchases.unshift({
            id: uid(),
            grNo,
            date: r.date,
            entryTimestamp: currentTimestamp(),
            vendorId: r.vendorObj.id,
            vendorName: r.vendorObj.name,
            itemId: r.itemObj.id,
            itemName: r.itemObj.name,
            itemCategory: r.itemObj.category,
            unit: r.unit || r.itemObj.unit,
            qty: r.qty,
            rate: r.rate,
            amount: r.amount,
            invoiceNo: r.invoiceNo,
            status: 'Received',
            remarks: r.remarks
        });
        imported++;
    });

    logUserAction('Purchases', 'Import', `Excel import: ${imported} purchase invoice vouchers imported`);
    saveDB();
    closeModal('pur-import-modal');
    renderPurchaseTable();
    renderPurchaseInventoryTable();
    renderDashboard();
    showToast(` Successfully imported ${imported} purchase invoice vouchers`, 'success');
    _purchaseImportPreviewRows = [];
}

window.reinitSearchableSelect = function(select) {
    if (!select) return;
    if (select.dataset.searchableInitialized) {
        const wrapper = select.closest('.searchable-select-wrapper');
        if (wrapper) {
            const input = wrapper.querySelector('.searchable-select-input');
            const menu = wrapper.querySelector('.searchable-select-menu');
            if (input) input.remove();
            if (menu) menu.remove();
            wrapper.parentNode.insertBefore(select, wrapper);
            wrapper.remove();
            delete select.dataset.searchableInitialized;
            select.style.display = '';
        }
    }
    makeSelectElementSearchable(select);
};

// ===== INIT =====
currentView = 'masters';

// Overrides for HTMLSelectElement to intercept programmatic updates safely
(function() {
    function getDescriptor(proto, prop) {
        let current = proto;
        while (current) {
            const desc = Object.getOwnPropertyDescriptor(current, prop);
            if (desc) return desc;
            current = Object.getPrototypeOf(current);
        }
        return null;
    }

    try {
        const originalValueDescriptor = getDescriptor(HTMLSelectElement.prototype, 'value');
        if (originalValueDescriptor && originalValueDescriptor.configurable) {
            Object.defineProperty(HTMLSelectElement.prototype, 'value', {
                get() {
                    return originalValueDescriptor.get ? originalValueDescriptor.get.call(this) : '';
                },
                set(val) {
                    if (this._isIntercepting) {
                        if (originalValueDescriptor.set) {
                            originalValueDescriptor.set.call(this, val);
                        }
                        return;
                    }
                    const oldVal = originalValueDescriptor.get ? originalValueDescriptor.get.call(this) : '';
                    if (String(oldVal) === String(val)) {
                        if (originalValueDescriptor.set) {
                            originalValueDescriptor.set.call(this, val);
                        }
                        return;
                    }
                    this._isIntercepting = true;
                    try {
                        if (originalValueDescriptor.set) {
                            originalValueDescriptor.set.call(this, val);
                        }
                        if (this.dataset.searchableInitialized) {
                            const wrapper = this.closest('.searchable-select-wrapper') || this.parentNode;
                            if (wrapper && wrapper.classList && wrapper.classList.contains('searchable-select-wrapper')) {
                                const input = wrapper.querySelector('.searchable-select-input');
                                if (input) {
                                    const selectedOpt = (this.selectedIndex >= 0) ? this.options[this.selectedIndex] : null;
                                    input.value = (selectedOpt && this.value !== '') ? selectedOpt.text : '';
                                }
                            }
                            this.dispatchEvent(new Event('change', { bubbles: true }));
                        }
                    } finally {
                        this._isIntercepting = false;
                    }
                },
                configurable: true,
                enumerable: true
            });
        }
    } catch (e) {
        console.error("Error overriding HTMLSelectElement.value:", e);
    }

    try {
        const originalSelectedIndexDescriptor = getDescriptor(HTMLSelectElement.prototype, 'selectedIndex');
        if (originalSelectedIndexDescriptor && originalSelectedIndexDescriptor.configurable) {
            Object.defineProperty(HTMLSelectElement.prototype, 'selectedIndex', {
                get() {
                    return originalSelectedIndexDescriptor.get ? originalSelectedIndexDescriptor.get.call(this) : -1;
                },
                set(val) {
                    if (this._isIntercepting) {
                        if (originalSelectedIndexDescriptor.set) {
                            originalSelectedIndexDescriptor.set.call(this, val);
                        }
                        return;
                    }
                    const oldIdx = originalSelectedIndexDescriptor.get ? originalSelectedIndexDescriptor.get.call(this) : -1;
                    if (Number(oldIdx) === Number(val)) {
                        if (originalSelectedIndexDescriptor.set) {
                            originalSelectedIndexDescriptor.set.call(this, val);
                        }
                        return;
                    }
                    this._isIntercepting = true;
                    try {
                        if (originalSelectedIndexDescriptor.set) {
                            originalSelectedIndexDescriptor.set.call(this, val);
                        }
                        if (this.dataset.searchableInitialized) {
                            this.dispatchEvent(new Event('change', { bubbles: true }));
                        }
                    } finally {
                        this._isIntercepting = false;
                    }
                },
                configurable: true,
                enumerable: true
            });
        }
    } catch (e) {
        console.error("Error overriding HTMLSelectElement.selectedIndex:", e);
    }

    try {
        const originalDisabledDescriptor = getDescriptor(HTMLSelectElement.prototype, 'disabled');
        if (originalDisabledDescriptor && originalDisabledDescriptor.configurable) {
            Object.defineProperty(HTMLSelectElement.prototype, 'disabled', {
                get() {
                    return originalDisabledDescriptor.get ? originalDisabledDescriptor.get.call(this) : false;
                },
                set(val) {
                    if (originalDisabledDescriptor.set) {
                        originalDisabledDescriptor.set.call(this, val);
                    }
                    if (this.dataset.searchableInitialized) {
                        const wrapper = this.parentNode;
                        if (wrapper && wrapper.classList.contains('searchable-select-wrapper')) {
                            const input = wrapper.querySelector('.searchable-select-input');
                            if (input) {
                                input.disabled = val;
                            }
                        }
                    }
                },
                configurable: true,
                enumerable: true
            });
        }
    } catch (e) {
        console.error("Error overriding HTMLSelectElement.disabled:", e);
    }

    // Intercept form reset events to sync the custom search inputs
    try {
        document.addEventListener('reset', (e) => {
            setTimeout(() => {
                const selects = e.target.querySelectorAll('select');
                selects.forEach(select => {
                    if (select.dataset.searchableInitialized) {
                        select.dispatchEvent(new Event('change', { bubbles: true }));
                    }
                });
            }, 0);
        }, true);
    } catch (e) {
        console.error("Error setting up form reset interceptor:", e);
    }
})();

function makeSelectElementSearchable(select) {
    if (!select || !select.parentNode || select.dataset.searchableInitialized) return;
    
    // Blacklist check for topbar selectors and fixed regulation selects
    const blacklist = ['topbar-fy-select', 'theme-select', 'item-category-filter', 'item-subcategory-filter', 'po-type', 'so-material-type', 'po-material-type', 'so-sales-type', 'po-purchase-type', 'po-consumable-type', 'grn-consumable-type', 'gtx-grn-link', 'hsn-gst-slab', 'hsn-tax-category'];
    if (blacklist.includes(select.id)) {
        if (select.parentNode && select.parentNode.classList && select.parentNode.classList.contains('searchable-select-wrapper')) {
            const wrapper = select.parentNode;
            wrapper.parentNode.insertBefore(select, wrapper);
            wrapper.remove();
            delete select.dataset.searchableInitialized;
        }
        return;
    }
    
    
    const wrapper = document.createElement('div');
    wrapper.className = 'searchable-select-wrapper';
    wrapper.style.position = 'relative';
    
    // Copy select's layout styling to the wrapper so layout remains intact
    if (select.style.width) wrapper.style.width = select.style.width;
    if (select.style.margin) wrapper.style.margin = select.style.margin;
    if (select.style.marginTop) wrapper.style.marginTop = select.style.marginTop;
    if (select.style.marginBottom) wrapper.style.marginBottom = select.style.marginBottom;
    if (select.style.marginLeft) wrapper.style.marginLeft = select.style.marginLeft;
    if (select.style.marginRight) wrapper.style.marginRight = select.style.marginRight;
    if (select.style.display && select.style.display !== 'none') wrapper.style.display = select.style.display;
    
    const originalValue = select.value;
    select.parentNode.insertBefore(wrapper, select);
    wrapper.appendChild(select);
    
    // Explicitly restore option selection state to prevent browser DOM movement resets
    if (originalValue) {
        Array.from(select.options).forEach(opt => {
            opt.selected = (opt.value === originalValue);
        });
    }
    select.value = originalValue;
    select.style.display = 'none';
    
    const input = document.createElement('input');
    input.type = 'text';
    input.className = 'form-input searchable-select-input';
    const initialSelectedOpt = (select.selectedIndex >= 0) ? select.options[select.selectedIndex] : null;
    if (initialSelectedOpt && select.value !== '') {
        input.value = initialSelectedOpt.text;
    }
    input.placeholder = (initialSelectedOpt && select.value !== '') ? initialSelectedOpt.text : (select.options[0]?.text || 'Type to search...');
    input.style.width = '100%';
    input.disabled = select.disabled;
    
    const menu = document.createElement('div');
    menu.className = 'searchable-select-menu';
    
    wrapper.appendChild(input);
    wrapper.appendChild(menu);

    let highlightedIndex = -1;
    
    function populateMenu(filterText = '') {
        const query = filterText.toLowerCase();
        menu.innerHTML = '';
        let count = 0;
        highlightedIndex = -1;
        
        Array.from(select.options).forEach(opt => {
            if (opt.text.toLowerCase().includes(query) || opt.value === '') {
                const item = document.createElement('div');
                item.className = 'searchable-select-item';
                item.textContent = opt.text;
                item.dataset.value = opt.value;
                if (select.value === opt.value) {
                    item.classList.add('selected');
                }
                
                item.addEventListener('click', (e) => {
                    select.value = opt.value;
                    input.value = opt.text;
                    menu.classList.remove('open');
                    select.dispatchEvent(new Event('change', { bubbles: true }));
                    select.dispatchEvent(new Event('input', { bubbles: true }));
                    e.stopPropagation();
                });
                menu.appendChild(item);
                count++;
            }
        });
        
        if (count === 0) {
            const noRes = document.createElement('div');
            noRes.className = 'searchable-select-no-results';
            noRes.textContent = 'No matches found';
            menu.appendChild(noRes);
        }
    }
    
    function syncInput() {
        const selectedOpt = select.options[select.selectedIndex];
        input.value = selectedOpt ? selectedOpt.text : '';
    }
    
    function adjustMenuPosition() {
        const rect = input.getBoundingClientRect();
        
        menu.style.position = 'fixed';
        menu.style.left = `${rect.left}px`;
        menu.style.width = `${rect.width}px`;
        menu.style.top = `${rect.bottom + 4}px`;
        menu.style.bottom = 'auto';
        menu.style.marginTop = '0';
        menu.style.marginBottom = '0';
    }

    select.addEventListener('change', syncInput);
    
    input.addEventListener('focus', () => {
        const selectedOpt = select.options[select.selectedIndex];
        if (selectedOpt) {
            input.value = selectedOpt.text;
            try { input.select(); } catch(e) {}
        }
        
        populateMenu('');
        document.querySelectorAll('.searchable-select-menu.open').forEach(m => {
            if (m !== menu) m.classList.remove('open');
        });
        adjustMenuPosition();
        menu.classList.add('open');
    });
    
    input.addEventListener('click', () => {
        if (!menu.classList.contains('open')) {
            const selectedOpt = select.options[select.selectedIndex];
            if (selectedOpt) {
                input.value = selectedOpt.text;
                try { input.select(); } catch(e) {}
            }
            populateMenu('');
            document.querySelectorAll('.searchable-select-menu.open').forEach(m => {
                if (m !== menu) m.classList.remove('open');
            });
            adjustMenuPosition();
            menu.classList.add('open');
        }
    });
    
    input.addEventListener('input', () => {
        populateMenu(input.value);
        adjustMenuPosition();
        menu.classList.add('open');
    });
    
    input.addEventListener('blur', () => {
        setTimeout(() => {
            menu.classList.remove('open');
            syncInput();
        }, 200);
    });

    menu.addEventListener('mousedown', (e) => {
        // Prevent input blur when clicking or scrolling on scrollbar inside the dropdown menu
        e.preventDefault();
    });

    const onScrollOrResize = () => {
        if (menu.classList.contains('open')) {
            adjustMenuPosition();
        }
    };
    document.addEventListener('scroll', onScrollOrResize, { capture: true, passive: true });
    window.addEventListener('resize', onScrollOrResize, { passive: true });

    input.addEventListener('keydown', (e) => {
        const items = menu.querySelectorAll('.searchable-select-item');
        if (items.length === 0) return;
        
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            highlightedIndex = (highlightedIndex + 1) % items.length;
            updateHighlight(items);
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            highlightedIndex = (highlightedIndex - 1 + items.length) % items.length;
            updateHighlight(items);
        } else if (e.key === 'Enter') {
            e.preventDefault();
            if (highlightedIndex >= 0 && highlightedIndex < items.length) {
                items[highlightedIndex].click();
            }
        } else if (e.key === 'Escape') {
            menu.classList.remove('open');
            input.blur();
        }
    });

    function updateHighlight(items) {
        items.forEach((item, idx) => {
            if (idx === highlightedIndex) {
                item.classList.add('highlighted');
                item.style.background = 'var(--accent-blue-hover, #efefff)';
                item.scrollIntoView({ block: 'nearest' });
            } else {
                item.classList.remove('highlighted');
                item.style.background = '';
            }
        });
    }
    
    syncInput();
    select.dataset.searchableInitialized = "true";
}

function initSearchableSelects() {
    // Make every select currently in the document searchable (except blacklist)
    document.querySelectorAll('select').forEach(select => {
        makeSelectElementSearchable(select);
    });
    
    // Set up MutationObserver to automatically convert dynamically added selects
    // and sync dynamically changed options or attributes
    const observer = new MutationObserver((mutations) => {
        mutations.forEach(mutation => {
            if (mutation.type === 'childList') {
                mutation.addedNodes.forEach(node => {
                    if (node.nodeType === Node.ELEMENT_NODE) {
                        const selects = node.tagName === 'SELECT' ? [node] : node.querySelectorAll('select');
                        selects.forEach(select => {
                            makeSelectElementSearchable(select);
                        });
                    }
                });
                
                // If options of an initialized select changed, re-sync placeholder and value
                if (mutation.target.tagName === 'SELECT' && mutation.target.dataset.searchableInitialized) {
                    const select = mutation.target;
                    const wrapper = select.parentNode;
                    if (wrapper && wrapper.classList.contains('searchable-select-wrapper')) {
                        const input = wrapper.querySelector('.searchable-select-input');
                        if (input) {
                            const curVal = select.value;
                            let matchedOpt = null;
                            if (curVal && !curVal.startsWith('--')) {
                                matchedOpt = Array.from(select.options).find(o => o.value === curVal || o.value.toLowerCase() === curVal.toLowerCase());
                            }
                            if (!matchedOpt && select.selectedIndex > 0) {
                                matchedOpt = select.options[select.selectedIndex];
                            }
                            if (matchedOpt && matchedOpt.value && !matchedOpt.value.startsWith('--')) {
                                input.value = matchedOpt.text;
                            } else if (!input.value || input.value.startsWith('--')) {
                                input.value = (matchedOpt && matchedOpt.value && !matchedOpt.value.startsWith('--')) ? matchedOpt.text : '';
                            }
                            input.placeholder = select.options[0]?.text || 'Type to search...';
                        }
                    }
                }
            }
            if (mutation.type === 'attributes' && mutation.target.tagName === 'SELECT') {
                const select = mutation.target;
                if (select.dataset.searchableInitialized && mutation.attributeName === 'disabled') {
                    const wrapper = select.parentNode;
                    if (wrapper && wrapper.classList.contains('searchable-select-wrapper')) {
                        const input = wrapper.querySelector('.searchable-select-input');
                        if (input) {
                            input.disabled = select.disabled;
                        }
                    }
                }
            }
        });
    });
    
    observer.observe(document.body, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['disabled']
    });

    // Close all open searchable select menus on scroll to avoid floating fixed dropdowns
    window.addEventListener('scroll', (e) => {
        if (e.target !== document && e.target !== document.body && e.target !== window) return;
        document.querySelectorAll('.searchable-select-menu.open').forEach(menu => {
            if (e.target && menu.contains(e.target)) return;
            menu.classList.remove('open');
            const wrapper = menu.closest('.searchable-select-wrapper');
            if (wrapper) {
                const select = wrapper.querySelector('select');
                const input = wrapper.querySelector('.searchable-select-input');
                if (select && input) {
                    const selectedOpt = select.options[select.selectedIndex];
                    input.value = selectedOpt ? selectedOpt.text : '';
                }
            }
        });
    }, true);
}

window.changeTheme = function(themeName) {
    const themeClasses = ['theme-clean-slate', 'theme-warm-neutral', 'theme-ice-blue'];
    document.body.classList.remove(...themeClasses);
    document.documentElement.classList.remove(...themeClasses);
    if (themeName !== 'dark') {
        document.body.classList.add('theme-' + themeName);
        document.documentElement.classList.add('theme-' + themeName);
    }
    localStorage.setItem('embroideryflow_theme', themeName);
    const themeSelect = document.getElementById('theme-select');
    if (themeSelect && themeSelect.value !== themeName) {
        themeSelect.value = themeName;
    }
};

window.changeModuleIconSize = function(moduleId, size) {
    const container = document.getElementById(`module-${moduleId}`);
    if (container) {
        container.setAttribute('data-icon-size', size);
    }
    localStorage.setItem(`embroideryflow_icon_size_${moduleId}`, size);
    
    const sizeSelect = document.getElementById(`icon-size-select-${moduleId}`);
    if (sizeSelect && sizeSelect.value !== size) {
        sizeSelect.value = size;
    }
};

window.syncModuleIconSizes = function() {
    const modules = ['masters', 'transactions', 'production', 'inventory', 'freight', 'costing', 'reports', 'utilities'];
    modules.forEach(mod => {
        const storedSize = localStorage.getItem(`embroideryflow_icon_size_${mod}`) || 'medium';
        const container = document.getElementById(`module-${mod}`);
        if (container) {
            container.setAttribute('data-icon-size', storedSize);
        }
        const sizeSelect = document.getElementById(`icon-size-select-${mod}`);
        if (sizeSelect && sizeSelect.value !== storedSize) {
            sizeSelect.value = storedSize;
        }
    });
};

document.addEventListener('DOMContentLoaded', async () => {
    try {
        console.log("[INIT] DOMContentLoaded started");
        // Set today's date in topbar
        const now = new Date();
        const pageDateEl = document.getElementById('pageDate');
        if (pageDateEl) {
            pageDateEl.textContent = now.toLocaleDateString('en-IN', {
                weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
            });
        }

        // Apply stored theme (defaults to Clean Slate / light mode)
        const storedTheme = localStorage.getItem('embroideryflow_theme') || 'clean-slate';
        console.log("[INIT] Applying theme:", storedTheme);
        if (typeof window.changeTheme === 'function') {
            window.changeTheme(storedTheme);
        }

        console.log("[INIT] Syncing module icon sizes");
        if (typeof window.syncModuleIconSizes === 'function') {
            window.syncModuleIconSizes();
        }

        // Initial render
        console.log("[INIT] Loading Master DB");
        await loadMasterDB();
        
        console.log("[INIT] Checking session");
        await checkSession();
        
        console.log("[INIT] Fetching HSN codes");
        if (typeof fetchIndianHsnCodes === 'function') {
            fetchIndianHsnCodes();
        }
        
        console.log("[INIT] Initializing searchable selects");
        if (typeof initSearchableSelects === 'function') {
            initSearchableSelects();
        }
        console.log("[INIT] Initialization completed successfully");
    } catch (err) {
        console.error("[INIT] Initialization CRITICAL ERROR:", err);
        alert("EmbroideryFlow critical startup failure:\n" + err.message + "\n\nStack trace:\n" + err.stack);
    }

    // Global keyboard shortcuts
    document.addEventListener('keydown', (e) => {
        // 1. Esc key - Close active modals
        if (e.key === 'Escape') {
            const openDropdowns = document.querySelectorAll('.searchable-select-menu.open');
            if (openDropdowns.length > 0) {
                return;
            }
            const openModalOverlay = document.querySelector('.modal-overlay.open');
            if (openModalOverlay) {
                closeModal(openModalOverlay.id);
                e.preventDefault();
            }
        }
        
        // 2. Ctrl + S (inside a modal) - Save form
        if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
            const openModalOverlay = document.querySelector('.modal-overlay.open');
            if (openModalOverlay) {
                e.preventDefault();
                const saveBtn = openModalOverlay.querySelector('.modal-footer .btn-primary');
                if (saveBtn) saveBtn.click();
            }
        }

        // 3. Alt + N - New record
        if (e.altKey && e.key.toLowerCase() === 'n') {
            e.preventDefault();
            if (currentModule === 'masters') {
                masterAdd();
            } else if (currentModule === 'transactions') {
                const activeView = document.querySelector('#module-transactions .inline-subview.active');
                if (activeView) {
                    const newBtn = activeView.querySelector('.btn-primary');
                    if (newBtn) newBtn.click();
                }
            } else if (currentModule === 'production') {
                const activeView = document.querySelector('#module-production .inline-subview.active');
                if (activeView) {
                    const newBtn = activeView.querySelector('.btn-primary');
                    if (newBtn) newBtn.click();
                }
            }
        }

        // 4. Ctrl + F or Alt + F - Focus Search
        if (((e.ctrlKey && e.key.toLowerCase() === 'f') || (e.altKey && e.key.toLowerCase() === 'f')) && !document.querySelector('.modal-overlay.open')) {
            e.preventDefault();
            if (currentModule === 'masters') {
                document.getElementById('master-search')?.focus();
            } else if (currentModule === 'transactions') {
                const activeView = document.querySelector('#module-transactions .inline-subview.active');
                if (activeView) {
                    activeView.querySelector('.search-input')?.focus();
                }
            } else if (currentModule === 'production') {
                const activeView = document.querySelector('#module-production .inline-subview.active');
                if (activeView) {
                    activeView.querySelector('.search-input')?.focus();
                }
            }
        }
        
        // 5. Alt + 1 to Alt + 7 - Switch module tabs
        if (e.altKey && !isNaN(e.key)) {
            const num = parseInt(e.key);
            if (num >= 1 && num <= 7) {
                e.preventDefault();
                const tabButtons = document.querySelectorAll('.module-tab');
                if (tabButtons && tabButtons[num - 1]) {
                    tabButtons[num - 1].click();
                }
            }
        }
    });

    // UI Layout Customizer Setup
    if (typeof window.assignDynamicCardIds === 'function') window.assignDynamicCardIds();
    if (typeof window.applyNavigationTabOrder === 'function') window.applyNavigationTabOrder();
    if (typeof window.applyAllModuleGridCardsOrders === 'function') window.applyAllModuleGridCardsOrders();
    if (typeof window.initLayoutReorderControls === 'function') window.initLayoutReorderControls();
});

