let outwardWizardState = {
    type: 'fabric_issue_challan',  // 'fabric_issue_challan', 'inhouse', 'jobworker'
    source: 'customer',            // 'customer', 'vendor'
    subType: 'plain'               // 'plain', 'embroidered'
};
window.outwardWizardState = outwardWizardState;


function parseOutwardWizardState(out) {
    let state = { type: 'fabric_issue_challan', source: 'customer', subType: 'plain' };
    if (!out) return state;

    const num = (out.number || '').trim().toUpperCase();
    let prefixState = null;
    if (num.startsWith('FI/C/PF')) {
        prefixState = { type: 'fabric_issue_challan', source: 'customer', subType: 'plain' };
    } else if (num.startsWith('FI/C/EM')) {
        prefixState = { type: 'fabric_issue_challan', source: 'customer', subType: 'embroidered' };
    } else if (num.startsWith('FI/V/PF')) {
        prefixState = { type: 'fabric_issue_challan', source: 'vendor', subType: 'plain' };
    } else if (num.startsWith('FI/V/EM')) {
        prefixState = { type: 'fabric_issue_challan', source: 'vendor', subType: 'embroidered' };
    } else if (num.startsWith('FI/INH')) {
        prefixState = { type: 'inhouse', source: null, subType: null };
    } else if (num.startsWith('FI/JW')) {
        prefixState = { type: 'jobworker', source: null, subType: null };
    }
    
    // 1. Read from Wizard metadata in remarks if available
    let wizardMeta = null;
    if (out.remarks) {
        const match = out.remarks.match(/\[WIZARD:(\{.*?\})\]/);
        if (match) {
            try {
                wizardMeta = JSON.parse(match[1]);
            } catch (e) {}
        }
    }

    if (prefixState) {
        if (wizardMeta) {
            return Object.assign({}, wizardMeta, prefixState);
        }
        return prefixState;
    }

    if (wizardMeta) {
        return wizardMeta;
    }
    
    // 2. Identify source (vendor or customer) by prefix or checking vendorId field
    state.type = 'fabric_issue_challan';
    if (num.startsWith('FI/V/')) {
        state.source = 'vendor';
    } else if (num.startsWith('FI/C/')) {
        state.source = 'customer';
    } else {
        const hasVendor = out.vendorId && out.vendorId.trim() !== '';
        state.source = hasVendor ? 'vendor' : 'customer';
    }
    
    // 3. Identify subtype (plain or embroidered)
    let resolvedPlain = true;
    if (num.includes('/EM/') || num.startsWith('FI/V/EM') || num.startsWith('FI/C/EM')) {
        resolvedPlain = false;
    } else if (out.poRefId && db.pos) {
        const po = db.pos.find(p => p.id === out.poRefId);
        if (po && ((po.poType || '') === 'inhouse' || (po.type || '').toLowerCase().includes('embroidered'))) {
            resolvedPlain = false;
        }
    }
    state.subType = resolvedPlain ? 'plain' : 'embroidered';
    
    return state;
}
window.parseOutwardWizardState = parseOutwardWizardState;

