function openBOMModal(editId = null, prefillItemId = null) {
    db.items = db.items || [];
    const itemSel = document.getElementById('bom-item');
    itemSel.innerHTML = '<option value="">-- Item Name --</option>';
    db.items.forEach(i => {
        const opt = document.createElement('option');
        opt.value = i.id;
        opt.textContent = i.name;
        itemSel.appendChild(opt);
    });

    document.getElementById('bom-edit-id').value = editId || '';
    document.getElementById('bom-grid-body').innerHTML = '';
    
    const titleEl = document.getElementById('bom-modal-title');
    if (titleEl) {
        titleEl.innerHTML = editId ? '<span style="font-size: 20px;">=�</span> Edit Bill of Materials (BOM)' : '<span style="font-size: 20px;">=�</span> New Bill of Materials (BOM)';
    }
    
    if (editId) {
        const bom = db.boms.find(x => x.id === editId);
        if (bom) {
            document.getElementById('bom-code').value = bom.code;
            document.getElementById('bom-item').value = bom.finishedItemId;
            document.getElementById('bom-batch-qty').value = bom.batchQty;
            const metaIng = (bom.ingredients || []).find(function(ing) { return ing.itemId === 'METADATA_DESIGN_STITCH'; });
            const designStitch = (bom.designStitch !== undefined && bom.designStitch !== null) ? bom.designStitch : (metaIng ? metaIng.qty : 0);
            document.getElementById('bom-design-stitch').value = designStitch;
            document.getElementById('bom-design-repeat').value = (bom.repeat !== undefined && bom.repeat !== null) ? bom.repeat : '';
            const realIngredients = (bom.ingredients || []).filter(function(ing) { 
                return ing.itemId !== 'METADATA_DESIGN_STITCH' && ing.itemId !== 'METADATA_DESIGN_REPEAT_STR'; 
            });
            realIngredients.forEach(ing => addBOMRow(ing.itemId, ing.qty));
        }
    } else {
        db.boms = db.boms || [];
        const maxNum = db.boms.reduce((max, b) => {
            const match = String(b.code || '').match(/BOM-(\d+)/i);
            if (match) {
                const num = parseInt(match[1], 10);
                return num > max ? num : max;
            }
            return max;
        }, 0);
        document.getElementById('bom-code').value = 'BOM-' + String(maxNum + 1).padStart(3, '0');
        document.getElementById('bom-item').value = prefillItemId || '';
        if (prefillItemId) {
            const itemObj = (db.items || []).find(i => i.id === prefillItemId);
            if (itemObj) {
                document.getElementById('bom-code').value = itemObj.name;
            }
        }
        document.getElementById('bom-item').value = prefillItemId || '';
        document.getElementById('bom-batch-qty').value = '1';
        document.getElementById('bom-design-stitch').value = '';
        document.getElementById('bom-design-repeat').value = '';
        addBOMRow();
        addBOMRow();
        addBOMRow();
        addBOMRow();
    }
    window.updateModalUserLog('bom-modal');
    openModal('bom-modal');
}

window.openBOMModalForItemId = function(itemId) {
    db.boms = db.boms || [];
    const existing = db.boms.find(b => b.finishedItemId === itemId);
    if (existing) {
        openBOMModal(existing.id);
    } else {
        openBOMModal(null, itemId);
    }
};

function addBOMRow(itemId = '', qty = '') {
    const tbody = document.getElementById('bom-grid-body');
    const index = tbody.rows.length;
    const tr = document.createElement('tr');
    
    // Filter to show ONLY consumable / raw material items in BOM ingredients dropdown
    const isConsumableCat = (catName, itemName) => {
        const c = (catName || '').toLowerCase().trim();
        const n = (itemName || '').toLowerCase().trim();
        db.itemGroups = db.itemGroups || [];
        const group = db.itemGroups.find(g => g && g.name && g.name.toLowerCase().trim() === c);
        if (group) {
            if (group.name && group.name.toLowerCase().trim() === 'consumables') return true;
            const parentId = group.underGroupId || group.under_group_id;
            if (parentId) {
                const parent = db.itemGroups.find(g => g && g.id === parentId);
                if (parent && parent.name && parent.name.toLowerCase().trim() === 'consumables') return true;
            }
        }
        const terms = ['consumable', 'consumables', 'interlining', 'non-woven', 'nonwoven', 'thread', 'yarn', 'bobbin', 'needle', 'oil', 'packing', 'accessories', 'raw material', 'raw'];
        return terms.some(term => c.includes(term) || n.includes(term));
    };

    let filteredItems = (db.items || []).filter(i => isConsumableCat(i.category || i.group, i.name));
    
    // Ensure the currently selected item is included even if it's not consumable (for backwards compatibility/editing)
    if (itemId && !filteredItems.some(i => i.id === itemId)) {
        const existingItem = db.items.find(i => i.id === itemId);
        if (existingItem) {
            filteredItems.push(existingItem);
        }
    }
    
    let options = filteredItems.map(i => `<option value="${i.id}" ${i.id === itemId ? 'selected' : ''}>${i.name}</option>`).join('');
    
    const labels = ["Front Yarn", "Back Yarn", "Non Woven Fabric", "Extra"];
    const displaySNo = labels[index] || "Extra";

    const formattedQty = (qty !== '' && !isNaN(Number(qty))) ? Number(qty).toFixed(3) : qty;

    tr.innerHTML = `
        <td style="padding: 12px 16px; font-weight: 600; color: #475569; border-bottom: 1px solid #e2e8f0;">${displaySNo}</td>
        <td style="padding: 12px 16px; border-bottom: 1px solid #e2e8f0;"><select class="form-input" onchange="updateBOMUnitAndCategory(this)" style="border: 1px solid #cbd5e1; padding: 8px 12px; border-radius: 6px; font-size: 13px; width: 100%; max-width: 320px; background: #ffffff;">
            <option value="">-- Select raw item --</option>
            ${options}
        </select></td>
        <td style="padding: 12px 16px; border-bottom: 1px solid #e2e8f0;"><span class="category-label badge badge-blue" style="font-weight: 600; text-transform: uppercase; font-size: 11px; padding: 4px 8px; border-radius: 4px; display: inline-block;">-</span></td>
        <td style="padding: 12px 16px; border-bottom: 1px solid #e2e8f0;"><input type="number" class="form-input" value="${formattedQty}" placeholder="0.000" step="0.001" style="border: 1px solid #cbd5e1; padding: 8px 12px; border-radius: 6px; font-size: 13px; width: 100%; max-width: 120px;"></td>
        <td style="padding: 12px 16px; border-bottom: 1px solid #e2e8f0;"><span class="unit-label" style="font-weight: 600; color: #64748b; font-size: 13px;">-</span></td>
        <td style="padding: 12px 16px; text-align: center; border-bottom: 1px solid #e2e8f0;"><button class="btn btn-sm btn-danger" onclick="this.closest('tr').remove(); recalculateBOMSNo();" style="background: #fee2e2; border: 1px solid #fca5a5; color: #ef4444; width: 30px; height: 30px; border-radius: 6px; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; transition: all 0.2s;">=�</button></td>
    `;
    tbody.appendChild(tr);
    if (itemId) {
        const sel = tr.querySelector('select');
        updateBOMUnitAndCategory(sel);
    }
}

function updateBOMUnitAndCategory(selectEl) {
    const item = db.items.find(i => i.id === selectEl.value);
    const tr = selectEl.closest('tr');
    const unitLabel = tr.querySelector('.unit-label');
    const catLabel = tr.querySelector('.category-label');
    if (unitLabel) unitLabel.textContent = item ? (item.unit || 'pcs') : '-';
    if (catLabel) catLabel.textContent = item ? (item.category || '-') : '-';
}

function recalculateBOMSNo() {
    const tbody = document.getElementById('bom-grid-body');
    const labels = ["Front Yarn", "Back Yarn", "Non Woven Fabric", "Extra"];
    Array.from(tbody.rows).forEach((row, i) => {
        row.cells[0].textContent = labels[i] || "Extra";
    });
}

async function saveBOM() {
    if (window.validateVoucherMaker && !(await window.validateVoucherMaker('bom-modal'))) return;
    const code = document.getElementById('bom-code').value.trim();
    const finishedItemId = document.getElementById('bom-item').value;
    const batchQty = parseFloat(document.getElementById('bom-batch-qty').value) || 1;
    const editId = document.getElementById('bom-edit-id').value;
    
    if (!code || !finishedItemId) {
        showToast('Please fill required BOM details', 'error');
        return;
    }

    db.boms = db.boms || [];
    const isDuplicate = db.boms.some(b => b.code.toLowerCase() === code.toLowerCase() && b.id !== editId);
    if (isDuplicate) {
        showToast('A BOM with this Code already exists.', 'error');
        return;
    }
    
    const ingredients = [];
    const rows = document.getElementById('bom-grid-body').rows;
    for (let i = 0; i < rows.length; i++) {
        const row = rows[i];
        const val = row.cells[1].querySelector('select').value;
        const qty = parseFloat(row.cells[3].querySelector('input').value) || 0;
        if (val && qty > 0) {
            ingredients.push({ itemId: val, qty });
        }
    }
    
    const finishedItem = db.items.find(i => i.id === finishedItemId);
    const designStitch = parseFloat(document.getElementById('bom-design-stitch').value) || 0;
    const repeatStr = document.getElementById('bom-design-repeat').value.trim();
    const numericRepeat = parseFloat(repeatStr) || 0;
    
    const cleanIngredients = ingredients.filter(function(ing) { 
        return ing.itemId !== 'METADATA_DESIGN_STITCH' && ing.itemId !== 'METADATA_DESIGN_REPEAT_STR'; 
    });
    
    if (repeatStr) {
        cleanIngredients.push({ itemId: 'METADATA_DESIGN_REPEAT_STR', qty: numericRepeat, repeatStr: repeatStr });
    }
    
    const data = {
        id: editId || uid(),
        company_id: (currentCompany ? currentCompany.id : 'co4'),
        code,
        finishedItemId,
        finishedItemName: finishedItem ? finishedItem.name : '',
        batchQty,
        designStitch,
        repeat: repeatStr, // Store original fraction text directly since the column is now text
        ingredients: cleanIngredients
    };
    
    db.boms = db.boms || [];
    try {
        await saveToSupabase('boms', data);
        const localBomData = { ...data, repeat: repeatStr }; // Preserve original format (e.g. "12/4") locally
        if (editId) {
            const idx = db.boms.findIndex(b => b.id === editId);
            if (idx !== -1) db.boms[idx] = localBomData;
        } else {
            db.boms.push(localBomData);
        }
        
        closeModal('bom-modal', true);
        renderBOMTable();
        showToast('BOM Saved Successfully', 'success');
        
        setTimeout(async () => {
            if (await window.showSmartConfirm('Sync to Busy ERP', `Do you want to sync BOM for ${data.finishedItemName} to Busy ERP now?`)) {
                try {
                    const { data: synced } = await supabase
                        .from('busy_sync_queue')
                        .select('id')
                        .eq('voucher_id', data.id)
                        .eq('status', 'success')
                        .limit(1);
                    const isEdit = synced && synced.length > 0;
                    await window.queueBOMForBusySync(data, isEdit);
                    showToast('BOM queued for Busy sync!', 'success');
                    setTimeout(() => {
                        window.openBusySyncLogsModal();
                    }, 400);
                } catch (err) {
                    showToast('Failed to queue BOM: ' + err.message, 'error');
                }
            }
        }, 300);
    } catch(e) {}
}

function renderBOMTable() {
    const tbody = document.getElementById('bom-table-body');
    if (!tbody) return;
    db.boms = db.boms || [];
    
    const search = getMasterSearchQuery();
    let data = db.boms;
    if (search) {
        data = data.filter(b => 
            String(b.code || '').toLowerCase().includes(search) ||
            String(b.finishedItemName || '').toLowerCase().includes(search) ||
            String(b.batchQty || '').toLowerCase().includes(search) ||
            String(b.designStitch || '').toLowerCase().includes(search) ||
            String(b.repeat || '').toLowerCase().includes(search) ||
            (b.ingredients || []).some(ing => {
                const ingItemObj = db.items ? db.items.find(x => x.id === ing.itemId) : null;
                const ingItemName = ingItemObj ? (ingItemObj.name || ingItemObj.itemName) : (ing.itemName || '');
                return String(ingItemName).toLowerCase().includes(search);
            })
        );
    }
    
    if (data.length === 0) {
        tbody.innerHTML = `<tr><td colspan="6" class="empty-row">${search ? 'No matching BOMs found.' : 'No BOM defined yet.'}</td></tr>`;
        return;
    }
    
    const sortState = window.masterSortState?.boms || { col: 'code', dir: 'asc' };
    const sortedBoms = [...data].sort((a, b) => {
        let valA = (a[sortState.col] || '').toString().trim().toLowerCase();
        let valB = (b[sortState.col] || '').toString().trim().toLowerCase();
        
        if (sortState.col === 'batchQty') {
            const numA = parseFloat(valA) || 0;
            const numB = parseFloat(valB) || 0;
            return sortState.dir === 'asc' ? numA - numB : numB - numA;
        }
        
        return sortState.dir === 'asc' 
            ? valA.localeCompare(valB, undefined, { numeric: true, sensitivity: 'base' })
            : valB.localeCompare(valA, undefined, { numeric: true, sensitivity: 'base' });
    });
    
    const codeIcon = document.getElementById('sort-icon-bom-code');
    const nameIcon = document.getElementById('sort-icon-bom-name');
    if (codeIcon) codeIcon.innerHTML = sortState.col === 'code' ? (sortState.dir === 'asc' ? '&#9650;' : '&#9660;') : '&#8645;';
    if (nameIcon) nameIcon.innerHTML = sortState.col === 'finishedItemName' ? (sortState.dir === 'asc' ? '&#9650;' : '&#9660;') : '&#8645;';

    tbody.innerHTML = sortedBoms.map(b => `
        <tr>
            <td><input type="checkbox" class="chk-select-mst" value="${b.id}" onchange="toggleBulkDeleteButton('mst')"></td>
            <td>${b.code}</td>
            <td><strong>${b.finishedItemName}</strong></td>
            <td>${b.batchQty}</td>
            <td>${(b.ingredients || []).length} items listed</td>
            <td>
                <div class="table-actions">
                    <button class="btn btn-sm btn-primary" onclick="window.confirmAndSyncBOM('${b.id}')" title="Sync to Busy ERP">=</button>
                    <button class="btn btn-sm btn-outline-info" onclick="window.viewBOMTemplate('${b.id}')" title="View BOM Template" style="padding: 2px 6px;">=�</button>
                    <button class="btn btn-sm btn-secondary" onclick="openBOMModal('${b.id}')"></button>
                    <button class="btn btn-sm btn-danger" onclick="deleteBOM('${b.id}')">=�</button>
                </div>
            </td>
        </tr>
    `).join('');
}

async function deleteBOM(id) {
    const bom = db.boms.find(b => b.id === id);
    const name = bom ? bom.name : '';
    if (!(await window.showSmartConfirm('Delete Blueprint', 'Are you sure you want to delete this BOM blueprint?'))) return;
    try {
        await deleteFromSupabase('boms', id);
        db.boms = db.boms.filter(b => b.id !== id);
        renderBOMTable();
        logUserAction('BOM', 'Deleted', `Deleted BOM blueprint: ${name}`);
        showToast('BOM Deleted', 'info');
    } catch(e) {
        showToast(`Delete failed: ${e.message || e}`, 'error');
    }
}

