// ===== HSN TAX SPEC SPLIT LOGIC =====
function onGSTSelectChange() {
    const val = document.getElementById('hsn-gst-slab').value;
    const customIn = document.getElementById('hsn-custom-rate');
    const busyCatIn = document.getElementById('hsn-busy-tax-category');
    if (val === 'custom') {
        customIn.readOnly = false;
        customIn.style.opacity = '1';
        customIn.value = '';
    } else {
        customIn.readOnly = true;
        customIn.style.opacity = '0.7';
        customIn.value = val;
        calcGSTSplit();
    }
    if (busyCatIn && (!busyCatIn.value || busyCatIn.dataset.autoGenerated === 'true')) {
        const rate = parseFloat(val) || 0;
        if (val === '0') busyCatIn.value = 'Exempt';
        else if (val === '5') busyCatIn.value = '5%(GST 5%)';
        else if (val === '18') busyCatIn.value = '18%, (GST 18%)';
        else if (val === '12') busyCatIn.value = '12%(GST 12%)';
        else if (val === '28') busyCatIn.value = '28%, (GST 28%)';
        else if (rate > 0) busyCatIn.value = `GST ${rate}%`;
        busyCatIn.dataset.autoGenerated = 'true';
    }
}

function calcGSTSplit() {
    const val = parseFloat(document.getElementById('hsn-custom-rate').value) || 0;
    document.getElementById('hsn-cgst').value = (val / 2).toFixed(2);
    document.getElementById('hsn-sgst').value = (val / 2).toFixed(2);
    document.getElementById('hsn-igst').value = val.toFixed(2);
    const busyCatIn = document.getElementById('hsn-busy-tax-category');
    if (busyCatIn && busyCatIn.dataset.autoGenerated === 'true') {
        busyCatIn.value = val === 0 ? 'Exempt' : `${val}%, (GST ${val}%)`;
    }
}

// ===== ITEM GROUP SPECIFY TAX CATEGORY LOGIC =====
let specifyTaxCategoryState = 'N';
function setIgTaxCat(state) {
    specifyTaxCategoryState = state;
    const btnY = document.getElementById('ig-tax-cat-y');
    const btnN = document.getElementById('ig-tax-cat-n');
    const wrap = document.getElementById('ig-tax-cat-wrap');
    if (state === 'Y') {
        if (btnY) btnY.classList.add('active');
        if (btnN) btnN.classList.remove('active');
        if (wrap) wrap.style.display = 'block';
    } else {
        if (btnY) btnY.classList.remove('active');
        if (btnN) btnN.classList.add('active');
        if (wrap) wrap.style.display = 'none';
    }
}

