window.saveQuickItem = async function() {
    if (!checkPermission('masters', 'write')) { showToast('Permission Denied', 'error'); return; }
    const name = document.getElementById('quick-item-name').value.trim();
    const hsn = document.getElementById('quick-item-hsn').value.trim();
    const category = document.getElementById('quick-item-category').value.trim() || 'Thread';
    
    if (!name) { showToast('Item Name is required', 'error'); return; }

    const exists = db.items.find(i => i.name.toLowerCase() === name.toLowerCase());
    if (exists) { showToast('Item name already exists!', 'error'); return; }

    const data = {
        id: 'item_' + uid(),
        company_id: currentCompany.id,
        code: 'ITM-' + Math.floor(100+Math.random()*900),
        name: name,
        category: category,
        hsn: hsn || null,
        base_unit: 'm',
        status: 'Active',
        opening_stock: 0,
        min_level: 0,
        reorder: 0
    };

    try {
        const cleanObj = cleanRecordForSupabase('items', data);
        await supabase.from('items').insert(cleanObj);
        
        db.items.push({
            ...data,
            unit: data.base_unit,
            altUnit: '',
            openingStockQty: 0,
            minLevel: 0,
            reorderLevel: 0,
            conversionFactor: 0,
            maxLevel: 0
        });

        populateAllDropdowns();
        renderAllTables();
        
        // Also update any select element options in active SO grid rows
        const activeRows = document.getElementById('so-items-grid-body')?.rows;
        if (activeRows) {
            for (let i = 0; i < activeRows.length; i++) {
                const selectEl = activeRows[i].querySelector('select');
                if (selectEl) {
                    const currentVal = selectEl.value;
                    let options = db.items.map(item => `<option value="${item.id}" ${item.id === currentVal ? 'selected' : ''}>${item.name}</option>`).join('');
                    selectEl.innerHTML = '<option value="">-- Item --</option>' + options;
                }
            }
        }

        closeModal('quick-item-modal', true);
        logUserAction('Masters', 'Created', `Quick added item: ${name}`);
        showToast('Item created successfully', 'success');
    } catch (err) {
        console.error("Failed to quick add item:", err);
        showToast(`Failed to save item: ${err.message}`, 'error');
    }
};
