function populateSOAndPODropdowns() {
    populateAllDropdowns();
    if (typeof window.populateCustomDropdowns === 'function') {
        window.populateCustomDropdowns();
    }
    if (typeof renderDashboard === 'function') renderDashboard();
}


window.toggleSOFormGRNSection = function() {
    const matSelect = document.getElementById('so-material-type');
    const grnRow = document.getElementById('so-linked-grns-row');
    if (matSelect && grnRow) {
        grnRow.style.display = (matSelect.value === 'with_material') ? 'none' : 'flex';
    }

    const statusGroup = document.getElementById('so-material-jobwork-status-group');
    if (statusGroup && matSelect) {
        if (matSelect.value === 'without_material' || matSelect.value === 'consumable_customer_fabric') {
            statusGroup.innerHTML = `<label>Job Work Status</label><div class="form-input" style="background:#ecfdf5; color:#047857; font-weight:600; border-color:#a7f3d0; display:flex; align-items:center; height:38px; padding-left:12px; border-radius:6px; user-select:none;">=� Job Work</div>`;
        } else {
            statusGroup.innerHTML = `<label>Job Work Status</label><div class="form-input" style="background:#fef2f2; color:#b91c1c; font-weight:600; border-color:#fecaca; display:flex; align-items:center; height:38px; padding-left:12px; border-radius:6px; user-select:none;">=� No Job Work</div>`;
        }
    }
};

async function openSOModal(editId = null, customDocNo = null) {
    // Ensure so-sales-type exists in DOM
    let soSalesTypeEl = document.getElementById('so-sales-type');
    if (!soSalesTypeEl) {
        console.log("[openSOModal] Dynamically creating missing 'so-sales-type' element...");
        const delDateEl = document.getElementById('so-delivery-date');
        if (delDateEl && delDateEl.parentElement && delDateEl.parentElement.parentElement) {
            const formRow = delDateEl.parentElement.parentElement;
            const newGroup = document.createElement('div');
            newGroup.className = 'form-group';
            newGroup.innerHTML = `
                <label>Sales Type *</label>
                <select id="so-sales-type" class="form-input">
                    <option value="">-- Select Sales Type --</option>
                </select>
            `;
            formRow.appendChild(newGroup);
        }
    }

    const delDateEl = document.getElementById('so-delivery-date');
    if (!editId) {
        if (!checkPermission('so', 'write')) {
            showToast('Permission Denied: Restricted Entry', 'error');
            return;
        }
    }
    populateSOAndPODropdowns();
    document.getElementById('so-edit-id').value = editId || '';
    document.getElementById('so-items-grid-body').innerHTML = '';
    
    const soPrintBtn = document.getElementById('so-print-btn');
    if (soPrintBtn) soPrintBtn.style.display = editId ? 'inline-block' : 'none';
    
    if (editId) {
        const so = db.salesOrders.find(x => x.id === editId);
        if (so) {
            if ((so.status || '').trim().toLowerCase() === 'cancelled') {
                if (await window.showSmartConfirm('Activate Voucher', 'This voucher is cancelled. Do you want to activate this voucher?')) {
                    so.status = 'Pending';
                    await saveToSupabase('sales_orders', so);
                    window.reactivatedVouchers = window.reactivatedVouchers || {};
                    window.reactivatedVouchers['so-modal'] = { table: 'sales_orders', localArray: 'salesOrders', id: so.id };
                    showToast('Voucher activated successfully!', 'success');
                    if (typeof renderSalesOrderTable === 'function') renderSalesOrderTable();
                } else {
                    return;
                }
            }
            document.getElementById('so-number').value = so.number;
            document.getElementById('so-party-po').value = so.partyOrderNo || '';
            document.getElementById('so-party-po-date').value = so.partyOrderDate || '';
            document.getElementById('so-date').value = so.date;
            
            document.getElementById('so-material-type').value = so.materialType || 'without_material';
            reinitSearchableSelect(document.getElementById('so-material-type'));
            
            // Ensure cancelled customer exists in dropdown if it's the one selected
            const custSelect = document.getElementById('so-customer');
            if (custSelect && so.customerId) {
                const optExists = Array.from(custSelect.options).some(o => o.value === so.customerId);
                if (!optExists) {
                    const c = db.customers.find(x => x.id === so.customerId);
                    if (c) {
                        const opt = document.createElement('option');
                        opt.value = c.id;
                        opt.textContent = c.name + ' (Cancelled)';
                        custSelect.appendChild(opt);
                    }
                }
            }
            document.getElementById('so-customer').value = so.customerId;
            reinitSearchableSelect(document.getElementById('so-customer'));
            
            document.getElementById('so-delivery-days').value = so.deliveryDays || '';
            document.getElementById('so-delivery-date').value = so.deliveryDate || '';
            const statusEl = document.getElementById('so-status');
            let salesType = '';
            let remarksVal = so.remarks || '';
            const match = remarksVal.match(/^\[Sales Type:\s*(.*?)\]\s*/);
            if (match) {
                salesType = match[1];
                remarksVal = remarksVal.replace(/^\[Sales Type:\s*(.*?)\]\s*/, '');
            }
            const salesTypeEl = document.getElementById('so-sales-type');
            if (salesTypeEl) {
                salesTypeEl.value = salesType;
                reinitSearchableSelect(salesTypeEl);
            }
            document.getElementById('so-remarks').value = window.getUserRemarks(so.id);
            
            // Automatically find and link GRNs pointing to this SO
            db.grns = db.grns || [];
            const grnIdsLinkedToThisSO = db.grns.filter(g => {
                const isMatch = 
                    g.soRefId === so.id || 
                    g.soRefId === so.number ||
                    (g.soLinks && g.soLinks.includes(so.id)) ||
                    (g.soLinks && g.soLinks.includes(so.number)) ||
                    (g.soLinks && g.soLinks.includes('manual:' + so.number));
                return isMatch;
            }).map(g => g.id);
            
            currentSOLinks = grnIdsLinkedToThisSO || [];
            window.renderSOFormGRNLinks();
            window.populateGRNLinkSelectForSO();
            
            (so.items || []).forEach(it => addSORow(
                it.itemId, 
                it.qty, 
                it.price
            ));
            
            const roundOffInput = document.getElementById('so-round-off');
            if (roundOffInput) {
                if (so.roundOff !== undefined && so.roundOff !== null) {
                    roundOffInput.value = parseFloat(so.roundOff).toFixed(2);
                    roundOffInput.dataset.manual = 'true';
                } else {
                    roundOffInput.value = '0.00';
                    delete roundOffInput.dataset.manual;
                }
            }
        }
    } else {
        document.getElementById('so-number').value = customDocNo || getDocumentNumber('SO', getNextSalesOrderNumber());
        document.getElementById('so-party-po').value = '';
        document.getElementById('so-party-po-date').value = '';
        document.getElementById('so-date').value = today();
        document.getElementById('so-material-type').value = 'without_material';
        reinitSearchableSelect(document.getElementById('so-material-type'));
        
        document.getElementById('so-customer').value = '';
        reinitSearchableSelect(document.getElementById('so-customer'));
        
        document.getElementById('so-delivery-days').value = '15';
        updateSODeliveryDate();
        const statusEl = document.getElementById('so-status');
        if (statusEl) statusEl.value = 'Pending';
        const salesTypeEl = document.getElementById('so-sales-type');
        if (salesTypeEl) {
            salesTypeEl.value = '';
            reinitSearchableSelect(salesTypeEl);
        }
        document.getElementById('so-remarks').value = '';
        
        const roundOffInput = document.getElementById('so-round-off');
        if (roundOffInput) {
            roundOffInput.value = '0.00';
            delete roundOffInput.dataset.manual;
        }

        currentSOLinks = [];
        window.renderSOFormGRNLinks();
        window.populateGRNLinkSelectForSO();
        
        addSORow();
    }
    window.toggleSOFormGRNSection();
    recalculateSOTotal();
    window.updateModalUserLog('so-modal');
    openModal('so-modal');
}
window.openSOModal = openSOModal;

function updateSODeliveryDate() {
    const days = parseInt(document.getElementById('so-delivery-days').value) || 0;
    const dateVal = document.getElementById('so-date').value;
    if (dateVal) {
        const d = new Date(dateVal);
        d.setDate(d.getDate() + days);
        document.getElementById('so-delivery-date').value = d.toISOString().split('T')[0];
    }
}
function addSORow(itemId = '', qty = '', price = '') {
    const tbody = document.getElementById('so-items-grid-body');
    const index = tbody.rows.length;
    const tr = document.createElement('tr');
    
    let options = db.items.map(i => `<option value="${i.id}" ${i.id === itemId ? 'selected' : ''}>${i.name}</option>`).join('');
    
    const readonlyAttr = window.allowPriceChange() ? '' : 'readonly style="background:#f1f5f9; cursor:not-allowed;"';
    
    tr.innerHTML = `
        <td>${index + 1}</td>
        <td><select class="form-input so-item-select" onchange="updateSOItemUnit(this); recalculateSOTotal();">
            <option value="">-- Item --</option>
            ${options}
        </select></td>
        <td><input type="number" class="form-input so-qty-in" value="${qty}" placeholder="0" oninput="recalculateSOTotal()" step="any" autocomplete="off" data-lpignore="true" data-1p-ignore></td>
        <td><span class="unit-lbl">-</span></td>
        <td><input type="number" class="form-input so-price-in" value="${price}" placeholder="0.00" oninput="recalculateSOTotal()" step="any" autocomplete="off" data-lpignore="true" data-1p-ignore ${readonlyAttr}></td>
        <td><strong>\u20B9<span class="row-amt-lbl">0.00</span></strong></td>
        <td><button class="btn btn-sm btn-danger" onclick="this.closest('tr').remove(); recalculateSORowSNo(); recalculateSOTotal();">=�</button></td>
    `;
    tbody.appendChild(tr);

    const sel = tr.querySelector('select');
    if (sel) makeSelectElementSearchable(sel);
    if (itemId) {
        updateSOItemUnit(sel);
    }
}

function updateSOItemUnit(selectEl) {
    const item = db.items.find(i => i.id === selectEl.value);
    const label = selectEl.closest('tr').querySelector('.unit-lbl');
    if (label && item) label.textContent = window.getItemUnitSymbol(item);
}

function recalculateSORowSNo() {
    Array.from(document.getElementById('so-items-grid-body').rows).forEach((row, i) => {
        row.cells[0].textContent = i + 1;
    });
}

function recalculateSOTotal() {
    let grandTotal = 0;
    const rows = document.getElementById('so-items-grid-body').rows;
    let itemsTaxDetails = [];
    
    const salesTypeSelect = document.getElementById('so-sales-type');
    const selectedSalesTypeName = salesTypeSelect ? salesTypeSelect.value : '';
    const salesTypeObj = (db.sales_types || []).find(x => x.name === selectedSalesTypeName);
    const gstType = salesTypeObj ? (salesTypeObj.gst_type || 'CGST + SGST') : 'CGST + SGST';

    for (let i = 0; i < rows.length; i++) {
        const row = rows[i];
        const select = row.querySelector('.so-item-select') || row.querySelector('select');
        const qty = parseFloat(row.querySelector('.so-qty-in').value) || 0;
        const priceInput = row.querySelector('.so-price-in');
        const price = parseFloat(priceInput.dataset.origVal || priceInput.value) || 0;
        const amount = qty * price;
        row.querySelector('.row-amt-lbl').textContent = amount.toLocaleString('en-IN', { minimumFractionDigits: 2 });
        grandTotal += amount;

        if (select && select.value) {
            const itemId = select.value;
            const item = (db.items || []).find(x => x.id === itemId);
            let taxRate = 5; // Default HSN tax rate 5%
            if (item && item.hsn) {
                const hsnObj = (db.hsnCodes || []).find(h => h.code === item.hsn);
                if (hsnObj) {
                    if (gstType === 'IGST') {
                        taxRate = parseFloat(hsnObj.igst) || (parseFloat(hsnObj.cgst) + parseFloat(hsnObj.sgst)) || 5;
                    } else {
                        taxRate = (parseFloat(hsnObj.cgst) + parseFloat(hsnObj.sgst)) || parseFloat(hsnObj.igst) || 5;
                    }
                }
            }
            itemsTaxDetails.push({ amount, taxRate });
        }
    }
    
    document.getElementById('so-total-display').textContent = grandTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 });

    const gstContainer = document.getElementById('so-gst-details-container');
    if (gstContainer) {
        if (grandTotal > 0 && selectedSalesTypeName) {
            gstContainer.style.display = 'block';
            document.getElementById('so-taxable-display').textContent = grandTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 });

            let gstSummary = {};
            itemsTaxDetails.forEach(detail => {
                const rate = detail.taxRate;
                if (!gstSummary[rate]) gstSummary[rate] = 0;
                gstSummary[rate] += detail.amount;
            });

            let gstHtml = '';
            let totalTaxAmount = 0;
            
            Object.keys(gstSummary).forEach(rate => {
                const basicAmt = gstSummary[rate];
                const r = parseFloat(rate);
                if (gstType === 'IGST') {
                    const igstAmt = (basicAmt * r) / 100;
                    totalTaxAmount += igstAmt;
                    gstHtml += `
                        <div style="display: flex; justify-content: space-between; margin-bottom: 4px; color: var(--text-secondary);">
                            <span>IGST (${r}%):</span>
                            <span>�${igstAmt.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
                        </div>
                    `;
                } else {
                    const cgstSgstRate = r / 2;
                    const cgstAmt = (basicAmt * cgstSgstRate) / 100;
                    const sgstAmt = (basicAmt * cgstSgstRate) / 100;
                    totalTaxAmount += (cgstAmt + sgstAmt);
                    gstHtml += `
                        <div style="display: flex; justify-content: space-between; margin-bottom: 4px; color: var(--text-secondary);">
                            <span>CGST (${cgstSgstRate}%):</span>
                            <span>�${cgstAmt.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
                        </div>
                        <div style="display: flex; justify-content: space-between; margin-bottom: 4px; color: var(--text-secondary);">
                            <span>SGST (${cgstSgstRate}%):</span>
                            <span>�${sgstAmt.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
                        </div>
                    `;
                }
            });

            document.getElementById('so-gst-rows').innerHTML = gstHtml;
            const rawGrandTotal = grandTotal + totalTaxAmount;
            const roundOffInput = document.getElementById('so-round-off');
            let roundOffVal = 0;
            if (roundOffInput) {
                if (roundOffInput.dataset.manual === 'true') {
                    roundOffVal = parseFloat(roundOffInput.value) || 0;
                } else {
                    roundOffVal = Math.round(rawGrandTotal) - rawGrandTotal;
                    roundOffInput.value = roundOffVal.toFixed(2);
                }
            }
            const finalGrandTotal = rawGrandTotal + roundOffVal;
            document.getElementById('so-grand-total-display').textContent = finalGrandTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 });
        } else {
            gstContainer.style.display = 'none';
        }
    }
}

window.onSORoundOffInput = function() {
    const input = document.getElementById('so-round-off');
    if (input) {
        input.dataset.manual = 'true';
    }
    recalculateSOTotal();
};

window.validateTaxTypeWithPartyState = function(taxTypeName, gstNo, partyType) {
    if (!taxTypeName || !gstNo) return { valid: true };
    const isIGSTType = taxTypeName.startsWith('I/') || taxTypeName.includes('IGST') || taxTypeName.includes('I/GST');
    const isLocalType = taxTypeName.startsWith('L/') || taxTypeName.includes('LGST') || taxTypeName.includes('L/GST');
    if (gstNo.length >= 2) {
        const stateCode = gstNo.substring(0, 2);
        const isRajasthan = (stateCode === '08');
        if (isIGSTType && isRajasthan) {
            return {
                valid: false,
                message: `Tax Type Mismatch: ${partyType} is from Rajasthan (GST: ${gstNo}), but the selected Tax Type is IGST (${taxTypeName}). A Local type (L/GST) should be selected.`
            };
        }
        if (isLocalType && !isRajasthan) {
            return {
                valid: false,
                message: `Tax Type Mismatch: ${partyType} is from outside Rajasthan (GST: ${gstNo}), but the selected Tax Type is Local CGST/SGST (${taxTypeName}). An IGST type (I/GST) should be selected.`
            };
        }
    }
    return { valid: true };
};

window.validatePoPurchaseType = function() {
    const typeFilter = document.getElementById('po-type').value || 'vendor';
    if (typeFilter === 'inhouse') return;
    const vendorId = document.getElementById('po-vendor').value;
    const purchaseType = document.getElementById('po-purchase-type').value;
    if (vendorId && purchaseType) {
        const vendorObj = db.vendors ? db.vendors.find(x => x.id === vendorId) : null;
        const vendorGst = vendorObj ? (vendorObj.gst || '') : '';
        const validation = window.validateTaxTypeWithPartyState(purchaseType, vendorGst, 'Vendor');
        if (!validation.valid) {
            showToast(validation.message, 'warning');
        }
    }
};

window.validateSoSalesType = function() {
    const customerId = document.getElementById('so-customer').value;
    const salesType = document.getElementById('so-sales-type').value;
    if (customerId && salesType) {
        const custObj = db.customers ? db.customers.find(x => x.id === customerId) : null;
        const custGst = custObj ? (custObj.gst || '') : '';
        const validation = window.validateTaxTypeWithPartyState(salesType, custGst, 'Customer');
        if (!validation.valid) {
            showToast(validation.message, 'warning');
        }
    }
};

async function saveSO() {
    if (window._isSavingSO) return;
    window._isSavingSO = true;
    const saveBtn = document.querySelector('#so-modal .btn-primary');
    const origBtnHtml = saveBtn ? saveBtn.innerHTML : '';
    if (saveBtn) { saveBtn.disabled = true; saveBtn.innerHTML = '� Saving...'; }
    try {
        if (window.validateVoucherMaker && !(await window.validateVoucherMaker('so-modal'))) return;
        if (window.reactivatedVouchers) delete window.reactivatedVouchers['so-modal'];
        let number = document.getElementById('so-number').value;
        if (number && window.formatStandardDocNumber) {
            number = window.formatStandardDocNumber(number);
        }
        const editId = document.getElementById('so-edit-id').value;
        if (!editId) {
            number = await window.ensureUniqueDocumentNumber('sales_orders', 'number', number);
            document.getElementById('so-number').value = number;
        }
        const partyOrderNo = document.getElementById('so-party-po').value.trim();
        const partyOrderDate = document.getElementById('so-party-po-date').value;
        const date = document.getElementById('so-date').value;
        const customerId = document.getElementById('so-customer').value;
        const deliveryDays = parseInt(document.getElementById('so-delivery-days').value) || 0;
        const deliveryDate = document.getElementById('so-delivery-date').value;
        const remarks = document.getElementById('so-remarks').value;
        const statusEl = document.getElementById('so-status');
        const status = statusEl ? statusEl.value : (editId ? (db.salesOrders.find(x => x.id === editId)?.status || 'Pending') : 'Pending');
        const materialType = document.getElementById('so-material-type').value;
        
        const salesTypeEl = document.getElementById('so-sales-type');
        const salesType = salesTypeEl ? salesTypeEl.value : '';
        if (!customerId || !date) { showToast('Customer and Date are required', 'error'); return; }
        if (!validateTransactionDate(date)) return;
        if (!window.validateDocumentDateChronology('sales_orders', number, date, editId)) return;
        
        const items = [];
        const rows = document.getElementById('so-items-grid-body').rows;
        let totalValue = 0;
        for (let i = 0; i < rows.length; i++) {
            const row = rows[i];
            const itemId = row.querySelector('select').value;
            const qty = parseFloat(row.querySelector('.so-qty-in').value) || 0;
            const priceInput = row.querySelector('.so-price-in');
            const price = parseFloat(priceInput.dataset.origVal || priceInput.value) || 0;
            if (qty > 0) {
                items.push({ itemId: itemId || '', qty, price, amount: qty * price });
                totalValue += qty * price;
            }
        }    
        if (items.length === 0) { showToast('Please add at least one item', 'error'); return; }
        
        const finalRemarks = `[Sales Type: ${salesType}] ${remarks}`;
        const cust = db.customers.find(c => c.id === customerId);
        const roundOffEl = document.getElementById('so-round-off');
        const roundOff = roundOffEl ? (parseFloat(roundOffEl.value) || 0) : 0;
        
        const data = {
            id: editId || uid(),
            number, partyOrderNo, partyOrderDate, date, customerId, customerName: cust ? cust.name : '',
            materialType,
            salesType,
            deliveryDays, deliveryDate, status, remarks: finalRemarks, items, totalValue,
            roundOff
        };
        
        if (materialType === 'with_material') {
            currentSOLinks = [];
            await window.executeSaveSO(data, editId);
        } else {
            if (currentSOLinks.length === 0) {
                await window.promptSOLinkToGRN(data, editId);
            } else {
                await window.executeSaveSO(data, editId);
            }
        }
    } catch (e) {
        console.error("[saveSO Error]", e);
        showToast("Error saving Sales Order: " + e.message, "error");
    } finally {
        window._isSavingSO = false;
        if (saveBtn) { saveBtn.disabled = false; saveBtn.innerHTML = origBtnHtml; }
    }
}

window.executeSaveSO = async function(data, editId) {
    const saveBtn = document.querySelector('#so-modal .btn-primary');
    const origBtnHtml = 'Save';
    try {
        data.qty = (data.items || []).reduce((sum, it) => sum + (parseFloat(it.qty) || 0), 0);
        data.amount = data.totalValue || (data.items || []).reduce((sum, it) => sum + (parseFloat(it.amount) || 0), 0);
        data.rate = data.items?.[0]?.price || 0;
        data.grnLinks = currentSOLinks || [];
        await saveToSupabase('sales_orders', data);
        const remarksInputVal = document.getElementById('so-remarks') ? document.getElementById('so-remarks').value : '';
        await window.saveUserRemarks(data.id, remarksInputVal);
        // Removed automatic queueing for Busy Sync on save
        window.triggerGoogleSheetsSync('so', data, editId ? 'edit' : 'create');
        await window.syncSOLinksWithGRNs(data.id, currentSOLinks, data.number);
        
        if (editId) {
            const idxRaw = rawDB.salesOrders.findIndex(x => x.id === editId);
            if (idxRaw !== -1) rawDB.salesOrders[idxRaw] = data;
        } else {
            rawDB.salesOrders.push(data);
        }
        applyFinancialYearFilters();
        
        renderSOTable();
        
        // Show success prompt modal with options
        document.getElementById('so-success-number').textContent = data.number;
        openModal('so-success-modal');
        
        const handleClose = function() {
            closeModal('so-success-modal');
            closeModal('so-modal', true);
        };
        const soSuccessModal = document.getElementById('so-success-modal');
        if (soSuccessModal) {
            const closeBtn = soSuccessModal.querySelector('.modal-close');
            if (closeBtn) closeBtn.onclick = handleClose;
            const doneBtn = soSuccessModal.querySelector('.modal-footer .btn');
            if (doneBtn) doneBtn.onclick = handleClose;
        }

        document.getElementById('btn-so-success-print').onclick = function() {
            printSO(data.id);
        };

        const btnSyncBusy = document.getElementById('btn-so-success-sync-busy');
        if (btnSyncBusy) {
            btnSyncBusy.onclick = async function() {
                if (!(await window.showSmartConfirm('Sync to Busy ERP', `Are you sure you want to sync Sales Order ${data.number} to Busy ERP?`))) {
                    return;
                }
                try {
                    await window.queueSalesOrderForBusySync(data, !!editId);
                    showToast('Sales Order queued for Busy sync!', 'success');
                    setTimeout(() => {
                        window.openBusySyncLogsModal();
                    }, 400);
                } catch (err) {
                    showToast('Failed to queue Sales Order: ' + err.message, 'error');
                }
            };
        }
        
        document.getElementById('btn-so-success-dual').onclick = function() {
            openSODualEntry(data);
        };
        
        document.getElementById('btn-so-success-grn-plain').onclick = function() {
            closeModal('so-success-modal');
            closeModal('so-modal', true);
            openGRNModalFromSO(data, 'plain');
        };
        
        if (typeof renderPendingTransactionsWidget === 'function') {
            renderPendingTransactionsWidget();
        }
    } catch(e) {
        console.error("[saveSO Error]", e);
    } finally {
        window._isSavingSO = false;
        if (saveBtn) { saveBtn.disabled = false; saveBtn.innerHTML = origBtnHtml; }
    }
};

function openSODualEntry(oldData) {
    closeModal('so-success-modal');
    
    // Open modal
    openModal('so-modal');
    
    // Increment SO Number
    const newSoNumber = getDocumentNumber('SO', getNextSalesOrderNumber());
    
    document.getElementById('so-edit-id').value = '';
    document.getElementById('so-number').value = newSoNumber;
    document.getElementById('so-party-po').value = oldData.partyOrderNo || '';
    document.getElementById('so-date').value = oldData.date;
    document.getElementById('so-customer').value = oldData.customerId;
    
    // Sync custom searchable select
    const custSelect = document.getElementById('so-customer');
    if (custSelect) {
        custSelect.dispatchEvent(new Event('change', { bubbles: true }));
    }
    
    document.getElementById('so-delivery-days').value = oldData.deliveryDays || '15';
    document.getElementById('so-delivery-date').value = oldData.deliveryDate || '';
    const statusEl = document.getElementById('so-status');
    if (statusEl) statusEl.value = 'Pending';
    document.getElementById('so-remarks').value = window.getUserRemarks(oldData.id) || cleanRemarks(oldData.remarks) || '';
    
    // Clear items grid and add one empty row
    document.getElementById('so-items-grid-body').innerHTML = '';
    addSORow();
    recalculateSOTotal();
}

function openGRNModalFromSO(so, subType = 'plain') {
    grnWizardState.type = 'fabric';
    grnWizardState.source = 'customer';
    grnWizardState.subType = subType;
    openGRNModal();
    // Set customer and reinit searchable select display
    const custSel = document.getElementById('grn-customer');
    custSel.value = so.customerId;
    reinitSearchableSelect(custSel);
    
    if (subType === 'plain') {
        currentGRNLinks = [so.id];
        window.renderGRNFormSOLinks();
        window.populateSOLinkSelectForGRN();
    } else {
        // Populate SO options for this customer
        filterGRNSalesOrders();
        // Set the SO ref and reinit its display
        const soRefSel = document.getElementById('grn-so-ref');
        soRefSel.value = so.id;
        reinitSearchableSelect(soRefSel);
    }
    // Auto-fill GRN rows from SO items
    fillGRNFromSO();
}

function renderSOTable() {
    const tbody = document.getElementById('tx-so-table-body');
    if (!tbody) return;
    db.salesOrders = db.salesOrders || [];

    function getBaseNumber(numberStr) {
        if (!numberStr) return null;
        const parts = String(numberStr).split('/').map(p => p.trim());
        for (let i = parts.length - 1; i >= 0; i--) {
            if (/^\d+$/.test(parts[i])) return parseInt(parts[i], 10);
        }
        let newMatch = numberStr.match(/(?:SO|PO)\/?(?:VEN|INH|CON|OTH|FJW)?\/(?:\d{4}-\d{2}|\d{2}-\d{2})\/(\d+)/i);
        if (newMatch) return parseInt(newMatch[1], 10);
        let matchDigits = numberStr.match(/\d+$/);
        if (matchDigits) return parseInt(matchDigits[0], 10);
        return null;
    }

    const baseNumbersMap = new Map();
    db.salesOrders.forEach(so => {
        const base = getBaseNumber(so.number);
        if (base !== null) {
            if (!baseNumbersMap.has(base)) {
                baseNumbersMap.set(base, []);
            }
            baseNumbersMap.get(base).push(so);
        }
    });

    let maxBase = 0;
    for (let base of baseNumbersMap.keys()) {
        if (base > maxBase) maxBase = base;
    }

    const fySuffix = (financialYears[currentFinancialYear] || {}).suffix || '/26-27';
    const cleanSuffix = fySuffix.startsWith('/') ? fySuffix.substring(1) : fySuffix;

    const itemsToRender = [];
    for (let i = 1; i <= maxBase; i++) {
        if (baseNumbersMap.has(i)) {
            itemsToRender.push(...baseNumbersMap.get(i));
        } else {
            itemsToRender.push({
                id: `placeholder_so_${i}`,
                number: getDocumentNumber('SO', i),
                isPlaceholder: true,
                partyOrderNo: '-',
                date: '',
                customerName: 'Cancelled',
                designNumber: '-',
                qty: 0,
                rate: 0,
                amount: 0,
                status: 'Cancelled'
            });
        }
    }
    
    window.renderDynamicHeader('so', 'tx-so-table-head');
    const config = window.getTableColumnConfig('so');

    const search = (document.getElementById('tx-so-search')?.value || '').toLowerCase().trim();
    const filtered = itemsToRender.filter(so => {
        if (!search) return true;
        const num = (so.number || '').toLowerCase();
        const party = (so.customerName || so.customer_name || so.partyName || '').toLowerCase();
        const status = (so.status || '').toLowerCase();
        const partyOrderNo = (so.partyOrderNo || so.party_order_no || so.partyDocNo || so.poNo || so.poNumber || '').toLowerCase();
        const designNo = (so.designNumber || so.designNo || so.designId || so.design || '').toLowerCase();
        const itemName = (so.itemName || so.item_name || '').toLowerCase();
        const remarks = (so.remarks || '').toLowerCase();
        const designDisplay = (typeof window.getSoDesignOrItemDisplay === 'function' ? window.getSoDesignOrItemDisplay(so) : '').toLowerCase();

        if (num.includes(search) || party.includes(search) || status.includes(search) ||
            partyOrderNo.includes(search) || designNo.includes(search) || itemName.includes(search) ||
            remarks.includes(search) || designDisplay.includes(search)) {
            return true;
        }

        if (so.items && Array.isArray(so.items)) {
            for (const it of so.items) {
                if (!it) continue;
                const itName = (it.itemName || it.item_name || it.processName || '').toLowerCase();
                const itDesign = (it.designNumber || it.designNo || it.designName || '').toLowerCase();
                if (itName.includes(search) || itDesign.includes(search)) return true;

                if (it.itemId) {
                    const itemObj = (db.items || []).find(x => x.id === it.itemId);
                    if (itemObj && itemObj.name && itemObj.name.toLowerCase().includes(search)) return true;
                }
            }
        }
        return false;
    });

    // Apply sorting dynamically
    const sortConf = window.tableSortConfig?.so || { field: 'number', order: 'asc' };
    const sortField = sortConf.field;
    const sortOrder = sortConf.order === 'asc' ? 1 : -1;
    filtered.sort((a, b) => {
        let valA = '';
        let valB = '';

        if (sortField === 'number') {
            const numA = getBaseNumber(a.number) || 0;
            const numB = getBaseNumber(b.number) || 0;
            return (numA - numB) * sortOrder;
        } else if (sortField === 'date') {
            valA = a.date ? new Date(a.date).getTime() : 0;
            valB = b.date ? new Date(b.date).getTime() : 0;
        } else if (sortField === 'customerName') {
            valA = a.customerName || '';
            valB = b.customerName || '';
        } else if (sortField === 'itemName') {
            valA = a.designNumber || (a.items?.[0] ? ((db.items || []).find(x => x.id === a.items[0].itemId)?.name || '') : '');
            valB = b.designNumber || (b.items?.[0] ? ((db.items || []).find(x => x.id === b.items[0].itemId)?.name || '') : '');
        } else if (sortField === 'qty') {
            valA = a.items && a.items.length > 0 ? a.items.reduce((s, it) => s + (it.qty || 0), 0) : (a.qty || 0);
            valB = b.items && b.items.length > 0 ? b.items.reduce((s, it) => s + (it.qty || 0), 0) : (b.qty || 0);
        } else if (sortField === 'rate') {
            valA = a.items?.[0]?.price || a.rate || 0;
            valB = b.items?.[0]?.price || b.rate || 0;
        } else if (sortField === 'totalValue') {
            valA = a.totalValue || a.amount || 0;
            valB = b.totalValue || b.amount || 0;
        } else if (sortField === 'deliveryDate') {
            valA = a.deliveryDate ? new Date(a.deliveryDate).getTime() : 0;
            valB = b.deliveryDate ? new Date(b.deliveryDate).getTime() : 0;
        } else if (sortField === 'status') {
            valA = a.status || '';
            valB = b.status || '';
        } else if (sortField === 'partyOrderNo') {
            valA = a.partyOrderNo || '';
            valB = b.partyOrderNo || '';
        }

        if (typeof valA === 'number' && typeof valB === 'number') {
            return (valA - valB) * sortOrder;
        }
        return String(valA).localeCompare(String(valB)) * sortOrder;
    });

    const visibleCols = config.filter(c => c.visible !== false).length;
    if (filtered.length === 0) {
        tbody.innerHTML = `<tr><td colspan="${visibleCols + 2}" class="empty-row">No Sales Orders.</td></tr>`;
        return;
    }
    
    tbody.innerHTML = filtered.map(so => {
        const isPlaceholder = so.isPlaceholder;
        const status = so.status || 'Pending';
        const isCancelledOrPlaceholder = isPlaceholder || status.trim().toLowerCase() === 'cancelled';
        const cancelledHtml = '<span style="color: #ef4444; font-weight: bold; text-transform: uppercase;">CANCELLED</span>';
        let rawItemName = window.getSoDesignOrItemDisplay(so);
        if (!rawItemName || rawItemName === 'null' || rawItemName === 'undefined') {
            rawItemName = '-';
        }
        const itemName = isCancelledOrPlaceholder ? cancelledHtml : rawItemName;
        const qty = isCancelledOrPlaceholder ? 0 : (so.items && so.items.length > 0 ? so.items.reduce((s, it) => s + (it.qty || 0), 0) : (so.qty || 0));
        const totalValue = isCancelledOrPlaceholder ? 0 : (so.totalValue || so.amount || 0);
        const rate = isCancelledOrPlaceholder ? 0 : (so.items?.[0]?.price || so.rate || 0);
        const statusBadge = `<span class="badge ${status === 'Completed' ? 'badge-green' : status === 'Cancelled' ? 'badge-red' : 'badge-orange'}">${status}</span>`;

        const numberDisplay = isPlaceholder 
            ? (checkPermission('so', 'edit_cancelled') ? `<strong><a href="#" onclick="openSOModal(null, '${so.number}')" style="${isCancelledOrPlaceholder ? 'color: var(--accent-red, #ef4444) !important;' : ''}">${so.number}</a></strong>` : `<span style="${isCancelledOrPlaceholder ? 'color: var(--accent-red, #ef4444) !important;' : ''}">${so.number}</span>`)
            : `<strong><a href="#" onclick="openSOModal('${so.id}')" style="${isCancelledOrPlaceholder ? 'color: var(--accent-red, #ef4444) !important;' : ''}">${so.number}</a></strong>`;
        const partyOrderNoDisplay = isCancelledOrPlaceholder ? cancelledHtml : (so.partyOrderNo || '-');
        const dateDisplay = isCancelledOrPlaceholder ? cancelledHtml : formatDate(so.date);
        const customerDisplay = isCancelledOrPlaceholder ? cancelledHtml : (so.customerName ? `<a href="#" onclick="openCustomerModalByName('${so.customerName.replace(/'/g, "\\'")}'); return false;" style="color: var(--primary, #4f7df5); font-weight: 500; text-decoration: underline;" title="Click to view customer details">${so.customerName}</a>` : '-');
        const qtyDisplay = isCancelledOrPlaceholder ? cancelledHtml : qty.toLocaleString('en-IN');
        const rateDisplay = isCancelledOrPlaceholder ? cancelledHtml : `\u20B9${rate.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
        const totalDisplay = isCancelledOrPlaceholder ? cancelledHtml : `\u20B9${totalValue.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
        const deliveryDateDisplay = isCancelledOrPlaceholder ? cancelledHtml : formatDate(so.deliveryDate);
        const checkboxDisplay = isPlaceholder ? '' : `<input type="checkbox" class="chk-select-so" value="${so.id}" onchange="toggleBulkDeleteButton('so')">`;
        
        const hasEditPerm = isCancelledOrPlaceholder ? checkPermission('so', 'edit_cancelled') : checkPermission('so', 'write');
        const hasDeletePerm = !isPlaceholder && checkPermission('so', 'delete');
        
        let actionsDisplay = '-';
        if (hasEditPerm || hasDeletePerm || (!isPlaceholder && checkPermission('so', 'write'))) {
            actionsDisplay = `
                <div class="table-actions">
                    ${hasEditPerm ? `<button class="btn btn-sm btn-secondary" onclick="openSOModal(${isPlaceholder ? 'null' : `'${so.id}'`}${isPlaceholder ? `, '${so.number}'` : ''})" title="Edit"></button>` : ''}
                    ${hasDeletePerm ? `<button class="btn btn-sm btn-danger" onclick="deleteSO('${so.id}')" title="Delete">=�</button>` : ''}
                    ${!isPlaceholder && checkPermission('so', 'write') ? `<button class="btn btn-sm btn-primary" onclick="window.confirmAndSyncSO('${so.id}')" title="Sync to Busy ERP">=</button>` : ''}
                </div>
            `;
        }

        const tds = config.map(col => {
            if (col.visible === false) return '';
            if (col.key === 'number') return `<td>${numberDisplay}</td>`;
            if (col.key === 'partyOrderNo') return `<td>${partyOrderNoDisplay}</td>`;
            if (col.key === 'date') return `<td>${dateDisplay}</td>`;
            if (col.key === 'customerName') return `<td>${customerDisplay}</td>`;
            if (col.key === 'itemName') return `<td class="cell-item-name wrap-text">${itemName}</td>`;
            if (col.key === 'qty') return `<td>${qtyDisplay}</td>`;
            if (col.key === 'rate') return `<td>${rateDisplay}</td>`;
            if (col.key === 'totalValue') return `<td>${totalDisplay}</td>`;
            if (col.key === 'deliveryDate') return `<td>${deliveryDateDisplay}</td>`;
            if (col.key === 'status') return `<td>${statusBadge}</td>`;
            return '';
        }).filter(Boolean).join('');

        return `
            <tr class="${isCancelledOrPlaceholder ? 'row-cancelled' : ''}" style="${isPlaceholder ? 'font-style: italic;' : ''}">
                <td>${checkboxDisplay}</td>
                ${tds}
                <td>${actionsDisplay}</td>
            </tr>
        `;
    }).join('');
    if (typeof renderPendingTransactionsWidget === 'function') {
        renderPendingTransactionsWidget();
    }
}

async function deleteSO(id) {
    const so = (rawDB.salesOrders || []).find(x => x.id === id);
    const docNo = so ? so.number : '';
    if (!(await window.showSmartConfirm('Delete Sales Order', 'Are you sure you want to delete this Sales Order?'))) return;
    try {
        await deleteFromSupabase('sales_orders', id);
        rawDB.salesOrders = rawDB.salesOrders.filter(so => so.id !== id);
        applyFinancialYearFilters();
        renderSOTable();
        logUserAction('Sales Orders', 'Deleted', `Deleted sales order: ${docNo}`);
        showToast('Sales Order Deleted', 'info');
    } catch(e) {}
}

window.confirmAndSyncSO = async function(id) {
    if (window.isBusySyncPaused('so')) {
        showToast('Sync for Sales Orders is temporarily paused.', 'warning');
        return;
    }
    const so = (rawDB.salesOrders || []).find(x => x.id === id);
    if (!so) {
        showToast('Sales Order not found.', 'error');
        return;
    }
    
    if (!(await window.showSmartConfirm('Sync to Busy ERP', `Do you want to sync Sales Order ${so.number} to Busy ERP?`))) {
        return;
    }
    
    showToast('Queueing Sales Order for Busy...', 'info');
    
    try {
        const { data: synced } = await supabase
            .from('busy_sync_queue')
            .select('id')
            .eq('voucher_id', so.id)
            .eq('status', 'success')
            .limit(1);
        
        const isEdit = synced && synced.length > 0;
        
        await window.queueSalesOrderForBusySync(so, isEdit);
        showToast('Sales Order queued! Cloud agent will sync it shortly.', 'success');
    } catch (err) {
        showToast('Failed to queue Sales Order: ' + err.message, 'error');
    }
};

