window.addGrnFabricUsedChallanLink = function(selectedChallanId = null) {
    if (!selectedChallanId) {
        const selectEl = document.getElementById('grn-fabric-used-select-challan');
        selectedChallanId = selectEl ? selectEl.value : '';
    }
    if (!selectedChallanId) {
        showToast('Please select a challan first', 'error');
        return;
    }

    const matchedOutward = db.outwards.find(o => o.id === selectedChallanId);
    if (!matchedOutward) {
        showToast('Selected challan not found', 'error');
        return;
    }

    // Check if this challan is already linked in this table
    const existingRows = document.querySelectorAll('.grn-fabric-used-row');
    let isAlreadyLinked = false;
    existingRows.forEach(row => {
        if (row.getAttribute('data-issue-id') === selectedChallanId) {
            isAlreadyLinked = true;
        }
    });
    if (isAlreadyLinked) {
        showToast('This challan is already linked in the table.', 'warning');
        return;
    }

    const fabricTypes = new Set();
    if (matchedOutward.dispatchedPackages && matchedOutward.dispatchedPackages.length > 0) {
        matchedOutward.dispatchedPackages.forEach(pkg => {
            let pkgFabType = pkg.fabricType;
            if (!pkgFabType && pkg.grnId) {
                if (pkg.convertedDone && matchedOutward.remarks && matchedOutward.remarks.includes('__CONVERTED_LOG__:')) {
                    try {
                        const m = matchedOutward.remarks.match(/__CONVERTED_LOG__:(.*)/);
                        if (m && m[1]) {
                            const convertedLog = JSON.parse(m[1].trim());
                            const batches = convertedLog[pkg.grnId] || [];
                            for (const batch of batches) {
                                const matchedItem = batch.items?.find(it => it.sIdx === pkg.slipIndex && it.pIdx === pkg.packageIndex);
                                if (matchedItem && (matchedItem.fabricType || matchedItem.slipType)) {
                                    pkgFabType = matchedItem.fabricType || matchedItem.slipType;
                                    break;
                                }
                            }
                        }
                    } catch (e) {
                        console.error("Error parsing __CONVERTED_LOG__:", e);
                    }
                }
                if (!pkgFabType) {
                    const srcGrn = db.grns.find(g => g.id === pkg.grnId);
                    if (srcGrn && srcGrn.packageSlips) {
                        const slip = srcGrn.packageSlips[pkg.slipIndex];
                        if (slip) {
                            pkgFabType = slip.fabricType;
                        }
                    }
                }
            }
            if (pkgFabType) fabricTypes.add(pkgFabType);
        });
    }
    if (fabricTypes.size === 0) {
        fabricTypes.add(matchedOutward.fabricType || 'Plain Fabric');
    }

    fabricTypes.forEach(fabType => {
        window.addGrnFabricUsedRow({
            issueId: selectedChallanId,
            issueNo: matchedOutward.number || matchedOutward.outwardNo || '',
            fabricType: fabType,
            than: '',
            conversion: '',
            qty: ''
        });
    });

    const selectEl = document.getElementById('grn-fabric-used-select-challan');
    if (selectEl) selectEl.value = '';
    reinitSearchableSelect(selectEl);

    syncGrnData();
};

window.onGrnFabricUsedRowCalc = function(inputEl) {
    const row = inputEl.closest('.grn-fabric-used-row');
    if (!row) return;
    const than = parseFloat(row.querySelector('.grn-fabric-used-than').value) || 0;
    const conversion = parseFloat(row.querySelector('.grn-fabric-used-conversion').value) || 0;
    const qtyInput = row.querySelector('.grn-fabric-used-qty');
    if (qtyInput) {
        qtyInput.value = (than * conversion).toFixed(2);
    }
    syncGrnData();
};

window.removeGrnFabricUsedRow = function(btnEl) {
    const row = btnEl.closest('.grn-fabric-used-row');
    if (!row) return;
    const tbody = row.parentNode;
    row.remove();

    if (tbody && tbody.querySelectorAll('.grn-fabric-used-row').length === 0) {
        tbody.innerHTML = `<tr><td colspan="7" class="empty-row" style="text-align:center; padding:8px; color:var(--text-muted);">No challans linked.</td></tr>`;
    }
    syncGrnData();
};

window.updateGrnFabricIssues = function() {
    const isVendorEmbroidery = (grnWizardState.type === 'fabric' && grnWizardState.source === 'vendor' && grnWizardState.subType === 'embroidered');
    if (!isVendorEmbroidery) return;

    const selectEl = document.getElementById('grn-fabric-used-select-challan');
    if (!selectEl) return;

    selectEl.innerHTML = '<option value="">-- Select Challan No --</option>';

    const vendorId = document.getElementById('grn-customer')?.value || '';
    const poId = document.getElementById('grn-so-ref')?.value || '';

    const vendorObj = (db.vendors || []).find(v => v.id === vendorId || v.name === vendorId);
    const vendorName = vendorObj ? vendorObj.name : '';
    const vendorIdVal = vendorObj ? vendorObj.id : '';

    const po = poId ? (db.pos || []).find(p => p.id === poId || p.number === poId) : null;
    const poNumber = po ? po.number : '';

    db.outwards = db.outwards || [];
    const plainIssues = db.outwards.filter(out => {
        const state = parseOutwardWizardState(out);
        const isVendorPlainOutward = ((state.type === 'fabric' || state.type === 'fabric_issue_challan') && state.source === 'vendor' && state.subType === 'plain');
        if (!isVendorPlainOutward || out.status === 'Cancelled') return false;

        const matchesVendor = (out.vendorId && (out.vendorId === vendorIdVal || out.vendorId === vendorName)) ||
                              (out.vendor_id && (out.vendor_id === vendorIdVal || out.vendor_id === vendorName)) ||
                              (out.vendorName && (out.vendorName === vendorName || out.vendorName === vendorIdVal)) ||
                              (!out.vendorId && !out.vendor_id && !out.vendorName); // Fallback for unspecified

        const matchesPO = (out.poRefId && (out.poRefId === poId || out.poRefId === poNumber)) ||
                          (out.linked_po_id && (out.linked_po_id === poId || out.linked_po_id === poNumber)) ||
                          (out.linked_po_number && (out.linked_po_number === poId || out.linked_po_number === poNumber)) ||
                          (out.poNo && (out.poNo === poId || out.poNo === poNumber));

        return matchesVendor && matchesPO;
    });

    plainIssues.forEach(out => {
        const opt = document.createElement('option');
        opt.value = out.id;
        opt.textContent = `${out.outwardNo || out.number} (Date: ${typeof formatDisplayDate === 'function' ? formatDisplayDate(out.date) : (out.date || '')})`;
        selectEl.appendChild(opt);
    });

    reinitSearchableSelect(selectEl);
};

window.isPartyOutstation = function(partyId, staticName = '') {
    const nameLower = String(staticName || '').toLowerCase().trim();
    if (nameLower.includes('kratika') || nameLower.includes('bella casa') || nameLower.includes('jai fab')) {
        return false;
    }
    if (nameLower.includes('swiss') || nameLower.includes('cocoon')) {
        return true;
    }
    
    if (!partyId && !staticName) return false;

    const vendorsList = [...(typeof rawDB !== 'undefined' && rawDB.vendors || []), ...(db.vendors || []), ...(window.crossCompanyVendors || [])];
    const customersList = [...(typeof rawDB !== 'undefined' && rawDB.customers || []), ...(db.customers || []), ...(window.crossCompanyCustomers || [])];

    let party = vendorsList.find(v => String(v.id) === String(partyId) || v.name === partyId) || 
                customersList.find(c => String(c.id) === String(partyId) || c.name === partyId);

    if (!party && nameLower) {
        party = vendorsList.find(v => v.name && v.name.toLowerCase().trim() === nameLower) ||
                customersList.find(c => c.name && c.name.toLowerCase().trim() === nameLower);
    }

    if (!party) {
        const fallbackVendors = (typeof defaultDB !== 'undefined' && defaultDB.vendors) || [];
        const fallbackCustomers = (typeof defaultDB !== 'undefined' && defaultDB.customers) || [];
        party = fallbackVendors.find(v => String(v.id) === String(partyId) || (v.name && v.name.toLowerCase().trim() === nameLower)) || 
                fallbackCustomers.find(c => String(c.id) === String(partyId) || (c.name && c.name.toLowerCase().trim() === nameLower));
    }

    const city = (party ? party.city || '' : '').toLowerCase().trim();
    const address = (party ? party.address || '' : '').toLowerCase().trim();
    const state = (party ? party.state || '' : '').toLowerCase().trim();
    const name = (party ? party.name || '' : nameLower).toLowerCase().trim();
    const pincode = String((party ? (party.pincode || party.pinCode || party.pin || party.zip) : '') || '').trim();

    if (city.includes('faridabad') || address.includes('faridabad') || name.includes('fbd') || name.includes('faridabad') || state.includes('haryana') || pincode.startsWith('121') || name.includes('swiss') || name.includes('cocoon')) {
        return true;
    }

    if (city.includes('jaipur') || address.includes('jaipur') || state.includes('jaipur') || name.includes('jaipur') ||
        name.includes('kratika') || name.includes('bella casa') || name.includes('jai fab')) {
        return false;
    }

    if (pincode) {
        if (pincode.startsWith('302')) {
            return false;
        } else {
            return true;
        }
    }

    return false;
};

window.onTransporterSelectChange = function() {
    const transId = document.getElementById('grn-transporter').value;
    const trans = (db.transporters || []).find(t => t.id === transId);
    const gstEl = document.getElementById('grn-transporter-gst');
    if (gstEl) {
        gstEl.value = trans ? (trans.gst || trans.gstNo || '') : '';
    }
    if (typeof window.toggleTransportSection === 'function') {
        window.toggleTransportSection();
    }
};

window.toggleTransportSection = function() {
    const partyId = document.getElementById('grn-customer')?.value || '';
    const partyObj = (db.vendors || []).find(v => v.id === partyId) || (db.customers || []).find(c => c.id === partyId);
    const partyName = partyObj ? partyObj.name : partyId;

    if (partyId) {
        const pincode = String(partyObj ? (partyObj.pincode || partyObj.pinCode || partyObj.pin || partyObj.zip || '') : '').trim();
        if (!pincode) {
            if (window._lastPincodeWarnedParty !== partyId && typeof showToast === 'function') {
                showToast(`Warning: Pincode is not specified for party "${partyName || partyId}". Please update pincode in Masters.`, 'warning');
                window._lastPincodeWarnedParty = partyId;
            }
        } else if (window._lastPincodeWarnedParty === partyId) {
            window._lastPincodeWarnedParty = null;
        }
    }

    const isOutstation = window.isPartyOutstation(partyId, partyName);

    const hasTransEl = document.getElementById('grn-has-transporter');
    const localFreightSelect = document.getElementById('grn-has-local-freight');

    if (partyId && !isOutstation && hasTransEl && hasTransEl.value === 'Yes') {
        if (typeof showToast === 'function') {
            showToast('Transporter is not applicable for local parties. Reverted to No.', 'warning');
        }
        hasTransEl.value = 'No';
        if (typeof reinitSearchableSelect === 'function') {
            reinitSearchableSelect(hasTransEl);
        }
    }

    if (!isOutstation) {
        // Local party: Local freight is mandatory
        if (localFreightSelect) {
            localFreightSelect.disabled = false;
            localFreightSelect.title = '';
        }
    } else {
        // Outstation party: Transporter is mandatory
        if (localFreightSelect) {
            localFreightSelect.disabled = false;
            localFreightSelect.title = '';
        }
    }

    const hasTrans = hasTransEl?.value === 'Yes';
    const hasFreight = (localFreightSelect?.value === 'Yes');

    const tInline = document.getElementById('grn-transporter-inline');
    const fInline = document.getElementById('grn-local-freight-inline');
    if (tInline) tInline.style.display = hasTrans ? 'flex' : 'none';
    if (fInline) fInline.style.display = hasFreight ? 'flex' : 'none';

    const tGroup = document.getElementById('grn-transporter-group');
    const fGroup = document.getElementById('grn-local-freight-group');
    if (tGroup) tGroup.style.display = 'none';
    if (fGroup) fGroup.style.display = 'none';

    if (typeof reinitSearchableSelect === 'function' && localFreightSelect) {
        reinitSearchableSelect(localFreightSelect);
    }
};
const toggleTransportSection = window.toggleTransportSection;

window.getGrnPermissionModule = function(grn) {
    if (!grn) {
        if (typeof grnWizardState !== 'undefined' && grnWizardState) {
            if (grnWizardState.type === 'fabric') {
                if (grnWizardState.source === 'customer') return 'grn_cust_plain';
                return 'grn_vend_emb';
            }
            return 'grn_consumable';
        }
        return 'grn_cust_plain';
    }
    const type = grn.type || (grn.grnNo || grn.number || '').split('/')[1] || '';
    if (type.includes('C') && type.includes('PF')) return 'grn_cust_plain';
    if (type.includes('V') && type.includes('EM')) return 'grn_vend_emb';
    if (type.includes('CON') || type.includes('OTH')) return 'grn_consumable';
    const no = (grn.grnNo || grn.number || '').toUpperCase();
    if (no.startsWith('GRN/C/PF')) return 'grn_cust_plain';
    if (no.startsWith('GRN/V/EM') || no.startsWith('GRN/V/PF') || no.startsWith('GRN/V/EMB')) return 'grn_vend_emb';
    if (no.startsWith('GRN/CON') || no.startsWith('GRN/OTH')) return 'grn_consumable';
    return 'grn_cust_plain';
};

window.updateGrnCustPfLayout = function() {
    const isPlainFabricCustomer = (grnWizardState.type === 'fabric' && grnWizardState.source === 'customer' && grnWizardState.subType === 'plain');
    if (!isPlainFabricCustomer) return;

    const packingSlipsContainer = document.getElementById('grn-packing-slips-container');
    const addSlipBtnContainer = document.getElementById('grn-add-slip-btn-container');
    const consumableContainer = document.getElementById('grn-consumable-container');
    const sectionTitleEl = consumableContainer ? consumableContainer.querySelector('.form-section-title') : null;

    const linkedSos = (db.salesOrders || []).filter(s => currentGRNLinks.includes(s.id));
    
    let showPackingSlips = true;
    let showConsumableMatrix = false;
    
    if (linkedSos.length > 0) {
        showPackingSlips = linkedSos.some(so => so.materialType === 'without_material' || so.materialType === 'consumable_customer_fabric');
        showConsumableMatrix = linkedSos.some(so => so.materialType === 'with_material' || so.materialType === 'consumable_customer_fabric');
    }

    if (packingSlipsContainer) packingSlipsContainer.style.display = showPackingSlips ? 'block' : 'none';
    if (addSlipBtnContainer) addSlipBtnContainer.style.display = showPackingSlips ? 'block' : 'none';
    
    if (consumableContainer) {
        consumableContainer.style.display = showConsumableMatrix ? 'block' : 'none';
        if (sectionTitleEl) {
            sectionTitleEl.textContent = 'Consumable Fabric Detail';
        }
        
        const headerCons = document.getElementById('grn-consumable-header');
        if (showConsumableMatrix && headerCons) {
            if (!headerCons.innerHTML.trim()) {
                headerCons.innerHTML = `
                    <th>Item name *</th>
                    <th style="width:150px; text-align:center;">Quantity *</th>
                    <th style="width:120px; text-align:center;">Unit</th>
                    <th style="width:40px;"></th>
                `;
            }
            const body = document.getElementById('grn-consumable-body');
            if (body && body.children.length === 0) {
                window.addConsumableRow();
            }
        }
    }
};

window.handleGRNSeriesChange = function(seriesVal) {
    if (!seriesVal) return;
    if (seriesVal === 'fabric_cust_plain') {
        grnWizardState.type = 'fabric';
        grnWizardState.source = 'customer';
        grnWizardState.subType = 'plain';
    } else if (seriesVal === 'fabric_cust_emb') {
        grnWizardState.type = 'fabric';
        grnWizardState.source = 'customer';
        grnWizardState.subType = 'embroidered';
    } else if (seriesVal === 'fabric_vend_plain') {
        grnWizardState.type = 'fabric';
        grnWizardState.source = 'vendor';
        grnWizardState.subType = 'plain';
    } else if (seriesVal === 'fabric_vend_emb') {
        grnWizardState.type = 'fabric';
        grnWizardState.source = 'vendor';
        grnWizardState.subType = 'embroidered';
    } else if (seriesVal === 'consumable') {
        grnWizardState.type = 'consumable';
        grnWizardState.source = 'vendor';
        grnWizardState.subType = null;
    } else if (seriesVal === 'other') {
        grnWizardState.type = 'other';
        grnWizardState.source = 'vendor';
        grnWizardState.subType = null;
    }

    const editIdEl = document.getElementById('grn-edit-id');
    const editId = editIdEl ? editIdEl.value : null;
    openGRNModal(editId || null, null, true);
};

async function openGRNModal(editId = null, customDocNo = null, keepWizardState = false) {
    let targetGrn = editId ? db.grns.find(g => g.id === editId) : null;
    const permModule = window.getGrnPermissionModule(targetGrn);
    if (!editId) {
        if (!checkPermission(permModule, 'write')) {
            showToast('Permission Denied: Restricted Entry', 'error');
            return;
        }
    }
    if (!checkPermission(permModule, 'read')) {
        showToast('Permission Denied', 'error');
        return;
    }

    populateSOAndPODropdowns();
    document.getElementById('grn-edit-id').value = editId || '';
    
    if (editId) {
        const grn = db.grns.find(g => g.id === editId);
        if (grn) {
            if ((grn.status || '').trim().toLowerCase() === 'cancelled') {
                if (await window.showSmartConfirm('Activate Voucher', 'This voucher is cancelled. Do you want to activate this voucher?')) {
                    grn.status = 'Received';
                    await saveToSupabase('grns', grn);
                    window.reactivatedVouchers = window.reactivatedVouchers || {};
                    window.reactivatedVouchers['grn-modal'] = { table: 'grns', localArray: 'grns', id: grn.id };
                    showToast('Voucher activated successfully!', 'success');
                    if (typeof renderGRNTable === 'function') renderGRNTable();
                } else {
                    return;
                }
            }
            if (!keepWizardState) {
                const loadedState = parseGrnWizardState(grn);
                grnWizardState.type = loadedState.type;
                grnWizardState.source = loadedState.source;
                grnWizardState.subType = loadedState.subType;
            }
        }
    }
    
    const grnSeriesSel = document.getElementById('grn-series-select');
    if (grnSeriesSel) {
        if (grnWizardState.type === 'fabric') {
            if (grnWizardState.source === 'customer') {
                grnSeriesSel.value = (grnWizardState.subType === 'embroidered') ? 'fabric_cust_emb' : 'fabric_cust_plain';
            } else {
                grnSeriesSel.value = (grnWizardState.subType === 'embroidered') ? 'fabric_vend_emb' : 'fabric_vend_plain';
            }
        } else if (grnWizardState.type === 'consumable') {
            grnSeriesSel.value = 'consumable';
        } else if (grnWizardState.type === 'other') {
            grnSeriesSel.value = 'other';
        }
    }
    
    let modalTitle = editId ? 'Edit Goods Receipt Note' : 'New Goods Receipt Note';
    if (grnWizardState.type === 'fabric') {
        const subTypeStr = grnWizardState.subType === 'plain' ? 'Plain Fabric' : 
                          grnWizardState.subType === 'embroidered' ? 'Embroidered Fabric' : 'Fabric';
        const sourceStr = grnWizardState.source === 'customer' ? 'From Customer' : 
                         grnWizardState.source === 'vendor' ? 'From Vendor' : '';
        modalTitle += ` - ${subTypeStr} - ${sourceStr}`;
    } else if (grnWizardState.type === 'consumable') {
        modalTitle += ' - Consumables';
    } else if (grnWizardState.type === 'other') {
        modalTitle += ' - Other Items';
    }
    const grnTitleEl = document.getElementById('grn-modal-title');
    if (grnTitleEl) grnTitleEl.textContent = modalTitle;
    
    const labelEl = document.getElementById('grn-customer-label');
    const custSel = document.getElementById('grn-customer');
    const isCustomerSource = (grnWizardState.type === 'fabric' && grnWizardState.source === 'customer');
    const isVendorPlain = (grnWizardState.type === 'fabric' && grnWizardState.source === 'vendor' && grnWizardState.subType === 'plain');
    
    const docNoLabelEl = document.getElementById('grn-party-doc-no-label');
    const docNoInputEl = document.getElementById('grn-party-doc-no');
    if (isCustomerSource) {
        if (labelEl) labelEl.textContent = 'Customer *';
        if (docNoLabelEl) docNoLabelEl.textContent = 'Party Challan No. *';
        if (docNoInputEl) docNoInputEl.placeholder = 'e.g. CH-2026-001';
        custSel.innerHTML = '<option value="">-- Select Customer --</option>';
        db.customers = db.customers || [];
        db.customers.filter(c => c.status !== 'Cancelled').forEach(c => {
            const opt = document.createElement('option');
            opt.value = c.id;
            opt.textContent = c.name;
            custSel.appendChild(opt);
        });
    } else {
        if (labelEl) labelEl.textContent = 'Vendor *';
        if (docNoLabelEl) docNoLabelEl.textContent = 'Purchase Invoice No. *';
        if (docNoInputEl) docNoInputEl.placeholder = 'e.g. PI-2026-001';
        custSel.innerHTML = '<option value="">-- Select Vendor / Party --</option>';
        db.vendors = db.vendors || [];
        
        let vendorsToUse = db.vendors.filter(v => v.id !== 'inhouse' && v.status !== 'Cancelled');
        if (grnWizardState.type === 'consumable') {
            const consumableGroupIds = (db.vendorGroups || [])
                .filter(g => g.name && g.name.toLowerCase().includes('consumable'))
                .map(g => g.id);
            vendorsToUse = vendorsToUse.filter(v => {
                if (v.group && consumableGroupIds.includes(v.group)) return true;
                const groupStr = String(v.group || '').toLowerCase();
                if (groupStr.includes('consumable')) return true;
                const specStr = String(v.spec || '').toLowerCase();
                if (specStr.includes('consumable') || specStr.includes('chemical') || specStr.includes('yarn')) return true;
                return false;
            });
        }

        vendorsToUse.forEach(v => {
            const opt = document.createElement('option');
            opt.value = v.id;
            opt.textContent = v.name;
            custSel.appendChild(opt);
        });

        // Include customers if vendor list is missing the party (only if not a consumables GRN)
        if (grnWizardState.type !== 'consumable') {
            db.customers = db.customers || [];
            db.customers.filter(c => c.status !== 'Cancelled').forEach(c => {
                if (!db.vendors.some(v => v.id === c.id || v.name.toLowerCase().trim() === c.name.toLowerCase().trim())) {
                    const opt = document.createElement('option');
                    opt.value = c.id;
                    opt.textContent = c.name + ' (Customer)';
                    custSel.appendChild(opt);
                }
            });
        }
    }
    reinitSearchableSelect(custSel);
    
    const isEmbroidery = (grnWizardState.type === 'fabric' && grnWizardState.subType === 'embroidered');
    const isConsumable = (grnWizardState.type === 'consumable');
    const isVendorEmbroidery = (grnWizardState.type === 'fabric' && grnWizardState.source === 'vendor' && grnWizardState.subType === 'embroidered');
    
    const soRefSel = document.getElementById('grn-so-ref');
    const soRefGroup = document.getElementById('grn-so-ref-group');
    const multiSoGroup = document.getElementById('grn-multi-so-group');
    const isPlainFabricCustomer = isCustomerSource && (grnWizardState.subType === 'plain');
    
    if (soRefGroup) {
        const labelElRef = soRefGroup.querySelector('label');
        if (isPlainFabricCustomer) {
            soRefGroup.style.display = 'none';
            if (multiSoGroup) multiSoGroup.style.display = 'block';
        } else {
            if (multiSoGroup) multiSoGroup.style.display = 'none';
            if (isCustomerSource) {
                if (labelElRef) labelElRef.textContent = 'Sales order no';
                soRefGroup.style.display = 'block';
            } else if (isVendorPlain || isVendorEmbroidery) {
                if (labelElRef) labelElRef.textContent = 'PO number';
                soRefGroup.style.display = 'block';
            } else if (isConsumable || grnWizardState.type === 'other') {
                if (labelElRef) labelElRef.textContent = 'Purchase order no';
                soRefGroup.style.display = 'block';
            } else {
                soRefGroup.style.display = 'none';
            }
        }
    }
    
    const custOrderInput = document.getElementById('grn-cust-order-no');
    const custOrderGroup = custOrderInput ? custOrderInput.parentElement : null;
    if (custOrderGroup) {
        const labelElCust = custOrderInput.previousElementSibling;
        if (isEmbroidery || isConsumable) {
            custOrderGroup.style.display = 'none';
        } else {
            if (labelElCust) labelElCust.textContent = 'Cust. Order No.';
            custOrderGroup.style.display = 'block';
        }
    }
    
    const consTypeGroup = document.getElementById('grn-consumable-type-group');
    if (consTypeGroup) {
        if (isConsumable) {
            window.populateConsumableTypeDropdowns();
            consTypeGroup.style.display = 'block';
        } else {
            consTypeGroup.style.display = 'none';
        }
    }
    
    const packingSlipsContainer = document.getElementById('grn-packing-slips-container');
    const addSlipBtnContainer = document.getElementById('grn-add-slip-btn-container');
    const embroideryContainer = document.getElementById('grn-embroidery-container');
    const embroideryBody = document.getElementById('grn-embroidery-body');
    const embroideryHeader = document.getElementById('grn-embroidery-header');
    const consumableContainer = document.getElementById('grn-consumable-container');
    const consumableBody = document.getElementById('grn-consumable-body');
    
    const fabricUsedContainer = document.getElementById('grn-fabric-used-container');
    if (fabricUsedContainer) {
        fabricUsedContainer.style.display = isVendorEmbroidery ? 'block' : 'none';
    }
    if (isEmbroidery) {
        if (packingSlipsContainer) packingSlipsContainer.style.display = 'none';
        if (addSlipBtnContainer) addSlipBtnContainer.style.display = 'none';
        if (embroideryContainer) embroideryContainer.style.display = 'block';
        if (consumableContainer) consumableContainer.style.display = 'none';
        
        if (embroideryHeader) {
            if (isCustomerSource) {
                embroideryHeader.innerHTML = `
                    <th>Item name *</th>
                    <th style="width:120px; text-align:center;">Than *</th>
                    <th style="width:120px; text-align:center;">Conversion *</th>
                    <th style="width:150px; text-align:center;">Quantity *</th>
                    <th style="width:40px;"></th>
                `;
            } else {
                embroideryHeader.innerHTML = `
                    <th>Item name *</th>
                    <th style="width:120px; text-align:center;">Than *</th>
                    <th style="width:120px; text-align:center;">Conversion *</th>
                    <th style="width:150px; text-align:center;">Quantity *</th>
                    <th style="width:40px;"></th>
                `;
            }
        }
        if (embroideryBody) embroideryBody.innerHTML = '';
    } else if (isConsumable || grnWizardState.type === 'other') {
        if (packingSlipsContainer) packingSlipsContainer.style.display = 'none';
        if (addSlipBtnContainer) addSlipBtnContainer.style.display = 'none';
        if (embroideryContainer) embroideryContainer.style.display = 'none';
        if (consumableContainer) consumableContainer.style.display = 'block';
        if (consumableBody) consumableBody.innerHTML = '';
        
        const sectionTitleEl = consumableContainer.querySelector('.form-section-title');
        if (sectionTitleEl) {
            sectionTitleEl.textContent = grnWizardState.type === 'other' ? 'Other Items Detail' : 'Consumable Items Detail';
        }
        
        const headerCons = document.getElementById('grn-consumable-header');
        if (grnWizardState.type === 'other') {
            if (headerCons) {
                headerCons.innerHTML = `
                    <th>Item name *</th>
                    <th style="width:120px; text-align:center;">Order Qty</th>
                    <th style="width:150px; text-align:center;">Received Qty *</th>
                    <th style="width:120px; text-align:center;">Unit</th>
                    <th style="width:40px;"></th>
                `;
            }
        } else {
            const consTypeSel = document.getElementById('grn-consumable-type');
            if (consTypeSel) {
                consTypeSel.value = '';
                reinitSearchableSelect(consTypeSel);
            }
            if (headerCons) headerCons.innerHTML = '';
        }
    } else {
        if (packingSlipsContainer) packingSlipsContainer.style.display = 'block';
        if (addSlipBtnContainer) addSlipBtnContainer.style.display = 'block';
        if (embroideryContainer) embroideryContainer.style.display = 'none';
        if (consumableContainer) consumableContainer.style.display = 'none';
    }
    
    const isPlainFabric = (grnWizardState.type === 'fabric' && grnWizardState.subType === 'plain');
    document.querySelectorAll('#grn-packing-slips-container .grn-row-dimensions').forEach(row => {
        row.style.display = isPlainFabric ? 'flex' : 'none';
    });
    
    const container = document.getElementById('grn-packing-slips-container');
    if (container) container.innerHTML = '';
    
    if (editId) {
        const grn = db.grns.find(g => g.id === editId);
        if (grn) {
            let loadedGrnNo = grn.grnNo || grn.number || '';
            if (loadedGrnNo && window.formatStandardDocNumber) loadedGrnNo = window.formatStandardDocNumber(loadedGrnNo);
            document.getElementById('grn-number').value = loadedGrnNo;
            document.getElementById('grn-date').value = grn.date || '';
            
            let partyId = '';
            if (isCustomerSource) {
                partyId = grn.customerId || grn.customer || '';
                if (!partyId && grn.customerName) {
                    const custObj = (db.customers || []).find(c => c.name.toLowerCase().trim() === String(grn.customerName).toLowerCase().trim());
                    if (custObj) partyId = custObj.id;
                }
            } else {
                partyId = grn.vendorId || grn.vendor || '';
                if (!partyId && grn.vendorName) {
                    const vendObj = (db.vendors || []).find(v => v.name.toLowerCase().trim() === String(grn.vendorName).toLowerCase().trim());
                    if (vendObj) partyId = vendObj.id;
                }
                if (!partyId) {
                    const poIdVal = grn.poRefId || grn.linked_po_id || grn.poRef || '';
                    const poNumVal = grn.poNumber || grn.linked_po_number || '';
                    const linkedPo = (db.pos || []).find(p => (poIdVal && (p.id === poIdVal || p.number === poIdVal)) || (poNumVal && p.number === poNumVal));
                    if (linkedPo) partyId = linkedPo.vendorId || linkedPo.vendor || '';
                }
            }
            if (custSel && partyId) {
                const optExists = Array.from(custSel.options).some(o => o.value === partyId);
                if (!optExists) {
                    if (isCustomerSource) {
                        const c = db.customers.find(x => x.id === partyId);
                        if (c) {
                            const opt = document.createElement('option');
                            opt.value = c.id;
                            opt.textContent = c.name + ' (Cancelled)';
                            custSel.appendChild(opt);
                        }
                    } else {
                        const v = db.vendors.find(x => x.id === partyId);
                        if (v) {
                            const opt = document.createElement('option');
                            opt.value = v.id;
                            opt.textContent = v.name + ' (Cancelled)';
                            custSel.appendChild(opt);
                        }
                    }
                }
            }
            document.getElementById('grn-customer').value = partyId;
            reinitSearchableSelect(custSel);
            
            if (isPlainFabricCustomer) {
                // Automatically find and link SOs pointing to this GRN
                const allSOs = [...(db.salesOrders || []), ...(rawDB.salesOrders || [])];
                const uniqueSOs = new Map();
                allSOs.forEach(s => { if (s && s.id) uniqueSOs.set(String(s.id), s); });

                const soIdsLinkedToThisGRN = Array.from(uniqueSOs.values()).filter(s => 
                    (s.grnLinks && (
                        s.grnLinks.includes(grn.id) || 
                        (grn.number && s.grnLinks.includes('manual:' + grn.number)) || 
                        (grn.grnNo && s.grnLinks.includes('manual:' + grn.grnNo))
                    )) ||
                    s.linked_grn_id === grn.id ||
                    s.grnRefId === grn.id
                ).map(s => s.id);

                let directSoLinks = Array.isArray(grn.soLinks) ? [...grn.soLinks] : (grn.soLinks ? [grn.soLinks] : []);
                if (grn.linked_so_id) directSoLinks.push(grn.linked_so_id);
                if (grn.soRefId) directSoLinks.push(grn.soRefId);
                if (grn.so_id) directSoLinks.push(grn.so_id);

                const remarksStr = grn.remarks || grn.rawRemarks || '';
                if (remarksStr) {
                    const matchRef = remarksStr.match(/\[SO Ref:\s*([^\]]+)\]/i);
                    if (matchRef && matchRef[1]) {
                        const refs = matchRef[1].split(',').map(r => r.trim()).filter(Boolean);
                        directSoLinks.push(...refs);
                    }
                }

                currentGRNLinks = [...new Set([...directSoLinks, ...soIdsLinkedToThisGRN])].filter(Boolean);
                window.currentGRNAllottedQtys = grn.soAllottedQtys || {};
                window.renderGRNFormSOLinks();
                window.populateSOLinkSelectForGRN();
            } else {
                currentGRNLinks = [];
            }
            if (isConsumable || grnWizardState.type === 'other') {
                let loadedConsType = grn.consumable_type || '';
                if (!loadedConsType) {
                    const remarksStr = grn.remarks || '';
                    const matchType = remarksStr.match(/\[CONSUMABLE_TYPE:(.*?)\]/);
                    loadedConsType = matchType ? matchType[1] : '';
                }
                const consTypeSel = document.getElementById('grn-consumable-type');
                if (consTypeSel) {
                    consTypeSel.value = loadedConsType;
                    reinitSearchableSelect(consTypeSel);
                }
                
                filterGRNSalesOrders();
                const targetVal = grn.soRefId || grn.linked_po_id || '';
                const soRefEl = document.getElementById('grn-so-ref');
                if (soRefEl) {
                    soRefEl.value = targetVal;
                    if (targetVal && !soRefEl.value) {
                        const poObj = db.pos ? db.pos.find(p => p.id === targetVal || p.number === targetVal) : null;
                        if (poObj) {
                            const opt = Array.from(soRefEl.options).find(o => o.value === poObj.id || o.value === poObj.number);
                            if (opt) soRefEl.value = opt.value;
                        } else {
                            const soObj = db.salesOrders ? db.salesOrders.find(s => s.id === targetVal || s.number === targetVal) : null;
                            if (soObj) {
                                const opt = Array.from(soRefEl.options).find(o => o.value === soObj.id || o.value === soObj.number);
                                if (opt) soRefEl.value = opt.value;
                            }
                        }
                    }
                }
                reinitSearchableSelect(soRefSel);
                
                if (grnWizardState.type !== 'other') {
                    onConsumableTypeChange();
                }
                
                const hasConsPackingSlip = isConsumable && loadedConsType.toLowerCase().includes('packing slip') && !loadedConsType.toLowerCase().includes('no packing slip');
                
                if (hasConsPackingSlip) {
                    const container = document.getElementById('grn-packing-slips-container');
                    if (container) container.innerHTML = '';
                    if (grn.packageSlips && grn.packageSlips.length > 0) {
                        grn.packageSlips.forEach(slip => {
                            window.addPackingSlipSection(slip);
                        });
                    }
                } else {
                    console.log("GRN packageSlips for Edit:", grn.packageSlips);
                    if (grn.packageSlips && grn.packageSlips.length > 0) {
                        if (consumableBody) consumableBody.innerHTML = '';
                        grn.packageSlips.forEach((slip, idx) => {
                            console.log(`Adding Consumable Row #${idx}:`, slip);
                            addConsumableRow(slip);
                        });
                    }
                }
            } else if (isCustomerSource || isVendorPlain || isVendorEmbroidery) {
                filterGRNSalesOrders();
                const targetVal = grn.soRefId || grn.linked_po_id || '';
                const soRefEl = document.getElementById('grn-so-ref');
                if (soRefEl) {
                    soRefEl.value = targetVal;
                    if (targetVal && !soRefEl.value) {
                        const poObj = db.pos ? db.pos.find(p => p.id === targetVal || p.number === targetVal) : null;
                        if (poObj) {
                            const opt = Array.from(soRefEl.options).find(o => o.value === poObj.id || o.value === poObj.number);
                            if (opt) soRefEl.value = opt.value;
                        } else {
                            const soObj = db.salesOrders ? db.salesOrders.find(s => s.id === targetVal || s.number === targetVal) : null;
                            if (soObj) {
                                const opt = Array.from(soRefEl.options).find(o => o.value === soObj.id || o.value === soObj.number);
                                if (opt) soRefEl.value = opt.value;
                            }
                        }
                    }
                }
                reinitSearchableSelect(soRefSel);
                
                if (isVendorEmbroidery) {
                    const tbody = document.getElementById('grn-fabric-used-body');
                    if (tbody) {
                        tbody.innerHTML = `<tr><td colspan="7" class="empty-row" style="text-align:center; padding:8px; color:var(--text-muted);">No challans linked.</td></tr>`;
                    }
                    const usedStates = parseFabricUsedState(grn.remarks || '');
                    if (usedStates && usedStates.length > 0) {
                        usedStates.forEach(state => {
                            if (state.issueId) {
                                window.addGrnFabricUsedRow(state);
                            } else {
                                window.addGrnFabricUsedManualRow(state);
                            }
                        });
                    }
                    window.updateGrnFabricIssues();
                }
            }
            
            let finalCustOrder = grn.custOrderNo || '';
            if (isPlainFabricCustomer) {
                if (currentGRNLinks && currentGRNLinks.length > 0) {
                    const linkedSos = (db.salesOrders || []).filter(s => currentGRNLinks.includes(s.id));
                    finalCustOrder = [...new Set(linkedSos.map(s => (s.partyOrderNo || '').trim()).filter(Boolean))].join(', ');
                }
            } else if (!finalCustOrder) {
                if (grn.soRefId) {
                    const linkedSo = (db.salesOrders || []).find(s => s.id === grn.soRefId);
                    if (linkedSo && linkedSo.partyOrderNo) {
                        finalCustOrder = linkedSo.partyOrderNo;
                    }
                }
            }
            document.getElementById('grn-cust-order-no').value = finalCustOrder;
            if (document.getElementById('grn-party-doc-type')) {
                const targetDoc = (grn.partyDocType || 'Challan').toString().toLowerCase().trim();
                const sel = document.getElementById('grn-party-doc-type');
                const matched = Array.from(sel.options).find(opt => opt.value.toLowerCase().trim() === targetDoc);
                if (matched) sel.value = matched.value;
                else sel.value = 'Challan';
            }
            document.getElementById('grn-party-doc-no').value = grn.partyDocNo || '';
            document.getElementById('grn-doc-date').value = grn.docDate || '';
            document.getElementById('grn-gate-pass-no').value = grn.gatePassNo || '';
            document.getElementById('grn-gate-pass-date').value = grn.gatePassDate || '';
            
            const tState = parseGrnTransportState(grn);
            document.getElementById('grn-has-transporter').value = tState.isTransporter || 'No';
            document.getElementById('grn-has-local-freight').value = tState.isLocalFreight || 'No';
            
            const grnTSel = document.getElementById('grn-transporter');
            if (grnTSel) {
                if (grn.transporterId) {
                    let opt = Array.from(grnTSel.options).find(o => o.value === grn.transporterId);
                    if (!opt && (tState.transporterName || grn.transporterName)) {
                        opt = document.createElement('option');
                        opt.value = grn.transporterId;
                        opt.textContent = tState.transporterName || grn.transporterName;
                        grnTSel.appendChild(opt);
                    }
                    grnTSel.value = grn.transporterId;
                } else if (tState.transporterName || grn.transporterName) {
                    let opt = Array.from(grnTSel.options).find(o => o.textContent.trim().toLowerCase() === String(tState.transporterName || grn.transporterName).trim().toLowerCase());
                    if (opt) grnTSel.value = opt.value;
                } else {
                    grnTSel.value = '';
                }
            }
            document.getElementById('grn-transporter-gst').value = tState.gstNo || '';
            document.getElementById('grn-lr').value = grn.lrNo || '';
            document.getElementById('grn-transport-pkg-count').value = tState.pkgCount || '';
            document.getElementById('grn-transport-labour').value = tState.labour || '';
            
            document.getElementById('grn-taxi-name').value = tState.taxiName || '';
            document.getElementById('grn-pkg-no').value = grn.vehicleNo || '';
            
            document.getElementById('grn-status').value = grn.status || 'Received';
            document.getElementById('grn-remarks').value = window.getUserRemarks(grn.id) || cleanRemarks(grn.remarks) || '';
            
            toggleTransportSection();
            
            if (isEmbroidery) {
                const po = db.pos ? db.pos.find(p => p.id === grn.soRefId || p.number === grn.soRefId) : null;
                const poItemName = po ? (po.itemName || po.processName || (po.design && po.design !== '-' ? po.design : '') || (po.designNumber && po.designNumber !== '-' ? po.designNumber : '') || (po.items && po.items[0] && (po.items[0].itemName || po.items[0].processName || po.items[0].process))) : '';
                if (grn.packageSlips && grn.packageSlips.length > 0) {
                    grn.packageSlips.forEach(slip => {
                        const mergedSlip = { ...slip };
                        if (!mergedSlip.itemName) {
                            mergedSlip.itemName = slip.fabricType || poItemName || '';
                        }
                        addEmbroideryRow(mergedSlip);
                    });
                    if (typeof window.updateGrnEmbroideryItemSelects === 'function') {
                        window.updateGrnEmbroideryItemSelects();
                    }
                }
            } else if (!isConsumable) {
                let showPackingSlips = true;
                let showConsumableMatrix = false;
                if (isPlainFabricCustomer) {
                    const linkedSos = (db.salesOrders || []).filter(s => currentGRNLinks.includes(s.id));
                    if (linkedSos.length > 0) {
                        showPackingSlips = linkedSos.some(so => so.materialType === 'without_material' || so.materialType === 'consumable_customer_fabric');
                        showConsumableMatrix = linkedSos.some(so => so.materialType === 'with_material' || so.materialType === 'consumable_customer_fabric');
                    }
                }

                if (isPlainFabricCustomer && showConsumableMatrix && grn.packageSlips) {
                    const consSlips = grn.packageSlips.filter(s => s.packingType === 'BOX');
                    if (consumableBody) consumableBody.innerHTML = '';
                    consSlips.forEach(slip => {
                        addConsumableRow(slip);
                    });
                }

                let slips = [];
                if (grn.packageSlips && grn.packageSlips.length > 0) {
                    let loadedSlips = grn.packageSlips;
                    if (isPlainFabricCustomer) {
                        loadedSlips = loadedSlips.filter(s => s.packingType !== 'BOX');
                    }
                    if (loadedSlips.length > 0) {
                        if ('packages' in loadedSlips[0]) {
                            const nonZeroSlips = loadedSlips.filter(s => (s.qty || 0) > 0 || (s.packages && s.packages.some(p => (p.qty || 0) > 0)));
                            slips = nonZeroSlips.length > 0 ? nonZeroSlips : loadedSlips;
                        } else {
                            slips = [{
                                fabricType: grn.fabricType,
                                color: grn.color,
                                length: grn.length,
                                width: grn.width,
                                packingType: grn.packingType,
                                pkgCount: grn.pkgCount,
                                weight: grn.weight,
                                packages: grn.packageSlips
                            }];
                        }
                    }
                } else if (grn.qty > 0) {
                    const cleanPackingType = grn.packingType || 'Roll';
                    slips = [{
                        fabricType: grn.fabricType || 'Plain Fabric',
                        color: grn.color || '-',
                        length: grn.length || '',
                        width: grn.width || '',
                        packingType: cleanPackingType,
                        pkgCount: grn.pkgCount || 1,
                        weight: grn.weight || 0,
                        packages: Array.from({ length: grn.pkgCount || 1 }, (_, i) => ({
                            label: `${cleanPackingType} ${i + 1}`,
                            packageNo: '',
                            qty: i === 0 ? grn.qty : 0
                        }))
                    }];
                }
                if (slips.length > 0) {
                    slips.forEach(slip => {
                        addPackingSlipSection(slip);
                    });
                } else {
                    showPackingSlipPrompt();
                }
            }
        }
    } else {
        let typePrefix = 'GRN';
        if (grnWizardState.type === 'fabric') {
            if (grnWizardState.source === 'customer') {
                typePrefix = grnWizardState.subType === 'plain' ? 'GRN/C/PF' : 'GRN/C/EM';
            } else {
                typePrefix = grnWizardState.subType === 'plain' ? 'GRN/V/PF' : 'GRN/V/EM';
            }
        } else if (grnWizardState.type === 'consumable') {
            typePrefix = 'GRN/CON';
        } else if (grnWizardState.type === 'other') {
            typePrefix = 'GRN/OTH';
        }

        const activeGrns = (db.grns || []).filter(g => {
            const state = parseGrnWizardState(g);
            if (state.type !== grnWizardState.type) return false;
            if (grnWizardState.type === 'fabric') {
                if (state.source !== grnWizardState.source) return false;
                if (state.subType !== grnWizardState.subType) return false;
            }
            return true;
        });

        let nextNum = 1;
        if (activeGrns.length > 0) {
            const numbers = activeGrns.map(g => getBaseNumberFromGrn(g.grnNo || g.number, typePrefix) || 0);
            nextNum = Math.max(...numbers) + 1;
        }

        let generatedDocNo = customDocNo || getDocumentNumber(typePrefix, nextNum);
        if (generatedDocNo && window.formatStandardDocNumber) generatedDocNo = window.formatStandardDocNumber(generatedDocNo);
        document.getElementById('grn-number').value = generatedDocNo;
        document.getElementById('grn-date').value = today();
        
        currentGRNLinks = [];
        window.currentGRNAllottedQtys = {};
        window.renderGRNFormSOLinks();
        window.populateSOLinkSelectForGRN();
        
        if (isVendorEmbroidery) {
            const tbody = document.getElementById('grn-fabric-used-body');
            if (tbody) {
                tbody.innerHTML = `<tr><td colspan="7" class="empty-row" style="text-align:center; padding:8px; color:var(--text-muted);">No challans linked.</td></tr>`;
            }
            window.updateGrnFabricIssues();
        }
        
        if (soRefSel) {
            soRefSel.value = '';
            reinitSearchableSelect(soRefSel);
        }
        if (custSel) {
            custSel.value = '';
            reinitSearchableSelect(custSel);
        }
        document.getElementById('grn-cust-order-no').value = '';
        document.getElementById('grn-party-doc-type').value = 'Challan';
        document.getElementById('grn-party-doc-no').value = '';
        document.getElementById('grn-doc-date').value = '';
        document.getElementById('grn-gate-pass-no').value = '';
        document.getElementById('grn-gate-pass-date').value = '';
        
        document.getElementById('grn-has-transporter').value = 'No';
        document.getElementById('grn-has-local-freight').value = 'No';
        document.getElementById('grn-transporter').value = '';
        document.getElementById('grn-transporter-gst').value = '';
        document.getElementById('grn-lr').value = '';
        document.getElementById('grn-transport-pkg-count').value = '';
        document.getElementById('grn-transport-labour').value = '';
        document.getElementById('grn-taxi-name').value = '';
        document.getElementById('grn-pkg-no').value = '';
        document.getElementById('grn-remarks').value = '';
        const errDiv = document.getElementById('grn-builty-error');
        if (errDiv) errDiv.style.display = 'none';
        
        toggleTransportSection();
        
        if (isEmbroidery) {
            addEmbroideryRow();
        } else if (isConsumable || grnWizardState.type === 'other') {
            onConsumableTypeChange();
        } else {
            showPackingSlipPrompt();
        }
        

    }
    
    // Final override check to hide/show SO Ref Group vs Multi SO Group to avoid reinitSearchableSelect override bugs
    if (soRefGroup) {
        if (isPlainFabricCustomer) {
            soRefGroup.style.display = 'none';
            if (multiSoGroup) multiSoGroup.style.display = 'block';
        } else {
            if (multiSoGroup) multiSoGroup.style.display = 'none';
            if (isCustomerSource || isVendorPlain || isVendorEmbroidery) {
                soRefGroup.style.display = 'block';
            } else if (isConsumable) {
                soRefGroup.style.display = 'block';
            } else {
                soRefGroup.style.display = 'none';
            }
        }
    }
    
    if (typeof window.updateGrnCustPfLayout === 'function') {
        window.updateGrnCustPfLayout();
    }
    window.updateModalUserLog('grn-modal');
    if (window.attachRamaSyncModalWarning) window.attachRamaSyncModalWarning('grn-modal', editId);
    openModal('grn-modal');
}
window.openGRNModal = openGRNModal;

