/* 
  ========================================================================
  CRITICAL CORE LOGIC - DO NOT MODIFY OR OVERWRITE THIS FUNCTION
  This saves the GRN to Supabase and manages active linkage updates.
  ========================================================================
*/
window.executeSaveGRN = async function(data, editId) {
    try {
        const state = parseGrnWizardState(data);
        const isCustomerSource = (state.type === 'fabric' && state.source === 'customer');
        const isPlain = (state.subType === 'plain');
        await saveToSupabase('grns', data);
        const remarksInputVal = document.getElementById('grn-remarks') ? document.getElementById('grn-remarks').value : '';
        await window.saveUserRemarks(data.id, remarksInputVal);
        window.triggerGoogleSheetsSync('grn', data, editId ? 'edit' : 'create');
        await window.syncGRNLinksWithSOs(data.id, currentGRNLinks, data.grnNo || data.number);
        
        if (editId) {
            const idxRaw = rawDB.grns.findIndex(g => g.id === editId);
            if (idxRaw !== -1) rawDB.grns[idxRaw] = data;
        } else {
            rawDB.grns.unshift(data);
        }
        applyFinancialYearFilters();
        
        renderGRNTable();
        if (typeof window.refreshAllLogisticsTables === 'function') window.refreshAllLogisticsTables();
        
        // Show success prompt modal
        document.getElementById('grn-success-number').textContent = data.grnNo || data.number;
        
        const isVendorSource = (state.type === 'fabric' && state.source === 'vendor');
        const isPurchaseGRN = (state.type === 'consumable') || (state.type === 'other') || isVendorSource;
        
        const btnMakePO = document.getElementById('grn-success-modal').querySelector('#btn-grn-success-make-po');
        const btnMakeInHousePO = document.getElementById('grn-success-modal').querySelector('#btn-grn-success-make-inhouse-po');
        const btnMakeVoucher = document.getElementById('grn-success-modal').querySelector('#btn-grn-success-make-voucher');

        if (btnMakeVoucher) btnMakeVoucher.style.display = 'none';

        if (isCustomerSource && isPlain) {
            btnMakePO.style.display = 'block';
            btnMakeInHousePO.style.display = 'block';
            
            const handlePoSetup = function(type) {
                window.comingFromGrnSuccessData = data;
                closeModal('grn-success-modal');
                closeModal('grn-modal', true);
                // Open PO Modal
                window.currentPoWizardType = type;
                openPOModal();
                
                // Prefill Customer
                const poCustomerSelect = document.getElementById('po-customer');
                if (poCustomerSelect && data.customerId) {
                    poCustomerSelect.value = data.customerId;
                    reinitSearchableSelect(poCustomerSelect);
                    if (typeof window.onPoCustomerChange === 'function') {
                        window.onPoCustomerChange();
                    }
                }

                // Find the linked Sales Order from GRN
                const linkedSoId = (data.soLinks && data.soLinks.length > 0) ? data.soLinks[0] : (data.soRefId || '');
                const linkedSo = linkedSoId ? db.salesOrders.find(s => s.id === linkedSoId) : null;

                if (linkedSo) {
                    // Use the SO's items (real item names) to populate the PO grid
                    // AND properly link the SO to this PO
                    window.selectSOForPO(linkedSo.id, linkedSo.number, linkedSo.designNumber || '');
                } else {
                    // Fallback: no linked SO, populate from GRN package slips using fabric type
                    const tbody = document.getElementById('po-items-grid-body');
                    if (tbody) {
                        tbody.innerHTML = '';
                        if (data.packageSlips && data.packageSlips.length > 0) {
                            data.packageSlips.forEach(slip => {
                                const itemObj = db.items.find(i => i.name.toLowerCase() === (slip.fabricType || '').toLowerCase());
                                const itemId = itemObj ? itemObj.id : (slip.fabricType || '');
                                window.addPORow(itemId, '', slip.qty || 0, '', slip.fabricType);
                            });
                        } else {
                            window.addPORow();
                        }
                    }
                }
            };

            btnMakePO.onclick = function() {
                handlePoSetup('vendor');
            };
            btnMakeInHousePO.onclick = function() {
                handlePoSetup('inhouse');
            };
        } else if (isPurchaseGRN) {
            if (btnMakePO) btnMakePO.style.display = 'none';
            if (btnMakeInHousePO) btnMakeInHousePO.style.display = 'none';
            if (btnMakeVoucher) {
                btnMakeVoucher.style.display = 'flex';
                btnMakeVoucher.onclick = function() {
                    closeModal('grn-success-modal');
                    closeModal('grn-modal', true);
                    window.pendingGrnIdForVoucher = data.id;
                    openGenericTxModal('voucher');
                };
            }
        } else {
            if (btnMakePO) btnMakePO.style.display = 'none';
            if (btnMakeInHousePO) btnMakeInHousePO.style.display = 'none';
            if (btnMakeVoucher) btnMakeVoucher.style.display = 'none';
        }
        document.getElementById('btn-grn-success-print').onclick = function() {
            printGRN(data.id);
        };
        
        const handleClose = function() {
            closeModal('grn-success-modal');
            closeModal('grn-modal', true);
            if (window.shouldPromptFreightDetails && window.shouldPromptFreightDetails(data, 'grn')) {
                window.openFreightPopModal(data.id, 'grn');
            }
        };
        const grnSuccessModal = document.getElementById('grn-success-modal');
        if (grnSuccessModal) {
            const closeBtn = grnSuccessModal.querySelector('.modal-close');
            if (closeBtn) closeBtn.onclick = handleClose;
            const doneBtn = grnSuccessModal.querySelector('.modal-footer .btn');
            if (doneBtn) doneBtn.onclick = handleClose;
        }

        openModal('grn-success-modal');
    } catch(e) {
        console.error("Error in executeSaveGRN:", e);
        showToast("Error: " + (e.message || e), "error");
    }
};

function isKnownFabricType(str) {
    if (!str || typeof str !== 'string') return false;
    const clean = str.trim().toLowerCase();
    if (!clean || clean === '-' || clean === 'fabric' || clean === 'other item' || clean === 'consumable') return false;
    return (db.fabric_types || []).some(f => f.name && f.name.trim().toLowerCase() === clean);
}

function isGRNConsumable(g) {
    if (!g || g.isPlaceholder) return false;
    const state = typeof parseGrnWizardState === 'function' ? parseGrnWizardState(g) : {};
    return state.type === 'consumable' || 
           (g.grnNo && String(g.grnNo).toUpperCase().startsWith('GRN/CON')) || 
           (g.number && String(g.number).toUpperCase().startsWith('GRN/CON')) || 
           g.poType === 'consumable' || 
           g.grn_class === 'consumable';
}

function isGRNItemNameString(str) {
    if (!str || typeof str !== 'string') return false;
    const s = str.trim().toUpperCase();
    if (!s || s === '-' || s === 'FABRIC' || s === 'OTHER ITEM' || s === 'CONSUMABLE' || s === 'PLAIN FABRIC') return false;
    if (s.startsWith('GI-') || s.startsWith('D-') || s.startsWith('DES-') || s.startsWith('ART-') || s.startsWith('SK-')) return true;
    if (s.includes('EMB') || s.includes('JOB WORK') || s.includes('JOBWORK') || s.includes('GPO') || s.includes('PATCH') || s.includes('LACE') || s.includes('BORDER') || s.includes('NECK') || s.includes('GALLA') || s.includes('DAMAN') || s.includes('DUPATTA') || s.includes('SCHIFFLI')) return true;
    const allItems = [...(db.items || []), ...(rawDB.items || [])];
    if (allItems.some(it => it.name && it.name.trim().toUpperCase() === s)) return true;
    return false;
}

window.getGRNItemName = function(g) {
    if (!g || g.isPlaceholder) return '-';

    if (isGRNConsumable(g)) {
        let name = g.itemName;
        if (!name || name.toLowerCase() === 'consumable' || name.toLowerCase() === 'fabric') name = g.yarnName;
        if (!name && Array.isArray(g.packageSlips) && g.packageSlips.length > 0) {
            name = g.packageSlips[0].itemName || g.packageSlips[0].yarnName || g.packageSlips[0].fabricType;
        }
        if (!name && Array.isArray(g.items) && g.items.length > 0) {
            const it = g.items[0];
            const masterItem = it.itemId ? (db.items || []).find(x => String(x.id) === String(it.itemId)) : null;
            name = (masterItem ? masterItem.name : null) || it.itemName || it.item_name || it.yarnName;
        }
        if (!name) name = g.consumable_type;
        if (name && name !== '-' && name.toLowerCase() !== 'consumable') return name;
        return '-';
    }

    let foundNames = [];

    const isInvalidPlaceholder = (n) => {
        if (!n || typeof n !== 'string') return true;
        const cl = n.trim().toLowerCase();
        return !cl || cl === '-' || cl === 'fabric' || cl === 'other item' || cl === 'consumable' || cl === 'plain fabric';
    };

    // 1. Check g.fabricType if it is actually an item/design name
    if (g.fabricType && isGRNItemNameString(g.fabricType)) {
        foundNames.push(g.fabricType.trim());
    }

    // 2. Direct design / processName on GRN
    const des = g.design || g.designNumber || g.designNo || g.processName;
    if (!isInvalidPlaceholder(des)) foundNames.push(des.trim());

    // 3. Items array & packageSlips
    if (Array.isArray(g.items) && g.items.length > 0) {
        for (const it of g.items) {
            if (!it) continue;
            const masterItem = (it.itemId || it.designId) ? (db.items || []).find(x => String(x.id) === String(it.itemId || it.designId)) : null;
            if (masterItem && !isInvalidPlaceholder(masterItem.name)) foundNames.push(masterItem.name);
            const iItem = it.designNumber || it.processName || it.itemName || it.item_name;
            if (!isInvalidPlaceholder(iItem)) foundNames.push(iItem);
        }
    }
    if (Array.isArray(g.packageSlips) && g.packageSlips.length > 0) {
        for (const slip of g.packageSlips) {
            const pItem = slip.itemName || slip.designNumber || slip.designNo;
            if (!isInvalidPlaceholder(pItem) && isGRNItemNameString(pItem)) foundNames.push(pItem);
        }
    }

    // 4. Linked Purchase Orders (g.poRefId, g.poNumber, g.linked_po_id)
    const allPos = [...(db.pos || []), ...(rawDB.pos || [])];
    const poRefList = [g.linked_po_id, g.poRefId, g.linked_po_number, g.poNumber].filter(Boolean);
    if (poRefList.length > 0) {
        poRefList.forEach(refId => {
            const idStr = String(refId);
            const po = allPos.find(p => String(p.id) === idStr || String(p.number) === idStr);
            if (po) {
                let poName = po.design || po.designNumber || po.designNo;
                if (!poName && po.items && po.items.length > 0) {
                    const master = po.items[0].itemId ? (db.items || []).find(x => String(x.id) === String(po.items[0].itemId)) : null;
                    poName = (master ? master.name : null) || po.items[0].processName || po.items[0].itemName;
                }
                if (!isInvalidPlaceholder(poName)) foundNames.push(poName);
            }
        });
    }

    // 5. Linked Sales Orders (g.soLinks, g.soRefId, g.linked_so_id)
    const allSos = [...(db.salesOrders || []), ...(rawDB.salesOrders || [])];
    const meta = typeof parseMetadataFromRemarks === 'function' ? parseMetadataFromRemarks(g.remarks, '__SO_LINKS__') : { links: null };
    const soRefList = [...(meta.links || []), g.soRefId, g.linked_so_id, g.so_id, ...(g.soLinks || [])].filter(Boolean);
    if (soRefList.length > 0) {
        soRefList.forEach(refId => {
            const idStr = typeof refId === 'object' ? (refId.soId || refId.id) : refId;
            const so = allSos.find(s => String(s.id) === String(idStr) || String(s.number) === String(idStr));
            if (so) {
                let names = [];
                if (so.designNumber && !isInvalidPlaceholder(so.designNumber)) names.push(so.designNumber);
                if (so.design && !isInvalidPlaceholder(so.design)) names.push(so.design);
                let itemsArr = so.items;
                if (typeof itemsArr === 'string') {
                    try { itemsArr = JSON.parse(itemsArr); } catch(e) {}
                }
                if (!Array.isArray(itemsArr) && so.remarks && typeof so.remarks === 'string' && so.remarks.includes('__ITEMS__:')) {
                    try {
                        const m = so.remarks.match(/__ITEMS__:(.*)/);
                        if (m) itemsArr = JSON.parse(m[1].trim());
                    } catch(e){}
                }
                if (Array.isArray(itemsArr) && itemsArr.length > 0) {
                    itemsArr.forEach(it => {
                        if (!it) return;
                        const itemId = it.itemId || it.item_id;
                        const master = itemId ? (db.items || []).find(x => String(x.id) === String(itemId)) : null;
                        const n = (master ? master.name : null) || it.itemName || it.item_name || it.processName || it.designNumber;
                        if (!isInvalidPlaceholder(n)) names.push(n);
                    });
                }
                if (names.length === 0 && so.item_id) {
                    const master = (db.items || []).find(x => String(x.id) === String(so.item_id));
                    if (master && !isInvalidPlaceholder(master.name)) names.push(master.name);
                }
                if (names.length > 0) foundNames.push(...names);
            }
        });
    }

    // 6. Direct g.itemName
    if (!isInvalidPlaceholder(g.itemName)) foundNames.push(g.itemName);

    const unique = [...new Set(foundNames)].filter(Boolean);
    return unique.length > 0 ? unique.join(', ') : '-';
};

window.getGRNFabricName = function(g) {
    if (!g || g.isPlaceholder) return '-';
    if (isGRNConsumable(g)) return '-';

    let foundFabs = [];

    const isInvalidPlaceholder = (n) => {
        if (!n || typeof n !== 'string') return true;
        const cl = n.trim().toLowerCase();
        return !cl || cl === '-' || cl === 'fabric' || cl === 'other item' || cl === 'consumable' || cl === 'plain fabric';
    };

    const resolveFabFromUsedItem = (item) => {
        if (!item) return '';
        let fab = item.fabricType || item.fabric_type || item.fabricName || '';
        if (fab && !isGRNItemNameString(fab) && !isInvalidPlaceholder(fab)) return fab.trim();
        
        const refId = item.issueId || item.issueNo || item.grnId || item.grnNo;
        if (refId) {
            const out = (db.outwards || []).find(o => String(o.id) === String(refId) || String(o.number) === String(refId) || String(o.partyDocNo) === String(refId));
            if (out) {
                const f = out.fabricType && !isGRNItemNameString(out.fabricType) && !isInvalidPlaceholder(out.fabricType) ? out.fabricType : '';
                if (f) return f.trim();
                if (Array.isArray(out.packageSlips)) {
                    for (const ps of out.packageSlips) {
                        if (ps && ps.fabricType && !isGRNItemNameString(ps.fabricType) && !isInvalidPlaceholder(ps.fabricType)) return ps.fabricType.trim();
                    }
                }
            }
            const grn = (db.grns || []).find(gr => String(gr.id) === String(refId) || String(gr.number) === String(refId) || String(gr.partyDocNo) === String(refId));
            if (grn) {
                const f = grn.fabricType && !isGRNItemNameString(grn.fabricType) && !isInvalidPlaceholder(grn.fabricType) ? grn.fabricType : '';
                if (f) return f.trim();
                if (Array.isArray(grn.packageSlips)) {
                    for (const ps of grn.packageSlips) {
                        if (ps && ps.fabricType && !isGRNItemNameString(ps.fabricType) && !isInvalidPlaceholder(ps.fabricType)) return ps.fabricType.trim();
                    }
                }
            }
        }
        return '';
    };

    // 1. Check FABRIC_USED in remarks
    if (g.remarks && typeof g.remarks === 'string' && g.remarks.includes('[FABRIC_USED:')) {
        try {
            const match = g.remarks.match(/\[FABRIC_USED:(\[.*?\])\]/) || g.remarks.match(/\[FABRIC_USED:(\{.*?\})\]/);
            if (match) {
                const list = JSON.parse(match[1]);
                const arr = Array.isArray(list) ? list : [list];
                arr.forEach(item => {
                    const f = resolveFabFromUsedItem(item);
                    if (f) foundFabs.push(f);
                });
            }
        } catch(e){}
    }

    // 2. Check g.fabricType ONLY IF it is NOT an item name
    if (g.fabricType && !isGRNItemNameString(g.fabricType) && !isInvalidPlaceholder(g.fabricType)) {
        foundFabs.push(g.fabricType.trim());
    }

    // 3. Check packageSlips / items for raw fabricType
    if (Array.isArray(g.packageSlips)) {
        g.packageSlips.forEach(s => {
            if (s && s.fabricType && !isGRNItemNameString(s.fabricType) && !isInvalidPlaceholder(s.fabricType)) {
                foundFabs.push(s.fabricType.trim());
            }
        });
    }
    if (Array.isArray(g.items)) {
        g.items.forEach(i => {
            if (i && i.fabricType && !isGRNItemNameString(i.fabricType) && !isInvalidPlaceholder(i.fabricType)) {
                foundFabs.push(i.fabricType.trim());
            }
        });
    }

    // 4. Linked SO or PO fabricType
    const allSos = [...(db.salesOrders || []), ...(rawDB.salesOrders || [])];
    const so = allSos.find(s => s.id === g.soRefId || s.number === g.soNumber || s.id === g.linked_so_id);
    if (so && so.fabricType && !isGRNItemNameString(so.fabricType) && !isInvalidPlaceholder(so.fabricType)) {
        foundFabs.push(so.fabricType.trim());
    }

    const allPos = [...(db.pos || []), ...(rawDB.pos || [])];
    const po = allPos.find(p => p.id === g.poRefId || p.number === g.poNumber || p.id === g.linked_po_id);
    if (po && po.fabricType && !isGRNItemNameString(po.fabricType) && !isInvalidPlaceholder(po.fabricType)) {
        foundFabs.push(po.fabricType.trim());
    }

    const unique = [...new Set(foundFabs)].filter(Boolean);
    return unique.length > 0 ? unique.join(', ') : '-';
};

function renderGRNTable() {
    const thead = document.getElementById('tx-grn-table-head');
    const tbody = document.getElementById('tx-grn-table-body');
    if (!tbody) return;
    db.grns = db.grns || [];
    
    const isPlainFabricCustomer = (grnWizardState.type === 'fabric' && grnWizardState.source === 'customer' && grnWizardState.subType === 'plain');
    
    window.renderDynamicHeader('grn', 'tx-grn-table-head');
    const config = window.getTableColumnConfig('grn');
    
    const activeGrns = db.grns.filter(g => {
        const state = parseGrnWizardState(g);
        if (state.type !== grnWizardState.type) return false;
        if (grnWizardState.type === 'fabric') {
            if (state.source !== grnWizardState.source) return false;
            if (state.subType !== grnWizardState.subType) return false;
        }
        return true;
    });

    let typePrefix = 'GRN';
    if (grnWizardState.type === 'fabric') {
        if (grnWizardState.source === 'customer') {
            typePrefix = grnWizardState.subType === 'plain' ? 'GRN/C/PF' : 'GRN/C/EM';
        } else {
            typePrefix = grnWizardState.subType === 'plain' ? 'GRN/V/PF' : 'GRN/V/EM';
        }
    } else if (grnWizardState.type === 'consumable') {
        typePrefix = 'GRN/CON';
    } else if (grnWizardState.type === 'other') {
        typePrefix = 'GRN/OTH';
    }

    function getBaseNumber(numberStr) {
        return getBaseNumberFromGrn(numberStr, typePrefix);
    }

    const baseNumbersMap = new Map();
    activeGrns.forEach(g => {
        const base = getBaseNumber(g.grnNo || g.number);
        if (base !== null) {
            if (!baseNumbersMap.has(base)) {
                baseNumbersMap.set(base, []);
            }
            baseNumbersMap.get(base).push(g);
        }
    });

    let maxBase = 0;
    for (let base of baseNumbersMap.keys()) {
        if (base > maxBase) maxBase = base;
    }

    const fySuffix = (financialYears[currentFinancialYear] || {}).suffix || '/26-27';
    const cleanSuffix = fySuffix.startsWith('/') ? fySuffix.substring(1) : fySuffix;

    const itemsToRender = [];
    for (let i = 1; i <= maxBase; i++) {
        if (baseNumbersMap.has(i)) {
            itemsToRender.push(...baseNumbersMap.get(i));
        } else {
            itemsToRender.push({
                id: `placeholder_grn_${i}`,
                grnNo: getDocumentNumber(typePrefix, i),
                number: getDocumentNumber(typePrefix, i),
                isPlaceholder: true,
                date: '',
                customerName: 'Cancelled',
                fabricType: '-',
                custOrderNo: '-',
                soRefId: '',
                soNumber: '-',
                partyDocType: '-',
                partyDocNo: '-',
                docDate: '',
                packingType: '-',
                pkgCount: 0,
                qty: 0,
                weight: 0,
                transporterName: '-',
                status: 'Cancelled',
                remarks: 'Missing GRN in series'
            });
        }
    }
    
    const searchInput = document.getElementById('tx-grn-search');
    const query = searchInput ? searchInput.value.toLowerCase().trim() : '';
    const dateFromInput = document.getElementById('tx-grn-date-from');
    const dateToInput = document.getElementById('tx-grn-date-to');
    const dateFrom = dateFromInput ? dateFromInput.value : '';
    const dateTo = dateToInput ? dateToInput.value : '';

    const filteredGrns = itemsToRender.filter(g => {
        if (g.isPlaceholder) {
            if (query || dateFrom || dateTo) return false;
        }
        if (dateFrom && g.date && g.date < dateFrom) return false;
        if (dateTo && g.date && g.date > dateTo) return false;

        if (query) {
            const grnNo = (g.grnNo || g.number || '').toLowerCase();
            const customerName = (g.customerName || '').toLowerCase();
            const partyName = (window.getGRNPartyName ? window.getGRNPartyName(g) : (g.partyName || g.vendorName || '')).toLowerCase();
            const partyOrderNo = (g.partyDocNo || g.partyOrderNo || g.poNumber || g.soNumber || '').toLowerCase();
            const designNo = (g.designNumber || g.designNo || g.design || '').toLowerCase();
            const fabricType = (g.fabricType || '').toLowerCase();
            const remarks = (g.remarks || '').toLowerCase();
            const status = (g.status || '').toLowerCase();

            if (grnNo.includes(query) || customerName.includes(query) || partyName.includes(query) ||
                partyOrderNo.includes(query) || designNo.includes(query) || fabricType.includes(query) ||
                remarks.includes(query) || status.includes(query)) {
                return true;
            }

            if (g.items && Array.isArray(g.items)) {
                for (const it of g.items) {
                    if (!it) continue;
                    const itName = (it.itemName || it.item_name || it.processName || '').toLowerCase();
                    const itDesign = (it.designNumber || it.designNo || it.designName || '').toLowerCase();
                    if (itName.includes(query) || itDesign.includes(query)) return true;
                }
            }
            return false;
        }
        return true;
    });

    // Apply sorting dynamically
    const sortConf = window.tableSortConfig?.grn || { field: 'number', order: 'desc' };
    const sortField = sortConf.field;
    const sortOrder = sortConf.order === 'asc' ? 1 : -1;
    filteredGrns.sort((a, b) => {
        let valA = '';
        let valB = '';

        if (sortField === 'number') {
            const numA = getBaseNumber(a.grnNo || a.number) || 0;
            const numB = getBaseNumber(b.grnNo || b.number) || 0;
            return (numA - numB) * sortOrder;
        } else if (sortField === 'date') {
            valA = a.date ? new Date(a.date).getTime() : 0;
            valB = b.date ? new Date(b.date).getTime() : 0;
        } else if (sortField === 'customerName') {
            valA = a.customerName || '';
            valB = b.customerName || '';
        } else if (sortField === 'itemName') {
            valA = window.getGRNItemName(a);
            valB = window.getGRNItemName(b);
        } else if (sortField === 'fabricType') {
            valA = window.getGRNFabricName(a);
            valB = window.getGRNFabricName(b);
        } else if (sortField === 'custOrderNo') {
            valA = a.custOrderNo || '';
            valB = b.custOrderNo || '';
        } else if (sortField === 'soNumber') {
            valA = a.soNumber || '';
            valB = b.soNumber || '';
        } else if (sortField === 'partyDocNo') {
            valA = a.partyDocNo || '';
            valB = b.partyDocNo || '';
        } else if (sortField === 'docDate') {
            valA = a.docDate ? new Date(a.docDate).getTime() : 0;
            valB = b.docDate ? new Date(b.docDate).getTime() : 0;
        } else if (sortField === 'packingType') {
            valA = a.packingType || '';
            valB = b.packingType || '';
        } else if (sortField === 'pkgCount') {
            valA = Number(a.pkgCount || 0);
            valB = Number(b.pkgCount || 0);
        } else if (sortField === 'qty') {
            valA = Number(a.qty || 0);
            valB = Number(b.qty || 0);
        } else if (sortField === 'status') {
            valA = a.status || '';
            valB = b.status || '';
        }

        if (typeof valA === 'number' && typeof valB === 'number') {
            return (valA - valB) * sortOrder;
        }
        return String(valA).localeCompare(String(valB)) * sortOrder;
    });
    
    const visibleCols = config.filter(c => c.visible !== false).length;
    if (filteredGrns.length === 0) {
        tbody.innerHTML = `<tr><td colspan="${visibleCols + 2}" class="empty-row">No matching inward GRNs.</td></tr>`;
        return;
    }
    
    tbody.innerHTML = filteredGrns.map(g => {
        const isPlaceholder = g.isPlaceholder;
        const status = g.status || 'Pending';
        const statusBadge = `<span class="badge ${status === 'Received' || status === 'Completed' ? 'badge-green' : status === 'Cancelled' ? 'badge-red' : 'badge-orange'}">${status}</span>`;
        const isCancelledOrPlaceholder = isPlaceholder || status.trim().toLowerCase() === 'cancelled';
        
        const cancelledHtml = '<span style="color: #ef4444; font-weight: bold; text-transform: uppercase;">CANCELLED</span>';
        const permModule = window.getGrnPermissionModule(g);

        let soNumbers = isCancelledOrPlaceholder ? cancelledHtml : 'Direct';
        if (!isCancelledOrPlaceholder) {
            let parts = [];
            
            const isPlainId = (val) => {
                if (!val) return false;
                const str = String(val).trim();
                return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(str) || 
                       str.startsWith('imported_') || 
                       /^[a-z0-9]{8,25}$/i.test(str);
            };

            const resolvePoNum = (val) => {
                if (!val) return null;
                const str = String(val).trim();
                const found = (rawDB.pos || []).find(p => p.id === str || p.number === str) || 
                              (db.pos || []).find(p => p.id === str || p.number === str);
                if (found && found.number) return found.number;
                if (!isPlainId(str) && (str.includes('/') || str.includes('-') || str.length < 30)) {
                    return str;
                }
                return null;
            };

            const resolveSoNum = (val) => {
                if (!val) return null;
                const str = String(val).trim();
                const found = (rawDB.salesOrders || []).find(s => s.id === str || s.number === str) || 
                              (db.salesOrders || []).find(s => s.id === str || s.number === str);
                if (found && found.number) return found.number;
                if (!isPlainId(str) && (str.includes('/') || str.includes('-') || str.length < 30)) {
                    return str;
                }
                return null;
            };

            // 1. Resolve PO Number
            const poNumVal = g.linked_po_number || g.poNumber || '';
            const poIdVal = g.linked_po_id || g.poRefId || '';
            const resolvedPo = resolvePoNum(poNumVal) || resolvePoNum(poIdVal);
            if (resolvedPo) {
                parts.push(resolvedPo);
            }
            
            // 2. Resolve SO Number
            const soNumVal = g.linked_so_number || g.soNumber || '';
            const soIdVal = g.linked_so_id || g.soRefId || '';
            const resolvedSo = resolveSoNum(soNumVal) || resolveSoNum(soIdVal);
            if (resolvedSo) {
                parts.push(resolvedSo);
            }
            
            // 3. Resolve SO Links Array
            if (g.soLinks && g.soLinks.length > 0) {
                const linked = g.soLinks.map(link => {
                    const id = typeof link === 'object' ? (link.soId || link.id) : link;
                    const found = (rawDB.salesOrders || []).find(s => s.id === id || s.number === id) || 
                                  (db.salesOrders || []).find(s => s.id === id || s.number === id);
                    if (found) return found.number;
                    const str = String(id);
                    if (str && str.length < 30 && (str.includes('/') || str.includes('-'))) {
                        return str;
                    }
                    return null;
                }).filter(Boolean);
                if (linked.length > 0) {
                    parts.push(...linked);
                }
            }
            
            // Deduplicate and join
            const uniqueParts = [...new Set(parts)].filter(Boolean);
            if (uniqueParts.length > 0) {
                soNumbers = uniqueParts.map(num => {
                    const isPo = String(num).toUpperCase().startsWith('PO');
                    if (isPo) {
                        return `<a href="#" onclick="event.preventDefault(); window.openPoByNumber('${num}')" style="color: var(--accent-blue, #3b82f6); text-decoration: underline; font-weight: bold;">${num}</a>`;
                    } else {
                        return `<a href="#" onclick="event.preventDefault(); window.openSoByNumber('${num}')" style="color: var(--accent-blue, #3b82f6); text-decoration: underline; font-weight: bold;">${num}</a>`;
                    }
                }).join(', ');
            } else if (poIdVal || soIdVal || (g.soLinks && g.soLinks.length > 0)) {
                soNumbers = 'Linked';
            }
        }
        
        const grnNumVal = window.formatStandardDocNumber(g.grnNo || g.number);
        const numberDisplay = isPlaceholder 
            ? (checkPermission(permModule, 'edit_cancelled') ? `<strong><a href="#" onclick="openGRNModal(null, '${grnNumVal}')" style="${isCancelledOrPlaceholder ? 'color: var(--accent-red, #ef4444) !important;' : 'color: var(--accent-blue);'} text-decoration: none;">${grnNumVal}</a></strong>` : `<span style="${isCancelledOrPlaceholder ? 'color: var(--accent-red, #ef4444) !important;' : ''}">${grnNumVal}</span>`)
            : `<strong><a href="#" onclick="openGRNModal('${g.id}')" style="${isCancelledOrPlaceholder ? 'color: var(--accent-red, #ef4444) !important;' : 'color: var(--accent-blue);'} text-decoration: none;">${grnNumVal || '-'}</a></strong>`;
        const dateDisplay = isCancelledOrPlaceholder ? cancelledHtml : formatDate(g.date);
        const customerDisplay = isCancelledOrPlaceholder ? cancelledHtml : window.getGRNPartyName(g);
        const custOrderDisplay = isCancelledOrPlaceholder ? cancelledHtml : (g.custOrderNo || '-');
        const partyDocNoDisplay = isCancelledOrPlaceholder ? cancelledHtml : (g.partyDocNo || '-');
        const docDateDisplay = isCancelledOrPlaceholder ? cancelledHtml : (g.docDate ? formatDate(g.docDate) : '-');
        const packingTypeDisplay = isCancelledOrPlaceholder ? cancelledHtml : (g.packingType || '-');
        const pkgCountDisplay = isCancelledOrPlaceholder ? cancelledHtml : (g.pkgCount || 0);
        const remarkDisplay = isCancelledOrPlaceholder ? cancelledHtml : (cleanRemarks(g.remarks) || '-');
        
        let qtyDisplay = isCancelledOrPlaceholder ? cancelledHtml : `<strong>${(parseFloat(g.qty) || 0).toFixed(2)} m</strong>`;
        let thanDisplay = isCancelledOrPlaceholder ? cancelledHtml : (g.than || '-');
        let conversionDisplay = isCancelledOrPlaceholder ? cancelledHtml : '-';
        
        if (!isCancelledOrPlaceholder) {
            if (g.packageSlips && g.packageSlips.length > 0) {
                const convs = g.packageSlips.map(s => s.conversion).filter(c => c !== undefined && c !== null && c !== '' && !isNaN(c));
                if (convs.length > 0) {
                    conversionDisplay = [...new Set(convs)].map(c => Number(c).toFixed(2)).join(', ');
                }
            }
            if (conversionDisplay === '-' && g.remarks) {
                try {
                    const match = g.remarks.match(/\[FABRIC_USED:(\[.*?\])\]/) || g.remarks.match(/\[FABRIC_USED:(\{.*?\})\]/);
                    if (match) {
                        const list = JSON.parse(match[1]);
                        const convs = list.map(r => r.conversion).filter(c => c !== undefined && c !== null && c !== '' && !isNaN(c));
                        if (convs.length > 0) {
                            conversionDisplay = [...new Set(convs)].map(c => Number(c).toFixed(2)).join(', ');
                        }
                    }
                } catch(e){}
                if (conversionDisplay === '-') {
                    try {
                        const matchItems = g.remarks.match(/__ITEMS__:(.*)/);
                        if (matchItems) {
                            const items = JSON.parse(matchItems[1]);
                            const convs = items.map(i => i.conversion).filter(c => c !== undefined && c !== null && c !== '' && !isNaN(c));
                            if (convs.length > 0) {
                                conversionDisplay = [...new Set(convs)].map(c => Number(c).toFixed(2)).join(', ');
                            }
                        }
                    } catch(e){}
                }
            }
        }
        
        const checkboxDisplay = isPlaceholder ? '' : `<input type="checkbox" class="chk-select-grn" value="${g.id}" onchange="toggleBulkDeleteButton('grn')">`;
        
        const hasEditPerm = isCancelledOrPlaceholder ? checkPermission(permModule, 'edit_cancelled') : checkPermission(permModule, 'write');
        const hasDeletePerm = !isPlaceholder && checkPermission(permModule, 'delete');
        
        let actionsDisplay = '-';
        if (hasEditPerm || hasDeletePerm) {
            actionsDisplay = `
                <div class="table-actions">
                    ${hasEditPerm ? `<button class="btn btn-sm btn-secondary" onclick="openGRNModal(${isPlaceholder ? 'null' : `'${g.id}'`}${isPlaceholder ? `, '${g.grnNo || g.number}'` : ''})"></button>` : ''}
                    ${hasDeletePerm ? `<button class="btn btn-sm btn-danger" onclick="deleteGRN('${g.id}')">=�</button>` : ''}
                </div>
            `;
        }

        const tds = config.map(col => {
            if (col.visible === false) return '';
            if (col.key === 'number') return `<td>${numberDisplay}</td>`;
            if (col.key === 'date') return `<td>${dateDisplay}</td>`;
            if (col.key === 'customerName') return `<td>${customerDisplay}</td>`;
            if (col.key === 'itemName') return `<td class="cell-item-name wrap-text">${isCancelledOrPlaceholder ? cancelledHtml : window.getGRNItemName(g)}</td>`;
            if (col.key === 'fabricType') return `<td class="cell-fabric-name wrap-text">${isCancelledOrPlaceholder ? cancelledHtml : window.getGRNFabricName(g)}</td>`;
            if (col.key === 'custOrderNo') return `<td>${custOrderDisplay}</td>`;
            if (col.key === 'soNumber') return `<td>${soNumbers}</td>`;
            if (col.key === 'conversion') return `<td>${conversionDisplay}</td>`;
            if (col.key === 'partyDocNo') return `<td>${partyDocNoDisplay}</td>`;
            if (col.key === 'docDate') return `<td>${docDateDisplay}</td>`;
            if (col.key === 'packingType') return `<td>${packingTypeDisplay}</td>`;
            if (col.key === 'pkgCount') return `<td>${pkgCountDisplay}</td>`;
            if (col.key === 'qty') return `<td>${qtyDisplay}</td>`;
            if (col.key === 'status') return `<td>${statusBadge}</td>`;
            return '';
        }).filter(Boolean).join('');

        return `
        <tr class="${isCancelledOrPlaceholder ? 'row-cancelled' : ''}" style="${isPlaceholder ? 'font-style: italic;' : ''}">
            <td>${checkboxDisplay}</td>
            ${tds}
            <td>${actionsDisplay}</td>
        </tr>
        `;
    }).join('');
    if (typeof renderPendingTransactionsWidget === 'function') {
        renderPendingTransactionsWidget();
    }
}

async function deleteGRN(id) {
    const grn = (rawDB.grns || []).find(g => g.id === id);
    const docNo = grn ? (grn.grnNo || grn.number) : '';
    if (!(await window.showSmartConfirm('Delete GRN', 'Are you sure you want to delete this Goods Receipt Note (GRN)?'))) return;
    try {
        await deleteFromSupabase('grns', id);
        rawDB.grns = rawDB.grns.filter(g => g.id !== id);
        applyFinancialYearFilters();
        renderGRNTable();
        if (typeof window.refreshAllLogisticsTables === 'function') window.refreshAllLogisticsTables();
        logUserAction('GRN', 'Deleted', `Deleted GRN: ${docNo}`);
        showToast('GRN Deleted', 'info');
    } catch(e) {
        showToast(`Delete failed: ${e.message || e}`, 'error');
    }
}

window.openOutwardModal = async function(editId = null, customDocNo = null, isViewOnly = false) {
    if (!editId) {
        if (!checkPermission('outward', 'write')) {
            showToast('Permission Denied: Restricted Entry', 'error');
            return;
        }
    }
    populateSOAndPODropdowns();
    
    document.querySelectorAll("#outward-modal input, #outward-modal select, #outward-modal textarea").forEach(el => {
        el.disabled = false;
    });
    
    const vSel = document.getElementById('outward-vendor');
    vSel.innerHTML = outwardWizardState.type === 'jobworker' ? '<option value="">-- Select Job Worker --</option>' : '<option value="">-- Select Vendor --</option>';
    let filteredVendorsList = db.vendors.filter(v => v.id !== 'inhouse' && v.status !== 'Cancelled');
    if (outwardWizardState.type === 'jobworker') {
        filteredVendorsList = filteredVendorsList.filter(v => String(v.group || '').trim().toUpperCase() === 'VENDOR - FINISHING JOB WORKER');
    }
    filteredVendorsList.forEach(v => {
        const opt = document.createElement('option');
        opt.value = v.id;
        opt.textContent = v.name;
        vSel.appendChild(opt);
    });

    const cSel = document.getElementById('outward-customer');
    cSel.innerHTML = '<option value="">-- Select Customer --</option>';
    db.customers.filter(c => c.status !== 'Cancelled').forEach(c => {
        const opt = document.createElement('option');
        opt.value = c.id;
        opt.textContent = c.name;
        cSel.appendChild(opt);
    });

    document.getElementById('outward-cust-challan').innerHTML = '<option value="">-- Select Challan No --</option>';
    document.getElementById('outward-grn-details-card').style.display = 'none';
    
    const outEmbBody = document.getElementById('outward-embroidery-body');
    if (outEmbBody) outEmbBody.innerHTML = '';
    const outFabricUsedBody = document.getElementById('outward-fabric-used-body');
    if (outFabricUsedBody) {
        outFabricUsedBody.innerHTML = '<tr><td colspan="7" class="empty-row" style="text-align:center; padding:8px; color:var(--text-muted);">No challans linked.</td></tr>';
    }

    document.getElementById('outward-edit-id').value = editId || '';
    const outwardPrintBtn = document.getElementById('outward-print-btn');
    if (outwardPrintBtn) outwardPrintBtn.style.display = editId ? 'inline-block' : 'none';

    const sourceTypeRow = document.getElementById('outward-source-type-row');
    if (sourceTypeRow) {
        if (outwardWizardState.type === 'inhouse') {
            sourceTypeRow.style.display = 'flex';
        } else {
            sourceTypeRow.style.display = 'none';
        }
    }
    
    const sourceTypeEl = document.getElementById('outward-material-source-type');
    if (sourceTypeEl) sourceTypeEl.value = 'customer';
    const consItemEl = document.getElementById('outward-consumable-item');
    if (consItemEl) consItemEl.value = '';
    const consQtyEl = document.getElementById('outward-consumable-qty');
    if (consQtyEl) consQtyEl.value = '';
    
    let editConsumableItemId = null;
    if (editId) {
        const out = db.outwards.find(o => o.id === editId);
        if (out && (out.materialSourceType === 'consumable' || out.materialSourceType === 'both')) {
            editConsumableItemId = out.consumableItemId;
        }
    }
    if (typeof window.populateConsumableItems === 'function') {
        window.populateConsumableItems(editConsumableItemId);
    }
    if (typeof window.onOutwardSourceTypeChange === 'function') {
        window.onOutwardSourceTypeChange();
    }
    
    if (editId) {
        const out = db.outwards.find(o => o.id === editId);
        if (out) {
            if ((out.status || '').trim().toLowerCase() === 'cancelled') {
                if (await window.showSmartConfirm('Activate Voucher', 'This voucher is cancelled. Do you want to activate this voucher?')) {
                    out.status = 'Issued';
                    await saveToSupabase('outwards', out);
                    window.reactivatedVouchers = window.reactivatedVouchers || {};
                    window.reactivatedVouchers['outward-modal'] = { table: 'outwards', localArray: 'outwards', id: out.id };
                    showToast('Voucher activated successfully!', 'success');
                    if (typeof renderOutwardTable === 'function') renderOutwardTable();
                } else {
                    return;
                }
            }
            const state = parseOutwardWizardState(out);
            outwardWizardState.type = state.type;
            outwardWizardState.source = state.source;
            outwardWizardState.subType = state.subType;

            const savedSourceType = out.materialSourceType || 'customer';
            if (sourceTypeEl) sourceTypeEl.value = savedSourceType;
            if (typeof window.onOutwardSourceTypeChange === 'function') {
                window.onOutwardSourceTypeChange();
            }
            if (consItemEl) {
                consItemEl.value = out.consumableItemId || '';
                if (typeof reinitSearchableSelect === 'function') {
                    reinitSearchableSelect(consItemEl);
                }
            }
            if (consQtyEl) consQtyEl.value = out.consumableQty || '';

            document.getElementById('outward-number').value = out.number;
            document.getElementById('outward-date').value = out.date;
            
            // Ensure cancelled vendor exists in dropdown if currently selected
            const outwardVendorSelect = document.getElementById('outward-vendor');
            if (outwardVendorSelect && out.vendorId) {
                const optExists = Array.from(outwardVendorSelect.options).some(o => o.value === out.vendorId);
                if (!optExists) {
                    const v = db.vendors.find(x => x.id === out.vendorId);
                    if (v) {
                        const opt = document.createElement('option');
                        opt.value = v.id;
                        opt.textContent = v.name + ' (Cancelled)';
                        outwardVendorSelect.appendChild(opt);
                    }
                }
            }
            document.getElementById('outward-vendor').value = out.vendorId;
            reinitSearchableSelect(outwardVendorSelect);
            
            filterOutwardPOs();
            let editPoId = out.poRefId || '';
            if (editPoId) {
                const matchedPO = (db.pos || []).find(p => p.id === editPoId || p.number === editPoId);
                if (matchedPO) editPoId = matchedPO.id;
            }
            document.getElementById('outward-po-ref').value = editPoId;
            window.onOutwardPOSelectChange();
            
            // Populate links
            if (out.grnLinks && out.grnLinks.length > 0) {
                currentOutwardLinks = JSON.parse(JSON.stringify(out.grnLinks));
            } else if (out.grnRefId) {
                currentOutwardLinks = [{ grnRefId: out.grnRefId, qty: out.qty }];
            } else {
                currentOutwardLinks = [];
            }
            
            if (out.dispatchedPackages && out.dispatchedPackages.length > 0) {
                currentOutwardPackages = JSON.parse(JSON.stringify(out.dispatchedPackages));
                // Restore grnConvertedLog from saved convertedLog
                if (out.convertedLog && Object.keys(out.convertedLog).length > 0) {
                    window.grnConvertedLog = JSON.parse(JSON.stringify(out.convertedLog));
                } else {
                    // Legacy: rebuild from dispatchedPackages with convertedDone flag
                    window.grnConvertedLog = {};
                    const convertedPkgs = currentOutwardPackages.filter(p => p.convertedDone);
                    convertedPkgs.forEach(p => {
                        if (!window.grnConvertedLog[p.grnId]) window.grnConvertedLog[p.grnId] = [];
                        const grn = db.grns.find(g => g.id === p.grnId);
                        const slips = (grn && grn.packageSlips && grn.packageSlips.length > 0) ? grn.packageSlips : [];
                        const slip = slips[p.slipIndex];
                        const pkg = slip && slip.packages ? slip.packages[p.packageIndex] : null;
                        // Group by convertedPackingType as a single batch per type
                        let batch = window.grnConvertedLog[p.grnId].find(b => b.targetType === p.convertedPackingType);
                        if (!batch) {
                            batch = { targetType: p.convertedPackingType, items: [], name: `Converted to ${p.convertedPackingType}` };
                            window.grnConvertedLog[p.grnId].push(batch);
                        }
                        batch.items.push({
                            sIdx: p.slipIndex, pIdx: p.packageIndex,
                            label: pkg ? pkg.label : `Pkg ${p.packageIndex + 1}`,
                            packageNo: pkg ? (pkg.packageNo || '') : '',
                            qty: p.qty,
                            slipType: slip ? (slip.fabricType || '') : '',
                            slipColor: slip ? (slip.color || '') : ''
                        });
                    });
                }
            } else if (currentOutwardLinks.length > 0) {
                // Legacy support fallback
                currentOutwardPackages = [];
                window.grnConvertedLog = {};
                currentOutwardLinks.forEach(link => {
                    const grn = db.grns.find(g => g.id === link.grnRefId);
                    if (grn) {
                        let slips = grn.packageSlips && grn.packageSlips.length > 0 ? grn.packageSlips : [{
                            packages: [{ label: `${grn.packingType || 'Roll'} 1`, qty: grn.qty }]
                        }];
                        slips.forEach((slip, sIdx) => {
                            if (slip.packages) {
                                slip.packages.forEach((pkg, pIdx) => {
                                    currentOutwardPackages.push({
                                        grnId: link.grnRefId,
                                        slipIndex: sIdx,
                                        packageIndex: pIdx,
                                        qty: pkg.qty
                                    });
                                });
                            }
                        });
                    }
                });
            } else {
                currentOutwardPackages = [];
                window.grnConvertedLog = {};
            }
            
            let editCustomerId = out.customerId || state.customerId || '';
            if (!editCustomerId && out.linked_so_id) {
                const associatedSO = (db.salesOrders || []).find(s => s.id === out.linked_so_id);
                if (associatedSO) {
                    editCustomerId = associatedSO.customer_id || associatedSO.customerId || '';
                }
            }
            if (!editCustomerId) {
                const firstGrnId = currentOutwardLinks[0]?.grnRefId;
                const associatedGrn = firstGrnId ? db.grns.find(g => g.id === firstGrnId) : null;
                if (associatedGrn) {
                    editCustomerId = associatedGrn.customerId || associatedGrn.customer_id || '';
                }
            }

            if (editCustomerId) {
                const outwardCustomerSelect = document.getElementById('outward-customer');
                if (outwardCustomerSelect) {
                    const optExists = Array.from(outwardCustomerSelect.options).some(o => o.value === editCustomerId);
                    if (!optExists) {
                        const c = db.customers.find(x => x.id === editCustomerId);
                        if (c) {
                            const opt = document.createElement('option');
                            opt.value = c.id;
                            opt.textContent = c.name + ' (Cancelled/System)';
                            outwardCustomerSelect.appendChild(opt);
                        }
                    }
                    outwardCustomerSelect.value = editCustomerId;
                    reinitSearchableSelect(outwardCustomerSelect);
                    window.onOutwardCustomerChange();
                }
            }

            if (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered') {
                const soSelect = document.getElementById('outward-linked-so');
                if (soSelect) {
                    if (editCustomerId && soSelect.dataset.lastCustomerId !== editCustomerId) {
                        soSelect.innerHTML = '<option value="">-- Select Sales Order --</option>';
                        const filteredSOs = (db.salesOrders || []).filter(so => so.customerId === editCustomerId && (so.status || '').toLowerCase() !== 'cancelled');
                        filteredSOs.forEach(so => {
                            const opt = document.createElement('option');
                            opt.value = so.id;
                            opt.textContent = `${so.number} (Design: ${window.getSoDesignOrItemDisplay(so)}, Qty: ${so.qty})`;
                            soSelect.appendChild(opt);
                        });
                        soSelect.dataset.lastCustomerId = editCustomerId;
                    }
                    soSelect.value = out.linked_so_id || '';
                    reinitSearchableSelect(soSelect);
                    window.onOutwardCustomerChange();
                }
                
                let slips = out.packageSlips || [];
                if ((!slips || slips.length === 0) && out.dispatchedPackages && out.dispatchedPackages.length > 0) {
                    let resolvedItemName = '';
                    if (out.linked_so_id) {
                        const allSalesOrders = [...(db.salesOrders || []), ...(rawDB.salesOrders || [])];
                        const so = allSalesOrders.find(s => String(s.id) === String(out.linked_so_id));
                        if (so) {
                            resolvedItemName = window.getSoDesignOrItemDisplay(so) || so.designNumber || so.item_name || so.itemName || '';
                            if (resolvedItemName.includes(',')) resolvedItemName = resolvedItemName.split(',')[0].trim();
                        }
                    }
                    slips = out.dispatchedPackages.map(pkg => ({
                        fabricType: resolvedItemName,
                        itemName: resolvedItemName,
                        pkgCount: pkg.than || pkg.pkgCount || 0,
                        than: pkg.than || pkg.pkgCount || 0,
                        conversion: pkg.conversion || 0,
                        qty: pkg.qty || 0
                    }));
                } else if ((!slips || slips.length === 0) && (Number(out.qty || out.meters_issued || 0) > 0)) {
                    let resolvedItemName = '';
                    if (out.linked_so_id) {
                        const allSalesOrders = [...(db.salesOrders || []), ...(rawDB.salesOrders || [])];
                        const so = allSalesOrders.find(s => String(s.id) === String(out.linked_so_id));
                        if (so) {
                            resolvedItemName = window.getSoDesignOrItemDisplay(so) || so.designNumber || so.item_name || so.itemName || '';
                            if (resolvedItemName.includes(',')) resolvedItemName = resolvedItemName.split(',')[0].trim();
                        }
                    }
                    const valQty = Number(out.qty || out.meters_issued || 0);
                    slips = [{
                        fabricType: resolvedItemName,
                        itemName: resolvedItemName,
                        pkgCount: 0,
                        than: 0,
                        conversion: 0,
                        qty: valQty
                    }];
                }

                if (slips && slips.length > 0) {
                    const outEmbBody = document.getElementById('outward-embroidery-body');
                    if (outEmbBody) outEmbBody.innerHTML = '';
                    slips.forEach(slip => {
                        window.addOutwardEmbroideryRow({
                            itemName: slip.fabricType || slip.itemName || '',
                            than: slip.pkgCount || slip.than || 0,
                            conversion: slip.conversion || 0,
                            qty: slip.qty || 0
                        });
                    });
                }
                
                const outEmbBody = document.getElementById('outward-embroidery-body');
                if (outEmbBody && outEmbBody.querySelectorAll('.outward-embroidery-row').length === 0) {
                    window.addOutwardEmbroideryRow();
                }

                let usedStates = parseFabricUsedState(out.remarks || '');
                if ((!usedStates || usedStates.length === 0) && out.grnLinks && out.grnLinks.length > 0) {
                    usedStates = out.grnLinks.map(link => {
                        const g = (db.grns || []).find(x => x.id === link.grnRefId);
                        return {
                            grnId: link.grnRefId,
                            grnNo: g ? (g.partyDocNo || g.grnNo || g.number) : '',
                            fabricType: g ? (g.fabricType || g.item || 'Plain Fabric') : 'Plain Fabric',
                            than: 0,
                            conversion: 0,
                            qty: link.qty || 0
                        };
                    });
                } else if ((!usedStates || usedStates.length === 0) && out.grnRefId) {
                    const g = (db.grns || []).find(x => x.id === out.grnRefId);
                    usedStates = [{
                        grnId: out.grnRefId,
                        grnNo: g ? (g.partyDocNo || g.grnNo || g.number) : '',
                        fabricType: g ? (g.fabricType || g.item || 'Plain Fabric') : 'Plain Fabric',
                        than: 0,
                        conversion: 0,
                        qty: Number(out.qty || out.meters_issued || 0)
                    }];
                }

                if (usedStates && usedStates.length > 0) {
                    const outFabricUsedBody = document.getElementById('outward-fabric-used-body');
                    if (outFabricUsedBody) outFabricUsedBody.innerHTML = '';
                    usedStates.forEach(state => {
                        if (state.grnId || state.issueId) {
                            window.addOutwardFabricUsedRow(state);
                        } else {
                            window.addOutwardFabricUsedManualRow(state);
                        }
                    });
                }
                window.updateOutwardFabricIssues();
            }
            window.renderOutwardFormGRNLinks();

            document.getElementById('outward-grn-ref').value = out.grnRefId || '';
            document.getElementById('outward-meters').value = Number(out.qty || 0).toFixed(2);
            if (typeof window.calcOutwardTotalMeters === 'function') {
                window.calcOutwardTotalMeters();
            }
            
            // Populate new transport values for edit
            let hasTrans = out.hasTransporter;
            if (hasTrans === true || hasTrans === 'true' || hasTrans === 'Yes') hasTrans = 'Yes';
            else if (hasTrans === false || hasTrans === 'false' || hasTrans === 'No') hasTrans = 'No';
            else hasTrans = out.transporterId ? 'Yes' : 'No';

            let hasFreight = out.hasLocalFreight;
            if (hasFreight === true || hasFreight === 'true' || hasFreight === 'Yes') hasFreight = 'Yes';
            else if (hasFreight === false || hasFreight === 'false' || hasFreight === 'No') hasFreight = 'No';
            else hasFreight = (out.taxiName || (!out.transporterId && out.vehicleNo)) ? 'Yes' : 'No';
            
            document.getElementById('outward-has-transporter').value = hasTrans;
            document.getElementById('outward-has-local-freight').value = hasFreight;
            
            const tSel = document.getElementById('outward-transporter');
            if (tSel) {
                if (out.transporterId) {
                    let opt = Array.from(tSel.options).find(o => o.value === out.transporterId);
                    if (!opt && (out.transporterName || out.transporter)) {
                        opt = document.createElement('option');
                        opt.value = out.transporterId;
                        opt.textContent = out.transporterName || out.transporter;
                        tSel.appendChild(opt);
                    }
                    tSel.value = out.transporterId;
                } else if (out.transporterName || out.transporter) {
                    let opt = Array.from(tSel.options).find(o => o.textContent.trim().toLowerCase() === String(out.transporterName || out.transporter).trim().toLowerCase());
                    if (opt) tSel.value = opt.value;
                } else {
                    tSel.value = '';
                }
            }
            const allTrans = [...(db.transporters || []), ...(rawDB?.transporters || []), ...(window.crossCompanyTransporters || [])];
            const trans = allTrans.find(t => String(t.id) === String(out.transporterId || '')) || allTrans.find(t => t.name && t.name.toLowerCase().trim() === String(out.transporterName || '').toLowerCase().trim());
            document.getElementById('outward-transporter-gst').value = trans ? (trans.gst || '') : '';
            
            document.getElementById('outward-lr').value = out.lrNo || '';
            const tState = parseGrnTransportState(out);
            const payTypeEl = document.getElementById('outward-freight-payment-type');
            if (payTypeEl) {
                payTypeEl.value = tState.freightPaymentType || out.freightPaymentType || 'To Pay';
                if (typeof reinitSearchableSelect === 'function') reinitSearchableSelect(payTypeEl);
            }
            document.getElementById('outward-transport-pkg-count').value = out.transportPkgCount || '';
            document.getElementById('outward-transport-labour').value = out.transportLabour || '';
            
            document.getElementById('outward-taxi-name').value = out.taxiName || '';
            document.getElementById('outward-vehicle').value = out.vehicleNo || '';
            document.getElementById('outward-place').value = out.place || '';
            
            window.toggleOutwardTransportSection();
            reinitSearchableSelect(document.getElementById('outward-has-transporter'));
            reinitSearchableSelect(document.getElementById('outward-has-local-freight'));
            reinitSearchableSelect(document.getElementById('outward-transporter'));
            reinitSearchableSelect(document.getElementById('outward-taxi-name'));
            
            window.onOutwardPOSelectChange();
        }
    } else {
        currentOutwardLinks = [];
        currentOutwardPackages = [];
        window.grnConvertedLog = {};
        let typePrefix = 'JW';
        if (outwardWizardState.type === 'fabric_issue_challan') {
            if (outwardWizardState.source === 'customer') {
                typePrefix = outwardWizardState.subType === 'plain' ? 'FI/C/PF' : 'FI/C/EM';
            } else {
                typePrefix = outwardWizardState.subType === 'plain' ? 'FI/V/PF' : 'FI/V/EM';
            }
        } else if (outwardWizardState.type === 'inhouse') {
            typePrefix = 'FI/INH';
        } else if (outwardWizardState.type === 'jobworker') {
            typePrefix = 'FI/JW';
        } else if (outwardWizardState.type === 'consumable') {
            typePrefix = 'FI/V/CON';
        }

        const activeOutwards = db.outwards.filter(o => {
            const state = parseOutwardWizardState(o);
            if (state.type !== outwardWizardState.type) return false;
            if (outwardWizardState.type === 'fabric_issue_challan') {
                if (state.source !== outwardWizardState.source) return false;
                if (state.subType !== outwardWizardState.subType) return false;
            }
            return true;
        });

        let nextNum = 1;
        if (activeOutwards.length > 0) {
            const numbers = activeOutwards.map(o => getBaseNumberFromOutward(o.number, typePrefix) || 0);
            nextNum = Math.max(...numbers) + 1;
        }

        document.getElementById('outward-number').value = customDocNo || getDocumentNumber(typePrefix, nextNum);
        document.getElementById('outward-date').value = today();
        document.getElementById('outward-customer').value = '';
        if (typeof reinitSearchableSelect === 'function') {
            reinitSearchableSelect(document.getElementById('outward-customer'));
        }
        window.onOutwardCustomerChange();
        window.renderOutwardFormGRNLinks();
        document.getElementById('outward-po-ref').value = '';
        if (typeof reinitSearchableSelect === 'function') {
            reinitSearchableSelect(document.getElementById('outward-po-ref'));
        }
        document.getElementById('outward-grn-ref').value = '';
        document.getElementById('outward-bal-meters').value = '0.00';
        document.getElementById('outward-meters').value = '';
        const fabQtyDisp = document.getElementById('outward-fabric-qty-display');
        if (fabQtyDisp) fabQtyDisp.value = '0.00';
        const consQtyDisp = document.getElementById('outward-consumable-qty-display');
        if (consQtyDisp) consQtyDisp.value = '0.00';
        if (typeof window.calcOutwardTotalMeters === 'function') {
            window.calcOutwardTotalMeters();
        }
        
        const sourceSelect = document.getElementById('outward-material-source-type');
        if (sourceSelect) {
            sourceSelect.value = 'customer';
            if (typeof reinitSearchableSelect === 'function') {
                reinitSearchableSelect(sourceSelect);
            }
        }
        
        const vendorSelect = document.getElementById('outward-vendor');
        if (vendorSelect) {
            vendorSelect.value = '';
            if (typeof reinitSearchableSelect === 'function') {
                reinitSearchableSelect(vendorSelect);
            }
        }
        
        if (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered') {
            window.addOutwardEmbroideryRow();
        }
        
        // Reset transport fields
        document.getElementById('outward-has-transporter').value = 'No';
        document.getElementById('outward-has-local-freight').value = 'No';
        document.getElementById('outward-transporter').value = '';
        document.getElementById('outward-transporter-gst').value = '';
        document.getElementById('outward-lr').value = '';
        const payTypeEl = document.getElementById('outward-freight-payment-type');
        if (payTypeEl) {
            payTypeEl.value = 'To Pay';
            if (typeof reinitSearchableSelect === 'function') reinitSearchableSelect(payTypeEl);
        }
        document.getElementById('outward-transport-pkg-count').value = '';
        document.getElementById('outward-transport-labour').value = '';
        document.getElementById('outward-taxi-name').value = '';
        document.getElementById('outward-vehicle').value = '';
        document.getElementById('outward-place').value = '';
        
        window.toggleOutwardTransportSection();
        reinitSearchableSelect(document.getElementById('outward-has-transporter'));
        reinitSearchableSelect(document.getElementById('outward-has-local-freight'));
        reinitSearchableSelect(document.getElementById('outward-transporter'));
        reinitSearchableSelect(document.getElementById('outward-taxi-name'));
    }

    // Dyn header and labels setup
    let modalTitle = editId ? 'Edit Fabric Issue' : 'New Fabric Issue';
    if (outwardWizardState.type === 'fabric_issue_challan') {
        const sourceStr = outwardWizardState.source === 'customer' ? 'For Customer' : 'For Vendor';
        const subTypeStr = outwardWizardState.subType === 'plain' ? 'Plain Fabric' : 'Embroidery';
        modalTitle = (editId ? 'Edit' : 'New') + ` Fabric Issue Challan - ${sourceStr} - ${subTypeStr}`;
    } else if (outwardWizardState.type === 'inhouse') {
        modalTitle = (editId ? 'Edit' : 'New') + ' Fabric Issue - In House';
    } else if (outwardWizardState.type === 'jobworker') {
        modalTitle = (editId ? 'Edit' : 'New') + ' Job Work Challan - Job Worker';
    } else if (outwardWizardState.type === 'consumable') {
        modalTitle = (editId ? 'Edit' : 'New') + ' Consumable Issue Challan - For Vendor';
    }
    
    const titleEl = document.querySelector('#outward-modal h3');
    if (titleEl) titleEl.textContent = modalTitle;

    // Field visibility logic
    const vendorRow = document.getElementById('outward-vendor-row');
    const vendorLabel = document.getElementById('outward-vendor-label');
    const vendorGroup = document.getElementById('outward-vendor-group');
    const customerRow = document.getElementById('outward-customer-row');
    const poRefGroup = document.getElementById('outward-po-ref-group');
    
    if (vendorRow) vendorRow.style.display = 'grid';
    if (vendorGroup) vendorGroup.style.display = '';
    if (customerRow) customerRow.style.display = 'grid';
    if (poRefGroup) poRefGroup.style.display = 'block';
    if (vendorLabel) vendorLabel.textContent = 'Vendor *';
    
    if (outwardWizardState.type === 'fabric_issue_challan') {
        if (outwardWizardState.source === 'customer') {
            if (vendorRow) vendorRow.style.display = 'none';
            if (poRefGroup) poRefGroup.style.display = 'none';
        }
    }
    const linkedSoGroup = document.getElementById('outward-linked-so-group');
    if (linkedSoGroup) {
        if (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered') {
            linkedSoGroup.style.display = 'block';
        } else {
            linkedSoGroup.style.display = 'none';
        }
    }
    if (outwardWizardState.type === 'inhouse') {
        if (vendorGroup) vendorGroup.style.display = 'none';
        const transContainer = document.getElementById('outward-transporter-fields-container');
        if (transContainer) transContainer.style.display = 'none';
    } else {
        const transContainer = document.getElementById('outward-transporter-fields-container');
        if (transContainer) transContainer.style.display = '';
        if (outwardWizardState.type === 'jobworker') {
            if (vendorLabel) vendorLabel.textContent = 'Job Worker *';
        }
    }

    // Set dynamic text for linked GRNs title
    const grnTitleEl = document.getElementById('outward-linked-grns-title');
    if (grnTitleEl) {
        let titleText = 'Linked Customer Challans (Plain Fabric GRN)';
        if (outwardWizardState.type === 'fabric_issue_challan') {
            const partyType = outwardWizardState.source === 'customer' ? 'Customer' : 'Vendor';
            const subTypeStr = outwardWizardState.subType === 'plain' ? 'Plain Fabric' : 'Embroidered Fabric';
            titleText = `Linked ${partyType} Challans (${subTypeStr} GRN)`;
        } else if (outwardWizardState.type === 'inhouse') {
            titleText = 'Linked Customer Challans (Plain Fabric GRN)';
        } else if (outwardWizardState.type === 'jobworker') {
            titleText = 'Linked Customer Challans (Plain Fabric GRN)';
        }
        grnTitleEl.textContent = titleText;
    }
    
    const saveBtn = document.querySelector("#outward-modal .btn-primary");
    const cancelBtn = document.querySelector("#outward-modal button[onclick*='cancelVoucher']");
    const headerTitleEl = document.querySelector('#outward-modal h3');
    
    if (isViewOnly) {
        if (saveBtn) saveBtn.style.display = 'none';
        if (cancelBtn) cancelBtn.style.display = 'none';
        document.querySelectorAll("#outward-modal input, #outward-modal select, #outward-modal textarea").forEach(el => {
            el.disabled = true;
        });
        document.querySelectorAll("#outward-modal button:not(.modal-close):not([onclick*='closeModal'])").forEach(el => {
            el.style.display = 'none';
        });
        if (headerTitleEl) {
            headerTitleEl.textContent = headerTitleEl.textContent.replace('Edit', 'View').replace('New', 'View');
        }
    } else {
        if (saveBtn) saveBtn.style.display = '';
        if (cancelBtn) cancelBtn.style.display = '';
        document.querySelectorAll("#outward-modal input, #outward-modal select, #outward-modal textarea").forEach(el => {
            el.disabled = false;
        });
        document.querySelectorAll("#outward-modal button").forEach(el => {
            el.style.display = '';
        });
    }

    const transportContainer = document.getElementById('outward-transporter-fields-container');
    const machineContainer = document.getElementById('outward-machine-internal-row');
    const transportTitle = document.getElementById('outward-transport-title');
    
    if (outwardWizardState.type === 'inhouse') {
        if (transportContainer) transportContainer.style.display = 'none';
        if (machineContainer) machineContainer.style.display = 'none';
        if (transportTitle) {
            transportTitle.style.display = 'none';
        }
    } else {
        if (transportContainer) transportContainer.style.display = 'block';
        if (machineContainer) machineContainer.style.display = 'none';
        if (transportTitle) {
            transportTitle.style.display = 'block';
            transportTitle.textContent = 'Transportation Details';
        }
    }

    const isConsumable = outwardWizardState.type === 'consumable';
    const isEmbroidery = (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered');
    const embroideryContainer = document.getElementById('outward-embroidery-container');
    const fabricUsedContainer = document.getElementById('outward-fabric-used-container');
    const multiGrnGroup = document.getElementById('outward-multi-grn-group');

    if (isConsumable) {
        if (vendorRow) vendorRow.style.display = 'grid';
        if (vendorGroup) vendorGroup.style.display = '';
        if (customerRow) customerRow.style.display = 'none';
        if (poRefGroup) poRefGroup.style.display = 'none';
        if (vendorLabel) vendorLabel.textContent = 'Vendor *';
        const sectionTitle = document.querySelector('#outward-embroidery-container .form-section-title');
        if (sectionTitle) sectionTitle.textContent = 'Consumable Items Detail';
    } else {
        const sectionTitle = document.querySelector('#outward-embroidery-container .form-section-title');
        if (sectionTitle) sectionTitle.textContent = 'Embroidery Items Detail';
    }

    if (embroideryContainer) {
        embroideryContainer.style.display = (isEmbroidery || isConsumable) ? 'block' : 'none';
        if (isConsumable && (!editId || (document.querySelectorAll('.outward-embroidery-row').length === 0))) {
            const outEmbBody = document.getElementById('outward-embroidery-body');
            if (outEmbBody && outEmbBody.children.length === 0) {
                window.addOutwardEmbroideryRow();
            }
        }
    }
    if (fabricUsedContainer) {
        const selectedSoId = document.getElementById('outward-linked-so')?.value || '';
        const linkedSO = db.salesOrders ? db.salesOrders.find(s => s.id === selectedSoId) : null;
        const isWithMaterial = linkedSO && linkedSO.materialType === 'with_material';
        fabricUsedContainer.style.display = (isEmbroidery && !isWithMaterial) ? 'block' : 'none';
    }
    if (multiGrnGroup) {
        const sourceTypeEl = document.getElementById('outward-material-source-type');
        const sourceType = sourceTypeEl ? sourceTypeEl.value : 'customer';
        if (sourceType === 'consumable') {
            multiGrnGroup.style.display = 'none';
        } else {
            multiGrnGroup.style.display = isEmbroidery ? 'none' : 'block';
        }
    }

    window.updateModalUserLog('outward-modal');
    if (window.attachRamaSyncModalWarning) window.attachRamaSyncModalWarning('outward-modal', editId);
    openModal('outward-modal');
}

window.toggleOutwardTransportSection = function() {
    const venId = document.getElementById('outward-vendor')?.value || '';
    const custId = document.getElementById('outward-customer')?.value || '';
    const partyId = venId || custId;
    const partyObj = (db.vendors || []).find(v => v.id === partyId) || (db.customers || []).find(c => c.id === partyId);
    const partyName = partyObj ? partyObj.name : partyId;

    if (partyId) {
        const pincode = String(partyObj ? (partyObj.pincode || partyObj.pinCode || partyObj.pin || partyObj.zip || '') : '').trim();
        if (!pincode) {
            if (window._lastPincodeWarnedPartyOutward !== partyId && typeof showToast === 'function') {
                showToast(`Warning: Pincode is not specified for party "${partyName || partyId}". Please update pincode in Masters.`, 'warning');
                window._lastPincodeWarnedPartyOutward = partyId;
            }
        } else if (window._lastPincodeWarnedPartyOutward === partyId) {
            window._lastPincodeWarnedPartyOutward = null;
        }
    }

    const isOutstation = window.isPartyOutstation(partyId, partyName);

    const hasTransEl = document.getElementById('outward-has-transporter');
    const localFreightSelect = document.getElementById('outward-has-local-freight');

    if (partyId && !isOutstation && hasTransEl) {
        hasTransEl.value = 'No';
        if (typeof reinitSearchableSelect === 'function') {
            reinitSearchableSelect(hasTransEl);
        }
    }

    if (localFreightSelect) {
        localFreightSelect.disabled = false;
        localFreightSelect.title = '';
    }

    const hasTrans = hasTransEl?.value === 'Yes';
    const hasFreight = (localFreightSelect?.value === 'Yes');

    // Show/hide the inline detail rows
    const tInline = document.getElementById('outward-transporter-inline');
    const fInline = document.getElementById('outward-local-freight-inline');
    if (tInline) tInline.style.display = hasTrans ? 'flex' : 'none';
    if (fInline) fInline.style.display = hasFreight ? 'flex' : 'none';

    // Keep old group hidden (now empty, kept for compat)
    const tGroup = document.getElementById('outward-transporter-group');
    const fGroup = document.getElementById('outward-local-freight-group');
    if (tGroup) tGroup.style.display = 'none';
    if (fGroup) fGroup.style.display = 'none';

    if (typeof reinitSearchableSelect === 'function' && localFreightSelect) {
        reinitSearchableSelect(localFreightSelect);
    }
};

window.onOutwardTransporterSelectChange = function() {
    const transId = document.getElementById('outward-transporter').value;
    const trans = (db.transporters || []).find(t => t.id === transId);
    document.getElementById('outward-transporter-gst').value = trans ? (trans.gst || '') : '';
    if (typeof window.toggleOutwardTransportSection === 'function') {
        window.toggleOutwardTransportSection();
    }
};

function filterOutwardPOs() {
    if (typeof window.toggleOutwardTransportSection === 'function') {
        window.toggleOutwardTransportSection();
    }
    const poSel = document.getElementById('outward-po-ref');
    if (!poSel) return;
    
    poSel._isIntercepting = true;
    try {
        const venId = document.getElementById('outward-vendor').value;
        const custId = document.getElementById('outward-customer').value;
        const poLabel = poSel.previousElementSibling;
        const selectedPoId = poSel.value;
        
        const editId = document.getElementById('outward-edit-id').value;
        let currentPoRefId = null;
        if (editId) {
            const out = (db.outwards || []).find(o => o.id === editId);
            if (out && out.poRefId) {
                const matchedPO = (db.pos || []).find(p => p.id === out.poRefId || p.number === out.poRefId);
                if (matchedPO) {
                    currentPoRefId = matchedPO.id;
                } else {
                    currentPoRefId = out.poRefId;
                }
            }
        }
        
        if (outwardWizardState.type === 'inhouse') {
            if (poLabel) poLabel.textContent = 'PO Reference *';
            poSel.innerHTML = '<option value="">-- Select PO --</option>';
            let filteredPOs = (db.pos || []).filter(po => 
                ((po.poType || 'vendor') === 'inhouse' || String(po.number || '').toUpperCase().startsWith('PO/INH')) && 
                (po.status || '').trim().toLowerCase() !== 'cancelled'
            );
            if (custId) {
                filteredPOs = filteredPOs.filter(po => {
                    if (po.id === currentPoRefId) return true;
                    if (po.customerId === custId) return true;
                    const linkedSoId = po.linkedSoId || po.soRef;
                    if (linkedSoId) {
                        const so = db.salesOrders.find(s => s.id === linkedSoId || s.number === linkedSoId);
                        if (so && so.customerId === custId) return true;
                    }
                    return false;
                });
            }
            if (currentPoRefId) {
                const currentPo = (db.pos || []).find(p => p.id === currentPoRefId);
                if (currentPo && !filteredPOs.some(p => p.id === currentPoRefId)) {
                    filteredPOs.push(currentPo);
                }
            }
            if (selectedPoId) {
                const selPo = (db.pos || []).find(p => p.id === selectedPoId);
                if (selPo && !filteredPOs.some(p => p.id === selectedPoId)) {
                    filteredPOs.push(selPo);
                }
            }
            const hasPoPermission = typeof checkPermission === 'function' ? checkPermission('po_inhouse', 'read') : true;
            filteredPOs.forEach(po => {
                const opt = document.createElement('option');
                opt.value = po.id;
                if (!hasPoPermission) {
                    opt.textContent = `${po.number} (*********)`;
                } else {
                    const itemName = po.items?.[0]?.processName || po.design || '';
                    const displayItemName = (itemName && itemName !== '-') ? itemName : '';
                    const clientName = po.customerName || po.customer_name || '';
                    const orderQty = po.qty ? `${po.qty} Mtr` : '';
                    const soStr = po.linkedSoNumber ? `SO: ${po.linkedSoNumber}` : '';
                    
                    const details = [clientName, displayItemName, orderQty, soStr].filter(Boolean).join(' | ');
                    const label = details ? `${po.number} (${details})` : po.number;
                    opt.textContent = label;
                }
                poSel.appendChild(opt);
            });
        } else {
            if (poLabel) {
                if (outwardWizardState.type === 'jobworker') {
                    poLabel.textContent = 'PO (Finishing JW) *';
                } else {
                    poLabel.textContent = 'PO Reference *';
                }
            }
            poSel.innerHTML = outwardWizardState.type === 'jobworker' ? '<option value="">-- Select PO Finishing JW --</option>' : '<option value="">-- Select PO --</option>';
            
            let filteredPOs;
            if (outwardWizardState.type === 'jobworker') {
                filteredPOs = (db.pos || []).filter(po => 
                    (po.poType || po.po_type || '').toLowerCase() === 'finishing_jw' && 
                    (po.status || '').trim().toLowerCase() !== 'cancelled'
                );
            } else {
                filteredPOs = (db.pos || []).filter(po => 
                    (po.poType || 'vendor') === 'vendor' && 
                    (po.status || '').trim().toLowerCase() !== 'cancelled'
                );
            }
            if (venId) {
                filteredPOs = filteredPOs.filter(po => po.id === currentPoRefId || po.vendorId === venId);
            }
            if (custId) {
                filteredPOs = filteredPOs.filter(po => {
                    if (po.id === currentPoRefId) return true;
                    if (po.customerId === custId) return true;
                    
                    const targetCust = db.customers.find(c => c.id === custId);
                    const targetCustName = targetCust ? String(targetCust.name || '').trim().toLowerCase() : '';
                    if (targetCustName && po.customerName && String(po.customerName).trim().toLowerCase() === targetCustName) {
                        return true;
                    }
                    
                    const linkedSoId = po.linkedSoId || po.soRef;
                    if (linkedSoId) {
                        const so = db.salesOrders.find(s => s.id === linkedSoId || s.number === linkedSoId);
                        if (so && so.customerId === custId) return true;
                    }
                    if (po.linkedSoNumber) {
                        const cleanSoNo = String(po.linkedSoNumber).trim().toLowerCase();
                        const so = db.salesOrders.find(s => String(s.number || '').trim().toLowerCase() === cleanSoNo);
                        if (so && so.customerId === custId) return true;
                    }
                    return false;
                });
            }
            if (currentPoRefId) {
                const currentPo = (db.pos || []).find(p => p.id === currentPoRefId);
                if (currentPo && !filteredPOs.some(p => p.id === currentPoRefId)) {
                    filteredPOs.push(currentPo);
                }
            }
            if (selectedPoId) {
                const selPo = (db.pos || []).find(p => p.id === selectedPoId);
                if (selPo && !filteredPOs.some(p => p.id === selectedPoId)) {
                    filteredPOs.push(selPo);
                }
            }
            filteredPOs.forEach(po => {
                const opt = document.createElement('option');
                opt.value = po.id;
                if (outwardWizardState.type === 'jobworker') {
                    const itemName = po.items?.[0]?.processName || po.design || '';
                    const displayItemName = (itemName && itemName !== '-') ? itemName : '';
                    const clientName = po.customerName || po.customer_name || '';
                    const orderQty = po.qty ? `${po.qty} Mtr` : '';
                    const details = [clientName, displayItemName, orderQty].filter(Boolean).join(' | ');
                    opt.textContent = details ? `${po.number} (${details})` : po.number;
                } else {
                    opt.textContent = po.number + ' (Val: \u20B9' + po.totalValue.toLocaleString('en-IN') + ')';
                }
                poSel.appendChild(opt);
            });
        }
        if (selectedPoId && [...poSel.options].some(opt => opt.value === selectedPoId)) {
            poSel.value = selectedPoId;
        } else if (currentPoRefId && [...poSel.options].some(opt => opt.value === currentPoRefId)) {
            poSel.value = currentPoRefId;
        }
        if (typeof reinitSearchableSelect === 'function') {
            reinitSearchableSelect(poSel);
        }
    } finally {
        poSel._isIntercepting = false;
    }
}

window.onOutwardSourceTypeChange = function() {
    const sourceTypeEl = document.getElementById('outward-material-source-type');
    const sourceType = sourceTypeEl ? sourceTypeEl.value : 'customer';
    const grnGroup = document.getElementById('outward-multi-grn-group');
    const consumableGroup = document.getElementById('outward-consumable-group');
    
    if (sourceType === 'customer') {
        if (grnGroup) grnGroup.style.display = 'flex';
        if (consumableGroup) consumableGroup.style.display = 'none';
    } else if (sourceType === 'consumable') {
        if (grnGroup) grnGroup.style.display = 'none';
        if (consumableGroup) consumableGroup.style.display = 'flex';
    } else if (sourceType === 'both') {
        if (grnGroup) grnGroup.style.display = 'flex';
        if (consumableGroup) consumableGroup.style.display = 'flex';
    }
    
    if (typeof window.calcOutwardTotalMeters === 'function') {
        window.calcOutwardTotalMeters();
    }
};

window.updateOutwardMetersSum = function() {
    if (typeof window.calcOutwardTotalMeters === 'function') {
        window.calcOutwardTotalMeters();
    }
};

window.populateConsumableItems = function(currentSelectedId = null) {
    const cItemSelect = document.getElementById('outward-consumable-item');
    if (!cItemSelect) return;
    
    cItemSelect.innerHTML = '<option value="">-- Select Consumable --</option>';
    
    const terms = ['consumable fabric', 'interlining', 'non-woven', 'nonwoven', 'thread', 'accessories', 'packing material', 'raw material', 'consumable', 'consumables', 'needle', 'yarn', 'non wooven'];
    const consumableItems = (db.items || []).filter(item => {
        const groupName = (item.group || item.category || '').toLowerCase().trim();
        const nameLower = (item.name || '').toLowerCase().trim();
        return terms.some(term => groupName.includes(term) || nameLower.includes(term));
    });
    
    consumableItems.forEach(item => {
        const opt = document.createElement('option');
        opt.value = item.id;
        opt.textContent = item.name + (item.code ? ` [${item.code}]` : '');
        cItemSelect.appendChild(opt);
    });
    
    if (currentSelectedId) {
        const optExists = Array.from(cItemSelect.options).some(o => o.value === currentSelectedId);
        if (!optExists) {
            const item = (db.items || []).find(i => i.id === currentSelectedId);
            if (item) {
                const opt = document.createElement('option');
                opt.value = item.id;
                opt.textContent = item.name + (item.code ? ` [${item.code}]` : '');
                cItemSelect.appendChild(opt);
            }
        }
    }
    
    if (typeof reinitSearchableSelect === 'function') {
        reinitSearchableSelect(cItemSelect);
    }
};

window.onOutwardPOSelectChange = function() {
    const poId = document.getElementById('outward-po-ref').value;
    if (!poId) return;

    const transportContainer = document.getElementById('outward-transporter-fields-container');
    const machineContainer = document.getElementById('outward-machine-internal-row');
    const transportTitle = document.getElementById('outward-transport-title');

    const machSelect = document.getElementById('outward-machine-select');
    if (machSelect && machSelect.options.length <= 1) {
        machSelect.innerHTML = '<option value="">-- Select Machine --</option>';
        (db.machines || []).forEach(m => {
            const opt = document.createElement('option');
            opt.value = m.id;
            opt.textContent = m.name;
            machSelect.appendChild(opt);
        });
    }

    let custId = '';
    let linkedSo = null;
    let po = null;

    if (outwardWizardState.type === 'inhouse') {
        if (transportContainer) transportContainer.style.display = 'none';
        if (machineContainer) machineContainer.style.display = 'none';
        if (transportTitle) transportTitle.style.display = 'none';

        const editId = document.getElementById('outward-edit-id').value;
        if (editId) {
            const out = db.outwards.find(o => o.id === editId);
            const meta = parseMetadataFromRemarks(out ? out.remarks : '', '__MACHINE_METADATA__');
            const machNo = out ? (out.machineNo || (meta && meta.links ? meta.links.machineNo : '')) : '';
            if (machNo && machSelect) {
                const match = (db.machines || []).find(m => m.name === machNo);
                if (match) machSelect.value = match.id;
            }
        }


        // poId is now an in-house PO ID!
        po = db.pos.find(p => p.id === poId);
        if (po) {
            const soId = po.linkedSoId || po.soRef || '';
            linkedSo = db.salesOrders.find(s => s.id === soId);
            if (linkedSo) {
                custId = linkedSo.customerId || '';
            }
        }
    } else {
        po = db.pos.find(p => p.id === poId);
        if (po) {
            if (po.poType === 'inhouse') {
                if (transportContainer) transportContainer.style.display = 'none';
                if (machineContainer) machineContainer.style.display = 'flex';
                if (transportTitle) transportTitle.textContent = 'Internal Production Details';
            } else {
                if (transportContainer) transportContainer.style.display = 'block';
                if (machineContainer) machineContainer.style.display = 'none';
                if (transportTitle) transportTitle.textContent = 'Transportation Details';
            }

            // Helper to resolve customer name to ID
            const resolveByName = (name) => {
                if (!name) return '';
                const c = db.customers.find(x => String(x.name || '').trim().toLowerCase() === String(name).trim().toLowerCase());
                return c ? c.id : '';
            };

            // 1. Try PO customerId directly
            if (po.customerId && db.customers.some(c => c.id === po.customerId)) {
                custId = po.customerId;
            }
            // 2. Try resolving PO customerId or customerName as a name
            if (!custId && po.customerId) {
                custId = resolveByName(po.customerId);
            }
            if (!custId && po.customerName) {
                custId = resolveByName(po.customerName);
            }

            // 3. Try resolving from linked Sales Order
            if (!custId) {
                if (po.linkedSoId) {
                    linkedSo = db.salesOrders.find(s => s.id === po.linkedSoId);
                }
                if (!linkedSo && po.linkedSoNumber) {
                    const cleanNum = String(po.linkedSoNumber).trim().toLowerCase();
                    linkedSo = db.salesOrders.find(s => String(s.number || '').trim().toLowerCase() === cleanNum);
                }
                if (linkedSo) {
                    if (linkedSo.customerId && db.customers.some(c => c.id === linkedSo.customerId)) {
                        custId = linkedSo.customerId;
                    }
                }
            } else {
                if (po.linkedSoId) {
                    linkedSo = db.salesOrders.find(s => s.id === po.linkedSoId);
                }
                if (!linkedSo && po.linkedSoNumber) {
                    const cleanNum = String(po.linkedSoNumber).trim().toLowerCase();
                    linkedSo = db.salesOrders.find(s => String(s.number || '').trim().toLowerCase() === cleanNum);
                }
            }
        }
    }

    const poDesigns = (po.items || []).map(it => (it.processName || it.itemName || '').toString().trim().toLowerCase()).filter(Boolean);
    if (po.designNumber) poDesigns.push(po.designNumber.toString().trim().toLowerCase());
    if (po.design) poDesigns.push(po.design.toString().trim().toLowerCase());
    if (po.designNo) poDesigns.push(po.designNo.toString().trim().toLowerCase());
    const hasPoDesigns = poDesigns.length > 0;
    if (!linkedSo && !hasPoDesigns) {
        showToast('Warning: Selected PO has no linked Sales Order or Design.', 'warning');
    }

    if (!custId) {
        custId = document.getElementById('outward-customer').value || '';
    }

    if (!custId) {
        showToast('Warning: Selected PO does not have an associated customer.', 'warning');
    }

    const linkedSoGroup = document.getElementById('outward-linked-so-group');
    const linkedSoDisplay = document.getElementById('outward-linked-so-display');
    if (linkedSoGroup && linkedSoDisplay) {
        if (linkedSo) {
            linkedSoGroup.style.display = 'block';
            linkedSoDisplay.value = `${linkedSo.number} (Item: ${window.getSoDesignOrItemDisplay(linkedSo)})`;
        } else {
            linkedSoGroup.style.display = 'none';
            linkedSoDisplay.value = '-';
        }
    }

    if (po && po.vendorId) {
        const venSelect = document.getElementById('outward-vendor');
        if (venSelect && venSelect.value !== po.vendorId) {
            venSelect.value = po.vendorId;
            if (typeof reinitSearchableSelect === 'function') {
                reinitSearchableSelect(venSelect);
            }
        }
    }

    if (custId) {
        const custSelect = document.getElementById('outward-customer');
        if (custSelect) {
            const oldCustVal = custSelect.value;
            custSelect.value = custId;
            if (typeof reinitSearchableSelect === 'function') {
                reinitSearchableSelect(custSelect);
            }
            if (oldCustVal !== custId) {
                window.onOutwardCustomerChange();
            }

            // Auto-scan and auto-select Customer GRN if found (Only on new entries)
            const editId = document.getElementById('outward-edit-id')?.value;
            if (!editId) {
                const targetSoId = linkedSo ? linkedSo.id : '';
                const targetSoNo = linkedSo ? linkedSo.number : '';
                
                if (targetSoId || targetSoNo) {
                    const matchingGrn = (db.grns || []).find(g => {
                        const wState = parseGrnWizardState(g);
                        const isPlainCustomerGRN = wState.type === 'fabric' && wState.source === 'customer' && wState.subType === 'plain';
                        if (!isPlainCustomerGRN) return false;

                        const matchesSO = (g.soRefId && (g.soRefId === targetSoId || g.soRefId === targetSoNo)) ||
                                          (g.linked_so_id && g.linked_so_id === targetSoId) ||
                                          (g.soLinks && g.soLinks.includes(targetSoId));
                        return matchesSO && (g.qty - (g.issuedMeters || 0) > 0);
                    });

                    const challanSel = document.getElementById('outward-cust-challan');
                    if (challanSel) {
                        if (matchingGrn) {
                            challanSel.value = matchingGrn.id;
                            window.onOutwardCustChallanChange();
                        } else {
                            challanSel.value = '';
                            window.onOutwardCustChallanChange();
                        }
                    }
                }
            }
        }
    }
    
    // Auto-update material source type from linked SO for in-house outward challans
    if (outwardWizardState.type === 'inhouse' && po) {
        const soId = po.linkedSoId || po.soRef || '';
        let soObj = db.salesOrders.find(s => s.id === soId || s.number === soId || String(s.id) === String(soId) || String(s.number).toLowerCase() === String(soId).toLowerCase());
        if (!soObj && po.linkedSoNumber) {
            const cleanSoNo = String(po.linkedSoNumber).trim().toLowerCase();
            soObj = db.salesOrders.find(s => String(s.number || '').trim().toLowerCase() === cleanSoNo);
        }
        if (soObj) {
            let matType = soObj.materialType;
            if (!matType && soObj.remarks) {
                const matMeta = parseMetadataFromRemarks(soObj.remarks, '__MATERIAL_TYPE__');
                if (matMeta && matMeta.links && typeof matMeta.links === 'string') {
                    matType = matMeta.links;
                }
            }
            const matSrcSelect = document.getElementById('outward-material-source-type');
            if (matSrcSelect) {
                if (matType === 'with_material') {
                    matSrcSelect.value = 'consumable';
                } else if (matType === 'consumable_customer_fabric') {
                    matSrcSelect.value = 'both';
                } else {
                    matSrcSelect.value = 'customer';
                }
                if (typeof window.onOutwardSourceTypeChange === 'function') {
                    window.onOutwardSourceTypeChange();
                }
            }
        }
    }

    if (typeof window.updateOutwardEmbroideryItemSelects === 'function') {
        window.updateOutwardEmbroideryItemSelects();
    }
};

let currentOutwardLinks = [];
let currentOutwardPackages = [];

window.onOutwardCustomerChange = function() {
    if (window.isOutwardCustomerChanging) return;
    window.isOutwardCustomerChanging = true;
    try {
        const custId = document.getElementById('outward-customer').value;
        const poRefEl = document.getElementById('outward-po-ref');
        if (poRefEl && poRefEl.value) {
            const po = (db.pos || []).find(p => p.id === poRefEl.value);
            if (po) {
                let poCustId = po.customerId || '';
                if (!poCustId && (po.poType === 'inhouse' || (po.number && String(po.number).toUpperCase().startsWith('PO/INH')))) {
                    const soId = po.linkedSoId || po.soRef || '';
                    const linkedSo = (db.salesOrders || []).find(s => s.id === soId);
                    if (linkedSo) {
                        poCustId = linkedSo.customerId || '';
                    }
                }
                if (!poCustId && po.customerName) {
                    const c = (db.customers || []).find(x => String(x.name || '').trim().toLowerCase() === String(po.customerName).trim().toLowerCase());
                    if (c) poCustId = c.id;
                }
                if (poCustId && poCustId !== custId) {
                    poRefEl.value = '';
                    if (typeof reinitSearchableSelect === 'function') {
                        reinitSearchableSelect(poRefEl);
                    }
                }
            }
        }
        if (window.outwardWizardState) {
            window.outwardWizardState.customerId = custId;
        }
        
        // Filter PO dropdown based on the selected customer
        filterOutwardPOs();

        const challanSel = document.getElementById('outward-cust-challan');
        const editId = document.getElementById('outward-edit-id').value;
        
        if (!challanSel) return;
        
        const soSel = document.getElementById('outward-linked-so');
        if (soSel) {
            if (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered') {
                if (soSel.dataset.lastCustomerId !== custId) {
                    challanSel.innerHTML = '<option value="">-- Select Challan No --</option>';
                    const prevVal = soSel.value;
                    soSel.innerHTML = '<option value="">-- Select Sales Order --</option>';
                    const filteredSOs = (db.salesOrders || []).filter(so => so.customerId === custId && (so.status || '').toLowerCase() !== 'cancelled');
                    filteredSOs.forEach(so => {
                        const opt = document.createElement('option');
                        opt.value = so.id;
                        opt.textContent = `${so.number} (Design: ${window.getSoDesignOrItemDisplay(so)}, Qty: ${so.qty})`;
                        soSel.appendChild(opt);
                    });
                    if (prevVal && filteredSOs.some(so => so.id === prevVal)) {
                        soSel.value = prevVal;
                    }
                    soSel.dataset.lastCustomerId = custId;
                    reinitSearchableSelect(soSel);
                }
            } else {
                delete soSel.dataset.lastCustomerId;
            }
        }

        if (!custId) {
            challanSel.innerHTML = '<option value="">-- Select Challan No --</option>';
            reinitSearchableSelect(challanSel);
            return;
        }
    
    // Clear links if customer changed (only on NEW entries when editId is not present)
    if (!editId) {
        const venId = document.getElementById('outward-vendor')?.value;
        const firstGrn = currentOutwardLinks.length > 0 ? (db.grns || []).find(g => g.id === currentOutwardLinks[0].grnRefId) : null;
        const currentCustIdOnLinks = firstGrn ? (firstGrn.customerId || firstGrn.vendorId) : null;
        if (currentCustIdOnLinks && currentCustIdOnLinks !== custId && currentCustIdOnLinks !== venId) {
            currentOutwardLinks = [];
            currentOutwardPackages = [];
            window.grnConvertedLog = {};
            window.renderOutwardFormGRNLinks();
        }
    }
    
    const poId = document.getElementById('outward-po-ref').value;
    const po = poId ? db.pos.find(p => p.id === poId) : null;
    let targetSoId = po ? po.linkedSoId : '';
    let targetSoNo = po ? po.linkedSoNumber : '';

    if (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered') {
        const soSelVal = document.getElementById('outward-linked-so')?.value;
        if (soSelVal) {
            targetSoId = soSelVal;
            const targetSo = db.salesOrders.find(s => s.id === soSelVal);
            if (targetSo) targetSoNo = targetSo.number;
        }
    }

    let allPlainGrns = (db.grns || []).filter(g => {
        const wState = parseGrnWizardState(g);
        let isMatching = false;
        if (outwardWizardState.type === 'fabric_issue_challan') {
            if (outwardWizardState.subType === 'plain') {
                isMatching = wState.type === 'fabric' && wState.subType === 'plain';
            } else {
                isMatching = wState.type === 'fabric' &&
                             wState.source === 'vendor' &&
                             wState.subType === 'embroidered';
            }
        } else {
            isMatching = wState.type === 'fabric' && wState.subType === 'plain';
        }
        if (!isMatching) return false;
        
        // Is it already linked in our table?
        const isAlreadyLinked = currentOutwardLinks.some(link => link.grnRefId === g.id);
        if (isAlreadyLinked) return false;
        
        // Does it have balance?
        let originalQty = 0;
        if (editId) {
            const existingOut = db.outwards.find(o => o.id === editId);
            if (existingOut) {
                if (existingOut.grnLinks) {
                    const match = existingOut.grnLinks.find(link => link.grnRefId === g.id);
                    if (match) originalQty = match.qty;
                } else if (existingOut.grnRefId === g.id) {
                    originalQty = existingOut.qty;
                }
            }
        }
        const bal = g.qty - (g.issuedMeters || 0) + originalQty;
        return (bal > 0);
    });

    let matchingGrns = allPlainGrns.filter(g => {
        if (!custId) return true;
        if (g.customerId === custId || g.vendorId === custId) return true;
        
        const dropdownCust = db.customers.find(c => c.id === custId) || db.vendors.find(v => v.id === custId);
        if (dropdownCust) {
            const grnCustName = String(g.customerName || g.vendorName || g.customerId || g.vendorId || '').trim().toLowerCase();
            const dropCustName = String(dropdownCust.name).trim().toLowerCase();
            if (grnCustName === dropCustName) return true;
            
            const linkedSo = db.salesOrders.find(so => so.id === g.soRefId || so.number === g.soRefId || so.id === g.linked_so_id);
            if (linkedSo) {
                const soCustName = String(linkedSo.customer_name || linkedSo.customer_id || '').trim().toLowerCase();
                if (soCustName === dropCustName || linkedSo.customer_id === custId) return true;
            }
        }
        return false;
    });

    // Soft fallback for linked Sales Order
    if (targetSoId || targetSoNo) {
        const matchesSO = matchingGrns.filter(g => {
            return (g.soRefId && (g.soRefId === targetSoId || g.soRefId === targetSoNo)) ||
                   (g.linked_so_id && (g.linked_so_id === targetSoId || g.linked_so_id === targetSoNo)) ||
                   (g.linked_so_number && (g.linked_so_number === targetSoId || g.linked_so_number === targetSoNo)) ||
                   (g.soLinks && g.soLinks.some(link => link === targetSoId || link === targetSoNo || (link && (link.soId === targetSoId || link.soNumber === targetSoNo))));
        });
        if (matchesSO.length > 0) {
            matchingGrns = matchesSO;
        }
    }

    // Soft fallback for PO design match
    if (po) {
        const poDesigns = (po.items || []).map(it => (it.processName || it.itemName || '').toString().trim().toLowerCase()).filter(Boolean);
        if (po.designNumber) poDesigns.push(po.designNumber.toString().trim().toLowerCase());
        if (po.design) poDesigns.push(po.design.toString().trim().toLowerCase());
        if (po.designNo) poDesigns.push(po.designNo.toString().trim().toLowerCase());

        if (poDesigns.length > 0) {
            const matchesDesign = matchingGrns.filter(g => {
                const grnDesign = (g.designNumber || g.fabricType || '').toString().trim().toLowerCase();
                const grnLinkedSo = (db.salesOrders || []).find(so => 
                    so.id === g.soRefId || 
                    (so.number && so.number === g.soRefId) || 
                    so.id === g.linked_so_id || 
                    (so.number && so.number === g.linked_so_number) ||
                    (g.soLinks && g.soLinks.some(link => link === so.id || (link && link.soId === so.id)))
                );
                const grnLinkedSoDesign = grnLinkedSo ? (grnLinkedSo.designNumber || grnLinkedSo.item_name || '').toString().trim().toLowerCase() : '';
                return poDesigns.some(pd => 
                    (grnDesign && (grnDesign.includes(pd) || pd.includes(grnDesign))) ||
                    (grnLinkedSoDesign && (grnLinkedSoDesign.includes(pd) || pd.includes(grnLinkedSoDesign)))
                );
            });
            if (matchesDesign.length > 0) {
                matchingGrns = matchesDesign;
            }
        }
    }

    // Ensure currently linked GRNs are included in the dropdown options
    if (currentOutwardLinks.length > 0) {
        currentOutwardLinks.forEach(link => {
            const linkedGrn = (db.grns || []).find(g => g.id === link.grnRefId);
            if (linkedGrn && !matchingGrns.some(g => g.id === linkedGrn.id)) {
                matchingGrns.unshift(linkedGrn);
            }
        });
    }
    
    if (matchingGrns.length === 0) {
        challanSel.innerHTML = '<option value="">-- No Challans Available --</option>';
    } else {
        challanSel.innerHTML = '<option value="">-- Select Challan No --</option>';
        matchingGrns.forEach(g => {
            const opt = document.createElement('option');
            opt.value = g.id;
            let originalQty = 0;
            if (editId) {
                const existingOut = db.outwards.find(o => o.id === editId);
                if (existingOut) {
                    if (existingOut.grnLinks) {
                        const match = existingOut.grnLinks.find(link => link.grnRefId === g.id);
                        if (match) originalQty = match.qty;
                    } else if (existingOut.grnRefId === g.id) {
                        originalQty = existingOut.qty;
                    }
                }
            }
            const bal = g.qty - (g.issuedMeters || 0) + originalQty;
            const linkedSo = (db.salesOrders || []).find(so => 
                so.id === g.soRefId || 
                (so.number && so.number === g.soRefId) || 
                so.id === g.linked_so_id || 
                (so.number && so.number === g.linked_so_number) ||
                (g.soLinks && g.soLinks.includes(so.id))
            );
            const itemName = (linkedSo ? (linkedSo.designNumber || (linkedSo.items?.[0] ? ((db.items || []).find(x => x.id === linkedSo.items[0].itemId)?.name || linkedSo.item_name) : linkedSo.item_name)) : '') || g.designNumber || g.fabricType || 'Plain Fabric';
            const grnRate = g.rate || (g.packageSlips && g.packageSlips[0] && g.packageSlips[0].rate) || (linkedSo && linkedSo.rate) || 0;
            const rateStr = grnRate ? `, Rate: �${parseFloat(grnRate).toFixed(2)}` : '';
            const partyNameStr = (g.customerName || g.vendorName) ? ` [${g.customerName || g.vendorName}]` : '';
            opt.textContent = `${g.partyDocNo || 'Challan (No No)'}${partyNameStr} (GRN: ${g.grnNo || g.number}, Bal: ${bal.toFixed(2)} m, Design: ${itemName}${rateStr})`;
            challanSel.appendChild(opt);
        });
        if (currentOutwardLinks.length > 0) {
            const firstGrnId = currentOutwardLinks[0].grnRefId;
            if (firstGrnId && Array.from(challanSel.options).some(o => o.value === firstGrnId)) {
                challanSel.value = firstGrnId;
            }
        }
    }
    reinitSearchableSelect(challanSel);
    window.updateOutwardEmbroideryItemSelects();
    window.updateOutwardFabricIssues();

    const isEmbroidery = (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered');
    const fabricUsedContainer = document.getElementById('outward-fabric-used-container');
    if (fabricUsedContainer) {
        const selectedSoId = document.getElementById('outward-linked-so')?.value || '';
        const linkedSO = db.salesOrders ? db.salesOrders.find(s => s.id === selectedSoId) : null;
        const isWithMaterial = linkedSO && linkedSO.materialType === 'with_material';
        fabricUsedContainer.style.display = (isEmbroidery && !isWithMaterial) ? 'block' : 'none';
        
        // If it is with_material, clear out any linked challans from the display list since they aren't needed
        if (isWithMaterial) {
            const outFabricUsedBody = document.getElementById('outward-fabric-used-body');
            if (outFabricUsedBody) {
                outFabricUsedBody.innerHTML = '<tr><td colspan="7" class="empty-row" style="text-align:center; padding:8px; color:var(--text-muted);">No challans linked.</td></tr>';
            }
        }
    }
    } finally {
        window.isOutwardCustomerChanging = false;
    }
};

window.updateOutwardEmbroideryItemSelects = function() {
    const selects = document.querySelectorAll('.outward-emb-item-name');
    if (selects.length === 0) return;

    const soId = document.getElementById('outward-linked-so')?.value || '';
    
    let candidates = [];
    const docNo = document.getElementById('outward-number')?.value || '';
    const soSelectGroup = document.getElementById('outward-linked-so-group');
    const isFiCEm = (window.outwardWizardState && 
                     outwardWizardState.type === 'fabric_issue_challan' && 
                     outwardWizardState.source === 'customer' && 
                     outwardWizardState.subType === 'embroidered') || 
                    /FI[/\-_]?C[/\-_]?EM/i.test(docNo) ||
                    (soSelectGroup && soSelectGroup.style.display !== 'none');

    if (isFiCEm) {
        if (soId) {
            const cleanSoId = String(soId).trim().toLowerCase();
            const allSalesOrders = [...(db.salesOrders || []), ...(rawDB.salesOrders || [])];
            const so = allSalesOrders.find(s => 
                String(s.id).trim().toLowerCase() === cleanSoId || 
                String(s.number).trim().toLowerCase() === cleanSoId
            );
            if (so) {
                // 1. Get from so.designId / so.item_id / so.itemId directly
                const targetDesignId = so.designId || so.item_id || so.itemId;
                if (targetDesignId) {
                    const itemObj = (db.items || []).find(x => x.id === targetDesignId);
                    if (itemObj && itemObj.name && !candidates.includes(itemObj.name)) {
                        candidates.push(itemObj.name);
                    }
                }
                // 2. Get from so.items array (with fallbacks if item is not in db.items)
                if (so.items && Array.isArray(so.items)) {
                    so.items.forEach(itemRow => {
                        const rowItemId = itemRow.itemId || itemRow.item_id || '';
                        if (rowItemId) {
                            const itemObj = (db.items || []).find(x => x.id === rowItemId);
                            if (itemObj && itemObj.name) {
                                if (!candidates.includes(itemObj.name)) {
                                    candidates.push(itemObj.name);
                                }
                            }
                        }
                        const fallbackName = itemRow.itemName || itemRow.designName || itemRow.designNumber || itemRow.processName || '';
                        if (fallbackName && !candidates.includes(fallbackName)) {
                            candidates.push(fallbackName);
                        }
                    });
                }
                // 3. Get from display string helper
                const displayStr = window.getSoDesignOrItemDisplay(so);
                if (displayStr && displayStr !== '-') {
                    displayStr.split(',').map(s => s.trim()).forEach(name => {
                        if (name && !candidates.includes(name)) {
                            candidates.push(name);
                        }
                    });
                }
                // 4. Get from so.designNumber / so.item_name
                const possibleDesignNumber = so.designNumber || so.item_name;
                if (possibleDesignNumber && !candidates.includes(possibleDesignNumber)) {
                    candidates.push(possibleDesignNumber);
                }
                // 5. Get from so.itemName
                if (so.itemName && !candidates.includes(so.itemName)) {
                    candidates.push(so.itemName);
                }
            }
        }
    } else {
        // For other types (e.g., FI/V/EM), populate with items from the selected PO
        const poId = document.getElementById('outward-po-ref')?.value || '';
        if (poId) {
            const po = (db.pos || []).find(p => p.id === poId);
            if (po && po.items) {
                po.items.forEach(itemRow => {
                    const itemName = (db.items ? db.items.find(x => x.id === itemRow.itemId)?.name : null) || itemRow.itemName || '';
                    if (itemName && !candidates.includes(itemName)) {
                        candidates.push(itemName);
                    }
                });
            }
        }
    }
    // Fallback: if candidates is empty, populate with all items from db.items
    // But DO NOT fall back to all items if isFiCEm is true and a Sales Order is selected (soId is not empty)
    // Or if other type and PO is selected (poId is not empty)
    const poId = document.getElementById('outward-po-ref')?.value || '';
    const shouldFallback = !(isFiCEm && soId) && !poId;
    if (candidates.length === 0 && shouldFallback && db.items) {
        db.items.forEach(item => {
            if (item.name && !candidates.includes(item.name)) {
                candidates.push(item.name);
            }
        });
    }
    
    selects.forEach(sel => {
        const savedVal = sel.value || sel.getAttribute('data-saved-val');
        sel.innerHTML = '<option value="">-- Select Item --</option>';
        candidates.forEach(c => {
            sel.appendChild(new Option(c, c));
        });
        
        let valToSet = savedVal;
        if ((!valToSet || !candidates.includes(valToSet)) && candidates.length > 0) {
            valToSet = candidates[0];
        }
        if (valToSet) {
            sel.value = valToSet;
        }
        if (typeof window.reinitSearchableSelect === 'function') {
            window.reinitSearchableSelect(sel);
        }
    });
};

window.addOutwardEmbroideryRow = function(initialData = null) {
    const tbody = document.getElementById('outward-embroidery-body');
    if (!tbody) return;
    
    const tr = document.createElement('tr');
    tr.className = 'outward-embroidery-row';
    
    tr.innerHTML = `
        <td style="padding: 6px 10px;"><select class="form-input outward-emb-item-name" style="width:100%; box-sizing:border-box;" onchange="window.updateOutwardFabricIssues()"></select></td>
        <td style="width: 110px; padding: 6px;"><input type="number" class="form-input outward-emb-than" placeholder="0" min="0" style="width:100%; box-sizing:border-box; text-align:center;" oninput="window.onOutwardEmbRowQtyCalc(this)"></td>
        <td style="width: 120px; padding: 6px;"><input type="number" class="form-input outward-emb-conversion" placeholder="0.00" step="0.01" min="0" style="width:100%; box-sizing:border-box; text-align:center;" oninput="window.onOutwardEmbRowQtyCalc(this)"></td>
        <td style="width: 130px; padding: 6px;"><input type="number" class="form-input outward-emb-qty" placeholder="0.00" step="0.01" min="0" style="width:100%; box-sizing:border-box; text-align:center;" oninput="window.updateOutwardFabricIssues()"></td>
        <td style="width: 50px; text-align:center; padding: 6px;"><button type="button" class="btn btn-sm btn-danger" onclick="window.removeOutwardEmbroideryRow(this)">=�</button></td>
    `;
    
    tbody.appendChild(tr);
    
    if (initialData && initialData.itemName) {
        tr.querySelector('.outward-emb-item-name').setAttribute('data-saved-val', initialData.itemName);
    }
    
    window.updateOutwardEmbroideryItemSelects();
    
    if (initialData) {
        tr.querySelector('.outward-emb-item-name').value = initialData.itemName || '';
        tr.querySelector('.outward-emb-than').value = initialData.than !== undefined ? initialData.than : '';
        tr.querySelector('.outward-emb-conversion').value = initialData.conversion !== undefined ? initialData.conversion : '';
        tr.querySelector('.outward-emb-qty').value = initialData.qty !== undefined ? initialData.qty : '';
    }
    
    const selEl = tr.querySelector('.outward-emb-item-name');
    if (selEl && typeof window.reinitSearchableSelect === 'function') {
        window.reinitSearchableSelect(selEl);
    }
    
    window.updateOutwardFabricIssues();
};

window.onOutwardEmbRowQtyCalc = function(inputEl) {
    const row = inputEl.closest('.outward-embroidery-row');
    if (!row) return;
    const than = parseFloat(row.querySelector('.outward-emb-than').value || 0);
    const conv = parseFloat(row.querySelector('.outward-emb-conversion').value || 0);
    const qtyInput = row.querySelector('.outward-emb-qty');
    if (qtyInput) {
        qtyInput.value = (than * conv).toFixed(2);
    }
    window.updateOutwardFabricIssues();
};

window.removeOutwardEmbroideryRow = function(btn) {
    const row = btn.closest('.outward-embroidery-row');
    if (row) {
        row.remove();
    }
    window.updateOutwardFabricIssues();
};

window.updateOutwardFabricIssues = function() {
    const isEmbroidery = (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered');
    if (!isEmbroidery) return;

    window.syncOutwardData();

    const selectEl = document.getElementById('outward-fabric-used-select-challan');
    if (!selectEl) return;

    selectEl.innerHTML = '<option value="">-- Select Challan No --</option>';

    const customerId = document.getElementById('outward-customer')?.value || '';
    const soId = document.getElementById('outward-linked-so')?.value || '';

    db.grns = db.grns || [];
    const plainGrns = db.grns.filter(g => {
        const isCustPlain = (g.type === 'fabric' || (g.grnNo || g.number || '').includes('C/PF')) && 
                            (g.source === 'customer' || (g.grnNo || g.number || '').includes('/C/')) && 
                            (g.subType === 'plain' || !(g.grnNo || g.number || '').includes('EM'));
        if (!isCustPlain || g.status === 'Cancelled') return false;

        const matchesCustomer = (g.customerId && g.customerId === customerId) || 
                                (g.customer_id && g.customer_id === customerId);

        let matchesSO = true;
        if (soId) {
            matchesSO = (g.soRefId && (g.soRefId === soId || g.soRefId === db.salesOrders.find(s => s.id === soId)?.number)) ||
                        (g.linked_so_id && g.linked_so_id === soId) ||
                        (g.soLinks && g.soLinks.includes(soId));
        }

        if (!matchesCustomer || !matchesSO) return false;

        // Calculate how much fabric has been consumed across all outwards (except the one currently being edited)
        let totalIssued = parseFloat(g.qty) || 0;
        let alreadyConsumed = 0;
        const currentEditId = document.getElementById('outward-edit-id')?.value || '';
        
        (db.outwards || []).forEach(out => {
            if (out.id === currentEditId) return;
            if (out.remarks && out.remarks.includes('[FABRIC_USED:')) {
                const match = out.remarks.match(/\[FABRIC_USED:(\[.*?\])\]/);
                if (match && match[1]) {
                    try {
                        const list = JSON.parse(match[1]);
                        list.forEach(row => {
                            if (row.grnId === g.id || row.issueId === g.id) {
                                alreadyConsumed += parseFloat(row.qty) || 0;
                            }
                        });
                    } catch (e) {}
                }
            }
        });

        // Also account for the current UI table values
        const uiRows = document.querySelectorAll('.outward-fabric-used-row');
        let uiConsumed = 0;
        uiRows.forEach(row => {
            if (row.getAttribute('data-grn-id') === g.id) {
                const qtyInput = row.querySelector('.outward-fabric-used-qty');
                if (qtyInput) {
                    uiConsumed += parseFloat(qtyInput.value) || 0;
                }
            }
        });

        const availableBalance = totalIssued - alreadyConsumed - uiConsumed;
        if (availableBalance <= 0.01) return false;

        g._availableBalanceDisplay = availableBalance;
        return true;
    });

    plainGrns.forEach(g => {
        const opt = document.createElement('option');
        opt.value = g.id;
        const balStr = g._availableBalanceDisplay !== undefined ? ` (Bal: ${g._availableBalanceDisplay.toFixed(2)}m)` : '';
        opt.textContent = `${g.partyDocNo || g.grnNo || g.number}${balStr} (Date: ${typeof formatDisplayDate === 'function' ? formatDisplayDate(g.date) : (g.date || '')})`;
        selectEl.appendChild(opt);
    });

    if (typeof window.reinitSearchableSelect === 'function') {
        window.reinitSearchableSelect(selectEl);
    }
};

window.addOutwardFabricUsedRow = function(rowData = null) {
    if (!rowData) return;

    const tbody = document.getElementById('outward-fabric-used-body');
    if (!tbody) return;

    const emptyRow = tbody.querySelector('.empty-row');
    if (emptyRow) {
        tbody.innerHTML = '';
    }

    const selectedGrnId = rowData.grnId || rowData.issueId || '';
    const fabType = rowData.fabricType || '';

    const matchedGrn = db.grns.find(g => g.id === selectedGrnId);
    const challanNo = matchedGrn ? (matchedGrn.partyDocNo || matchedGrn.grnNo || matchedGrn.number) : (rowData.grnNo || 'Unknown Challan');

    let totalIssued = matchedGrn ? (parseFloat(matchedGrn.qty) || 0) : (parseFloat(rowData.qty) || 0);

    let alreadyConsumed = 0;
    const currentEditId = document.getElementById('outward-edit-id')?.value || '';
    db.outwards.forEach(out => {
        if (out.id === currentEditId) return;
        if (out.remarks && out.remarks.includes('[FABRIC_USED:')) {
            const match = out.remarks.match(/\[FABRIC_USED:(\[.*?\])\]/);
            if (match && match[1]) {
                try {
                    const list = JSON.parse(match[1]);
                    list.forEach(row => {
                        if ((row.grnId === selectedGrnId || row.issueId === selectedGrnId) && row.fabricType === fabType) {
                            alreadyConsumed += parseFloat(row.qty) || 0;
                        }
                    });
                } catch (e) {
                    console.error("Error parsing Outward FABRIC_USED metadata:", e);
                }
            }
        }
    });

    const availableBalance = Math.max(0, totalIssued - alreadyConsumed);

    const tr = document.createElement('tr');
    tr.className = 'outward-fabric-used-row';
    tr.setAttribute('data-grn-id', selectedGrnId);
    tr.setAttribute('data-fabric-type', fabType);

    const thanVal = rowData.than !== undefined ? rowData.than : '';
    const convVal = rowData.conversion !== undefined ? rowData.conversion : '';
    const qtyVal = rowData.qty !== undefined ? rowData.qty : '';

    tr.innerHTML = `
        <td style="width: 160px; padding: 6px 10px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;"><strong>${challanNo}</strong></td>
        <td style="padding: 6px 10px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;"><strong>${fabType}</strong></td>
        <td style="width: 170px; padding: 6px 10px;"><span class="outward-fabric-used-balance">${availableBalance.toFixed(2)}</span> m</td>
        <td style="width: 110px; padding: 6px;"><input type="number" class="form-input outward-fabric-used-than" placeholder="0" min="0" value="${thanVal}" style="width:100%; box-sizing:border-box; text-align:center;" oninput="window.onOutwardFabricUsedRowCalc(this)"></td>
        <td style="width: 120px; padding: 6px;"><input type="number" class="form-input outward-fabric-used-conversion" placeholder="0.00" step="0.01" min="0" value="${convVal}" style="width:100%; box-sizing:border-box; text-align:center;" oninput="window.onOutwardFabricUsedRowCalc(this)"></td>
        <td style="width: 130px; padding: 6px;"><input type="number" class="form-input outward-fabric-used-qty" placeholder="0.00" step="0.01" min="0" value="${qtyVal}" style="width:100%; box-sizing:border-box; text-align:center;" oninput="window.updateOutwardFabricIssues()"></td>
        <td style="width: 50px; text-align:center; padding: 6px;"><button type="button" class="btn btn-sm btn-danger" onclick="window.removeOutwardFabricUsedRow(this)">=�</button></td>
    `;

    tbody.appendChild(tr);
};

