window.getTableColumnConfig = function(tableId) {
    const defaults = window.tableColumnDefaults[tableId] || [];
    const saved = localStorage.getItem(`table_design_${tableId}`);
    if (saved) {
        try {
            let parsed = JSON.parse(saved);
            if (tableId === 'grn') {
                parsed = parsed.filter(col => col.key !== 'status');
            }
            parsed.forEach(col => {
                if (col.key === 'itemName' && col.label && col.label.includes('Fabric')) col.label = 'Item Name';
                if (col.key === 'fabricType' && col.label && col.label.includes('Item')) col.label = 'Fabric Name';
            });
            // Merge default columns that are missing in the saved layout
            defaults.forEach(defCol => {
                if (!parsed.some(c => c.key === defCol.key)) {
                    parsed.push({
                        key: defCol.key,
                        label: defCol.label,
                        visible: defCol.defaultVisible,
                        sortable: defCol.defaultSortable
                    });
                }
            });
            return parsed;
        } catch (e) {
            console.error(e);
        }
    }
    return defaults.map(col => ({
        key: col.key,
        label: col.label,
        visible: col.defaultVisible,
        sortable: col.defaultSortable
    }));
};

window.currentDesignTableId = null;

window.openCurrentMasterGridConfig = function() {
    const masterTableMap = {
        'customers': 'customer',
        'vendors': 'vendor',
        'items': 'item',
        'bom': 'bom',
        'transporters': 'transporter',
        'units': 'unit',
        'hsn': 'hsn',
        'itemgroups': 'itemGroup',
        'vendorgroups': 'vendorGroup',
        'doctypes': 'partyDocType',
        'fabrictypes': 'fabricType',
        'packingtypes': 'packingStandard',
        'taxinames': 'taxi',
        'machines': 'machine',
        'rateagreements': 'rateagreement'
    };
    const tableId = masterTableMap[window.currentMasterSubtab] || window.currentMasterSubtab || 'customer';
    window.openTableDesignModal(tableId);
};

window.openTableDesignModal = function(tableId) {
    window.currentDesignTableId = tableId;
    const config = window.getTableColumnConfig(tableId);
    const container = document.getElementById('design-table-columns-container');
    if (!container) return;

    container.innerHTML = config.map(col => {
        return `
            <div style="display: flex; align-items: center; justify-content: space-between; padding: 10px 14px; background: rgba(79, 125, 255, 0.04); border-radius: 8px; border: 1px solid var(--border);">
                <span style="font-weight: 600; font-size: 14px;">${col.label}</span>
                <div style="display: flex; align-items: center; gap: 20px;">
                    <label style="display: flex; align-items: center; gap: 6px; cursor: pointer; font-size: 13px; user-select: none;">
                        <input type="checkbox" class="design-visible-chk" data-key="${col.key}" ${col.visible ? 'checked' : ''} onchange="window.triggerLiveTableDesignUpdate()">
                        Visible
                    </label>
                    <label style="display: flex; align-items: center; gap: 6px; cursor: pointer; font-size: 13px; user-select: none;">
                        <input type="checkbox" class="design-sortable-chk" data-key="${col.key}" ${col.sortable ? 'checked' : ''} onchange="window.triggerLiveTableDesignUpdate()">
                        � Sortable
                    </label>
                </div>
            </div>
        `;
    }).join('');

    openModal('design-table-modal');
};

window.toggleCustomerFreezeSetting = function(isFreeze) {
    localStorage.setItem('freeze_first_4_customer', isFreeze ? 'true' : 'false');
    document.querySelectorAll('#chk-cust-freeze-top, #cust-freeze-toolbar-toggle input[type="checkbox"]').forEach(chk => {
        chk.checked = isFreeze;
    });
    renderCustomerTable();
    if (typeof renderVendorTable === 'function') renderVendorTable();
};

window.toggleItemFreezeSetting = function(isFreeze) {
    localStorage.setItem('freeze_first_4_item', isFreeze ? 'true' : 'false');
    document.querySelectorAll('#chk-item-freeze-top, #item-freeze-toolbar-toggle input[type="checkbox"]').forEach(chk => {
        chk.checked = isFreeze;
    });
    if (typeof renderItemTable === 'function') renderItemTable();
};

window.renderTableByDesignId = function(tableId) {
    if (!tableId) tableId = window.currentDesignTableId;
    if (!tableId) return;

    if (tableId === 'so') { if (typeof renderSOTable === 'function') renderSOTable(); }
    else if (tableId === 'po') { if (typeof window.renderPOTable === 'function') window.renderPOTable(); }
    else if (tableId === 'grn') { if (typeof renderGRNTable === 'function') renderGRNTable(); }
    else if (tableId === 'outward') { if (typeof renderOutwardTable === 'function') renderOutwardTable(); }
    else if (tableId === 'production') { if (typeof renderProductionTable === 'function') renderProductionTable(); }
    else if (tableId === 'customer' || tableId === 'customers') { if (typeof renderCustomerTable === 'function') renderCustomerTable(); }
    else if (tableId === 'vendor' || tableId === 'vendors') { if (typeof renderVendorTable === 'function') renderVendorTable(); }
    else if (tableId === 'item' || tableId === 'items') { if (typeof renderItemTable === 'function') renderItemTable(); }
    else if (tableId === 'bom' || tableId === 'boms') { if (typeof renderBOMTable === 'function') renderBOMTable(); }
    else if (tableId === 'transporter' || tableId === 'transporters') { if (typeof renderTransporterTable === 'function') renderTransporterTable(); }
    else if (tableId === 'unit' || tableId === 'units') { if (typeof renderUnitTable === 'function') renderUnitTable(); }
    else if (tableId === 'hsn' || tableId === 'hsns' || tableId === 'hsn_codes') { if (typeof renderHSNTable === 'function') renderHSNTable(); }
    else if (tableId === 'itemGroup' || tableId === 'itemgroups') { if (typeof renderItemGroupTable === 'function') renderItemGroupTable(); }
    else if (tableId === 'vendorGroup' || tableId === 'vendorgroups') { if (typeof renderVendorGroupTable === 'function') renderVendorGroupTable(); }
    else if (tableId === 'partyDocType' || tableId === 'doctypes') { if (typeof renderDoctypeTable === 'function') renderDoctypeTable(); }
    else if (tableId === 'fabricType' || tableId === 'fabrictypes') { if (typeof renderFabrictypeTable === 'function') renderFabrictypeTable(); }
    else if (tableId === 'packingStandard' || tableId === 'packingtypes') { if (typeof renderPackingtypeTable === 'function') renderPackingtypeTable(); }
    else if (tableId === 'taxi' || tableId === 'taxinames') { if (typeof renderTaxinameTable === 'function') renderTaxinameTable(); }
    else if (tableId === 'machine' || tableId === 'machines') { if (typeof renderMachineTable === 'function') renderMachineTable(); }
    else if (tableId === 'rateagreement' || tableId === 'rateagreements') { if (typeof renderRateAgreementTable === 'function') renderRateAgreementTable(); }
};

window.triggerLiveTableDesignUpdate = function(tableId) {
    if (!tableId) tableId = window.currentDesignTableId;
    if (!tableId) return;

    const config = window.getTableColumnConfig(tableId);
    const container = document.getElementById('design-table-columns-container');
    if (!container) return;

    const visibleChks = container.querySelectorAll('.design-visible-chk');
    const sortableChks = container.querySelectorAll('.design-sortable-chk');

    visibleChks.forEach(chk => {
        const key = chk.getAttribute('data-key');
        const col = config.find(c => c.key === key);
        if (col) col.visible = chk.checked;
    });

    sortableChks.forEach(chk => {
        const key = chk.getAttribute('data-key');
        const col = config.find(c => c.key === key);
        if (col) col.sortable = chk.checked;
    });

    localStorage.setItem(`table_design_${tableId}`, JSON.stringify(config));
    window.renderTableByDesignId(tableId);
};

window.saveTableDesign = function() {
    const tableId = window.currentDesignTableId;
    if (!tableId) return;

    window.triggerLiveTableDesignUpdate(tableId);
    closeModal('design-table-modal');
    showToast('Grid configuration saved successfully!', 'success');
};

window.resetTableDesignToDefault = function() {
    const tableId = window.currentDesignTableId;
    if (!tableId) return;

    localStorage.removeItem(`table_design_${tableId}`);
    window.openTableDesignModal(tableId);
    window.renderTableByDesignId(tableId);
    showToast('Grid configuration reset to defaults', 'info');
};

window.sortTable = function(tableId, field) {
    const config = window.getTableColumnConfig(tableId);
    const col = config.find(c => c.key === field);
    if (!col || !col.sortable || !col.visible) return;

    window.tableSortConfig = window.tableSortConfig || {};
    const current = window.tableSortConfig[tableId] || { field: '', order: 'desc' };

    let nextOrder = 'asc';
    if (current.field === field) {
        nextOrder = current.order === 'asc' ? 'desc' : 'asc';
    }
    window.tableSortConfig[tableId] = { field, order: nextOrder };

    // Sync back to masterSortState
    window.masterSortState = window.masterSortState || {};
    if (tableId === 'customer') {
        window.masterSortState.customers = { col: field, dir: nextOrder };
    } else if (tableId === 'vendor') {
        window.masterSortState.vendors = { col: field, dir: nextOrder };
    } else if (tableId === 'bom') {
        window.masterSortState.boms = { col: field, dir: nextOrder };
    }

    if (tableId === 'so') renderSOTable();
    else if (tableId === 'po') if (typeof window.renderPOTable === 'function') window.renderPOTable();
    else if (tableId === 'grn') renderGRNTable();
    else if (tableId === 'outward') renderOutwardTable();
    else if (tableId === 'production') renderProductionTable();
    else if (tableId === 'customer') renderCustomerTable();
    else if (tableId === 'vendor') renderVendorTable();
    else if (tableId === 'item') renderItemTable();
    else if (tableId === 'bom') renderBOMTable();
    else if (tableId === 'transporter') renderTransporterTable();
    else if (tableId === 'unit') renderUnitTable();
    else if (tableId === 'hsn') renderHSNTable();
    else if (tableId === 'itemGroup') renderItemGroupTable();
    else if (tableId === 'vendorGroup') renderVendorGroupTable();
    else if (tableId === 'partyDocType') renderDoctypeTable();
    else if (tableId === 'fabricType') renderFabrictypeTable();
    else if (tableId === 'packingStandard') renderPackingtypeTable();
    else if (tableId === 'taxi') renderTaxinameTable();
    else if (tableId === 'machine') renderMachineTable();
    else if (tableId === 'rateagreement') renderRateAgreementTable();
};

window.renderDynamicHeader = function(tableId, defaultTheadId, defaultHeaders) {
    const thead = document.getElementById(defaultTheadId);
    if (!thead) return;

    const config = window.getTableColumnConfig(tableId);
    window.tableSortConfig = window.tableSortConfig || {};
    const currentSort = window.tableSortConfig[tableId] || { field: '', order: '' };

    const isTxTable = ['so', 'po', 'grn', 'outward', 'production'].includes(tableId);

    const tableEl = thead.closest('table');
    if (tableEl) {
        if (!isTxTable && !['customer', 'customers', 'vendor', 'vendors', 'item', 'items', 'fabricType', 'packingStandard', 'partyDocType', 'taxi', 'unit', 'hsn', 'itemGroup', 'vendorGroup', 'machine'].includes(tableId)) {
            tableEl.classList.add('freeze-first-3');
        } else {
            tableEl.classList.remove('freeze-first-3');
        }
    }

    // Select-all checkbox key mapping
    let chkHtml = '';
    if (tableId === 'so') {
        chkHtml = `<th><input type="checkbox" id="so-select-all" onclick="toggleSelectAllRows(this, 'so')"></th>`;
    } else if (tableId === 'po') {
        chkHtml = `<th><input type="checkbox" id="po-select-all" onclick="toggleSelectAllRows(this, 'po')"></th>`;
    } else if (tableId === 'grn') {
        chkHtml = `<th><input type="checkbox" id="grn-select-all" class="chk-select-all-grn" onclick="toggleSelectAllRows(this, 'grn')"></th>`;
    } else if (tableId === 'outward') {
        chkHtml = `<th><input type="checkbox" id="outward-select-all" class="chk-select-all-outward" onclick="toggleSelectAllRows(this, 'outward')"></th>`;
    } else if (tableId === 'production') {
        chkHtml = `<th><input type="checkbox" id="production-select-all" class="chk-select-all-production" onclick="toggleSelectAllRows(this, 'production')"></th>`;
    } else {
        chkHtml = `<th><input type="checkbox" class="chk-select-all-mst" onclick="toggleSelectAllRows(this, 'mst')"></th>`;
    }

    let colsHtml = config.map(col => {
        if (col.visible === false) return '';
        
        // Custom override for In-house PO / Outward
        if (tableId === 'po' && window.currentPoWizardType === 'inhouse' && ['rate', 'totalValue', 'deliveryDate'].includes(col.key)) {
            return '';
        }
        if (tableId === 'outward' && (window.outwardWizardState || outwardWizardState)?.type === 'inhouse' && (col.key === 'vehicleNo' || col.key === 'partyName')) {
            return '';
        }

        let label = col.label;
        if (tableId === 'grn' && col.key === 'customerName') {
            const isCustomer = (grnWizardState.type === 'fabric' && grnWizardState.source === 'customer');
            label = isCustomer ? 'CUSTOMER NAME' : 'VENDOR NAME';
        }
        let style = '';
        let onclick = '';
        
        if (col.sortable !== false) {
            style = 'cursor: pointer; user-select: none; color: var(--accent-blue);';
            onclick = `onclick="window.sortTable('${tableId}', '${col.key}')"`;
            if (currentSort.field === col.key) {
                label += currentSort.order === 'asc' ? ' &#9650;' : ' &#9660;';
            } else {
                label += ' &#8645;';
            }
        }
        
        let extraClass = (col.key === 'itemName' ? 'cell-item-name col-itemName' : (col.key === 'fabricType' ? 'cell-fabric-name col-fabricType' : ''));
        return `<th class="${extraClass}" style="${style}" ${onclick}>${label}</th>`;
    }).filter(Boolean).join('');

    thead.innerHTML = `<tr>
        ${chkHtml}
        ${!isTxTable ? '<th>Sr.</th>' : ''}
        ${colsHtml}
        <th>Actions</th>
    </tr>`;
};

window.getIssuedPackagesForGRN = function(grnId, excludeOutwardId = null) {
    const issued = [];
    const outwards = db.outwards || [];
    outwards.forEach(out => {
        if (excludeOutwardId && out.id === excludeOutwardId) return;
        
        // Skip customer embroidered outward challans from the package clash check,
        // because their packages are entered as raw rows and not selected from the checklist!
        const state = parseOutwardWizardState(out);
        if (state.type === 'fabric_issue_challan' && state.source === 'customer' && state.subType === 'embroidered') {
            return;
        }

        if (out.dispatchedPackages) {
            out.dispatchedPackages.forEach(pkg => {
                if (pkg.grnId === grnId) {
                    issued.push(`${pkg.slipIndex}-${pkg.packageIndex}`);
                }
            });
        }
    });
    return issued;
};

window.updateOutwardPackagesList = function(grnId) {
    // 1. Remove all packages for this grnId from currentOutwardPackages
    currentOutwardPackages = currentOutwardPackages.filter(p => p.grnId !== grnId);

    // 2. Add currently checked original packages from the DOM grid
    const checkboxes = document.querySelectorAll(`.outward-pkg-checkbox[data-grn-id="${grnId}"]`);
    checkboxes.forEach(cb => {
        if (cb.checked) {
            const sIdx = parseInt(cb.getAttribute('data-slip-idx'));
            const pIdx = parseInt(cb.getAttribute('data-pkg-idx'));
            const qty = parseFloat(cb.getAttribute('data-qty')) || 0;
            currentOutwardPackages.push({
                grnId,
                slipIndex: sIdx,
                packageIndex: pIdx,
                qty,
                convertedDone: false
            });
        }
    });

    // 3. Add packages from checked/dispatched converted batches
    const batches = window.grnConvertedLog[grnId] || [];
    batches.forEach((batch, bIdx) => {
        batch.items.forEach((it, itIdx) => {
            if (it.dispatched !== false) {
                currentOutwardPackages.push({
                    grnId,
                    slipIndex: it.sIdx !== undefined ? it.sIdx : batch.slipIdx,
                    packageIndex: it.pIdx !== undefined ? it.pIdx : -1,
                    qty: it.qty,
                    convertedPackingType: batch.targetType,
                    convertedDone: true,
                    label: it.label || `${batch.targetType} ${itIdx + 1}`,
                    packageNo: it.packageNo || '',
                    originalItems: batch.originalItems || []
                });
            }
        });
    });

    // 4. Update the qty for this GRN link in currentOutwardLinks
    const link = currentOutwardLinks.find(l => l.grnRefId === grnId);
    if (link) {
        link.qty = currentOutwardPackages.filter(p => p.grnId === grnId).reduce((s, p) => s + p.qty, 0);
    }
    const inputEl = document.querySelector(`.outward-link-issue-qty[data-grn-id="${grnId}"]`);
    if (inputEl) inputEl.value = (link ? link.qty : 0).toFixed(2);

    window.calcOutwardTotalMeters();
};

window.onOutwardPackageToggle = function(grnId) {
    window.updateOutwardPackagesList(grnId);
    window.renderOutwardFormGRNLinks();
};

window.onOutwardBatchToggle = function(grnId, bIdx, cb) {
    if (!window.grnConvertedLog[grnId]) return;
    const batch = window.grnConvertedLog[grnId][bIdx];
    if (batch) {
        batch.dispatched = cb.checked;
        batch.items.forEach(it => {
            it.dispatched = cb.checked;
        });
    }
    window.updateOutwardPackagesList(grnId);
    window.renderOutwardFormGRNLinks();
};

window.onOutwardBatchItemToggle = function(grnId, bIdx, itIdx, cb) {
    if (!window.grnConvertedLog[grnId]) return;
    const batch = window.grnConvertedLog[grnId][bIdx];
    if (batch && batch.items[itIdx]) {
        batch.items[itIdx].dispatched = cb.checked;
        const anyChecked = batch.items.some(it => it.dispatched !== false);
        batch.dispatched = anyChecked;
    }
    window.updateOutwardPackagesList(grnId);
    window.renderOutwardFormGRNLinks();
};

window.renderConvertedLogBatches = function(grnId) {
    const converterId = `packing-converted-log-${grnId}`;
    let logDiv = document.getElementById(converterId);
    if (!logDiv) {
        const converterBar = document.querySelector(`.packing-converter-container[data-grn-id="${grnId}"]`);
        if (converterBar) {
            logDiv = document.createElement('div');
            logDiv.id = converterId;
            logDiv.style.cssText = 'margin-top:14px; padding:14px; border-radius:10px; background:rgba(34,197,94,0.04); border:1px solid rgba(34,197,94,0.25);';
            converterBar.insertAdjacentElement('afterend', logDiv);
        }
    }
    if (!logDiv) return;

    const convertedBatches = window.grnConvertedLog[grnId] || [];
    if (convertedBatches.length === 0) {
        logDiv.remove();
        return;
    }

    let batchesHtml = '';
    convertedBatches.forEach((batch, bIdx) => {
        const batchTotal = batch.items.reduce((s, it) => s + it.qty, 0);
        const tableRows = batch.items.map((it, i) => `
            <tr style="border-bottom:1px solid rgba(34,197,94,0.15);">
                <td style="padding:6px 10px; text-align:center; width:30px;">
                    <input type="checkbox" class="outward-batch-item-checkbox" data-grn-id="${grnId}" data-batch-idx="${bIdx}" data-item-idx="${i}" ${it.dispatched !== false ? 'checked' : ''} onchange="window.onOutwardBatchItemToggle('${grnId}', ${bIdx}, ${i}, this)" style="cursor:pointer; width:13px; height:13px; margin:0;">
                </td>
                <td style="padding:6px 10px; font-size:11px; color:var(--text-muted); text-align:center; width:36px;">${i + 1}</td>
                <td style="padding:6px 10px; font-size:11px; font-weight:600;">${it.label}${it.packageNo ? ` <span style="color:var(--text-muted); font-weight:400;">(#${it.packageNo})</span>` : ''}</td>
                <td style="padding:6px 10px; font-size:11px; color:var(--text-secondary);">${it.slipType}${it.slipColor ? ` - ${it.slipColor}` : ''}</td>
                <td style="padding:6px 10px; font-size:11px; color:var(--accent-blue); font-weight:700; text-align:right;">${it.qty} m</td>
                <td style="padding:6px 10px; text-align:center;">
                    <span style="background:#16a34a; color:white; padding:2px 8px; border-radius:4px; font-size:10px; font-weight:700; white-space:nowrap;">&rarr; ${batch.targetType}</span>
                </td>
            </tr>`).join('');

        batchesHtml += `
            <div style="margin-bottom:14px;" data-batch-idx="${bIdx}">
                <div style="display:flex; align-items:center; gap:8px; margin-bottom:6px;">
                    <span style="font-size:11px; color:#15803d; font-weight:600; white-space:nowrap;">Converted Package Name:</span>
                    <input type="text" value="${batch.name || `${batch.targetType} ${bIdx + 1}`}"
                        style="font-size:11px; font-weight:600; color:#15803d; background:transparent; border:none; border-bottom:1px dashed rgba(34,197,94,0.4); outline:none; padding:1px 4px; width:200px; cursor:text;"
                        onchange="if(window.grnConvertedLog['${grnId}'] && window.grnConvertedLog['${grnId}'][${bIdx}]) window.grnConvertedLog['${grnId}'][${bIdx}].name=this.value;"
                        placeholder="${batch.targetType} Name...">
                    <span style="font-size:10px; color:var(--text-muted);">(${batch.items.length} original pkg${batch.items.length > 1 ? 's' : ''}, ${batchTotal.toFixed(2)} m total)</span>
                    <button type="button" onclick="window.deleteConvertedBatch('${grnId}', ${bIdx}, this)"
                        style="margin-left:auto; background:rgba(239,68,68,0.1); color:#dc2626; border:1px solid rgba(239,68,68,0.3); border-radius:5px; padding:2px 10px; font-size:10px; font-weight:600; cursor:pointer; white-space:nowrap;"
                        onmouseover="this.style.background='rgba(239,68,68,0.22)'" onmouseout="this.style.background='rgba(239,68,68,0.1)'">Revert</button>
                </div>
                <div style="border-radius:8px; overflow:hidden; border:1px solid rgba(34,197,94,0.2);">
                    <table style="width:100%; border-collapse:collapse;">
                        <thead>
                            <tr style="background:rgba(34,197,94,0.12);">
                                <th style="padding:6px 10px; text-align:center; font-size:10px; color:#15803d; font-weight:700; width:30px;">Select</th>
                                <th style="padding:6px 10px; text-align:center; font-size:10px; color:#15803d; font-weight:700; width:36px;">#</th>
                                <th style="padding:6px 10px; text-align:left; font-size:10px; color:#15803d; font-weight:700;">Package</th>
                                <th style="padding:6px 10px; text-align:left; font-size:10px; color:#15803d; font-weight:700;">Fabric / Color</th>
                                <th style="padding:6px 10px; text-align:right; font-size:10px; color:#15803d; font-weight:700;">Qty (m)</th>
                                <th style="padding:6px 10px; text-align:center; font-size:10px; color:#15803d; font-weight:700;">Converted To</th>
                            </tr>
                        </thead>
                        <tbody style="background:rgba(255,255,255,0.02);">${tableRows}</tbody>
                    </table>
                </div>
            </div>`;
    });

    logDiv.innerHTML = `
        <div style="font-size:12px; font-weight:700; color:#15803d; margin-bottom:12px; display:flex; align-items:center; gap:6px;">
            <span></span> Converted Packages
        </div>
        <div id="${converterId}-batches">${batchesHtml}</div>`;
};

window.convertSelectedPackagesPackingType = function(grnId, sIdx) {
    const select = document.getElementById(`convert-packing-type-select-${grnId}-${sIdx}`);
    if (!select) return;
    const targetType = select.value;

    const grn = db.grns.find(g => g.id === grnId);
    if (!grn) return;

    // Collect currently checked boxes for this GRN and specific slip
    const checkboxes = document.querySelectorAll(`.outward-pkg-checkbox[data-grn-id="${grnId}"][data-slip-idx="${sIdx}"]:checked`);
    if (checkboxes.length === 0) {
        showToast('Please select at least one package in this slip to convert', 'warning');
        return;
    }

    const slips = (grn.packageSlips && grn.packageSlips.length > 0) ? grn.packageSlips : [{
        fabricType: grn.fabricType || 'Plain Fabric',
        color: grn.color || '-',
        packingType: grn.packingType || 'Roll',
        packages: [{ label: `${grn.packingType || 'Roll'} 1`, packageNo: '', qty: grn.qty }]
    }];

    const originalItems = [];
    let totalQty = 0;
    checkboxes.forEach(cb => {
        const pIdx = parseInt(cb.getAttribute('data-pkg-idx'));
        const qty  = parseFloat(cb.getAttribute('data-qty') || 0);
        const slip = slips[sIdx];
        const pkg  = slip && slip.packages ? slip.packages[pIdx] : null;

        originalItems.push({
            sIdx, pIdx,
            label     : pkg ? pkg.label : `Pkg ${pIdx + 1}`,
            packageNo : pkg ? (pkg.packageNo || '') : '',
            qty,
            slipType  : slip ? (slip.fabricType || '') : '',
            slipColor : slip ? (slip.color || '') : ''
        });
        totalQty += qty;
    });

    // Create and show conversion modal
    let modal = document.getElementById('packing-conversion-dialog-modal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'packing-conversion-dialog-modal';
        modal.className = 'modal-overlay';
        modal.setAttribute('style', 'position:fixed; z-index:100000; left:0; top:0; width:100vw; height:100vh; background:rgba(0,0,0,0.5); display:flex; justify-content:center; align-items:center;');
        document.body.appendChild(modal);
    }

    const slip = slips[sIdx] || {};
    const sourcePackingType = (slip.packingType || 'Roll').toUpperCase();
    const isBaleTarget = targetType.toUpperCase() === 'BALE';

    modal.innerHTML = `
        <div class="card" style="width:${isBaleTarget ? '680px' : '480px'}; max-height:85vh; background:var(--bg-primary); border-radius:12px; box-shadow:0 10px 25px rgba(0,0,0,0.15); border:1px solid var(--border); overflow:hidden; display:flex; flex-direction:column; padding:20px; animation: modalFadeIn 0.2s;">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:15px; border-bottom:1px solid var(--border); padding-bottom:10px;">
                <h3 style="margin:0; font-size:14px; font-weight:700; color:var(--text-primary); font-family: 'Outfit', sans-serif;">= Package Conversion</h3>
                <span style="font-size:20px; cursor:pointer; color:var(--text-secondary);" onclick="document.getElementById('packing-conversion-dialog-modal').style.display='none'">&times;</span>
            </div>
            
            <div style="overflow-y:auto; flex:1; display:flex; flex-direction:column; gap:14px; padding-right:4px;">
                <!-- Existing Selected Details -->
                <div style="background:var(--bg-input); padding:10px; border-radius:8px; border:1px solid var(--border); font-size:11px;">
                    <div style="font-weight:700; color:var(--text-secondary); margin-bottom:4px;">Selected Original Packages (${sourcePackingType}):</div>
                    <div style="color:var(--text-primary); max-height:100px; overflow-y:auto; line-height:1.6;">
                        ${originalItems.map(item => `� ${item.label}${item.packageNo ? ` (#${item.packageNo})` : ''}: <strong>${item.qty.toFixed(2)} m</strong>`).join('<br>')}
                    </div>
                    <div style="margin-top:6px; border-top:1px solid var(--border); padding-top:6px; font-weight:700;">
                        Total Selected Quantity: <span style="color:var(--accent-blue);">${totalQty.toFixed(2)} m</span>
                    </div>
                </div>

                <!-- Conversion Requirement -->
                <div>
                    <label style="display:block; font-size:11px; font-weight:700; color:var(--text-secondary); margin-bottom:6px;">Conversion Required:</label>
                    <div style="display:flex; align-items:center; gap:8px; font-size:12px;">
                        <span>Convert to</span>
                        <input type="number" id="conversion-count-input" value="1" min="1" max="100" 
                            style="width:60px; padding:4px 8px; border:1px solid var(--border); border-radius:6px; background:var(--bg-input); color:var(--text-primary); font-weight:700; text-align:center;"
                            onchange="window.updateConversionDialogRows(${totalQty}, '${targetType}')"
                            oninput="window.updateConversionDialogRows(${totalQty}, '${targetType}')">
                        <strong style="color:var(--accent-blue); text-transform:uppercase;">${targetType}</strong>
                    </div>
                </div>

                <!-- Empty Columns / Dynamic Rows -->
                <div id="conversion-dialog-rows-wrapper">
                    <div id="conversion-dialog-vertical-header" style="display:grid; grid-template-columns:1.5fr 1fr 1fr; gap:8px; font-size:10px; font-weight:700; color:var(--text-muted); text-transform:uppercase; margin-bottom:6px; padding-bottom:4px; border-bottom:1px solid var(--border);">
                        <div>Package Label</div>
                        <div>Package No (Optional)</div>
                        <div style="text-align:right;">Quantity (m)</div>
                    </div>
                    <div id="conversion-dialog-rows-container" style="display:flex; flex-direction:column; gap:6px;">
                        <!-- Rows rendered dynamically -->
                    </div>
                </div>

                <!-- Validation Status -->
                <div style="margin-top:4px; padding:8px; border-radius:8px; font-size:11px; font-weight:600; display:flex; align-items:center; justify-content:space-between; background:rgba(0,0,0,0.05); border:1px solid var(--border);">
                    <div>Entered: <span id="conv-entered-qty">0.00</span> m</div>
                    <div id="conv-validation-warning" style="color:var(--accent-red); display:none;">� Sum must equal ${totalQty.toFixed(2)} m</div>
                    <div id="conv-validation-ok" style="color:#15803d;"><span style="color:#22c55e;"></span> Match</div>
                </div>
            </div>

            <!-- Action Buttons -->
            <div style="display:flex; justify-content:flex-end; gap:10px; margin-top:15px; border-top:1px solid var(--border); padding-top:10px;">
                <button type="button" class="btn btn-secondary" style="font-size:11px; padding:6px 14px;" onclick="document.getElementById('packing-conversion-dialog-modal').style.display='none'">Cancel</button>
                <button type="button" id="conv-apply-btn" class="btn btn-primary" style="font-size:11px; padding:6px 14px;" data-total-qty="${totalQty}" onclick="window.executePackingConversion('${grnId}', ${sIdx}, '${targetType}', ${JSON.stringify(originalItems).replace(/"/g, '&quot;')}, ${totalQty})">Apply</button>
            </div>
        </div>
    `;

    modal.style.display = 'flex';
    window.updateConversionDialogRows(totalQty, targetType);
};

window.updateConversionDialogRows = function(totalQty, targetType) {
    const countInput = document.getElementById('conversion-count-input');
    const container = document.getElementById('conversion-dialog-rows-container');
    const headerEl = document.getElementById('conversion-dialog-vertical-header');
    if (!countInput || !container) return;

    let count = parseInt(countInput.value) || 1;
    if (count < 1) count = 1;
    if (count > 100) count = 100;

    const avgQty = parseFloat((totalQty / count).toFixed(2));

    if (targetType.toUpperCase() === 'BALE') {
        if (headerEl) headerEl.style.display = 'none';
        
        let headerCells = `<th>Bale No / ID</th>`;
        let idInputCells = `<td><strong>Enter ID/No</strong></td>`;
        
        for (let colIdx = 0; colIdx < count; colIdx++) {
            headerCells += `<th style="text-align:center; min-width:120px;">Bale ${colIdx + 1}</th>`;
            idInputCells += `<td><input type="text" class="form-input conv-grid-pkg-id" data-col="${colIdx}" value="" placeholder="e.g. ID-${colIdx + 1}" style="width:100%; text-align:center; font-size:11px; padding:4px 8px; border:1px solid var(--border); border-radius:6px; background:var(--bg-input); color:var(--text-primary);"></td>`;
        }
        
        let qtyRowsHtml = '';
        const numQtyRows = 4;
        for (let rowIdx = 0; rowIdx < numQtyRows; rowIdx++) {
            qtyRowsHtml += `<tr class="conv-grid-qty-row"><td><strong>Qty ${rowIdx + 1}</strong></td>`;
            for (let colIdx = 0; colIdx < count; colIdx++) {
                let val = '';
                if (rowIdx === 0) {
                    if (colIdx === count - 1) {
                        val = (totalQty - (avgQty * (count - 1))).toFixed(2);
                    } else {
                        val = avgQty.toFixed(2);
                    }
                }
                qtyRowsHtml += `<td><input type="number" class="form-input conv-grid-qty-input" data-col="${colIdx}" data-row="${rowIdx}" value="${val}" placeholder="0.00" step="0.01" oninput="window.calculateConversionColumnTotals(${totalQty})" style="width:100%; text-align:center; font-size:11px; padding:4px 8px; border:1px solid var(--border); border-radius:6px; background:var(--bg-input); color:var(--text-primary);"></td>`;
            }
            qtyRowsHtml += `</tr>`;
        }
        
        let footerCells = `<td><strong>Total Qty</strong></td>`;
        for (let colIdx = 0; colIdx < count; colIdx++) {
            footerCells += `<td style="text-align:center; font-weight:700;"><span class="grn-column-total conv-column-total" data-col="${colIdx}">0.00</span></td>`;
        }
        
        container.innerHTML = `
            <div style="border:1px solid var(--border); border-radius:8px; background:var(--bg-card); max-height:280px; overflow:auto !important; margin-bottom:12px; position:relative; width:100%;">
                <table class="data-table grid-spreadsheet-table conversion-grid-spreadsheet-table" style="width:100%; border-collapse:collapse;">
                    <thead style="position:sticky; top:0; background:var(--bg-input); z-index:10; box-shadow:0 1px 2px rgba(0,0,0,0.15);">
                        <tr>${headerCells}</tr>
                    </thead>
                    <tbody>
                        <tr class="conv-grid-id-row" style="position:sticky; top:39px; background:var(--bg-input); z-index:9; box-shadow:0 1px 2px rgba(0,0,0,0.15);">${idInputCells}</tr>
                        ${qtyRowsHtml}
                        <tr class="conv-grid-total-row" style="position:sticky; bottom:0; background:var(--bg-input); z-index:10; font-weight:bold; border-top:2px solid var(--border); box-shadow:0 -1px 2px rgba(0,0,0,0.15);">${footerCells}</tr>
                    </tbody>
                </table>
            </div>
            <div style="margin-top:10px; display:flex; justify-content:flex-end; width:100%;">
                <button type="button" class="btn btn-sm btn-secondary" onclick="window.addConversionGridQtyRow()">� Add Qty Row</button>
            </div>
        `;
        window.calculateConversionColumnTotals(totalQty);
    } else {
        if (headerEl) headerEl.style.display = 'grid';
        let rowsHtml = '';
        for (let i = 0; i < count; i++) {
            let rowQty = avgQty;
            if (i === count - 1) {
                rowQty = parseFloat((totalQty - (avgQty * (count - 1))).toFixed(2));
            }

            rowsHtml += `
                <div style="display:grid; grid-template-columns:1.5fr 1fr 1fr; gap:8px; align-items:center;">
                    <input type="text" class="conv-row-label" value="${targetType} ${i + 1}" 
                        style="font-size:11px; padding:4px 8px; border:1px solid var(--border); border-radius:6px; background:var(--bg-input); color:var(--text-primary); width:100%; box-sizing:border-box;">
                    <input type="text" class="conv-row-no" placeholder="e.g. ${i + 1}"
                        style="font-size:11px; padding:4px 8px; border:1px solid var(--border); border-radius:6px; background:var(--bg-input); color:var(--text-primary); width:100%; box-sizing:border-box;">
                    <input type="number" step="0.01" class="conv-row-qty" value="${rowQty.toFixed(2)}"
                        style="font-size:11px; padding:4px 8px; border:1px solid var(--border); border-radius:6px; background:var(--bg-input); color:var(--text-primary); width:100%; box-sizing:border-box; text-align:right;"
                        oninput="window.validateConversionSum(${totalQty})">
                </div>
            `;
        }
        container.innerHTML = rowsHtml;
        window.validateConversionSum(totalQty);
    }
};

window.addConversionGridQtyRow = function() {
    const table = document.querySelector('.conversion-grid-spreadsheet-table');
    if (!table) return;
    const tbody = table.querySelector('tbody');
    const countInput = document.getElementById('conversion-count-input');
    const count = parseInt(countInput.value) || 1;
    const totalQty = parseFloat(document.getElementById('conv-apply-btn').getAttribute('data-total-qty') || 0);

    const qtyRows = tbody.querySelectorAll('.conv-grid-qty-row');
    const nextRowIdx = qtyRows.length;

    const tr = document.createElement('tr');
    tr.className = 'conv-grid-qty-row';
    let tds = `<td><strong>Qty ${nextRowIdx + 1}</strong></td>`;
    for (let colIdx = 0; colIdx < count; colIdx++) {
        tds += `<td><input type="number" class="form-input conv-grid-qty-input" data-col="${colIdx}" data-row="${nextRowIdx}" value="" placeholder="0.00" step="0.01" oninput="window.calculateConversionColumnTotals(${totalQty})" style="width:100%; text-align:center; font-size:11px; padding:4px 8px; border:1px solid var(--border); border-radius:6px; background:var(--bg-input); color:var(--text-primary);"></td>`;
    }
    tr.innerHTML = tds;
    
    const totalRow = tbody.querySelector('.conv-grid-total-row');
    if (totalRow) {
        tbody.insertBefore(tr, totalRow);
    } else {
        tbody.appendChild(tr);
    }
};

window.calculateConversionColumnTotals = function(totalQty) {
    const table = document.querySelector('.conversion-grid-spreadsheet-table');
    if (!table) return;
    const countInput = document.getElementById('conversion-count-input');
    const count = parseInt(countInput.value) || 1;

    let overallSum = 0;
    for (let colIdx = 0; colIdx < count; colIdx++) {
        let colSum = 0;
        table.querySelectorAll(`.conv-grid-qty-input[data-col="${colIdx}"]`).forEach(input => {
            colSum += parseFloat(input.value) || 0;
        });
        const totalSpan = table.querySelector(`.conv-column-total[data-col="${colIdx}"]`);
        if (totalSpan) {
            totalSpan.textContent = colSum.toFixed(2);
        }
        overallSum += colSum;
    }

    const enteredEl = document.getElementById('conv-entered-qty');
    if (enteredEl) enteredEl.textContent = overallSum.toFixed(2);

    const diff = Math.abs(overallSum - totalQty);
    const isValid = diff < 0.02;

    const warningEl = document.getElementById('conv-validation-warning');
    const okEl = document.getElementById('conv-validation-ok');
    const applyBtn = document.getElementById('conv-apply-btn');

    if (warningEl && okEl && applyBtn) {
        if (isValid) {
            warningEl.style.display = 'none';
            okEl.style.display = 'block';
            applyBtn.disabled = false;
            applyBtn.style.opacity = '1';
            applyBtn.style.cursor = 'pointer';
        } else {
            warningEl.style.display = 'block';
            warningEl.textContent = `� Sum must equal ${totalQty.toFixed(2)} m (Diff: ${(overallSum - totalQty).toFixed(2)} m)`;
            okEl.style.display = 'none';
            applyBtn.disabled = true;
            applyBtn.style.opacity = '0.5';
            applyBtn.style.cursor = 'not-allowed';
        }
    }
};

window.validateConversionSum = function(totalQty) {
    const qtyInputs = document.querySelectorAll('.conv-row-qty');
    let sum = 0;
    qtyInputs.forEach(input => {
        sum += parseFloat(input.value) || 0;
    });

    const enteredEl = document.getElementById('conv-entered-qty');
    if (enteredEl) enteredEl.textContent = sum.toFixed(2);

    const diff = Math.abs(sum - totalQty);
    const isValid = diff < 0.02;

    const warningEl = document.getElementById('conv-validation-warning');
    const okEl = document.getElementById('conv-validation-ok');
    const applyBtn = document.getElementById('conv-apply-btn');

    if (warningEl && okEl && applyBtn) {
        if (isValid) {
            warningEl.style.display = 'none';
            okEl.style.display = 'block';
            applyBtn.disabled = false;
            applyBtn.style.opacity = '1';
            applyBtn.style.cursor = 'pointer';
        } else {
            warningEl.style.display = 'block';
            warningEl.textContent = `� Sum must equal ${totalQty.toFixed(2)} m (Diff: ${(sum - totalQty).toFixed(2)} m)`;
            okEl.style.display = 'none';
            applyBtn.disabled = true;
            applyBtn.style.opacity = '0.5';
            applyBtn.style.cursor = 'not-allowed';
        }
    }
};

window.executePackingConversion = function(grnId, sIdx, targetType, originalItems, totalQty) {
    const grn = db.grns.find(g => g.id === grnId);
    if (!grn) return;

    let sum = 0;
    const newItems = [];

    if (targetType.toUpperCase() === 'BALE') {
        const table = document.querySelector('.conversion-grid-spreadsheet-table');
        if (!table) return;
        
        const countInput = document.getElementById('conversion-count-input');
        const count = parseInt(countInput.value) || 1;
        
        for (let colIdx = 0; colIdx < count; colIdx++) {
            const colLabel = `${targetType} ${colIdx + 1}`;
            const packageNo = table.querySelector(`.conv-grid-pkg-id[data-col="${colIdx}"]`)?.value.trim() || '';
            const qtyInputs = table.querySelectorAll(`.conv-grid-qty-input[data-col="${colIdx}"]`);
            
            qtyInputs.forEach(input => {
                const qty = parseFloat(input.value) || 0;
                if (qty > 0) {
                    sum += qty;
                    newItems.push({
                        sIdx,
                        pIdx: -1,
                        label: colLabel,
                        packageNo,
                        qty,
                        slipType: originalItems[0] ? originalItems[0].slipType : '',
                        slipColor: originalItems[0] ? originalItems[0].slipColor : '',
                        dispatched: true
                    });
                }
            });
        }
    } else {
        const qtyInputs = document.querySelectorAll('.conv-row-qty');
        const labelInputs = document.querySelectorAll('.conv-row-label');
        const noInputs = document.querySelectorAll('.conv-row-no');

        qtyInputs.forEach((input, idx) => {
            const qty = parseFloat(input.value) || 0;
            const label = labelInputs[idx] ? labelInputs[idx].value.trim() : `${targetType} ${idx + 1}`;
            const packageNo = noInputs[idx] ? noInputs[idx].value.trim() : '';
            sum += qty;
            
            newItems.push({
                sIdx,
                pIdx: -1,
                label,
                packageNo,
                qty,
                slipType: originalItems[0] ? originalItems[0].slipType : '',
                slipColor: originalItems[0] ? originalItems[0].slipColor : '',
                dispatched: true
            });
        });
    }

    const diff = Math.abs(sum - totalQty);
    if (diff >= 0.02) {
        showToast(`Total quantity must equal ${totalQty.toFixed(2)} m`, 'warning');
        return;
    }

    // Hide the selected packages from the DOM
    const checkboxes = document.querySelectorAll(`.outward-pkg-checkbox[data-grn-id="${grnId}"][data-slip-idx="${sIdx}"]:checked`);
    checkboxes.forEach(cb => {
        const labelEl = cb.closest('label');
        if (labelEl) labelEl.remove();
    });

    if (!window.grnConvertedLog[grnId]) window.grnConvertedLog[grnId] = [];
    window.grnConvertedLog[grnId].push({
        targetType,
        slipIdx: sIdx,
        originalItems,
        items: newItems,
        name: newItems.length === 1 ? newItems[0].label : `Batch ${window.grnConvertedLog[grnId].length + 1}`,
        dispatched: true
    });

    // Close modal
    const modal = document.getElementById('packing-conversion-dialog-modal');
    if (modal) modal.style.display = 'none';

    window.updateOutwardPackagesList(grnId);
    window.renderOutwardFormGRNLinks();
    showToast(`Converted selected packages into ${newItems.length} ${targetType}(s)`, 'success');
};

window.toggleSelectAllPackingType = function(grnId, packingType, isChecked) {
    const grn = db.grns.find(g => g.id === grnId);
    if (!grn) return;
    
    const slips = (grn.packageSlips && grn.packageSlips.length > 0) ? grn.packageSlips : [{
        fabricType: grn.fabricType || 'Plain Fabric',
        color: grn.color || '-',
        packingType: grn.packingType || 'Roll'
    }];
    
    const checkboxes = document.querySelectorAll(`.outward-pkg-checkbox[data-grn-id="${grnId}"]`);
    checkboxes.forEach(cb => {
        const sIdx = parseInt(cb.getAttribute('data-slip-idx'));
        const slip = slips[sIdx];
        const slipPackingType = (slip ? (slip.packingType || 'Roll') : 'Roll').toUpperCase().trim();
        if (slipPackingType === packingType.toUpperCase().trim()) {
            if (!cb.disabled) {
                cb.checked = isChecked;
            }
        }
    });
    
    window.updateOutwardPackagesList(grnId);
    window.renderOutwardFormGRNLinks();
};

window.toggleShowPackingConversion = function(grnId, sIdx, show) {
    window.showPackingConversionStates = window.showPackingConversionStates || {};
    window.showPackingConversionStates[`${grnId}-${sIdx}`] = show;
    window.renderOutwardFormGRNLinks();
};

window.toggleSelectAllSlipPackages = function(grnId, sIdx, isChecked) {
    const grn = db.grns.find(g => g.id === grnId);
    if (!grn) return;
    
    const slips = (grn.packageSlips && grn.packageSlips.length > 0) ? grn.packageSlips : [{
        fabricType: grn.fabricType || 'Plain Fabric',
        color: grn.color || '-',
        packingType: grn.packingType || 'Roll',
        pkgCount: grn.pkgCount || 1,
        packages: [{ label: `${grn.packingType || 'Roll'} 1`, packageNo: '', qty: grn.qty }]
    }];
    
    const slip = slips[sIdx];
    if (!slip || !slip.packages) return;
    
    const editId = document.getElementById('outward-edit-id').value;
    const issuedPkgKeys = window.getIssuedPackagesForGRN(grnId, editId);
    
    // 1. Toggle unconverted packages in memory
    currentOutwardPackages = currentOutwardPackages.filter(p => 
        !(p.grnId === grnId && p.slipIndex === sIdx && !p.convertedDone)
    );
    
    if (isChecked) {
        slip.packages.forEach((pkg, pIdx) => {
            const key = `${sIdx}-${pIdx}`;
            const isAlreadyIssued = issuedPkgKeys.includes(key);
            const alreadyConverted = (window.grnConvertedLog[grnId] || []).some(batch =>
                batch.items.some(it => it.sIdx === sIdx && it.pIdx === pIdx)
            );
            
            if (!isAlreadyIssued && !alreadyConverted) {
                currentOutwardPackages.push({
                    grnId,
                    slipIndex: sIdx,
                    packageIndex: pIdx,
                    qty: pkg.qty,
                    convertedDone: false
                });
            }
        });
    }
    
    // 2. Toggle converted batches/items that belong to this slip
    const batches = window.grnConvertedLog[grnId] || [];
    batches.forEach(batch => {
        const slipIdx = batch.slipIdx !== undefined ? batch.slipIdx : (batch.items[0] ? batch.items[0].sIdx : 0);
        if (slipIdx === sIdx) {
            batch.dispatched = isChecked;
            batch.items.forEach(it => {
                it.dispatched = isChecked;
            });
        }
    });

    // 3. Update currentOutwardPackages to reflect converted batches checked state
    currentOutwardPackages = currentOutwardPackages.filter(p => 
        !(p.grnId === grnId && p.slipIndex === sIdx && p.convertedDone)
    );
    
    batches.forEach(batch => {
        const slipIdx = batch.slipIdx !== undefined ? batch.slipIdx : (batch.items[0] ? batch.items[0].sIdx : 0);
        if (slipIdx === sIdx) {
            batch.items.forEach(it => {
                if (it.dispatched !== false) {
                    currentOutwardPackages.push({
                        grnId,
                        slipIndex: it.sIdx,
                        packageIndex: it.pIdx,
                        qty: it.qty,
                        convertedPackingType: batch.targetType,
                        convertedDone: true
                    });
                }
            });
        }
    });

    // 4. Sync the grn link total qty input and global state
    const link = currentOutwardLinks.find(l => l.grnRefId === grnId);
    if (link) {
        link.qty = currentOutwardPackages.filter(p => p.grnId === grnId).reduce((s, p) => s + p.qty, 0);
    }
    const inputEl = document.querySelector(`.outward-link-issue-qty[data-grn-id="${grnId}"]`);
    if (inputEl) inputEl.value = (link ? link.qty : 0).toFixed(2);
    
    window.calcOutwardTotalMeters();
    window.renderOutwardFormGRNLinks();
};

window.toggleSelectAllBalePackages = function(grnId, sIdx, baleLabel, isChecked) {
    const grn = db.grns.find(g => g.id === grnId);
    if (!grn) return;
    
    const slips = (grn.packageSlips && grn.packageSlips.length > 0) ? grn.packageSlips : [{
        fabricType: grn.fabricType || 'Plain Fabric',
        color: grn.color || '-',
        packingType: grn.packingType || 'Roll',
        pkgCount: grn.pkgCount || 1,
        packages: [{ label: `${grn.packingType || 'Roll'} 1`, packageNo: '', qty: grn.qty }]
    }];
    
    const slip = slips[sIdx];
    if (!slip || !slip.packages) return;
    
    const editId = document.getElementById('outward-edit-id').value;
    const issuedPkgKeys = window.getIssuedPackagesForGRN(grnId, editId);
    
    // Toggle only the packages matching this baleLabel
    slip.packages.forEach((pkg, pIdx) => {
        if ((pkg.label || 'Bale 1') === baleLabel) {
            const key = `${sIdx}-${pIdx}`;
            const isAlreadyIssued = issuedPkgKeys.includes(key);
            const alreadyConverted = (window.grnConvertedLog[grnId] || []).some(batch =>
                batch.items.some(it => it.sIdx === sIdx && it.pIdx === pIdx)
            );
            
            if (!isAlreadyIssued && !alreadyConverted) {
                // Filter it out first to avoid duplicates
                currentOutwardPackages = currentOutwardPackages.filter(p => 
                    !(p.grnId === grnId && p.slipIndex === sIdx && p.packageIndex === pIdx && !p.convertedDone)
                );
                
                if (isChecked) {
                    currentOutwardPackages.push({
                        grnId,
                        slipIndex: sIdx,
                        packageIndex: pIdx,
                        qty: pkg.qty,
                        convertedDone: false
                    });
                }
            }
        }
    });
    
    // Sync the grn link total qty input and global state
    window.updateOutwardPackagesList(grnId);
    window.renderOutwardFormGRNLinks();
};

// Toggle dispatched status of a converted package item
window.toggleConvertedPackageDispatch = function(grnId, batchIdx, itemIdx, isChecked) {
    if (window.grnConvertedLog[grnId] && window.grnConvertedLog[grnId][batchIdx]) {
        const batch = window.grnConvertedLog[grnId][batchIdx];
        if (batch.items[itemIdx]) {
            batch.items[itemIdx].dispatched = isChecked;
        }
        // Sync batch dispatched status
        batch.dispatched = batch.items.some(it => it.dispatched !== false);
    }
    window.updateOutwardPackagesList(grnId);
    window.renderOutwardFormGRNLinks();
};

// Revert all conversions for a specific slip
window.revertAllSlipConversions = function(grnId, sIdx) {
    if (window.grnConvertedLog[grnId]) {
        window.grnConvertedLog[grnId] = window.grnConvertedLog[grnId].filter(batch => {
            const slipIdx = batch.slipIdx !== undefined ? batch.slipIdx : (batch.items[0] ? batch.items[0].sIdx : 0);
            return slipIdx !== sIdx;
        });
    }
    window.updateOutwardPackagesList(grnId);
    window.renderOutwardFormGRNLinks();
    showToast('Reverted slip to original packages', 'info');
};

// Delete a converted batch: restores packages to the top grid and removes from log
window.deleteConvertedBatch = function(grnId, batchIdx, btnEl) {
    if (!window.grnConvertedLog[grnId] || !window.grnConvertedLog[grnId][batchIdx]) return;

    const batch = window.grnConvertedLog[grnId][batchIdx];
    const grn = db.grns.find(g => g.id === grnId);
    if (!grn) return;

    const slips = (grn.packageSlips && grn.packageSlips.length > 0) ? grn.packageSlips : [{
        fabricType: grn.fabricType || 'Plain Fabric',
        color: grn.color || '-',
        packingType: grn.packingType || 'Roll',
        packages: [{ label: `${grn.packingType || 'Roll'} 1`, packageNo: '', qty: grn.qty }]
    }];

    // Remove from log
    window.grnConvertedLog[grnId].splice(batchIdx, 1);

    window.updateOutwardPackagesList(grnId);
    window.renderOutwardFormGRNLinks();
    showToast('Batch deleted � packages restored', 'info');
};

window.calcOutwardTotalMeters = function() {
    const isEmbroidery = (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered');
    if (isEmbroidery) {
        window.syncOutwardData();
        return;
    }

    const sourceTypeEl = document.getElementById('outward-material-source-type');
    const sourceType = sourceTypeEl ? sourceTypeEl.value : 'customer';

    let totalFabricMeters = 0;
    let totalFabricBal = 0;
    const editId = document.getElementById('outward-edit-id').value;
    
    if (sourceType !== 'consumable') {
        currentOutwardLinks.forEach(link => {
            totalFabricMeters += link.qty;
            
            const grn = db.grns.find(g => g.id === link.grnRefId);
            if (grn) {
                let originalQty = 0;
                if (editId) {
                    const existingOut = db.outwards.find(o => o.id === editId);
                    if (existingOut) {
                        if (existingOut.grnLinks) {
                            const match = existingOut.grnLinks.find(l => l.grnRefId === link.grnRefId);
                            if (match) originalQty = match.qty;
                        } else if (existingOut.grnRefId === link.grnRefId) {
                            originalQty = existingOut.qty;
                        }
                    }
                }
                totalFabricBal += (grn.qty - (grn.issuedMeters || 0) + originalQty);
            }
        });
    }

    const consQtyInput = document.getElementById('outward-consumable-qty');
    const totalConsumableQty = consQtyInput ? (parseFloat(consQtyInput.value) || 0) : 0;

    const fabricGroup = document.getElementById('outward-fabric-qty-group');
    const consumableGroup = document.getElementById('outward-consumable-qty-group');
    const fabricDisplay = document.getElementById('outward-fabric-qty-display');
    const consumableDisplay = document.getElementById('outward-consumable-qty-display');

    if (fabricDisplay) fabricDisplay.value = totalFabricMeters.toFixed(2);
    if (consumableDisplay) consumableDisplay.value = totalConsumableQty.toFixed(2);

    if (sourceType === 'customer') {
        if (fabricGroup) fabricGroup.style.display = 'block';
        if (consumableGroup) consumableGroup.style.display = 'none';
        const label = document.getElementById('outward-fabric-qty-label');
        if (label) label.textContent = 'Total Fabric Issue (Meters) *';
    } else if (sourceType === 'consumable') {
        if (fabricGroup) fabricGroup.style.display = 'none';
        if (consumableGroup) consumableGroup.style.display = 'block';
        const label = document.getElementById('outward-consumable-qty-label');
        if (label) label.textContent = 'Total Consumable Issue *';
    } else if (sourceType === 'both') {
        if (fabricGroup) fabricGroup.style.display = 'block';
        if (consumableGroup) consumableGroup.style.display = 'block';
        const flabel = document.getElementById('outward-fabric-qty-label');
        if (flabel) flabel.textContent = 'Total Fabric Issue (Meters) *';
        const clabel = document.getElementById('outward-consumable-qty-label');
        if (clabel) clabel.textContent = 'Total Consumable Issue *';
    }

    const finalQty = sourceType === 'consumable' ? totalConsumableQty : totalFabricMeters;
    const finalBal = sourceType === 'consumable' ? totalConsumableQty : totalFabricBal;
    
    document.getElementById('outward-meters').value = finalQty.toFixed(2);
    document.getElementById('outward-bal-meters').value = finalBal.toFixed(2);
};

window.renderOutwardFormGRNLinks = function() {
    const slipsContainer = document.getElementById('outward-packing-slips-container');
    if (!slipsContainer) return;
    
    slipsContainer.innerHTML = '';
    window.grnConvertedLog = window.grnConvertedLog || {};
    currentOutwardPackages = currentOutwardPackages || [];
    
    if (currentOutwardLinks.length === 0) {
        slipsContainer.innerHTML = `<div style="text-align:center; padding:20px; color:var(--text-muted); border: 1px dashed var(--border); border-radius:8px; font-size:12px;">Select a Plain Fabric GRN to display its packing slip.</div>`;
        const isEmbroidery = (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered');
        if (!isEmbroidery) {
            document.getElementById('outward-meters').value = '';
            const fDisp = document.getElementById('outward-fabric-qty-display');
            if (fDisp) fDisp.value = '0.00';
            const cDisp = document.getElementById('outward-consumable-qty-display');
            if (cDisp) cDisp.value = '0.00';
        }
        document.getElementById('outward-bal-meters').value = '0.00';
        return;
    }
    
    const editId = document.getElementById('outward-edit-id').value;
    
    currentOutwardLinks.forEach(link => {
        const grn = db.grns.find(g => g.id === link.grnRefId);
        if (!grn) return;
        
        let originalQty = 0;
        if (editId) {
            const existingOut = db.outwards.find(o => o.id === editId);
            if (existingOut) {
                if (existingOut.grnLinks) {
                    const match = existingOut.grnLinks.find(l => l.grnRefId === link.grnRefId);
                    if (match) originalQty = match.qty;
                } else if (existingOut.grnRefId === link.grnRefId) {
                    originalQty = existingOut.qty;
                }
            }
        }
        
        const bal = grn.qty - (grn.issuedMeters || 0) + originalQty;
        
        let linkTotalSelectedAfterL = 0;
        let tempSlips = grn.packageSlips && grn.packageSlips.length > 0 ? grn.packageSlips : [{ length: 100, qty: grn.qty, packages: [{ qty: grn.qty }] }];
        tempSlips.forEach((slip, sIdx) => {
            const slipLength = parseFloat(slip.length) || 100;
            const lenFactor = slipLength / 100;
            const selectedGrnPkgs = currentOutwardPackages.filter(p => p.grnId === grn.id && p.slipIndex === sIdx);
            const selectedQtySum = selectedGrnPkgs.reduce((s, p) => s + p.qty, 0);
            linkTotalSelectedAfterL += selectedQtySum * lenFactor;
        });
        link.qty = Math.round(linkTotalSelectedAfterL * 100) / 100;
        
        const slipConvertedBatchesCount = (window.grnConvertedLog[grn.id] || []).reduce((sum, batch) => {
            return sum + batch.items.reduce((s, it) => s + (it.dispatched !== false ? it.qty : 0), 0);
        }, 0);
        
        let isNewlyLinked = true;
        if (editId) {
            const existingOut = db.outwards.find(o => o.id === editId);
            if (existingOut) {
                if (existingOut.grnLinks) {
                    isNewlyLinked = !existingOut.grnLinks.some(l => l.grnRefId === link.grnRefId);
                } else if (existingOut.grnRefId === link.grnRefId) {
                    isNewlyLinked = false;
                }
            }
        }
        
        // if (editId && !isNewlyLinked && (selectedQtySum + slipConvertedBatchesCount) === 0) {
        //     return;
        // }
        
        let slips = [];
        if (grn.packageSlips && grn.packageSlips.length > 0) {
            slips = grn.packageSlips;
        } else {
            slips = [{
                fabricType: grn.fabricType || 'Plain Fabric',
                color: grn.color || '-',
                packingType: grn.packingType || 'Roll',
                pkgCount: grn.pkgCount || 1,
                packages: [{ label: `${grn.packingType || 'Roll'} 1`, packageNo: '', qty: grn.qty }]
            }];
        }

        const issuedPkgKeys = window.getIssuedPackagesForGRN(grn.id, editId);

        let slipsHtml = '';
        slips.forEach((slip, sIdx) => {
            let slipCheckboxesHtml = '';
            let slipTotalQty = 0;
            let slipSelectedQty = 0;
            let slipTotalCount = 0;
            let slipSelectedCount = 0;

            if (slip.packages) {
                const isBale = slip.packingType && slip.packingType.toUpperCase() === 'BALE';
                if (isBale) {
                    const groups = {};
                    slip.packages.forEach((pkg, pIdx) => {
                        const label = pkg.label || 'Bale 1';
                        if (!groups[label]) {
                            groups[label] = [];
                        }
                        groups[label].push({ pkg, pIdx });
                    });

                    for (const baleLabel in groups) {
                        const pkgList = groups[baleLabel];


                        let baleTotalQty = 0;
                        let baleSelectedQty = 0;
                        let baleTotalCount = 0;
                        let baleSelectedCount = 0;
                        let baleCheckboxesHtml = '';
                        let baleNo = '';

                        pkgList.forEach(({ pkg, pIdx }) => {
                            const key = `${sIdx}-${pIdx}`;
                            const isAlreadyIssued = issuedPkgKeys.includes(key);
                            
                            const alreadyConverted = (window.grnConvertedLog[grn.id] || []).some(batch =>
                                (batch.originalItems || batch.items).some(it => it.sIdx === sIdx && it.pIdx === pIdx)
                            );
                            if (alreadyConverted) {
                                return;
                            }

                            baleTotalQty += pkg.qty;
                            baleTotalCount++;
                            if (pkg.packageNo) baleNo = pkg.packageNo;

                            const isPreSelected = !isAlreadyIssued && currentOutwardPackages.some(
                                p => p.grnId === grn.id && p.slipIndex === sIdx && p.packageIndex === pIdx && !p.convertedDone
                            );
                            if (isPreSelected) {
                                baleSelectedQty += pkg.qty;
                                baleSelectedCount++;
                            }

                            slipTotalQty += pkg.qty;
                            slipTotalCount++;
                            if (isPreSelected) {
                                slipSelectedQty += pkg.qty;
                                slipSelectedCount++;
                            }

                            baleCheckboxesHtml += `
                                <label class="pkg-label" data-search-text="${(baleLabel + ' ' + (pkg.packageNo || '') + ' ' + pkg.qty).toLowerCase()}" style="display:flex; align-items:center; gap:6px; font-size:11px; background:var(--bg-input); padding:4px 8px; border-radius:4px; border:1px solid var(--border); cursor:${isAlreadyIssued ? 'not-allowed' : 'pointer'}; opacity:${isAlreadyIssued ? 0.5 : 1}; user-select:none; margin:0;">
                                    <input type="checkbox" class="outward-pkg-checkbox" data-grn-id="${grn.id}" data-slip-idx="${sIdx}" data-pkg-idx="${pIdx}" data-qty="${pkg.qty}" ${isAlreadyIssued ? 'disabled' : ''} ${isPreSelected ? 'checked' : ''} onchange="window.onOutwardPackageToggle('${grn.id}')" style="cursor:inherit; width:12px; height:12px; margin:0;">
                                    <span>${pkg.qty} m</span>
                                </label>
                            `;
                        });

                        const isAllBaleSelected = baleTotalCount > 0 && baleSelectedCount === baleTotalCount;

                        slipCheckboxesHtml += `
                            <div class="bale-card" style="border:1px solid var(--border); border-radius:8px; padding:10px; background:rgba(255,255,255,0.015); margin-bottom:8px; grid-column:1/-1; width:100%; box-sizing:border-box;">
                                <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--border); padding-bottom:6px; margin-bottom:8px; flex-wrap:wrap; gap:6px;">
                                    <label style="display:flex; align-items:center; gap:8px; font-weight:600; font-size:12px; margin:0; cursor:pointer; color:var(--accent-blue);">
                                        <input type="checkbox" class="bale-select-all-checkbox" data-grn-id="${grn.id}" data-slip-idx="${sIdx}" data-bale-label="${baleLabel}" ${isAllBaleSelected ? 'checked' : ''} onchange="window.toggleSelectAllBalePackages('${grn.id}', ${sIdx}, '${baleLabel}', this.checked)" style="width:14px; height:14px; cursor:pointer; margin:0;">
                                        ${baleLabel}${baleNo ? ` (#${baleNo})` : ''}
                                    </label>
                                    <span style="font-size:11px; color:var(--text-secondary);">Selected: <strong style="color:var(--accent-blue);">${baleSelectedQty.toFixed(2)} m</strong> / ${baleTotalQty.toFixed(2)} m (${baleTotalCount} Thans)</span>
                                </div>
                                <div style="display:grid; grid-template-columns:repeat(auto-fill, minmax(90px, 1fr)); gap:6px;">
                                    ${baleCheckboxesHtml || '<div style="color:var(--text-muted); font-style:italic; font-size:11px;">No original pieces in this bale.</div>'}
                                </div>
                            </div>
                        `;
                    }
                } else {
                    slip.packages.forEach((pkg, pIdx) => {
                        const key = `${sIdx}-${pIdx}`;
                        const isAlreadyIssued = issuedPkgKeys.includes(key);

                        const alreadyConverted = (window.grnConvertedLog[grn.id] || []).some(batch =>
                            (batch.originalItems || batch.items).some(it => it.sIdx === sIdx && it.pIdx === pIdx)
                        );
                        if (alreadyConverted) {
                            return;
                        }

                        slipTotalQty += pkg.qty;
                        slipTotalCount++;

                        const isPreSelected = !isAlreadyIssued && currentOutwardPackages.some(
                            p => p.grnId === grn.id && p.slipIndex === sIdx && p.packageIndex === pIdx && !p.convertedDone
                        );
                        if (isPreSelected) {
                            slipSelectedQty += pkg.qty;
                            slipSelectedCount++;
                        }

                        slipCheckboxesHtml += `
                            <label class="pkg-label" data-search-text="${(pkg.label + ' ' + (pkg.packageNo || '') + ' ' + pkg.qty).toLowerCase()}" style="display:flex; align-items:center; gap:8px; font-size:11px; background:var(--bg-input); padding:6px 10px; border-radius:6px; border:1px solid var(--border); cursor:${isAlreadyIssued ? 'not-allowed' : 'pointer'}; opacity:${isAlreadyIssued ? 0.5 : 1}; user-select:none; margin: 2px 0;">
                                <input type="checkbox" class="outward-pkg-checkbox" data-grn-id="${grn.id}" data-slip-idx="${sIdx}" data-pkg-idx="${pIdx}" data-qty="${pkg.qty}" ${isAlreadyIssued ? 'disabled' : ''} ${isPreSelected ? 'checked' : ''} onchange="window.onOutwardPackageToggle('${grn.id}')" style="cursor:inherit;">
                                <span style="flex:1;">
                                    <span style="font-weight:400; color:var(--text-secondary);">${pkg.label}${pkg.packageNo ? ` (#${pkg.packageNo})` : ''}</span>: <strong style="color:var(--accent-blue);">${pkg.qty} m</strong>
                                    ${isAlreadyIssued ? ' <span style="color:var(--accent-red); font-weight:700;">(Dispatched)</span>' : ''}
                                </span>
                            </label>
                        `;
                    });
                }
            }

            // Append converted packages directly to the same grid list!
            const slipConvertedBatches = (window.grnConvertedLog[grn.id] || []).filter(batch => {
                const slipIdx = batch.slipIdx !== undefined ? batch.slipIdx : (batch.items[0] ? batch.items[0].sIdx : 0);
                return slipIdx === sIdx;
            });

            slipConvertedBatches.forEach(batch => {
                const globalIdx = window.grnConvertedLog[grn.id].indexOf(batch);
                batch.items.forEach((it, i) => {
                    const isPreSelected = it.dispatched !== false;
                    if (isPreSelected) {
                        slipSelectedQty += it.qty;
                        slipSelectedCount++;
                    }
                    slipTotalQty += it.qty;
                    slipTotalCount++;

                    slipCheckboxesHtml += `
                        <label class="pkg-label" data-search-text="${(it.label + ' ' + (it.packageNo || '') + ' ' + it.qty).toLowerCase()}" style="display:flex; align-items:center; gap:8px; font-size:11px; background:rgba(79, 125, 255, 0.04); padding:6px 10px; border-radius:6px; border:1px solid rgba(79, 125, 255, 0.25); cursor:pointer; user-select:none; margin: 2px 0;">
                            <input type="checkbox" class="outward-batch-item-checkbox" data-grn-id="${grn.id}" data-batch-idx="${globalIdx}" data-item-idx="${i}" ${isPreSelected ? 'checked' : ''} onchange="window.toggleConvertedPackageDispatch('${grn.id}', ${globalIdx}, ${i}, this.checked)" style="cursor:inherit;">
                            <span style="flex:1; display:flex; justify-content:space-between; align-items:center;">
                                <span>
                                    <span style="font-weight:600; color:var(--accent-blue);">${it.label}${it.packageNo ? ` (#${it.packageNo})` : ''}</span>: <strong style="color:var(--text-primary);">${it.qty} m</strong>
                                </span>
                                <span style="background:rgba(79, 125, 255, 0.12); color:var(--accent-blue); padding:1px 6px; border-radius:4px; font-size:9px; font-weight:700; text-transform:uppercase;">${batch.targetType} (Converted)</span>
                            </span>
                        </label>
                    `;
                });
            });

            if (editId && slipTotalCount === 0) {
                return;
            }

            const isAllSlipSelected = slipTotalCount > 0 && slipSelectedCount === slipTotalCount;
            const showConv = !!(window.showPackingConversionStates && window.showPackingConversionStates[`${grn.id}-${sIdx}`]);

            const origQtyWithoutL = slip.packages ? slip.packages.reduce((sum, p) => sum + (parseFloat(p.qty) || 0), 0) : 0;
            const slipLength = parseFloat(slip.length) || 100;
            const origQtyAfterL = parseFloat(slip.qty) || (origQtyWithoutL * (slipLength / 100));

            let detailsParts = [];
            if (slip.fabricType) detailsParts.push(slip.fabricType);
            if (slip.packingType) detailsParts.push(slip.packingType);
            if (slip.color) detailsParts.push(slip.color);
            if (slip.rate) detailsParts.push(`�${slip.rate}/m`);

            const isPlainFabric = (grnWizardState.type === 'fabric' && grnWizardState.subType === 'plain') || (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.subType === 'plain');
            if (isPlainFabric || slipLength > 0) {
                detailsParts.push(`L: ${slipLength}`);
                detailsParts.push(`Total (without L): ${origQtyWithoutL.toFixed(2)}m`);
                detailsParts.push(`Total (after L): ${origQtyAfterL.toFixed(2)}m`);
            }
            const detailsStr = detailsParts.join(' - ');

            const slipSelectedQtyAfterL = Math.round(slipSelectedQty * (slipLength / 100) * 100) / 100;
            const slipTotalQtyAfterL = Math.round(slipTotalQty * (slipLength / 100) * 100) / 100;

            slipsHtml += `
                <div style="margin-bottom:18px; border:1px solid var(--border); padding:12px; border-radius:8px; background:rgba(255,255,255,0.01);">
                    <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--border); padding-bottom:8px; margin-bottom:12px; font-size:11px; gap:10px; flex-wrap:wrap;">
                        <div style="display:flex; align-items:center; gap:10px; flex-wrap:wrap;">
                            <input type="checkbox" class="slip-select-all-checkbox" data-grn-id="${grn.id}" data-slip-idx="${sIdx}" ${isAllSlipSelected ? 'checked' : ''} onchange="window.toggleSelectAllSlipPackages('${grn.id}', ${sIdx}, this.checked)" style="cursor:pointer; width:14px; height:14px; margin:0;">
                            <div>
                                <strong style="color:var(--accent-blue);">Packing Slip #${sIdx + 1}</strong>
                                <span style="color:var(--text-secondary); margin-left:6px;">(${detailsStr})</span>
                            </div>
                            <div>
                                <input type="text" id="pkg-search-${grn.id}-${sIdx}"
                                    placeholder="=  Search name or meters..."
                                    oninput="window.filterSlipPackages('${grn.id}', ${sIdx}, this.value)"
                                    style="font-size:11px; padding:3px 8px; height:24px; border-radius:5px; border:1px solid var(--border); background:var(--bg-input); color:var(--text-primary); width:185px; outline:none;">
                            </div>
                            <label style="display:inline-flex; align-items:center; gap:5px; font-size:11px; color:var(--text-secondary); cursor:pointer; user-select:none; margin:0 0 0 10px;">
                                <input type="checkbox" ${showConv ? 'checked' : ''} onchange="window.toggleShowPackingConversion('${grn.id}', ${sIdx}, this.checked)" style="width:12px; height:12px; margin:0; cursor:pointer;">
                                = Show Conversion
                            </label>
                        </div>
                        <div style="color:var(--text-secondary);">
                            Selected (without L): <strong style="color:var(--accent-blue);">${slipSelectedQty.toFixed(2)} m</strong> (after L: <strong style="color:var(--accent-blue);">${slipSelectedQtyAfterL.toFixed(2)} m</strong>) / Total (without L): ${slipTotalQty.toFixed(2)} m (after L: ${slipTotalQtyAfterL.toFixed(2)} m)
                        </div>
                    </div>

                    <div style="font-weight: 700; font-size: 10px; color: var(--text-muted); text-transform: uppercase; margin-bottom: 6px;">=� Select Packages to Dispatch:</div>
                    <div id="pkg-grid-${grn.id}-${sIdx}" style="display:grid; grid-template-columns:repeat(auto-fill, minmax(220px, 1fr)); gap:6px; margin-bottom:12px;">
                        ${slipCheckboxesHtml || '<div style="color:var(--text-muted); font-style:italic; font-size:11px;">No packages in this slip.</div>'}
                    </div>

                    <div style="margin-top:12px; display: ${showConv ? 'block' : 'none'};">
                        <div class="packing-converter-container" data-grn-id="${grn.id}" data-slip-idx="${sIdx}" style="padding: 10px; border-radius: 8px; background: rgba(79, 125, 255, 0.04); border: 1px dashed rgba(79, 125, 255, 0.25); display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap:wrap;">
                            <div style="font-size: 11px; color: var(--text-secondary); display: flex; align-items: center; gap: 8px;">
                                <span>= <strong>Convert Selected Packages To:</strong></span>
                                <select id="convert-packing-type-select-${grn.id}-${sIdx}" class="form-input" style="width: 120px; font-size: 11px; padding: 2px 6px; height: 26px; margin: 0;">
                                    ${(window.customMasters && window.customMasters.packingtypes && window.customMasters.packingtypes.length > 0 ? window.customMasters.packingtypes : ['BALE', 'ROLL', 'LOOSE', 'BUNDLE', 'LUMP', 'THAN']).map(pt => `<option value="${pt}">${pt}</option>`).join('')}
                                </select>
                            </div>
                            <div style="display:flex; align-items:center; gap:8px;">
                                <button type="button" class="btn btn-secondary btn-sm" onclick="window.convertSelectedPackagesPackingType('${grn.id}', ${sIdx})" style="padding: 2px 10px; font-size: 11px; height: 26px;">Apply Packing Conversion</button>
                                ${slipConvertedBatches.length > 0 ? `<button type="button" class="btn btn-secondary btn-sm" onclick="window.revertAllSlipConversions('${grn.id}', ${sIdx})" style="padding: 2px 10px; font-size: 11px; height: 26px; background:rgba(239,68,68,0.08); color:#dc2626; border:1px solid rgba(239,68,68,0.2); cursor:pointer;" onmouseover="this.style.background='rgba(239,68,68,0.15)'" onmouseout="this.style.background='rgba(239,68,68,0.08)'">Revert to Original Slip</button>` : ''}
                            </div>
                        </div>
                    </div>
                </div>
            `;
        });

        const div = document.createElement('div');
        div.style.cssText = 'padding:14px; border:1px solid var(--border); border-radius:8px; background:rgba(79,125,255,0.01); margin-bottom:15px; width:100%; box-sizing:border-box;';
        div.innerHTML = `
            <div style="display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid var(--border); padding-bottom:8px; margin-bottom:14px; flex-wrap:wrap; gap:8px;">
                <div style="font-size:13px; font-weight:700; color:var(--text-primary); display:flex; align-items:center; gap:8px;">
                    =� Associated GRN Info: <span style="color:var(--accent-blue);">${grn.partyDocNo || 'Challan (No No)'}</span> (GRN: ${grn.grnNo || grn.number})
                    <button type="button" class="btn btn-sm" onclick="window.removeOutwardGRNLink('${grn.id}')" style="background:rgba(239,68,68,0.1); color:#dc2626; border:1px solid rgba(239,68,68,0.2); border-radius:4px; padding:2px 8px; font-size:10px; font-weight:600; cursor:pointer; margin-left:12px;" onmouseover="this.style.background='rgba(239,68,68,0.18)'" onmouseout="this.style.background='rgba(239,68,68,0.1)'">L Remove</button>
                </div>
                <div style="font-size:12px; color:var(--text-secondary);">
                    Available Balance: <strong style="color:var(--accent-green);">${bal.toFixed(2)} m</strong> | Selected Issue Qty: <strong style="color:var(--accent-blue);">${link.qty.toFixed(2)} m</strong>
                </div>
            </div>
            
            <div style="margin-top:10px;">
                ${slipsHtml}
            </div>
        `;
        slipsContainer.appendChild(div);
    });
    
    window.calcOutwardTotalMeters();
};
// Filter package labels in a slip grid by name or meter value
window.filterSlipPackages = function(grnId, sIdx, query) {
    const grid = document.getElementById(`pkg-grid-${grnId}-${sIdx}`);
    if (!grid) return;
    const q = (query || '').trim().toLowerCase();
    const labels = grid.querySelectorAll('.pkg-label');
    let visibleCount = 0;

    labels.forEach(lbl => {
        const text = (lbl.getAttribute('data-search-text') || lbl.textContent).toLowerCase();
        const match = !q || text.includes(q);
        lbl.style.display = match ? 'flex' : 'none';
        if (match) visibleCount++;
    });

    // Show/hide no-match message
    let noMatchEl = grid.querySelector('.pkg-no-match');
    if (q && visibleCount === 0) {
        if (!noMatchEl) {
            noMatchEl = document.createElement('div');
            noMatchEl.className = 'pkg-no-match';
            noMatchEl.style.cssText = 'color:var(--text-muted); font-style:italic; font-size:11px; padding:6px 0; grid-column:1/-1;';
            grid.appendChild(noMatchEl);
        }
        noMatchEl.textContent = `No packages matching "${query}"`;
        noMatchEl.style.display = 'block';
    } else if (noMatchEl) {
        noMatchEl.style.display = 'none';
    }
};

