async function saveOutward() {
    if (window._isSavingOutward) return;
    window._isSavingOutward = true;
    const saveBtn = document.querySelector('#outward-modal .btn-primary') || document.getElementById('outward-save-btn');
    const origBtnHtml = saveBtn ? saveBtn.innerHTML : '';
    if (saveBtn) { saveBtn.disabled = true; saveBtn.innerHTML = '� Saving...'; }
    try {
        if (window.validateVoucherMaker && !(await window.validateVoucherMaker('outward-modal'))) return;
        if (window.reactivatedVouchers) delete window.reactivatedVouchers['outward-modal'];
        let number = document.getElementById('outward-number').value;
    if (number && window.formatStandardDocNumber) {
        number = window.formatStandardDocNumber(number);
    }
    const editId = document.getElementById('outward-edit-id').value;
    if (!editId) {
        number = await window.ensureUniqueDocumentNumber('outwards', 'number', number);
        document.getElementById('outward-number').value = number;
    }
    const date = document.getElementById('outward-date').value;
    const vendorId = document.getElementById('outward-vendor').value;
    const poRefId = document.getElementById('outward-po-ref').value;
    const customerId = document.getElementById('outward-customer').value;
    const qty = parseFloat(document.getElementById('outward-meters').value) || 0;
    const transporterId = document.getElementById('outward-transporter').value;
    const lrNo = document.getElementById('outward-lr').value;
    const vehicleNo = document.getElementById('outward-vehicle').value;
    const place = document.getElementById('outward-place').value;

    let hasTransporter = document.getElementById('outward-has-transporter').value;
    let hasLocalFreight = document.getElementById('outward-has-local-freight').value;

    if (outwardWizardState.type === 'inhouse') {
        hasTransporter = 'No';
        hasLocalFreight = 'No';
    }

    const isCustomerEmb = (outwardWizardState.subType === 'embroidered') || 
                           String(number || '').toUpperCase().startsWith('FI/C/EM') || 
                           String(number || '').toUpperCase().startsWith('FI/V/EM');

    const sourceTypeEl = document.getElementById('outward-material-source-type');
    const sourceType = sourceTypeEl ? sourceTypeEl.value : 'customer';

    let consumableItemId = '';
    let consumableQty = 0;
    let consumableThan = 0;
    if (sourceType === 'consumable' || sourceType === 'both') {
        consumableItemId = document.getElementById('outward-consumable-item')?.value || '';
        consumableQty = parseFloat(document.getElementById('outward-consumable-qty')?.value) || 0;
        if (!consumableItemId) {
            showToast('Please select a Consumable Item', 'error');
            return;
        }
        if (consumableQty <= 0) {
            showToast('Consumable quantity must be greater than zero', 'error');
            return;
        }
    }

    if (isCustomerEmb) {
        currentOutwardLinks = [];
        currentOutwardPackages = [];
        
        const usedRows = document.querySelectorAll('.outward-fabric-used-row');
        usedRows.forEach((row, rowIndex) => {
            const grnId = row.getAttribute('data-grn-id');
            const qtyVal = parseFloat(row.querySelector('.outward-fabric-used-qty').value) || 0;
            const than = parseFloat(row.querySelector('.outward-fabric-used-than').value) || 0;
            const conversion = parseFloat(row.querySelector('.outward-fabric-used-conversion').value) || 0;
            
            if (grnId && qtyVal > 0) {
                let existingLink = currentOutwardLinks.find(l => l.grnRefId === grnId);
                if (existingLink) {
                    existingLink.qty += qtyVal;
                } else {
                    currentOutwardLinks.push({ grnRefId: grnId, qty: qtyVal });
                }
                
                currentOutwardPackages.push({
                    grnId: grnId,
                    slipIndex: 0,
                    packageIndex: rowIndex,
                    qty: qtyVal,
                    than: than,
                    conversion: conversion
                });
            }
        });
    }

    const isVendorRequired = !(
        (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer') ||
        outwardWizardState.type === 'inhouse'
    );
    if (isVendorRequired && !vendorId) {
        showToast('Please select a Vendor / Job Worker', 'error');
        return;
    }
    if (!customerId) {
        showToast('Please select a Customer', 'error');
        return;
    }
    const finalQty = sourceType === 'consumable' ? consumableQty : qty;
    if (finalQty <= 0) {
        showToast(sourceType === 'consumable' ? 'Consumable quantity must be greater than zero' : 'Meters issued must be greater than zero', 'error');
        return;
    }
    if (!isCustomerEmb && sourceType !== 'consumable' && currentOutwardLinks.length === 0) {
        showToast('Please select a Plain Fabric GRN and select package rolls to issue.', 'error');
        return;
    }
    if (!date) {
        showToast('Date is required', 'error');
        return;
    }
    if (!validateTransactionDate(date)) return;
    if (!window.validateDocumentDateChronology('outwards', number, date, editId)) return;

    if (!editId) {
        const isDuplicate = (db.outwards || []).some(o => o.number && o.number.toLowerCase() === number.toLowerCase());
        if (isDuplicate) {
            showToast(`Error: Challan number ${number} already exists! Please use a unique number.`, 'error');
            return;
        }
    }

    let taxiName = (hasLocalFreight === 'Yes' && document.getElementById('outward-taxi-name')) ? document.getElementById('outward-taxi-name').value.trim() : '';

    const oldOut = editId ? db.outwards.find(o => o.id === editId) : null;
    const oldLinks = (oldOut && oldOut.materialSourceType !== 'consumable') ? (oldOut.grnLinks || (oldOut.grnRefId ? [{ grnRefId: oldOut.grnRefId, qty: oldOut.qty }] : [])) : [];

    // Revert old links issuedMeters on GRNs temporarily to validate total balances accurately (Skip if customer embroidered or consumable only)
    if (!isCustomerEmb && sourceType !== 'consumable') {
        for (const link of oldLinks) {
            const g = db.grns.find(x => x.id === link.grnRefId);
            if (g) {
                g.issuedMeters = Math.max(0, (g.issuedMeters || 0) - link.qty);
            }
        }
    }

    // Calculate actual linked outwards sum for each GRN in database
    const getLinkedOutwardsSum = (grnId) => {
        let sum = 0;
        (db.outwards || []).forEach(o => {
            if (editId && o.id === editId) return;
            const oState = parseOutwardWizardState(o);
            if (oState.type === 'fabric_issue_challan' && oState.source === 'customer' && oState.subType === 'embroidered') return;
            if (o.materialSourceType === 'consumable') return;
            if (o.grnLinks) {
                const match = o.grnLinks.find(l => l.grnRefId === grnId);
                if (match) sum += match.qty;
            } else if (o.grnRefId === grnId) {
                sum += o.qty;
            }
        });
        return sum;
    };

    // Also temporarily subtract any "orphaned" issued meters (Skip if customer embroidered or consumable only)
    const grnsToAdjust = new Set(currentOutwardLinks.map(l => l.grnRefId));
    const orphanedMetersMap = {};
    if (!isCustomerEmb && sourceType !== 'consumable') {
        for (const grnId of grnsToAdjust) {
            const g = db.grns.find(x => x.id === grnId);
            if (g) {
                const linkedSum = getLinkedOutwardsSum(grnId);
                const orphaned = Math.max(0, (g.issuedMeters || 0) - linkedSum);
                if (orphaned > 0) {
                    orphanedMetersMap[grnId] = orphaned;
                    g.issuedMeters = Math.max(0, g.issuedMeters - orphaned);
                }
            }
        }
    }

    // Validate and apply new links (Skip stock validation if customer embroidered or consumable only)
    let isValid = true;
    if (!isCustomerEmb && sourceType !== 'consumable') {
        for (const link of currentOutwardLinks) {
            const g = db.grns.find(x => x.id === link.grnRefId);
            if (!g) continue;
            const currentBalance = g.qty - (g.issuedMeters || 0);
            if (link.qty > currentBalance) {
                showToast(`CRITICAL REJECTION: Outflow Qty for ${g.grnNo} exceeds Stock (Max: ${currentBalance.toFixed(2)} m)`, 'error');
                isValid = false;
                break;
            }
        }
    }

    if (isValid) {
        // Double check individual packages to prevent concurrent issues or corruptions (Skip if customer embroidered or consumable only)
        if (!isCustomerEmb && sourceType !== 'consumable') {
            for (const pkg of currentOutwardPackages) {
                if (pkg.convertedDone) continue; // skip already converted ones if edit
                
                const key = `${pkg.slipIndex}-${pkg.packageIndex}`;
                const issuedByOthers = window.getIssuedPackagesForGRN(pkg.grnId, editId);
                if (issuedByOthers.includes(key)) {
                    const grn = db.grns.find(g => g.id === pkg.grnId);
                    showToast(`CRITICAL REJECTION: Package in GRN ${grn ? grn.grnNo : ''} has already been issued in another Challan!`, 'error');
                    isValid = false;
                    break;
                }
            }
        }
    }

    if (!isValid) {
        // Re-apply old links to restore state on validation failure (Skip if customer embroidered or consumable only)
        if (!isCustomerEmb && sourceType !== 'consumable') {
            for (const link of oldLinks) {
                const g = db.grns.find(x => x.id === link.grnRefId);
                if (g) {
                    g.issuedMeters = (g.issuedMeters || 0) + link.qty;
                }
            }
            // Restore orphaned meters
            for (const grnId in orphanedMetersMap) {
                const g = db.grns.find(x => x.id === grnId);
                if (g) {
                    g.issuedMeters = (g.issuedMeters || 0) + orphanedMetersMap[grnId];
                }
            }
        }
        return;
    }

    // Commit changes to database for each GRN (Skip stock commitment if customer embroidered or consumable only)
    if (!isCustomerEmb && sourceType !== 'consumable') {
        for (const link of currentOutwardLinks) {
            const g = db.grns.find(x => x.id === link.grnRefId);
            if (g) {
                g.issuedMeters = (g.issuedMeters || 0) + link.qty;
                await saveToSupabase('grns', g);
            }
        }
    }

    // For any grns that were in oldLinks but are completely removed in new links, save their updated grn state
    if (!isCustomerEmb && sourceType !== 'consumable') {
        for (const oldLink of oldLinks) {
            if (!currentOutwardLinks.some(l => l.grnRefId === oldLink.grnRefId)) {
                const g = db.grns.find(x => x.id === oldLink.grnRefId);
                if (g) {
                    await saveToSupabase('grns', g);
                }
            }
        }
    }

    const vendor = db.vendors.find(v => v.id === vendorId);
    const transporterObj = db.transporters.find(t => t.id === transporterId);
    
    const firstGrnId = currentOutwardLinks[0]?.grnRefId;
    const firstGrn = db.grns.find(g => g.id === firstGrnId);
    
    const linkedGrnNos = currentOutwardLinks.map(link => db.grns.find(g => g.id === link.grnRefId)?.grnNo).filter(Boolean).join(', ');
    const linkedCustChallanNos = currentOutwardLinks.map(link => db.grns.find(g => g.id === link.grnRefId)?.partyDocNo).filter(Boolean).join(', ');
    if (customerId) {
        outwardWizardState.customerId = customerId;
        outwardWizardState.customerName = (db.customers.find(c => c.id === customerId) || {}).name || '';
    }
    if (vendorId) {
        outwardWizardState.vendorId = vendorId;
        outwardWizardState.vendorName = (db.vendors.find(v => v.id === vendorId) || {}).name || '';
    }
    const wizardRemarks = `[WIZARD:${JSON.stringify(outwardWizardState)}]`;

    let linked_po_id = '';
    let linked_po_number = '';
    let linked_so_id = '';
    let linked_so_number = '';
    let isPOInhouse = false;

    if (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered') {
        const selectedSoId = document.getElementById('outward-linked-so')?.value || '';
        if (!selectedSoId) {
            showToast('Please select a Sales Order to link', 'error');
            // Re-apply old links to restore state on validation failure
            for (const link of oldLinks) {
                const g = db.grns.find(x => x.id === link.grnRefId);
                if (g) {
                    g.issuedMeters = (g.issuedMeters || 0) + link.qty;
                }
            }
            // Restore orphaned meters
            for (const grnId in orphanedMetersMap) {
                const g = db.grns.find(x => x.id === grnId);
                if (g) {
                    g.issuedMeters = (g.issuedMeters || 0) + orphanedMetersMap[grnId];
                }
            }
            return;
        }
        const linkedSO = db.salesOrders.find(s => s.id === selectedSoId);
        linked_so_id = selectedSoId;
        linked_so_number = linkedSO ? (linkedSO.number || '') : '';
    } else if (outwardWizardState.type === 'inhouse') {
        const linkedPO = poRefId ? db.pos.find(p => p.id === poRefId) : null;
        linked_po_id = poRefId || '';
        linked_po_number = linkedPO ? (linkedPO.number || '') : '';
        linked_so_id = linkedPO ? (linkedPO.linkedSoId || linkedPO.soRef || '') : '';
        linked_so_number = linkedPO ? (linkedPO.linkedSoNumber || '') : '';
        isPOInhouse = true;
    } else {
        const linkedPO = poRefId ? db.pos.find(p => p.id === poRefId) : null;
        linked_po_id = poRefId || '';
        linked_po_number = linkedPO ? (linkedPO.number || '') : '';
        linked_so_id = linkedPO ? (linkedPO.linkedSoId || linkedPO.soRef || '') : '';
        linked_so_number = linkedPO ? (linkedPO.linkedSoNumber || '') : '';
        isPOInhouse = (linkedPO && linkedPO.poType === 'inhouse');
    }

    if (outwardWizardState.type === 'inhouse' || isPOInhouse) {
        const linkedPOObj = poRefId ? db.pos.find(p => p.id === poRefId) : null;
        if (linkedPOObj) {
            const poQty = parseFloat(linkedPOObj.qty) || 0;
            const maxAllowedPoQty = Math.round((poQty * 1.10 + Number.EPSILON) * 100) / 100;
            const otherOutwards = (db.outwards || []).filter(o => {
                if ((o.status || '').toLowerCase() === 'cancelled') return false;
                if (editId && o.id === editId) return false;
                const oState = parseOutwardWizardState(o);
                return oState.type === 'inhouse' && (o.poRefId === poRefId || o.linked_po_id === poRefId);
            });
            const totalOtherOutQty = otherOutwards.reduce((sum, o) => {
                const oFabricQty = o.materialSourceType === 'consumable' ? 0 : (parseFloat(o.qty) || 0);
                return sum + oFabricQty;
            }, 0);
            const outwardFabricQty = sourceType === 'consumable' ? 0 : qty;
            if (totalOtherOutQty + outwardFabricQty > maxAllowedPoQty + 0.001) {
                showToast(`CRITICAL REJECTION: Total Fabric Issue quantity (${(totalOtherOutQty + outwardFabricQty).toFixed(2)} m) exceeds the In-House PO limit + 10% tolerance (${maxAllowedPoQty.toFixed(2)} m) for PO ${linkedPOObj.number}.`, 'error');
                
                // Re-apply old links to restore state on validation failure
                if (!isCustomerEmb) {
                    for (const link of oldLinks) {
                        const g = db.grns.find(x => x.id === link.grnRefId);
                        if (g) {
                            g.issuedMeters = (g.issuedMeters || 0) + link.qty;
                        }
                    }
                    for (const grnId in orphanedMetersMap) {
                        const g = db.grns.find(x => x.id === grnId);
                        if (g) {
                            g.issuedMeters = (g.issuedMeters || 0) + orphanedMetersMap[grnId];
                        }
                    }
                }
                return;
            }
        }
    }

    const machineSelect = document.getElementById('outward-machine-select');
    const machineId = (isPOInhouse && machineSelect) ? machineSelect.value : '';
    const machineObj = machineId ? db.machines.find(m => m.id === machineId) : null;
    const machineNo = machineObj ? machineObj.name : '';

    // Validate Machine selection if In-House flow
    if (false) {
        
        // Re-apply old links to restore state on validation failure
        for (const link of oldLinks) {
            const g = db.grns.find(x => x.id === link.grnRefId);
            if (g) {
                g.issuedMeters = (g.issuedMeters || 0) + link.qty;
            }
        }
        // Restore orphaned meters
        for (const grnId in orphanedMetersMap) {
            const g = db.grns.find(x => x.id === grnId);
            if (g) {
                g.issuedMeters = (g.issuedMeters || 0) + orphanedMetersMap[grnId];
            }
        }
        return;
    }

    const firstSlip = firstGrn && firstGrn.packageSlips ? firstGrn.packageSlips[currentOutwardPackages[0]?.slipIndex || 0] : null;
    const rate = firstSlip ? (parseFloat(firstSlip.rate) || 0) : 0;

    const freightPaymentType = document.getElementById('outward-freight-payment-type')?.value || 'To Pay';
    const transportState = {
        isTransporter: hasTransporter,
        isLocalFreight: hasLocalFreight,
        freightPaymentType: freightPaymentType,
        gstNo: document.getElementById('outward-transporter-gst')?.value || '',
        pkgCount: document.getElementById('outward-transport-pkg-count')?.value || '',
        labour: document.getElementById('outward-transport-labour')?.value || '',
        taxiName: hasLocalFreight === 'Yes' ? taxiName : ''
    };
    const transportStr = `[TRANSPORT:${JSON.stringify(transportState)}]`;

    const data = {
        id: editId || uid(),
        company_id: (window.currentCompany && window.currentCompany.id) || 'co4',
        number, date, vendorId, vendorName: vendor ? vendor.name : (outwardWizardState.type === 'inhouse' ? 'In House' : (outwardWizardState.source === 'customer' ? 'Customer' : '')),
        poRefId,
        grnRefId: firstGrnId || '',
        grnNo: linkedGrnNos || '',
        qty: finalQty,
        materialSourceType: sourceType,
        consumableItemId: consumableItemId,
        consumableQty: consumableQty,
        consumableThan: consumableThan,
        hasTransporter,
        hasLocalFreight,
        freightPaymentType,
        transporterId: hasTransporter === 'Yes' ? transporterId : '',
        transporterName: hasTransporter === 'Yes' ? (transporterObj ? transporterObj.name : '') : '',
        lrNo: hasTransporter === 'Yes' ? lrNo : '',
        transportPkgCount: hasTransporter === 'Yes' ? parseInt(document.getElementById('outward-transport-pkg-count').value) || 0 : 0,
        transportLabour: (hasTransporter === 'Yes' && document.getElementById('outward-transport-labour').value.trim()) ? parseFloat(document.getElementById('outward-transport-labour').value) || 0 : null,
        taxiName: hasLocalFreight === 'Yes' ? taxiName : '',
        vehicleNo: (hasLocalFreight === 'Yes' || hasTransporter === 'Yes') ? vehicleNo : '',
        place,
        customerId,
        customerName: (db.customers.find(c => c.id === customerId) || {}).name || (firstGrn ? firstGrn.customerName : ''),
        custChallanNo: linkedCustChallanNos || '',
        grnLinks: currentOutwardLinks,
        dispatchedPackages: currentOutwardPackages,
        convertedLog: JSON.parse(JSON.stringify(window.grnConvertedLog || {})),
        packageSlips: (function() {
            if (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered') {
                const slips = [];
                document.querySelectorAll('.outward-embroidery-row').forEach(row => {
                    const itemName = row.querySelector('.outward-emb-item-name').value;
                    const than = parseFloat(row.querySelector('.outward-emb-than').value) || 0;
                    const conversion = parseFloat(row.querySelector('.outward-emb-conversion').value) || 0;
                    const qty = parseFloat(row.querySelector('.outward-emb-qty').value) || 0;
                    slips.push({
                        fabricType: itemName,
                        itemName: itemName,
                        pkgCount: than,
                        than: than,
                        conversion: conversion,
                        qty: qty
                    });
                });
                return slips;
            }
            return [];
        })(),
        remarks: (function() {
            let rText = encodeMetadataToRemarks(wizardRemarks, '__CONVERTED_LOG__', window.grnConvertedLog || {});
            if (machineNo) {
                rText = encodeMetadataToRemarks(rText, '__MACHINE_METADATA__', { machineNo });
            }
            if (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer' && outwardWizardState.subType === 'embroidered') {
                const usedList = [];
                document.querySelectorAll('.outward-fabric-used-row').forEach(row => {
                    const isManual = row.getAttribute('data-is-manual') === 'true';
                    const grnId = row.getAttribute('data-grn-id') || '';
                    let grnNo = '';
                    let fabricType = '';
                    if (isManual) {
                        grnNo = row.querySelector('.outward-fabric-used-manual-challan')?.value?.trim() || '';
                        fabricType = row.querySelector('.outward-fabric-used-manual-fabric')?.value?.trim() || '';
                    } else {
                        grnNo = row.querySelector('td:first-child')?.textContent?.trim() || '';
                        fabricType = row.getAttribute('data-fabric-type') || '';
                    }
                    const than = parseFloat(row.querySelector('.outward-fabric-used-than').value) || 0;
                    const conversion = parseFloat(row.querySelector('.outward-fabric-used-conversion').value) || 0;
                    const qty = parseFloat(row.querySelector('.outward-fabric-used-qty').value) || 0;
                    usedList.push({
                        grnId,
                        grnNo,
                        fabricType,
                        than,
                        conversion,
                        qty
                    });
                });
                rText += `\n[FABRIC_USED:${JSON.stringify(usedList)}]`;
            }
            if (editId) {
                const existingOutward = (db.outwards || []).find(o => o.id === editId);
                if (existingOutward) {
                    const syncInfo = window.getRamaSyncInfo ? window.getRamaSyncInfo(existingOutward) : { isSynced: false, isEdited: false };
                    const wasRamaSynced = syncInfo.isSynced || syncInfo.isEdited;

                    if (wasRamaSynced) {
                        const oldHash = window.getTransportDetailsHash ? window.getTransportDetailsHash(existingOutward) : '';
                        const tempNewOutward = {
                            transporterId: hasTransporter === 'Yes' ? transporterId : '',
                            transporterName: hasTransporter === 'Yes' ? (transporterObj ? transporterObj.name : '') : '',
                            lrNo: hasTransporter === 'Yes' ? lrNo : '',
                            vehicleNo: (hasLocalFreight === 'Yes' || hasTransporter === 'Yes') ? vehicleNo : '',
                            taxiName: hasLocalFreight === 'Yes' ? taxiName : '',
                            isLocalFreight: hasLocalFreight,
                            hasTransporter: hasTransporter,
                            transportPkgCount: hasTransporter === 'Yes' ? parseInt(document.getElementById('outward-transport-pkg-count').value) || 0 : 0,
                            transportLabour: (hasTransporter === 'Yes' && document.getElementById('outward-transport-labour').value.trim()) ? parseFloat(document.getElementById('outward-transport-labour').value) || 0 : null,
                            remarks: rText
                        };
                        const newHash = window.getTransportDetailsHash ? window.getTransportDetailsHash(tempNewOutward) : '';

                        if (oldHash !== newHash) {
                            const nowIso = new Date().toISOString();
                            const activeUser = (typeof currentUser !== 'undefined' && currentUser) ? (currentUser.displayName || currentUser.username || 'User') : 'Admin';
                            const editTagData = { at: nowIso, by: activeUser };
                            const editTag = `[RAMA_EDITED:${JSON.stringify(editTagData)}]`;

                            if (rText.includes('[RAMA_EDITED:')) {
                                rText = rText.replace(/\[RAMA_EDITED:[\s\S]*?\]/, editTag);
                            } else {
                                rText += `\n${editTag}`;
                            }

                            if (window.supabase) {
                                window.supabase.from('rama_freight_billing')
                                    .update({
                                        sync_state: 'edited',
                                        updated_at: nowIso,
                                        transporter_taxi_name: window.getTaxiNameFromRecord ? window.getTaxiNameFromRecord(tempNewOutward) : (taxiName || 'Rama Logistics'),
                                        vehicle_no: vehicleNo || '-',
                                        lr_no: lrNo || '-',
                                        pkg_count: tempNewOutward.transportPkgCount
                                    })
                                    .eq('voucher_type', 'Outward')
                                    .eq('voucher_id', String(existingOutward.id))
                                    .then(({ error }) => {
                                        if (error) console.warn("Could not update rama_freight_billing edit state:", error);
                                    });
                            }

                            showToast('Transport details modified on a synced voucher. Marked for Re-sync to RAMA LOGISTICS.', 'warning');
                        } else if (existingOutward.remarks && existingOutward.remarks.includes('[RAMA_SYNCED:')) {
                            const matchSync = existingOutward.remarks.match(/\[RAMA_SYNCED:[\s\S]*?\]/);
                            if (matchSync && !rText.includes('[RAMA_SYNCED:')) {
                                rText = rText ? (rText + '\n' + matchSync[0]) : matchSync[0];
                            }
                        }
                    } else if (existingOutward.remarks && existingOutward.remarks.includes('[RAMA_SYNCED:')) {
                        const matchSync = existingOutward.remarks.match(/\[RAMA_SYNCED:[\s\S]*?\]/);
                        if (matchSync && !rText.includes('[RAMA_SYNCED:')) {
                            rText = rText ? (rText + '\n' + matchSync[0]) : matchSync[0];
                        }
                    }
                }
            }
            rText += `\n${transportStr}`;
            return rText;
        })(),
        syncedToRama: editId ? (db.outwards?.find(o => o.id === editId)?.syncedToRama || false) : false,
        linked_so_id,
        linked_so_number,
        linked_po_id,
        linked_po_number,
        machineNo,
        rate
    };

    const validationResult = window.validateNegativeInventory('outwards', data, editId);
    if (!validationResult.valid) {
        showToast(validationResult.error, 'error');
        return;
    }

    await saveToSupabase('outwards', data);
        window.triggerGoogleSheetsSync('outward', data, editId ? 'edit' : 'create');
        
        // Handle linked PO's vendor job work challan no
        if (editId) {
            const previousOutward = db.outwards.find(o => o.id === editId);
            if (previousOutward && previousOutward.poRefId && previousOutward.poRefId !== poRefId) {
                const prevPO = db.pos.find(p => p.id === previousOutward.poRefId);
                if (prevPO && ((prevPO.poType || 'vendor') === 'vendor' || prevPO.poType === 'inhouse')) {
                    const poNumber = prevPO.number;
                    const matchingPOs = db.pos.filter(p => p.number === poNumber);
                    
                    const otherOutwards = db.outwards.filter(o => o.id !== editId && o.poRefId === previousOutward.poRefId);
                    const uniqueChallans = [...new Set(otherOutwards.map(o => o.number))].filter(Boolean).join(', ');
                    
                    for (const mpo of matchingPOs) {
                        mpo.vendorJobWorkChallanNo = uniqueChallans;
                        await saveToSupabase('purchase_orders', mpo);
                    }
                }
            }
        }

        if (poRefId) {
            const linkedPO = db.pos.find(p => p.id === poRefId);
            if (linkedPO && ((linkedPO.poType || 'vendor') === 'vendor' || linkedPO.poType === 'inhouse')) {
                const poNumber = linkedPO.number;
                const matchingPOs = db.pos.filter(p => p.number === poNumber);
                
                const allOutwards = db.outwards.filter(o => {
                    if (o.id === editId) return false;
                    if (!o.poRefId) return false;
                    const lpo = db.pos.find(p => p.id === o.poRefId || p.number === o.poRefId);
                    return lpo && lpo.number === poNumber;
                });
                
                const challanNumbers = allOutwards.map(o => o.number);
                challanNumbers.push(number);
                
                const uniqueChallans = [...new Set(challanNumbers)].filter(Boolean).join(', ');
                
                for (const mpo of matchingPOs) {
                    mpo.vendorJobWorkChallanNo = uniqueChallans;
                    await saveToSupabase('purchase_orders', mpo);
                }
            }
        }

        if (editId) {
            const idxRaw = rawDB.outwards.findIndex(o => o.id === editId);
            if (idxRaw !== -1) rawDB.outwards[idxRaw] = data;
        } else {
            rawDB.outwards.push(data);
        }
        applyFinancialYearFilters();

        renderOutwardTable();
        if (typeof window.refreshAllLogisticsTables === 'function') window.refreshAllLogisticsTables();
        if (typeof renderPOTable === 'function') if (typeof window.renderPOTable === 'function') window.renderPOTable();
        
        // Show success prompt modal
        document.getElementById('outward-success-number').textContent = data.number;
        
        document.getElementById('btn-outward-success-print').onclick = function() {
            printOutward(data.id);
        };

        const state = parseOutwardWizardState(data);
        const btnMakeOutwardVoucher = document.getElementById('outward-success-modal')?.querySelector('#btn-outward-success-make-voucher');
        if (btnMakeOutwardVoucher) {
            btnMakeOutwardVoucher.style.display = 'flex';
            if (state.source === 'vendor' || state.type === 'jobworker') {
                btnMakeOutwardVoucher.innerHTML = '=� Create Purchase Voucher';
                btnMakeOutwardVoucher.onclick = function() {
                    closeModal('outward-success-modal');
                    closeModal('outward-modal', true);
                    window.pendingOutwardIdForVoucher = data.id;
                    openGenericTxModal('voucher');
                };
            } else {
                btnMakeOutwardVoucher.innerHTML = '=� Create Sales Invoice';
                btnMakeOutwardVoucher.onclick = function() {
                    closeModal('outward-success-modal');
                    closeModal('outward-modal', true);
                    window.pendingOutwardIdForInvoice = data.id;
                    openGenericTxModal('invoice');
                };
            }
        }
        
        const handleClose = function() {
            closeModal('outward-success-modal');
            closeModal('outward-modal', true);
            if (window.shouldPromptFreightDetails && window.shouldPromptFreightDetails(data, 'outward')) {
                window.openFreightPopModal(data.id, 'outward');
            }
        };
        const outwardSuccessModal = document.getElementById('outward-success-modal');
        if (outwardSuccessModal) {
            const closeBtn = outwardSuccessModal.querySelector('.modal-close');
            if (closeBtn) closeBtn.onclick = handleClose;
            const doneBtn = outwardSuccessModal.querySelector('.modal-footer .btn');
            if (doneBtn) doneBtn.onclick = handleClose;
        }

        openModal('outward-success-modal');
    } catch(e) {
        console.error("Error saving outward:", e);
    } finally {
        window._isSavingOutward = false;
        if (saveBtn) {
            saveBtn.disabled = false;
            saveBtn.innerHTML = origBtnHtml;
        }
    }
}

window.getPOPartyName = function(p) {
    if (!p) return '-';
    if (p.poType === 'inhouse') {
        if (p.customerId) {
            const c = (db.customers || []).find(x => String(x.id) === String(p.customerId));
            if (c && c.name) return c.name;
        }
        return (p.customerName && p.customerName !== 'Pending') ? p.customerName : 'In-House';
    }
    if (p.vendorId) {
        const v = (db.vendors || []).find(x => String(x.id) === String(p.vendorId));
        if (v && v.name) return v.name;
    }
    if (p.customerId) {
        const c = (db.customers || []).find(x => String(x.id) === String(p.customerId));
        if (c && c.name) return c.name;
    }
    let name = (p.vendorName || p.customerName || '').trim();
    if (name && name !== 'Customer' && name !== 'Vendor' && name !== 'Pending') return name;
    if (p.isPlaceholder || p.status === 'Cancelled' || (p.remarks || '').trim().toLowerCase().startsWith('cancelled')) {
        return 'Cancelled';
    }
    return '-';
};

window.getReportVendorDisplay = function(poNums, defaultVendor) {
    let poList = [];
    if (Array.isArray(poNums)) {
        poList = poNums;
    } else if (typeof poNums === 'string' && poNums.trim()) {
        poList = poNums.split(',').map(s => s.trim());
    }
    
    const vendorNames = [];
    let hasInhousePo = false;
    const customers = [...(db.customers || []), ...(window.crossCompanyCustomers || [])];
    const customerNamesList = customers.map(c => (c.name || '').toLowerCase().trim()).filter(Boolean);

    poList.forEach(numOrId => {
        if (!numOrId) return;
        const po = (db.pos || []).find(p => p.number === numOrId || p.id === numOrId || String(p.number).toLowerCase() === String(numOrId).toLowerCase());
        if (po) {
            if (po.poType === 'inhouse') {
                hasInhousePo = true;
                vendorNames.push('In-House');
            }
            if (po.vendorId) {
                const vendors = [...(db.vendors || []), ...(window.crossCompanyVendors || [])];
                const v = vendors.find(x => String(x.id) === String(po.vendorId));
                if (v && v.name && v.name !== 'Pending') vendorNames.push(v.name);
            } else if (po.vendorName) {
                const vName = po.vendorName.trim();
                if (vName && vName !== 'Vendor' && vName !== 'Customer' && vName !== 'Pending' && vName.toLowerCase() !== 'in-house' && vName.toLowerCase() !== 'inhouse' && !customerNamesList.includes(vName.toLowerCase())) {
                    vendorNames.push(vName);
                }
            }
        }
    });

    if (hasInhousePo && !vendorNames.includes('In-House')) {
        vendorNames.push('In-House');
    }

    const uniqueVendors = [...new Set(vendorNames.filter(Boolean))];
    if (uniqueVendors.length > 0) {
        uniqueVendors.sort((a, b) => {
            if (a === 'In-House') return 1;
            if (b === 'In-House') return -1;
            return a.localeCompare(b);
        });
        return uniqueVendors.join(', ');
    }

    if (defaultVendor && defaultVendor !== '-' && defaultVendor !== 'Vendor' && defaultVendor !== 'Customer' && defaultVendor !== 'Pending') {
        const defTrim = String(defaultVendor).trim();
        if (defTrim.toLowerCase() === 'in-house' || defTrim.toLowerCase() === 'inhouse') {
            return 'In-House';
        }
        if (defTrim !== 'Pending' && !customerNamesList.includes(defTrim.toLowerCase())) {
            return defTrim;
        }
    }
    return '-';
};

window.getGRNPartyName = function(g) {
    if (!g) return '-';
    const customers = [
        ...(typeof rawDB !== 'undefined' && rawDB?.customers || []),
        ...(typeof masterDB !== 'undefined' && masterDB?.customers || []),
        ...(typeof defaultDB !== 'undefined' && defaultDB?.customers || []),
        ...(db.customers || []),
        ...(window.crossCompanyCustomers || [])
    ];
    const vendors = [
        ...(typeof rawDB !== 'undefined' && rawDB?.vendors || []),
        ...(typeof masterDB !== 'undefined' && masterDB?.vendors || []),
        ...(typeof defaultDB !== 'undefined' && defaultDB?.vendors || []),
        ...(db.vendors || []),
        ...(window.crossCompanyVendors || [])
    ];

    const isRawIdFormat = (str) => {
        if (!str || typeof str !== 'string') return false;
        const s = str.trim();
        if (s.startsWith('v_') || s.startsWith('vend_') || s.startsWith('cust_') || s.startsWith('c_')) return true;
        if (/^[a-z0-9_-]{8,32}$/i.test(s) && !s.includes(' ')) return true;
        return false;
    };

    const resolveVendorOnly = (val) => {
        if (!val) return '';
        const str = String(val).trim();
        if (!str || str === 'Customer' || str === 'Vendor' || str === 'Pending' || str === '-') return '';
        if (str.toLowerCase() === 'inhouse' || str.toLowerCase() === 'in_house') return 'In House';
        
        const v = vendors.find(x => String(x.id) === str || String(x.name).toLowerCase().trim() === str.toLowerCase().trim());
        if (v && v.name && !isRawIdFormat(v.name)) return v.name;
        
        const isCust = customers.some(x => String(x.id) === str || String(x.name).toLowerCase().trim() === str.toLowerCase().trim());
        if (isCust) return '';
        if (isRawIdFormat(str)) return '';
        return str;
    };

    const resolveCustomerOnly = (val) => {
        if (!val) return '';
        const str = String(val).trim();
        if (!str || str === 'Customer' || str === 'Vendor' || str === 'Pending' || str === '-') return '';
        
        const c = customers.find(x => String(x.id) === str || String(x.name).toLowerCase().trim() === str.toLowerCase().trim());
        if (c && c.name && !isRawIdFormat(c.name)) return c.name;
        
        const isVend = vendors.some(x => String(x.id) === str || String(x.name).toLowerCase().trim() === str.toLowerCase().trim());
        if (isVend) return '';
        if (isRawIdFormat(str)) return '';
        return str;
    };

    const docNo = String(g.grnNo || g.number || g.partyDocNo || '').toUpperCase();
    const grnType = String(g.type || g.grnType || g.source || '').toLowerCase();
    
    const isVendorSource = docNo.includes('/V/') || docNo.includes('/CON/') || docNo.includes('/FAB/') || docNo.startsWith('GRN/V') || docNo.startsWith('GRN/CON') || docNo.startsWith('GRN/FAB') || grnType === 'vendor' || grnType.includes('vend') || grnType.includes('consumable') || g.source === 'vendor' || !!(g.vendorId || g.vendor_id || g.vendorName);

    if (isVendorSource) {
        let vRes = resolveVendorOnly(g.vendorId || g.vendor_id || g.vendor);
        if (!vRes) vRes = resolveVendorOnly(g.vendorName || g.vendor_name);
        if (!vRes) {
            const poId = g.poRefId || g.linked_po_id || g.poRef || g.poId;
            if (poId) {
                const po = (db.pos || []).find(p => p.id === poId || p.number === poId);
                if (po) vRes = resolveVendorOnly(po.vendorId || po.vendor || po.vendorName);
            }
        }
        if (vRes) return vRes;
        const fallback = resolveVendorOnly(g.partyName || g.party || g.supplier || g.supplierName);
        if (fallback) return fallback;
    }

    // Try customer resolution
    let cRes = resolveCustomerOnly(g.customerId || g.customer_id || g.customer);
    if (!cRes) cRes = resolveCustomerOnly(g.customerName || g.customer_name);
    if (!cRes) {
        const soId = g.linkedSoId || g.soRefId || g.soId;
        if (soId) {
            const so = (db.salesOrders || []).find(s => s.id === soId || s.number === soId);
            if (so) cRes = resolveCustomerOnly(so.customerId || so.customer || so.customerName);
        }
    }
    if (cRes) return cRes;
    const fallbackCust = resolveCustomerOnly(g.partyName || g.party || g.supplier || g.supplierName);
    if (fallbackCust) return fallbackCust;

    // Last resort: direct string matching on vendor / party fields
    const directName = g.vendorName || g.partyName || g.customerName || g.supplierName || g.vendor || g.party;
    if (directName && typeof directName === 'string' && !directName.startsWith('v_') && !directName.startsWith('c_') && directName.trim() !== '-' && directName.trim() !== 'Customer' && directName.trim() !== 'Vendor') {
        return directName.trim();
    }

    if (g.isPlaceholder || g.status === 'Cancelled' || (g.remarks || '').trim().toLowerCase().startsWith('cancelled')) {
        return 'Cancelled';
    }
    return '-';
};

window.getOutwardPartyName = function(out) {
    if (!out) return '-';
    const wizard = typeof parseOutwardWizardState === 'function' ? parseOutwardWizardState(out) : {};

    const customers = [
        ...(typeof rawDB !== 'undefined' && rawDB?.customers || []),
        ...(typeof masterDB !== 'undefined' && masterDB?.customers || []),
        ...(typeof defaultDB !== 'undefined' && defaultDB?.customers || []),
        ...(db.customers || []),
        ...(window.crossCompanyCustomers || [])
    ];
    const vendors = [
        ...(typeof rawDB !== 'undefined' && rawDB?.vendors || []),
        ...(typeof masterDB !== 'undefined' && masterDB?.vendors || []),
        ...(typeof defaultDB !== 'undefined' && defaultDB?.vendors || []),
        ...(db.vendors || []),
        ...(window.crossCompanyVendors || [])
    ];

    const isRawIdFormat = (str) => {
        if (!str || typeof str !== 'string') return false;
        const s = str.trim();
        if (s.startsWith('v_') || s.startsWith('vend_') || s.startsWith('cust_') || s.startsWith('c_')) return true;
        if (/^[a-z0-9_-]{8,32}$/i.test(s) && !s.includes(' ')) return true;
        return false;
    };

    const resolveVendorOnly = (val) => {
        if (!val) return '';
        const str = String(val).trim();
        if (!str || str === 'Customer' || str === 'Vendor' || str === 'Pending' || str === '-') return '';
        if (str.toLowerCase() === 'inhouse' || str.toLowerCase() === 'in_house') return 'In House';
        
        const v = vendors.find(x => String(x.id) === str || String(x.name).toLowerCase().trim() === str.toLowerCase().trim());
        if (v && v.name && !isRawIdFormat(v.name)) return v.name;
        
        const isCust = customers.some(x => String(x.id) === str || String(x.name).toLowerCase().trim() === str.toLowerCase().trim());
        if (isCust) return '';
        if (isRawIdFormat(str)) return '';
        return str;
    };

    const resolveCustomerOnly = (val) => {
        if (!val) return '';
        const str = String(val).trim();
        if (!str || str === 'Customer' || str === 'Vendor' || str === 'Pending' || str === '-') return '';
        
        const c = customers.find(x => String(x.id) === str || String(x.name).toLowerCase().trim() === str.toLowerCase().trim());
        if (c && c.name && !isRawIdFormat(c.name)) return c.name;
        
        const isVend = vendors.some(x => String(x.id) === str || String(x.name).toLowerCase().trim() === str.toLowerCase().trim());
        if (isVend) return '';
        if (isRawIdFormat(str)) return '';
        return str;
    };

    const docNo = String(out.number || out.outwardNo || out.partyDocNo || '').toUpperCase();
    const isVendorSource = docNo.includes('/V/') || docNo.startsWith('FI/V') || docNo.startsWith('OUT/V') || wizard.source === 'vendor' || out.source === 'vendor';

    if (isVendorSource) {
        let vRes = resolveVendorOnly(out.vendorId || out.vendor_id || out.vendor || wizard.vendorId);
        if (!vRes) vRes = resolveVendorOnly(out.vendorName || out.vendor_name || wizard.vendorName);
        if (!vRes) {
            const poId = out.linked_po_id || out.poRefId || out.po_ref;
            if (poId) {
                const po = [...(db.pos || []), ...(window.crossCompanyPos || [])].find(p => p.id === poId || p.number === poId);
                if (po) vRes = resolveVendorOnly(po.vendorId || po.vendor || po.vendorName);
            }
        }
        if (vRes) return vRes;
        const fallback = resolveVendorOnly(out.partyName || out.party);
        if (fallback) return fallback;
    } else {
        let cRes = resolveCustomerOnly(out.customerId || out.customer_id || out.customer || wizard.customerId);
        if (!cRes) cRes = resolveCustomerOnly(out.customerName || out.customer_name || wizard.customerName);
        if (!cRes) {
            const soId = out.linked_so_id || out.linkedSoId || out.soRefId || out.soRef;
            if (soId) {
                const so = [...(db.salesOrders || []), ...(window.crossCompanySalesOrders || [])].find(s => s.id === soId || s.number === soId);
                if (so) cRes = resolveCustomerOnly(so.customerId || so.customer || so.customerName);
            }
        }
        if (cRes) return cRes;
        const fallback = resolveCustomerOnly(out.partyName || out.party);
        if (fallback) return fallback;
    }

    if (out.isPlaceholder || out.status === 'Cancelled' || (out.remarks || '').trim().toLowerCase().startsWith('cancelled')) {
        return 'Cancelled';
    }
    return '-';
};

function isOutwardConsumable(o) {
    if (!o || o.isPlaceholder) return false;
    return o.type === 'consumable' || 
           (o.outwardNo && String(o.outwardNo).toUpperCase().startsWith('OUT/CON')) || 
           (o.number && String(o.number).toUpperCase().startsWith('OUT/CON')) || 
           o.poType === 'consumable' || 
           o.outward_class === 'consumable';
}

window.getOutwardItemName = function(o) {
    if (!o || o.isPlaceholder) return '-';

    if (isOutwardConsumable(o)) {
        let name = o.itemName;
        if (!name || name.toLowerCase() === 'consumable' || name.toLowerCase() === 'fabric') name = o.yarnName;
        if (!name && Array.isArray(o.packageSlips) && o.packageSlips.length > 0) {
            name = o.packageSlips[0].itemName || o.packageSlips[0].yarnName || o.packageSlips[0].fabricType;
        }
        if (!name && Array.isArray(o.items) && o.items.length > 0) {
            const it = o.items[0];
            const masterItem = it.itemId ? (db.items || []).find(x => String(x.id) === String(it.itemId)) : null;
            name = (masterItem ? masterItem.name : null) || it.itemName || it.item_name || it.yarnName;
        }
        if (!name) name = o.consumable_type;
        if (name && name !== '-' && name.toLowerCase() !== 'consumable') return name;
        return '-';
    }

    const isInvalidPlaceholder = (n) => {
        if (!n || typeof n !== 'string') return true;
        const cl = n.trim().toLowerCase();
        return !cl || cl === '-' || cl === 'fabric' || cl === 'other item' || cl === 'consumable' || cl === 'plain fabric';
    };

    // 1. Priority: Linked Sales Order (SO)
    const allSos = [...(db.salesOrders || []), ...(rawDB.salesOrders || [])];
    const soRefList = [o.linked_so_id, o.linkedSoId, o.soRefId, o.soNumber, o.soRef].filter(Boolean);
    if (o.poRefId || o.poNumber) {
        const po = (db.pos || []).find(p => p.id === o.poRefId || p.number === o.poNumber);
        if (po) {
            soRefList.push(po.linked_so_id, po.soRefId, po.soNumber, po.soRef);
        }
    }
    for (const ref of soRefList) {
        const idStr = String(ref);
        const so = allSos.find(s => String(s.id) === idStr || String(s.number) === idStr);
        if (so) {
            let soName = so.designNumber || so.design || so.designNo;
            if (!soName && Array.isArray(so.items) && so.items.length > 0) {
                const it = so.items[0];
                const master = it.itemId ? (db.items || []).find(x => String(x.id) === String(it.itemId)) : null;
                soName = (master ? master.name : null) || it.itemName || it.item_name || it.processName;
            }
            if (soName && !isInvalidPlaceholder(soName)) return soName.trim();
        }
    }

    if (o.fabricType && isGRNItemNameString(o.fabricType)) {
        return o.fabricType.trim();
    }

    const fabQuality = (o.fabricType && !isGRNItemNameString(o.fabricType)) ? o.fabricType.trim().toLowerCase() : '';

    const des = o.design || o.designNumber || o.designNo || o.processName;
    if (des && des !== '-' && des.trim().toLowerCase() !== fabQuality && !isKnownFabricType(des)) return des;

    if (Array.isArray(o.items) && o.items.length > 0) {
        for (const it of o.items) {
            if (!it) continue;
            const masterItem = (it.itemId || it.designId) ? (db.items || []).find(x => String(x.id) === String(it.itemId || it.designId)) : null;
            if (masterItem && masterItem.name && masterItem.name.trim().toLowerCase() !== fabQuality && !isKnownFabricType(masterItem.name)) {
                return masterItem.name;
            }
            const iItem = it.designNumber || it.processName || it.itemName || it.item_name;
            if (iItem && iItem !== '-' && iItem.trim().toLowerCase() !== fabQuality && iItem.toLowerCase() !== 'fabric' && iItem.toLowerCase() !== 'other item' && !isKnownFabricType(iItem)) {
                return iItem;
            }
        }
    }

    if (Array.isArray(o.packageSlips) && o.packageSlips.length > 0) {
        const pItem = o.packageSlips[0].designNumber || o.packageSlips[0].designNo || o.packageSlips[0].itemName;
        if (pItem && pItem !== '-' && pItem.trim().toLowerCase() !== fabQuality && pItem.toLowerCase() !== 'fabric' && pItem.toLowerCase() !== 'other item' && !isKnownFabricType(pItem)) return pItem;
    }

    if (o.poRefId || o.poNumber) {
        const po = (db.pos || []).find(p => p.id === o.poRefId || p.number === o.poNumber);
        if (po) {
            const poItem = po.design || po.designNumber || (po.items && po.items[0]?.itemName);
            if (poItem && poItem !== '-' && poItem.trim().toLowerCase() !== fabQuality && !isKnownFabricType(poItem)) return poItem;
        }
    }

    if (o.grnNo || o.grnRefId) {
        const grn = (db.grns || []).find(g => g.grnNo === o.grnNo || g.number === o.grnNo || g.id === o.grnRefId);
        if (grn) {
            const grnItem = window.getGRNItemName ? window.getGRNItemName(grn) : (grn.designNumber || grn.design);
            if (grnItem && grnItem !== '-' && grnItem.trim().toLowerCase() !== fabQuality && !isKnownFabricType(grnItem)) return grnItem;
        }
    }

    if (o.itemName && o.itemName !== '-' && o.itemName.trim().toLowerCase() !== fabQuality && o.itemName.toLowerCase() !== 'fabric' && o.itemName.toLowerCase() !== 'other item' && o.itemName.toLowerCase() !== 'consumable' && !isKnownFabricType(o.itemName)) {
        return o.itemName;
    }

    return '-';
};

window.getOutwardFabricName = function(o) {
    if (!o || o.isPlaceholder) return '-';
    if (isOutwardConsumable(o)) return '-';

    let foundFabs = [];

    const isInvalidPlaceholder = (n) => {
        if (!n || typeof n !== 'string') return true;
        const cl = n.trim().toLowerCase();
        return !cl || cl === '-' || cl === 'fabric' || cl === 'other item' || cl === 'consumable' || cl === 'plain fabric';
    };

    const resolveFabFromUsedItem = (item) => {
        if (!item) return '';
        let fab = item.fabricType || item.fabric_type || item.fabricName || '';
        if (fab && !isGRNItemNameString(fab) && !isInvalidPlaceholder(fab)) return fab.trim();
        
        const refId = item.issueId || item.issueNo || item.grnId || item.grnNo;
        if (refId) {
            const out = (db.outwards || []).find(ow => String(ow.id) === String(refId) || String(ow.number) === String(refId) || String(ow.partyDocNo) === String(refId));
            if (out) {
                const f = out.fabricType && !isGRNItemNameString(out.fabricType) && !isInvalidPlaceholder(out.fabricType) ? out.fabricType : '';
                if (f) return f.trim();
                if (Array.isArray(out.packageSlips)) {
                    for (const ps of out.packageSlips) {
                        if (ps && ps.fabricType && !isGRNItemNameString(ps.fabricType) && !isInvalidPlaceholder(ps.fabricType)) return ps.fabricType.trim();
                    }
                }
            }
            const grn = (db.grns || []).find(gr => String(gr.id) === String(refId) || String(gr.number) === String(refId) || String(gr.partyDocNo) === String(refId));
            if (grn) {
                const f = grn.fabricType && !isGRNItemNameString(grn.fabricType) && !isInvalidPlaceholder(grn.fabricType) ? grn.fabricType : '';
                if (f) return f.trim();
                if (Array.isArray(grn.packageSlips)) {
                    for (const ps of grn.packageSlips) {
                        if (ps && ps.fabricType && !isGRNItemNameString(ps.fabricType) && !isInvalidPlaceholder(ps.fabricType)) return ps.fabricType.trim();
                    }
                }
            }
        }
        return '';
    };

    if (o.remarks && typeof o.remarks === 'string' && o.remarks.includes('[FABRIC_USED:')) {
        try {
            const match = o.remarks.match(/\[FABRIC_USED:(\[.*?\])\]/) || o.remarks.match(/\[FABRIC_USED:(\{.*?\})\]/);
            if (match) {
                const list = JSON.parse(match[1]);
                const arr = Array.isArray(list) ? list : [list];
                arr.forEach(item => {
                    const f = resolveFabFromUsedItem(item);
                    if (f) foundFabs.push(f);
                });
            }
        } catch(e){}
    }

    if (o.fabricType && !isGRNItemNameString(o.fabricType) && !isInvalidPlaceholder(o.fabricType)) {
        foundFabs.push(o.fabricType.trim());
    }

    if (Array.isArray(o.packageSlips)) {
        o.packageSlips.forEach(s => {
            if (s && s.fabricType && !isGRNItemNameString(s.fabricType) && !isInvalidPlaceholder(s.fabricType)) {
                foundFabs.push(s.fabricType.trim());
            }
        });
    }

    if (Array.isArray(o.items)) {
        o.items.forEach(i => {
            if (i && i.fabricType && !isGRNItemNameString(i.fabricType) && !isInvalidPlaceholder(i.fabricType)) {
                foundFabs.push(i.fabricType.trim());
            }
        });
    }

    if (o.grnNo || o.grnRefId) {
        const grn = (db.grns || []).find(g => g.grnNo === o.grnNo || g.number === o.grnNo || g.id === o.grnRefId);
        if (grn) {
            const grnFab = window.getGRNFabricName ? window.getGRNFabricName(grn) : (grn.fabricType && !isGRNItemNameString(grn.fabricType) ? grn.fabricType : '');
            if (grnFab && grnFab !== '-') foundFabs.push(grnFab.trim());
        }
    }

    if (o.poRefId || o.poNumber) {
        const po = (db.pos || []).find(p => p.id === o.poRefId || p.number === o.poNumber);
        if (po && po.fabricType && !isGRNItemNameString(po.fabricType) && !isInvalidPlaceholder(po.fabricType)) {
            foundFabs.push(po.fabricType.trim());
        }
    }

    const unique = [...new Set(foundFabs)].filter(Boolean);
    return unique.length > 0 ? unique.join(', ') : '-';
};

function renderOutwardTable() {
    const thead = document.getElementById('tx-outward-table-head');
    const tbody = document.getElementById('tx-outward-table-body');
    if (!tbody) return;
    db.outwards = db.outwards || [];

    const isCustomer = (outwardWizardState.type === 'fabric_issue_challan' && outwardWizardState.source === 'customer');
    const isInhouse = outwardWizardState.type === 'inhouse';

    window.renderDynamicHeader('outward', 'tx-outward-table-head');
    const config = window.getTableColumnConfig('outward');

    let typePrefix = 'JW';
    if (outwardWizardState.type === 'fabric_issue_challan') {
        if (outwardWizardState.source === 'customer') {
            typePrefix = outwardWizardState.subType === 'plain' ? 'FI/C/PF' : 'FI/C/EM';
        } else {
            typePrefix = outwardWizardState.subType === 'plain' ? 'FI/V/PF' : 'FI/V/EM';
        }
    } else if (outwardWizardState.type === 'inhouse') {
        typePrefix = 'FI/INH';
    } else if (outwardWizardState.type === 'jobworker') {
        typePrefix = 'FI/JW';
    }

    const activeOutwards = db.outwards.filter(o => {
        const state = parseOutwardWizardState(o);
        if (state.type !== outwardWizardState.type) return false;
        if (outwardWizardState.type === 'fabric_issue_challan') {
            if (state.source !== outwardWizardState.source) return false;
            if (state.subType !== outwardWizardState.subType) return false;
        }
        return true;
    });

    const baseNumbersMap = new Map();
    activeOutwards.forEach(o => {
        const base = getBaseNumberFromOutward(o.number, typePrefix);
        if (base !== null) {
            if (!baseNumbersMap.has(base)) {
                baseNumbersMap.set(base, []);
            }
            baseNumbersMap.get(base).push(o);
        }
    });

    let maxBase = 0;
    for (let base of baseNumbersMap.keys()) {
        if (base > maxBase) maxBase = base;
    }

    const fySuffix = (financialYears[currentFinancialYear] || {}).suffix || '/26-27';
    const cleanSuffix = fySuffix.startsWith('/') ? fySuffix.substring(1) : fySuffix;

    const itemsToRender = [];
    for (let i = 1; i <= maxBase; i++) {
        if (baseNumbersMap.has(i)) {
            itemsToRender.push(...baseNumbersMap.get(i));
        } else {
            itemsToRender.push({
                id: `placeholder_out_${i}`,
                number: getDocumentNumber(typePrefix, i),
                isPlaceholder: true,
                date: '',
                vendorName: 'Cancelled',
                customerName: 'Cancelled',
                poRefId: '',
                grnNo: '-',
                qty: 0,
                vehicleNo: '-',
                remarks: 'Missing Challan in series'
            });
        }
    }

    const searchVal = (document.getElementById('tx-outward-search')?.value || '').toLowerCase().trim();
    const dateFromInput = document.getElementById('tx-outward-date-from');
    const dateToInput = document.getElementById('tx-outward-date-to');
    const dateFrom = dateFromInput ? dateFromInput.value : '';
    const dateTo = dateToInput ? dateToInput.value : '';

    const filteredOutwards = itemsToRender.filter(o => {
        if (o.isPlaceholder) {
            if (!searchVal) return false;
            if (dateFrom || dateTo) return false;
        }
        if (dateFrom && o.date && o.date < dateFrom) return false;
        if (dateTo && o.date && o.date > dateTo) return false;

        if (!searchVal) return true;
        const num = (o.number || '').toLowerCase();
        const party = window.getOutwardPartyName(o).toLowerCase();
        const grn = (o.grnNo || '').toLowerCase();
        const item = window.getOutwardItemName(o).toLowerCase();
        const fabricType = window.getOutwardFabricName(o).toLowerCase();
        const partyOrderNo = (o.partyOrderNo || o.party_order_no || o.partyDocNo || o.poNo || o.poNumber || o.soRef || '').toLowerCase();
        const designNo = (o.designNumber || o.designNo || o.design || '').toLowerCase();
        const remarks = (o.remarks || '').toLowerCase();

        if (num.includes(searchVal) || party.includes(searchVal) || grn.includes(searchVal) ||
            item.includes(searchVal) || fabricType.includes(searchVal) || partyOrderNo.includes(searchVal) || designNo.includes(searchVal) ||
            remarks.includes(searchVal)) {
            return true;
        }

        if (o.items && Array.isArray(o.items)) {
            for (const it of o.items) {
                if (!it) continue;
                const itName = (it.itemName || it.item_name || it.processName || '').toLowerCase();
                const itDesign = (it.designNumber || it.designNo || '').toLowerCase();
                if (itName.includes(searchVal) || itDesign.includes(searchVal)) return true;
            }
        }
        return false;
    });

    // Apply sorting dynamically
    const sortConf = window.tableSortConfig?.outward || { field: 'number', order: 'desc' };
    const sortField = sortConf.field;
    const sortOrder = sortConf.order === 'asc' ? 1 : -1;
        filteredOutwards.sort((a, b) => {
        let valA = '';
        let valB = '';

        if (sortField === 'number') {
            const numA = getBaseNumberFromOutward(a.number, typePrefix) || 0;
            const numB = getBaseNumberFromOutward(b.number, typePrefix) || 0;
            return (numA - numB) * sortOrder;
        } else if (sortField === 'date') {
            valA = a.date ? new Date(a.date).getTime() : 0;
            valB = b.date ? new Date(b.date).getTime() : 0;
        } else if (sortField === 'partyName') {
            valA = window.getOutwardPartyName(a);
            valB = window.getOutwardPartyName(b);
        } else if (sortField === 'poRef') {
            const poA = a.poRefId ? db.pos.find(p => p.id === a.poRefId) : null;
            valA = poA ? poA.number : '';
            const poB = b.poRefId ? db.pos.find(p => p.id === b.poRefId) : null;
            valB = poB ? poB.number : '';
        } else if (sortField === 'grnNo') {
            valA = a.grnNo || '';
            valB = b.grnNo || '';
        } else if (sortField === 'itemName') {
            valA = window.getOutwardItemName(a);
            valB = window.getOutwardItemName(b);
        } else if (sortField === 'fabricType') {
            valA = window.getOutwardFabricName(a);
            valB = window.getOutwardFabricName(b);
        } else if (sortField === 'qty') {
            valA = Number(a.qty || 0);
            valB = Number(b.qty || 0);
        } else if (sortField === 'vehicleNo') {
            valA = a.vehicleNo || '';
            valB = b.vehicleNo || '';
        }

        if (typeof valA === 'number' && typeof valB === 'number') {
            return (valA - valB) * sortOrder;
        }
        return String(valA).localeCompare(String(valB)) * sortOrder;
    });

    const visibleCols = config.filter(c => {
        if (c.visible === false) return false;
        if (isInhouse && (c.key === 'vehicleNo' || c.key === 'partyName')) return false;
        return true;
    }).length;

    if (filteredOutwards.length === 0) {
        tbody.innerHTML = `<tr><td colspan="${visibleCols + 2}" class="empty-row">No Outward Challans found.</td></tr>`;
        return;
    }

    tbody.innerHTML = filteredOutwards.map(o => {
        const isPlaceholder = o.isPlaceholder;
        const status = o.status || 'Pending';
        const isCancelledOrPlaceholder = isPlaceholder || status.trim().toLowerCase() === 'cancelled';
        const cancelledHtml = '<span style="color: #ef4444; font-weight: bold; text-transform: uppercase;">CANCELLED</span>';
        
        if (isPlaceholder) {
            const hasEditPerm = checkPermission('outward', 'edit_cancelled'); // Outward falls under 'outward' key in txModules
            const tds = config.map(col => {
                if (col.visible === false) return '';
                if (isInhouse && (col.key === 'vehicleNo' || col.key === 'partyName')) return '';

                if (col.key === 'number') return `<td><strong>${checkPermission('outward', 'edit_cancelled') ? `<a href="#" onclick="openOutwardModal(null, '${o.number}')" style="color: var(--accent-red, #ef4444) !important;">${o.number}</a>` : `<span style="color: var(--accent-red, #ef4444) !important;">${o.number}</span>`}</strong></td>`;
                if (col.key === 'date') return `<td>${cancelledHtml}</td>`;
                if (col.key === 'partyName') return `<td>${cancelledHtml}</td>`;
                if (col.key === 'poRef') return `<td>${cancelledHtml}</td>`;
                if (col.key === 'grnNo') return `<td>${cancelledHtml}</td>`;
                if (col.key === 'itemName') return `<td>${cancelledHtml}</td>`;
                if (col.key === 'fabricType') return `<td>${cancelledHtml}</td>`;
                if (col.key === 'qty') return `<td>${cancelledHtml}</td>`;
                if (col.key === 'vehicleNo') return `<td>${cancelledHtml}</td>`;
                return '';
            }).filter(Boolean).join('');

            return `
            <tr class="row-cancelled" style="font-style: italic;">
                <td></td>
                ${tds}
                <td>
                    <div class="table-actions">
                        ${hasEditPerm ? `<button class="btn btn-sm btn-secondary" onclick="openOutwardModal(null, '${o.number}')"></button>` : '-'}
                    </div>
                </td>
            </tr>
            `;
        }
        
        const partyName = window.getOutwardPartyName(o);
        const po = o.poRefId ? db.pos.find(p => p.id === o.poRefId || p.number === o.poRefId) : null;
        let partyPoNum = '';
        if (po) {
            partyPoNum = po.partyOrderNo || po.custOrderNo || '';
            if (!partyPoNum && po.linkedSoId) {
                const so = db.salesOrders.find(s => s.id === po.linkedSoId);
                if (so) partyPoNum = so.partyOrderNo || '';
            }
        }
        let poNumDisplay = '-';
        if (po) {
            const displayStr = po.number + (partyPoNum ? ' (' + partyPoNum + ')' : '');
            poNumDisplay = `<a href="#" onclick="event.preventDefault(); window.openPoByNumber('${po.number}')" style="color: var(--accent-blue, #3b82f6); text-decoration: underline; font-weight: bold;">${displayStr}</a>`;
        } else if (o.poRefId) {
            poNumDisplay = `<a href="#" onclick="event.preventDefault(); window.openPoByNumber('${o.poRefId}')" style="color: var(--accent-blue, #3b82f6); text-decoration: underline; font-weight: bold;">${o.poRefId}</a>`;
        }
        
        const hasEditPerm = isCancelledOrPlaceholder ? checkPermission('outward', 'edit_cancelled') : checkPermission('outward', 'write');
        const hasDeletePerm = !isPlaceholder && checkPermission('outward', 'delete');
        
        let actionsDisplay = '-';
        if (hasEditPerm || hasDeletePerm) {
            actionsDisplay = `
                <div class="table-actions">
                    ${!isCancelledOrPlaceholder ? `<button class="btn btn-sm btn-secondary" onclick="printOutward('${o.id}')">=�</button>` : ''}
                    ${hasEditPerm ? `<button class="btn btn-sm btn-secondary" onclick="openOutwardModal('${o.id}')"></button>` : ''}
                    ${hasDeletePerm ? `<button class="btn btn-sm btn-danger" onclick="deleteOutward('${o.id}')">=�</button>` : ''}
                </div>
            `;
        }
        
        const tds = config.map(col => {
            if (col.visible === false) return '';
            if (isInhouse && (col.key === 'vehicleNo' || col.key === 'partyName')) return '';

            if (col.key === 'number') return `<td><strong><a href="#" onclick="event.preventDefault(); openOutwardModal('${o.id}')" style="${isCancelledOrPlaceholder ? 'color: var(--accent-red, #ef4444) !important;' : ''}">${o.number}</a></strong></td>`;
            if (col.key === 'date') return `<td>${isCancelledOrPlaceholder ? cancelledHtml : formatDate(o.date)}</td>`;
            if (col.key === 'partyName') return `<td>${isCancelledOrPlaceholder ? cancelledHtml : partyName}</td>`;
            if (col.key === 'poRef') return `<td>${isCancelledOrPlaceholder ? cancelledHtml : poNumDisplay}</td>`;
            if (col.key === 'grnNo') {
                if (isCancelledOrPlaceholder) return `<td>${cancelledHtml}</td>`;
                const formatGrnLinks = (grnStr) => {
                    if (!grnStr) return '';
                    const grnList = String(grnStr).split(',').map(s => s.trim()).filter(Boolean);
                    if (grnList.length === 0) return '';
                    const linksHtml = grnList.map(num => `<a href="#" onclick="event.preventDefault(); window.openGrnByNumber('${num}')" style="display:inline-flex; align-items:center; background:rgba(37,99,235,0.08); color:#2563eb; font-weight:600; font-size:11px; padding:2px 6px; border-radius:4px; border:1px solid rgba(37,99,235,0.25); text-decoration:none; white-space:nowrap; cursor:pointer;" onmouseover="this.style.background='rgba(37,99,235,0.2)'" onmouseout="this.style.background='rgba(37,99,235,0.08)'">${num}</a>`).join('');
                    return `<div style="display:flex; flex-wrap:wrap; gap:4px; max-width:280px; align-items:center;">${linksHtml}</div>`;
                };
                const formattedGrns = formatGrnLinks(o.grnNo);
                if (o.materialSourceType === 'consumable') {
                    const masterRecords = db.items || [];
                    const consumable = masterRecords.find(item => item.id === o.consumableItemId);
                    const consName = consumable ? consumable.name : (o.consumableItemId || 'Consumable');
                    return `<td>Consumable: ${consName}</td>`;
                } else if (o.materialSourceType === 'both') {
                    const masterRecords = db.items || [];
                    const consumable = masterRecords.find(item => item.id === o.consumableItemId);
                    const consName = consumable ? consumable.name : (o.consumableItemId || 'Consumable');
                    const fabricPart = (formattedGrns ? formattedGrns : '') + (o.custChallanNo ? ' (Ch: ' + o.custChallanNo + ')' : '');
                    return `<td>${fabricPart}<br><small style="color: var(--text-secondary);">+ Consumable: ${consName}</small></td>`;
                } else {
                    return `<td>` + (formattedGrns ? formattedGrns : '') + (o.custChallanNo ? ' (Ch: ' + o.custChallanNo + ')' : '') + `</td>`;
                }
            }
            if (col.key === 'itemName') return `<td class="cell-item-name wrap-text">${isCancelledOrPlaceholder ? cancelledHtml : window.getOutwardItemName(o)}</td>`;
            if (col.key === 'fabricType') return `<td class="cell-fabric-name wrap-text">${isCancelledOrPlaceholder ? cancelledHtml : window.getOutwardFabricName(o)}</td>`;
            if (col.key === 'qty') {
                if (isCancelledOrPlaceholder) return `<td>${cancelledHtml}</td>`;
                if (o.materialSourceType === 'both') {
                    return `<td><strong>Fab: ${Number(o.qty || 0).toFixed(2)} m</strong><br><small style="color: var(--text-secondary);">Cons: ${Number(o.consumableQty || 0).toFixed(2)}</small></td>`;
                } else if (o.materialSourceType === 'consumable') {
                    return `<td><strong>Cons: ${Number(o.qty || 0).toFixed(2)}</strong></td>`;
                } else {
                    return `<td><strong>Fab: ${Number(o.qty || 0).toFixed(2)} m</strong></td>`;
                }
            }
            if (col.key === 'vehicleNo') return `<td>${isCancelledOrPlaceholder ? cancelledHtml : (o.vehicleNo || '-')}</td>`;
            return '';
        }).filter(Boolean).join('');

        return `
        <tr class="${isCancelledOrPlaceholder ? 'row-cancelled' : ''}">
            <td><input type="checkbox" class="chk-select-outward" value="${o.id}" onchange="toggleBulkDeleteButton('outward')"></td>
            ${tds}
            <td>${actionsDisplay}</td>
        </tr>
        `;
    }).join('');

    let totalMetersIssued = 0;
    let totalConsumableIssued = 0;
    filteredOutwards.forEach(o => {
        if (!o.isPlaceholder && (o.status || '').trim().toLowerCase() !== 'cancelled') {
            if (o.materialSourceType === 'consumable') {
                totalConsumableIssued += Number(o.qty || 0);
            } else if (o.materialSourceType === 'both') {
                totalMetersIssued += Number(o.qty || 0);
                totalConsumableIssued += Number(o.consumableQty || 0);
            } else {
                totalMetersIssued += Number(o.qty || 0);
            }
        }
    });

    let footerText = '';
    if (totalMetersIssued > 0 && totalConsumableIssued > 0) {
        footerText = `Fab: ${totalMetersIssued.toFixed(2)} m | Cons: ${totalConsumableIssued.toFixed(2)}`;
    } else if (totalConsumableIssued > 0) {
        footerText = `Cons: ${totalConsumableIssued.toFixed(2)}`;
    } else {
        footerText = `${totalMetersIssued.toFixed(2)} m`;
    }

    // Determine correct colspans for footer based on configured columns
    let numberColIdx = config.filter(c => c.visible !== false && !(isInhouse && (c.key === 'vehicleNo' || c.key === 'partyName'))).findIndex(c => c.key === 'qty');
    if (numberColIdx === -1) numberColIdx = visibleCols - 1;

    tbody.innerHTML += `
        <tr style="background: rgba(79, 125, 255, 0.05); font-weight: 700;">
            <td colspan="${numberColIdx + 1}" style="text-align: right; padding: 10px;">Total Qty Issued:</td>
            <td colspan="${(visibleCols + 2) - (numberColIdx + 1)}" style="text-align: left; padding: 10px; color: var(--accent-blue);">${footerText}</td>
        </tr>
    `;
}

async function deleteOutward(id) {
    const out = (rawDB.outwards || db.outwards || []).find(o => o.id === id);
    if (!out) {
        showToast('Fabric Outward Challan not found.', 'error');
        return;
    }

    const challanNo = (out.number || '').toUpperCase();
    const isChallanInhouse = challanNo.startsWith('FI/INH') || (out.remarks && out.remarks.includes('"type":"inhouse"'));

    if (isChallanInhouse) {
        const linkedReqs = (rawDB.requisitionSlips || []).filter(r => {
            if (r.status === 'Cancelled') return false;
            const ids = r.linkedChallanIds || [];
            return ids.includes(out.id) || ids.includes(out.number);
        });

        if (linkedReqs.length > 0) {
            let parentPoNo = '-';
            const matchedPo = (rawDB.pos || []).find(p => p.id === out.poRefId || p.number === out.poRefId || p.id === out.poId || p.number === out.linked_po_number);
            if (matchedPo) parentPoNo = matchedPo.number;
            
            let errorMsg = `This Inhouse Fabric Issue Challan (${out.number}) cannot be deleted because it is already referenced in:`;
            errorMsg += `<br><br><strong>Requisition Slip(s)</strong>:<br>- ` + linkedReqs.map(r => r.number).join('<br>- ');
            if (parentPoNo !== '-') {
                errorMsg += `<br><br><strong>Parent Inhouse PO</strong>: ${parentPoNo}`;
            }
            window.showSmartAlert('Document Linked', errorMsg);
            return;
        }
    } else {
        const matchedPo = (rawDB.pos || []).find(p => p.id === out.poRefId || p.number === out.poRefId || p.id === out.poId || p.number === out.linked_po_number);
        if (matchedPo) {
            let errorMsg = `This Vendor Fabric Issue Challan (${out.number}) cannot be deleted because it is linked to:<br><br><strong>Vendor Purchase Order</strong>: ${matchedPo.number}`;
            window.showSmartAlert('Document Linked', errorMsg);
            return;
        }
    }

    if (!(await window.showSmartConfirm('Revert Outward', 'Are you sure you want to revert this Fabric Outward Challan?'))) return;
    try {
        if (out) {
            if (out.grnLinks && out.grnLinks.length > 0) {
                for (const link of out.grnLinks) {
                    const grn = db.grns.find(g => g.id === link.grnRefId);
                    if (grn) {
                        grn.issuedMeters = Math.max(0, (grn.issuedMeters || 0) - link.qty);
                        await saveToSupabase('grns', grn);
                    }
                }
            } else {
                const grn = db.grns.find(g => g.id === out.grnRefId);
                if (grn) {
                    grn.issuedMeters = Math.max(0, (grn.issuedMeters || 0) - out.qty);
                    await saveToSupabase('grns', grn);
                }
            }
            if (out.poRefId) {
                const linkedPO = db.pos.find(p => p.id === out.poRefId);
                if (linkedPO && ((linkedPO.poType || 'vendor') === 'vendor' || linkedPO.poType === 'inhouse')) {
                    const poNumber = linkedPO.number;
                    const matchingPOs = db.pos.filter(p => p.number === poNumber);
                    
                    const otherOutwards = db.outwards.filter(o => o.id !== id && o.poRefId === out.poRefId);
                    const uniqueChallans = [...new Set(otherOutwards.map(o => o.number))].filter(Boolean).join(', ');
                    
                    for (const mpo of matchingPOs) {
                        mpo.vendorJobWorkChallanNo = uniqueChallans;
                        await saveToSupabase('purchase_orders', mpo);
                    }
                }
            }
        }
        await deleteFromSupabase('outwards', id);
        rawDB.outwards = rawDB.outwards.filter(o => o.id !== id);
        applyFinancialYearFilters();
        renderOutwardTable();
        if (typeof window.refreshAllLogisticsTables === 'function') window.refreshAllLogisticsTables();
        if (typeof renderPOTable === 'function') if (typeof window.renderPOTable === 'function') window.renderPOTable();
        const docNo = out ? (out.outwardNo || out.number) : '';
        logUserAction('Outward', 'Deleted', `Deleted outward: ${docNo}`);
        showToast('Outward Challan Reverted', 'info');
    } catch(e) {
        showToast(`Delete failed: ${e.message || e}`, 'error');
    }
}

