function renderMachineTable() {
    const search = getMasterSearchQuery();
    const tbody = document.getElementById('machine-table-body');
    if (!tbody) return;
    db.machines = db.machines || [];
    
    const filtered = db.machines.filter(m => 
        (m.machineNo || '').toLowerCase().includes(search) ||
        (m.machineModel || '').toLowerCase().includes(search)
    );
    
    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" class="empty-row">No machines defined yet. Click ➕ Add to create one.</td></tr>';
        return;
    }
    
    tbody.innerHTML = filtered.map((m, idx) => `
        <tr>
            <td><input type="checkbox" class="chk-select-mst" value="${m.id}" onchange="toggleBulkDeleteButton('mst')"></td>
            <td>${idx + 1}</td>
            <td><strong>${m.machineNo}</strong></td>
            <td>${m.machineModel || '-'}</td>
            <td>${m.fabricConversion || '0.00'}</td>
            <td>${m.embroideryMtr || '0.00'}</td>
            <td>
                <div class="table-actions">
                    <button class="btn btn-sm btn-secondary" onclick="openMachineModal('${m.id}')"></button>
                    <button class="btn btn-sm btn-danger" onclick="deleteMachine('${m.id}')">=�</button>
                </div>
            </td>
        </tr>
    `).join('');
}

function openMachineModal(editId = null) {
    if (!checkPermission('masters', 'write')) {
        showToast('Permission Denied', 'error');
        return;
    }
    document.getElementById('machine-edit-id').value = editId || '';
    if (editId) {
        const m = db.machines.find(x => x.id === editId);
        if (m) {
            document.getElementById('machine-modal-title').textContent = 'Edit Machine';
            document.getElementById('machine-no').value = m.machineNo;
            document.getElementById('machine-model').value = m.machineModel || '';
            document.getElementById('machine-fabric-conversion').value = m.fabricConversion;
            document.getElementById('machine-embroidery-mtr').value = m.embroideryMtr || '';
        }
    } else {
        document.getElementById('machine-modal-title').textContent = 'Add Machine';
        document.getElementById('machine-no').value = '';
        document.getElementById('machine-model').value = '';
        document.getElementById('machine-fabric-conversion').value = '';
        document.getElementById('machine-embroidery-mtr').value = '';
    }
    openModal('machine-modal');
}

async function saveMachine() {
    if (!checkPermission('masters', 'write')) {
        showToast('Permission Denied', 'error');
        return;
    }
    const machineNo = document.getElementById('machine-no').value.trim();
    const machineModel = document.getElementById('machine-model').value.trim();
    const fabricConversion = parseFloat(document.getElementById('machine-fabric-conversion').value) || 0;
    const embroideryMtr = parseFloat(document.getElementById('machine-embroidery-mtr').value) || 0;
    const editId = document.getElementById('machine-edit-id').value;

    if (!machineNo) { showToast('Machine number is required', 'error'); return; }
    if (fabricConversion <= 0) { showToast('Valid fabric conversion is required', 'error'); return; }
    if (embroideryMtr <= 0) { showToast('Valid Embroidery Mtr is required', 'error'); return; }

    db.machines = db.machines || [];
    const isDuplicate = db.machines.some(m => m.machineNo.toLowerCase() === machineNo.toLowerCase() && m.id !== editId);
    if (isDuplicate) {
        showToast('A Machine with this Number already exists.', 'error');
        return;
    }

    const data = {
        id: editId || uid(),
        company_id: (currentCompany ? currentCompany.id : 'co4'),
        machineNo,
        machineModel,
        fabricConversion,
        embroideryMtr
    };

    try {
        await saveToSupabase('machines', data);
        if (editId) {
            const idx = db.machines.findIndex(m => m.id === editId);
            if (idx !== -1) db.machines[idx] = data;
            sortMachines();
            logUserAction('Masters', 'Modified', `Updated machine: ${machineNo}`);
            showToast('Machine updated', 'success');
        } else {
            db.machines.push(data);
            sortMachines();
            logUserAction('Masters', 'Created', `Created machine: ${machineNo}`);
            showToast('Machine created', 'success');
        }
        closeModal('machine-modal', true);
        renderMachineTable();
    } catch(e) {
        console.error("Failed to save machine:", e);
    }
}

async function deleteMachine(id) {
    if (!checkPermission('masters', 'delete')) {
        showToast('Permission Denied', 'error');
        return;
    }
    const m = db.machines.find(x => x.id === id);
    const machineNo = m ? m.machineNo : '';
    if (!(await window.showSmartConfirm('Delete Machine', 'Are you sure you want to delete this machine?'))) return;
    try {
        await deleteFromSupabase('machines', id);
        db.machines = db.machines.filter(x => x.id !== id);
        renderMachineTable();
        logUserAction('Masters', 'Deleted', `Deleted machine: ${machineNo}`);
        showToast('Machine deleted', 'info');
    } catch(e) {
        showToast(`Delete failed: ${e.message || e}`, 'error');
    }
}


window.getProductionPlanRemainingItems = function(plan, editSlipId = null) {
    if (!plan) return [];
    if (!plan.items || plan.items.length === 0) return [];

    db.productionSlips = db.productionSlips || [];
    const slips = db.productionSlips.filter(s => 
        (s.status || '').trim().toLowerCase() !== 'cancelled' && 
        s.planId === plan.id && 
        s.id !== editSlipId
    );

    const producedPoIds = new Set();
    slips.forEach(s => {
        const links = s.links && s.links.length > 0 ? s.links : [{ poId: s.poId }];
        links.forEach(l => {
            if (l.poId) {
                producedPoIds.add(`${l.poId}_${s.machineId}`);
                producedPoIds.add(l.poId);
            }
        });
    });

    const remaining = [];
    plan.items.forEach(it => {
        const mId = it.machineId;
        const mach = db.machines.find(m => m.id === mId || m.machineNo === mId || m.machineNo === it.machineNo);
        const machId = mach ? mach.id : mId;

        if (it.pos && Array.isArray(it.pos)) {
            const remainingPos = it.pos.filter(pPo => {
                if (!pPo.poId) return false;
                return !producedPoIds.has(`${pPo.poId}_${machId}`);
            });
            if (remainingPos.length > 0) {
                remaining.push({
                    ...it,
                    pos: remainingPos
                });
            }
        }
    });
    return remaining;
};

window.isProductionPlanFullyCompleted = function(plan, editSlipId = null) {
    if (!plan) return true;
    if ((plan.status || '').toLowerCase() === 'completed') return true;
    if ((plan.status || '').toLowerCase() === 'cancelled') return true;
    const remaining = window.getProductionPlanRemainingItems(plan, editSlipId);
    return remaining.length === 0;
};

