async function samplingBulkDelete() {
    const checkboxes = document.querySelectorAll('.chk-select-sampling');
    const idsToDelete = Array.from(checkboxes).filter(cb => cb.checked).map(cb => cb.value);
    if (idsToDelete.length === 0) { showToast('No Sampling Slips selected.', 'info'); return; }
    if (!(await window.showSmartConfirm('Delete Sampling Slips', `Are you sure you want to delete the ${idsToDelete.length} selected Sampling Slips? This action cannot be undone.`))) return;
    showImportLoadingOverlay();
    try {
        await deleteMultipleFromSupabase('production_slips', idsToDelete);
        applyFinancialYearFilters();
        if (typeof renderSamplingTable === 'function') renderSamplingTable();
        const headerChk = document.getElementById('sampling-select-all');
        if (headerChk) headerChk.checked = false;
        toggleBulkDeleteButton('sampling');
        showToast(`Successfully deleted ${idsToDelete.length} Sampling Slips.`, 'success');
    } catch (err) {
        console.error("Bulk delete failed:", err);
    } finally {
        hideImportLoadingOverlay();
    }
}
window.samplingBulkDelete = samplingBulkDelete;

