window.renderProductionPlanTable = function() {
    const search = (document.getElementById('prod-plan-search')?.value || '').toLowerCase();
    const tbody = document.getElementById('prod-plan-table-body');
    if (!tbody) return;
    db.productionPlans = db.productionPlans || [];

    let filteredPlans = db.productionPlans.filter(p => {
        const planType = p.planningType || p.planning_type || 'Production';
        if (planType !== 'Production') return false;

        const numStr = String(p.number || '').toLowerCase();
        const dateStr = formatDate(p.planDate || p.date || '').toLowerCase();
        const remarksStr = String(p.remarks || '').toLowerCase();
        return numStr.includes(search) || 
               dateStr.includes(search) || 
               remarksStr.includes(search);
    });

    filteredPlans.sort((a, b) => {
        const numA = parseInt(String(a.number || '').split('/').pop()) || 0;
        const numB = parseInt(String(b.number || '').split('/').pop()) || 0;
        return numB - numA;
    });

    if (filteredPlans.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" class="empty-row">No Production Plans scheduled.</td></tr>';
        return;
    }

    tbody.innerHTML = filteredPlans.map((p) => {
        const machineNos = (p.items || []).map(item => {
            const m = db.machines.find(mach => mach.id === item.machineId);
            return m ? (m.machineNo || m.name || '') : '';
        }).filter(Boolean).join(', ') || '-';

        const totalTargetQty = p.totalTargetQty !== undefined ? p.totalTargetQty : (p.items ? p.items.reduce((s, it) => {
            const innerQty = it.pos ? it.pos.reduce((sum, item) => sum + (item.targetQty || 0), 0) : (it.targetQty || 0);
            return s + innerQty;
        }, 0) : 0);

        const planType = p.planningType || p.planning_type || 'Production';
        let badgeStyle = 'background-color: rgba(79, 125, 255, 0.1); color: var(--accent-blue);';

        let numberHtml = `<strong>${p.number || '-'}</strong>`;

        return `
            <tr>
                <td><input type="checkbox" class="chk-select-prod-plan" value="${p.id}" onchange="toggleBulkDeleteButton('prod-plan')"></td>
                <td>${numberHtml}</td>
                <td>${formatDate(p.planDate || p.date)}</td>
                <td><span style="${badgeStyle} padding: 4px 8px; border-radius: 4px; font-weight: 600; font-size: 11.5px; display: inline-block;">${planType}</span></td>
                <td><strong>${machineNos}</strong></td>
                <td><strong>${totalTargetQty}</strong></td>
                <td>
                    <div class="table-actions">
                        <button class="btn btn-sm btn-secondary" onclick="openProdPlanModal('${p.id}', 'production')"></button>
                        <button class="btn btn-sm btn-danger" onclick="deleteProductionPlan('${p.id}', 'production')">=�</button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
};

