window.onProdPlanTypeChange = function() {
    const editId = document.getElementById('prod-plan-edit-id').value;
    const type = document.getElementById('prod-plan-type').value;
    
    const groupPP = document.getElementById('group-prod-plan-number');
    const groupFS = document.getElementById('group-prod-plan-sampling-number');
    
    if (type === 'Production') {
        groupPP.style.display = '';
        groupFS.style.display = 'none';
    } else if (type === 'Full Sampling') {
        groupPP.style.display = 'none';
        groupFS.style.display = '';
    } else if (type === 'Partial Sampling') {
        groupPP.style.display = '';
        groupFS.style.display = '';
    }

    const isFullSampling = (type === 'Full Sampling');
    const poSection = document.getElementById('prod-plan-po-section');
    if (poSection) poSection.style.display = isFullSampling ? 'none' : 'block';

    const prodSec = document.getElementById('prod-plan-exp-standard-section');
    const sampSec = document.getElementById('prod-plan-exp-sampling-section');
    if (prodSec) prodSec.style.display = isFullSampling ? 'none' : 'block';
    if (sampSec) sampSec.style.display = (type === 'Production') ? 'none' : 'block';

    // Synchronize 24h stitch value between sections
    if (type === 'Full Sampling' || type === 'Partial Sampling') {
        const val = document.getElementById('prod-plan-exp-24h-stitch')?.value || '';
        const sampInput = document.getElementById('prod-plan-exp-24h-stitch-sampling');
        if (sampInput) {
            sampInput.value = val;
        }
    } else {
        const val = document.getElementById('prod-plan-exp-24h-stitch-sampling')?.value || '';
        const prodInput = document.getElementById('prod-plan-exp-24h-stitch');
        if (prodInput) {
            prodInput.value = val;
        }
    }
    
    window.runProdPlanCalculations();

    const reportSection = document.getElementById('prod-plan-stock-report-section');
    if (reportSection) {
        reportSection.style.display = isFullSampling ? 'none' : '';
    }
    
    function getNextProductionPlanNumber(prefixType) {
        const list = db.productionPlans || rawDB.productionPlans || [];
        const fySuffix = (financialYears[currentFinancialYear] || {}).suffix || '/26-27';
        const cleanSuffix = fySuffix.startsWith('/') ? fySuffix.substring(1) : fySuffix.toLowerCase();
        const shortSuffix = cleanSuffix.replace(/^20/, '');

        const filtered = list.filter(p => {
            if (!p) return false;
            const planType = p.planningType || p.planning_type || 'Production';
            const num = p.number || p.samplingNumber || p.sampling_number || '';
            const numLower = num.toLowerCase();
            const matchesFY = numLower.includes(cleanSuffix) || numLower.includes(shortSuffix);
            
            if (prefixType === 'PP') {
                return matchesFY && planType !== 'Full Sampling';
            } else {
                return matchesFY && (planType === 'Full Sampling' || planType === 'Partial Sampling');
            }
        });

        if (filtered.length === 0) return 1;

        const numbers = filtered.map(p => {
            let num = '';
            if (prefixType === 'PP') {
                num = p.number || '';
            } else {
                num = p.samplingNumber || p.sampling_number || p.number || '';
            }
            if (!num) return 0;
            const parts = num.split('/');
            if (parts.length < 3) return 0;
            const val = parseInt(parts[parts.length - 1]);
            return isNaN(val) ? 0 : val;
        });

        let next = 1;
        while (numbers.includes(next)) {
            next++;
        }
        return next;
    }

    if (!editId) {
        if (type === 'Production' || type === 'Partial Sampling') {
            const prodCount = getNextProductionPlanNumber('PP');
            document.getElementById('prod-plan-number').value = getDocumentNumber('PP', prodCount);
        } else {
            document.getElementById('prod-plan-number').value = '';
        }
        
        if (type === 'Full Sampling' || type === 'Partial Sampling') {
            const fsCount = getNextProductionPlanNumber('FS');
            document.getElementById('prod-plan-sampling-number').value = getDocumentNumber('FS', fsCount);
        } else {
            document.getElementById('prod-plan-sampling-number').value = '';
        }
    }
};

window.openProdPlanModal = function(editId = null, mode = 'production') {
    document.getElementById('prod-plan-edit-id').value = editId || '';
    
    const tbody = document.getElementById('prod-plan-po-rows-body');
    if (tbody) tbody.innerHTML = '';
    
    db.machines = db.machines || [];
    const machSelect = document.getElementById('prod-plan-machine-select');
    if (machSelect) {
        machSelect.innerHTML = '<option value="">-- Select Machine --</option>' + 
            db.machines.map(m => `<option value="${m.id}">${m.machineNo}</option>`).join('');
        if (typeof reinitSearchableSelect === 'function') reinitSearchableSelect(machSelect);
    }
    
    const typeSelect = document.getElementById('prod-plan-type');
    const titleEl = document.getElementById('prod-plan-modal-title');
    
    let resolvedMode = mode;
    if (editId) {
        const p = db.productionPlans.find(x => x.id === editId);
        if (p) {
            const planType = p.planningType || p.planning_type || 'Production';
            if (planType === 'Full Sampling' || planType === 'Partial Sampling') {
                resolvedMode = 'sampling';
            } else {
                resolvedMode = 'production';
            }
        }
    }

    if (typeSelect) {
        typeSelect.innerHTML = `
            <option value="Production">Production</option>
            <option value="Partial Sampling">Partial Sampling</option>
            <option value="Full Sampling">Full Sampling</option>
        `;
        if (titleEl) {
            titleEl.textContent = editId ? 
                (resolvedMode === 'sampling' ? 'Edit Sampling Plan' : 'Edit Production Plan') : 
                (resolvedMode === 'sampling' ? 'New Sampling Plan' : 'New Production Plan');
        }
        if (!editId) {
            typeSelect.value = (resolvedMode === 'sampling') ? 'Partial Sampling' : 'Production';
        }
    }
    
    if (editId) {
        const p = db.productionPlans.find(x => x.id === editId);
        if (p) {
            document.getElementById('prod-plan-type').value = p.planningType || p.planning_type || 'Production';
            document.getElementById('prod-plan-number').value = p.number || '';
            document.getElementById('prod-plan-sampling-number').value = p.samplingNumber || p.sampling_number || '';
            document.getElementById('prod-plan-date').value = p.planDate || p.date || today();
            document.getElementById('prod-plan-remarks').value = window.getUserRemarks(p.id) || cleanRemarks(p.remarks) || '';
            
            const item = (p.items && p.items[0]) ? p.items[0] : null;
            if (item) {
                if (machSelect) {
                    machSelect.value = item.machineId || '';
                    if (typeof reinitSearchableSelect === 'function') reinitSearchableSelect(machSelect);
                }
                const opInput = document.getElementById('prod-plan-operator');
                if (opInput) opInput.value = item.operator || '';
                
                const pos = item.pos || [];
                if (pos.length > 0) {
                    pos.forEach(po => {
                        window.addProdPlanRowToBlock(null, po.poId, po.targetQty, po.targetThans, po.conversion, po.runningMinThan, po.poNumber, po.designName);
                    });
                    
                    const rows = tbody.rows;
                    pos.forEach((po, idx) => {
                        if (rows[idx]) {
                            if (po.designStitch !== undefined && po.designStitch !== null) {
                                rows[idx].dataset.designStitch = po.designStitch;
                                const thanInput = rows[idx].querySelector('.row-than');
                                if (thanInput) window.calculateRowQty(thanInput);
                            }
                            if (po.runningMinThan !== undefined && po.runningMinThan !== null) {
                                rows[idx].dataset.runningMinThan = po.runningMinThan;
                            }
                        }
                    });
                } else if (p.planningType !== 'Full Sampling') {
                    window.addProdPlanRowToBlock(null);
                }
                
                const exp = item.expectation;
                if (exp) {
                    const prodStitchInput = document.getElementById('prod-plan-exp-24h-stitch');
                    if (prodStitchInput) prodStitchInput.value = exp.stitch24h || '';
                    const sampStitchInput = document.getElementById('prod-plan-exp-24h-stitch-sampling');
                    if (sampStitchInput) sampStitchInput.value = exp.stitch24h || '';
                    const hoursInput = document.getElementById('prod-plan-sampling-hours');
                    if (hoursInput) hoursInput.value = exp.samplingHours || '';
                    const stitchesUsedInput = document.getElementById('prod-plan-stitches-used');
                    if (stitchesUsedInput) stitchesUsedInput.value = exp.stitchesUsed || '';
                }
            }
        }
    } else {
        document.getElementById('prod-plan-type').value = resolvedMode === 'sampling' ? 'Full Sampling' : 'Production';
        document.getElementById('prod-plan-date').value = today();
        document.getElementById('prod-plan-remarks').value = '';
        
        const opInput = document.getElementById('prod-plan-operator');
        if (opInput) opInput.value = '';
        if (machSelect) {
            machSelect.value = '';
            if (typeof reinitSearchableSelect === 'function') reinitSearchableSelect(machSelect);
        }
        
        const prodStitchInput = document.getElementById('prod-plan-exp-24h-stitch');
        if (prodStitchInput) prodStitchInput.value = '';
        const sampStitchInput = document.getElementById('prod-plan-exp-24h-stitch-sampling');
        if (sampStitchInput) sampStitchInput.value = '';
        const hoursInput = document.getElementById('prod-plan-sampling-hours');
        if (hoursInput) hoursInput.value = '';
        const stitchesUsedInput = document.getElementById('prod-plan-stitches-used');
        if (stitchesUsedInput) stitchesUsedInput.value = '';

        if (resolvedMode !== 'sampling') {
            window.addProdPlanRowToBlock(null);
        }
    }
    
    window.onProdPlanTypeChange();
    window.runProdPlanStockCheck();
    window.updateModalUserLog('prod-plan-modal');
    openModal('prod-plan-modal');
};

window.findStitchForPoDesign = function(poId) {
    if (!poId) return null;
    const po = db.pos.find(p => p.id === poId);
    if (!po) return null;
    
    const designText = po.items?.[0]?.processName || po.design || '';
    if (!designText) return null;
    db.designs = db.designs || [];
    const match = db.designs.find(d => d.number && designText.toLowerCase().includes(d.number.toLowerCase()));
    if (match && match.stitch) {
        return parseFloat(match.stitch) || null;
    }
    return null;
};

window.runProdPlanCalculations = function() {
    const type = document.getElementById('prod-plan-type')?.value || 'Production';
    
    if (type === 'Full Sampling') {
        const stitch24h = parseFloat(document.getElementById('prod-plan-exp-24h-stitch-sampling')?.value) || 0;
        const hours = parseFloat(document.getElementById('prod-plan-sampling-hours')?.value) || 0;
        const stitchesUsed = parseFloat(document.getElementById('prod-plan-stitches-used')?.value) || 0;
        const estThansEl = document.getElementById('prod-plan-sampling-est-thans');
        if (estThansEl) {
            const estThans = (stitchesUsed > 0) ? ((stitch24h * hours) / 24) / stitchesUsed : 0;
            estThansEl.textContent = estThans > 0 ? estThans.toFixed(2) : '0.00';
        }
        return;
    }

    const poTbody = document.getElementById('prod-plan-po-rows-body');
    const poRows = poTbody ? poTbody.rows : [];
    const container = document.getElementById('prod-plan-exp-rows-body');
    if (!container) return;

    container.innerHTML = '';
    
    let validCount = 0;
    const rowDatas = [];
    let totalCalculated24hStitches = 0;
    
    for (let i = 0; i < poRows.length; i++) {
        const row = poRows[i];
        const poSelect = row.querySelector('.row-po-select');
        const poId = poSelect ? poSelect.value : '';
        if (!poId) continue;
        
        const po = db.pos.find(p => p.id === poId);
        if (po && (po.status || '').trim().toLowerCase() === 'cancelled') continue;
        
        validCount++;
        const designName = row.querySelector('.row-design')?.value || (po?.items?.[0]?.processName || po?.design || 'Unknown Design');
        const conversion = parseFloat(row.querySelector('.row-conversion')?.value) || 0;
        const runningMinThan = parseFloat(row.querySelector('.row-min-than')?.value) || parseFloat(row.dataset.runningMinThan) || 0;
        
        let designStitch = parseFloat(row.dataset.designStitch);
        if (isNaN(designStitch)) {
            designStitch = window.findStitchForPoDesign(poId) || 0;
            row.dataset.designStitch = designStitch;
        }
        
        const targetThans = runningMinThan > 0 ? Math.round(1200 / runningMinThan) : 0;
        const targetMeters = targetThans * conversion;
        
        totalCalculated24hStitches += designStitch * targetThans;
        
        rowDatas.push({
            designName,
            targetThans,
            targetMeters
        });
    }
    
    const stitch24hInput = document.getElementById('prod-plan-exp-24h-stitch');
    if (stitch24hInput) {
        stitch24hInput.value = totalCalculated24hStitches > 0 ? totalCalculated24hStitches : '';
    }

    if (type === 'Partial Sampling') {
        const sampInput = document.getElementById('prod-plan-exp-24h-stitch-sampling');
        if (sampInput) {
            sampInput.value = totalCalculated24hStitches > 0 ? totalCalculated24hStitches : '';
        }
        const hours = parseFloat(document.getElementById('prod-plan-sampling-hours')?.value) || 0;
        const stitchesUsed = parseFloat(document.getElementById('prod-plan-stitches-used')?.value) || 0;
        const estThansEl = document.getElementById('prod-plan-sampling-est-thans');
        if (estThansEl) {
            const estThans = (stitchesUsed > 0) ? ((totalCalculated24hStitches * hours) / 24) / stitchesUsed : 0;
            estThansEl.textContent = estThans > 0 ? estThans.toFixed(2) : '0.00';
        }
    }
    
    rowDatas.forEach(r => {
        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td style="padding: 6px; font-weight: 600; color: var(--text-dark);">${r.designName}</td>
            <td style="padding: 6px;">
                <input type="text" class="form-input exp-target-thans" readonly value="${r.targetThans > 0 ? r.targetThans.toFixed(0) : ''}" style="height: 28px; font-size: 12px; padding: 4px 6px; background: #f4f5f7; border: 1px solid var(--border);" placeholder="Auto">
            </td>
            <td style="padding: 6px;">
                <input type="text" class="form-input exp-target-meters" readonly value="${r.targetMeters > 0 ? r.targetMeters.toFixed(2) : ''}" style="height: 28px; font-size: 12px; padding: 4px 6px; background: #f4f5f7; font-weight: 700; color: var(--accent-blue); border: 1px solid var(--border);" placeholder="Auto">
            </td>
        `;
        container.appendChild(tr);
    });
};

window.onRunningMinThanInput = function(input) {
    const row = input.closest('tr');
    if (row) {
        row.dataset.runningMinThan = input.value;
        const minThan = parseFloat(input.value) || 0;
        const thanInput = row.querySelector('.row-than');
        if (minThan > 0 && thanInput) {
            const targetThans = Math.round(1200 / minThan);
            thanInput.value = targetThans > 0 ? targetThans : '';
            window.calculateRowQty(thanInput);
        }
    }
    window.runProdPlanCalculations();
};

window.addProdPlanRowToBlock = function(element, poId = '', targetQty = '', targetThans = '', conversion = '', runningMinThan = '', poNumber = '', designNameVal = '') {
    const tbody = document.getElementById('prod-plan-po-rows-body');
    if (!tbody) return;
    
    db.pos = db.pos || [];
    const inhousePOs = db.pos.filter(po => (po.poType || 'vendor') === 'inhouse' && (po.status || '').trim().toLowerCase() !== 'cancelled');
    
    if (poId && !inhousePOs.some(po => po.id === poId)) {
        const poObj = db.pos.find(p => p.id === poId);
        if (poObj) {
            inhousePOs.push(poObj);
        } else {
            const fallbackPoName = poNumber || 'Deleted PO';
            inhousePOs.push({
                id: poId,
                number: fallbackPoName,
                design: designNameVal,
                items: [{ processName: designNameVal }]
            });
        }
    }

    const poOptions = inhousePOs.map(po => {
        const itemName = po.items?.[0]?.processName || po.design || '';
        return `<option value="${po.id}" ${po.id === poId ? 'selected' : ''}>${po.number} ${itemName ? '(' + itemName + ')' : ''}</option>`;
    }).join('');
    
    let designName = designNameVal || '';
    if (poId && !designName) {
        const selectedPo = db.pos.find(p => p.id === poId);
        if (selectedPo) {
            designName = selectedPo.items?.[0]?.processName || selectedPo.design || '';
        }
    }

    let initialStitch = '';
    if (poId && targetThans) {
        const stitchPerThan = window.findStitchForPoDesign(poId);
        if (stitchPerThan) {
            initialStitch = Math.round(parseFloat(targetThans) * stitchPerThan).toLocaleString('en-IN');
        }
    }

    const tr = document.createElement('tr');
    tr.innerHTML = `
        <td style="padding:6px 8px;">
            <select class="form-input row-po-select" style="padding:4px 8px; font-size:13px; height:30px;" onchange="window.onProdPlanRowPoChange(this)">
                <option value="">-- In-House PO --</option>
                ${poOptions}
            </select>
        </td>
        <td style="padding:6px 8px;">
            <input type="text" class="form-input row-design" readonly value="${designName}" placeholder="Auto from PO" style="padding:4px 8px; font-size:13px; height:30px; background:#f4f5f7;">
        </td>
        <td style="padding:6px 8px;">
            <input type="number" class="form-input row-min-than" value="${runningMinThan !== undefined && runningMinThan !== null ? runningMinThan : ''}" placeholder="Min/Than" step="0.1" style="padding:4px 8px; font-size:13px; height:30px;" oninput="window.onRunningMinThanInput(this)">
        </td>
        <td style="padding:6px 8px;">
            <input type="number" class="form-input row-conversion" value="${conversion !== undefined && conversion !== null ? conversion : ''}" placeholder="Mtr/Than" step="0.01" style="padding:4px 8px; font-size:13px; height:30px;" oninput="window.calculateRowQty(this)">
        </td>
        <td style="padding:6px 8px;">
            <input type="number" class="form-input row-than" value="${targetThans !== undefined && targetThans !== null ? targetThans : ''}" placeholder="Thans" step="0.01" style="padding:4px 8px; font-size:13px; height:30px;" oninput="window.calculateRowQty(this)">
        </td>
        <td style="padding:6px 8px;">
            <input type="number" class="form-input row-qty" value="${targetQty}" placeholder="Qty" step="0.01" style="padding:4px 8px; font-size:13px; height:30px;" oninput="window.runProdPlanStockCheck()">
        </td>
        <td style="padding:6px 8px;">
            <input type="text" class="form-input row-total-stitch" readonly value="${initialStitch}" placeholder="Auto" style="padding:4px 8px; font-size:13px; height:30px; background:#f4f5f7;">
        </td>
        <td style="padding:6px 8px; text-align:center;">
            <button type="button" class="btn btn-xs btn-danger" onclick="this.closest('tr').remove(); window.runProdPlanCalculations(); window.runProdPlanStockCheck();" style="padding:2px 6px;">=�</button>
        </td>
    `;
    
    tbody.appendChild(tr);
    if (runningMinThan) {
        tr.dataset.runningMinThan = runningMinThan;
    }
    const poSel = tr.querySelector('.row-po-select');
    if (poSel) makeSelectElementSearchable(poSel);
    
    window.runProdPlanCalculations();
    window.runProdPlanStockCheck();
};

window.calculateRowQty = function(input) {
    const row = input.closest('tr');
    if (!row) return;
    const thans = parseFloat(row.querySelector('.row-than')?.value) || 0;
    const conv = parseFloat(row.querySelector('.row-conversion')?.value) || 0;
    const qtyInput = row.querySelector('.row-qty');
    if (qtyInput) {
        if (thans > 0 && conv > 0) {
            qtyInput.value = parseFloat((thans * conv).toFixed(2));
        }
    }
    
    const poSelect = row.querySelector('.row-po-select');
    const poId = poSelect ? poSelect.value : '';
    const stitchInput = row.querySelector('.row-total-stitch');
    if (stitchInput) {
        const stitchPerThan = row.dataset.designStitch ? parseFloat(row.dataset.designStitch) : window.findStitchForPoDesign(poId);
        if (stitchPerThan && thans > 0) {
            stitchInput.value = Math.round(thans * stitchPerThan).toLocaleString('en-IN');
        } else {
            stitchInput.value = '';
        }
    }
    
    window.runProdPlanCalculations();
    window.runProdPlanStockCheck();
};

window.onProdPlanRowPoChange = function(selectEl) {
    const row = selectEl.closest('tr');
    if (!row) return;
    const poId = selectEl.value;
    const po = db.pos.find(p => p.id === poId);
    
    const designInput = row.querySelector('.row-design');
    const qtyInput = row.querySelector('.row-qty');
    
    if (po) {
        const itemName = po.items?.[0]?.processName || po.design || '';
        if (designInput) designInput.value = itemName;
        if (qtyInput && !qtyInput.value) qtyInput.value = po.qty || '';
        
        const stitch = window.findStitchForPoDesign(poId) || 0;
        row.dataset.designStitch = stitch;
        
        const machSelect = document.getElementById('prod-plan-machine-select');
        const machId = machSelect ? machSelect.value : '';
        const mach = db.machines.find(m => m.id === machId);
        const machineConversion = mach ? (mach.embroideryMtr || '') : '';
        
        const rowConversionInput = row.querySelector('.row-conversion');
        if (rowConversionInput && !rowConversionInput.value) {
            rowConversionInput.value = machineConversion;
        }
    } else {
        if (designInput) designInput.value = '';
        delete row.dataset.designStitch;
    }
    
    window.calculateRowQty(selectEl);
};

window.runProdPlanStockCheck = function() {
    const tbody = document.getElementById('prod-plan-stock-report-body');
    if (!tbody) return;

    const machineSelect = document.getElementById('prod-plan-machine-select');
    const machineId = machineSelect ? machineSelect.value : '';
    const machine = db.machines.find(m => m.id === machineId);
    const machineName = machine ? machine.machineNo : 'Unknown Machine';

    const poTbody = document.getElementById('prod-plan-po-rows-body');
    const poRows = poTbody ? poTbody.rows : [];
    
    if (!machineId || poRows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" class="empty-row">Select machine and add PO rows above to view stock availability.</td></tr>';
        return;
    }

    const materialRequirements = [];

    for (let j = 0; j < poRows.length; j++) {
        const row = poRows[j];
        const poSelect = row.querySelector('.row-po-select');
        const poId = poSelect ? poSelect.value : '';
        const qtyVal = parseFloat(row.querySelector('.row-qty')?.value) || 0;

        if (!poId || qtyVal <= 0) continue;

        const po = db.pos.find(p => p.id === poId);
        if (!po) continue;

        const finishedItemId = po.items?.[0]?.itemId || '';
        const bom = db.boms.find(b => b.id === po.bomId || (b.code && po.bomNumber && String(b.code).toLowerCase() === String(po.bomNumber).toLowerCase())) || 
                    db.boms.find(b => b.finishedItemId === finishedItemId);

        if (bom) {
            const ingredients = bom.ingredients || [];
            ingredients.forEach(ing => {
                if (ing.itemId === 'METADATA_DESIGN_STITCH' || ing.itemId === 'METADATA_DESIGN_REPEAT_STR') return;
                const reqQty = (ing.qty || 0) * (qtyVal / (bom.batchQty || 1));
                
                let existing = materialRequirements.find(mr => mr.itemId === ing.itemId);
                if (existing) {
                    existing.reqQty += reqQty;
                } else {
                    materialRequirements.push({
                        machineId,
                        machineName,
                        itemId: ing.itemId,
                        reqQty
                    });
                }
            });
        }

        const poFabrics = new Set();
        if (bom) {
            (bom.ingredients || []).forEach(ing => {
                const item = db.items.find(i => i.id === ing.itemId);
                if (item && String(item.itemGroup || '').toLowerCase().includes('fabric')) {
                    poFabrics.add(ing.itemId);
                }
            });
        }
        if (finishedItemId) {
            const finishedItem = db.items.find(i => i.id === finishedItemId);
            if (finishedItem && String(finishedItem.itemGroup || '').toLowerCase().includes('fabric')) {
                poFabrics.add(finishedItemId);
            }
        }

        const resolvedPlainFabric = (function() {
            if (!po) return null;
            const soId = po.linkedSoId || po.soRef;
            if (soId) {
                const linkedGrn = (db.grns || []).find(g => {
                    const wState = parseGrnWizardState(g);
                    const isPlain = wState.type === 'fabric' && wState.subType === 'plain';
                    const matchesSo = g.soRefId === soId || 
                                      g.linked_so_id === soId || 
                                      g.linked_so_number === po.linkedSoNumber ||
                                      (g.soLinks && g.soLinks.some(link => link === soId || (link && link.soId === soId)));
                    return isPlain && matchesSo;
                });
                if (linkedGrn && (linkedGrn.fabricType || linkedGrn.item)) {
                    return (linkedGrn.fabricType || linkedGrn.item).trim();
                }
            }
            
            const outwardIssue = (db.outwards || []).find(out => {
                const state = parseOutwardWizardState(out);
                return state.type === 'inhouse' && (out.poRefId === po.id || out.poRefId === po.number);
            });
            if (outwardIssue && outwardIssue.dispatchedPackages) {
                for (const pkg of outwardIssue.dispatchedPackages) {
                    const linkedGrn = db.grns.find(g => g.id === pkg.grnId);
                    const wState = linkedGrn ? parseGrnWizardState(linkedGrn) : null;
                    if (wState && wState.subType === 'plain') {
                        const slip = linkedGrn && linkedGrn.packageSlips ? linkedGrn.packageSlips[pkg.slipIndex] : null;
                        const fabricName = (slip ? slip.fabricType : null) || linkedGrn.fabricType || linkedGrn.item;
                        if (fabricName) return fabricName.trim();
                    }
                }
            }

            const reqSlip = (db.requisitionSlips || []).find(req => {
                if (req.status === 'Cancelled' || req.status === 'Pending') return false;
                const reqType = (req.type || 'Fabric').toLowerCase();
                if (reqType !== 'fabric') return false;
                const reqMeta = parseMetadataFromRemarks(req.remarks, '__REQ_METADATA__');
                const linkedPoId = reqMeta.inhousePoId || req.inhousePoId || '';
                return linkedPoId === po.id || linkedPoId === po.number;
            });
            if (reqSlip) {
                const reqMeta = parseMetadataFromRemarks(reqSlip.remarks, '__REQ_METADATA__');
                const linkedChallanIds = reqMeta.linkedChallanIds || [];
                for (const grnId of linkedChallanIds) {
                    const g = db.grns.find(x => x.id === grnId);
                    if (g && (g.fabricType || g.item)) {
                        return (g.fabricType || g.item).trim();
                    }
                }
            }

            const custId = po.customerId;
            if (custId) {
                const designName = po.items?.[0]?.processName || '';
                const matchingGrn = (db.grns || []).find(g => {
                    const wState = parseGrnWizardState(g);
                    if (wState.type !== 'fabric' || wState.subType !== 'plain' || g.customerId !== custId) return false;
                    const grnTxt = JSON.stringify(g).toLowerCase();
                    return designName && grnTxt.includes(designName.toLowerCase());
                });
                if (matchingGrn && (matchingGrn.fabricType || matchingGrn.item)) {
                    return (matchingGrn.fabricType || matchingGrn.item).trim();
                }
                
                const lastPlainGrn = (db.grns || []).filter(g => {
                    const wState = parseGrnWizardState(g);
                    return wState.type === 'fabric' && wState.subType === 'plain' && g.customerId === custId;
                }).sort((a, b) => new Date(b.date) - new Date(a.date))[0];
                
                if (lastPlainGrn && (lastPlainGrn.fabricType || lastPlainGrn.item)) {
                    return (lastPlainGrn.fabricType || lastPlainGrn.item).trim();
                }
            }

            return null;
        })();

        if (resolvedPlainFabric) {
            poFabrics.add(resolvedPlainFabric);
        } else {
            (db.outwards || []).forEach(out => {
                const state = parseOutwardWizardState(out);
                if (state.type === 'inhouse' && (out.poRefId === po.id || out.poRefId === po.number)) {
                    (out.dispatchedPackages || []).forEach(pkg => {
                        const linkedGrn = db.grns.find(g => g.id === pkg.grnId);
                        const slip = linkedGrn && linkedGrn.packageSlips ? linkedGrn.packageSlips[pkg.slipIndex] : null;
                        const fabricName = (slip ? slip.fabricType : null) || (linkedGrn ? (linkedGrn.fabricType || linkedGrn.item) : '') || 'Plain Fabric';
                        if (fabricName) {
                            poFabrics.add(fabricName.trim());
                        }
                    });
                }
            });

            (db.requisitionSlips || []).forEach(req => {
                if (req.status === 'Cancelled' || req.status === 'Pending') return;
                const reqType = (req.type || 'Fabric').toLowerCase();
                if (reqType !== 'fabric' && reqType !== 'fabricreturn') return;
                const reqMeta = parseMetadataFromRemarks(req.remarks, '__REQ_METADATA__');
                const linkedPoId = reqMeta.inhousePoId || req.inhousePoId || '';
                if (linkedPoId === po.id || linkedPoId === po.number) {
                    (req.items || []).forEach(it => {
                        if (it.itemName) {
                            const processName = po.items?.[0]?.processName || '';
                            if (it.itemName.trim() !== processName.trim()) {
                                poFabrics.add(it.itemName.trim());
                            }
                        }
                    });
                }
            });
        }

        poFabrics.forEach(fab => {
            let existing = materialRequirements.find(mr => mr.isFabric && mr.fabricName === fab);
            if (existing) {
                existing.reqQty += qtyVal;
            } else {
                materialRequirements.push({
                    machineId,
                    machineName,
                    itemId: null,
                    fabricName: fab,
                    isFabric: true,
                    reqQty: qtyVal
                });
            }
        });
    }

    if (materialRequirements.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" class="empty-row">No raw material requirements found. Make sure selected POs have BOMs defined or fabric linked.</td></tr>';
        return;
    }

    tbody.innerHTML = materialRequirements.map(mr => {
        if (mr.isFabric) {
            const planRows = Array.from(document.querySelectorAll('#prod-plan-grid-body tr'));
            let allottedQty = 0;
            let requisitionsIssued = 0;
            let totalConsumed = 0;

            planRows.forEach(pRow => {
                const poSelect = pRow.querySelector('.row-po-select');
                const poId = poSelect ? poSelect.value : '';
                if (!poId) return;
                const po = db.pos.find(p => p.id === poId);
                if (!po) return;

                const resolvedPlainFabric = (function() {
                    const soId = po.linkedSoId || po.soRef;
                    if (soId) {
                        const linkedGrn = (db.grns || []).find(g => {
                            const wState = parseGrnWizardState(g);
                            return wState.type === 'fabric' && wState.subType === 'plain' && (g.soRefId === soId || g.linked_so_id === soId || g.linked_so_number === po.linkedSoNumber);
                        });
                        if (linkedGrn && (linkedGrn.fabricType || linkedGrn.item)) return (linkedGrn.fabricType || linkedGrn.item).trim();
                    }
                    const outwardIssue = (db.outwards || []).find(out => {
                        const state = parseOutwardWizardState(out);
                        return state.type === 'inhouse' && (out.poRefId === po.id || out.poRefId === po.number);
                    });
                    if (outwardIssue && outwardIssue.dispatchedPackages) {
                        for (const pkg of outwardIssue.dispatchedPackages) {
                            const linkedGrn = db.grns.find(g => g.id === pkg.grnId);
                            if (linkedGrn && (linkedGrn.fabricType || linkedGrn.item)) return (linkedGrn.fabricType || linkedGrn.item).trim();
                        }
                    }
                    return null;
                })();

                const matchesFabric = (resolvedPlainFabric && resolvedPlainFabric.toLowerCase().trim() === mr.fabricName.toLowerCase().trim());
                if (!matchesFabric) return;

                // A. Allotted from FI/INH
                const linkedOutwards = (db.outwards || []).filter(o => {
                    if ((o.status || '').toLowerCase() === 'cancelled') return false;
                    const state = parseOutwardWizardState(o);
                    return state.type === 'inhouse' && (o.poRefId === po.id || o.poRefId === po.number || o.linked_po_id === po.id);
                });
                allottedQty += linkedOutwards.reduce((sum, o) => sum + (parseFloat(o.qty) || 0), 0);

                // B. Requisitions issued
                const linkedReqs = (db.requisitionSlips || []).filter(r => {
                    if ((r.status || '').toLowerCase() === 'cancelled') return false;
                    const reqType = (r.type || 'Fabric').toLowerCase();
                    if (reqType !== 'fabric') return false;
                    const reqMeta = parseMetadataFromRemarks(r.remarks, '__REQ_METADATA__');
                    const linkedPoId = reqMeta.inhousePoId || r.inhousePoId || '';
                    return linkedPoId === po.id || linkedPoId === po.number;
                });
                requisitionsIssued += linkedReqs.reduce((sum, r) => {
                    const items = r.items || [];
                    return sum + items.reduce((s, it) => s + (parseFloat(it.qty) || 0), 0);
                }, 0);

                // C. Consumed in production slips
                const linkedProds = (db.productionSlips || []).filter(s => {
                    if ((s.status || '').toLowerCase() === 'cancelled') return false;
                    return s.poId === po.id || s.poNumber === po.number;
                });
                totalConsumed += linkedProds.reduce((sum, s) => {
                    const rows = s.rows || s.items || [];
                    return sum + rows.reduce((sSum, r) => sSum + (parseFloat(r.fabricConsumption) || parseFloat(r.qty) || 0), 0);
                }, 0);
            });

            const mainStock = Math.max(0, allottedQty - requisitionsIssued);
            const machineStock = Math.max(0, requisitionsIssued - totalConsumed);
            const unit = 'Mtr';
            let statusBadge = '';
            
            if (machineStock >= mr.reqQty) {
                statusBadge = '<span class="badge badge-green">=� Ready on Machine</span>';
            } else if (machineStock + mainStock >= mr.reqQty) {
                statusBadge = '<span class="badge badge-orange">=� In Warehouse (Needs Issue)</span>';
            } else {
                const shortage = mr.reqQty - (machineStock + mainStock);
                statusBadge = `<span class="badge badge-red">=4 Shortage: ${shortage.toFixed(2)} ${unit}</span>`;
            }

            return `
                <tr>
                    <td><strong>${mr.machineName}</strong></td>
                    <td>${mr.fabricName} (Fabric)</td>
                    <td><strong>${mr.reqQty.toFixed(2)} ${unit}</strong></td>
                    <td>${mainStock.toFixed(2)} ${unit} (Allotted: ${allottedQty.toFixed(2)} | Issued: ${requisitionsIssued.toFixed(2)})</td>
                    <td>${machineStock.toFixed(2)} ${unit}</td>
                    <td>${statusBadge}</td>
                </tr>
            `;
        }

        const item = db.items.find(i => i.id === mr.itemId);
        const itemName = item ? item.name : 'Unknown Item';
        const unit = item ? (item.unit || 'm') : '';

        const purForItem = db.purchases.filter(p => p.itemId === mr.itemId);
        let totalPurchased = purForItem.reduce((sum, p) => sum + (p.qty || 0), 0);
        if (item) {
            const grnsForItem = (db.grns || []).filter(g => {
                const state = parseGrnWizardState(g);
                return state.type === 'consumable' && g.fabricType === item.name;
            });
            totalPurchased += grnsForItem.reduce((sum, g) => sum + (parseFloat(g.qty) || 0), 0);
        }
        totalPurchased += (item?.openingStockQty || 0);

        const totalIssued = (db.outwards || []).filter(out => {
            const state = parseOutwardWizardState(out);
            return state.type === 'inhouse';
        }).reduce((sum, out) => {
            if (!out.poRefId) return sum;
            const linkedPo = db.pos.find(p => p.id === out.poRefId);
            if (!linkedPo) return sum;
            const finishedItemId = linkedPo.items?.[0]?.itemId || '';
            const bom = db.boms.find(b => b.id === linkedPo.bomId || (b.code && linkedPo.bomNumber && String(b.code).toLowerCase() === String(linkedPo.bomNumber).toLowerCase())) || 
                        db.boms.find(b => b.finishedItemId === finishedItemId);
            if (bom) {
                const hasIng = bom.ingredients?.some(ing => ing.itemId === mr.itemId);
                if (hasIng) {
                    return sum + (parseFloat(out.qty) || 0);
                }
            }
            return sum;
        }, 0);

        const mainStock = Math.max(0, totalPurchased - totalIssued);

        const totalConsumed = (db.productionSlips || []).reduce((sum, slip) => {
            const poRef = db.pos.find(p => p.id === slip.poId);
            const finItem = poRef?.items?.[0]?.itemId;
            const matchBom = poRef ? (db.boms.find(b => b.id === poRef.bomId || (b.code && poRef.bomNumber && String(b.code).toLowerCase() === String(poRef.bomNumber).toLowerCase())) || 
                             db.boms.find(b => b.finishedItemId === finItem)) : null;
            if (matchBom) {
                const matchIng = matchBom.ingredients?.find(it => it.itemId === mr.itemId);
                if (matchIng) {
                    return sum + (slip.qty * matchIng.qty / (matchBom.batchQty || 1));
                }
            }
            return sum;
        }, 0);

        const machineStock = Math.max(0, totalIssued - totalConsumed);

        let statusBadge = '';
        if (machineStock >= mr.reqQty) {
            statusBadge = '<span class="badge badge-green">=� Ready on Machine</span>';
        } else if (machineStock + mainStock >= mr.reqQty) {
            statusBadge = '<span class="badge badge-orange">=� In Warehouse (Needs Issue)</span>';
        } else {
            const shortage = mr.reqQty - (machineStock + mainStock);
            statusBadge = `<span class="badge badge-red">=4 Shortage: ${shortage.toFixed(2)} ${unit}</span>`;
        }

        return `
            <tr>
                <td><strong>${mr.machineName}</strong></td>
                <td>${itemName}</td>
                <td><strong>${mr.reqQty.toFixed(2)} ${unit}</strong></td>
                <td>${mainStock.toFixed(2)} ${unit}</td>
                <td>${machineStock.toFixed(2)} ${unit}</td>
                <td>${statusBadge}</td>
            </tr>
        `;
    }).join('');
};

window.saveProductionPlan = async function() {
    if (window.validateVoucherMaker && !(await window.validateVoucherMaker('prod-plan-modal'))) return;
    try {
        const editId = document.getElementById('prod-plan-edit-id').value;
        const planNumber = document.getElementById('prod-plan-number').value;
        const samplingNumber = document.getElementById('prod-plan-sampling-number').value;
        const planDate = document.getElementById('prod-plan-date').value;
        const planType = document.getElementById('prod-plan-type').value;
        const remarks = document.getElementById('prod-plan-remarks').value;

        if (!planDate) {
            showToast('Please select a plan date.', 'error');
            return;
        }

        const machineId = document.getElementById('prod-plan-machine-select').value;
        const operator = document.getElementById('prod-plan-operator').value;
        
        if (!machineId) {
            showToast('Please select a machine.', 'error');
            return;
        }

        const machine = db.machines.find(m => m.id === machineId);
        
        const blockPos = [];
        let expectationObj = {};
        let isValid = true;

        if (planType === 'Full Sampling') {
            const exp24hStitch = parseFloat(document.getElementById('prod-plan-exp-24h-stitch-sampling')?.value) || 0;
            const samplingHours = parseFloat(document.getElementById('prod-plan-sampling-hours')?.value) || 0;
            const stitchesUsed = parseFloat(document.getElementById('prod-plan-stitches-used')?.value) || 0;
            expectationObj = {
                stitch24h: exp24hStitch,
                samplingHours: samplingHours,
                stitchesUsed: stitchesUsed
            };
        } else {
            const poTbody = document.getElementById('prod-plan-po-rows-body');
            const poRows = poTbody ? poTbody.rows : [];
            if (poRows.length === 0) {
                showToast('Please add at least one PO row.', 'error');
                return;
            }

            for (let j = 0; j < poRows.length; j++) {
                const row = poRows[j];
                const poSelect = row.querySelector('.row-po-select');
                const poId = poSelect ? poSelect.value : '';
                const qtyVal = row.querySelector('.row-qty')?.value || '';
                const thanVal = row.querySelector('.row-than')?.value || '';
                const conversionVal = row.querySelector('.row-conversion')?.value || '';
                
                if (!poId || !qtyVal) {
                    isValid = false;
                    break;
                }

                const po = db.pos.find(p => p.id === poId);
                const targetQty = parseFloat(qtyVal);

                blockPos.push({
                    poId,
                    poNumber: po ? po.number : '',
                    designName: row.querySelector('.row-design')?.value || '',
                    targetThans: thanVal ? parseFloat(thanVal) : null,
                    conversion: conversionVal ? parseFloat(conversionVal) : null,
                    targetQty,
                    designStitch: row.dataset.designStitch ? parseFloat(row.dataset.designStitch) : null,
                    runningMinThan: row.dataset.runningMinThan ? parseFloat(row.dataset.runningMinThan) : null
                });
            }
            
            if (!isValid) {
                showToast('Please fill all PO and target quantity fields in all rows.', 'error');
                return;
            }

            const exp24hStitch = parseFloat(document.getElementById('prod-plan-exp-24h-stitch')?.value) || 0;
            expectationObj = {
                stitch24h: exp24hStitch,
                targetMeters: blockPos.reduce((sum, p) => sum + (p.targetQty || 0), 0)
            };
            if (planType === 'Partial Sampling') {
                const samplingHours = parseFloat(document.getElementById('prod-plan-sampling-hours')?.value) || 0;
                const stitchesUsed = parseFloat(document.getElementById('prod-plan-stitches-used')?.value) || 0;
                expectationObj.samplingHours = samplingHours;
                expectationObj.stitchesUsed = stitchesUsed;
            }
        }

        const items = [{
            machineId,
            machineNo: machine ? machine.machineNo : '',
            operator,
            pos: blockPos,
            expectation: expectationObj
        }];

        let totalTargetQty = 0;
        let machinesPlanned = items.length;
        
        items.forEach(m => {
            m.pos.forEach(p => {
                totalTargetQty += p.targetQty;
            });
        });

        const record = {
            company_id: currentCompany ? currentCompany.id : 'co3',
            number: planNumber || samplingNumber,
            samplingNumber: samplingNumber,
            sampling_number: samplingNumber,
            planDate: planDate,
            date: planDate,
            planningType: planType,
            planning_type: planType,
            remarks: remarks,
            items: items,
            machinesPlanned: machinesPlanned,
            totalTargetQty: totalTargetQty
        };

        let prodRecord, sampRecord;
        if (planType === 'Partial Sampling') {
            const prodItems = items.map(m => ({
                machineId: m.machineId,
                machineNo: m.machineNo,
                operator: m.operator,
                pos: m.pos,
                expectation: {
                    stitch24h: m.expectation.stitch24h,
                    targetMeters: m.expectation.targetMeters
                }
            }));

            const sampItems = items.map(m => ({
                machineId: m.machineId,
                machineNo: m.machineNo,
                operator: m.operator,
                pos: [],
                expectation: {
                    stitch24h: m.expectation.stitch24h,
                    samplingHours: m.expectation.samplingHours,
                    stitchesUsed: m.expectation.stitchesUsed
                }
            }));

            prodRecord = {
                id: editId || uid(),
                company_id: currentCompany ? currentCompany.id : 'co3',
                number: planNumber,
                planDate: planDate,
                date: planDate,
                planningType: 'Production',
                planning_type: 'Production',
                remarks: remarks,
                items: prodItems,
                machinesPlanned: machinesPlanned,
                totalTargetQty: totalTargetQty
            };

            sampRecord = {
                id: uid(),
                company_id: currentCompany ? currentCompany.id : 'co3',
                number: samplingNumber,
                planDate: planDate,
                date: planDate,
                planningType: 'Full Sampling',
                planning_type: 'Full Sampling',
                remarks: remarks,
                items: sampItems,
                machinesPlanned: machinesPlanned,
                };
        

            try {
                await saveToSupabase('production_plans', prodRecord);
                await saveToSupabase('production_plans', sampRecord);
                const remarksInputVal = document.getElementById('prod-plan-remarks') ? document.getElementById('prod-plan-remarks').value : '';
                await window.saveUserRemarks(prodRecord.id, remarksInputVal);
                await window.saveUserRemarks(sampRecord.id, remarksInputVal);
                
                if (editId) {
                    const idx = rawDB.productionPlans.findIndex(x => x.id === editId);
                    if (idx !== -1) {
                        rawDB.productionPlans[idx] = prodRecord;
                    }
                } else {
                    rawDB.productionPlans.push(prodRecord);
                }
                rawDB.productionPlans.push(sampRecord);
            } catch (e) {
                throw e;
            }
        } else {
        try {
            if (editId) {
                record.id = editId;
                await saveToSupabase('production_plans', record);
                const remarksInputVal = document.getElementById('prod-plan-remarks') ? document.getElementById('prod-plan-remarks').value : '';
                await window.saveUserRemarks(record.id, remarksInputVal);
                const idx = rawDB.productionPlans.findIndex(x => x.id === editId);
                if (idx !== -1) {
                    rawDB.productionPlans[idx] = { ...rawDB.productionPlans[idx], ...record };
                }
            } else {
                record.id = uid();
                await saveToSupabase('production_plans', record);
                const remarksInputVal = document.getElementById('prod-plan-remarks') ? document.getElementById('prod-plan-remarks').value : '';
                await window.saveUserRemarks(record.id, remarksInputVal);
                rawDB.productionPlans.push(record);
            }
        } catch (e) {
            throw e;
        }
    }

        if (currentCompany) {
            localStorage.setItem('local_production_plans_' + currentCompany.id, JSON.stringify(
                rawDB.productionPlans.filter(p => !p.company_id || p.company_id === currentCompany.id)
            ));
        }

        applyFinancialYearFilters();
        closeModal('prod-plan-modal', true);
        renderProductionPlanTable();
        if (typeof renderSamplingPlanTable === 'function') renderSamplingPlanTable();
        showToast('Plan saved successfully', 'success');
        
        setTimeout(() => {
            const savedRecord = (planType === 'Partial Sampling') ? prodRecord : record;
            const hasAnyReqWritePerm = checkPermission('requisition_slip_fabric', 'write') || 
                                       checkPermission('requisition_slip_consumable', 'write');
            if (window.promptRequisitionsForPlan && hasAnyReqWritePerm) {
                window.promptRequisitionsForPlan(savedRecord);
            }
        }, 300);
    } catch(e) {
        showToast(`Save plan failed: ${e.message || e}`, 'error');
    }
};

window.promptRequisitionsForPlan = async function(planRecord) {
    if (!planRecord) return;
    
    return new Promise((resolve) => {
        const backdrop = document.createElement('div');
        backdrop.style.position = 'fixed';
        backdrop.style.top = '0';
        backdrop.style.left = '0';
        backdrop.style.width = '100vw';
        backdrop.style.height = '100vh';
        backdrop.style.backgroundColor = 'rgba(0, 0, 0, 0.6)';
        backdrop.style.backdropFilter = 'blur(4px)';
        backdrop.style.display = 'flex';
        backdrop.style.justifyContent = 'center';
        backdrop.style.alignItems = 'center';
        backdrop.style.zIndex = '99999';
        backdrop.style.opacity = '0';
        backdrop.style.transition = 'opacity 0.2s ease';
        
        const box = document.createElement('div');
        box.style.background = 'var(--bg-card, #1a1e29)';
        box.style.border = '1px solid var(--border, rgba(255,255,255,0.08))';
        box.style.borderRadius = '16px';
        box.style.padding = '24px';
        box.style.width = '420px';
        box.style.boxShadow = '0 20px 25px -5px rgba(0,0,0,0.3)';
        box.style.transform = 'translateY(20px)';
        box.style.transition = 'transform 0.2s ease';
        
        box.innerHTML = `
            <h3 style="margin-top:0; margin-bottom:12px; font-family:'Outfit',sans-serif; color:var(--text-primary, #fff);">Generate Requisitions</h3>
            <p style="color:var(--text-secondary, #a0aec0); font-size:14px; margin-bottom:20px; line-height:1.5;">Would you like to generate Requisition Slips for this production plan? Select an option below:</p>
            <div style="display:flex; flex-direction:column; gap:10px;">
                <button id="btn-choice-both" class="btn btn-primary" style="justify-content:center; padding:10px;">Fabric &amp; Consumables (Both)</button>
                <button id="btn-choice-fabric" class="btn btn-secondary" style="justify-content:center; padding:10px; background:var(--bg-input);">Fabric Only</button>
                <button id="btn-choice-consumable" class="btn btn-secondary" style="justify-content:center; padding:10px; background:var(--bg-input);">Consumable Only</button>
                <button id="btn-choice-skip" class="btn btn-ghost" style="justify-content:center; padding:10px; color:var(--text-muted);">Skip / No Requisition</button>
            </div>
        `;
        
        backdrop.appendChild(box);
        document.body.appendChild(backdrop);

        const hasFabricWrite = checkPermission('requisition_slip_fabric', 'write');
        const hasConsumableWrite = checkPermission('requisition_slip_consumable', 'write');
        
        if (!hasFabricWrite || !hasConsumableWrite) {
            const btnBoth = backdrop.querySelector('#btn-choice-both');
            if (btnBoth) btnBoth.style.display = 'none';
        }
        if (!hasFabricWrite) {
            const btnFab = backdrop.querySelector('#btn-choice-fabric');
            if (btnFab) btnFab.style.display = 'none';
        }
        if (!hasConsumableWrite) {
            const btnCons = backdrop.querySelector('#btn-choice-consumable');
            if (btnCons) btnCons.style.display = 'none';
        }
        
        setTimeout(() => {
            backdrop.style.opacity = '1';
            box.style.transform = 'translateY(0)';
        }, 10);
        
        const closeDialog = () => {
            backdrop.style.opacity = '0';
            box.style.transform = 'translateY(20px)';
            setTimeout(() => {
                backdrop.remove();
            }, 200);
        };
        
        backdrop.querySelector('#btn-choice-both').onclick = async () => {
            closeDialog();
            window.nextRequisitionFlow = {
                planRecord: planRecord,
                nextType: 'Consumable'
            };
            await window.openRequisitionModalForPlan(planRecord, 'Fabric');
            resolve();
        };
        
        backdrop.querySelector('#btn-choice-fabric').onclick = async () => {
            closeDialog();
            window.nextRequisitionFlow = null;
            await window.openRequisitionModalForPlan(planRecord, 'Fabric');
            resolve();
        };
        
        backdrop.querySelector('#btn-choice-consumable').onclick = async () => {
            closeDialog();
            window.nextRequisitionFlow = null;
            await window.openRequisitionModalForPlan(planRecord, 'Consumable');
            resolve();
        };
        
        backdrop.querySelector('#btn-choice-skip').onclick = () => {
            closeDialog();
            window.nextRequisitionFlow = null;
            resolve();
        };
    });
};

window.openRequisitionModalForPlan = async function(planRecord, type) {
    try {
        const opened = await window.openRequisitionModal(null, type);
        if (!opened) return;
        
        const typeSelect = document.getElementById('req-type');
        if (typeSelect) {
            typeSelect.value = type;
            window.onReqTypeChange();
        }
        
        const poIds = new Set();
        if (planRecord.items) {
            planRecord.items.forEach(item => {
                if (item.pos) {
                    item.pos.forEach(p => {
                        if (p.poId) poIds.add(p.poId);
                    });
                }
            });
        }
        const poIdArray = Array.from(poIds);
        if (poIdArray.length > 0) {
            const poSelect = document.getElementById('req-inhouse-po');
            if (poSelect) {
                poSelect.value = poIdArray[0];
                if (typeof window.onReqInhousePoChange === 'function') {
                    window.onReqInhousePoChange();
                }
            }
        }
        
        const tbody = document.getElementById('req-items-grid-body');
        if (tbody) tbody.innerHTML = '';
        
        if (type === 'Fabric') {
            const fabricRequirements = {};
            if (planRecord.items) {
                planRecord.items.forEach(item => {
                    if (item.pos) {
                        item.pos.forEach(p => {
                            const po = (db.pos || []).find(x => x.id === p.poId);
                            if (!po) return;
                            const targetQty = parseFloat(p.targetQty) || 0;
                            
                            let resolvedPlainFabric = (function() {
                                const soId = po.linkedSoId || po.soRef;
                                if (soId) {
                                    const linkedGrn = (db.grns || []).find(g => {
                                        const wState = parseGrnWizardState(g);
                                        const isPlain = wState.type === 'fabric' && wState.subType === 'plain';
                                        const matchesSo = g.soRefId === soId || 
                                                          g.linked_so_id === soId || 
                                                          g.linked_so_number === po.linkedSoNumber ||
                                                          (g.soLinks && g.soLinks.some(link => link === soId || (link && link.soId === soId)));
                                        return isPlain && matchesSo;
                                    });
                                    if (linkedGrn && (linkedGrn.fabricType || linkedGrn.item)) {
                                        return (linkedGrn.fabricType || linkedGrn.item).trim();
                                    }
                                }
                                const outwardIssue = (db.outwards || []).find(out => {
                                    const state = parseOutwardWizardState(out);
                                    return state.type === 'inhouse' && (out.poRefId === po.id || out.poRefId === po.number);
                                });
                                if (outwardIssue && outwardIssue.dispatchedPackages) {
                                    for (const pkg of outwardIssue.dispatchedPackages) {
                                        const linkedGrn = (db.grns || []).find(g => g.id === pkg.grnId);
                                        const wState = linkedGrn ? parseGrnWizardState(linkedGrn) : null;
                                        if (wState && wState.subType === 'plain') {
                                            const slip = linkedGrn && linkedGrn.packageSlips ? linkedGrn.packageSlips[pkg.slipIndex] : null;
                                            const fabricName = (slip ? slip.fabricType : null) || linkedGrn.fabricType || linkedGrn.item;
                                            if (fabricName) return fabricName.trim();
                                        }
                                    }
                                }
                                return null;
                            })();
                            
                            const poFabrics = new Set();
                            if (resolvedPlainFabric) {
                                poFabrics.add(resolvedPlainFabric);
                            } else {
                                (db.outwards || []).forEach(out => {
                                    const state = parseOutwardWizardState(out);
                                    if (state.type === 'inhouse' && (out.poRefId === po.id || out.poRefId === po.number)) {
                                        (out.dispatchedPackages || []).forEach(pkg => {
                                            const linkedGrn = (db.grns || []).find(g => g.id === pkg.grnId);
                                            const slip = linkedGrn && linkedGrn.packageSlips ? linkedGrn.packageSlips[pkg.slipIndex] : null;
                                            const fabricName = (slip ? slip.fabricType : null) || (linkedGrn ? (linkedGrn.fabricType || linkedGrn.item) : '') || 'Plain Fabric';
                                            if (fabricName) poFabrics.add(fabricName.trim());
                                        });
                                    }
                                });
                            }
                            
                            if (poFabrics.size === 0) {
                                poFabrics.add('Plain Fabric');
                            }
                            
                            const qtyPerFabric = targetQty / poFabrics.size;
                            poFabrics.forEach(fab => {
                                fabricRequirements[fab] = (fabricRequirements[fab] || 0) + qtyPerFabric;
                            });
                        });
                    }
                });
            }
            
            Object.keys(fabricRequirements).forEach(fabricName => {
                const qty = fabricRequirements[fabricName];
                window.addReqRow(fabricName, qty.toFixed(2));
            });
            
        } else if (type === 'Consumable') {
            const consumableRequirements = {};
            if (planRecord.items) {
                planRecord.items.forEach(item => {
                    if (item.pos) {
                        item.pos.forEach(p => {
                            const po = (db.pos || []).find(x => x.id === p.poId);
                            if (!po) return;
                            const qtyVal = parseFloat(p.targetQty) || 0;
                            
                            const finishedItemId = po.items?.[0]?.itemId || '';
                            const bom = (db.boms || []).find(b => b.id === po.bomId || (b.code && po.bomNumber && String(b.code).toLowerCase() === String(po.bomNumber).toLowerCase())) || 
                                        (db.boms || []).find(b => b.finishedItemId === finishedItemId);
                            if (bom) {
                                const ingredients = bom.ingredients || [];
                                ingredients.forEach(ing => {
                                    if (ing.itemId === 'METADATA_DESIGN_STITCH' || ing.itemId === 'METADATA_DESIGN_REPEAT_STR') return;
                                    const reqQty = (ing.qty || 0) * (qtyVal / (bom.batchQty || 1));
                                    consumableRequirements[ing.itemId] = (consumableRequirements[ing.itemId] || 0) + reqQty;
                                });
                            }
                        });
                    }
                });
            }
            
            Object.keys(consumableRequirements).forEach(itemId => {
                const qty = consumableRequirements[itemId];
                window.addReqRow(itemId, qty.toFixed(2));
            });
        }
    } catch (err) {
        console.error("Error populating requisition for plan:", err);
        showToast("Error populating requirements: " + err.message, "error");
    }
};


window.deleteProductionPlan = async function(id) {
    const plan = (rawDB.productionPlans || []).find(p => p.id === id);
    const planNo = plan ? (plan.planNo || plan.number) : '';
    if (!(await window.showSmartConfirm('Delete Plan', 'Are you sure you want to delete this Plan?'))) return;
    try {
        await deleteFromSupabase('production_plans', id);
        rawDB.productionPlans = rawDB.productionPlans.filter(p => p.id !== id);
        applyFinancialYearFilters();
        renderProductionPlanTable();
        if (typeof renderSamplingPlanTable === 'function') renderSamplingPlanTable();
        logUserAction('Production Plans', 'Deleted', `Deleted Production/Sampling Plan: ${planNo}`);
        showToast('Plan deleted', 'info');
    } catch(e) {
        showToast(`Delete failed: ${e.message || e}`, 'error');
    }
};

window.prodPlanBulkDelete = async function() {
    const checkboxes = document.querySelectorAll('.chk-select-prod-plan');
    const idsToDelete = Array.from(checkboxes).filter(cb => cb.checked).map(cb => cb.value);
    if (idsToDelete.length === 0) { showToast('No Production Plans selected.', 'info'); return; }
    if (!(await window.showSmartConfirm('Delete Production Plans', `Are you sure you want to delete the ${idsToDelete.length} selected Production Plans?`))) return;
    
    try {
        const deletedNos = [];
        for (const id of idsToDelete) {
            const plan = (rawDB.productionPlans || []).find(p => p.id === id);
            if (plan) deletedNos.push(plan.planNo || plan.number);
            await deleteFromSupabase('production_plans', id);
            rawDB.productionPlans = rawDB.productionPlans.filter(p => p.id !== id);
        }
        
        if (currentCompany) {
            localStorage.setItem('local_production_plans_' + currentCompany.id, JSON.stringify(
                rawDB.productionPlans.filter(p => !p.company_id || p.company_id === currentCompany.id)
            ));
        }

        applyFinancialYearFilters();
        renderProductionPlanTable();
        const headerChk = document.getElementById('prod-plan-select-all');
        if (headerChk) headerChk.checked = false;
        toggleBulkDeleteButton('prod-plan');
        logUserAction('Production Plans', 'Deleted', `Bulk deleted production plans: ${deletedNos.join(', ')}`);
        showToast(`Successfully deleted ${idsToDelete.length} Production Plans.`, 'success');
    } catch (err) {
        console.error("Bulk delete failed:", err);
        showToast(`Bulk delete failed: ${err.message || err}`, 'error');
    }
};

