window.renderExpectedProductionTable = function() {
    const search = (document.getElementById('prod-expected-search')?.value || '').toLowerCase();
    const tbody = document.getElementById('prod-expected-table-body');
    if (!tbody) return;
    db.productionPlans = db.productionPlans || [];

    const rows = [];
    db.productionPlans.forEach(p => {
        const planType = p.planningType || p.planning_type || 'Production';
        if (planType !== 'Production') return;

        const items = p.items || [];
        items.forEach(m => {
            const pos = m.pos || [];
            pos.forEach(po => {
                rows.push({
                    machineNo: m.machineNo || '',
                    planDate: p.planDate || p.date || '',
                    planNumber: p.number || '',
                    poNumber: po.poNumber || '',
                    designName: po.designName || '',
                    targetQty: po.targetQty || 0,
                    operator: m.operator || ''
                });
            });
        });
    });

    const filteredRows = rows.filter(r => {
        return r.machineNo.toLowerCase().includes(search) ||
               formatDate(r.planDate).toLowerCase().includes(search) ||
               r.planNumber.toLowerCase().includes(search) ||
               r.poNumber.toLowerCase().includes(search) ||
               r.designName.toLowerCase().includes(search) ||
               r.operator.toLowerCase().includes(search);
    });

    filteredRows.sort((a, b) => {
        const numA = parseInt(String(a.planNumber || '').split('/').pop()) || 0;
        const numB = parseInt(String(b.planNumber || '').split('/').pop()) || 0;
        return numB - numA;
    });

    if (filteredRows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" class="empty-row">No Expected Production scheduled.</td></tr>';
        return;
    }

    tbody.innerHTML = filteredRows.map(r => `
        <tr>
            <td><strong>${r.machineNo || '-'}</strong></td>
            <td>${formatDate(r.planDate)}</td>
            <td>${r.planNumber || '-'}</td>
            <td>${r.poNumber || '-'}</td>
            <td><strong>${r.designName || '-'}</strong></td>
            <td><strong>${r.targetQty}</strong></td>
            <td>${r.operator || '-'}</td>
        </tr>
    `).join('');
};

window.renderExpectedSamplingTable = function() {
    const search = (document.getElementById('samp-expected-search')?.value || '').toLowerCase();
    const tbody = document.getElementById('samp-expected-table-body');
    if (!tbody) return;
    db.productionPlans = db.productionPlans || [];

    const rows = [];
    db.productionPlans.forEach(p => {
        const planType = p.planningType || p.planning_type || 'Production';
        if (planType !== 'Full Sampling' && planType !== 'Partial Sampling') return;

        const items = p.items || [];
        items.forEach(m => {
            const pos = m.pos || [];
            if (pos.length === 0) {
                rows.push({
                    machineNo: m.machineNo || '',
                    planDate: p.planDate || p.date || '',
                    planNumber: p.samplingNumber || p.sampling_number || p.number || '',
                    poNumber: '-',
                    designName: 'Full Sampling',
                    targetQty: '-',
                    operator: m.operator || ''
                });
            } else {
                pos.forEach(po => {
                    rows.push({
                        machineNo: m.machineNo || '',
                        planDate: p.planDate || p.date || '',
                        planNumber: p.samplingNumber || p.sampling_number || p.number || '',
                        poNumber: po.poNumber || '',
                        designName: po.designName || '',
                        targetQty: po.targetQty || 0,
                        operator: m.operator || ''
                    });
                });
            }
        });
    });

    const filteredRows = rows.filter(r => {
        return r.machineNo.toLowerCase().includes(search) ||
               formatDate(r.planDate).toLowerCase().includes(search) ||
               r.planNumber.toLowerCase().includes(search) ||
               r.poNumber.toLowerCase().includes(search) ||
               r.designName.toLowerCase().includes(search) ||
               r.operator.toLowerCase().includes(search);
    });

    filteredRows.sort((a, b) => {
        const numA = parseInt(String(a.planNumber || '').split('/').pop()) || 0;
        const numB = parseInt(String(b.planNumber || '').split('/').pop()) || 0;
        return numB - numA;
    });

    if (filteredRows.length === 0) {
        tbody.innerHTML = '<tr><td colspan="7" class="empty-row">No Expected Sampling scheduled.</td></tr>';
        return;
    }

    tbody.innerHTML = filteredRows.map(r => `
        <tr>
            <td><strong>${r.machineNo || '-'}</strong></td>
            <td>${formatDate(r.planDate)}</td>
            <td>${r.planNumber || '-'}</td>
            <td>${r.poNumber || '-'}</td>
            <td><strong>${r.designName || '-'}</strong></td>
            <td><strong>${r.targetQty}</strong></td>
            <td>${r.operator || '-'}</td>
        </tr>
    `).join('');
};

// ===== GENERIC TRANSACTION VOUCHERS (INVOICES / VOUCHERS / RETURNS) =====
window.getGrnPendingQty = function(grn, currentEditId) {
    const totalGRNQty = parseFloat(grn.qty || 0);
    let consumedQty = 0;
    (rawDB.genericTransactions || []).forEach(gt => {
        if (gt.status === 'Cancelled') return;
        if (gt.type === 'voucher' && String(gt.id) !== String(currentEditId || '')) {
            (gt.items || []).forEach(it => {
                if (String(it.orderId) === String(grn.id) || String(it.orderNumber) === String(grn.grnNo || grn.number)) {
                    consumedQty += parseFloat(it.invoicedQty || 0);
                }
            });
        }
    });
    return Math.max(0, totalGRNQty - consumedQty);
};

window.getPoBalanceQty = function(po) {
    if (!po) return 0;
    const totalPOQty = parseFloat(po.qty || po.quantity || po.items?.reduce((s, x) => s + parseFloat(x.qty || 0), 0) || 0);
    let consumedInGRNs = 0;
    (db.grns || []).forEach(g => {
        if (g.status === 'Cancelled') return;
        const poRefId = g.poRefId || g.linked_po_id || g.poId || g.poRef;
        const poRefNo = g.poNumber || g.linked_po_number;
        if (String(poRefId) === String(po.id) || (poRefNo && String(po.number).trim().toLowerCase() === String(poRefNo).trim().toLowerCase())) {
            consumedInGRNs += parseFloat(g.qty || 0);
        }
    });
    return Math.max(0, totalPOQty - consumedInGRNs);
};

window.getGstRateFromOrder = function(order, isPo, itemObj) {
    if (!order) return 18;
    let typeName = '';
    if (isPo) {
        typeName = order.purchaseType || '';
        if (!typeName && order.remarks) {
            const match = order.remarks.match(/\[Purchase Type:\s*([^\]]+)\]/);
            if (match) typeName = match[1];
        }
    } else {
        typeName = order.salesType || '';
        if (!typeName && order.remarks) {
            const match = order.remarks.match(/\[Sales Type:\s*([^\]]+)\]/);
            if (match) typeName = match[1];
        }
    }
    
    if (typeName) {
        const typeMatch = typeName.match(/(\d+)\s*%/);
        if (typeMatch) {
            return parseInt(typeMatch[1], 10);
        }
        if (typeName.toLowerCase().includes('exempt') || typeName.toLowerCase().includes('nil')) {
            return 0;
        }
    }
    
    // Fallback to HSN
    if (itemObj && itemObj.hsn && db.hsnCodes) {
        const hsnObj = db.hsnCodes.find(h => h.code === itemObj.hsn || h.id === itemObj.hsn);
        if (hsnObj) {
            if (hsnObj.taxCategory === 'Exempt' || hsnObj.taxCategory === 'Nil Rated') return 0;
            let typeString = typeName ? typeName.toUpperCase() : '';
            const isIgst = typeString.includes('IGST') || (isPo && typeString.includes('I-GST'));
            if (isIgst) {
                return parseFloat(hsnObj.igst) || (parseFloat(hsnObj.cgst) + parseFloat(hsnObj.sgst)) || 18;
            } else {
                return (parseFloat(hsnObj.cgst) + parseFloat(hsnObj.sgst)) || parseFloat(hsnObj.igst) || 18;
            }
        }
    }
    
    return 18;
};

