    const gst = currentGtxItems[idx].gst !== undefined ? currentGtxItems[idx].gst : 18;
    
    const baseAmount = qty * (isLogistics ? (rate + labourRate) : rate);
    const gstAmount = (baseAmount * gst) / 100;
    
    const el = document.getElementById(`gtx-item-amount-${idx}`);
    if (el) {
        el.innerHTML = `�${baseAmount.toFixed(2)}<br><small style="color:var(--text-muted)">Basic: �${baseAmount.toFixed(2)} | GST: �${gstAmount.toFixed(2)}</small>`;
    }
    calculateGtxTotal();
