window.loadCustomMasters = function() {
    const stored = localStorage.getItem('embroideryflow_custom_masters');
    if (stored) {
        try {
            const parsed = JSON.parse(stored);
            if (parsed && typeof parsed === 'object') {
                if (Array.isArray(parsed.doctypes)) window.customMasters.doctypes = parsed.doctypes;
                if (Array.isArray(parsed.fabrictypes)) window.customMasters.fabrictypes = parsed.fabrictypes;
                if (Array.isArray(parsed.packingtypes)) window.customMasters.packingtypes = parsed.packingtypes;
                if (Array.isArray(parsed.taxinames)) window.customMasters.taxinames = parsed.taxinames;
                if (Array.isArray(parsed.salestypes)) window.customMasters.salestypes = parsed.salestypes;
                if (Array.isArray(parsed.purchasetypes)) window.customMasters.purchasetypes = parsed.purchasetypes;
                if (Array.isArray(parsed.tdspolicies)) window.customMasters.tdspolicies = parsed.tdspolicies;
                if (Array.isArray(parsed.gstnatures)) window.customMasters.gstnatures = parsed.gstnatures;
                if (Array.isArray(parsed.freightJVs)) window.customMasters.freightJVs = parsed.freightJVs;
                if (Array.isArray(parsed.jobworktypes)) {
                    window.customMasters.jobworktypes = parsed.jobworktypes.map((x, idx) => {
                        if (typeof x === 'string') return { id: 'jw_' + idx, name: x };
                        return x;
                    });
                }
            }
        } catch(e) {}
    }
};

window.saveCustomMasters = async function() {
    localStorage.setItem('embroideryflow_custom_masters', JSON.stringify(window.customMasters));
    window.populateCustomDropdowns();
    if (currentCompany && window.supabase) {
        try {
            const settingsRec = {
                id: 'custom_masters_' + currentCompany.id,
                company_id: currentCompany.id,
                contactPerson: '__CUSTOM_MASTERS__',
                name: 'Custom Masters Settings',
                address: JSON.stringify(window.customMasters),
                gst: '',
                mobile: '',
                email: 'seeded',
                designation: 'seeded'
            };
            let localMasters = db.transporters.find(t => t.id === 'custom_masters_' + currentCompany.id);
            if (!localMasters) {
                localMasters = { id: 'custom_masters_' + currentCompany.id, company_id: currentCompany.id, contactPerson: '__CUSTOM_MASTERS__' };
                db.transporters.push(localMasters);
            }
            Object.assign(localMasters, settingsRec);
            const { data: existingTransporter } = await window.supabase.from('transporters').select('id').eq('id', settingsRec.id).maybeSingle();
            if (existingTransporter) {
                await window.supabase.from('transporters').update(settingsRec).eq('id', settingsRec.id);
            } else {
                await window.supabase.from('transporters').insert(settingsRec);
            }
        } catch (e) {
            console.error("Failed to sync custom masters to Supabase:", e);
        }
    }
};

window.populateCustomDropdowns = function() {
    // Populate Taxi Names select
    const taxiSel = document.getElementById('grn-taxi-name');
    if (taxiSel) {
        taxiSel.innerHTML = window.customMasters.taxinames.map(t => {
            const name = typeof t === 'object' && t !== null ? t.name : t;
            return `<option value="${name}">${name}</option>`;
        }).join('');
        reinitSearchableSelect(taxiSel);
    }
    const outwardTaxiSel = document.getElementById('outward-taxi-name');
    if (outwardTaxiSel && window.customMasters && window.customMasters.taxinames) {
        outwardTaxiSel.innerHTML = window.customMasters.taxinames.map(t => {
            const name = typeof t === 'object' && t !== null ? t.name : t;
            return `<option value="${name}">${name}</option>`;
        }).join('');
        reinitSearchableSelect(outwardTaxiSel);
    }
    
    // Populate Document Types select
    const docSel = document.getElementById('grn-party-doc-type');
    if (docSel) {
        docSel.innerHTML = window.customMasters.doctypes.map(d => {
            const name = typeof d === 'object' && d !== null ? d.name : d;
            return `<option value="${name}">${name}</option>`;
        }).join('');
        reinitSearchableSelect(docSel);
    }

    // Populate TDS Policy select for Customer and Vendor
    const custTdsSel = document.getElementById('cust-tds-policy');
    const tdsOptions = (window.customMasters.tdspolicies || []).map(p => {
        return `<option value="${p.id}">${p.name} (${p.rate}%, Sec ${p.section})</option>`;
    });
    tdsOptions.unshift('<option value="">-- No TDS --</option>');
    if (custTdsSel) {
        custTdsSel.innerHTML = tdsOptions.join('');
    }
    const vendTdsSel = document.getElementById('vend-tds-policy');
    if (vendTdsSel) {
        vendTdsSel.innerHTML = tdsOptions.join('');
    }

    // Populate Sales Type select for Sales Order
    let soSalesTypeSel = document.getElementById('so-sales-type');
    if (!soSalesTypeSel) {
        console.log("[populateCustomDropdowns] Dynamically creating missing 'so-sales-type' element...");
        const delDateEl = document.getElementById('so-delivery-date');
        if (delDateEl && delDateEl.parentElement && delDateEl.parentElement.parentElement) {
            const formRow = delDateEl.parentElement.parentElement;
            const newGroup = document.createElement('div');
            newGroup.className = 'form-group';
            newGroup.innerHTML = `
                <label>Sales Type *</label>
                <select id="so-sales-type" class="form-input">
                    <option value="">-- Select Sales Type --</option>
                </select>
            `;
            formRow.appendChild(newGroup);
            soSalesTypeSel = document.getElementById('so-sales-type');
        }
    }
    if (soSalesTypeSel) {
        const salesOptions = (window.customMasters.salestypes || []).map(s => {
            const name = typeof s === 'object' && s !== null ? s.name : s;
            return `<option value="${name}">${name}</option>`;
        });
        salesOptions.unshift('<option value="">-- Select Sales Type --</option>');
        soSalesTypeSel.innerHTML = salesOptions.join('');
        reinitSearchableSelect(soSalesTypeSel);
    }

    // Populate Purchase Type select for Purchase Order
    let poPurchaseTypeSel = document.getElementById('po-purchase-type');
    if (!poPurchaseTypeSel) {
        console.log("[populateCustomDropdowns] Dynamically creating missing 'po-purchase-type' element...");
        const delDateEl = document.getElementById('po-return-date');
        if (delDateEl && delDateEl.parentElement && delDateEl.parentElement.parentElement) {
            const formRow = delDateEl.parentElement.parentElement;
            const newGroup = document.createElement('div');
            newGroup.className = 'form-group';
            newGroup.id = 'po-purchase-type-group';
            newGroup.innerHTML = `
                <label>Purchase Type *</label>
                <select id="po-purchase-type" class="form-input" onchange="if(window.recalculatePOTotal) window.recalculatePOTotal();">
                    <option value="">-- Select Purchase Type --</option>
                </select>
            `;
            formRow.appendChild(newGroup);
            poPurchaseTypeSel = document.getElementById('po-purchase-type');
        }
    }
    if (poPurchaseTypeSel) {
        const purchaseOptions = (window.customMasters.purchasetypes || []).map(p => {
            const name = typeof p === 'object' && p !== null ? p.name : p;
            return `<option value="${name}">${name}</option>`;
        });
        purchaseOptions.unshift('<option value="">-- Select Purchase Type --</option>');
        poPurchaseTypeSel.innerHTML = purchaseOptions.join('');
        reinitSearchableSelect(poPurchaseTypeSel);
    }

    // Populate Sales/Purchase Type select for Generic Transactions (Sales Invoice)
    let gtxSalesTypeSel = document.getElementById('gtx-sales-type');
    let gtxSalesTypeLabel = document.getElementById('gtx-sales-type-label');
    if (gtxSalesTypeSel) {
        const type = document.getElementById('gtx-type')?.value;
        const isPurchase = (type === 'voucher' || type === 'purchasereturn' || type === 'payment');
        if (gtxSalesTypeLabel) {
            gtxSalesTypeLabel.textContent = isPurchase ? 'Purchase Type' : 'Sales Type';
        }
        const list = isPurchase ? 
                     (window.customMasters.purchasetypes || []) : (window.customMasters.salestypes || []);
        const options = list.map(s => {
            const name = typeof s === 'object' && s !== null ? s.name : s;
            return `<option value="${name}">${name}</option>`;
        });
        const placeholder = isPurchase ? '-- Select Purchase Type --' : '-- Select Sales Type --';
        options.unshift(`<option value="">${placeholder}</option>`);
        gtxSalesTypeSel.innerHTML = options.join('');
        reinitSearchableSelect(gtxSalesTypeSel);
    }
    
    // Populate Job Work Type select for PO modal
    const fjwJobWorkTypeSel = document.getElementById('po-fjw-jobwork-type');
    if (fjwJobWorkTypeSel) {
        const jwOptions = (window.customMasters.jobworktypes || []).map(j => {
            const name = typeof j === 'object' && j !== null ? j.name : j;
            return `<option value="${name}">${name}</option>`;
        });
        jwOptions.unshift('<option value="">-- Select Job Work Type --</option>');
        fjwJobWorkTypeSel.innerHTML = jwOptions.join('');
        reinitSearchableSelect(fjwJobWorkTypeSel);
    }

    // Populate Sales & Purchase Account select in Item Master
    if (typeof window.populateSalesAndPurchaseAccountDropdowns === 'function') {
        window.populateSalesAndPurchaseAccountDropdowns();
    }
};

