window.deleteCustomMasterItem = async function(key, idToDelete) {
    if (!checkPermission('masters', 'delete')) {
        showToast('Permission Denied', 'error');
        return;
    }

    if (key === 'gstnatures' || key === 'jobworktypes' || key === 'salesaccounts' || key === 'purchaseaccounts') {
        const rec = (window.customMasters[key] || []).find(x => (typeof x === 'object' ? x.id : x) === idToDelete || (typeof x === 'object' ? x.name : x) === idToDelete);
        if (!rec) {
            showToast(`Item not found.`, 'error');
            return;
        }
        const name = rec.name;
        if (await window.showSmartConfirm('Delete Item', `Are you sure you want to delete "${name}"?`)) {
            try {
                window.customMasters[key] = (window.customMasters[key] || []).filter(x => (typeof x === 'object' ? x.id : x) !== idToDelete && (typeof x === 'object' ? x.name : x) !== idToDelete);
                await window.saveCustomMasters();
                window.populateCustomDropdowns();
                switchMasterSubtab(currentMasterSubtab);
                showToast('Item deleted successfully', 'success');
            } catch(e) {
                console.error("[DELETE MASTER] Failed to delete custom master item:", e);
                showToast("Delete failed: " + (e.message || JSON.stringify(e)), 'error');
            }
        }
        return;
    }

    let table = '';
    let name = '';

    if (key === 'fabrictypes') {
        table = 'fabric_types';
        const rec = db.fabric_types.find(x => x.id === idToDelete);
        if (rec) name = rec.name;
    } else if (key === 'doctypes') {
        table = 'doctypes';
        const rec = db.doctypes.find(x => x.id === idToDelete);
        if (rec) name = rec.name;
    } else if (key === 'packingtypes') {
        table = 'packing_types';
        const rec = db.packing_types.find(x => x.id === idToDelete);
        if (rec) name = rec.name;
    } else if (key === 'taxinames') {
        table = 'taxi_names';
        const rec = db.taxi_names.find(x => x.id === idToDelete);
        if (rec) name = rec.name;
    } else if (key === 'salestypes') {
        table = 'sales_types';
        const rec = db.sales_types.find(x => x.id === idToDelete);
        if (rec) name = rec.name;
    } else if (key === 'purchasetypes') {
        table = 'purchase_types';
        const rec = db.purchase_types.find(x => x.id === idToDelete);
        if (rec) name = rec.name;
    }

    console.log(`[DELETE MASTER] Key: ${key}, ID to delete: ${idToDelete}, Table: ${table}, Name: ${name}`);

    if (!table || !idToDelete) {
        showToast(`Item not found in database. Please reload (F5).`, 'error');
        return;
    }

    if (await window.showSmartConfirm('Delete Template', `Are you sure you want to delete "${name}"?`)) {
        try {
            const { data, error, status } = await window.supabase.from(table).delete().eq('id', idToDelete).select();
            if (error) throw error;

            console.log(`[DELETE MASTER] Supabase response status: ${status}, deleted data:`, data);
            
            if (!data || data.length === 0) {
                console.warn(`[DELETE MASTER] Warning: No rows were deleted from database for ID ${idToDelete}`);
                showToast(`Delete request sent, but row not found in database. Please reload (F5).`, 'warning');
                return;
            }

            // Update memory DB
            if (key === 'fabrictypes') db.fabric_types = db.fabric_types.filter(x => x.id !== idToDelete);
            else if (key === 'doctypes') db.doctypes = db.doctypes.filter(x => x.id !== idToDelete);
            else if (key === 'packingtypes') db.packing_types = db.packing_types.filter(x => x.id !== idToDelete);
            else if (key === 'taxinames') db.taxi_names = db.taxi_names.filter(x => x.id !== idToDelete);
            else if (key === 'salestypes') db.sales_types = db.sales_types.filter(x => x.id !== idToDelete);
            else if (key === 'purchasetypes') db.purchase_types = db.purchase_types.filter(x => x.id !== idToDelete);

            // Sync window.customMasters
            window.customMasters.doctypes = db.doctypes.map(x => x.name);
            window.customMasters.fabrictypes = db.fabric_types.map(x => ({
                name: x.name,
                width: x.width || '',
                category: x.category || '',
                hsn: x.hsn || ''
            }));
            window.customMasters.packingtypes = db.packing_types.map(x => x.name);
            window.customMasters.taxinames = db.taxi_names.map(x => x.name);
            window.customMasters.salestypes = db.sales_types.map(x => ({
                id: x.id,
                name: x.name,
                gst_type: x.gst_type || 'CGST + SGST'
            }));
            window.customMasters.purchasetypes = db.purchase_types.map(x => ({
                id: x.id,
                name: x.name,
                gst_type: x.gst_type || 'CGST + SGST'
            }));

            window.populateCustomDropdowns();
            switchMasterSubtab(currentMasterSubtab);
            showToast('Item deleted successfully', 'success');
        } catch(e) {
            console.error("[DELETE MASTER] Failed to delete custom master item:", e);
            showToast("Delete failed: " + (e.message || JSON.stringify(e)), 'error');
        }
    }
};

