window.saveCustomMasterItem = async function() {
    const key = document.getElementById('custom-master-key').value;
    const val = document.getElementById('custom-master-value').value.trim();
    const oldVal = document.getElementById('custom-master-old-value').value;
    
    if (!val) {
        showToast('Value is required', 'error');
        return;
    }

    if (!currentCompany) {
        showToast('No active company selected', 'error');
        return;
    }
    const companyId = currentCompany.id;

    if (key === 'gstnatures' || key === 'jobworktypes' || key === 'salesaccounts' || key === 'purchaseaccounts') {
        if (key === 'gstnatures') {
            const code = document.getElementById('custom-master-gstnature-code').value.trim();
            if (oldVal) {
                const idx = window.customMasters.gstnatures.findIndex(x => (typeof x === 'object' ? x.name : x) === oldVal);
                if (idx !== -1) {
                    window.customMasters.gstnatures[idx] = { id: window.customMasters.gstnatures[idx].id || ('gst_' + Math.random().toString(36).substr(2, 9)), name: val, code };
                }
            } else {
                const exists = window.customMasters.gstnatures.some(x => (typeof x === 'object' ? x.name : x).toLowerCase() === val.toLowerCase());
                if (exists) {
                    showToast('This item already exists!', 'error');
                    return;
                }
                window.customMasters.gstnatures.push({ id: 'gst_' + Math.random().toString(36).substr(2, 9), name: val, code });
            }
        } else if (key === 'jobworktypes') {
            const rate = parseFloat(document.getElementById('custom-master-jobwork-rate')?.value || 0) || 0;
            if (oldVal) {
                const idx = window.customMasters.jobworktypes.findIndex(x => (typeof x === 'object' ? x.name : x) === oldVal);
                if (idx !== -1) {
                    window.customMasters.jobworktypes[idx] = { id: window.customMasters.jobworktypes[idx].id || ('jw_' + Math.random().toString(36).substr(2, 9)), name: val, rate };
                }
            } else {
                const exists = window.customMasters.jobworktypes.some(x => (typeof x === 'object' ? x.name : x).toLowerCase() === val.toLowerCase());
                if (exists) {
                    showToast('This item already exists!', 'error');
                    return;
                }
                window.customMasters.jobworktypes.push({ id: 'jw_' + Math.random().toString(36).substr(2, 9), name: val, rate });
            }
        } else if (key === 'salesaccounts' || key === 'purchaseaccounts') {
            if (!window.customMasters[key]) window.customMasters[key] = [];
            if (oldVal) {
                const idx = window.customMasters[key].findIndex(x => (typeof x === 'object' ? x.name : x) === oldVal);
                if (idx !== -1) {
                    window.customMasters[key][idx] = { id: (typeof window.customMasters[key][idx] === 'object' ? window.customMasters[key][idx].id : '') || ('acc_' + Math.random().toString(36).substr(2, 9)), name: val };
                }
            } else {
                const exists = window.customMasters[key].some(x => (typeof x === 'object' ? x.name : x).toLowerCase() === val.toLowerCase());
                if (exists) {
                    showToast('This item already exists!', 'error');
                    return;
                }
                window.customMasters[key].push({ id: 'acc_' + Math.random().toString(36).substr(2, 9), name: val });
            }
        }
        try {
            await window.saveCustomMasters();
            window.populateCustomDropdowns();
            switchMasterSubtab(currentMasterSubtab);
            closeModal('custom-master-item-modal', true);
            showToast(oldVal ? 'Item updated successfully' : 'Item added successfully', 'success');
        } catch(e) {
            console.error(`Failed to save ${key}:`, e);
            showToast("Save failed: " + e.message, 'error');
        }
        return;
    }

    let table = '';
    let payload = {};

    if (key === 'fabrictypes') {
        table = 'fabric_types';
        const hsn = document.getElementById('custom-master-hsn').value.trim();
        const category = document.getElementById('custom-master-category').value.trim() || 'Thread';
        const width = document.getElementById('custom-master-width').value.trim();
        payload = { name: val, hsn, category, width };
    } else if (key === 'doctypes') {
        table = 'doctypes';
        payload = { name: val };
    } else if (key === 'packingtypes') {
        table = 'packing_types';
        payload = { name: val };
    } else if (key === 'taxinames') {
        table = 'taxi_names';
        payload = { name: val };
    } else if (key === 'salestypes') {
        table = 'sales_types';
        const gstType = document.getElementById('custom-master-gst-type').value;
        payload = { name: val, gst_type: gstType };
    } else if (key === 'purchasetypes') {
        table = 'purchase_types';
        const gstType = document.getElementById('custom-master-gst-type').value;
        payload = { name: val, gst_type: gstType };
    }

    if (!table) return;

    try {
        if (oldVal) {
            let existingRec = null;
            if (key === 'fabrictypes') {
                existingRec = db.fabric_types.find(x => x.name.toLowerCase() === oldVal.toLowerCase());
            } else if (key === 'doctypes') {
                existingRec = db.doctypes.find(x => x.name.toLowerCase() === oldVal.toLowerCase());
            } else if (key === 'packingtypes') {
                existingRec = db.packing_types.find(x => x.name.toLowerCase() === oldVal.toLowerCase());
            } else if (key === 'taxinames') {
                existingRec = db.taxi_names.find(x => x.name.toLowerCase() === oldVal.toLowerCase());
            } else if (key === 'salestypes') {
                existingRec = db.sales_types.find(x => x.name.toLowerCase() === oldVal.toLowerCase());
            } else if (key === 'purchasetypes') {
                existingRec = db.purchase_types.find(x => x.name.toLowerCase() === oldVal.toLowerCase());
            }

            if (existingRec) {
                payload.id = existingRec.id;
                if ((key === 'salestypes' || key === 'purchasetypes') && (!payload.id || payload.id.startsWith('mst_') || !payload.id.includes('-'))) {
                    payload.id = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16); });
                }
                payload.company_id = companyId;
                const { data: ext } = await window.supabase.from(table).select('id').eq('id', payload.id).maybeSingle();
                let error;
                if (ext) {
                    const res = await window.supabase.from(table).update(cleanRecordForSupabase(table, payload)).eq('id', payload.id);
                    error = res.error;
                } else {
                    const res = await window.supabase.from(table).insert(cleanRecordForSupabase(table, payload));
                    error = res.error;
                }
                if (error) throw error;
                Object.assign(existingRec, payload);
                existingRec.id = payload.id;
            }
        } else {
            let exists = false;
            if (key === 'fabrictypes') {
                exists = db.fabric_types.some(x => x.name.toLowerCase() === val.toLowerCase());
            } else if (key === 'doctypes') {
                exists = db.doctypes.some(x => x.name.toLowerCase() === val.toLowerCase());
            } else if (key === 'packingtypes') {
                exists = db.packing_types.some(x => x.name.toLowerCase() === val.toLowerCase());
            } else if (key === 'taxinames') {
                exists = db.taxi_names.some(x => x.name.toLowerCase() === val.toLowerCase());
            } else if (key === 'salestypes') {
                exists = db.sales_types.some(x => x.name.toLowerCase() === val.toLowerCase());
            } else if (key === 'purchasetypes') {
                exists = db.purchase_types.some(x => x.name.toLowerCase() === val.toLowerCase());
            }

            if (exists) {
                showToast('This item already exists!', 'error');
                return;
            }

            if (key === 'salestypes' || key === 'purchasetypes') {
                payload.id = crypto.randomUUID();
            } else {
                payload.id = 'mst_' + Math.random().toString(36).substr(2, 9);
            }
            payload.company_id = companyId;

            const { error } = await window.supabase.from(table).insert(cleanRecordForSupabase(table, payload));
            if (error) throw error;

            if (key === 'fabrictypes') db.fabric_types.push(payload);
            else if (key === 'doctypes') db.doctypes.push(payload);
            else if (key === 'packingtypes') db.packing_types.push(payload);
            else if (key === 'taxinames') db.taxi_names.push(payload);
            else if (key === 'salestypes') db.sales_types.push(payload);
            else if (key === 'purchasetypes') db.purchase_types.push(payload);
        }

        window.customMasters.doctypes = db.doctypes.map(x => x.name);
        window.customMasters.fabrictypes = db.fabric_types.map(x => ({
            name: x.name,
            width: x.width || '',
            category: x.category || '',
            hsn: x.hsn || ''
        }));
        window.customMasters.packingtypes = db.packing_types.map(x => x.name);
        window.customMasters.taxinames = db.taxi_names.map(x => x.name);
        window.customMasters.salestypes = db.sales_types.map(x => ({
            id: x.id,
            name: x.name,
            gst_type: x.gst_type || 'CGST + SGST'
        }));
        window.customMasters.purchasetypes = db.purchase_types.map(x => ({
            id: x.id,
            name: x.name,
            gst_type: x.gst_type || 'CGST + SGST'
        }));

        window.populateCustomDropdowns();
        switchMasterSubtab(currentMasterSubtab);
        closeModal('custom-master-item-modal', true);
        showToast(oldVal ? 'Item updated successfully' : 'Item added successfully', 'success');
    } catch(e) {
        console.error("Failed to save custom master item:", e);
        showToast("Save failed: " + (e.message || e), 'error');
    }
};

