// ===== DYNAMIC TRANSACTION IMPORT/EXPORT INJECTION =====
window.importTransaction = function(type) {
    let input = document.getElementById('tx-import-input');
    if (!input) {
        input = document.createElement('input');
        input.type = 'file';
        input.id = 'tx-import-input';
        input.style.display = 'none';
        input.accept = '.xlsx,.xls,.csv';
        input.onchange = window.txImportFile;
        document.body.appendChild(input);
    }
    input.setAttribute('data-type', type);
    input.click();
};

window.txImportFile = function(event) {
    const type = event.target.getAttribute('data-type');
    const file = event.target.files[0];
    if (!file) return;
    event.target.value = '';

    const reader = new FileReader();
    const fileName = file.name.toLowerCase();

    reader.onload = async function(e) {
        showImportLoadingOverlay();
        try {
            let rows = [];
            if (fileName.endsWith('.csv')) {
                const text = e.target.result;
                rows = parseCSV(text);
            } else if (fileName.endsWith('.xlsx') || fileName.endsWith('.xls')) {
                if (typeof XLSX === 'undefined') {
                    showToast('Excel library not loaded.', 'error');
                    hideImportLoadingOverlay();
                    return;
                }
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, { type: 'array' });
                
                // Robust sheet selection: Find sheet containing the type name, or fallback to standard logic
                let sheetName = '';
                const lowerType = type.toLowerCase();
                for (let sn of workbook.SheetNames) {
                    const snl = sn.toLowerCase();
                    if (snl.includes('template') || snl.includes('sample') || snl.includes('instructions') || snl.includes('read first')) {
                        continue;
                    }
                    if (snl.includes(lowerType) || (lowerType === 'bom' && snl.includes('bom')) || (lowerType.includes('grn') && snl.includes('grn')) || (lowerType === 'po_inhouse' && snl.includes('inhouse'))) {
                        sheetName = sn;
                        break;
                    }
                }
                if (!sheetName) {
                    // Try to find any sheet that doesn't contain template/sample/read first keywords
                    for (let sn of workbook.SheetNames) {
                        const snl = sn.toLowerCase();
                        if (!snl.includes('template') && !snl.includes('sample') && !snl.includes('read first') && !snl.includes('instructions')) {
                            sheetName = sn;
                            break;
                        }
                    }
                }
                if (!sheetName) {
                    sheetName = workbook.SheetNames[0] === 'READ FIRST' && workbook.SheetNames[1] ? workbook.SheetNames[1] : workbook.SheetNames[0];
                }
                
                const worksheet = workbook.Sheets[sheetName];
                rows = XLSX.utils.sheet_to_json(worksheet, { header: 1, defval: "" });
                showToast(`Reading sheet: "${sheetName}" with ${rows.length} rows`, 'info');
            } else {
                showToast('Unsupported file format.', 'error');
                hideImportLoadingOverlay();
                return;
            }

            if (rows.length < 2) {
                showToast('No data rows found to import', 'error');
                hideImportLoadingOverlay();
                return;
            }

            let headerRowIndex = 0;
            const headers = rows[headerRowIndex].map(h => h ? h.toString().trim() : '');
            
            const records = [];
            for (let i = 1; i < rows.length; i++) {
                const row = rows[i];
                if (!row || row.every(c => c === null || c === undefined || c === "")) continue;
                const rec = {};
                headers.forEach((h, colIdx) => {
                    if (h) rec[h] = row[colIdx] !== undefined ? row[colIdx] : '';
                });
                records.push(rec);
            }

            await window.saveImportedTransactions(type, records);
        } catch (err) {
            console.error(err);
            showToast('Import failed: ' + err.message, 'error');
            hideImportLoadingOverlay();
        }
    };

    if (fileName.endsWith('.csv')) {
        reader.readAsText(file);
    } else {
        reader.readAsArrayBuffer(file);
    }
};

window.saveImportedTransactions = async function(type, records) {
    if (!currentCompany) {
        showToast('Please select a company first', 'error');
        return;
    }

    let successCount = 0;
    let duplicateCount = 0;
    let updatedCount = 0;
    let errorLogs = [];
    
    let newSoCount = 0;
    let newPoCount = 0;
    let newGrnCount = 0;
    let newOutwardCount = 0;
    let newProdCount = 0;
    let newGtxCount = 0;
    let newReqCount = 0;

    for (let rec of records) {
        const id = rec.id || 'imported_' + Math.random().toString(36).substring(2, 11);
        
        if (type === 'so') {
            const checkCust = (rec.customerName || rec.customer || '').toString().trim();
            const checkDesign = (rec.designNumber || '').toString().trim();
            const checkQty = parseFloat(rec.qty) || 0;

            if (!checkCust && !checkDesign && checkQty === 0) {
                const existing = rawDB.salesOrders.find(x => String(x.number || '').trim() === String(rec.number || '').trim());
                const data = {
                    id: existing ? existing.id : id,
                    number: rec.number || getDocumentNumber('SO', db.salesOrders.length + (++newSoCount)),
                    date: rec.date || today(),
                    status: 'Cancelled',
                    remarks: rec.remarks || 'Cancelled (Empty Row Imported)',
                    customerId: '', customerName: '', designId: '', designNumber: '', qty: 0, rate: 0, amount: 0, totalValue: 0, items: []
                };
                if (existing) {
                    await mergeAndSaveImportedRecord('sales_orders', existing, data);
                    updatedCount++;
                } else {
                    await saveToSupabase('sales_orders', data);
                    rawDB.salesOrders.push(data);
                    successCount++;
                }
                continue;
            }

            let cust = db.customers.find(c => String(c.name || '').trim().toLowerCase() === String(rec.customerName || '').trim().toLowerCase());
            if (!cust) {
                errorLogs.push(`Row ${records.indexOf(rec) + 2}: Customer "${rec.customerName || ''}" not found in Customer Master.`);
                duplicateCount++;
                continue;
            }
            let rawDesignNo = (rec.designNumber || '').toString().trim();
            let parsedDesignNo = rawDesignNo;
            let design = db.items.find(d => String(d.name || '').trim().toLowerCase() === parsedDesignNo.toLowerCase() || String(d.code || '').trim().toLowerCase() === parsedDesignNo.toLowerCase());
            if (!design) {
                errorLogs.push(`Row ${records.indexOf(rec) + 2}: Item "${parsedDesignNo || ''}" not found in Item Master.`);
                duplicateCount++;
                continue;
            }

            const existing = rawDB.salesOrders.find(x => String(x.number || '').trim() === String(rec.number || '').trim());
            if (existing) {
                existing.designId = design.id;
                existing.designNumber = design.name;
                existing.customerId = cust.id;
                existing.customerName = cust.name;
                const data = {
                    partyOrderNo: rec.partyOrderNo || '',
                    qty: parseFloat(rec.qty) || 0,
                    rate: parseFloat(rec.rate) || 0,
                    amount: parseFloat(rec.amount) || (parseFloat(rec.qty)*parseFloat(rec.rate)) || 0,
                    totalValue: parseFloat(rec.amount) || (parseFloat(rec.qty)*parseFloat(rec.rate)) || 0,
                    deliveryDate: rec.deliveryDate || '',
                    deliveryDays: parseInt(rec.deliveryDays) || 0,
                    status: rec.status || '',
                    remarks: rec.remarks || '',
                    items: [{ itemId: design.id, qty: parseFloat(rec.qty) || 0, price: parseFloat(rec.rate) || 0, amount: parseFloat(rec.amount) || (parseFloat(rec.qty)*parseFloat(rec.rate)) || 0 }]
                };
                await mergeAndSaveImportedRecord('sales_orders', existing, data);
                updatedCount++;
                continue;
            } else {
                const data = {
                    id,
                    number: rec.number || getDocumentNumber('SO', db.salesOrders.length + (++newSoCount)),
                    date: rec.date || today(),
                    customerId: cust.id,
                    customerName: cust.name,
                    designId: design.id,
                    designNumber: design.name,
                    partyOrderNo: rec.partyOrderNo || '',
                    qty: parseFloat(rec.qty) || 0,
                    rate: parseFloat(rec.rate) || 0,
                    amount: parseFloat(rec.amount) || (parseFloat(rec.qty)*parseFloat(rec.rate)) || 0,
                    totalValue: parseFloat(rec.amount) || (parseFloat(rec.qty)*parseFloat(rec.rate)) || 0,
                    deliveryDate: rec.deliveryDate || today(),
                    deliveryDays: parseInt(rec.deliveryDays) || 15,
                    status: rec.status || 'Pending',
                    remarks: rec.remarks || 'CSV Imported',
                    items: [{ itemId: design.id, qty: parseFloat(rec.qty) || 0, price: parseFloat(rec.rate) || 0, amount: parseFloat(rec.amount) || (parseFloat(rec.qty)*parseFloat(rec.rate)) || 0 }]
                };
                await saveToSupabase('sales_orders', data);
                rawDB.salesOrders.push(data);
                successCount++;
            }
        }
        else if (type === 'po' || type === 'po_inhouse') {
            const rawVendorName = (rec.vendorName || rec.vendor || '').toString().trim();
            const designName = (rec.design || '').toString().trim();
            const checkQty = parseFloat(rec.qty) || 0;

            if (!rawVendorName && !designName && checkQty === 0) {
                const existing = rawDB.pos.find(x => String(x.number || '').trim() === String(rec.number || '').trim());
                const isInhouse = (type === 'po_inhouse' || rec.poType === 'inhouse');
                const data = {
                    id: existing ? existing.id : id,
                    number: rec.number || getDocumentNumber(isInhouse ? 'PO/INH' : 'PO/VEN', db.pos.length + (++newPoCount)),
                    date: rec.date || today(),
                    status: 'Cancelled',
                    remarks: rec.remarks || 'Cancelled (Empty Row Imported)',
                    poType: isInhouse ? 'inhouse' : 'vendor',
                    vendorId: '', vendorName: '', customerId: '', customerName: '', linkedSoId: '', linkedSoNumber: '', design: '', qty: 0, rate: 0, amount: 0, items: []
                };
                if (existing) {
                    await mergeAndSaveImportedRecord('purchase_orders', existing, data);
                    updatedCount++;
                } else {
                    await saveToSupabase('purchase_orders', data);
                    rawDB.pos.push(data);
                    successCount++;
                }
                continue;
            }

            const isInhouse = (type === 'po_inhouse' || rec.poType === 'inhouse');
            let vendor = null;
            if (isInhouse) {
                vendor = { id: '', name: '' };
            } else {
                vendor = db.vendors.find(v => String(v.name || '').trim().toLowerCase() === rawVendorName.toLowerCase());
                if (!vendor) {
                    errorLogs.push(`Row ${records.indexOf(rec) + 2}: Vendor "${rawVendorName}" not found in Vendor Master.`);
                    duplicateCount++;
                    continue;
                }
            }

            let design = db.items.find(d => 
                String(d.name || '').trim().toLowerCase() === designName.toLowerCase() || 
                String(d.code || '').trim().toLowerCase() === designName.toLowerCase()
            );
            
            // Fuzzy/partial match fallback for complete item name mapping
            if (!design && designName) {
                design = db.items.find(d => {
                    const dbName = String(d.name || '').trim().toLowerCase();
                    const dbCode = String(d.code || '').trim().toLowerCase();
                    const csvName = designName.toLowerCase();
                    return dbName.startsWith(csvName) || csvName.startsWith(dbName) ||
                           dbCode.startsWith(csvName) || csvName.startsWith(dbCode);
                });
            }

            if (!design) {
                errorLogs.push(`Row ${records.indexOf(rec) + 2}: Item/Design "${designName || ''}" not found in Item Master.`);
                duplicateCount++;
                continue;
            }

            let customerId = '';
            let customerName = '';
            const rawCustName = (rec.customerName || rec.customer || '').toString().trim();
            if (rawCustName) {
                let cust = db.customers.find(c => String(c.name || '').trim().toLowerCase() === rawCustName.toLowerCase());
                if (cust) {
                    customerId = cust.id;
                    customerName = cust.name;
                } else {
                    errorLogs.push(`Row ${records.indexOf(rec) + 2}: Customer "${rawCustName}" not found in Customer Master.`);
                    duplicateCount++;
                    continue;
                }
            }

            let linkedSoId = '';
            let linkedSoNumber = '';
            const rawSoNo = (rec.linkedSoNumber || rec.soNumber || '').toString().trim();
            if (rawSoNo) {
                let so = db.salesOrders.find(s => String(s.number || '').trim().toLowerCase() === rawSoNo.toLowerCase());
                if (so) {
                    linkedSoId = so.id;
                    linkedSoNumber = so.number;
                } else {
                    errorLogs.push(`Row ${records.indexOf(rec) + 2}: Sales Order "${rawSoNo}" not found in Sales Orders.`);
                    duplicateCount++;
                    continue;
                }
            }

            let bomId = '';
            let bomCode = '';
            const rawBom = (rec.bomNumber || '').toString().trim();
            if (rawBom) {
                const bomObj = (db.boms || []).find(b => String(b.code || '').trim().toLowerCase() === rawBom.toLowerCase() || String(b.id || '').trim().toLowerCase() === rawBom.toLowerCase());
                if (bomObj) {
                    bomId = bomObj.id;
                    bomCode = bomObj.code;
                } else {
                    errorLogs.push(`Row ${records.indexOf(rec) + 2}: BOM "${rawBom}" not found in BOM Master.`);
                    duplicateCount++;
                    continue;
                }
            }

            const existing = rawDB.pos.find(x => String(x.number || '').trim() === String(rec.number || '').trim());
            // isInhouse is already defined above
            const dataRate = isInhouse ? 0 : (parseFloat(rec.rate) || 0);
            const dataAmount = isInhouse ? 0 : (parseFloat(rec.amount) || (parseFloat(rec.qty) * dataRate) || 0);
            const dataDays = isInhouse ? 0 : (parseInt(rec.deliveryDays) || 0);
            const dataReturnDate = isInhouse ? '' : (rec.returnDate || '');

            if (existing) {
                existing.vendorId = vendor.id;
                existing.vendorName = vendor.name;
                const data = {
                    customerId,
                    customerName,
                    linkedSoId,
                    linkedSoNumber,
                    design: design.name,
                    qty: parseFloat(rec.qty) || 0,
                    rate: dataRate,
                    amount: dataAmount,
                    returnDate: dataReturnDate,
                    deliveryDays: dataDays,
                    status: rec.status || '',
                    remarks: rec.remarks || '',
                    vendorJobWorkChallanNo: rec.vendorJobWorkChallanNo || '',
                    poType: isInhouse ? 'inhouse' : (existing.poType || 'vendor'),
                    items: [{ itemId: design.id, bomId: bomId, bomCode: bomCode, processName: design.name, qty: parseFloat(rec.qty) || 0, rate: dataRate, amount: dataAmount }]
                };
                await mergeAndSaveImportedRecord('purchase_orders', existing, data);
                updatedCount++;
                continue;
            } else {
                const data = {
                    id,
                    number: rec.number || getDocumentNumber(isInhouse ? 'PO/INH' : 'PO/VEN', db.pos.length + (++newPoCount)),
                    date: rec.date || today(),
                    vendorId: vendor.id,
                    vendorName: vendor.name,
                    customerId,
                    customerName,
                    linkedSoId,
                    linkedSoNumber,
                    design: design.name,
                    qty: parseFloat(rec.qty) || 0,
                    rate: dataRate,
                    amount: dataAmount,
                    returnDate: isInhouse ? '' : (dataReturnDate || today()),
                    deliveryDays: isInhouse ? 0 : (dataDays || 15),
                    status: rec.status || 'Pending',
                    remarks: rec.remarks || 'CSV Imported',
                    vendorJobWorkChallanNo: rec.vendorJobWorkChallanNo || '',
                    poType: isInhouse ? 'inhouse' : 'vendor',
                    items: [{ itemId: design.id, bomId: bomId, bomCode: bomCode, processName: design.name, qty: parseFloat(rec.qty) || 0, rate: dataRate, amount: dataAmount }]
                };
                await saveToSupabase('purchase_orders', data);
                rawDB.pos.push(data);
                successCount++;
            }
        }
        else if (type === 'grn') {
            const checkParty = (rec.customerName || rec.vendorName || '').toString().trim();
            const checkFabric = (rec.fabricType || rec.designNumber || '').toString().trim();
            const checkQty = parseFloat(rec.qty) || 0;

            if (!checkParty && !checkFabric && checkQty === 0) {
                const existing = rawDB.grns.find(x => (x.grnNo || x.number) === rec.number);
                const data = {
                    id: existing ? existing.id : id,
                    grnNo: rec.number || getDocumentNumber('GRN', db.grns.length + (++newGrnCount)),
                    number: rec.number || getDocumentNumber('GRN', db.grns.length + (newGrnCount)),
                    date: rec.date || today(),
                    status: 'Cancelled',
                    remarks: rec.remarks || 'Cancelled (Empty Row Imported)',
                    customer: '', customerId: '', customerName: '', vendorId: '', vendorName: '', qty: 0, weight: 0, pkgCount: 0, packageSlips: []
                };
                if (existing) {
                    await mergeAndSaveImportedRecord('grns', existing, data);
                    updatedCount++;
                } else {
                    await saveToSupabase('grns', data);
                    rawDB.grns.push(data);
                    successCount++;
                }
                continue;
            }

            const wState = parseGrnWizardState({ remarks: rec.remarks });
            const isCustomerSource = (wState.type === 'fabric' && wState.source === 'customer');
            
            let partyId = '';
            let partyName = rec.customerName || rec.vendorName || '';
            
            if (isCustomerSource) {
                let cust = db.customers.find(c => String(c.name || '').trim().toLowerCase() === String(partyName || '').trim().toLowerCase());
                if (!cust) {
                    errorLogs.push(`Row ${records.indexOf(rec) + 2}: Customer "${partyName || ''}" not found in Customer Master.`);
                    duplicateCount++;
                    continue;
                }
                partyId = cust.id;
                partyName = cust.name;
            } else {
                let vendor = db.vendors.find(v => String(v.name || '').trim().toLowerCase() === String(partyName || '').trim().toLowerCase());
                if (!vendor) {
                    errorLogs.push(`Row ${records.indexOf(rec) + 2}: Vendor "${partyName || ''}" not found in Vendor Master.`);
                    duplicateCount++;
                    continue;
                }
                partyId = vendor.id;
                partyName = vendor.name;
            }

            let soRefId = '';
            let soLinks = [];
            let cleanSoNumber = '';
            const searchNo = String(rec.salesOrderNo || rec.soNumber || '').trim().toLowerCase();
            
            if (searchNo) {
                if (!isCustomerSource) {
                    // Link with Vendor Purchase Order only
                    let po = db.pos.find(p => String(p.number || '').trim().toLowerCase() === searchNo && p.poType !== 'inhouse');
                    if (po) {
                        soRefId = po.id;
                        soLinks = [po.id];
                        cleanSoNumber = po.number;
                        
                        // Fetch item from PO
                        const poItemName = po.design || (po.items && po.items[0] ? po.items[0].processName : '');
                        if (poItemName) {
                            rec.fabricType = poItemName;
                            rec.designNumber = poItemName;
                        }
                    }
                } else {
                    // Link with Sales Order
                    let so = db.salesOrders.find(s => String(s.number || '').trim().toLowerCase() === searchNo);
                    if (so) {
                        if (so.customerId === partyId) {
                            soRefId = so.id;
                            soLinks = [so.id];
                            cleanSoNumber = so.number;
                            
                            // Fetch item from SO
                            const soItemName = so.designNumber || (so.items && so.items[0] ? so.items[0].processName : '');
                            if (soItemName) {
                                rec.fabricType = soItemName;
                                rec.designNumber = soItemName;
                            }
                        }
                    }
                }
            }

            const existing = rawDB.grns.find(x => (x.grnNo || x.number) === rec.number);
            if (existing) {
                const finalFabricType = rec.fabricType || rec.designNumber || existing.fabricType || 'Crepe';
                const finalPackingType = rec.packingType || existing.packingType || 'ROLL';
                const finalPkgCount = parseInt(rec.pkgCount) || existing.pkgCount || 1;
                const finalQty = parseFloat(rec.qty) || existing.qty || 0;
                const finalWeight = parseFloat(rec.weight) || existing.weight || 0;
                
                const fallbackSlips = [{
                    fabricType: finalFabricType,
                    color: rec.color || existing.color || '',
                    length: parseFloat(rec.length) || existing.length || 0,
                    width: parseFloat(rec.width) || existing.width || 0,
                    packingType: finalPackingType,
                    pkgCount: finalPkgCount,
                    weight: finalWeight,
                    qty: finalQty,
                    packages: Array.from({ length: finalPkgCount }, (_, i) => ({
                        label: `${finalPackingType} ${i + 1}`,
                        packageNo: `${i + 1}`,
                        qty: i === 0 ? finalQty : 0
                    }))
                }];

                let finalCustOrderNo = rec.custOrderNo || existing.custOrderNo || '';
                if (soRefId) {
                    if (!isCustomerSource) {
                        const linkedPo = db.pos.find(p => p.id === soRefId);
                        if (linkedPo && linkedPo.vendorJobWorkChallanNo) {
                            finalCustOrderNo = linkedPo.vendorJobWorkChallanNo;
                        }
                    } else {
                        const linkedSo = db.salesOrders.find(s => s.id === soRefId);
                        if (linkedSo && linkedSo.partyOrderNo) {
                            finalCustOrderNo = linkedSo.partyOrderNo;
                        }
                    }
                }

                const data = {
                    soNumber: cleanSoNumber,
                    soRefId: soRefId,
                    soLinks: soLinks,
                    designNumber: rec.designNumber || '',
                    qty: finalQty,
                    weight: finalWeight,
                    pkgCount: finalPkgCount,
                    vehicleNo: rec.vehicleNo || '',
                    status: rec.status || '',
                    remarks: rec.remarks || '',
                    custOrderNo: finalCustOrderNo,
                    partyDocType: rec.partyDocType || '',
                    partyDocNo: rec.partyDocNo || '',
                    docDate: rec.docDate || null,
                    packingType: finalPackingType,
                    fabricType: finalFabricType,
                    color: rec.color || existing.color || '',
                    length: parseFloat(rec.length) || existing.length || 0,
                    width: parseFloat(rec.width) || existing.width || 0,
                    packageSlips: rec.packageSlips || existing.packageSlips || fallbackSlips
                };
                if (partyId) {
                    data.customer = partyId;
                    data.customerId = partyId;
                    data.customerName = partyName;
                }
                await mergeAndSaveImportedRecord('grns', existing, data);
                updatedCount++;
                continue;
            }

            const finalFabricType = rec.fabricType || rec.designNumber || 'Crepe';
            const finalPackingType = rec.packingType || 'ROLL';
            const finalPkgCount = parseInt(rec.pkgCount) || 1;
            const finalQty = parseFloat(rec.qty) || 0;
            const finalWeight = parseFloat(rec.weight) || 0;
            
            const fallbackSlips = [{
                fabricType: finalFabricType,
                color: rec.color || '',
                length: parseFloat(rec.length) || 0,
                width: parseFloat(rec.width) || 0,
                packingType: finalPackingType,
                pkgCount: finalPkgCount,
                weight: finalWeight,
                qty: finalQty,
                packages: Array.from({ length: finalPkgCount }, (_, i) => ({
                    label: `${finalPackingType} ${i + 1}`,
                    packageNo: `${i + 1}`,
                    qty: i === 0 ? finalQty : 0
                }))
            }];

            const data = {
                id,
                grnNo: rec.number || getDocumentNumber('GRN', db.grns.length + (++newGrnCount)),
                number: rec.number || getDocumentNumber('GRN', db.grns.length + (newGrnCount)),
                date: rec.date || today(),
                customer: partyId,
                customerId: partyId,
                customerName: partyName,
                soNumber: cleanSoNumber,
                soRefId: soRefId,
                soLinks: soLinks,
                designNumber: rec.designNumber || '',
                qty: finalQty,
                weight: finalWeight,
                pkgCount: finalPkgCount,
                transporterName: rec.transporterName || '',
                lr: rec.lr || '',
                status: rec.status || 'Pending',
                remarks: rec.remarks || 'CSV Imported',
                custOrderNo: (function() {
                    let no = rec.custOrderNo || '';
                    if (soRefId) {
                        const linkedSo = db.salesOrders.find(s => s.id === soRefId);
                        if (linkedSo && linkedSo.partyOrderNo) {
                            no = linkedSo.partyOrderNo;
                        }
                    }
                    return no;
                })(),
                partyDocType: rec.partyDocType || '',
                partyDocNo: rec.partyDocNo || '',
                docDate: rec.docDate || null,
                packingType: finalPackingType,
                fabricType: finalFabricType,
                color: rec.color || '',
                length: parseFloat(rec.length) || 0,
                width: parseFloat(rec.width) || 0,
                packageSlips: rec.packageSlips || fallbackSlips
            };
            await saveToSupabase('grns', data);
            rawDB.grns.push(data);
            successCount++;
        }
        else if (type === 'outward') {
            const checkVendor = (rec.vendorName || '').toString().trim();
            const checkCustomer = (rec.customerName || '').toString().trim();
            const checkQty = parseFloat(rec.qty) || 0;

            if (!checkVendor && !checkCustomer && checkQty === 0) {
                const existing = rawDB.outwards.find(x => x.number === rec.number);
                const data = {
                    id: existing ? existing.id : id,
                    number: rec.number || getDocumentNumber('JW', db.outwards.length + (++newOutwardCount)),
                    date: rec.date || today(),
                    status: 'Cancelled',
                    remarks: rec.remarks || 'Cancelled (Empty Row Imported)',
                    vendorId: '', vendorName: '', customerId: '', customerName: '', qty: 0, grnLinks: [], dispatchedPackages: []
                };
                if (existing) {
                    await mergeAndSaveImportedRecord('outwards', existing, data);
                    updatedCount++;
                } else {
                    await saveToSupabase('outwards', data);
                    rawDB.outwards.push(data);
                    successCount++;
                }
                continue;
            }

            let vendor = db.vendors.find(v => String(v.name || '').trim().toLowerCase() === String(rec.vendorName || '').trim().toLowerCase());
            if (!vendor && String(rec.vendorName || '').trim().toLowerCase() === 'in house') {
                vendor = { id: 'inhouse', name: 'In House' };
            }
            let customer = null;
            if (!vendor) {
                const custMatch = db.customers.find(c => String(c.name || '').trim().toLowerCase() === String(rec.vendorName || '').trim().toLowerCase());
                if (custMatch) {
                    vendor = { id: 'customer', name: custMatch.name };
                    customer = custMatch;
                }
            }
            if (!vendor) {
                errorLogs.push(`Row ${records.indexOf(rec) + 2}: Party "${rec.vendorName || ''}" not found in Vendor or Customer Masters.`);
                duplicateCount++;
                continue;
            }

            if (!customer && rec.customerName && rec.customerName.trim() !== '') {
                customer = db.customers.find(c => String(c.name || '').trim().toLowerCase() === String(rec.customerName).trim().toLowerCase());
                if (!customer) {
                    errorLogs.push(`Row ${records.indexOf(rec) + 2}: Customer "${rec.customerName}" not found in Customer Master.`);
                    duplicateCount++;
                    continue;
                }
            }

            let grnRefId = '';
            let grnNo = rec.grnNo || '';
            let grnLinks = [];
            if (rec.grnNo) {
                const grn = db.grns.find(g => String(g.grnNo || '').trim().toLowerCase() === String(rec.grnNo).trim().toLowerCase());
                if (grn) {
                    grnRefId = grn.id;
                    grnNo = grn.grnNo;
                    grnLinks = [{ grnRefId: grn.id, qty: parseFloat(rec.qty) || 0 }];
                }
            }

            let poRefId = '';
            if (rec.poNumber) {
                const po = db.pos.find(p => String(p.number || '').trim().toLowerCase() === String(rec.poNumber).trim().toLowerCase());
                if (po) {
                    poRefId = po.id;
                }
            }

            const existing = rawDB.outwards.find(x => x.number === rec.number);
            if (existing) {
                const data = {
                    vendorId: vendor.id === 'inhouse' ? '' : vendor.id,
                    vendorName: vendor.name,
                    customerId: customer ? customer.id : '',
                    customerName: customer ? customer.name : '',
                    poRefId,
                    grnRefId,
                    grnNo,
                    grnLinks,
                    qty: parseFloat(rec.qty) || 0,
                    remarks: rec.remarks || existing.remarks || 'CSV Imported'
                };
                await mergeAndSaveImportedRecord('outwards', existing, data);
                if (poRefId) {
                    const linkedPO = db.pos.find(p => p.id === poRefId);
                    if (linkedPO && ((linkedPO.poType || 'vendor') === 'vendor' || linkedPO.poType === 'inhouse')) {
                        const poNumber = linkedPO.number;
                        const matchingPOs = db.pos.filter(p => p.number === poNumber);
                        const allOutwards = (db.outwards || []).filter(o => {
                            if (o.id === existing.id) return false;
                            if (!o.poRefId) return false;
                            const lpo = db.pos.find(p => p.id === o.poRefId);
                            return lpo && lpo.number === poNumber;
                        });
                        const challanNumbers = allOutwards.map(o => o.number);
                        challanNumbers.push(existing.number || data.number);
                        const uniqueChallans = [...new Set(challanNumbers)].filter(Boolean).join(', ');
                        for (const mpo of matchingPOs) {
                            mpo.vendorJobWorkChallanNo = uniqueChallans;
                            await saveToSupabase('purchase_orders', mpo);
                        }
                    }
                }
                updatedCount++;
                continue;
            }

            const data = {
                id,
                number: rec.number || getDocumentNumber('JW', db.outwards.length + (++newOutwardCount)),
                date: rec.date || today(),
                vendorId: vendor.id === 'inhouse' ? '' : vendor.id,
                vendorName: vendor.name,
                customerId: customer ? customer.id : '',
                customerName: customer ? customer.name : '',
                poRefId,
                grnRefId,
                grnNo,
                grnLinks,
                qty: parseFloat(rec.qty) || 0,
                remarks: rec.remarks || 'CSV Imported'
            };
            await saveToSupabase('outwards', data);
            if (poRefId) {
                const linkedPO = db.pos.find(p => p.id === poRefId);
                if (linkedPO && ((linkedPO.poType || 'vendor') === 'vendor' || linkedPO.poType === 'inhouse')) {
                    const poNumber = linkedPO.number;
                    const matchingPOs = db.pos.filter(p => p.number === poNumber);
                    const allOutwards = (db.outwards || []).filter(o => {
                        if (o.id === data.id) return false;
                        if (!o.poRefId) return false;
                        const lpo = db.pos.find(p => p.id === o.poRefId);
                        return lpo && lpo.number === poNumber;
                    });
                    const challanNumbers = allOutwards.map(o => o.number);
                    challanNumbers.push(data.number);
                    const uniqueChallans = [...new Set(challanNumbers)].filter(Boolean).join(', ');
                    for (const mpo of matchingPOs) {
                        mpo.vendorJobWorkChallanNo = uniqueChallans;
                        await saveToSupabase('purchase_orders', mpo);
                    }
                }
            }
            rawDB.outwards.push(data);
            successCount++;
        }
        else if (type === 'production') {
            let machineId = '';
            let machineNo = '';
            if (rec.machineNo) {
                const cleanMach = String(rec.machineNo).trim().toLowerCase();
                const machineObj = db.machines.find(m => String(m.machineNo).trim().toLowerCase() === cleanMach || String(m.name).trim().toLowerCase() === cleanMach || String(m.id).trim().toLowerCase() === cleanMach);
                if (machineObj) {
                    machineId = machineObj.id;
                    machineNo = machineObj.machineNo || machineObj.name;
                } else {
                    errorLogs.push(`Row ${records.indexOf(rec) + 2}: Machine "${rec.machineNo}" not found.`);
                    duplicateCount++;
                    continue;
                }
            } else {
                errorLogs.push(`Row ${records.indexOf(rec) + 2}: Machine No is required.`);
                duplicateCount++;
                continue;
            }

            let poId = '';
            let poNumber = '';
            let finishedItemId = '';
            let finishedItemName = '';
            if (rec.poNumber) {
                const cleanPo = String(rec.poNumber).trim().toLowerCase();
                const poObj = db.pos.find(p => String(p.number).trim().toLowerCase() === cleanPo);
                if (poObj) {
                    poId = poObj.id;
                    poNumber = poObj.number;
                    finishedItemId = poObj.items?.[0]?.itemId || '';
                    finishedItemName = poObj.items?.[0]?.processName || poObj.design || '';
                } else {
                    errorLogs.push(`Row ${records.indexOf(rec) + 2}: In-House PO "${rec.poNumber}" not found.`);
                    duplicateCount++;
                    continue;
                }
            } else {
                errorLogs.push(`Row ${records.indexOf(rec) + 2}: In-House PO Number is required.`);
                duplicateCount++;
                continue;
            }

            const existing = rawDB.productionSlips.find(x => x.number === rec.number);
            if (existing) {
                const data = {
                    poId,
                    poNumber,
                    machineId,
                    machineNo,
                    finishedItemId,
                    finishedItemName,
                    qty: parseFloat(rec.qty) || 0,
                    remarks: rec.remarks || ''
                };
                await mergeAndSaveImportedRecord('production_slips', existing, data);
                updatedCount++;
                continue;
            }

            const data = {
                id,
                number: rec.number || getDocumentNumber('PRD', window.getNextProductionSlipNumber('PRD') + (++newProdCount) - 1),
                date: rec.date || today(),
                poId,
                poNumber,
                machineId,
                machineNo,
                than: 1,
                conversion: 1,
                embroideryMtr: 1,
                finishedItemId,
                finishedItemName,
                qty: parseFloat(rec.qty) || 0,
                remarks: rec.remarks || 'CSV Imported'
            };
            await saveToSupabase('production_slips', data);
            rawDB.productionSlips.push(data);
            successCount++;
        }
        else if (['invoice', 'voucher', 'salesreturn', 'purchasereturn'].includes(type)) {
            const existing = rawDB.genericTransactions.find(x => x.number === rec.number && x.type === type);
            
            if (existing) {
                const data = {
                    partyName: rec.partyName || existing.partyName || '',
                    totalValue: parseFloat(rec.totalValue) || 0,
                    remarks: rec.remarks || ''
                };
                await mergeAndSaveImportedRecord('generic_transactions', existing, data);
                updatedCount++;
                continue;
            } else {
                const partyLower = (rec.partyName || '').trim().toLowerCase();
                const partyExists = db.customers.some(c => c.name.trim().toLowerCase() === partyLower) ||
                                    db.vendors.some(v => v.name.trim().toLowerCase() === partyLower);
                if (!partyExists) {
                    errorLogs.push(`Row ${records.indexOf(rec) + 2}: Party "${rec.partyName || ''}" not found in Customer or Vendor Master.`);
                    duplicateCount++;
                    continue;
                }

                const data = {
                    id,
                    number: rec.number || (type === 'invoice' && typeof window.getSalesInvoiceNumber === 'function' ? window.getSalesInvoiceNumber() : getDocumentNumber(type === 'voucher' ? 'VOUCH' : type === 'salesreturn' ? 'SR' : 'PR', getGenericTxList(type).length + (++newGtxCount))),
                    date: rec.date || today(),
                    partyName: rec.partyName || '',
                    totalValue: parseFloat(rec.totalValue) || 0,
                    remarks: rec.remarks || 'CSV Imported',
                    type
                };
                await saveToSupabase('generic_transactions', data);
                rawDB.genericTransactions.push(data);
                successCount++;
            }
        }
        else if (type === 'requisition') {
            const existing = rawDB.requisitionSlips.find(x => x.number === rec.number);
            if (existing) {
                const data = {
                    dept: rec.dept || '',
                    requiredDate: rec.requiredDate || '',
                    status: rec.status || '',
                    remarks: rec.remarks || ''
                };
                await mergeAndSaveImportedRecord('requisition_slips', existing, data);
                updatedCount++;
                continue;
            } else {
                const data = {
                    id,
                    number: rec.number || getDocumentNumber('REQ', db.requisitionSlips.length + (++newReqCount)),
                    date: rec.date || today(),
                    dept: rec.dept || '',
                    requiredDate: rec.requiredDate || '',
                    status: rec.status || 'Pending',
                    remarks: rec.remarks || 'CSV Imported',
                    items: []
                };
                await saveToSupabase('requisition_slips', data);
                rawDB.requisitionSlips.push(data);
                successCount++;
            }
        }
    }

    applyFinancialYearFilters();
    showImportSummaryPopup(type, successCount, duplicateCount, errorLogs, updatedCount);
};

window.exportTransaction = function(type) {
    console.log("window.exportTransaction called with type:", type);
    let targetType = type;
    if (!ExportConfig[targetType]) {
        const baseType = type.split('_')[0];
        if (ExportConfig[baseType]) {
            targetType = baseType;
        }
    }
    if (ExportConfig[targetType]) {
        console.log("Found ExportConfig for type:", targetType);
        window.openExportSelectorModal(targetType);
    } else {
        console.warn("ExportConfig not found for type:", type);
        showToast('Export not available for this transaction type', 'info');
    }
};

