// ===== PENDING INCOMPLETE TRANSACTIONS SYSTEM =====
function getTransactionIncompleteFields(tx, type) {
    const txStatus = (tx.status || '').toString().trim().toLowerCase();
    if (txStatus === 'cancelled' || txStatus === 'closed') {
        return [];
    }
    const missing = [];
    if (type === 'so') {
        if (!tx.partyOrderNo || !String(tx.partyOrderNo).trim()) missing.push('Customer PO No.');
        if (!tx.deliveryDays || tx.deliveryDays <= 0) missing.push('Expected Days');
        if (!tx.deliveryDate) missing.push('Delivery Date');
        
        let salesType = '';
        let remarksVal = tx.remarks || '';
        const match = remarksVal.match(/^\[Sales Type:\s*(.*?)\]\s*/);
        if (match) {
            salesType = match[1];
        }
        if (!salesType) {
            missing.push('Sales Type');
        }
        
        const hasMissingRate = (tx.items || []).some(it => !it.price || parseFloat(it.price) <= 0);
        if (hasMissingRate || !tx.items || tx.items.length === 0) {
            missing.push('Item Rate');
        }

        if (tx.materialType !== 'with_material') {
            const hasGrnLink = (tx.grnLinks && tx.grnLinks.length > 0) || 
                               (db.grns || []).some(g => 
                                   g.soRefId === tx.id || 
                                   g.soRef === tx.id || 
                                   (g.soLinks && g.soLinks.includes(tx.id)) ||
                                   (g.soNumber && String(g.soNumber).trim().toLowerCase() === String(tx.number || '').trim().toLowerCase())
                               );
            if (!hasGrnLink) {
                missing.push('GRN Link');
            }
        }
    } else if (type === 'po') {
        const isPOInhouse = tx.poType === 'inhouse' || tx.po_type === 'inhouse' || (tx.number && String(tx.number).toUpperCase().startsWith('PO/INH'));
        const isPOConsumableOrOther = tx.subType === 'consumable' || tx.subType === 'other' || tx.poType === 'consumable' || tx.poType === 'other' || 
            (tx.number && (String(tx.number).toUpperCase().startsWith('PO/CON') || String(tx.number).toUpperCase().startsWith('PO/OTH')));
        
        let purchaseType = '';
        let remarksVal = tx.remarks || '';
        const match = remarksVal.match(/^\[Purchase Type:\s*(.*?)\]\s*/);
        if (match) {
            purchaseType = match[1];
        }
        if (!isPOInhouse && !purchaseType) {
            missing.push('Purchase Type');
        }

        if (!isPOInhouse) {
            const hasMissingRate = (tx.items || []).some(it => !it.rate || parseFloat(it.rate) <= 0);
            if (hasMissingRate || !tx.items || tx.items.length === 0) {
                missing.push('Item Rate');
            }
        }

        if (!isPOInhouse) {
            if (!tx.vendorId) {
                missing.push('Vendor');
            }
            if (!isPOConsumableOrOther) {
                if (!tx.customerId) {
                    missing.push('Customer');
                }
                const hasSOLink = tx.linkedSoId || tx.linkedSoNumber || tx.linked_so_id || tx.linked_so_number || tx.soRef || tx.soRefId || tx.soNumber || (tx.soLinks && tx.soLinks.length > 0);
                if (!hasSOLink) {
                    missing.push('SO Link');
                }
                if (!tx.deliveryDays || tx.deliveryDays <= 0) {
                    missing.push('Expected Days');
                }
                let currentReturnDate = tx.returnDate || tx.deliveryDate || '';
                if (!currentReturnDate && tx.date && tx.deliveryDays && tx.deliveryDays > 0) {
                    try {
                        const poDate = new Date(tx.date);
                        if (!isNaN(poDate.getTime())) {
                            poDate.setDate(poDate.getDate() + parseInt(tx.deliveryDays));
                            currentReturnDate = poDate.toISOString().split('T')[0];
                            tx.returnDate = currentReturnDate;
                        }
                    } catch (e) {
                        console.error(e);
                    }
                }
                if (!currentReturnDate) {
                    missing.push('Expected Return Date');
                }
            }
        }
    } else if (type === 'grn') {
        let currentCustOrderNo = (tx.custOrderNo || '').trim();
        if (!currentCustOrderNo) {
            db.salesOrders = db.salesOrders || [];
            const linkedSoId = tx.soRefId || tx.soRef || tx.linked_so_id || tx.linkedSoId;
            let linkedSo = null;
            if (linkedSoId) {
                linkedSo = db.salesOrders.find(s => s.id === linkedSoId);
            }
            if (!linkedSo && tx.soNumber) {
                const searchNo = String(tx.soNumber).trim().toLowerCase();
                linkedSo = db.salesOrders.find(s => String(s.number || '').trim().toLowerCase() === searchNo);
            }
            if (linkedSo && linkedSo.partyOrderNo) {
                currentCustOrderNo = (linkedSo.partyOrderNo || '').trim();
                if (currentCustOrderNo) {
                    tx.custOrderNo = currentCustOrderNo;
                    if (!tx.soRefId) tx.soRefId = linkedSo.id;
                    if (!tx.soLinks || !tx.soLinks.includes(linkedSo.id)) {
                        tx.soLinks = [...new Set([...(tx.soLinks || []), linkedSo.id])];
                    }
                    if (!tx.soNumber) tx.soNumber = linkedSo.number;
                }
            }
        }

        const grnWizard = parseGrnWizardState(tx);
        const isGrnEmbroidery = (grnWizard.type === 'fabric' && grnWizard.subType === 'embroidered');
        const isConsumableOrOther = (grnWizard.type === 'consumable' || grnWizard.type === 'other');
        if (!isGrnEmbroidery && !isConsumableOrOther && !currentCustOrderNo) missing.push('Cust. Order No.');
        if (!tx.partyDocNo || !String(tx.partyDocNo).trim()) missing.push('Party Doc No.');
        if (!tx.docDate) missing.push('Doc Date');
        
        const tState = parseGrnTransportState(tx);
        const cleanDate = getComparableDate(tx.date || tx.docDate) || '';
        const coName = (window.currentCompany ? window.currentCompany.name : '') || '';
        const isGirisons = !coName || coName.toLowerCase().includes('girisons');
        const isAfterCutoff = cleanDate >= '2026-07-01';

        const partyId = tx.vendorId || tx.customerId;
        const staticName = tx.vendorName || tx.customerName || '';
        const isOutstation = window.isPartyOutstation(partyId, staticName);

        if (isGirisons && isAfterCutoff) {
            if (isOutstation) {
                const hasTransporter = tState.isTransporter === 'Yes' && !!tx.transporterId;
                const hasLocal = tState.isLocalFreight === 'Yes';
                if (!hasTransporter && !hasLocal) {
                    missing.push('Transporter Details');
                } else {
                    if (tState.isTransporter === 'Yes') {
                        if (!tx.transporterId) missing.push('Transporter');
                    }
                    if (hasLocal) {
                        if (!tx.vehicleNo || !String(tx.vehicleNo).trim()) missing.push('Vehicle Number');
                        if (!tState.taxiName || !String(tState.taxiName).trim()) missing.push('Taxi Name');
                    }
                }
            } else {
                const hasLocal = tState.isLocalFreight === 'Yes';
                if (!hasLocal) {
                    missing.push('Local Freight Details');
                } else {
                    if (!tx.vehicleNo || !String(tx.vehicleNo).trim()) missing.push('Vehicle Number');
                    if (!tState.taxiName || !String(tState.taxiName).trim()) missing.push('Taxi Name');
                }
            }
        } else {
            if (isOutstation) {
                const hasTransporter = tState.isTransporter === 'Yes' && !!tx.transporterId;
                if (!hasTransporter) {
                    missing.push('Transporter Details');
                }
            }
            if (tState.isTransporter === 'Yes') {
                if (!tx.transporterId) missing.push('Transporter');
            }
            if (tState.isLocalFreight === 'Yes') {
                if (!tx.vehicleNo || !String(tx.vehicleNo).trim()) missing.push('Vehicle Number');
                if (!tState.taxiName || !String(tState.taxiName).trim()) missing.push('Taxi Name');
            }
        }

        const hasCarrier = tx.transporterId || tx.vehicleNo || tState.isTransporter === 'Yes' || tState.isLocalFreight === 'Yes' || tState.freightMode;
        if (hasCarrier) {
            if (tState.freightAmount === undefined || tState.freightAmount === null || tState.freightAmount === '') {
                missing.push('Freight Details');
            }
        }
    } else if (type === 'outward') {
        const wizard = parseOutwardWizardState(tx);
        const isVendorRequired = !(
            (wizard.type === 'fabric_issue_challan' && wizard.source === 'customer') ||
            wizard.type === 'inhouse'
        );
        if (isVendorRequired && !tx.vendorId) {
            missing.push('Vendor');
        }
        if (!tx.qty || parseFloat(tx.qty) <= 0) {
            missing.push('Total Issued Qty');
        }
        
        let currentCustomerId = tx.customerId || '';
        if (!currentCustomerId) {
            db.salesOrders = db.salesOrders || [];
            const linkedSoId = tx.soRefId || tx.soRef || tx.linked_so_id || tx.linkedSoId;
            let linkedSo = null;
            if (linkedSoId) {
                linkedSo = db.salesOrders.find(s => s.id === linkedSoId);
            }
            if (!linkedSo && tx.soNumber) {
                const searchNo = String(tx.soNumber).trim().toLowerCase();
                linkedSo = db.salesOrders.find(s => String(s.number || '').trim().toLowerCase() === searchNo);
            }
            if (linkedSo) {
                currentCustomerId = linkedSo.customerId || linkedSo.customer_id || '';
                if (currentCustomerId) {
                    tx.customerId = currentCustomerId;
                    tx.customerName = linkedSo.customerName || tx.customerName || '';
                }
            }
        }

        if (wizard.type !== 'inhouse' && !currentCustomerId) {
            missing.push('Customer');
        }
        if (wizard.source === 'customer') {
            const hasSOLink = tx.soRefId || tx.soRef || (tx.soLinks && tx.soLinks.length > 0) || tx.soNumber ||
                              tx.linked_so_id || tx.linkedSoId || tx.linked_so_number || tx.linkedSoNumber;
            if (!hasSOLink) {
                missing.push('SO Link');
            }
            if (wizard.type === 'fabric_issue_challan' && wizard.subType === 'embroidered') {
                const linkedSoId = tx.soRefId || tx.soRef || tx.linked_so_id || tx.linkedSoId;
                let linkedSo = null;
                if (linkedSoId) {
                    linkedSo = db.salesOrders.find(s => s.id === linkedSoId);
                }
                if (!linkedSo && tx.soNumber) {
                    const searchNo = String(tx.soNumber).trim().toLowerCase();
                    linkedSo = db.salesOrders.find(s => String(s.number || '').trim().toLowerCase() === searchNo);
                }
                const isWithMaterial = linkedSo && linkedSo.materialType === 'with_material';

                if (!isWithMaterial) {
                    const hasFabricLink = (tx.grnLinks && tx.grnLinks.length > 0) || tx.grnRefId || tx.grnNo;
                    if (!hasFabricLink) {
                        missing.push('Fabric Challan Link');
                    }
                }
            }
        } else if (wizard.type !== 'inhouse') {
            if (!tx.poRefId) {
                missing.push('PO Link');
            }
        }

        // Transport Details validation for Outward
        const tState = parseGrnTransportState(tx); // Uses same remarks parsing
        if (wizard.type !== 'inhouse') {
            const cleanDate = getComparableDate(tx.date || tx.docDate) || '';
            const coName = (window.currentCompany ? window.currentCompany.name : '') || '';
            const isGirisons = !coName || coName.toLowerCase().includes('girisons');
            const isAfterCutoff = cleanDate >= '2026-07-01';

            const partyId = tx.vendorId || tx.customerId;
            const staticName = tx.vendorName || tx.customerName || '';
            const isOutstation = window.isPartyOutstation(partyId, staticName);

            if (isGirisons && isAfterCutoff) {
                if (isOutstation) {
                    const hasTransporter = tState.isTransporter === 'Yes' && !!tx.transporterId;
                    const hasLocal = tState.isLocalFreight === 'Yes';
                    if (!hasTransporter && !hasLocal) {
                        missing.push('Transporter Details');
                    } else {
                        if (tState.isTransporter === 'Yes') {
                            if (!tx.transporterId) missing.push('Transporter');
                        }
                        if (hasLocal) {
                            if (!tx.vehicleNo || !String(tx.vehicleNo).trim()) missing.push('Vehicle Number');
                            if (!tState.taxiName || !String(tState.taxiName).trim()) missing.push('Taxi Name');
                        }
                    }
                } else {
                    const hasLocal = tState.isLocalFreight === 'Yes';
                    if (!hasLocal) {
                        missing.push('Local Freight Details');
                    } else {
                        if (!tx.vehicleNo || !String(tx.vehicleNo).trim()) missing.push('Vehicle Number');
                        if (!tState.taxiName || !String(tState.taxiName).trim()) missing.push('Taxi Name');
                    }
                }
            } else {
                if (isOutstation) {
                    const hasTransporter = tState.isTransporter === 'Yes' && !!tx.transporterId;
                    if (!hasTransporter) {
                        missing.push('Transporter Details');
                    }
                }
                if (tState.isTransporter === 'Yes') {
                    if (!tx.transporterId) missing.push('Transporter');
                }
                if (tState.isLocalFreight === 'Yes') {
                    if (!tx.vehicleNo || !String(tx.vehicleNo).trim()) missing.push('Vehicle Number');
                    if (!tState.taxiName || !String(tState.taxiName).trim()) missing.push('Taxi Name');
                }
            }
        }

        const hasCarrier = tx.transporterId || tx.vehicleNo || tState.isTransporter === 'Yes' || tState.isLocalFreight === 'Yes' || tState.freightMode;
        if (hasCarrier) {
            if (tState.freightAmount === undefined || tState.freightAmount === null || tState.freightAmount === '') {
                missing.push('Freight Details');
            }
        }
    }
    return missing;
}
window.getTransactionIncompleteFields = getTransactionIncompleteFields;

async function reconcileAndSyncTransactions() {
    db.salesOrders = db.salesOrders || [];
    db.pos = db.pos || [];
    db.grns = db.grns || [];

    const updatedGRNs = new Set();
    const updatedPOs = new Set();
    const updatedSOs = new Set();

    // 1. Sync SOs <-> POs
    db.pos.forEach(po => {
        let so = null;
        if (po.linkedSoId) {
            so = db.salesOrders.find(s => s.id === po.linkedSoId);
        }
        if (!so && po.linkedSoNumber) {
            const cleanNum = String(po.linkedSoNumber).trim().toLowerCase();
            so = db.salesOrders.find(s => String(s.number || '').trim().toLowerCase() === cleanNum);
        }
        
        if (so) {
            if (so.customerId && po.customerId !== so.customerId) {
                po.customerId = so.customerId;
                po.customerName = so.customerName || po.customerName;
                updatedPOs.add(po);
            }
            if (so.customerName && po.customerName !== so.customerName) {
                po.customerName = so.customerName;
                updatedPOs.add(po);
            }
            if (so.partyOrderNo && !po.linkedSoNumber) {
                po.linkedSoNumber = so.number;
                po.linkedSoId = so.id;
                updatedPOs.add(po);
            }
            if (!po.linkedSoId) {
                po.linkedSoId = so.id;
                po.linkedSoNumber = so.number;
                updatedPOs.add(po);
            }
        }
    });

    // 2. Sync SOs <-> GRNs
    db.grns.forEach(grn => {
        let so = null;
        if (grn.soRefId || grn.soRef) {
            so = db.salesOrders.find(s => s.id === (grn.soRefId || grn.soRef) && s.customerId === grn.customerId);
        }
        if (!so && grn.soLinks && grn.soLinks.length > 0) {
            so = db.salesOrders.find(s => grn.soLinks.includes(s.id) && s.customerId === grn.customerId);
        }
        if (!so && grn.soNumber) {
            const cleanNum = String(grn.soNumber).trim().toLowerCase();
            so = db.salesOrders.find(s => String(s.number || '').trim().toLowerCase() === cleanNum && s.customerId === grn.customerId);
        }
        if (!so) {
            so = db.salesOrders.find(s => 
                s.customerId === grn.customerId &&
                s.grnLinks && (
                    s.grnLinks.includes(grn.id) ||
                    (grn.number && s.grnLinks.includes('manual:' + grn.number)) ||
                    (grn.grnNo && s.grnLinks.includes('manual:' + grn.grnNo))
                )
            );
        }

        if (so) {
            if (!grn.soRefId) {
                grn.soRefId = so.id;
                updatedGRNs.add(grn);
            }
            if (!grn.soNumber) {
                grn.soNumber = so.number;
                updatedGRNs.add(grn);
            }
            if (!grn.soLinks || !grn.soLinks.includes(so.id)) {
                grn.soLinks = [...new Set([...(grn.soLinks || []), so.id])];
                updatedGRNs.add(grn);
            }
            if (!so.grnLinks || (
                !so.grnLinks.includes(grn.id) &&
                !(grn.number && so.grnLinks.includes('manual:' + grn.number)) &&
                !(grn.grnNo && so.grnLinks.includes('manual:' + grn.grnNo))
            )) {
                so.grnLinks = [...new Set([...(so.grnLinks || []), grn.id])];
                updatedSOs.add(so);
            }

            const soPartyNo = (so.partyOrderNo || '').toString().trim();
            const grnCustNo = (grn.custOrderNo || '').toString().trim();
            
            if (soPartyNo && !grnCustNo) {
                grn.custOrderNo = soPartyNo;
                updatedGRNs.add(grn);
            } else if (grnCustNo && !soPartyNo) {
                so.partyOrderNo = grnCustNo;
                updatedSOs.add(so);
            }
        }
    });

    // 3. Sync POs <-> GRNs
    db.grns.forEach(grn => {
        let po = null;
        if (grn.poRefId || grn.poRef) {
            po = db.pos.find(p => p.id === (grn.poRefId || grn.poRef));
        }
        if (!po && grn.poNumber) {
            const cleanNum = String(grn.poNumber).trim().toLowerCase();
            po = db.pos.find(p => String(p.number || '').trim().toLowerCase() === cleanNum);
        }

        if (po) {
            if (!grn.poRefId) {
                grn.poRefId = po.id;
                updatedGRNs.add(grn);
            }
            if (!grn.poNumber) {
                grn.poNumber = po.number;
                updatedGRNs.add(grn);
            }

            if (po.linkedSoId && !grn.soRefId) {
                grn.soRefId = po.linkedSoId;
                grn.soNumber = po.linkedSoNumber || grn.soNumber;
                grn.soLinks = [...new Set([...(grn.soLinks || []), po.linkedSoId])];
                updatedGRNs.add(grn);
            }
            if (grn.soRefId && !po.linkedSoId) {
                po.linkedSoId = grn.soRefId;
                po.linkedSoNumber = grn.soNumber || po.linkedSoNumber;
                updatedPOs.add(po);
            }
        }
    });

    // 4. Sync Outwards <-> POs <-> SOs
    db.outwards = db.outwards || [];
    const updatedOutwards = new Set();
    db.outwards.forEach(out => {
        let po = null;
        const poRefId = out.poRefId || out.linked_po_id;
        if (poRefId) {
            po = db.pos.find(p => p.id === poRefId);
        }
        if (!po && out.poNumber) {
            const cleanNum = String(out.poNumber).trim().toLowerCase();
            po = db.pos.find(p => String(p.number || '').trim().toLowerCase() === cleanNum);
        }

        if (po) {
            if (!out.poRefId) {
                out.poRefId = po.id;
                updatedOutwards.add(out);
            }
            if (!out.poNumber) {
                out.poNumber = po.number;
                updatedOutwards.add(out);
            }

            // Sync Customer
            let resolvedCustId = po.customerId;
            if (!resolvedCustId && po.linkedSoId) {
                const so = db.salesOrders.find(s => s.id === po.linkedSoId);
                if (so) resolvedCustId = so.customerId;
            }
            if (resolvedCustId && out.customerId !== resolvedCustId) {
                out.customerId = resolvedCustId;
                const custObj = db.customers.find(c => c.id === resolvedCustId);
                if (custObj) out.customerName = custObj.name;
                updatedOutwards.add(out);
            }
        }
    });

    if (updatedGRNs.size > 0 || updatedPOs.size > 0 || updatedSOs.size > 0 || updatedOutwards.size > 0) {
        saveDB();
        console.log(`[Reconciliation] Local DB updated. Reconciled ${updatedGRNs.size} GRNs, ${updatedPOs.size} POs, ${updatedSOs.size} SOs, ${updatedOutwards.size} Outwards.`);
    }
}
window.reconcileAndSyncTransactions = reconcileAndSyncTransactions;

window.scrollToPendingTransactions = function() {
    const el = document.getElementById('pending-transactions-section');
    if (el) {
        el.scrollIntoView({ behavior: 'smooth' });
        // Flash the container with a soft orange overlay to highlight focus
        el.style.transition = 'background-color 0.5s ease';
        el.style.backgroundColor = 'rgba(245, 158, 11, 0.08)';
        setTimeout(() => {
            el.style.backgroundColor = 'transparent';
        }, 1500);
    }
};

window.setComingFromPending = function() {
    window.comingFromPendingModal = {
        tab: window.currentPendingModalTab || 'All',
        search: document.getElementById('pending-modal-search')?.value || '',
        subFilter: document.getElementById('pending-modal-subtype-filter')?.value || 'All'
    };
};

window.currentPendingModalTab = 'All';

window.openPendingIncompleteModal = function(tabName = 'All') {
    window.currentPendingModalTab = tabName;
    if (typeof openModal === 'function') {
        openModal('pending-incomplete-modal');
    } else {
        const el = document.getElementById('pending-incomplete-modal');
        if (el) el.classList.add('active');
    }
    switchPendingModalTab(tabName);
};

window.openPendingIncompleteModalWithSubtype = function(tabName, subtype) {
    window.currentPendingModalTab = tabName;
    if (typeof openModal === 'function') {
        openModal('pending-incomplete-modal');
    } else {
        const el = document.getElementById('pending-incomplete-modal');
        if (el) el.classList.add('active');
    }
    switchPendingModalTab(tabName);
    const subFilter = document.getElementById('pending-modal-subtype-filter');
    if (subFilter) {
        subFilter.value = subtype;
        renderPendingModalTable();
    }
};

window.openPendingIncompleteModalWithSearch = function(searchVal) {
    window.openPendingIncompleteModal('All');
    setTimeout(() => {
        const searchInput = document.getElementById('pending-modal-search');
        if (searchInput) {
            searchInput.value = searchVal;
            renderPendingModalTable();
        }
    }, 50);
};

window.gatherAllPendencyItems = function() {
    db.salesOrders = db.salesOrders || [];
    db.pos = db.pos || [];
    db.grns = db.grns || [];
    db.outwards = db.outwards || [];
    db.requisitionSlips = db.requisitionSlips || [];
    db.genericTransactions = db.genericTransactions || [];
    db.productionSlips = db.productionSlips || [];
    db.boms = db.boms || [];
    db.productionPlans = db.productionPlans || [];

    const list = [];

    // 1. Sales Orders
    db.salesOrders.forEach(so => {
        if (!window.isRecordVisibleToCurrentUser(so)) return;
        const missing = getTransactionIncompleteFields(so, 'so');
        if (missing.length > 0) {
            list.push({
                id: so.id,
                type: 'Sales Order',
                subType: '',
                refNo: so.number || '',
                date: so.date,
                party: so.customerName || 'N/A',
                missing: missing,
                status: so.status || 'Pending',
                action: `window.setComingFromPending(); closeModal('pending-incomplete-modal'); openSOModal('${so.id}')`
            });
        }
    });

    // 2. Purchase Orders
    db.pos.forEach(po => {
        if (!window.isRecordVisibleToCurrentUser(po)) return;
        const missing = getTransactionIncompleteFields(po, 'po');
        if (missing.length > 0) {
            let typeLabel = 'Purchase Order - Vendor';
            let subType = 'vendor';
            const num = (po.number || '').toUpperCase();
            if (num.includes('PO/VEN')) { typeLabel = 'Purchase Order - Vendor'; subType = 'vendor'; }
            else if (num.includes('PO/INH')) { typeLabel = 'Purchase Order - Inhouse'; subType = 'inhouse'; }
            else if (num.includes('PO/CON')) { typeLabel = 'Purchase Order - Consumable'; subType = 'consumable'; }
            else if (num.includes('PO/FJW') || num.includes('PO/FIN')) { typeLabel = 'Purchase Order - Finishing JW'; subType = 'finishing_jw'; }
            else if (num.includes('PO/OTH')) { typeLabel = 'Purchase Order - Other'; subType = 'other'; }
            list.push({
                id: po.id,
                type: typeLabel,
                subType: subType,
                refNo: po.number || '',
                date: po.date,
                party: po.vendorName || po.customerName || 'N/A',
                missing: missing,
                status: po.status || 'Pending',
                action: `window.setComingFromPending(); closeModal('pending-incomplete-modal'); openPOModal('${po.id}')`
            });
        }

        // In-House PO Pendency (No Fabric Issue FI/INH yet)
        if (po.status !== 'Cancelled') {
            const isPOInhouse = po.poType === 'inhouse' || po.po_type === 'inhouse' || (po.number && String(po.number).toUpperCase().startsWith('PO/INH'));
            if (isPOInhouse) {
                const hasFiInh = (db.outwards || []).some(out => {
                    if (out.status === 'Cancelled') return false;
                    const num = (out.number || out.outwardNo || '').toUpperCase();
                    const isFiInh = num.startsWith('FI/INH');
                    if (!isFiInh) return false;
                    return out.linkedPoId === po.id || out.linked_po_id === po.id || out.poNo === po.number || out.po_number === po.number;
                });
                if (!hasFiInh) {
                    list.push({
                        id: po.id,
                        type: 'Purchase Order - Inhouse',
                        subType: 'inhouse',
                        refNo: po.number || '',
                        date: po.date,
                        party: po.customerName || po.customer_name || 'N/A',
                        missing: ['No Fabric Issue Yet (FI/INH)'],
                        status: po.status || 'Pending',
                        action: `window.setComingFromPending(); closeModal('pending-incomplete-modal'); openPOModal('${po.id}')`
                    });
                }
            }
        }
    });

    // 3. GRNs
    db.grns.forEach(grn => {
        if (!window.isRecordVisibleToCurrentUser(grn)) return;
        const missing = getTransactionIncompleteFields(grn, 'grn');
        if (missing.length > 0) {
            let typeLabel = 'GRN - Cust Plain';
            let subType = 'c_pf';
            const num = (grn.grnNo || grn.number || '').toUpperCase();
            if (num.includes('GRN/C/PF')) { typeLabel = 'GRN - Cust Plain'; subType = 'c_pf'; }
            else if (num.includes('GRN/V/EM') || num.includes('GRN/V/PF') || num.includes('GRN/V/EMB')) { typeLabel = 'GRN - Vend Emb'; subType = 'v_em'; }
            else if (num.includes('GRN/CON') || num.includes('GRN/OTH')) { typeLabel = 'GRN - Consumable'; subType = 'consumable'; }
            list.push({
                id: grn.id,
                type: typeLabel,
                subType: subType,
                refNo: grn.grnNo || grn.number || '',
                date: grn.date,
                party: grn.customerName || grn.vendorName || 'N/A',
                missing: missing,
                status: grn.status || 'Pending',
                action: missing.includes('Freight Details') ? `window.setComingFromPending(); closeModal('pending-incomplete-modal'); window.openFreightPopModal('${grn.id}', 'grn')` : `window.setComingFromPending(); closeModal('pending-incomplete-modal'); openGRNModal('${grn.id}')`
            });
        }
    });

    // 4. Outwards
    db.outwards.forEach(out => {
        if (!window.isRecordVisibleToCurrentUser(out)) return;
        const missing = getTransactionIncompleteFields(out, 'outward');
        if (missing.length > 0) {
            const wizard = parseOutwardWizardState(out);
            let subType = '';
            if (wizard.type === 'fabric_issue_challan') {
                subType = `fi_${wizard.source}_${wizard.subType}`;
            } else if (wizard.type === 'inhouse') {
                subType = 'inhouse';
            } else if (wizard.type === 'jobworker') {
                subType = 'jobworker';
            }
            let resolvedParty = window.getOutwardPartyName(out);

            list.push({
                id: out.id,
                type: 'Outward',
                subType: subType,
                refNo: out.number || '',
                date: out.date,
                party: resolvedParty,
                missing: missing,
                status: out.status || 'Pending',
                action: missing.includes('Freight Details') ? `window.setComingFromPending(); closeModal('pending-incomplete-modal'); window.openFreightPopModal('${out.id}', 'outward')` : `window.setComingFromPending(); closeModal('pending-incomplete-modal'); openOutwardModal('${out.id}')`
            });
        }
    });

    // 5. Requisitions
    db.requisitionSlips.forEach(req => {
        if (!window.isRecordVisibleToCurrentUser(req)) return;
        if (req.status === 'Cancelled' || req.status === 'Closed') return;
        const missing = [];
        if (!req.date) missing.push('Date');
        if (!req.items || req.items.length === 0) missing.push('Items Grid');
        if (missing.length > 0 || (req.status || 'Pending').toLowerCase().trim() === 'pending') {
            const displayMissing = missing.length > 0 ? missing : ['Pending Issue'];
            list.push({
                id: req.id,
                type: 'Requisition',
                subType: '',
                refNo: req.number || '',
                date: req.date,
                party: req.dept || 'N/A',
                missing: displayMissing,
                status: req.status || 'Pending',
                action: `window.setComingFromPending(); closeModal('pending-incomplete-modal'); window.openRequisitionModal('${req.id}')`
            });
        }
    });

    // 6. Generic Transactions (Invoices, Purchases, Accounting Vouchers, Returns)
    db.genericTransactions.forEach(tx => {
        if (!window.isRecordVisibleToCurrentUser(tx)) return;
        const missing = [];
        if (!tx.date) missing.push('Date');
        if (!tx.partyId) missing.push('Party/Account');
        if (!tx.totalValue || tx.totalValue <= 0) missing.push('Amount');
        if (missing.length > 0) {
            let label = 'Invoice';
            if (tx.type === 'voucher') label = 'Voucher';
            else if (tx.type === 'salesreturn') label = 'Sales Return';
            else if (tx.type === 'purchasereturn') label = 'Purchase Return';
            else if (tx.type === 'receipt') label = 'Receipt';
            else if (tx.type === 'payment') label = 'Payment';
            else if (tx.type === 'journal') label = 'Journal';
            else if (tx.type === 'contra') label = 'Contra';
            list.push({
                id: tx.id,
                type: label,
                subType: '',
                refNo: tx.number || '',
                date: tx.date,
                party: tx.partyName || 'N/A',
                missing: missing,
                status: tx.status || 'Pending',
                action: `window.setComingFromPending(); closeModal('pending-incomplete-modal'); openGenericTxModal('${tx.type}', '${tx.id}')`
            });
        }
    });

    // 7. Production Slips / Sampling Slips
    db.productionSlips.forEach(slip => {
        if (!window.isRecordVisibleToCurrentUser(slip)) return;
        if (slip.status === 'Cancelled') return;
        const missing = [];
        if (!slip.date) missing.push('Date');
        if (!slip.machineId) missing.push('Machine');
        const hasRows = (slip.links && slip.links.length > 0) || 
                        (slip.rows && slip.rows.length > 0) || 
                        (slip.poId && slip.qty > 0);
        if (!hasRows) missing.push('Production Details');
        if (missing.length > 0) {
            const isSampling = (slip.number || '').startsWith('SMP');
            list.push({
                id: slip.id,
                type: isSampling ? 'Sampling' : 'Production',
                subType: '',
                refNo: slip.number || '',
                date: slip.date,
                party: isSampling ? 'Sampling Slip' : 'Production Slip',
                missing: missing,
                status: slip.status || 'Pending',
                action: `window.setComingFromPending(); closeModal('pending-incomplete-modal'); openProductionModal('${slip.id}', '${isSampling ? 'sampling' : 'production'}')`
            });
        }
    });

    // 8. BOM Specs
    db.boms.forEach(bom => {
        if (!checkPermission('masters_bom', 'read')) return;
        const missingBOMItems = [];
        const stitch = parseFloat(bom.designStitch) || 0;
        const repeat = (bom.repeat || '').toString().trim();
        const realIngs = (bom.ingredients || []).filter(ing => 
            ing.itemId !== 'METADATA_DESIGN_STITCH' && ing.itemId !== 'METADATA_DESIGN_REPEAT_STR'
        );
        if (stitch <= 0) missingBOMItems.push('Stitch Count');
        if (!repeat) missingBOMItems.push('Repeat Specs');
        if (realIngs.length === 0) missingBOMItems.push('Ingredients/Raw Materials');
        if (missingBOMItems.length > 0) {
            list.push({
                id: bom.id,
                type: 'BOM Specs',
                subType: 'All',
                refNo: bom.code || 'BOM',
                date: '-',
                party: bom.finishedItemName || 'Finished Item',
                missing: missingBOMItems.map(m => `Missing ${m}`),
                status: bom.status || 'Active',
                action: `window.setComingFromPending(); closeModal('pending-incomplete-modal'); openBOMModal('${bom.id}')`
            });
        }
    });

    // 9. Production Slip Date Mismatch Check
    db.productionSlips.forEach(slip => {
        if (!window.isRecordVisibleToCurrentUser(slip)) return;
        if (slip.planId && (slip.status || '').trim().toLowerCase() !== 'cancelled') {
            const plan = (db.productionPlans || []).find(p => p.id === slip.planId);
            if (plan) {
                const planDateRaw = plan.planDate || plan.date;
                const slipDateRaw = slip.date;
                const planDate = getComparableDate(planDateRaw);
                const slipDate = getComparableDate(slipDateRaw);
                if (planDate && slipDate && slipDate < planDate) {
                    list.push({
                        id: slip.id,
                        type: 'Prod Slip Date Mismatch',
                        subType: 'All',
                        refNo: slip.number || '',
                        date: slipDateRaw,
                        party: `Plan: ${plan.number || 'N/A'} (${formatDate(planDateRaw)})`,
                        missing: [`Date (${formatDate(slipDateRaw)}) is earlier than Plan Date (${formatDate(planDateRaw)})`],
                        status: slip.status || 'Pending',
                        action: `window.setComingFromPending(); closeModal('pending-incomplete-modal'); openProductionModal('${slip.id}', 'production')`
                    });
                }
            }
        }
    });

    return list;
};

window.switchPendingModalTab = function(tabName) {
    window.currentPendingModalTab = tabName;
    
    // Clear 'Freight Details' search if switching tabs
    const searchInput = document.getElementById('pending-modal-search');
    if (searchInput && searchInput.value === 'Freight Details') {
        searchInput.value = '';
    }
    
    // Highlight correct tab button
    ['All', 'SalesOrder', 'PurchaseOrder', 'GRN', 'Outward', 'BOMPendency', 'ProdSlipDateMismatch', 'OtherVouchers'].forEach(t => {
        const btn = document.getElementById(`p-tab-${t}`);
        if (!btn) return;
        
        let match = false;
        if (t === 'All' && tabName === 'All') match = true;
        if (t === 'SalesOrder' && tabName === 'Sales Order') match = true;
        if (t === 'PurchaseOrder' && tabName === 'Purchase Order') match = true;
        if (t === 'GRN' && tabName === 'GRN') match = true;
        if (t === 'Outward' && tabName === 'Outward') match = true;
        if (t === 'BOMPendency' && tabName === 'BOM Pendency') match = true;
        if (t === 'ProdSlipDateMismatch' && tabName === 'Prod Slip Date Mismatch') match = true;
        if (t === 'OtherVouchers' && tabName === 'Other Vouchers') match = true;
        
        if (match) {
            btn.style.background = 'linear-gradient(135deg, #e11d48 0%, #be123c 100%)';
            btn.style.color = '#ffffff';
            btn.style.borderColor = 'transparent';
        } else {
            btn.style.background = 'var(--bg-card)';
            btn.style.color = 'var(--text-primary)';
            btn.style.borderColor = 'var(--border)';
        }
    });

    // Populate Sub-Type select options
    const subFilter = document.getElementById('pending-modal-subtype-filter');
    if (subFilter) {
        subFilter.innerHTML = '';
        if (tabName === 'All' || tabName === 'Sales Order' || tabName === 'BOM Pendency' || tabName === 'Prod Slip Date Mismatch') {
            subFilter.innerHTML = '<option value="All">All Sub-Types</option>';
            subFilter.disabled = true;
        } else if (tabName === 'Purchase Order') {
            subFilter.disabled = false;
            subFilter.innerHTML = `
                <option value="All">All Purchase Orders</option>
                <option value="vendor">Vendor Job Work PO (PO/VEN)</option>
                <option value="inhouse">Inhouse Fabric PO (PO/INH)</option>
                <option value="consumable">Consumable PO (PO/CON)</option>
                <option value="finishing_jw">Finishing JW PO (PO/FJW)</option>
                <option value="other">Other PO (PO/OTH)</option>
            `;
        } else if (tabName === 'GRN') {
            subFilter.disabled = false;
            subFilter.innerHTML = `
                <option value="All">All GRNs</option>
                <option value="v_pf">Vendor Plain (GRN/V/PF)</option>
                <option value="v_em">Vendor Embroidered (GRN/V/EM)</option>
                <option value="c_pf">Customer Plain (GRN/C/PF)</option>
                <option value="c_em">Customer Embroidered (GRN/C/EM)</option>
                <option value="consumable">Consumable / Other GRN</option>
            `;
        } else if (tabName === 'Outward') {
            subFilter.disabled = false;
            subFilter.innerHTML = `
                <option value="All">All Outward Challans</option>
                <option value="fi_vendor_plain">Fabric Issue - Vendor Plain (FI/V/PF)</option>
                <option value="fi_vendor_embroidered">Fabric Issue - Vendor Embroidered (FI/V/EM)</option>
                <option value="fi_customer_plain">Fabric Issue - Customer Plain (FI/C/PF)</option>
                <option value="fi_customer_embroidered">Fabric Issue - Customer Embroidered (FI/C/EM)</option>
                <option value="inhouse">Fabric Issue - In-House (FI/INH)</option>
                <option value="jobworker">Job Work Challan - Job Worker (FI/JW)</option>
            `;
        } else if (tabName === 'Other Vouchers') {
            subFilter.disabled = false;
            subFilter.innerHTML = `
                <option value="All">All Other Vouchers</option>
                <option value="Requisition">Requisition Slip</option>
                <option value="Invoice">Tax Invoice</option>
                <option value="Voucher">Purchase Voucher</option>
                <option value="Sales Return">Sales Return</option>
                <option value="Purchase Return">Purchase Return</option>
                <option value="Receipt">Receipt Voucher</option>
                <option value="Payment">Payment Voucher</option>
                <option value="Journal">Journal Voucher</option>
                <option value="Contra">Contra Voucher</option>
                <option value="Production">Production Log</option>
                <option value="Sampling">Sampling Slip</option>
            `;
        }
    }

    renderPendingModalTable();
};

window.renderPendingModalTable = function() {
    const tbody = document.getElementById('pending-modal-table-body');
    if (!tbody) return;

    let list = window.gatherAllPendencyItems();

    const layout = getCurrentUserDashboardLayout();
    const allowedTypes = layout.pendingTypes || [
        'Sales Order', 
        'Purchase Order - Vendor', 'Purchase Order - Inhouse', 'Purchase Order - Consumable', 'Purchase Order - Other', 
        'GRN - Cust Plain', 'GRN - Vend Emb', 'GRN - Consumable', 
        'Outward', 'Requisition', 'Invoice', 'Voucher', 'Sales Return', 'Purchase Return', 'Receipt', 'Payment', 'Journal', 'Contra', 'Production', 'Sampling',
        'BOM Specs', 'Prod Slip Date Mismatch'
    ];
    list = list.filter(tx => allowedTypes.includes(tx.type));

    const soCount = list.filter(tx => tx.type === 'Sales Order').length;
    const poCount = list.filter(tx => tx.type.startsWith('Purchase Order')).length;
    const grnCount = list.filter(tx => tx.type.startsWith('GRN')).length;
    const outwardCount = list.filter(tx => tx.type === 'Outward').length;
    const bomCount = list.filter(tx => tx.type === 'BOM Specs' || tx.type === 'BOM Pendency').length;
    const mismatchCount = list.filter(tx => tx.type === 'Prod Slip Date Mismatch').length;
    const otherCount = list.filter(tx => ['Requisition', 'Invoice', 'Voucher', 'Sales Return', 'Purchase Return', 'Receipt', 'Payment', 'Journal', 'Contra', 'Production', 'Sampling'].includes(tx.type)).length;
    const allCount = list.length;

    const cntAll = document.getElementById('p-cnt-all');
    if (cntAll) cntAll.textContent = allCount;
    const cntSo = document.getElementById('p-cnt-so');
    if (cntSo) cntSo.textContent = soCount;
    const cntPo = document.getElementById('p-cnt-po');
    if (cntPo) cntPo.textContent = poCount;
    const cntGrn = document.getElementById('p-cnt-grn');
    if (cntGrn) cntGrn.textContent = grnCount;
    const cntOut = document.getElementById('p-cnt-out');
    if (cntOut) cntOut.textContent = outwardCount;
    const cntBom = document.getElementById('p-cnt-bom');
    if (cntBom) cntBom.textContent = bomCount;
    const cntMismatch = document.getElementById('p-cnt-mismatch');
    if (cntMismatch) cntMismatch.textContent = mismatchCount;
    const cntOther = document.getElementById('p-cnt-other');
    if (cntOther) cntOther.textContent = otherCount;

    let filtered = list;
    if (window.currentPendingModalTab === 'Sales Order') {
        filtered = list.filter(tx => tx.type === 'Sales Order');
    } else if (window.currentPendingModalTab === 'Purchase Order') {
        filtered = list.filter(tx => tx.type.startsWith('Purchase Order'));
    } else if (window.currentPendingModalTab === 'GRN') {
        filtered = list.filter(tx => tx.type.startsWith('GRN'));
    } else if (window.currentPendingModalTab === 'Outward') {
        filtered = list.filter(tx => tx.type === 'Outward');
    } else if (window.currentPendingModalTab === 'BOM Pendency') {
        filtered = list.filter(tx => tx.type === 'BOM Specs' || tx.type === 'BOM Pendency');
    } else if (window.currentPendingModalTab === 'Prod Slip Date Mismatch') {
        filtered = list.filter(tx => tx.type === 'Prod Slip Date Mismatch');
    } else if (window.currentPendingModalTab === 'Other Vouchers') {
        const others = ['Requisition', 'Invoice', 'Voucher', 'Sales Return', 'Purchase Return', 'Receipt', 'Payment', 'Journal', 'Contra', 'Production', 'Sampling'];
        filtered = list.filter(tx => others.includes(tx.type));
    }

    const subFilter = document.getElementById('pending-modal-subtype-filter');
    if (subFilter && subFilter.value !== 'All' && !subFilter.disabled) {
        if (window.currentPendingModalTab === 'Other Vouchers') {
            filtered = filtered.filter(tx => tx.type === subFilter.value);
        } else {
            filtered = filtered.filter(tx => tx.subType === subFilter.value);
        }
    }

    const searchInput = document.getElementById('pending-modal-search');
    const searchVal = searchInput ? searchInput.value.toLowerCase().trim() : '';
    if (searchVal) {
        filtered = filtered.filter(tx => 
            tx.refNo.toLowerCase().includes(searchVal) || 
            tx.party.toLowerCase().includes(searchVal) ||
            tx.missing.join(', ').toLowerCase().includes(searchVal)
        );
    }

    if (filtered.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" class="empty-row" style="text-align: center; padding: 40px; color: var(--text-muted);">No pending documents found matching current filters.</td></tr>';
    } else {
        tbody.innerHTML = filtered.map(tx => {
            let docBadgeColor = '#64748b';
            if (tx.type === 'Sales Order') docBadgeColor = 'var(--accent-purple)';
            else if (tx.type.startsWith('Purchase Order')) docBadgeColor = 'var(--accent-orange)';
            else if (tx.type.startsWith('GRN')) docBadgeColor = '#e11d48';
            else if (tx.type === 'Outward') docBadgeColor = '#0284c7';
            else if (tx.type === 'BOM Specs' || tx.type === 'BOM Pendency') docBadgeColor = 'var(--accent-green, #10b981)';
            else if (tx.type === 'Requisition') docBadgeColor = '#6366f1';
            else if (tx.type === 'Invoice') docBadgeColor = '#059669';
            else if (tx.type === 'Voucher') docBadgeColor = '#7c3aed';
            else if (tx.type === 'Production') docBadgeColor = '#db2777';
            else if (tx.type === 'Sampling') docBadgeColor = '#ea580c';

            const formattedMissing = tx.missing.map(f => `<span style="display: inline-block; background: #ffe4e6; color: #b91c1c; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 600; margin: 2px 4px 2px 0;">${f}</span>`).join(' ');
            const statusBadgeColor = (tx.status === 'Issued' || tx.status === 'Active' || tx.status === 'Verified') ? '#dcfce7' : '#fef9c3';
            const statusTextColor = (tx.status === 'Issued' || tx.status === 'Active' || tx.status === 'Verified') ? '#15803d' : '#854d0e';

            return `
                <tr style="border-bottom: 1px solid var(--border);">
                    <td style="padding: 12px; font-weight: 600;"><span style="background: ${docBadgeColor}; color: white; padding: 3px 8px; border-radius: 4px; font-size: 11px;">${tx.type}</span></td>
                    <td style="padding: 12px; font-weight: 700; color: var(--text-primary);">
                        <a href="javascript:void(0)" onclick="${tx.action}" style="color: var(--accent-blue, #3b82f6); text-decoration: underline;">${tx.refNo}</a>
                        <span style="display: inline-block; background: ${statusBadgeColor}; color: ${statusTextColor}; padding: 2px 6px; border-radius: 4px; font-size: 10px; font-weight: 700; margin-left: 6px; border: 1px solid opacity 0.1;">
                            ${tx.status || 'Pending'}
                        </span>
                    </td>
                    <td style="padding: 12px; color: var(--text-secondary);">${tx.date === '-' ? '-' : (typeof formatDate === 'function' ? formatDate(tx.date) : tx.date)}</td>
                    <td style="padding: 12px; font-weight: 600; color: var(--text-primary);">${tx.party}</td>
                    <td style="padding: 12px;">${formattedMissing}</td>
                    <td style="padding: 12px; text-align: center;">
                        <button class="btn btn-sm btn-primary" onclick="${tx.action}" style="font-weight: 600; padding: 5px 12px; border-radius: 6px;"> Modify</button>
                    </td>
                </tr>
            `;
        }).join('');
    }
};

window.renderPendingTransactionsWidget = function() {
    const container = document.getElementById('widget-pending-transactions');
    const tbody = document.getElementById('pending-transactions-body');
    const countBadge = document.getElementById('pending-transactions-count');
    if (!tbody || !container) return;

    // Trigger reconciliation asynchronously but do not block UI render
    reconcileAndSyncTransactions().catch(e => console.error(e));

    let pendingList = window.gatherAllPendencyItems();

    const layout = getCurrentUserDashboardLayout();
    const allowedTypes = layout.pendingTypes || [
        'Sales Order', 
        'Purchase Order - Vendor', 'Purchase Order - Inhouse', 'Purchase Order - Consumable', 'Purchase Order - Other', 
        'GRN - Cust Plain', 'GRN - Vend Emb', 'GRN - Consumable', 
        'Outward', 'Requisition', 'Invoice', 'Voucher', 'Sales Return', 'Purchase Return', 'Receipt', 'Payment', 'Journal', 'Contra', 'Production', 'Sampling',
        'BOM Specs', 'Prod Slip Date Mismatch'
    ];
    pendingList = pendingList.filter(tx => allowedTypes.includes(tx.type));

    const filterEl = document.getElementById('pending-tx-type-filter');
    const filterVal = filterEl ? filterEl.value : 'All';
    let filteredList = pendingList;
    if (filterVal !== 'All') {
        if (['Sales Order', 'Requisition', 'Invoice', 'Voucher', 'Sales Return', 'Purchase Return', 'Receipt', 'Payment', 'Journal', 'Contra', 'Production', 'Sampling', 'Prod Slip Date Mismatch'].includes(filterVal)) {
            filteredList = pendingList.filter(tx => tx.type === filterVal);
        } else if (filterVal === 'BOM Specs' || filterVal === 'BOM Pendency') {
            filteredList = pendingList.filter(tx => tx.type === 'BOM Specs' || tx.type === 'BOM Pendency');
        } else if (filterVal === 'Purchase Order') {
            filteredList = pendingList.filter(tx => tx.type.startsWith('Purchase Order'));
        } else if (filterVal === 'GRN') {
            filteredList = pendingList.filter(tx => tx.type.startsWith('GRN'));
        } else if (filterVal === 'Outward') {
            filteredList = pendingList.filter(tx => tx.type === 'Outward');
        } else if (filterVal.startsWith('PO_')) {
            const subtypeVal = filterVal.substring(3);
            filteredList = pendingList.filter(tx => tx.type.startsWith('Purchase Order') && tx.subType === subtypeVal);
        } else if (filterVal.startsWith('GRN_')) {
            const subtypeVal = filterVal.substring(4);
            filteredList = pendingList.filter(tx => tx.type.startsWith('GRN') && tx.subType === subtypeVal);
        } else if (filterVal.startsWith('OUT_')) {
            const subtypeVal = filterVal.substring(4);
            filteredList = pendingList.filter(tx => tx.type === 'Outward' && tx.subType === subtypeVal);
        }
    }

    if (countBadge) countBadge.textContent = filteredList.length;

    const statPendingCountEl = document.getElementById('stat-pending-count');
    if (statPendingCountEl) {
        statPendingCountEl.textContent = pendingList.length;
    }

    const soCount = pendingList.filter(tx => tx.type === 'Sales Order').length;
    const poCount = pendingList.filter(tx => tx.type.startsWith('Purchase Order')).length;
    const grnCount = pendingList.filter(tx => tx.type.startsWith('GRN')).length;
    const outwardCount = pendingList.filter(tx => tx.type === 'Outward').length;

    const subSoEl = document.getElementById('sub-pending-so');
    if (subSoEl) subSoEl.textContent = soCount;
    const subPoEl = document.getElementById('sub-pending-po');
    if (subPoEl) subPoEl.textContent = poCount;
    const subGrnEl = document.getElementById('sub-pending-grn');
    if (subGrnEl) subGrnEl.textContent = grnCount;
    const subOutEl = document.getElementById('sub-pending-outward');
    if (subOutEl) subOutEl.textContent = outwardCount;

    if (typeof renderPendingShortcuts === 'function') {
        renderPendingShortcuts(pendingList);
    }

    container.style.display = 'none';

    if (pendingList.length === 0) {
        tbody.innerHTML = '<tr><td colspan="6" class="empty-row" style="text-align: center;">No pending documents needing attention.</td></tr>';
    } else {
        if (filteredList.length === 0) {
            tbody.innerHTML = `<tr><td colspan="6" class="empty-row" style="text-align: center;">No pending ${filterVal}s found.</td></tr>`;
        } else {
            tbody.innerHTML = filteredList.map(tx => {
                let docBadgeColor = 'var(--accent-blue)';
                if (tx.type === 'Sales Order') docBadgeColor = '#9333ea';
                else if (tx.type.startsWith('Purchase Order')) docBadgeColor = '#ea580c';
                else if (tx.type.startsWith('GRN')) docBadgeColor = '#2563eb';
                else if (tx.type === 'Outward') docBadgeColor = '#0284c7';
                else if (tx.type === 'BOM Specs' || tx.type === 'BOM Pendency') docBadgeColor = 'var(--accent-green, #10b981)';
                else if (tx.type === 'Requisition') docBadgeColor = '#6366f1';
                else if (tx.type === 'Invoice') docBadgeColor = '#059669';
                else if (tx.type === 'Voucher') docBadgeColor = '#7c3aed';
                else if (tx.type === 'Production') docBadgeColor = '#db2777';
                else if (tx.type === 'Sampling') docBadgeColor = '#ea580c';

                const formattedMissing = tx.missing.map(f => `<span style="display: inline-block; background: #ffe4e6; color: #b91c1c; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 600; margin: 2px 4px 2px 0;">${f}</span>`).join(' ');

                return `
                    <tr style="border-bottom: 1px solid var(--border);">
                        <td style="padding: 12px; font-weight: 600;"><span style="background: ${docBadgeColor}; color: white; padding: 3px 8px; border-radius: 4px; font-size: 11px;">${tx.type}</span></td>
                        <td style="padding: 12px; font-weight: 700; color: var(--text-primary);">${tx.refNo}</td>
                        <td style="padding: 12px; color: var(--text-secondary);">${tx.date === '-' ? '-' : (typeof formatDate === 'function' ? formatDate(tx.date) : tx.date)}</td>
                        <td style="padding: 12px; font-weight: 600; color: var(--text-primary);">${tx.party}</td>
                        <td style="padding: 12px;">${formattedMissing}</td>
                        <td style="padding: 12px; text-align: center;">
                            <button class="btn btn-sm btn-primary" onclick="${tx.action}" style="font-weight: 600; padding: 5px 12px; border-radius: 6px;"> Modify</button>
                        </td>
                    </tr>
                `;
            }).join('');
        }
    }
};

