// ===== CUSTOM EXPORT PRESETS CONFIGURATOR LOGIC =====
window.openExportSelectorModal = function(type) {
    console.log("openExportSelectorModal called with type:", type);
    const typeInput = document.getElementById('export-module-type');
    const container = document.getElementById('export-columns-container');
    const selectPreset = document.getElementById('export-preset-select');
    const presetNameInput = document.getElementById('export-preset-name');
    
    if (!typeInput || !container || !selectPreset || !presetNameInput) {
        console.warn("Failed to find one or more export dialog elements:", {
            typeInput: !!typeInput,
            container: !!container,
            selectPreset: !!selectPreset,
            presetNameInput: !!presetNameInput
        });
        return;
    }
    
    typeInput.value = type;
    presetNameInput.value = '';
    
    let headers = [];
    if (ExportConfig[type]) {
        headers = ExportConfig[type].headers;
    } else if (window.customMasters && window.customMasters[type]) {
        headers = ['name'];
    } else {
        showToast('Export not available for this type', 'info');
        return;
    }
    
    // Helper map for label display
    const labelMap = {};
    const singularKey = type.endsWith('s') ? type.slice(0, -1) : type;
    const colDefaults = window.tableColumnDefaults ? (window.tableColumnDefaults[type] || window.tableColumnDefaults[singularKey]) : null;
    if (colDefaults) {
        colDefaults.forEach(col => {
            labelMap[col.key] = col.label;
        });
    }

    // Render column checkboxes
    container.innerHTML = headers.map(hdr => {
        const displayLabel = labelMap[hdr] || hdr;
        return `
        <label style="display: flex; align-items: center; gap: 8px; color: var(--text-primary); cursor: pointer; font-size: 13px;">
            <input type="checkbox" class="export-col-checkbox" value="${hdr}" checked>
            <span>${displayLabel}</span>
        </label>
    `}).join('');
    
    // Load presets
    window.populateExportPresetsDropdown(type);
    
    openModal('export-config-modal');
};

window.populateExportPresetsDropdown = function(type) {
    const selectPreset = document.getElementById('export-preset-select');
    if (!selectPreset) return;
    
    selectPreset.innerHTML = '<option value="">-- Default Columns (All) --</option>';
    try {
        const presets = JSON.parse(localStorage.getItem('export_presets_' + type) || '{}');
        Object.keys(presets).forEach(name => {
            const opt = document.createElement('option');
            opt.value = name;
            opt.textContent = name;
            selectPreset.appendChild(opt);
        });
    } catch(e) {
        console.error("Failed to load presets:", e);
    }
};

window.saveExportPreset = function() {
    const typeInput = document.getElementById('export-module-type');
    const presetNameInput = document.getElementById('export-preset-name');
    if (!typeInput || !presetNameInput) return;
    
    const type = typeInput.value;
    const name = presetNameInput.value.trim();
    if (!name) {
        showToast('Please enter a preset name', 'error');
        return;
    }
    
    const checkboxes = document.querySelectorAll('.export-col-checkbox');
    const selectedCols = Array.from(checkboxes).filter(cb => cb.checked).map(cb => cb.value);
    
    if (selectedCols.length === 0) {
        showToast('Please select at least one column to export', 'error');
        return;
    }
    
    try {
        const presets = JSON.parse(localStorage.getItem('export_presets_' + type) || '{}');
        presets[name] = selectedCols;
        localStorage.setItem('export_presets_' + type, JSON.stringify(presets));
        
        window.populateExportPresetsDropdown(type);
        document.getElementById('export-preset-select').value = name;
        presetNameInput.value = '';
        showToast(`Preset "${name}" saved successfully!`, 'success');
    } catch(e) {
        console.error("Failed to save preset:", e);
        showToast('Failed to save preset', 'error');
    }
};

window.loadSavedExportPreset = function() {
    const typeInput = document.getElementById('export-module-type');
    const selectPreset = document.getElementById('export-preset-select');
    if (!typeInput || !selectPreset) return;
    
    const type = typeInput.value;
    const presetName = selectPreset.value;
    
    const checkboxes = document.querySelectorAll('.export-col-checkbox');
    if (!presetName) {
        // Reset: check all
        checkboxes.forEach(cb => cb.checked = true);
        return;
    }
    
    try {
        const presets = JSON.parse(localStorage.getItem('export_presets_' + type) || '{}');
        const selectedCols = presets[presetName] || [];
        checkboxes.forEach(cb => {
            cb.checked = selectedCols.includes(cb.value);
        });
    } catch(e) {
        console.error("Failed to load preset:", e);
    }
};

window.triggerCustomExport = function() {
    const typeInput = document.getElementById('export-module-type');
    if (!typeInput) return;
    const type = typeInput.value;
    
    const checkboxes = document.querySelectorAll('.export-col-checkbox');
    const selectedCols = Array.from(checkboxes).filter(cb => cb.checked).map(cb => cb.value);
    
    if (selectedCols.length === 0) {
        showToast('Please select at least one column to export', 'error');
        return;
    }
    
    let originalData = [];
    let filename = `${type}_export.csv`;
    
    if (ExportConfig[type]) {
        originalData = ExportConfig[type].getData();
        filename = ExportConfig[type].filename;
    } else if (window.customMasters && window.customMasters[type]) {
        const list = window.customMasters[type];
        originalData = list.map(item => ({ name: item }));
        filename = `${type}_master.csv`;
    } else {
        showToast('Export data not found', 'error');
        return;
    }
    
    // Export data filtering by selected columns
    exportToCSV(selectedCols, originalData, filename);
    closeModal('export-config-modal');
};

// ==========================================
// MANY-TO-MANY SO AND PLAIN FABRIC GRN LINKING
// ==========================================
let currentSOLinks = []; // Store linked GRN IDs for the open SO form
let currentGRNLinks = []; // Store linked SO IDs for the open GRN form

// Helper: Populate GRNs available to link in the SO Modal
window.populateGRNLinkSelectForSO = function() {
    const custId = document.getElementById('so-customer').value;
    const selectEl = document.getElementById('so-link-grn-select');
    if (!selectEl) return;
    
    selectEl.innerHTML = '<option value="">-- Link a GRN --</option>';
    if (!custId) return;
    
    // Find plain fabric GRNs for this customer that are not already linked
    const plainGrns = (rawDB.grns || []).filter(g => {
        const state = parseGrnWizardState(g);
        const isPlainCustomerFabric = state.type === 'fabric' && state.source === 'customer' && state.subType === 'plain';
        const matchesCustomer = g.customerId === custId;
        const notAlreadyLinked = !currentSOLinks.includes(g.id);
        return isPlainCustomerFabric && matchesCustomer && notAlreadyLinked;
    });

    // Sort GRNs numerically by their trailing document sequence number
    plainGrns.sort((a, b) => {
        const numA = parseInt(String(a.grnNo || a.number || '').split('/').pop()) || 0;
        const numB = parseInt(String(b.grnNo || b.number || '').split('/').pop()) || 0;
        return numA - numB;
    });
    
    plainGrns.forEach(g => {
        const opt = document.createElement('option');
        opt.value = g.id;
        opt.textContent = `${g.grnNo || g.number} (Qty: ${g.qty}, Doc: ${g.partyDocNo || '-'})`;
        selectEl.appendChild(opt);
    });
    reinitSearchableSelect(selectEl);
};

// Helper: Populate SOs available to link in the GRN Modal
window.populateSOLinkSelectForGRN = function() {
    const custId = document.getElementById('grn-customer').value;
    const selectEl = document.getElementById('grn-link-so-select');
    if (!selectEl) return;
    
    selectEl.innerHTML = '<option value="">-- Link a Sales Order --</option>';
    if (!custId) {
        reinitSearchableSelect(selectEl);
        return;
    }
    
    // Find Sales Orders for this customer that are not already linked
    const allSOs = [...(db.salesOrders || []), ...(rawDB.salesOrders || [])];
    const uniqueMap = new Map();
    allSOs.forEach(s => { if (s && s.id) uniqueMap.set(String(s.id), s); });

    const openSOs = Array.from(uniqueMap.values()).filter(so => {
        const matchesCustomer = String(so.customerId || so.customer_id || '') === String(custId);
        const notAlreadyLinked = !currentGRNLinks.includes(so.id);
        const notCancelled = (so.status || '').toLowerCase() !== 'cancelled';
        return matchesCustomer && notAlreadyLinked && notCancelled;
    });

    // Sort Sales Orders numerically by their trailing document sequence number
    openSOs.sort((a, b) => {
        const numA = parseInt(String(a.number || '').split('/').pop()) || 0;
        const numB = parseInt(String(b.number || '').split('/').pop()) || 0;
        return numA - numB;
    });
    
    openSOs.forEach(so => {
        const opt = document.createElement('option');
        opt.value = so.id;
        opt.textContent = `${so.number} (Item: ${window.getSoDesignOrItemDisplay(so)}, Qty: ${so.qty})`;
        selectEl.appendChild(opt);
    });
    reinitSearchableSelect(selectEl);
};

// Render linked GRN rows on the SO form
window.renderSOFormGRNLinks = function() {
    const tbody = document.getElementById('so-linked-grns-table-body');
    const partyDocsInput = document.getElementById('so-linked-party-docs');
    if (!tbody) return;
    
    tbody.innerHTML = '';
    const docs = [];
    
    if (currentSOLinks.length === 0) {
        tbody.innerHTML = `<tr><td colspan="4" class="empty-row" style="text-align:center; padding:8px; color:var(--text-muted);">No linked GRNs.</td></tr>`;
        if (partyDocsInput) partyDocsInput.value = '';
        return;
    }
    
    const activeSoId = document.getElementById('so-edit-id') ? document.getElementById('so-edit-id').value : '';
    
    currentSOLinks.forEach(grnId => {
        let name = '';
        let partyDoc = '-';
        let grnQty = '-';
        let grnAllotted = '-';
        if (typeof grnId === 'string' && grnId.startsWith('manual:')) {
            name = grnId.substring(7);
        } else {
            const grnObj = (rawDB.grns || []).find(g => g.id === grnId);
            if (grnObj) {
                name = grnObj.grnNo || grnObj.number || 'GRN';
                partyDoc = grnObj.partyDocNo || '-';
                grnQty = grnObj.qty !== undefined ? grnObj.qty : '-';
                
                const activeSo = (rawDB.salesOrders || []).find(s => s.id === activeSoId);
                const activeSoNo = activeSo ? activeSo.number : '';
                
                let allotted = 0;
                if (grnObj.soAllottedQtys) {
                    if (activeSoId && grnObj.soAllottedQtys[activeSoId] !== undefined) {
                        allotted = grnObj.soAllottedQtys[activeSoId];
                    } else if (activeSoNo && grnObj.soAllottedQtys[activeSoNo] !== undefined) {
                        allotted = grnObj.soAllottedQtys[activeSoNo];
                    } else if (activeSoNo && grnObj.soAllottedQtys['manual:' + activeSoNo] !== undefined) {
                        allotted = grnObj.soAllottedQtys['manual:' + activeSoNo];
                    } else {
                        // Fuzzy lookup
                        const keys = Object.keys(grnObj.soAllottedQtys);
                        for (let key of keys) {
                            const cleanKey = key.replace('manual:', '').trim().toLowerCase();
                            if (activeSoId && cleanKey === String(activeSoId).toLowerCase()) {
                                allotted = grnObj.soAllottedQtys[key];
                                break;
                            }
                            if (activeSoNo && cleanKey === String(activeSoNo).trim().toLowerCase()) {
                                allotted = grnObj.soAllottedQtys[key];
                                break;
                            }
                        }
                    }
                }
                
                if (!allotted || allotted === 0) {
                    allotted = grnObj.qty || 0;
                }
                
                grnAllotted = `<span style="background-color: var(--bg-card, #eef2f6); color: var(--text-primary, #1e293b); padding: 3px 10px; border-radius: 12px; font-weight: 600; border: 1px solid var(--border, #cbd5e1); display: inline-block;">${allotted}</span>`;
                
                if (grnObj.partyDocNo) {
                    docs.push(grnObj.partyDocNo);
                }
            }
        }
        if (!name) return;
        
        let onclickAttr = `openGRNModal('${grnId}')`;
        if (typeof grnId === 'string' && grnId.startsWith('manual:')) {
            const cleanNum = grnId.substring(7).trim().toLowerCase();
            const found = (rawDB.grns || []).find(g => (g.grnNo || g.number || '').trim().toLowerCase() === cleanNum);
            if (found) {
                onclickAttr = `openGRNModal('${found.id}')`;
                
                const activeSo = (rawDB.salesOrders || []).find(s => s.id === activeSoId);
                const activeSoNo = activeSo ? activeSo.number : '';
                
                let allotted = 0;
                if (found.soAllottedQtys) {
                    if (activeSoId && found.soAllottedQtys[activeSoId] !== undefined) {
                        allotted = found.soAllottedQtys[activeSoId];
                    } else if (activeSoNo && found.soAllottedQtys[activeSoNo] !== undefined) {
                        allotted = found.soAllottedQtys[activeSoNo];
                    } else if (activeSoNo && found.soAllottedQtys['manual:' + activeSoNo] !== undefined) {
                        allotted = found.soAllottedQtys['manual:' + activeSoNo];
                    } else {
                        // Fuzzy lookup
                        const keys = Object.keys(found.soAllottedQtys);
                        for (let key of keys) {
                            const cleanKey = key.replace('manual:', '').trim().toLowerCase();
                            if (activeSoId && cleanKey === String(activeSoId).toLowerCase()) {
                                allotted = found.soAllottedQtys[key];
                                break;
                            }
                            if (activeSoNo && cleanKey === String(activeSoNo).trim().toLowerCase()) {
                                allotted = found.soAllottedQtys[key];
                                break;
                            }
                        }
                    }
                }

                if (!allotted || allotted === 0) {
                    allotted = found.qty || 0;
                }

                grnAllotted = `<span style="background-color: var(--bg-card, #eef2f6); color: var(--text-primary, #1e293b); padding: 3px 10px; border-radius: 12px; font-weight: 600; border: 1px solid var(--border, #cbd5e1); display: inline-block;">${allotted}</span>`;

                if (found.partyDocNo) {
                    docs.push(found.partyDocNo);
                }
            } else {
                onclickAttr = `window.showSmartAlert('Not Found', 'GRN not found in database')`;
            }
        }
        
        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td><strong><a href="#" onclick="event.preventDefault(); ${onclickAttr}" style="color: var(--accent-blue, #3b82f6); text-decoration: underline;">${name}</a></strong></td>
            <td>${partyDoc}</td>
            <td>${grnQty}</td>
            <td>${grnAllotted}</td>
        `;
        tbody.appendChild(tr);
    });
    
    if (partyDocsInput) {
        partyDocsInput.value = docs.length > 0 ? docs.join(', ') : '';
    }
};

// Render linked SO rows on the GRN form
// Render linked SO rows on the GRN form
window.renderGRNFormSOLinks = function() {
    const tbody = document.getElementById('grn-linked-sos-table-body');
    if (!tbody) return;
    
    tbody.innerHTML = '';
    
    if (currentGRNLinks.length === 0) {
        tbody.innerHTML = `<tr><td colspan="5" class="empty-row" style="text-align:center; padding:8px; color:var(--text-muted);">No linked Sales Orders.</td></tr>`;
        const isPlainFabricCustomer = (grnWizardState.type === 'fabric' && grnWizardState.source === 'customer' && grnWizardState.subType === 'plain');
        if (isPlainFabricCustomer) {
            const custOrderNoInput = document.getElementById('grn-cust-order-no');
            if (custOrderNoInput) custOrderNoInput.value = '';
        }
        return;
    }
    
    const custOrderNos = [];
    if (!window.currentGRNAllottedQtys) {
        window.currentGRNAllottedQtys = {};
    }
    if (!window.userManuallySetAllottedQty) {
        window.userManuallySetAllottedQty = {};
    }
    
    const grnTotalQty = parseFloat(document.getElementById('grn-qty')?.value) || 0;
    
    currentGRNLinks.forEach(soId => {
        let name = '';
        let designNumber = '-';
        let qty = '-';
        let allottedQty = 0;
        
        const currentGrnId = document.getElementById('grn-edit-id')?.value || '';
        const targetSoId = (typeof soId === 'string' && soId.startsWith('manual:')) ? '' : soId;
        
        if (currentGrnId && targetSoId) {
            (db.outwards || []).forEach(o => {
                if (o.status === 'Cancelled') return;
                const isThisSO = (o.soRefId === targetSoId || o.soRef === targetSoId || (o.soLinks && o.soLinks.includes(targetSoId)));
                if (!isThisSO) return;
                
                if (o.grnLinks && Array.isArray(o.grnLinks)) {
                    o.grnLinks.forEach(link => {
                        if (link.grnRefId === currentGrnId) {
                            allottedQty += (parseFloat(link.qty) || 0);
                        }
                    });
                } else if (o.grnRefId === currentGrnId) {
                    allottedQty += (parseFloat(o.qty) || 0);
                }
            });
        }
        
        if (typeof soId === 'string' && soId.startsWith('manual:')) {
            const rawName = soId.substring(7);
            const cleanMatch = rawName.match(/^([^\s(]+)/);
            name = cleanMatch ? cleanMatch[1] : rawName;
            
            const itemMatch = rawName.match(/Item:\s*([^,)]+)/i);
            if (itemMatch) designNumber = itemMatch[1];
            
            const qtyMatch = rawName.match(/Qty:\s*([0-9.]+)/i);
            if (qtyMatch) qty = qtyMatch[1];
        } else {
            const soObj = (db.salesOrders || []).find(s => s.id === soId);
            if (soObj) {
                name = soObj.number || 'SO';
                designNumber = window.getSoDesignOrItemDisplay(soObj);
                qty = soObj.items && soObj.items.length > 0 ? soObj.items.reduce((s, it) => s + (it.qty || 0), 0) : (soObj.qty || 0);
                if (soObj.partyOrderNo) {
                    custOrderNos.push(soObj.partyOrderNo);
                }
            }
        }
        if (!name) return;
        
        let displayAllotted = window.currentGRNAllottedQtys[soId];
        const isManuallySet = window.userManuallySetAllottedQty[soId];
        
        let soQtyVal = parseFloat(qty) || 0;
        if (!isManuallySet || displayAllotted === undefined) {
            displayAllotted = allottedQty || (grnTotalQty ? Math.min(grnTotalQty, soQtyVal) : soQtyVal);
            window.currentGRNAllottedQtys[soId] = displayAllotted;
        }
        
        const tr = document.createElement('tr');
        tr.innerHTML = `
            <td><strong>${name}</strong></td>
            <td>${designNumber}</td>
            <td>${qty}</td>
            <td>
                <input type="number" step="any" class="form-input" style="width:100px; padding:3px 6px; font-size:11px; margin:0;" value="${displayAllotted}" onchange="window.updateGRNSOAllottedQty('${soId}', this.value)">
            </td>
            <td style="text-align: right;"><button type="button" class="btn btn-sm btn-outline-danger" style="font-size:11px; padding:3px 8px; cursor:pointer;" onclick="window.removeGRNToSOLink('${soId}')">Delink</button></td>
        `;
        tbody.appendChild(tr);
    });
    
    const isPlainFabricCustomer = (grnWizardState.type === 'fabric' && grnWizardState.source === 'customer' && grnWizardState.subType === 'plain');
    if (isPlainFabricCustomer) {
        const uniqueCustOrderNos = [...new Set(custOrderNos.map(no => String(no).trim()).filter(Boolean))];
        const custOrderNoInput = document.getElementById('grn-cust-order-no');
        if (custOrderNoInput) {
            custOrderNoInput.value = uniqueCustOrderNos.join(', ');
        }
    }
    if (typeof window.updateGrnCustPfLayout === 'function') {
        window.updateGrnCustPfLayout();
    }
};

window.updateGRNSOAllottedQty = function(soId, value) {
    if (!window.currentGRNAllottedQtys) {
        window.currentGRNAllottedQtys = {};
    }
    if (!window.userManuallySetAllottedQty) {
        window.userManuallySetAllottedQty = {};
    }
    const valNum = parseFloat(value) || 0;
    window.currentGRNAllottedQtys[soId] = valNum;
    window.userManuallySetAllottedQty[soId] = true;
};

// Event: Add Link in SO Form
window.addSOToGRNLink = function() {
    const selectEl = document.getElementById('so-link-grn-select');
    const manualInput = document.getElementById('so-link-grn-manual-input');
    let grnId = selectEl ? selectEl.value : '';
    
    if (!grnId && manualInput && manualInput.value.trim()) {
        const val = manualInput.value.trim();
        const found = (db.grns || []).find(g => (g.grnNo || g.number || '').toLowerCase() === val.toLowerCase());
        if (found) {
            grnId = found.id;
        } else {
            grnId = 'manual:' + val;
        }
        manualInput.value = '';
    }
    
    if (grnId && !currentSOLinks.includes(grnId)) {
        currentSOLinks.push(grnId);
        window.renderSOFormGRNLinks();
        window.populateGRNLinkSelectForSO();
    }
};

// Event: Remove Link in SO Form
window.removeSOToGRNLink = function(grnId) {
    currentSOLinks = currentSOLinks.filter(id => id !== grnId);
    window.renderSOFormGRNLinks();
    window.populateGRNLinkSelectForSO();
};

// Event: Add Link in GRN Form
window.addGRNToSOLink = function() {
    const selectEl = document.getElementById('grn-link-so-select');
    const manualInput = document.getElementById('grn-link-so-manual-input');
    let soId = selectEl ? selectEl.value : '';
    
    if (!soId && manualInput && manualInput.value.trim()) {
        let val = manualInput.value.trim();
        const cleanMatch = val.match(/^([^\s(]+)/);
        if (cleanMatch) {
            val = cleanMatch[1];
        }
        const found = (db.salesOrders || []).find(s => (s.number || '').toLowerCase() === val.toLowerCase());
        if (found) {
            const custId = document.getElementById('grn-customer').value;
            if (found.customerId !== custId) {
                showToast(`Sales Order ${found.number} belongs to a different customer!`, 'error');
                manualInput.value = '';
                return;
            }
            soId = found.id;
        } else {
            soId = 'manual:' + val;
        }
        manualInput.value = '';
    }
    
    if (soId && !currentGRNLinks.includes(soId)) {
        currentGRNLinks.push(soId);
        window.renderGRNFormSOLinks();
        window.populateSOLinkSelectForGRN();
        if (typeof window.updateGrnEmbroideryItemSelects === 'function') {
            window.updateGrnEmbroideryItemSelects();
        }
    }
};

// Event: Remove Link in GRN Form
window.removeGRNToSOLink = function(soId) {
    currentGRNLinks = currentGRNLinks.filter(id => id !== soId);
    if (window.currentGRNAllottedQtys && window.currentGRNAllottedQtys[soId]) {
        delete window.currentGRNAllottedQtys[soId];
    }
    window.renderGRNFormSOLinks();
    window.populateSOLinkSelectForGRN();
    if (typeof window.updateGrnEmbroideryItemSelects === 'function') {
        window.updateGrnEmbroideryItemSelects();
    }
};

// Bidirectional linking sync helper: When SO is saved, sync linked GRNs
window.syncSOLinksWithGRNs = async function(soId, linkedGrnIds, soNumber) {
    for (let grn of (rawDB.grns || [])) {
        const grnNo = grn.grnNo || grn.number || '';
        const isLinkedNow = linkedGrnIds.includes(grn.id) || 
                            (grnNo && linkedGrnIds.includes('manual:' + grnNo));
        grn.soLinks = grn.soLinks || [];
        const isLinkedBefore = grn.soLinks.includes(soId) || 
                               (soNumber && grn.soLinks.includes('manual:' + soNumber));
        
        if (isLinkedNow && !isLinkedBefore) {
            grn.soLinks = grn.soLinks.filter(id => id !== soId && id !== 'manual:' + soNumber);
            grn.soLinks.push(soId);
            await saveToSupabase('grns', grn);
        } else if (!isLinkedNow && isLinkedBefore) {
            grn.soLinks = grn.soLinks.filter(id => id !== soId && id !== 'manual:' + soNumber);
            await saveToSupabase('grns', grn);
        }
    }
};

// Bidirectional linking sync helper: When GRN is saved, sync linked SOs
/* 
  ========================================================================
  CRITICAL CORE LOGIC - DO NOT MODIFY OR OVERWRITE THIS FUNCTION
  This handles the bidirectional unlinking/linking between GRNs and SOs.
  Modifying this will break the sales order/challan linkages.
  ========================================================================
*/
window.syncGRNLinksWithSOs = async function(grnId, linkedSoIds, grnNumber) {
    console.log("syncGRNLinksWithSOs starting. grnId:", grnId, "linkedSoIds:", linkedSoIds, "grnNumber:", grnNumber);
    for (let so of (rawDB.salesOrders || [])) {
        const isLinkedNow = linkedSoIds.includes(so.id) || 
                             (so.number && linkedSoIds.includes('manual:' + so.number));
        so.grnLinks = so.grnLinks || [];
        const isLinkedBefore = so.grnLinks.includes(grnId) || 
                               (grnNumber && so.grnLinks.includes('manual:' + grnNumber));
        
        if (isLinkedNow || isLinkedBefore) {
            console.log("Checking SO " + so.number + ": isLinkedNow=" + isLinkedNow + ", isLinkedBefore=" + isLinkedBefore + ", current grnLinks=", so.grnLinks);
        }

        if (isLinkedNow && !isLinkedBefore) {
            so.grnLinks = so.grnLinks.filter(id => id !== grnId && id !== 'manual:' + grnNumber);
            so.grnLinks.push(grnId);
            console.log("Linking SO " + so.number + " to GRN. Saving new grnLinks:", so.grnLinks);
            await saveToSupabase('sales_orders', so);
        } else if (!isLinkedNow && isLinkedBefore) {
            so.grnLinks = so.grnLinks.filter(id => id !== grnId && id !== 'manual:' + grnNumber);
            console.log("Unlinking SO " + so.number + " from GRN. Saving new grnLinks:", so.grnLinks);
            await saveToSupabase('sales_orders', so);
        }
    }
};

// Prompt: Link SO to existing Plain Fabric GRN on Save
window.promptSOLinkToGRN = function(soData, editId) {
    const custId = soData.customerId;
    const plainGrns = (db.grns || []).filter(g => {
        const state = parseGrnWizardState(g);
        return g.customerId === custId && state.type === 'fabric' && state.source === 'customer' && state.subType === 'plain';
    });
    
    // Show new GRN button
    const newGrnBtn = document.getElementById('btn-link-prompt-new-grn');
    if (newGrnBtn) {
        newGrnBtn.style.display = 'inline-block';
        newGrnBtn.onclick = async function() {
            closeModal('link-prompt-modal');
            await window.executeSaveSO(soData, editId);
            // Open GRN modal from SO
            openGRNModalFromSO(soData, 'plain');
        };
    }
    
    document.getElementById('link-prompt-title').textContent = 'Link to Plain Fabric GRN(s)';
    document.getElementById('link-prompt-text').textContent = `Select Plain Fabric GRN(s) for ${soData.customerName || 'customer'} to link with this Sales Order:`;
    
    const listEl = document.getElementById('link-prompt-list');
    listEl.innerHTML = '';
    
    if (plainGrns.length === 0) {
        listEl.innerHTML = `<div style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 13px;">No existing Plain Fabric GRNs found for this customer. Click "+ New GRN/C/PF" to create one.</div>`;
    } else {
        plainGrns.forEach(g => {
            const row = document.createElement('label');
            row.style.display = 'flex';
            row.style.alignItems = 'center';
            row.style.gap = '8px';
            row.style.cursor = 'pointer';
            row.style.fontSize = '13px';
            row.style.color = 'var(--text-primary)';
            row.innerHTML = `
                <input type="checkbox" class="link-prompt-cb" value="${g.id}">
                <span>${g.grnNo || g.number || 'GRN'} (Qty: ${g.qty}, Doc: ${g.partyDocNo || '-'})</span>
            `;
            listEl.appendChild(row);
        });
    }
    
    openModal('link-prompt-modal');
    
    document.getElementById('btn-link-prompt-skip').onclick = function() {
        closeModal('link-prompt-modal');
        window.executeSaveSO(soData, editId);
    };
    
    document.getElementById('btn-link-prompt-submit').onclick = function() {
        const cbs = document.querySelectorAll('.link-prompt-cb');
        const selectedIds = Array.from(cbs).filter(cb => cb.checked).map(cb => cb.value);
        currentSOLinks = selectedIds;
        soData.grnLinks = currentSOLinks;
        closeModal('link-prompt-modal');
        window.executeSaveSO(soData, editId);
    };
};

// Prompt: Link GRN to existing Sales Order on Save
/* 
  ========================================================================
  CRITICAL CORE LOGIC - DO NOT MODIFY OR OVERWRITE THIS FUNCTION
  This prompts the user to select SOs to link or clear on GRN save.
  ========================================================================
*/
window.promptGRNLinkToSO = function(grnData, editId) {
    const custId = grnData.customerId;
    const openSos = (db.salesOrders || []).filter(so => so.customerId === custId);
    
    // Hide new GRN button for GRN saving prompt
    const newGrnBtn = document.getElementById('btn-link-prompt-new-grn');
    if (newGrnBtn) newGrnBtn.style.display = 'none';
    
    if (openSos.length === 0) {
        window.executeSaveGRN(grnData, editId);
        return;
    }
    
    document.getElementById('link-prompt-title').textContent = 'Link to Sales Order(s)';
    document.getElementById('link-prompt-text').textContent = `Select Sales Order(s) for ${grnData.customerName || 'customer'} to link with this GRN:`;
    
    const listEl = document.getElementById('link-prompt-list');
    listEl.innerHTML = '';
    
    openSos.forEach(so => {
        const row = document.createElement('label');
        row.style.display = 'flex';
        row.style.alignItems = 'center';
        row.style.gap = '8px';
        row.style.cursor = 'pointer';
        row.style.fontSize = '13px';
        row.style.color = 'var(--text-primary)';
        row.innerHTML = `
            <input type="checkbox" class="link-prompt-cb" value="${so.id}">
            <span>${so.number} (Item: ${window.getSoDesignOrItemDisplay(so)}, Qty: ${so.qty})</span>
        `;
        listEl.appendChild(row);
    });
    
    openModal('link-prompt-modal');
    
    document.getElementById('btn-link-prompt-skip').onclick = function() {
        grnData.soLinks = [];
        grnData.soRefId = '';
        grnData.soAllottedQtys = {};
        currentGRNLinks = [];
        closeModal('link-prompt-modal');
        window.executeSaveGRN(grnData, editId);
    };
    
    document.getElementById('btn-link-prompt-submit').onclick = function() {
        const cbs = document.querySelectorAll('.link-prompt-cb');
        const selectedIds = Array.from(cbs).filter(cb => cb.checked).map(cb => cb.value);
        currentGRNLinks = selectedIds;
        grnData.soLinks = currentGRNLinks;
        grnData.soRefId = currentGRNLinks[0] || '';
        grnData.soAllottedQtys = {};
        selectedIds.forEach(id => {
            grnData.soAllottedQtys[id] = 0;
        });
        closeModal('link-prompt-modal');
        window.executeSaveGRN(grnData, editId);
    };
};

// Bind Customer select change events to update dropdown lists
document.addEventListener('DOMContentLoaded', () => {
    const soCust = document.getElementById('so-customer');
    if (soCust) {
        soCust.addEventListener('change', () => {
            currentSOLinks = [];
            window.renderSOFormGRNLinks();
            window.populateGRNLinkSelectForSO();
        });
    }
    
    const grnCust = document.getElementById('grn-customer');
    if (grnCust) {
        grnCust.addEventListener('change', () => {
            currentGRNLinks = [];
            window.renderGRNFormSOLinks();
            window.populateSOLinkSelectForGRN();
            window.updateGrnFabricIssues();
        });
    }
    const grnSoRef = document.getElementById('grn-so-ref');
    if (grnSoRef) {
        grnSoRef.addEventListener('change', () => {
            window.updateGrnFabricIssues();
        });
    }
});

