async function poBulkDelete() {
    const checkboxes = document.querySelectorAll('.chk-select-po');
    const idsToDelete = Array.from(checkboxes).filter(cb => cb.checked).map(cb => cb.value);
    
    if (idsToDelete.length === 0) {
        showToast('No Purchase Orders selected.', 'info');
        return;
    }

    // Verify each selected PO for active references
    const blockedPos = [];
    for (const poId of idsToDelete) {
        const po = (rawDB.pos || []).find(p => p.id === poId);
        if (!po) continue;

        const poNumUpper = (po.number || '').toUpperCase();
        const isPoInhouse = po.poType === 'inhouse' || po.po_type === 'inhouse' || poNumUpper.startsWith('PO/INH');

        if (isPoInhouse) {
            const linkedOutwards = (rawDB.outwards || []).filter(o => {
                if (o.remarks && o.remarks.includes('Cancelled')) return false;
                return o.poRefId === po.id || o.poRefId === po.number || o.linked_po_id === po.id || o.linked_po_number === po.number;
            });

            const linkedSlips = (rawDB.productionSlips || []).filter(s => {
                if (s.status === 'Cancelled') return false;
                const matchesId = s.poId === po.id || s.inhousePoId === po.id;
                const matchesNo = (s.poNumber && s.poNumber.toUpperCase() === po.number.toUpperCase()) ||
                                  (s.inhousePoNumber && s.inhousePoNumber.toUpperCase() === po.number.toUpperCase()) ||
                                  (s.poNo && s.poNo.toUpperCase() === po.number.toUpperCase());
                return matchesId || matchesNo;
            });

            if (linkedOutwards.length > 0 || linkedSlips.length > 0) {
                blockedPos.push({
                    number: po.number,
                    outwards: linkedOutwards.map(o => o.number),
                    slips: linkedSlips.map(s => s.number)
                });
            }
        } else {
            const linkedOutwards = (rawDB.outwards || []).filter(o => {
                if (o.remarks && o.remarks.includes('Cancelled')) return false;
                return o.poRefId === po.id || o.poRefId === po.number || o.linked_po_id === po.id || o.linked_po_number === po.number;
            });

            if (linkedOutwards.length > 0) {
                blockedPos.push({
                    number: po.number,
                    outwards: linkedOutwards.map(o => o.number),
                    slips: []
                });
            }
        }
    }

    if (blockedPos.length > 0) {
        let msg = "The following Purchase Order(s) cannot be deleted because they are referenced in other documents:";
        blockedPos.forEach(item => {
            msg += `<br><br><strong>${item.number}</strong>:`;
            if (item.outwards.length > 0) {
                msg += `<br> - Fabric Issues: ` + item.outwards.join(', ');
            }
            if (item.slips.length > 0) {
                msg += `<br> - Production Slips: ` + item.slips.join(', ');
            }
        });
        window.showSmartAlert('Referenced Documents', msg);
        return;
    }
    
    if (!(await window.showSmartConfirm('Bulk Delete', `Are you sure you want to delete the ${idsToDelete.length} selected Purchase Orders? This action cannot be undone.`))) {
        return;
    }
    
    showImportLoadingOverlay();
    try {
        await deleteMultipleFromSupabase('purchase_orders', idsToDelete);
        
        // Remove locally
        db.pos = db.pos.filter(x => !idsToDelete.includes(x.id));
        
        if (typeof renderPOTable === 'function') if (typeof window.renderPOTable === 'function') window.renderPOTable();
        
        // Uncheck header checkbox
        const headerChk = document.getElementById('po-select-all');
        if (headerChk) headerChk.checked = false;
        
        toggleBulkDeleteButton('po');
        showToast(`Successfully deleted ${idsToDelete.length} Purchase Orders.`, 'success');
    } catch (err) {
        console.error("Bulk delete failed:", err);
    } finally {
        hideImportLoadingOverlay();
    }
}
window.poBulkDelete = poBulkDelete;

