async function outwardBulkDelete() {
    const checkboxes = document.querySelectorAll('.chk-select-outward');
    const idsToDelete = Array.from(checkboxes).filter(cb => cb.checked).map(cb => cb.value);
    if (idsToDelete.length === 0) { showToast('No Outwards selected.', 'info'); return; }
    if (!(await window.showSmartConfirm('Bulk Delete', `Are you sure you want to delete the ${idsToDelete.length} selected Outwards? This action cannot be undone.`))) return;
    showImportLoadingOverlay();
    try {
        const affectedPoIds = new Set();
        for (let id of idsToDelete) {
            const out = db.outwards.find(o => o.id === id);
            if (out) {
                const grn = db.grns.find(g => g.id === out.grnRefId);
                if (grn) {
                    grn.issuedMeters = Math.max(0, (grn.issuedMeters || 0) - out.qty);
                    await saveToSupabase('grns', grn);
                }
                if (out.poRefId) affectedPoIds.add(out.poRefId);
            }
        }
        await deleteMultipleFromSupabase('outwards', idsToDelete);
        rawDB.outwards = rawDB.outwards.filter(o => !idsToDelete.includes(o.id));
        applyFinancialYearFilters();
        
        // Update affected POs with recalculated challan list
        for (let poId of affectedPoIds) {
            const po = db.pos.find(p => p.id === poId);
            if (po && ((po.poType || 'vendor') === 'vendor' || po.poType === 'inhouse')) {
                const mpo = { ...po };
                const otherOutwards = db.outwards.filter(o => o.poRefId === poId);
                const uniqueChallans = [...new Set(otherOutwards.map(o => o.number))].filter(Boolean).join(', ');
                mpo.vendorJobWorkChallanNo = uniqueChallans;
                await saveToSupabase('purchase_orders', mpo);
                const idx = rawDB.pos.findIndex(p => p.id === poId);
                if (idx !== -1) rawDB.pos[idx] = mpo;
            }
        }
        
        renderOutwardTable();
        const headerChk = document.getElementById('outward-select-all');
        if (headerChk) headerChk.checked = false;
        toggleBulkDeleteButton('outward');
        showToast(`Successfully deleted ${idsToDelete.length} Outward Challans.`, 'success');
    } catch (err) {
        console.error("Bulk delete failed:", err);
    } finally {
        hideImportLoadingOverlay();
    }
}
window.outwardBulkDelete = outwardBulkDelete;

