async function soBulkCancel() {
    const checkboxes = document.querySelectorAll('.chk-select-so');
    const idsToCancel = Array.from(checkboxes).filter(cb => cb.checked).map(cb => cb.value);
    if (idsToCancel.length === 0) { showToast('No Sales Orders selected.', 'info'); return; }
    if (!(await window.showSmartConfirm(
        '� WARNING: Cancel Selected Sales Orders',
        `� <strong>WARNING:</strong> Are you sure you want to <strong>CANCEL</strong> the ${idsToCancel.length} selected Sales Order(s)?<br><br><span style="color:#f59e0b;">This will mark them as Cancelled.</span>`,
        'Yes, Cancel Sales Orders',
        'No, Keep Sales Orders'
    ))) return;

    showImportLoadingOverlay();
    try {
        let count = 0;
        for (const id of idsToCancel) {
            const existing = (db.salesOrders || []).find(x => String(x.id) === String(id));
            if (!existing) continue;
            existing.status = 'Cancelled';
            existing.remarks = 'Cancelled (Voucher Cancelled)';
            await saveToSupabase('sales_orders', existing);
            if (typeof window.syncSOLinksWithGRNs === 'function') {
                await window.syncSOLinksWithGRNs(existing.id, [], existing.number);
            }
            count++;
        }
        if (typeof renderSOTable === 'function') renderSOTable();
        if (typeof renderSalesOrderTable === 'function') renderSalesOrderTable();
        const headerChk = document.getElementById('so-select-all');
        if (headerChk) headerChk.checked = false;
        toggleBulkDeleteButton('so');
        showToast(`Successfully cancelled ${count} Sales Order(s).`, 'success');
    } catch (err) {
        console.error("Bulk cancel failed:", err);
        showToast("Failed to cancel selected Sales Orders: " + (err.message || err), 'error');
    } finally {
        hideImportLoadingOverlay();
    }
}
window.soBulkCancel = soBulkCancel;

