async function genericTxBulkCancel(scope, typeName, dbKey, table, renderFn, headerChkId) {
    const checkboxes = document.querySelectorAll(`.chk-select-${scope}`);
    const idsToCancel = Array.from(checkboxes).filter(cb => cb.checked).map(cb => cb.value);
    if (idsToCancel.length === 0) { showToast(`No ${typeName} selected.`, 'info'); return; }
    if (!(await window.showSmartConfirm(
        `� WARNING: Cancel Selected ${typeName}`,
        `� <strong>WARNING:</strong> Are you sure you want to <strong>CANCEL</strong> the ${idsToCancel.length} selected ${typeName}?`,
        `Yes, Cancel ${typeName}`,
        'No, Keep Them'
    ))) return;

    showImportLoadingOverlay();
    try {
        let count = 0;
        const list = db[dbKey] || db.genericTransactions || [];
        for (const id of idsToCancel) {
            const existing = list.find(x => String(x.id) === String(id));
            if (!existing) continue;
            existing.status = 'Cancelled';
            existing.remarks = 'Cancelled (Voucher Cancelled)';
            await saveToSupabase(table, existing);
            count++;
        }
        if (typeof renderFn === 'function') renderFn();
        if (headerChkId) {
            const headerChk = document.getElementById(headerChkId);
            if (headerChk) headerChk.checked = false;
        }
        toggleBulkDeleteButton(scope);
        showToast(`Successfully cancelled ${count} ${typeName}.`, 'success');
    } catch (err) {
        console.error("Bulk cancel failed:", err);
        showToast(`Failed to cancel selected ${typeName}: ` + (err.message || err), 'error');
    } finally {
        hideImportLoadingOverlay();
    }
}

