window.cancelVoucher = async function(type) {
    let inputId = '';
    let dbKey = '';
    let editIdField = '';
    let modalId = '';
    
    if (type === 'so') {
        inputId = 'so-number';
        dbKey = 'salesOrders';
        editIdField = 'so-edit-id';
        modalId = 'so-modal';
    } else if (type === 'po') {
        inputId = 'po-number';
        dbKey = 'pos';
        editIdField = 'po-edit-id';
        modalId = 'po-modal';
    } else if (type === 'grn') {
        inputId = 'grn-number';
        dbKey = 'grns';
        editIdField = 'grn-edit-id';
        modalId = 'grn-modal';
    } else if (type === 'outward') {
        inputId = 'outward-number';
        dbKey = 'outwards';
        editIdField = 'outward-edit-id';
        modalId = 'outward-modal';
    } else if (type === 'pur') {
        inputId = 'pur-number';
        dbKey = 'purchases';
        editIdField = 'pur-edit-id';
        modalId = 'pur-modal';
    } else if (type === 'req') {
        inputId = 'req-number';
        dbKey = 'requisitionSlips';
        editIdField = 'req-edit-id';
        modalId = 'requisition-modal';
    } else if (type === 'production' || type === 'sampling') {
        inputId = 'prod-number';
        dbKey = 'productionSlips';
        editIdField = 'prod-edit-id';
        modalId = 'production-modal';
    } else if (['invoice', 'voucher', 'salesreturn', 'purchasereturn', 'receipt', 'payment', 'journal', 'contra'].includes(type)) {
        inputId = 'gtx-number';
        dbKey = 'genericTransactions';
        editIdField = 'gtx-edit-id';
        modalId = 'generic-tx-modal';
    } else {
        return;
    }
    
    const docNo = document.getElementById(inputId).value.trim();
    if (!docNo) {
        showToast('Document number is empty. Cannot cancel.', 'error');
        return;
    }
    
    if (!(await window.showSmartConfirm('Cancel Voucher', `Are you sure you want to CANCEL voucher ${docNo}? This will consume the document number.`))) {
        return;
    }
    
    const editId = document.getElementById(editIdField)?.value || '';
    let existing = null;
    
    const listToSearch = ['invoice', 'voucher', 'salesreturn', 'purchasereturn', 'receipt', 'payment', 'journal', 'contra'].includes(type)
        ? [...getGenericTxList(type), ...(db.genericTransactions || []), ...(rawDB?.genericTransactions || [])]
        : (db[dbKey] || []);

    if (editId) {
        existing = listToSearch.find(x => String(x.id) === String(editId));
    } else {
        existing = listToSearch.find(x => (x.number || x.grnNo || x.requisitionNo || x.invoiceNo || '') === docNo);
    }
    
    const permModule = getRecordPermissionModule(existing || { number: docNo, grnNo: docNo });
    if (permModule && typeof checkPermission === 'function') {
        if (!checkPermission(permModule, 'write')) {
            showToast("Permission Denied: You do not have permission to cancel this document.", "error");
            return;
        }
    }
    
    let targetId = editId || existing?.id || uid();
    
    let dateInputId = '';
    if (type === 'so') dateInputId = 'so-date';
    else if (type === 'po') dateInputId = 'po-date';
    else if (type === 'grn') dateInputId = 'grn-date';
    else if (type === 'outward') dateInputId = 'outward-date';
    else if (type === 'pur') dateInputId = 'pur-date';
    else if (type === 'req') dateInputId = 'req-date';
    else if (type === 'production' || type === 'sampling') dateInputId = 'prod-date';
    else if (['invoice', 'voucher', 'salesreturn', 'purchasereturn', 'receipt', 'payment', 'journal', 'contra'].includes(type)) dateInputId = 'gtx-date';

    const modalDateVal = dateInputId ? (document.getElementById(dateInputId)?.value || '') : '';
    const recordDate = modalDateVal || existing?.date || today();

    let cancelledRemarks = 'Cancelled (Voucher Cancelled)';

    let record = {
        id: targetId,
        company_id: currentCompany.id,
        number: docNo,
        date: recordDate,
        status: 'Cancelled',
        remarks: cancelledRemarks,
        qty: 0,
        amount: 0,
        totalValue: 0,
        items: [],
        packageSlips: [],
        soLinks: [],
        grnLinks: [],
        linkedOrderIds: [],
        dispatchedPackages: [],
        soAllottedQtys: {},
        reconciledShipments: []
    };
    
    if (type === 'grn') {
        record.grnNo = docNo;
        record.customerId = existing?.customerId || existing?.customer_id || document.getElementById('grn-customer')?.value || '';
        record.customerName = existing?.customerName || existing?.customer_name || '';
        record.vendorId = existing?.vendorId || existing?.vendor_id || document.getElementById('grn-vendor')?.value || '';
        record.vendorName = existing?.vendorName || existing?.vendor_name || '';
        record.customer = record.customerName;
        record.weight = 0;
        record.pkgCount = 0;
        record.soLinks = [];
    } else if (type === 'po') {
        const poTypeInput = document.getElementById('po-type');
        record.poType = poTypeInput ? poTypeInput.value : (existing?.poType || (outwardWizardState?.type === 'inhouse' ? 'inhouse' : 'vendor'));
        record.design = '';
        record.vendorId = existing?.vendorId || existing?.vendor_id || document.getElementById('po-vendor')?.value || '';
        record.vendorName = existing?.vendorName || existing?.vendor_name || '';
    } else if (type === 'outward') {
        record.vendorId = existing?.vendorId || existing?.vendor_id || '';
        record.vendorName = existing?.vendorName || existing?.vendor_name || '';
        record.customerId = existing?.customerId || existing?.customer_id || '';
        record.customerName = existing?.customerName || existing?.customer_name || '';
        record.grnNo = '';
        record.dispatchedPackages = [];
        record.grnLinks = [];
    } else if (type === 'req') {
        record.requisitionNo = docNo;
    } else if (type === 'pur') {
        record.grNo = docNo;
        delete record.number;
    } else if (['invoice', 'voucher', 'salesreturn', 'purchasereturn', 'receipt', 'payment', 'journal', 'contra'].includes(type)) {
        record.type = type;
        delete record.amount;
        delete record.qty;
        delete record.packageSlips;
        const partySel = document.getElementById('gtx-party');
        if (partySel && partySel.value) {
            record.partyId = partySel.value;
            record.partyName = partySel.options[partySel.selectedIndex]?.text || '';
        }
        if (!record.partyId && existing) {
            record.partyId = existing.partyId || existing.party_id || '';
            record.partyName = existing.partyName || existing.party_name || '';
        }
        if (!record.partyId) {
            if (['voucher', 'purchasereturn', 'payment'].includes(type)) {
                const fallbackV = (db.vendors && db.vendors.length > 0) ? db.vendors[0] : null;
                if (fallbackV) {
                    record.partyId = fallbackV.id;
                    record.partyName = fallbackV.name;
                }
            } else {
                const fallbackC = (db.customers && db.customers.length > 0) ? db.customers[0] : null;
                if (fallbackC) {
                    record.partyId = fallbackC.id;
                    record.partyName = fallbackC.name;
                }
            }
        }
        record.totalValue = 0;
    } else if (type === 'so') {
        const custSelect = document.getElementById('so-customer');
        if (custSelect && custSelect.value) {
            record.customerId = custSelect.value;
            record.customerName = custSelect.options[custSelect.selectedIndex]?.text || '';
        }
        if (!record.customerId && existing) {
            record.customerId = existing.customerId || existing.customer_id;
            record.customerName = existing.customerName || existing.customer_name;
        }
        if (!record.customerId) {
            const fallbackCust = (db.customers && db.customers.length > 0) ? db.customers[0] : null;
            if (fallbackCust) {
                record.customerId = fallbackCust.id;
                record.customerName = fallbackCust.name;
            }
        }
    } else if (type === 'production' || type === 'sampling') {
        record.remarks = encodeMetadataToRemarks(cancelledRemarks, '__SLIP_METADATA__', [{
            machineId: '',
            machineNo: '',
            poId: '',
            poNumber: '',
            than: 0,
            conversion: 0,
            embroideryMtr: 0,
            fabricConsumption: 0,
            planId: null,
            planItemId: null,
            planNumber: null
        }]);
        record.finishedItemId = '';
        record.finishedItemName = '';
        record.qty = 0;
    }
    
    showImportLoadingOverlay();
    try {
        if (type === 'so') {
            if (typeof window.syncSOLinksWithGRNs === 'function') {
                await window.syncSOLinksWithGRNs(targetId, [], docNo);
            }
        } else if (type === 'grn') {
            if (typeof window.syncGRNLinksWithSOs === 'function') {
                await window.syncGRNLinksWithSOs(targetId, [], docNo);
            }
        } else if (type === 'outward') {
            if (existing) {
                const links = existing.grnLinks || (existing.grnRefId ? [{ grnRefId: existing.grnRefId, qty: existing.qty }] : []);
                for (const link of links) {
                    const grn = db.grns.find(g => g.id === link.grnRefId);
                    if (grn) {
                        grn.issuedMeters = Math.max(0, (grn.issuedMeters || 0) - link.qty);
                        await saveToSupabase('grns', grn);
                    }
                }
                if (existing.poRefId) {
                    const linkedPO = db.pos.find(p => p.id === existing.poRefId);
                    if (linkedPO && ((linkedPO.poType || 'vendor') === 'vendor' || linkedPO.poType === 'inhouse')) {
                        const poNumber = linkedPO.number;
                        const matchingPOs = db.pos.filter(p => p.number === poNumber);
                        const otherOutwards = db.outwards.filter(o => o.id !== existing.id && o.poRefId === existing.poRefId && o.status !== 'Cancelled');
                        const uniqueChallans = [...new Set(otherOutwards.map(o => o.number))].filter(Boolean).join(', ');
                        for (const mpo of matchingPOs) {
                            mpo.vendorJobWorkChallanNo = uniqueChallans;
                            await saveToSupabase('purchase_orders', mpo);
                        }
                    }
                }
            }
        }

        const supabaseTable = type === 'so' ? 'sales_orders' : 
                              (type === 'po' ? 'purchase_orders' : 
                              (type === 'grn' ? 'grns' : 
                              (type === 'outward' ? 'outwards' : 
                              (type === 'pur' ? 'purchases' : 
                              (type === 'req' ? 'requisition_slips' : 
                              (type === 'production' || type === 'sampling' ? 'production_slips' : 'generic_transactions'))))));
        try {
            await saveToSupabase(supabaseTable, record);
        } catch (subErr) {
            console.warn("Supabase cancel sync warning (proceeding with local cancellation):", subErr);
        }
        
        if (existing) {
            Object.assign(existing, record);
            if (rawDB && rawDB[dbKey]) {
                const rawExisting = rawDB[dbKey].find(x => x.id === existing.id);
                if (rawExisting) {
                    Object.assign(rawExisting, record);
                } else {
                    rawDB[dbKey].push(record);
                }
            }
        } else {
            db[dbKey].push(record);
            if (rawDB && rawDB[dbKey]) {
                rawDB[dbKey].push(record);
            }
        }
        
        window.showSmartSuccessAlert('Voucher Cancelled', `Voucher ${docNo} has been successfully cancelled.`);
        closeModal(modalId);
        
        if (type === 'so') {
            renderSalesOrderTable();
        } else if (type === 'po') {
            if (typeof window.renderPOTable === 'function') window.renderPOTable();
        } else if (type === 'grn') {
            renderGRNTable();
        } else if (type === 'outward') {
            renderOutwardTable();
        } else if (type === 'pur') {
            renderPurchaseTable();
        } else if (type === 'req') {
            renderRequisitionTable();
        } else if (type === 'production') {
            renderProductionTable();
        } else if (type === 'sampling') {
            if (typeof renderSamplingTable === 'function') renderSamplingTable();
        } else if (['invoice', 'voucher', 'salesreturn', 'purchasereturn', 'receipt', 'payment', 'journal', 'contra'].includes(type)) {
            applyFinancialYearFilters();
            switchTxSubtab(type);
        }
        renderDashboard();
    } catch (e) {
        console.error("Error cancelling voucher:", e);
        showToast('Error cancelling voucher: ' + (e.message || e), 'error');
    } finally {
        hideImportLoadingOverlay();
    }
};

// ===== GOOGLE SHEETS SYNC SYSTEM =====
function columnLetterToIndex(letter) {
    letter = String(letter).toUpperCase().replace(/[^A-Z]/g, '');
    let index = 0;
    for (let i = 0; i < letter.length; i++) {
        index = index * 26 + (letter.charCodeAt(i) - 64);
    }
    return index > 0 ? index : 1;
}

