window.bulkSyncSheetsData = async function() {
    const key = `sheets_sync_config_${currentCompany.id}`;
    let config = null;
    try {
        config = JSON.parse(localStorage.getItem(key));
    } catch(e) {}
    
    if (!config || !config.enabled || !config.url) {
        showToast('Please configure and enable Sheets Sync first!', 'error');
        return;
    }

    const type = currentSheetsMapModule;
    let list = [];
    if (type === 'so') {
        list = rawDB.salesOrders || [];
    } else if (type === 'po') {
        list = rawDB.pos || [];
    } else if (type === 'grn') {
        list = rawDB.grns || [];
    } else if (type === 'outward') {
        list = rawDB.outwards || [];
    } else if (type === 'slip') {
        list = rawDB.productionSlips || [];
    }

    if (list.length === 0) {
        showToast(`No records found for ${type.toUpperCase()} module to sync.`, 'info');
        return;
    }

    showToast(`Starting bulk sync of ${list.length} ${type.toUpperCase()} records. Please wait...`, 'info');
    
    // Process one by one to avoid rate limits
    for (let i = 0; i < list.length; i++) {
        await window.triggerGoogleSheetsSync(type, list[i], 'create');
        // Small delay
        await new Promise(r => setTimeout(r, 150));
    }

    showToast(`Bulk sync completed successfully! Synced ${list.length} records.`, 'success');
};

function parseGrnWizardStateForSync(grn) {
    let state = { type: 'fabric', source: 'customer', subType: 'plain', soAllottedQts: {} };
    if (!grn) return state;
    const no = String(grn.grnNo || grn.number || '').trim().toUpperCase();
    const rem = String(grn.remarks || '');
    
    let wizardMeta = null;
    if (grn.remarks) {
        const match = grn.remarks.match(/\[WIZARD:(\{.*?\})\]/);
        if (match) {
            try {
                wizardMeta = JSON.parse(match[1]);
            } catch (e) {}
        }
    }
    
    let prefixState = null;
    if (no.includes('/CON/') || no.includes('-CON-') || no.startsWith('GRN/CON') || rem.includes('[CONSUMABLE_TYPE:')) {
        prefixState = { type: 'consumable', source: 'vendor', subType: '' };
    } else if (no.includes('/OTH/') || no.includes('-OTH-') || no.startsWith('GRN/OTH')) {
        prefixState = { type: 'other', source: 'vendor', subType: '' };
    } else if (no.includes('GRN/V/EM') || no.includes('GRN/V/EMB')) {
        prefixState = { type: 'fabric', source: 'vendor', subType: 'embroidered' };
    } else if (no.includes('GRN/V/PF') || no.includes('GRN/V/PL')) {
        prefixState = { type: 'fabric', source: 'vendor', subType: 'plain' };
    } else if (no.includes('GRN/C/EM') || no.includes('GRN/C/EMB')) {
        prefixState = { type: 'fabric', source: 'customer', subType: 'embroidered' };
    } else if (no.includes('GRN/C/PF') || no.includes('GRN/C/PL')) {
        prefixState = { type: 'fabric', source: 'customer', subType: 'plain' };
    }

    if (prefixState) {
        state = Object.assign({}, wizardMeta || {}, prefixState);
    } else if (wizardMeta) {
        state = wizardMeta;
    }
    state.soAllottedQts = state.soAllottedQts || {};
    return state;
}

function getSheetsSubtypeId(type, record) {
    if (type === 'so') return 'so';
    if (type === 'po') {
        return 'po_' + (record.poType || 'vendor');
    }
    if (type === 'grn') {
        const wState = parseGrnWizardStateForSync(record);
        if (wState.type === 'fabric') {
            if (wState.source === 'customer') {
                return wState.subType === 'plain' ? 'grn_c_pf' : 'grn_c_em';
            } else {
                return wState.subType === 'plain' ? 'grn_v_pf' : 'grn_v_em';
            }
        } else if (wState.type === 'consumable') {
            return 'grn_con';
        } else if (wState.type === 'other') {
            return 'grn_oth';
        }
        // Fallback checks using prefix
        const numberStr = (record.grnNo || record.number || '').toUpperCase();
        if (numberStr.includes('GRN/C/PF')) return 'grn_c_pf';
        if (numberStr.includes('GRN/C/EM')) return 'grn_c_em';
        if (numberStr.includes('GRN/V/PF')) return 'grn_v_pf';
        if (numberStr.includes('GRN/V/EM')) return 'grn_v_em';
        if (numberStr.includes('GRN/CON')) return 'grn_con';
        if (numberStr.includes('GRN/OTH')) return 'grn_oth';
        return 'grn_v_pf';
    }
    if (type === 'outward') {
        const numberStr = (record.number || '').toUpperCase();
        if (numberStr.startsWith('FI/INH')) return 'outward_inh';
        if (numberStr.startsWith('FI/JW')) return 'outward_jw';
        if (numberStr.startsWith('FI/C/')) {
            return numberStr.includes('/EM/') || numberStr.startsWith('FI/C/EM') ? 'outward_c_em' : 'outward_c_pf';
        }
        return numberStr.includes('/EM/') || numberStr.startsWith('FI/V/EM') ? 'outward_v_em' : 'outward_v_pf';
    }
    if (type === 'slip') return 'slip';
    return type;
}

window.triggerGoogleSheetsSync = async function(type, record, action) {
    return; // Google Sheets sync is disabled as requested by the user
    const key = `sheets_sync_config_${currentCompany.id}`;
    let config = null;
    try { config = JSON.parse(localStorage.getItem(key)); } catch(e) {}
    if (!config || !config.enabled || !config.url) return;
    const subtypeId = getSheetsSubtypeId(type, record);
    const subConfig = config[subtypeId];
    if (!subConfig || !subConfig.mappings || subConfig.mappings.length === 0) return;
    const mappingsPayload = subConfig.mappings.map(m => {
        const val = record[m.field];
        return {
            colLetter: m.colLetter,
            colIndex: m.colIndex || columnLetterToIndex(m.colLetter),
            header: m.header,
            value: val !== undefined && val !== null ? String(val) : ''
        };
    });
    const payload = {
        action: action,
        type: subtypeId,
        id: record.id || record.number,
        tabName: subConfig.tabName,
        spreadsheetUrl: subConfig.spreadsheetUrl || '',
        mappings: mappingsPayload
    };
    try {
        await fetch(config.url, {
            method: 'POST',
            mode: 'no-cors',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        console.log('Google Sheets Sync executed for: ' + (record.number || record.id));
    } catch(e) {
        console.error('Google Sheets Sync failed:', e);
    }
};

window.resequenceVoucherSeries = async function(type) {
    if (!currentCompany) return;
    let selectedPrefix = 'ALL';
    if (type === 'grn') {
        selectedPrefix = document.getElementById('resequence-grn-prefix')?.value || 'ALL';
    } else if (type === 'outward') {
        selectedPrefix = document.getElementById('resequence-outward-prefix')?.value || 'ALL';
    }
    const confirmRun = await window.showSmartConfirm('Re-sequence Vouchers', 'Are you sure you want to re-sequence all ' + type.toUpperCase() + 
        (selectedPrefix !== 'ALL' ? ' with prefix "' + selectedPrefix + '"' : '') + 
        ' document numbers strictly in series by date?\n\nThis will update your Supabase database and CANNOT be undone!');
    if (!confirmRun) return;
    showImportLoadingOverlay();
    try {
        const fySuffix = (financialYears[currentFinancialYear] || {}).suffix || '/26-27';
        const cleanSuffix = fySuffix.startsWith('/') ? fySuffix.substring(1) : fySuffix;

        if (type === 'production') {
            const list = rawDB.productionSlips || [];
            if (!list.length) { showToast('No Production Slip records found to re-sequence.', 'info'); hideImportLoadingOverlay(); return; }
            var groups = {};
            list.forEach(function(item) {
                var prefix = (item.number && item.number.startsWith('SMP')) ? 'SMP' : 'PRD';
                if (!groups[prefix]) groups[prefix] = [];
                groups[prefix].push(item);
            });
            var updateCount = 0;
            for (var prefix in groups) {
                var groupItems = groups[prefix];
                groupItems.sort(function(a, b) {
                    var d = new Date(a.date || 0).getTime() - new Date(b.date || 0).getTime();
                    if (d !== 0) return d;
                    return new Date(a.entryTimestamp || 0).getTime() - new Date(b.entryTimestamp || 0).getTime();
                });
                for (var j = 0; j < groupItems.length; j++) {
                    var gitem = groupItems[j];
                    var correctNo = prefix + '/' + cleanSuffix + '/' + String(j + 1).padStart(3, '0');
                    if (gitem.number !== correctNo) {
                        gitem.number = correctNo;
                        await saveToSupabase('production_slips', gitem);
                        updateCount++;
                    }
                }
            }
            showToast('Successfully re-sequenced ' + updateCount + ' Production Slips in strict series!', 'success');
            if (typeof renderProductionTable === 'function') renderProductionTable();
            if (typeof renderSamplingTable === 'function') renderSamplingTable();
            hideImportLoadingOverlay();
            return;
        }

        if (type === 'so') {
            const list = (rawDB.salesOrders || []).filter(function(so) { return isDateInCurrentFY(so.date, so.number); });
            if (!list.length) { showToast('No Sales Orders found in current FY to re-sequence.', 'info'); hideImportLoadingOverlay(); return; }
            list.sort(function(a, b) {
                var d = new Date(a.date || 0).getTime() - new Date(b.date || 0).getTime();
                if (d !== 0) return d;
                return new Date(a.entryTimestamp || 0).getTime() - new Date(b.entryTimestamp || 0).getTime();
            });
            var updateCount = 0;
            for (var i = 0; i < list.length; i++) {
                var item = list[i];
                var correctNo = 'SO/' + cleanSuffix + '/' + String(i + 1).padStart(3, '0');
                if (item.number !== correctNo) {
                    item.number = correctNo;
                    await saveToSupabase('sales_orders', item);
                    updateCount++;
                }
            }
            rawDB.salesOrders = (rawDB.salesOrders || []).map(function(orig) {
                var updated = list.find(function(l) { return l.id === orig.id; });
                return updated || orig;
            });
            db.salesOrders = rawDB.salesOrders.filter(function(so) { return isDateInCurrentFY(so.date, so.number); });
            showToast('Re-sequenced ' + updateCount + ' Sales Orders in strict series!', 'success');
            if (typeof renderSOTable === 'function') renderSOTable();
            else renderSalesOrderTable();
            hideImportLoadingOverlay();
            return;
        }

        var list2 = [];
        if (type === 'grn') {
            list2 = rawDB.grns || [];
        } else if (type === 'outward') {
            list2 = rawDB.outwards || [];
        }
        if (!list2.length) { showToast('No ' + type.toUpperCase() + ' records found to re-sequence.', 'info'); return; }

        var groups = {};
        list2.forEach(function(item) {
            var prefix = 'GRN';
            if (type === 'grn') {
                var state = parseGrnWizardStateForSync(item);
                if (state.type === 'fabric') {
                    if (state.source === 'customer') {
                        prefix = state.subType === 'plain' ? 'GRN/C/PF' : 'GRN/C/EM';
                    } else {
                        prefix = state.subType === 'plain' ? 'GRN/V/PF' : 'GRN/V/EM';
                    }
                } else if (state.type === 'consumable') {
                    prefix = 'GRN/CON';
                } else if (state.type === 'other') {
                    prefix = 'GRN/OTH';
                }
            } else if (type === 'outward') {
                var num = (item.number || '').toUpperCase();
                if (num.startsWith('FI/INH')) prefix = 'FI/INH';
                else if (num.startsWith('FI/JW')) prefix = 'FI/JW';
                else if (num.startsWith('FI/C/EM')) prefix = 'FI/C/EM';
                else if (num.startsWith('FI/C/PF')) prefix = 'FI/C/PF';
                else if (num.startsWith('FI/V/EM')) prefix = 'FI/V/EM';
                else prefix = 'FI/V/PF';
            }
            if (!groups[prefix]) groups[prefix] = [];
            groups[prefix].push(item);
        });

        var updateCount2 = 0;
        for (var prefix in groups) {
            if (selectedPrefix && selectedPrefix !== 'ALL' && prefix !== selectedPrefix) {
                continue;
            }
            var groupItems = groups[prefix];
            groupItems.sort(function(a, b) { return new Date(a.date || 0).getTime() - new Date(b.date || 0).getTime(); });
            for (var j = 0; j < groupItems.length; j++) {
                var gitem = groupItems[j];
                var correctNo2 = prefix + '/' + cleanSuffix + '/' + String(j + 1).padStart(3, '0');
                var currentNo = type === 'grn' ? (gitem.grnNo || gitem.number) : gitem.number;
                if (currentNo !== correctNo2) {
                    if (type === 'grn') {
                        gitem.grnNo = correctNo2;
                        gitem.number = correctNo2;
                        await saveToSupabase('grns', gitem);
                    } else if (type === 'outward') {
                        gitem.number = correctNo2;
                        await saveToSupabase('outwards', gitem);
                    }
                    updateCount2++;
                }
            }
        }
        showToast('Successfully re-sequenced ' + updateCount2 + ' records matching series!', 'success');
        if (type === 'grn') renderGRNTable();
        else if (type === 'outward') renderOutwardTable();

    } catch(e) {
        console.error(e);
        showToast('Re-sequencing failed: ' + e.message, 'error');
    } finally {
        hideImportLoadingOverlay();
    }
};

