window.initReconciliation = function() {
    const select = document.getElementById('recon-customer-select');
    if (!select) return;
    
    // Group dropdown by Customers and Vendors
    select.innerHTML = '<option value="">-- Custom / Random Party --</option>';
    
    const custGroup = document.createElement('optgroup');
    custGroup.label = 'Customers';
    const customers = db.customers || [];
    customers.forEach(c => {
        const opt = document.createElement('option');
        opt.value = 'cust_' + c.id;
        opt.textContent = c.name;
        custGroup.appendChild(opt);
    });
    select.appendChild(custGroup);

    const vendGroup = document.createElement('optgroup');
    vendGroup.label = 'Vendors';
    const vendors = db.vendors || [];
    vendors.forEach(v => {
        const opt = document.createElement('option');
        opt.value = 'vend_' + v.id;
        opt.textContent = v.name;
        vendGroup.appendChild(opt);
    });
    select.appendChild(vendGroup);

    const internalPaste = document.getElementById('recon-internal-paste');
    const customerPaste = document.getElementById('recon-customer-paste');
    if (internalPaste && !internalPaste.value) {
        internalPaste.value = "";
    }
    if (customerPaste && !customerPaste.value) {
        customerPaste.value = "";
    }
};

window.updateReconPartyNames = function() {
    const partyName = document.getElementById('recon-company-party-name').value || 'Custom Party';
    document.getElementById('recon-customer-identifier').value = partyName + " Statement";
};

window.loadInternalLedger = function() {
    const selectVal = document.getElementById('recon-customer-select').value;
    if (!selectVal) {
        document.getElementById('recon-company-party-name').value = '';
        document.getElementById('recon-customer-identifier').value = '';
        document.getElementById('recon-internal-paste').value = '';
        document.getElementById('recon-customer-paste').value = '';
        return;
    }

    let partyName = '';
    let internalRows = [];
    let startingDate = '2026-06-01';

    if (selectVal.startsWith('cust_')) {
        const customerId = selectVal.replace('cust_', '');
        const customer = (db.customers || []).find(c => c.id === customerId);
        if (!customer) return;

        partyName = customer.name;
        document.getElementById('recon-party-type-toggle').value = 'Customer';
        const salesOrders = (db.salesOrders || []).filter(so => so.customerId === customerId);
        const payments = (db.genericTransactions || []).filter(gt => gt.partyId === customerId || gt.partyName === customer.name);

        salesOrders.forEach(so => {
            let amt = parseFloat(so.amount || so.totalValue || 0);
            if (amt === 0) {
                (so.items || []).forEach(item => {
                    const r = parseFloat(item.price || item.rate || 0);
                    const q = parseFloat(item.qty || 0);
                    amt += parseFloat(item.amount || (q * r) || 0);
                });
            }
            if (amt > 0) {
                internalRows.push({
                    date: so.date || startingDate,
                    ref: so.number,
                    amount: amt,
                    type: 'Dr' // Debit due from customer
                });
            }
        });

        payments.forEach(p => {
            const amt = parseFloat(p.amount || p.totalValue) || 0;
            if (amt > 0) {
                internalRows.push({
                    date: p.date || startingDate,
                    ref: p.number || p.voucherNo || p.id.substring(0,8).toUpperCase(),
                    amount: amt,
                    type: 'Cr' // Credit payment received
                });
            }
        });

    } else if (selectVal.startsWith('vend_')) {
        const vendorId = selectVal.replace('vend_', '');
        const vendor = (db.vendors || []).find(v => v.id === vendorId);
        if (!vendor) return;

        partyName = vendor.name;
        document.getElementById('recon-party-type-toggle').value = 'Vendor';
        // Fetch purchase orders / bills
        const purchaseOrders = (db.pos || []).filter(po => po.vendorId === vendorId || po.vendorName === vendor.name);
        const payments = (db.genericTransactions || []).filter(gt => gt.partyId === vendorId || gt.partyName === vendor.name);

        purchaseOrders.forEach(po => {
            let amt = parseFloat(po.amount || po.totalValue || 0);
            if (amt === 0) {
                (po.items || []).forEach(item => {
                    const r = parseFloat(item.price || item.rate || 0);
                    const q = parseFloat(item.qty || 0);
                    amt += parseFloat(item.amount || (q * r) || 0);
                });
            }
            if (amt > 0) {
                internalRows.push({
                    date: po.date || startingDate,
                    ref: po.vendorInvoiceNo || po.billNo || po.billNumber || po.invoiceNo || po.number,
                    amount: amt,
                    type: 'Cr' // Credit due to vendor
                });
            }
        });

        payments.forEach(p => {
            const amt = parseFloat(p.amount || p.totalValue) || 0;
            if (amt > 0) {
                internalRows.push({
                    date: p.date || startingDate,
                    ref: p.number || p.voucherNo || p.id.substring(0,8).toUpperCase(),
                    amount: amt,
                    type: 'Dr' // Debit payment made to vendor
                });
            }
        });
    }

    document.getElementById('recon-company-party-name').value = partyName;
    document.getElementById('recon-customer-identifier').value = partyName + " Statement";

    const cleanPartyKey = partyName.toLowerCase().replace(/[^a-z0-9]/g, '_');
    const savedOurOpening = localStorage.getItem(`recon_opening_our_${cleanPartyKey}`);
    const savedOurOpeningType = localStorage.getItem(`recon_opening_our_type_${cleanPartyKey}`);
    const savedCustOpening = localStorage.getItem(`recon_opening_cust_${cleanPartyKey}`);
    const savedCustOpeningType = localStorage.getItem(`recon_opening_cust_type_${cleanPartyKey}`);
    const savedCustActual = localStorage.getItem(`recon_actual_cust_${cleanPartyKey}`);
    const savedCustActualType = localStorage.getItem(`recon_actual_cust_type_${cleanPartyKey}`);

    const ourInput = document.getElementById('recon-our-opening');
    const ourSelect = document.getElementById('recon-our-opening-type');
    const custInput = document.getElementById('recon-customer-opening');
    const custSelect = document.getElementById('recon-customer-opening-type');
    const custActualInput = document.getElementById('recon-customer-actual-input');
    const custActualSelect = document.getElementById('recon-customer-actual-type');

    if (ourInput) ourInput.value = savedOurOpening !== null ? savedOurOpening : '0';
    if (ourSelect) ourSelect.value = savedOurOpeningType !== null ? savedOurOpeningType : 'Dr';
    if (custInput) custInput.value = savedCustOpening !== null ? savedCustOpening : '0';
    if (custSelect) custSelect.value = savedCustOpeningType !== null ? savedCustOpeningType : 'Cr';
    if (custActualInput) custActualInput.value = savedCustActual !== null ? savedCustActual : '0';
    if (custActualSelect) custActualSelect.value = savedCustActualType !== null ? savedCustActualType : 'Dr';

    const savedAdj = localStorage.getItem(`recon_adj_${cleanPartyKey}`);
    const savedAdjReason = localStorage.getItem(`recon_adj_reason_${cleanPartyKey}`);
    const adjInput = document.getElementById('recon-custom-adjustment');
    const adjReasonInput = document.getElementById('recon-custom-reason');
    if (adjInput) adjInput.value = savedAdj !== null ? savedAdj : '';
    if (adjReasonInput) adjReasonInput.value = savedAdjReason !== null ? savedAdjReason : '';

    // Sort by date
    internalRows.sort((a,b) => new Date(a.date) - new Date(b.date));

    // Format text representation for the Paste Textarea
    let textLines = [];
    internalRows.forEach(r => {
        textLines.push(`${r.date}\t${r.ref}\t${r.amount}\t${r.type}`);
    });

    document.getElementById('recon-internal-paste').value = textLines.join('\n');

    // Simulate party books matches
    let partyLines = [];
    internalRows.forEach((r, idx) => {
        const oppositeType = r.type === 'Dr' ? 'Cr' : 'Dr';
        if (idx === 1 && r.type === 'Cr') {
            partyLines.push(`${r.date}\t${r.ref}\t${r.amount - 2000}\t${oppositeType}`);
        } else if (idx === 2) {
            return;
        } else {
            partyLines.push(`${r.date}\t${r.ref}\t${r.amount}\t${oppositeType}`);
        }
    });

    // Add a mismatch row
    partyLines.push(`2026-06-25\tTXN-MISMATCH-99\t15000\tDr`);

    document.getElementById('recon-customer-paste').value = partyLines.join('\n');
    
    showToast(`Pulled company ledger and simulated ${selectVal.startsWith('cust_') ? 'customer' : 'vendor'} matches!`, 'info');
    window.runReconMatch();
};

function loadPdfJs() {
    return new Promise((resolve, reject) => {
        if (window.pdfjsLib) {
            resolve(window.pdfjsLib);
            return;
        }
        const script = document.createElement('script');
        script.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.4.120/pdf.min.js';
        script.onload = () => {
            window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.4.120/pdf.worker.min.js';
            resolve(window.pdfjsLib);
        };
        script.onerror = () => {
            reject(new Error('Failed to load PDF library.'));
        };
        document.head.appendChild(script);
    });
}

async function extractTextFromPdf(arrayBuffer) {
    const pdfjsLib = await loadPdfJs();
    const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer });
    const pdf = await loadingTask.promise;
    let fullText = '';
    
    for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
        const page = await pdf.getPage(pageNum);
        const textContent = await page.getTextContent();
        const items = textContent.items;
        const lineMap = {};
        
        items.forEach(item => {
            const y = item.transform[5];
            let foundY = null;
            for (let existingY in lineMap) {
                if (Math.abs(parseFloat(existingY) - y) < 4) {
                    foundY = existingY;
                    break;
                }
            }
            if (foundY !== null) {
                lineMap[foundY].push(item);
            } else {
                lineMap[y] = [item];
            }
        });
        
        const sortedY = Object.keys(lineMap).sort((a, b) => b - a);
        sortedY.forEach(y => {
            const lineItems = lineMap[y].sort((a, b) => a.transform[4] - b.transform[4]);
            let lineStr = '';
            let prevX = -1;
            let lastStartX = -1;
            lineItems.forEach(item => {
                if (prevX !== -1) {
                    const dist = item.transform[4] - prevX;
                    const startsNewWord = (item.transform[4] > lastStartX + 2);
                    if (dist > 5) {
                        lineStr += '\t';
                    } else if (dist > 0.3 || startsNewWord) {
                        lineStr += ' ';
                    }
                }
                lineStr += item.str;
                lastStartX = item.transform[4];
                prevX = item.transform[4] + (item.width || 0);
            });
            
            if (lineStr.trim()) {
                fullText += lineStr + '\n';
            }
        });
    }
    return fullText;
}

window.autoParseRawText = function(text, isOurBooks) {
    const correctReconRowType = function(ref, currentType, isOurBooks) {
        const refLower = String(ref || '').toLowerCase();
        const partyTypeToggle = document.getElementById('recon-party-type-toggle');
        const isVendor = partyTypeToggle ? (partyTypeToggle.value === 'Vendor') : true;

        if (isVendor) {
            if (refLower.includes('tds') || refLower.includes('payment') || refLower.includes('pymt') || refLower.includes('bank') || refLower.includes('cash') || refLower.includes('canara') || refLower.includes('icici')) {
                return isOurBooks ? 'Dr' : 'Cr';
            } else if (refLower.includes('purchase') || refLower.includes('purc') || refLower.includes('job work') || refLower.includes('invoice') || refLower.includes('bill')) {
                return isOurBooks ? 'Cr' : 'Dr';
            }
        } else {
            if (refLower.includes('tds') || refLower.includes('payment') || refLower.includes('pymt') || refLower.includes('bank') || refLower.includes('cash') || refLower.includes('canara') || refLower.includes('icici') || refLower.includes('receipt') || refLower.includes('rcpt')) {
                return isOurBooks ? 'Cr' : 'Dr';
            } else if (refLower.includes('sale') || refLower.includes('sales') || refLower.includes('invoice') || refLower.includes('bill')) {
                return isOurBooks ? 'Dr' : 'Cr';
            }
        }
        return currentType;
    };
    // Insert spaces at letter-digit and digit-letter boundaries to handle columns running together
    const cleanText = text
        .replace(/([a-zA-Z])(\d)/g, '$1 $2')
        .replace(/(\d)([a-zA-Z])/g, '$1 $2');

    const lines = cleanText.split('\n').map(l => l.trim()).filter(l => l !== '');
    if (lines.length === 0) return [];
    
    let delimiter = /\s{2,}/;
    const hasTab = lines.some(l => l.includes('\t'));
    if (hasTab) {
        delimiter = '\t';
    } else if (lines[0] && lines[0].includes(',')) {
        delimiter = ',';
    }
    
    const splitRows = lines.map(line => {
        return line.split(delimiter).map(cell => cell.trim());
    });
    
    let maxCols = 0;
    splitRows.forEach(row => {
        if (row.length > maxCols) maxCols = row.length;
    });
    
    let colStats = [];
    for (let c = 0; c < maxCols; c++) {
        colStats.push({ dates: 0, amounts: 0, types: 0, refs: 0, total: 0 });
    }
    
    const dateRegex = /\d{1,4}[-./\\]\d{1,2}[-./\\]\d{1,4}/;
    const wordMonths = /jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec/i;
    
    splitRows.forEach(row => {
        row.forEach((cell, c) => {
            colStats[c].total++;
            const cleanCell = cell.replace(/[�,]/g, '').trim();
            const num = parseFloat(cleanCell);
            
            if (dateRegex.test(cell) || wordMonths.test(cell)) {
                colStats[c].dates++;
            } else if (!isNaN(num) && num > 0 && cell.match(/\d/) && !cell.includes('-') && !cell.includes('/')) {
                colStats[c].amounts++;
            } else if (cell.toLowerCase() === 'dr' || cell.toLowerCase() === 'cr' || cell.toLowerCase() === 'debit' || cell.toLowerCase() === 'credit') {
                colStats[c].types++;
            } else if (cell.length > 0) {
                colStats[c].refs++;
            }
        });
    });
    
    // Gather concatenated header words in the first 15 rows column-by-column to find the PDF headers
    let colHeaderTerms = [];
    for (let c = 0; c < maxCols; c++) {
        colHeaderTerms.push('');
    }
    splitRows.slice(0, 15).forEach(row => {
        row.forEach((cell, c) => {
            colHeaderTerms[c] += ' ' + cell.toLowerCase();
        });
    });
    
    let dateCol = -1;
    let debitCol = -1;
    let creditCol = -1;
    let amountCol = -1;
    let typeCol = -1;
    let refCol = -1;
    let docNoCol = -1;
    
    for (let c = 0; c < maxCols; c++) {
        const terms = colHeaderTerms[c];
        if (terms.includes('date')) {
            dateCol = c;
        } else if (terms.includes('debit') || (terms.includes('payment') && !terms.includes('method')) || (terms.includes('withdrawal') && !terms.includes('limit'))) {
            debitCol = c;
        } else if (terms.includes('credit') || terms.includes('receipt') || terms.includes('deposit')) {
            creditCol = c;
        } else if (terms.includes('amount') || terms.includes('value')) {
            amountCol = c;
        } else if (terms.includes('vch no') || terms.includes('voucher no') || terms.includes('doc no') || terms.includes('document') || terms.includes('inv no') || terms.includes('invoice no') || terms.includes('bill no') || terms.includes('bill') || terms.includes('chq no') || terms.includes('cheque no')) {
            if (!terms.includes('type') && !terms.includes('class')) {
                docNoCol = c;
            }
        } else if (terms.includes('particular') || terms.includes('description') || terms.includes('narration') || terms.includes('details') || terms.includes('account') || terms.includes('ledger') || terms.includes('name')) {
            refCol = c;
        } else if (terms.includes('vch') || terms.includes('ref') || terms.includes('invoice') || terms.includes('chq') || terms.includes('cheque')) {
            if (!terms.includes('type') && !terms.includes('class')) {
                if (docNoCol === -1) docNoCol = c;
                else if (refCol === -1) refCol = c;
            }
        } else if (terms.includes('dr') && terms.includes('cr')) {
            typeCol = c;
        }
    }
    
    // Detect if column widths / row lengths are inconsistent (which means empty columns collapsed and shifted data)
    let forceFallback = false;
    let dateRowLengths = [];
    splitRows.forEach(row => {
        const hasDate = row.some(cell => dateRegex.test(cell) || wordMonths.test(cell));
        if (hasDate) {
            dateRowLengths.push(row.length);
        }
    });
    if (dateRowLengths.length > 0) {
        const firstLen = dateRowLengths[0];
        const isConsistent = dateRowLengths.every(len => len === firstLen);
        if (!isConsistent) {
            // Columns are shifting/collapsing! Force regex-based fallback
            forceFallback = true;
            dateCol = -1;
            debitCol = -1;
            creditCol = -1;
            amountCol = -1;
        }
    }

    // Heuristic fallbacks if keyword matching missed columns
    if (!forceFallback) {
        if (dateCol === -1) {
            let maxDates = 0;
            for (let c = 0; c < maxCols; c++) {
                if (colStats[c].dates > maxDates) {
                    maxDates = colStats[c].dates;
                    dateCol = c;
                }
            }
        }
        
        if (amountCol === -1 && debitCol === -1 && creditCol === -1) {
            let maxAmounts = 0;
            for (let c = 0; c < maxCols; c++) {
                if (c === dateCol) continue;
                if (colStats[c].amounts > maxAmounts) {
                    maxAmounts = colStats[c].amounts;
                    amountCol = c;
                }
            }
        }
        
        if (typeCol === -1) {
            let maxTypes = 0;
            for (let c = 0; c < maxCols; c++) {
                if (c === dateCol || c === amountCol || c === debitCol || c === creditCol) continue;
                if (colStats[c].types > maxTypes) {
                    maxTypes = colStats[c].types;
                    typeCol = c;
                }
            }
        }
    }
    
    // Gather leftover text columns
    let textCols = [];
    for (let c = 0; c < maxCols; c++) {
        if (c !== dateCol && c !== amountCol && c !== debitCol && c !== creditCol && c !== typeCol && c !== docNoCol) {
            textCols.push(c);
        }
    }
    
    if (refCol === -1 && textCols.length > 0) {
        refCol = textCols[0];
        textCols.shift();
    }
    
    if (docNoCol === -1 && textCols.length > 0) {
        docNoCol = textCols[0];
    }
    
    let parsed = [];
    splitRows.forEach(row => {
        if (forceFallback) return;
        const rowStr = row.join(' ').toLowerCase();
        if (rowStr.includes('account :') || rowStr.includes('opening bal') || rowStr.includes('closing bal') || rowStr.includes('closing balance') || rowStr.includes('opening balance') || rowStr.includes('ledger account')) {
            return;
        }
        let dateVal = '';
        let refVal = '';
        let amtVal = 0;
        let typeVal = isOurBooks ? 'Dr' : 'Cr';
        
        if (dateCol !== -1 && row[dateCol]) dateVal = row[dateCol];
        
        // Handle double-column layouts (Debit column and Credit column separate)
        if (debitCol !== -1 && row[debitCol]) {
            const cleanD = parseFloat(row[debitCol].replace(/[�,]/g, '').trim());
            if (!isNaN(cleanD) && cleanD > 0) {
                amtVal = cleanD;
                typeVal = 'Dr';
            }
        }
        if (creditCol !== -1 && row[creditCol] && amtVal === 0) {
            const cleanC = parseFloat(row[creditCol].replace(/[�,]/g, '').trim());
            if (!isNaN(cleanC) && cleanC > 0) {
                amtVal = cleanC;
                typeVal = 'Cr';
            }
        }
        
        // Handle single-column layouts with a separate type column (Dr/Cr)
        if (amtVal === 0 && amountCol !== -1 && row[amountCol]) {
            amtVal = parseFloat(row[amountCol].replace(/[�,]/g, '').trim()) || 0;
            if (typeCol !== -1 && row[typeCol]) {
                const t = row[typeCol].toLowerCase();
                if (t.includes('dr') || t.includes('deb')) typeVal = 'Dr';
                if (t.includes('cr') || t.includes('cre')) typeVal = 'Cr';
            }
        }
        
        if (refCol !== -1 && row[refCol]) refVal = row[refCol];
        let docNoVal = '';
        if (docNoCol !== -1 && row[docNoCol]) docNoVal = row[docNoCol];
        
        if (isNaN(amtVal) || amtVal <= 0) {
            if (parsed.length > 0) {
                const lastTx = parsed[parsed.length - 1];
                const rowStr = row.join(' ').trim();
                const billMatch = rowStr.match(/(?:bill\s*no|vch\s*no|voucher\s*no|inv\s*no|invoice\s*no|ref\s*no|bill|vch|inv|ref|doc)[:.-]?\s*([a-zA-Z0-9-/]+)/i);
                if (billMatch) {
                    const extractedDoc = billMatch[1];
                    if (extractedDoc && !/^\d{10,}$/.test(extractedDoc)) {
                        lastTx.docNo = extractedDoc;
                    }
                } else {
                    const possibleCode = row.find(cell => cell.match(/^[a-zA-Z0-9-/]{2,15},?$/));
                    if (possibleCode) {
                        const cleanCode = possibleCode.replace(/,/g, '').trim();
                        if (cleanCode && !/^\d{10,}$/.test(cleanCode)) {
                            lastTx.docNo = cleanCode;
                        }
                    }
                }
            }
            return;
        }
        
        // Avoid mapping table header rows themselves
        if (dateVal.toLowerCase().includes('date') || refVal.toLowerCase().includes('particular') || refVal.toLowerCase().includes('vch')) return;
        
        if (!dateVal && refVal.toLowerCase().includes('tds') && parsed.length > 0) {
            dateVal = parsed[parsed.length - 1].date;
            refVal = `TDS on ${parsed[parsed.length - 1].ref} (${refVal})`;
        }
        
        if (!dateVal) dateVal = new Date().toLocaleDateString('en-IN');
        if (!refVal) refVal = 'Txn-' + Math.floor(1000 + Math.random() * 9000);
        
        if (!docNoVal && refVal) {
            const vchMatch = refVal.match(/(?:vch\s*no|voucher\s*no|inv\s*no|invoice\s*no|ref\s*no|vch|inv|ref|doc)[:.-]?\s*([a-zA-Z0-9-/]+)/i);
            if (vchMatch) {
                docNoVal = vchMatch[1];
                refVal = refVal.replace(vchMatch[0], '').trim();
            } else {
                const trailingMatch = refVal.match(/\s+([a-zA-Z0-9/-]{2,15})$/);
                if (trailingMatch && isNaN(trailingMatch[1])) {
                    docNoVal = trailingMatch[1];
                    refVal = refVal.substring(0, refVal.lastIndexOf(trailingMatch[0])).trim();
                } else if (trailingMatch && !isNaN(trailingMatch[1]) && trailingMatch[1].length >= 2) {
                    docNoVal = trailingMatch[1];
                    refVal = refVal.substring(0, refVal.lastIndexOf(trailingMatch[0])).trim();
                }
            }
        }
        
        if (docNoVal && /^\d{10,}$/.test(docNoVal)) {
            docNoVal = '';
        }
        
        parsed.push({
            date: dateVal,
            ref: refVal.slice(0, 60),
            docNo: docNoVal || '-',
            amount: amtVal,
            type: correctReconRowType(row.join(' '), typeVal, isOurBooks)
        });
    });
    
    // Fallback: regex search on single line to extract dates and amounts if column-based parsing returned nothing
    if (parsed.length === 0) {
        const fallbackDateRegex = /(\d{1,2}[-./\\](?:\d{1,2}|[A-Za-z]{3})[-./\\]\d{2,4})/;
        let lastSeenDate = '';
        splitRows.forEach(row => {
            const line = row.join(' ');
            const lowerLine = line.toLowerCase();
            if (lowerLine.includes('account :') || lowerLine.includes('opening bal') || lowerLine.includes('closing bal') || lowerLine.includes('closing balance') || lowerLine.includes('opening balance') || lowerLine.includes('ledger account')) {
                return;
            }
            let dateVal = '';
            const dateMatch = line.match(fallbackDateRegex);
            if (dateMatch) {
                dateVal = dateMatch[1];
                lastSeenDate = dateVal;
            } else if (lastSeenDate && (
                /\b(dr|cr)\b/i.test(line) || 
                /\b(receipt|payment|pymt|purc|purchase|sale|sales|invoice|inv|jv|journal)\b/i.test(line)
            )) {
                // If it has transaction keywords/types and a number, it's a new transaction on the same date!
                const numberMatches = line.match(/\b\d{1,3}(?:,\d{2,3})*(?:\.\d+)?\b/g) || [];
                let nums = numberMatches
                    .map(n => parseFloat(n.replace(/,/g, '')))
                    .filter(n => n > 0 && !/^\d{10,}$/.test(String(n)));
                if (nums.length > 0) {
                    dateVal = lastSeenDate;
                }
            }
            
            if (!dateVal) {
                if (lowerLine.includes('tds') && parsed.length > 0) {
                    dateVal = parsed[parsed.length - 1].date;
                } else {
                    if (parsed.length > 0) {
                        const lastTx = parsed[parsed.length - 1];
                        const rawLine = line.trim();
                        const billMatch = rawLine.match(/(?:bill\s*no|vch\s*no|voucher\s*no|inv\s*no|invoice\s*no|ref\s*no|bill|vch|inv|ref|doc)[:.-]?\s*([a-zA-Z0-9-/]+)/i);
                        if (billMatch) {
                            const extractedDoc = billMatch[1];
                            if (extractedDoc && !/^\d{10,}$/.test(extractedDoc)) {
                                lastTx.docNo = extractedDoc;
                            }
                        } else if (rawLine.match(/^[a-zA-Z0-9-/]{2,15},?$/)) {
                            const cleanCode = rawLine.replace(/,/g, '').trim();
                            if (cleanCode && !/^\d{10,}$/.test(cleanCode)) {
                                if (!lastTx.docNo || lastTx.docNo === '-') {
                                    lastTx.docNo = cleanCode;
                                }
                            }
                        }
                    }
                    return;
                }
            }
            
            const lineWithoutDate = line.replace(dateVal, '');
            
            const numberMatches = lineWithoutDate.match(/\b\d{1,3}(?:,\d{2,3})*(?:\.\d+)?\b/g) || [];
            let nums = numberMatches
                .map(n => parseFloat(n.replace(/,/g, '')))
                .filter(n => n > 0 && !/^\d{10,}$/.test(String(n)));

            const percentMatches = lineWithoutDate.match(/(\d+(?:\.\d+)?)\s*%/g) || [];
            percentMatches.forEach(pMatch => {
                const pVal = parseFloat(pMatch);
                const pIdx = nums.indexOf(pVal);
                if (pIdx !== -1) nums.splice(pIdx, 1);
            });

            const hasBalanceSuffix = /\b(dr|cr)\b$/i.test(line.trim());
            let amtVal = 0;
            let docNoVal = '';
            
            if (hasBalanceSuffix) {
                if (nums.length >= 2) {
                    amtVal = nums[nums.length - 2];
                } else if (nums.length === 1) {
                    amtVal = nums[0];
                }
            } else {
                if (nums.length >= 1) {
                    amtVal = nums[nums.length - 1];
                }
            }

            let possibleDocNumbers = [];
            if (nums.length > 0) {
                const amtIdx = nums.indexOf(amtVal);
                if (amtIdx > 0) {
                    possibleDocNumbers = nums.slice(0, amtIdx);
                } else if (amtIdx === -1 && nums.length > 1) {
                    possibleDocNumbers = nums.slice(0, nums.length - 1);
                }
            }
            if (possibleDocNumbers.length > 0) {
                docNoVal = String(possibleDocNumbers[possibleDocNumbers.length - 1]);
            }

            let rawRef = lineWithoutDate;
            numberMatches.forEach(nStr => {
                rawRef = rawRef.replace(nStr, '');
            });
            rawRef = rawRef.replace(/\b(dr|cr|debit|credit|pymt|purc|payment|purchase|receipt|journal|jv)\b/gi, '');
            rawRef = rawRef.replace(/\s+/g, ' ').trim();
            if (!rawRef) rawRef = 'Txn-' + Math.floor(1000 + Math.random() * 9000);
            
            let typeVal = isOurBooks ? 'Dr' : 'Cr';
            let explicitType = '';
            
            // Clean Tally running balance Dr/Cr indicator at the beginning and end
            let typeCheckLine = line.trim();
            const dateM = typeCheckLine.match(dateRegex);
            if (dateM) {
                typeCheckLine = typeCheckLine.replace(dateM[0], '').trim();
            }
            typeCheckLine = typeCheckLine.replace(/^(dr|cr)\b/i, '').trim();
            typeCheckLine = typeCheckLine.replace(/\b(dr|cr)\s*$/i, '').trim();

            if (/\b(dr|deb|debit)\b/i.test(typeCheckLine)) {
                explicitType = 'Dr';
            } else if (/\b(cr|cre|credit)\b/i.test(typeCheckLine)) {
                explicitType = 'Cr';
            }

            if (explicitType) {
                typeVal = explicitType;
            } else {
                const lowerLine = line.toLowerCase();
                const partyTypeToggle = document.getElementById('recon-party-type-toggle');
                const isVendor = partyTypeToggle ? (partyTypeToggle.value === 'Vendor') : true;

                if (isVendor) {
                    if (lowerLine.includes('pymt') || lowerLine.includes('payment') || lowerLine.includes('bank') || lowerLine.includes('cash') || lowerLine.includes('tds') || lowerLine.includes('rcpt') || lowerLine.includes('receipt')) {
                        typeVal = isOurBooks ? 'Dr' : 'Cr';
                    } else if (lowerLine.includes('purc') || lowerLine.includes('purchase') || lowerLine.includes('sale') || lowerLine.includes('invoice') || lowerLine.includes('bill')) {
                        typeVal = isOurBooks ? 'Cr' : 'Dr';
                    }
                } else {
                    if (lowerLine.includes('rcpt') || lowerLine.includes('receipt') || lowerLine.includes('bank') || lowerLine.includes('cash') || lowerLine.includes('tds') || lowerLine.includes('pymt') || lowerLine.includes('payment')) {
                        typeVal = isOurBooks ? 'Cr' : 'Dr';
                    } else if (lowerLine.includes('sale') || lowerLine.includes('invoice') || lowerLine.includes('bill') || lowerLine.includes('purc') || lowerLine.includes('purchase')) {
                        typeVal = isOurBooks ? 'Dr' : 'Cr';
                    }
                }
            }
            
            if (amtVal > 0) {
                parsed.push({
                    date: dateVal,
                    ref: rawRef.slice(0, 60),
                    docNo: docNoVal || '-',
                    amount: amtVal,
                    type: correctReconRowType(line, typeVal, isOurBooks)
                });
            }
        });
    }

    return parsed;
};

window.handleReconFileUpload = function(type) {
    const fileInput = document.getElementById(`recon-${type}-file`);
    if (!fileInput.files.length) return;

    const file = fileInput.files[0];
    const reader = new FileReader();
    const isOurBooks = (type === 'internal');

    const processExtractedText = function(text) {
        // Scan for opening balances in text headers (e.g. "Opening Bal. = Rs. 21,676.00 Dr")
        const opRegex = /(dr|cr)?\s*opening\s*bal(?:ance)?(?:\.|=|\s|:|rs)*\s*([0-9,.]+)\s*(dr|cr)?/i;
        const opMatch = text.match(opRegex);
        if (opMatch) {
            const val = parseFloat(opMatch[2].replace(/,/g, '')) || 0;
            if (val > 0) {
                const rawType = (opMatch[1] || opMatch[3] || '').toUpperCase();
                const detectedType = rawType === 'DR' ? 'Dr' : (rawType === 'CR' ? 'Cr' : (isOurBooks ? 'Dr' : 'Cr'));
                
                const targetKey = isOurBooks ? 'our' : 'customer';
                const inputEl = document.getElementById(`recon-${targetKey}-opening`);
                const selectEl = document.getElementById(`recon-${targetKey}-opening-type`);
                if (inputEl) inputEl.value = val;
                if (selectEl) selectEl.value = detectedType;
            }
        }

        // Scan for closing balances (e.g. "Dr Closing Balance 1,07,744.00")
        if (!isOurBooks) {
            const clRegex = /(dr|cr)?\s*(?:closing\s*bal(?:ance)?|bal(?:ance)?\s*c\/[fd]|closing)(?:\.|=|\s|:|rs)*\s*([0-9,.]+)\s*(dr|cr)?/i;
            const clMatch = text.match(clRegex);
            if (clMatch) {
                const val = parseFloat(clMatch[2].replace(/,/g, '')) || 0;
                if (val > 0) {
                    const rawType = (clMatch[1] || clMatch[3] || '').toUpperCase();
                    const detectedType = rawType === 'CR' ? 'Cr' : 'Dr';
                    
                    const inputEl = document.getElementById('recon-customer-actual-input');
                    const selectEl = document.getElementById('recon-customer-actual-type');
                    if (inputEl) inputEl.value = val;
                    if (selectEl) selectEl.value = detectedType;
                }
            }
        }

        const txns = window.autoParseRawText(text, isOurBooks);
        if (txns.length > 0) {
            const lines = txns.map(t => `${t.date}\t${t.ref}\t${t.docNo || '-'}\t${t.amount}\t${t.type}`);
            document.getElementById(`recon-${type}-paste`).value = lines.join('\n');
            showToast(`Automatically extracted ${txns.length} transactions from ${file.name}!`, 'success');
            window.runReconMatch();
        } else {
            showToast(`Could not extract any valid transactions from ${file.name}. Please copy-paste details instead.`, 'warning');
        }
    };

    if (file.name.endsWith('.xlsx') || file.name.endsWith('.xls')) {
        reader.onload = function(e) {
            try {
                const data = new Uint8Array(e.target.result);
                const workbook = XLSX.read(data, {type: 'array'});
                const sheetName = workbook.SheetNames[0];
                const worksheet = workbook.Sheets[sheetName];
                const csv = XLSX.utils.sheet_to_csv(worksheet);
                processExtractedText(csv);
            } catch (err) {
                showToast(`Failed to parse Excel: ${err.message}`, 'error');
            }
        };
        reader.readAsArrayBuffer(file);
    } else if (file.name.endsWith('.pdf')) {
        showToast('Scanning PDF file and auto-detecting columns...', 'info');
        reader.onload = async function(e) {
            try {
                const text = await extractTextFromPdf(e.target.result);
                processExtractedText(text);
            } catch (err) {
                showToast(`Failed to parse PDF: ${err.message}`, 'error');
            }
        };
        reader.readAsArrayBuffer(file);
    } else if (file.name.endsWith('.csv') || file.name.endsWith('.txt') || file.name.endsWith('.tsv') || file.type.startsWith('text/')) {
        reader.onload = function(e) {
            processExtractedText(e.target.result);
        };
        reader.readAsText(file);
    } else {
        showToast('Unsupported file type. Please select a PDF, Excel, or CSV file.', 'warning');
        fileInput.value = '';
    }
};

window.openReconMappingModal = function(type, initialText = '', isPdf = false, filename = '') {
    document.getElementById('recon-mapping-type').value = type;
    const rawTextarea = document.getElementById('recon-mapping-raw');
    
    const partyName = document.getElementById(type === 'internal' ? 'recon-company-party-name' : 'recon-customer-identifier').value || filename || 'General';
    const cleanPartyKey = partyName.toLowerCase().replace(/[^a-z0-9]/g, '_');
    
    if (isPdf) {
        rawTextarea.value = '';
        rawTextarea.placeholder = `Copy/paste the transaction rows from your PDF Statement (${filename}) here...`;
        showToast("Open your PDF, copy the transaction rows, and paste them here!", "info", 5000);
    } else {
        rawTextarea.value = initialText;
    }
    
    openModal('recon-mapping-modal');
    window.previewReconMappingColumns(cleanPartyKey);
};

window.previewReconMappingColumns = function(partyKey = '') {
    const type = document.getElementById('recon-mapping-type').value;
    if (!partyKey) {
        const partyName = document.getElementById(type === 'internal' ? 'recon-company-party-name' : 'recon-customer-identifier').value || 'General';
        partyKey = partyName.toLowerCase().replace(/[^a-z0-9]/g, '_');
    }
    
    const rawText = document.getElementById('recon-mapping-raw').value;
    const lines = rawText.split('\n').map(l => l.trim()).filter(l => l !== '');
    
    if (lines.length === 0) {
        document.getElementById('recon-mapping-preview-thead').innerHTML = '<th>No data yet</th>';
        document.getElementById('recon-mapping-preview-tbody').innerHTML = '<tr><td>Pasted rows will appear split here.</td></tr>';
        document.getElementById('recon-mapping-selectors').innerHTML = '';
        return;
    }
    
    let delimiter = /\s{2,}/;
    const firstFew = lines.slice(0, 5);
    let sample = firstFew[0] || '';
    if (sample.includes('\t')) delimiter = '\t';
    else if (sample.includes(',')) delimiter = ',';
    
    const splitRows = lines.map(line => {
        return line.split(delimiter).map(cell => cell.trim()).filter(cell => cell !== '');
    });
    
    let maxCols = 0;
    splitRows.forEach(row => {
        if (row.length > maxCols) maxCols = row.length;
    });
    
    const savedTemplates = JSON.parse(localStorage.getItem('recon_feedback_templates') || '{}');
    const partyTemplate = savedTemplates[partyKey] || {};
    
    const selectorsDiv = document.getElementById('recon-mapping-selectors');
    selectorsDiv.innerHTML = '';
    
    const fields = [
        { value: 'ignore', label: 'L Ignore Column' },
        { value: 'date', label: '=� Date Column' },
        { value: 'ref', label: '=" Invoice / Ref' },
        { value: 'amount', label: '� Amount' },
        { value: 'type', label: '� Dr/Cr' }
    ];
    
    for (let c = 0; c < maxCols; c++) {
        let selectedValue = partyTemplate[c] || 'ignore';
        
        if (!partyTemplate[c]) {
            const dateRegex = /\d{1,4}[-./\\]\d{1,2}[-./\\]\d{1,4}/;
            const wordMonths = /jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec/i;
            const cleanCell = (splitRows[0]?.[c] || '').replace(/[�,]/g, '').trim();
            const num = parseFloat(cleanCell);
            
            if (dateRegex.test(splitRows[0]?.[c] || '') || wordMonths.test(splitRows[0]?.[c] || '')) {
                selectedValue = 'date';
            } else if (!isNaN(num) && num > 0 && splitRows[0]?.[c]?.match(/\d/)) {
                selectedValue = 'amount';
            } else if ((splitRows[0]?.[c] || '').toLowerCase() === 'dr' || (splitRows[0]?.[c] || '').toLowerCase() === 'cr') {
                selectedValue = 'type';
            } else if (c === 1) {
                selectedValue = 'ref';
            }
        }
        
        let selectHtml = `
            <div style="background:var(--bg-secondary); padding:8px; border-radius:6px; border:1px solid var(--border); display:flex; flex-direction:column; gap:4px;">
                <span style="font-size:11px; font-weight:600;">Column ${c + 1}</span>
                <select class="form-input column-selector-dropdown" data-col="${c}" onchange="window.previewReconMappingColumns()" style="font-size:11px; padding:4px 8px; width:140px;">
                    ${fields.map(f => `<option value="${f.value}" ${selectedValue === f.value ? 'selected' : ''}>${f.label}</option>`).join('')}
                </select>
            </div>
        `;
        selectorsDiv.innerHTML += selectHtml;
    }
    
    // Find mapped columns
    let amountColIdx = -1;
    const dropdownSelects = selectorsDiv.querySelectorAll('select');
    dropdownSelects.forEach(sel => {
        if (sel.value === 'amount') {
            amountColIdx = parseInt(sel.getAttribute('data-col'));
        }
    });

    const thead = document.getElementById('recon-mapping-preview-thead');
    thead.innerHTML = '<th style="text-align:center; width: 90px;">Action</th>';
    for (let c = 0; c < maxCols; c++) {
        thead.innerHTML += `<th>Column ${c + 1}</th>`;
    }
    
    const tbody = document.getElementById('recon-mapping-preview-tbody');
    tbody.innerHTML = '';
    splitRows.forEach(row => {
        let hasAmountVal = false;
        if (amountColIdx !== -1 && row[amountColIdx]) {
            const cleanAmt = parseFloat(row[amountColIdx].replace(/[�,]/g, '').trim());
            if (!isNaN(cleanAmt) && cleanAmt > 0) {
                hasAmountVal = true;
            }
        } else {
            row.forEach(cell => {
                const cleanAmt = parseFloat(cell.replace(/[�,]/g, '').trim());
                if (!isNaN(cleanAmt) && cleanAmt > 0 && !cell.includes('-') && !cell.includes('/') && cell.match(/\d/)) {
                    hasAmountVal = true;
                }
            });
        }

        const isImported = hasAmountVal;
        const rowStyle = isImported ? '' : 'style="opacity: 0.55; background: var(--bg-secondary);"';
        const badgeHtml = isImported 
            ? '<span class="badge badge-success" style="font-size:10px; padding:2px 6px; font-weight:700;"> Import</span>' 
            : '<span class="badge badge-secondary" style="font-size:10px; padding:2px 6px; opacity:0.7;">L Ignore</span>';

        let trHtml = `<tr ${rowStyle}>`;
        trHtml += `<td style="text-align:center;">${badgeHtml}</td>`;
        for (let c = 0; c < maxCols; c++) {
            trHtml += `<td>${row[c] || '-'}</td>`;
        }
        trHtml += '</tr>';
        tbody.innerHTML += trHtml;
    });
};

window.saveReconMappingFeedback = function() {
    const type = document.getElementById('recon-mapping-type').value;
    const rawText = document.getElementById('recon-mapping-raw').value;
    const dropdowns = document.querySelectorAll('.column-selector-dropdown');
    
    const partyName = document.getElementById(type === 'internal' ? 'recon-company-party-name' : 'recon-customer-identifier').value || 'General';
    const cleanPartyKey = partyName.toLowerCase().replace(/[^a-z0-9]/g, '_');
    
    let templateConfig = {};
    dropdowns.forEach(dd => {
        const colIndex = dd.getAttribute('data-col');
        templateConfig[colIndex] = dd.value;
    });
    
    const savedTemplates = JSON.parse(localStorage.getItem('recon_feedback_templates') || '{}');
    savedTemplates[cleanPartyKey] = templateConfig;
    localStorage.setItem('recon_feedback_templates', JSON.stringify(savedTemplates));
    
    const lines = rawText.split('\n').map(l => l.trim()).filter(l => l !== '');
    if (lines.length === 0) {
        closeModal('recon-mapping-modal');
        return;
    }
    
    let delimiter = /\s{2,}/;
    const hasTab = lines.some(l => l.includes('\t'));
    if (hasTab) {
        delimiter = '\t';
    } else if (lines[0] && lines[0].includes(',')) {
        delimiter = ',';
    }
    
    let parsedLines = [];
    lines.forEach(line => {
        const parts = line.split(delimiter).map(p => p.trim());
        if (parts.length === 0 || (parts.length === 1 && parts[0] === '')) return;
        
        let date = '';
        let ref = '';
        let amount = 0;
        let txnType = type === 'internal' ? 'Dr' : 'Cr';
        
        Object.keys(templateConfig).forEach(colIdx => {
            const val = parts[colIdx] || '';
            const mappedField = templateConfig[colIdx];
            
            if (mappedField === 'date') {
                date = val;
            } else if (mappedField === 'ref') {
                ref = val;
            } else if (mappedField === 'amount') {
                amount = parseFloat(val.replace(/[�,]/g, '')) || 0;
            } else if (mappedField === 'type') {
                if (val.toLowerCase().includes('dr') || val.toLowerCase().includes('debit')) txnType = 'Dr';
                if (val.toLowerCase().includes('cr') || val.toLowerCase().includes('credit')) txnType = 'Cr';
            }
        });
        
        if (!date) date = new Date().toLocaleDateString('en-IN');
        if (!ref) ref = 'Txn-' + Math.floor(1000 + Math.random() * 9000);
        
        if (amount > 0) {
            parsedLines.push(`${date}\t${ref}\t${amount}\t${txnType}`);
        }
    });
    
    document.getElementById(`recon-${type}-paste`).value = parsedLines.join('\n');
    closeModal('recon-mapping-modal');
    showToast(`Learned column mappings for "${partyName}"! Re-running match...`, 'success');
    window.runReconMatch();
};

window.runReconMatch = function() {
    const internalText = document.getElementById('recon-internal-paste').value;
    const customerText = document.getElementById('recon-customer-paste').value;

    if (!internalText.trim() && !customerText.trim()) {
        document.getElementById('recon-our-tbody').innerHTML = '<tr><td colspan="6" style="text-align:center; color:var(--text-secondary);">No transactions loaded.</td></tr>';
        document.getElementById('recon-customer-tbody').innerHTML = '<tr><td colspan="6" style="text-align:center; color:var(--text-secondary);">No transactions loaded.</td></tr>';
        document.getElementById('recon-our-count').textContent = '0 Rows';
        document.getElementById('recon-customer-count').textContent = '0 Rows';
        
        // Reset summary metrics
        document.getElementById('rep-our-balance').textContent = '�0.00';
        document.getElementById('rep-add-cust-pay').textContent = '+ �0.00';
        document.getElementById('rep-add-our-inv').textContent = '+ �0.00';
        document.getElementById('rep-less-our-pay').textContent = '- �0.00';
        document.getElementById('rep-less-cust-inv').textContent = '- �0.00';
        document.getElementById('rep-cust-adjusted').textContent = '�0.00';
        document.getElementById('rep-cust-actual').textContent = '�0.00';
        document.getElementById('rep-unreconciled-diff').textContent = '�0.00';
        return;
    }

    // Auto-scan pasted text for opening and closing balances
    const opRegex = /(dr|cr)?\s*opening\s*bal(?:ance)?(?:\.|=|\s|:|rs)*\s*([0-9,.]+)\s*(dr|cr)?/i;
    
    // Internal Books
    if (internalText.trim()) {
        const ourOpInput = document.getElementById('recon-our-opening');
        const ourOpSelect = document.getElementById('recon-our-opening-type');
        if (ourOpInput && (parseFloat(ourOpInput.value) || 0) === 0) {
            const match = internalText.match(opRegex);
            if (match) {
                const val = parseFloat(match[2].replace(/,/g, '')) || 0;
                if (val > 0) {
                    ourOpInput.value = val;
                    const rawType = (match[1] || match[3] || '').toUpperCase();
                    if (ourOpSelect) ourOpSelect.value = rawType === 'CR' ? 'Cr' : 'Dr';
                }
            }
        }
    }

    // Customer Books
    if (customerText.trim()) {
        const custOpInput = document.getElementById('recon-customer-opening');
        const custOpSelect = document.getElementById('recon-customer-opening-type');
        if (custOpInput && (parseFloat(custOpInput.value) || 0) === 0) {
            const match = customerText.match(opRegex);
            if (match) {
                const val = parseFloat(match[2].replace(/,/g, '')) || 0;
                if (val > 0) {
                    custOpInput.value = val;
                    const rawType = (match[1] || match[3] || '').toUpperCase();
                    if (custOpSelect) custOpSelect.value = rawType === 'DR' ? 'Dr' : 'Cr';
                }
            }
        }

        const custClInput = document.getElementById('recon-customer-actual-input');
        const custClSelect = document.getElementById('recon-customer-actual-type');
        if (custClInput && (parseFloat(custClInput.value) || 0) === 0) {
            const clRegex = /(dr|cr)?\s*(?:closing\s*bal(?:ance)?|bal(?:ance)?\s*c\/[fd]|closing)(?:\.|=|\s|:|rs)*\s*([0-9,.]+)\s*(dr|cr)?/i;
            const match = customerText.match(clRegex);
            if (match) {
                const val = parseFloat(match[2].replace(/,/g, '')) || 0;
                if (val > 0) {
                    custClInput.value = val;
                    const rawType = (match[1] || match[3] || '').toUpperCase();
                    if (custClSelect) custClSelect.value = rawType === 'CR' ? 'Cr' : 'Dr';
                }
            }
        }
    }

    const parseLines = (text, isOurBooks) => {
        const correctType = (refVal, currentType) => {
            const refLower = String(refVal || '').toLowerCase();
            const partyTypeToggle = document.getElementById('recon-party-type-toggle');
            const isVendor = partyTypeToggle ? (partyTypeToggle.value === 'Vendor') : true;

            if (isVendor) {
                if (refLower.includes('tds') || refLower.includes('payment') || refLower.includes('pymt') || refLower.includes('bank') || refLower.includes('cash') || refLower.includes('canara') || refLower.includes('icici')) {
                    return isOurBooks ? 'Dr' : 'Cr';
                } else if (refLower.includes('purchase') || refLower.includes('purc') || refLower.includes('job work') || refLower.includes('invoice') || refLower.includes('bill')) {
                    return isOurBooks ? 'Cr' : 'Dr';
                }
            } else {
                if (refLower.includes('tds') || refLower.includes('payment') || refLower.includes('pymt') || refLower.includes('bank') || refLower.includes('cash') || refLower.includes('canara') || refLower.includes('icici') || refLower.includes('receipt') || refLower.includes('rcpt')) {
                    return isOurBooks ? 'Cr' : 'Dr';
                } else if (refLower.includes('sale') || refLower.includes('sales') || refLower.includes('invoice') || refLower.includes('bill')) {
                    return isOurBooks ? 'Dr' : 'Cr';
                }
            }
            return currentType;
        };

        const lines = text.split('\n');
        let parsed = [];
        lines.forEach(rawLine => {
            if (!rawLine.trim()) return;
            const line = rawLine
                .replace(/([a-zA-Z])(\d)/g, '$1 $2')
                .replace(/(\d)([a-zA-Z])/g, '$1 $2');
            const lowerLine = line.toLowerCase();
            if (lowerLine.includes('account :') || lowerLine.includes('opening bal') || lowerLine.includes('closing bal') || lowerLine.includes('closing balance') || lowerLine.includes('opening balance') || lowerLine.includes('ledger account')) {
                return;
            }
            let parts = [];
            if (line.includes('\t')) {
                parts = line.split('\t');
            } else if (line.includes(',')) {
                parts = line.split(',');
            } else {
                parts = line.split(/\s{2,}/);
                if (parts.length < 2) {
                    parts = line.split(/\s+/);
                }
            }
            parts = parts.map(p => p.trim()).filter(p => p !== '');
            if (parts.length < 1) return;

            // Direct parser for standard tab/comma delimited columns (bypasses heuristics to prevent date-year amount/type mismatch)
            if ((line.includes('\t') || line.includes(',')) && (parts.length === 4 || parts.length === 5)) {
                let isFiveCols = false;
                let testAmtVal = parseFloat((parts[3] || '').replace(/[�,]/g, ''));
                if (!isNaN(testAmtVal) && testAmtVal > 0) {
                    isFiveCols = true;
                }
                
                let testAmtValFour = parseFloat((parts[2] || '').replace(/[�,]/g, ''));
                
                if (isFiveCols) {
                    const dateVal = parts[0];
                    const refVal = parts[1];
                    const docNoVal = parts[2];
                    const amtVal = testAmtVal;
                    const typeVal = (parts[4] === 'Dr' || parts[4] === 'Cr') ? parts[4] : (isOurBooks ? 'Dr' : 'Cr');
                    parsed.push({
                        date: dateVal,
                        ref: refVal.slice(0, 60),
                        docNo: docNoVal || '-',
                        amount: amtVal,
                        type: correctType(line, typeVal),
                        matched: false
                    });
                    return;
                } else if (!isNaN(testAmtValFour) && testAmtValFour > 0) {
                    const dateVal = parts[0];
                    const refVal = parts[1];
                    const docNoVal = '-';
                    const amtVal = testAmtValFour;
                    const typeVal = (parts[3] === 'Dr' || parts[3] === 'Cr') ? parts[3] : (isOurBooks ? 'Dr' : 'Cr');
                    parsed.push({
                        date: dateVal,
                        ref: refVal.slice(0, 60),
                        docNo: docNoVal || '-',
                        amount: amtVal,
                        type: correctType(line, typeVal),
                        matched: false
                    });
                    return;
                }
            }

            let date = '';
            const dateRegex = /\d{1,4}[-./\\]\d{1,2}[-./\\]\d{1,4}/;
            const wordMonths = /jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec/i;

            parts.forEach(part => {
                if (dateRegex.test(part) || wordMonths.test(part)) {
                    if (!date) date = part;
                }
            });

            if (!date) {
                if (lowerLine.includes('tds') && parsed.length > 0) {
                    date = parsed[parsed.length - 1].date;
                } else if (parts[0] && (parts[0].includes('-') || parts[0].includes('/') || parts[0].includes('.'))) {
                    date = parts[0];
                } else {
                    if (parsed.length > 0) {
                        const lastTx = parsed[parsed.length - 1];
                        const rawLine = line.trim();
                        const billMatch = rawLine.match(/(?:bill\s*no|vch\s*no|voucher\s*no|inv\s*no|invoice\s*no|ref\s*no|bill|vch|inv|ref|doc)[:.-]?\s*([a-zA-Z0-9-/]+)/i);
                        if (billMatch) {
                            const extractedDoc = billMatch[1];
                            if (extractedDoc && !/^\d{10,}$/.test(extractedDoc)) {
                                lastTx.docNo = extractedDoc;
                            }
                        } else if (rawLine.match(/^[a-zA-Z0-9-/]{2,15},?$/)) {
                            const cleanCode = rawLine.replace(/,/g, '').trim();
                            if (cleanCode && !/^\d{10,}$/.test(cleanCode)) {
                                lastTx.docNo = cleanCode;
                            }
                        }
                    }
                    return;
                }
            }

            const lineWithoutDate = line.replace(date, '');
            const numberMatches = lineWithoutDate.match(/\b\d{1,3}(?:,\d{2,3})*(?:\.\d+)?\b/g) || [];
            let nums = numberMatches
                .map(n => parseFloat(n.replace(/,/g, '')))
                .filter(n => n > 0 && !/^\d{10,}$/.test(String(n)));

            const percentMatches = lineWithoutDate.match(/(\d+(?:\.\d+)?)\s*%/g) || [];
            percentMatches.forEach(pMatch => {
                const pVal = parseFloat(pMatch);
                const pIdx = nums.indexOf(pVal);
                if (pIdx !== -1) nums.splice(pIdx, 1);
            });

            const hasBalanceSuffix = /\b(dr|cr)\b$/i.test(line.trim());
            let amt = 0;
            let docNo = '';

            if (hasBalanceSuffix) {
                if (nums.length >= 2) {
                    amt = nums[nums.length - 2];
                } else if (nums.length === 1) {
                    amt = nums[0];
                }
            } else {
                if (nums.length >= 1) {
                    amt = nums[nums.length - 1];
                }
            }

            let possibleDocNumbers = [];
            if (nums.length > 0) {
                const amtIdx = nums.indexOf(amt);
                if (amtIdx > 0) {
                    possibleDocNumbers = nums.slice(0, amtIdx);
                } else if (amtIdx === -1 && nums.length > 1) {
                    possibleDocNumbers = nums.slice(0, nums.length - 1);
                }
            }
            if (possibleDocNumbers.length > 0) {
                docNo = String(possibleDocNumbers[possibleDocNumbers.length - 1]);
            }

            let ref = lineWithoutDate;
            numberMatches.forEach(nStr => {
                ref = ref.replace(nStr, '');
            });
            ref = ref.replace(/\b(dr|cr|debit|credit|pymt|purc|payment|purchase|receipt|journal|jv)\b/gi, '');
            ref = ref.replace(/\s+/g, ' ').trim();
            if (!ref || ref === 'N/A') ref = 'Txn-' + Math.floor(1000 + Math.random() * 9000);

            let type = isOurBooks ? 'Dr' : 'Cr';
            let explicitType = '';

            // Clean Tally running balance Dr/Cr indicator at the beginning and end
            let typeCheckLine = line.trim();
            const dateM = typeCheckLine.match(dateRegex);
            if (dateM) {
                typeCheckLine = typeCheckLine.replace(dateM[0], '').trim();
            }
            typeCheckLine = typeCheckLine.replace(/^(dr|cr)\b/i, '').trim();
            typeCheckLine = typeCheckLine.replace(/\b(dr|cr)\s*$/i, '').trim();

            if (/\b(dr|deb|debit)\b/i.test(typeCheckLine)) {
                explicitType = 'Dr';
            } else if (/\b(cr|cre|credit)\b/i.test(typeCheckLine)) {
                explicitType = 'Cr';
            }

            if (explicitType) {
                type = explicitType;
            } else {
                const partyTypeToggle = document.getElementById('recon-party-type-toggle');
                const isVendor = partyTypeToggle ? (partyTypeToggle.value === 'Vendor') : true;

                if (isVendor) {
                    if (lowerLine.includes('pymt') || lowerLine.includes('payment') || lowerLine.includes('bank') || lowerLine.includes('cash') || lowerLine.includes('tds') || lowerLine.includes('rcpt') || lowerLine.includes('receipt')) {
                        type = isOurBooks ? 'Dr' : 'Cr';
                    } else if (lowerLine.includes('purc') || lowerLine.includes('purchase') || lowerLine.includes('sale') || lowerLine.includes('invoice') || lowerLine.includes('bill')) {
                        type = isOurBooks ? 'Cr' : 'Dr';
                    }
                } else {
                    if (lowerLine.includes('rcpt') || lowerLine.includes('receipt') || lowerLine.includes('bank') || lowerLine.includes('cash') || lowerLine.includes('tds') || lowerLine.includes('pymt') || lowerLine.includes('payment')) {
                        type = isOurBooks ? 'Cr' : 'Dr';
                    } else if (lowerLine.includes('sale') || lowerLine.includes('invoice') || lowerLine.includes('bill') || lowerLine.includes('purc') || lowerLine.includes('purchase')) {
                        type = isOurBooks ? 'Dr' : 'Cr';
                    }
                }
            }

            if (amt > 0) {
                parsed.push({
                    date: date,
                    ref: ref.slice(0, 60),
                    docNo: docNo || '-',
                    amount: amt,
                    type: correctType(line, type),
                    matched: false,
                    matchRef: ''
                });
            } else {
                if (parsed.length > 0) {
                    const lastTx = parsed[parsed.length - 1];
                    const rawLine = line.trim();
                    const billMatch = rawLine.match(/(?:bill\s*no|vch\s*no|voucher\s*no|inv\s*no|invoice\s*no|ref\s*no|bill|vch|inv|ref|doc)[:.-]?\s*([a-zA-Z0-9-/]+)/i);
                    if (billMatch) {
                        const extractedDoc = billMatch[1];
                        if (extractedDoc && !/^\d{10,}$/.test(extractedDoc)) {
                            lastTx.docNo = extractedDoc;
                        }
                    } else if (rawLine.match(/^[a-zA-Z0-9-/]{2,15},?$/)) {
                        const cleanCode = rawLine.replace(/,/g, '').trim();
                        if (cleanCode && !/^\d{10,}$/.test(cleanCode)) {
                            lastTx.docNo = cleanCode;
                        }
                    }
                }
            }
        });
        return parsed;
    };

    const ourBooks = parseLines(internalText, true);
    const customerBooks = parseLines(customerText, false);

    const partyTypeToggle = document.getElementById('recon-party-type-toggle');
    const partyTypeLabel = partyTypeToggle ? partyTypeToggle.value : 'Customer';
    const isVendorMode = partyTypeLabel === 'Vendor';
    const partyStatementLabel = partyTypeLabel + ' Statement';

    const partyNameVal = document.getElementById('recon-company-party-name').value || 'General';
    const partyKeyVal = partyNameVal.toLowerCase().replace(/[^a-z0-9]/g, '_');

    const customAdditions = JSON.parse(localStorage.getItem(`recon_custom_additions_${partyKeyVal}`) || '[]');
    customAdditions.forEach(add => {
        const row = {
            date: add.date,
            ref: add.ref,
            docNo: add.docNo || '',
            amount: parseFloat(add.amount) || 0,
            type: add.type,
            key: add.key,
            isCustomAdded: true,
            category: add.category || 'auto'
        };
        if (add.isOurBooks) {
            ourBooks.push(row);
        } else {
            customerBooks.push(row);
        }
    });

    window.lastParsedOurBooks = ourBooks;
    window.lastParsedCustomerBooks = customerBooks;

    // Dynamic UI labels
    const custPanelHeader = document.getElementById('recon-customer-panel-header-title');
    if (custPanelHeader) custPanelHeader.textContent = `=� ${partyTypeLabel} Books (Their Statement)`;

    const custNameLabel = document.getElementById('recon-customer-name-label');
    if (custNameLabel) custNameLabel.textContent = `${partyTypeLabel} Name / Identifier`;

    const uploadCustLabel = document.getElementById('recon-upload-customer-label');
    if (uploadCustLabel) uploadCustLabel.textContent = `Upload ${partyTypeLabel} Statement (CSV, PDF, Excel)`;

    const pasteCustLabel = document.getElementById('recon-paste-customer-label');
    if (pasteCustLabel) pasteCustLabel.textContent = `Or Paste ${partyTypeLabel} Statement Transactions`;

    const custHeader = document.getElementById('recon-customer-header-title');
    if (custHeader) custHeader.textContent = `=� Transactions in ${partyTypeLabel} Books`;

    const repAdjustedLabel = document.getElementById('rep-adjusted-balance-label');
    if (repAdjustedLabel) {
        const balSuffix = partyTypeLabel === 'Vendor' ? '(Debit Balance)' : '(Credit Balance)';
        repAdjustedLabel.textContent = `Adjusted Balance as per ${partyTypeLabel} Books ${balSuffix}`;
    }

    const repActualLabel = document.getElementById('rep-actual-balance-label');
    if (repActualLabel) repActualLabel.textContent = `Actual Balance as per ${partyStatementLabel}`;

    const repAddCustPayLabel = document.getElementById('rep-add-cust-pay-label');
    if (repAddCustPayLabel) repAddCustPayLabel.textContent = `Add: Payments/Receipts in ${partyTypeLabel.toLowerCase()} books but not in our books`;

    const repAddOurInvLabel = document.getElementById('rep-add-our-inv-label');
    if (repAddOurInvLabel) repAddOurInvLabel.textContent = `Add: Invoices/Bills in our books but not in ${partyTypeLabel.toLowerCase()} books`;

    const repAddCustTdsLabel = document.getElementById('rep-add-cust-tds-label');
    if (repAddCustTdsLabel) repAddCustTdsLabel.textContent = `Add: TDS in ${partyTypeLabel.toLowerCase()} books but not in our books`;

    const repLessOurPayLabel = document.getElementById('rep-less-our-pay-label');
    if (repLessOurPayLabel) repLessOurPayLabel.textContent = `Less: Payments/Receipts in our books but not in ${partyTypeLabel.toLowerCase()} books`;

    const repLessCustInvLabel = document.getElementById('rep-less-cust-inv-label');
    if (repLessCustInvLabel) repLessCustInvLabel.textContent = `Less: Invoices/Bills in ${partyTypeLabel.toLowerCase()} books but not in our books`;

    const repLessOurTdsLabel = document.getElementById('rep-less-our-tds-label');
    if (repLessOurTdsLabel) repLessOurTdsLabel.textContent = `Less: TDS in our books but not in ${partyTypeLabel.toLowerCase()} books`;

    const partyName = document.getElementById('recon-company-party-name').value || 'General';
    const partyKey = partyName.toLowerCase().replace(/[^a-z0-9]/g, '_');
    const manualMatches = JSON.parse(localStorage.getItem(`recon_manual_${partyKey}`) || '{}');
    const excludedKeys = JSON.parse(localStorage.getItem(`recon_excluded_${partyKey}`) || '[]');
    const editedAmounts = JSON.parse(localStorage.getItem(`recon_edited_${partyKey}`) || '{}');
    const customEdits = JSON.parse(localStorage.getItem(`recon_custom_edits_${partyKey}`) || '{}');

    // Reset breakdown global arrays
    window.lastReconBreakdown = {
        'add-cust-pay': [],
        'add-our-inv': [],
        'less-our-pay': [],
        'less-cust-inv': [],
        'add-cust-tds': [],
        'less-our-tds': []
    };

    // Assign unique keys to each row for robust correlation & manual match tracking
    ourBooks.forEach((row, idx) => {
        if (!row.key) {
            row.key = `our_${idx}_${row.date}_${row.ref}_${row.amount}_${row.type}`.replace(/[^a-zA-Z0-9_]/g, '');
        }
        if (excludedKeys.includes(row.key)) {
            row.isExcluded = true;
        }
        if (editedAmounts[row.key] !== undefined) {
            row.amount = parseFloat(editedAmounts[row.key]);
        }
        if (customEdits[row.key]) {
            const edit = customEdits[row.key];
            if (edit.amount !== undefined) row.amount = parseFloat(edit.amount);
            if (edit.docNo !== undefined) row.docNo = edit.docNo;
            if (edit.date !== undefined) row.date = edit.date;
            if (edit.ref !== undefined) row.ref = edit.ref;
            if (edit.category !== undefined) row.category = edit.category;
            if (edit.type !== undefined) row.type = edit.type;
        }
    });
    customerBooks.forEach((row, idx) => {
        if (!row.key) {
            row.key = `cust_${idx}_${row.date}_${row.ref}_${row.amount}_${row.type}`.replace(/[^a-zA-Z0-9_]/g, '');
        }
        if (excludedKeys.includes(row.key)) {
            row.isExcluded = true;
        }
        if (editedAmounts[row.key] !== undefined) {
            row.amount = parseFloat(editedAmounts[row.key]);
        }
        if (customEdits[row.key]) {
            const edit = customEdits[row.key];
            if (edit.amount !== undefined) row.amount = parseFloat(edit.amount);
            if (edit.docNo !== undefined) row.docNo = edit.docNo;
            if (edit.date !== undefined) row.date = edit.date;
            if (edit.ref !== undefined) row.ref = edit.ref;
            if (edit.category !== undefined) row.category = edit.category;
            if (edit.type !== undefined) row.type = edit.type;
        }
    });

    // 0. Extract and isolate opening balance rows, sync to input fields
    ourBooks.forEach(row => {
        const desc = row.ref.toLowerCase();
        if (desc.includes('opening') || desc.includes('bal b/f') || desc.includes('bal b/d') || desc.includes('opg bal') || desc.includes('brought forward') || desc.includes('opening balance') || desc.includes('op. bal')) {
            row.isOpening = true;
            row.matched = true;
            const inputEl = document.getElementById('recon-our-opening');
            const selectEl = document.getElementById('recon-our-opening-type');
            if (inputEl && (!parseFloat(inputEl.value) || inputEl.value === '0')) {
                inputEl.value = row.amount;
                if (selectEl) selectEl.value = row.type;
            }
        }
    });

    customerBooks.forEach(row => {
        const desc = row.ref.toLowerCase();
        if (desc.includes('opening') || desc.includes('bal b/f') || desc.includes('bal b/d') || desc.includes('opg bal') || desc.includes('brought forward') || desc.includes('opening balance') || desc.includes('op. bal')) {
            row.isOpening = true;
            row.matched = true;
            const inputEl = document.getElementById('recon-customer-opening');
            const selectEl = document.getElementById('recon-customer-opening-type');
            if (inputEl && (!parseFloat(inputEl.value) || inputEl.value === '0')) {
                inputEl.value = row.amount;
                if (selectEl) selectEl.value = row.type;
            }
        }
    });

    const ourOpeningInput = parseFloat(document.getElementById('recon-our-opening').value) || 0;
    const ourOpeningType = document.getElementById('recon-our-opening-type').value;
    const ourOpeningSigned = ourOpeningType === 'Dr' ? ourOpeningInput : -ourOpeningInput;

    const custOpeningInput = parseFloat(document.getElementById('recon-customer-opening').value) || 0;
    const custOpeningType = document.getElementById('recon-customer-opening-type').value;
    const custOpeningSigned = isVendorMode
        ? (custOpeningType === 'Dr' ? custOpeningInput : -custOpeningInput)
        : (custOpeningType === 'Cr' ? custOpeningInput : -custOpeningInput);

    const custActualInput = parseFloat(document.getElementById('recon-customer-actual-input').value) || 0;
    const custActualType = document.getElementById('recon-customer-actual-type').value;
    const custActualSigned = isVendorMode
        ? (custActualType === 'Dr' ? custActualInput : -custActualInput)
        : (custActualType === 'Cr' ? custActualInput : -custActualInput);

    // Save current values to localStorage for persistence
    const partyNameForSave = document.getElementById('recon-company-party-name').value || 'General';
    const cleanPartyKeyForSave = partyNameForSave.toLowerCase().replace(/[^a-z0-9]/g, '_');
    localStorage.setItem(`recon_opening_our_${cleanPartyKeyForSave}`, ourOpeningInput);
    localStorage.setItem(`recon_opening_our_type_${cleanPartyKeyForSave}`, ourOpeningType);
    localStorage.setItem(`recon_opening_cust_${cleanPartyKeyForSave}`, custOpeningInput);
    localStorage.setItem(`recon_opening_cust_type_${cleanPartyKeyForSave}`, custOpeningType);
    localStorage.setItem(`recon_actual_cust_${cleanPartyKeyForSave}`, custActualInput);
    localStorage.setItem(`recon_actual_cust_type_${cleanPartyKeyForSave}`, custActualType);

    // 1. First apply manually saved match overrides (skipping isolated opening balances)
    ourBooks.forEach(our => {
        if (our.isOpening) return;
        const targetCustKey = manualMatches[our.key];
        if (targetCustKey) {
            const cust = customerBooks.find(c => c.key === targetCustKey);
            if (cust && !cust.isOpening) {
                our.matched = true;
                cust.matched = true;
                our.matchRef = cust.ref;
                cust.matchRef = our.ref;
                our.matchedKey = cust.key;
                cust.matchedKey = our.key;
            }
        }
    });
    customerBooks.forEach(cust => {
        if (cust.isOpening || cust.matched) return;
        const targetOurKey = manualMatches[cust.key];
        if (targetOurKey) {
            const our = ourBooks.find(o => o.key === targetOurKey);
            if (our && !our.isOpening && !our.matched) {
                our.matched = true;
                cust.matched = true;
                our.matchRef = cust.ref;
                cust.matchRef = our.ref;
                our.matchedKey = cust.key;
                cust.matchedKey = our.key;
            }
        }
    });

    const getReconRowCategory = function(ref) {
        const text = String(ref || '').toLowerCase();
        if (text.includes('tds')) return 'TDS';
        if (text.includes('freight') || text.includes('transport') || text.includes('cartage') || text.includes('carriage') || text.includes('loading') || text.includes('unloading')) return 'Freight';
        if (text.includes('bank') || text.includes('canara') || text.includes('icici') || text.includes('rtgs') || text.includes('neft') || text.includes('imps') || text.includes('cheque') || text.includes('chq') || text.includes('pymt') || text.includes('payment') || text.includes('receipt') || text.includes('online') || text.includes('transfer') || text.includes('canara bank')) return 'Bank';
        if (text.includes('purchase') || text.includes('inv') || text.includes('bill') || text.includes('job work') || text.includes('sale') || text.includes('gst sales') || text.includes('sales')) return 'Purchase Invoice';
        return 'Other';
    };

    const getReconCategory = function(row) {
        if (row.category && row.category !== 'auto') {
            const cat = row.category.toLowerCase();
            if (cat === 'invoice') return 'Purchase Invoice';
            if (cat === 'payment') return 'Bank';
            if (cat === 'tds') return 'TDS';
            if (cat === 'freight') return 'Freight';
            return 'Other';
        }
        return getReconRowCategory(row.ref);
    };

    // 2. Run Automatic Matching for remaining unmatched records
    ourBooks.forEach(our => {
        if (our.matched || our.isOpening || our.isExcluded) return;
        customerBooks.forEach(cust => {
            if (cust.matched || cust.isOpening || cust.isExcluded) return;
            
            const docNoMatches = our.docNo && cust.docNo && our.docNo !== '-' && cust.docNo !== '-' && 
                                 our.docNo.toLowerCase().trim() === cust.docNo.toLowerCase().trim();
            const refMatches = String(our.ref).toLowerCase().includes(String(cust.ref).toLowerCase()) ||
                               String(cust.ref).toLowerCase().includes(String(our.ref).toLowerCase());
            const amountMatches = Math.abs(our.amount - cust.amount) < 0.01;
            
            const typesAreOpposite = (our.type === 'Dr' && cust.type === 'Cr') || 
                                     (our.type === 'Cr' && cust.type === 'Dr');

            const ourCat = getReconCategory(our);
            const custCat = getReconCategory(cust);
            const categoryMatches = (ourCat === custCat);

            if (amountMatches && categoryMatches && (docNoMatches || refMatches || typesAreOpposite)) {
                our.matched = true;
                cust.matched = true;
                our.matchRef = cust.ref;
                cust.matchRef = our.ref;
                our.matchedKey = cust.key;
                cust.matchedKey = our.key;
            }
        });
    });

    const filterEl = document.getElementById('recon-filter-select');
    const filterVal = filterEl ? filterEl.value : 'all';

    // Render Our Books Table
    const ourTbody = document.getElementById('recon-our-tbody');
    ourTbody.innerHTML = '';
    let ourBalance = ourOpeningSigned;
    let ourRenderedCount = 0;
    ourBooks.forEach(row => {
        if (!row.isOpening) {
            const drVal = row.type === 'Dr' ? row.amount : 0;
            const crVal = row.type === 'Cr' ? row.amount : 0;
            ourBalance += (drVal - crVal);
        }

        if (filterVal === 'unmatched' && row.matched && !row.isOpening) return;
        if (filterVal === 'matched' && !row.matched && !row.isOpening) return;
        ourRenderedCount++;

        const drVal = row.type === 'Dr' ? row.amount : 0;
        const crVal = row.type === 'Cr' ? row.amount : 0;

        let matchBadge = '';
        if (row.isOpening) {
            matchBadge = `<span class="badge badge-info" style="background:#e0f2fe; color:#0369a1; font-weight:600;">= Starting Balance</span>`;
        } else if (row.isExcluded) {
            matchBadge = `<span class="badge badge-secondary" title="Click to include back" style="background:#fee2e2; color:#ef4444; cursor:pointer;" onclick="window.toggleExcludeTransaction('${row.key}', true)">=� Excluded</span>`;
        } else if (row.matched) {
            matchBadge = `<div style="display:flex; align-items:center; justify-content:center; gap:5px;">
                <span class="badge badge-success" title="Click to break match" style="cursor:pointer;" onclick="window.unmatchRows('${row.key}', '${row.matchedKey}')"> Matched</span>
                <button class="btn btn-sm btn-outline-primary" style="padding:1px 5px; font-size:10px; cursor:pointer;" onclick="window.editReconRow('${row.key}', true)" title="Edit details"></button>
            </div>`;
        } else {
            let badgeContent = '';
            if (window.activeManualMatchKey) {
                if (window.activeManualMatchSide === false) {
                    badgeContent = `<button class="btn btn-primary" style="font-size:10px; padding:2px 6px;" onclick="window.completeManualMatch('${row.key}')">= Connect Match</button>`;
                } else if (window.activeManualMatchKey === row.key) {
                    badgeContent = `<span class="badge badge-warning" style="cursor:pointer;" onclick="window.cancelManualMatch()">� Selecting... (Cancel)</span>`;
                } else {
                    badgeContent = `<span class="badge badge-secondary" style="background:#fee2e2; color:#ef4444; opacity: 0.5;">L Unmatched</span>`;
                }
            } else {
                badgeContent = `<span class="badge badge-secondary" title="Click to manually match" style="background:#fee2e2; color:#ef4444; cursor:pointer;" onclick="window.startManualMatch('${row.key}', true)">L Unmatched</span>`;
            }
            matchBadge = `<div style="display:flex; align-items:center; justify-content:center; gap:5px;">
                ${badgeContent}
                <button class="btn btn-sm btn-outline-primary" style="padding:1px 5px; font-size:10px; cursor:pointer;" onclick="window.editReconRow('${row.key}', true)" title="Edit details"></button>
            </div>`;
        }

        const activeRowStyle = (window.activeManualMatchKey === row.key) ? 'style="border: 2px solid var(--primary); background: rgba(79,125,255,0.08);"' : '';

        const tr = document.createElement('tr');
        if (activeRowStyle) tr.setAttribute('style', 'border: 2px solid var(--primary); background: rgba(79,125,255,0.08);');
        if (row.isOpening) {
            tr.innerHTML = `
                <td>${row.date}</td>
                <td style="font-weight:600;">${row.ref}</td>
                <td>${row.docNo || '-'}</td>
                <td style="text-align:right;">${drVal > 0 ? `�${drVal.toLocaleString('en-IN', {minimumFractionDigits:2})}` : '-'}</td>
                <td style="text-align:right;">${crVal > 0 ? `�${crVal.toLocaleString('en-IN', {minimumFractionDigits:2})}` : '-'}</td>
                <td style="text-align:center;">
                    ${matchBadge}
                </td>
            `;
        } else {
            tr.innerHTML = `
                <td><input class="recon-inline-edit" type="text" value="${row.date}" onchange="window.saveReconField('${row.key}', 'date', this.value, true)"></td>
                <td style="font-weight:600;"><input class="recon-inline-edit" type="text" value="${row.ref.replace(/"/g, '&quot;')}" style="font-weight:600;" onchange="window.saveReconField('${row.key}', 'ref', this.value, true)"></td>
                <td><input class="recon-inline-edit" type="text" value="${(row.docNo || '').replace(/"/g, '&quot;')}" placeholder="-" onchange="window.saveReconField('${row.key}', 'docNo', this.value, true)"></td>
                <td><input class="recon-inline-edit" style="text-align:right;" type="text" value="${drVal > 0 ? drVal.toFixed(2) : ''}" placeholder="-" onchange="window.saveReconFieldAmount('${row.key}', 'Dr', this.value, true)"></td>
                <td><input class="recon-inline-edit" style="text-align:right;" type="text" value="${crVal > 0 ? crVal.toFixed(2) : ''}" placeholder="-" onchange="window.saveReconFieldAmount('${row.key}', 'Cr', this.value, true)"></td>
                <td style="text-align:center;">
                    ${matchBadge}
                </td>
            `;
        }
        ourTbody.appendChild(tr);
    });
    document.getElementById('recon-our-count').textContent = `${ourRenderedCount} Rows`;

    // Render Customer Books Table
    const custTbody = document.getElementById('recon-customer-tbody');
    custTbody.innerHTML = '';
    let custRunningSumBalance = custOpeningSigned;
    let custRenderedCount = 0;
    customerBooks.forEach(row => {
        if (!row.isOpening) {
            const drVal = row.type === 'Dr' ? row.amount : 0;
            const crVal = row.type === 'Cr' ? row.amount : 0;
            if (isVendorMode) {
                custRunningSumBalance += (drVal - crVal);
            } else {
                custRunningSumBalance += (crVal - drVal);
            }
        }

        if (filterVal === 'unmatched' && row.matched && !row.isOpening) return;
        if (filterVal === 'matched' && !row.matched && !row.isOpening) return;
        custRenderedCount++;

        const drVal = row.type === 'Dr' ? row.amount : 0;
        const crVal = row.type === 'Cr' ? row.amount : 0;

        let matchBadge = '';
        if (row.isOpening) {
            matchBadge = `<span class="badge badge-info" style="background:#e0f2fe; color:#0369a1; font-weight:600;">= Starting Balance</span>`;
        } else if (row.isExcluded) {
            matchBadge = `<span class="badge badge-secondary" title="Click to include back" style="background:#fee2e2; color:#ef4444; cursor:pointer;" onclick="window.toggleExcludeTransaction('${row.key}', true)">=� Excluded</span>`;
        } else if (row.matched) {
            matchBadge = `<div style="display:flex; align-items:center; justify-content:center; gap:5px;">
                <span class="badge badge-success" title="Click to break match" style="cursor:pointer;" onclick="window.unmatchRows('${row.matchedKey}', '${row.key}')"> Matched</span>
                <button class="btn btn-sm btn-outline-primary" style="padding:1px 5px; font-size:10px; cursor:pointer;" onclick="window.editReconRow('${row.key}', false)" title="Edit details"></button>
            </div>`;
        } else {
            let badgeContent = '';
            if (window.activeManualMatchKey) {
                if (window.activeManualMatchSide === true) {
                    badgeContent = `<button class="btn btn-primary" style="font-size:10px; padding:2px 6px;" onclick="window.completeManualMatch('${row.key}')">= Connect Match</button>`;
                } else if (window.activeManualMatchKey === row.key) {
                    badgeContent = `<span class="badge badge-warning" style="cursor:pointer;" onclick="window.cancelManualMatch()">� Selecting... (Cancel)</span>`;
                } else {
                    badgeContent = `<span class="badge badge-secondary" style="background:#fee2e2; color:#ef4444; opacity: 0.5;">L Unmatched</span>`;
                }
            } else {
                badgeContent = `<span class="badge badge-secondary" title="Click to manually match" style="background:#fee2e2; color:#ef4444; cursor:pointer;" onclick="window.startManualMatch('${row.key}', false)">L Unmatched</span>`;
            }
            matchBadge = `<div style="display:flex; align-items:center; justify-content:center; gap:5px;">
                ${badgeContent}
                <button class="btn btn-sm btn-outline-primary" style="padding:1px 5px; font-size:10px; cursor:pointer;" onclick="window.editReconRow('${row.key}', false)" title="Edit details"></button>
            </div>`;
        }

        const activeRowStyle = (window.activeManualMatchKey === row.key) ? 'style="border: 2px solid var(--primary); background: rgba(79,125,255,0.08);"' : '';

        const tr = document.createElement('tr');
        if (activeRowStyle) tr.setAttribute('style', 'border: 2px solid var(--primary); background: rgba(79,125,255,0.08);');
        if (row.isOpening) {
            tr.innerHTML = `
                <td>${row.date}</td>
                <td style="font-weight:600;">${row.ref}</td>
                <td>${row.docNo || '-'}</td>
                <td style="text-align:right;">${drVal > 0 ? `�${drVal.toLocaleString('en-IN', {minimumFractionDigits:2})}` : '-'}</td>
                <td style="text-align:right;">${crVal > 0 ? `�${crVal.toLocaleString('en-IN', {minimumFractionDigits:2})}` : '-'}</td>
                <td style="text-align:center;">
                    ${matchBadge}
                </td>
            `;
        } else {
            tr.innerHTML = `
                <td><input class="recon-inline-edit" type="text" value="${row.date}" onchange="window.saveReconField('${row.key}', 'date', this.value, false)"></td>
                <td style="font-weight:600;"><input class="recon-inline-edit" type="text" value="${row.ref.replace(/"/g, '&quot;')}" style="font-weight:600;" onchange="window.saveReconField('${row.key}', 'ref', this.value, false)"></td>
                <td><input class="recon-inline-edit" type="text" value="${(row.docNo || '').replace(/"/g, '&quot;')}" placeholder="-" onchange="window.saveReconField('${row.key}', 'docNo', this.value, false)"></td>
                <td><input class="recon-inline-edit" style="text-align:right;" type="text" value="${drVal > 0 ? drVal.toFixed(2) : ''}" placeholder="-" onchange="window.saveReconFieldAmount('${row.key}', 'Dr', this.value, false)"></td>
                <td><input class="recon-inline-edit" style="text-align:right;" type="text" value="${crVal > 0 ? crVal.toFixed(2) : ''}" placeholder="-" onchange="window.saveReconFieldAmount('${row.key}', 'Cr', this.value, false)"></td>
                <td style="text-align:center;">
                    ${matchBadge}
                </td>
            `;
        }
        custTbody.appendChild(tr);
    });
    document.getElementById('recon-customer-count').textContent = `${custRenderedCount} Rows`;

    // Calculate Reconciliation Statement items
    let addCustPayTotal = 0; // Payments in customer statement but not in our books
    let addOurInvTotal = 0;  // Invoices in our books but not in customer statement
    let addCustTdsTotal = 0; // TDS in customer statement but not in our books
    let lessOurPayTotal = 0; // Payments in our books but not in customer statement
    let lessCustInvTotal = 0; // Invoices in customer books but not in our books
    let lessOurTdsTotal = 0; // TDS in our books but not in customer statement


    customerBooks.forEach(row => {
        if (row.isOpening) return;
        const isTds = row.category === 'tds' || (row.category !== 'other' && row.category !== 'payment' && row.category !== 'invoice' && row.ref.toLowerCase().includes('tds'));
        if (!row.matched && !row.isExcluded) {
            if (isTds) {
                addCustTdsTotal += row.amount;
                window.lastReconBreakdown['add-cust-tds'].push(row);
            } else {
                // In Vendor mode (customerBooks is Vendor statement): Dr is Invoice, Cr is Payment
                // In Customer mode (customerBooks is Customer statement): Dr is Payment, Cr is Invoice
                const isInvoice = row.category === 'invoice' || (row.category !== 'payment' && (isVendorMode ? (row.type === 'Dr') : (row.type === 'Cr')));
                if (isInvoice) {
                    lessCustInvTotal += row.amount;
                    window.lastReconBreakdown['less-cust-inv'].push(row);
                } else {
                    addCustPayTotal += row.amount;
                    window.lastReconBreakdown['add-cust-pay'].push(row);
                }
            }
        } else if (row.isExcluded) {
            if (isTds) {
                window.lastReconBreakdown['add-cust-tds'].push(row);
            } else {
                const isInvoice = row.category === 'invoice' || (row.category !== 'payment' && (isVendorMode ? (row.type === 'Dr') : (row.type === 'Cr')));
                if (isInvoice) {
                    window.lastReconBreakdown['less-cust-inv'].push(row);
                } else {
                    window.lastReconBreakdown['add-cust-pay'].push(row);
                }
            }
        }
    });

    ourBooks.forEach(row => {
        if (row.isOpening) return;
        const isTds = row.category === 'tds' || (row.category !== 'other' && row.category !== 'payment' && row.category !== 'invoice' && row.ref.toLowerCase().includes('tds'));
        if (!row.matched && !row.isExcluded) {
            if (isTds) {
                lessOurTdsTotal += row.amount;
                window.lastReconBreakdown['less-our-tds'].push(row);
            } else {
                // In Our Books:
                // If isVendorMode is true: Dr is Payment, Cr is Invoice
                // If isVendorMode is false: Dr is Invoice, Cr is Payment
                const isInvoice = row.category === 'invoice' || (row.category !== 'payment' && (isVendorMode ? (row.type === 'Cr') : (row.type === 'Dr')));
                if (isInvoice) {
                    addOurInvTotal += row.amount;
                    window.lastReconBreakdown['add-our-inv'].push(row);
                } else {
                    lessOurPayTotal += row.amount;
                    window.lastReconBreakdown['less-our-pay'].push(row);
                }
            }
        } else if (row.isExcluded) {
            if (isTds) {
                window.lastReconBreakdown['less-our-tds'].push(row);
            } else {
                const isInvoice = row.category === 'invoice' || (row.category !== 'payment' && (isVendorMode ? (row.type === 'Cr') : (row.type === 'Dr')));
                if (isInvoice) {
                    window.lastReconBreakdown['add-our-inv'].push(row);
                } else {
                    window.lastReconBreakdown['less-our-pay'].push(row);
                }
            }
        }
    });

    // Opening balance difference factor
    const openingDiff = ourOpeningSigned - custOpeningSigned;
    const openingDiffFactor = (isVendorMode ? openingDiff : -openingDiff);
    const custActualBalance = custActualInput > 0 ? custActualSigned : custRunningSumBalance;
    const adjustedCustBalance = ourBalance + addCustPayTotal + addOurInvTotal + addCustTdsTotal - lessOurPayTotal - lessCustInvTotal - lessOurTdsTotal + openingDiffFactor;
    const diff = Math.abs(adjustedCustBalance - custActualBalance);

    // Update reconciliation summary text fields
    const ourBalanceLabelSuffix = ourBalance >= 0 ? '(Debit Balance)' : '(Credit Balance)';
    const ourBalanceLabelEl = document.getElementById('rep-our-balance-label');
    if (ourBalanceLabelEl) ourBalanceLabelEl.textContent = `Balance as per Company Books ${ourBalanceLabelSuffix}`;
    document.getElementById('rep-our-balance').textContent = `�${Math.abs(ourBalance).toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('rep-add-cust-pay').textContent = `+ �${addCustPayTotal.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('rep-add-our-inv').textContent = `+ �${addOurInvTotal.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('rep-add-cust-tds').textContent = `+ �${addCustTdsTotal.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('rep-less-our-pay').textContent = `- �${lessOurPayTotal.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('rep-less-cust-inv').textContent = `- �${lessCustInvTotal.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('rep-less-our-tds').textContent = `- �${lessOurTdsTotal.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('rep-opening-diff').textContent = `${openingDiffFactor >= 0 ? '+' : '-'} �${Math.abs(openingDiffFactor).toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('rep-cust-adjusted').textContent = `�${adjustedCustBalance.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('rep-cust-actual').textContent = `�${custActualBalance.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('rep-unreconciled-diff').textContent = `�${diff.toLocaleString('en-IN', {minimumFractionDigits:2})}`;

    // Parallel Summary Table calculations and updates
    let totalOurDebits = 0;
    let totalOurCredits = 0;
    ourBooks.forEach(r => {
        if (r.isOpening) return;
        if (r.type === 'Dr') totalOurDebits += r.amount;
        if (r.type === 'Cr') totalOurCredits += r.amount;
    });

    let totalTheirDebits = 0;
    let totalTheirCredits = 0;
    customerBooks.forEach(r => {
        if (r.isOpening) return;
        if (r.type === 'Dr') totalTheirDebits += r.amount;
        if (r.type === 'Cr') totalTheirCredits += r.amount;
    });

    const ourClosingCalculated = ourOpeningSigned + totalOurDebits - totalOurCredits;
    const theirClosingCalculated = isVendorMode
        ? (custOpeningSigned + totalTheirDebits - totalTheirCredits)
        : (custOpeningSigned + totalTheirCredits - totalTheirDebits);

    document.getElementById('summary-party-header').textContent = `${partyTypeLabel} Books`;
    document.getElementById('summary-our-opening').textContent = `�${ourOpeningSigned.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('summary-their-opening').textContent = `�${custOpeningSigned.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('summary-our-debits').textContent = `�${totalOurDebits.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('summary-their-debits').textContent = `�${totalTheirDebits.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('summary-our-credits').textContent = `�${totalOurCredits.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('summary-their-credits').textContent = `�${totalTheirCredits.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('summary-our-closing').textContent = `�${ourClosingCalculated.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
    document.getElementById('summary-their-closing').textContent = `�${theirClosingCalculated.toLocaleString('en-IN', {minimumFractionDigits:2})}`;

    // Custom adjustment inputs processing
    const customAdjEl = document.getElementById('recon-custom-adjustment');
    const customAdjReasonEl = document.getElementById('recon-custom-reason');
    const customAdjInput = customAdjEl ? (parseFloat(customAdjEl.value) || 0) : 0;
    const customAdjReason = customAdjReasonEl ? (customAdjReasonEl.value || '') : '';

    localStorage.setItem(`recon_adj_${cleanPartyKeyForSave}`, customAdjInput);
    localStorage.setItem(`recon_adj_reason_${cleanPartyKeyForSave}`, customAdjReason);

    const netDiff = Math.abs(diff - customAdjInput);
    const adjContainer = document.getElementById('recon-adj-diff-container');
    if (customAdjInput !== 0) {
        if (adjContainer) {
            adjContainer.style.display = 'flex';
            document.getElementById('rep-adjusted-unreconciled-diff').textContent = `�${netDiff.toLocaleString('en-IN', {minimumFractionDigits:2})}`;
        }
    } else {
        if (adjContainer) adjContainer.style.display = 'none';
    }

    const badge = document.getElementById('recon-status-badge');
    const diffContainer = document.getElementById('recon-diff-container');
    
    const evaluationDiff = customAdjInput !== 0 ? netDiff : diff;
    
    if (evaluationDiff < 0.05) {
        badge.textContent = customAdjInput !== 0 ? 'Reconciled with Manual Adjustments ' : 'Fully Reconciled ';
        badge.style.background = '#dcfce7';
        badge.style.color = '#15803d';
        diffContainer.style.background = 'rgba(16, 185, 129, 0.05)';
        diffContainer.style.color = '#10b981';
    } else {
        badge.textContent = 'Discrepancies Found �';
        badge.style.background = '#fef3c7';
        badge.style.color = '#d97706';
        diffContainer.style.background = 'rgba(239, 68, 68, 0.05)';
        diffContainer.style.color = '#ef4444';
    }

    // Build matched pairs list for automated audit log
    const matchedPairs = [];
    const processedKeys = new Set();
    ourBooks.forEach(our => {
        if (our.matched && our.matchedKey && !our.isOpening) {
            const cust = customerBooks.find(c => c.key === our.matchedKey);
            if (cust && !processedKeys.has(our.key) && !processedKeys.has(cust.key)) {
                matchedPairs.push({ our, cust });
                processedKeys.add(our.key);
                processedKeys.add(cust.key);
            }
        }
    });
    window.lastMatchedPairs = matchedPairs;
    if (window.renderAuditLog) window.renderAuditLog();
};

