window.saveReconRowEdit = function(rowKey, isOurBooks) {
    const partyName = document.getElementById('recon-company-party-name').value || 'General';
    const partyKey = partyName.toLowerCase().replace(/[^a-z0-9]/g, '_');
    const customEdits = JSON.parse(localStorage.getItem(`recon_custom_edits_${partyKey}`) || '{}');

    const dateVal = document.getElementById('edit-recon-date').value.trim();
    const refVal = document.getElementById('edit-recon-ref').value.trim();
    const docNoVal = document.getElementById('edit-recon-docno').value.trim();
    const amountVal = parseFloat(document.getElementById('edit-recon-amount').value) || 0;
    const categoryVal = document.getElementById('edit-recon-category').value;

    customEdits[rowKey] = {
        date: dateVal,
        ref: refVal,
        docNo: docNoVal,
        amount: amountVal,
        category: categoryVal
    };

    localStorage.setItem(`recon_custom_edits_${partyKey}`, JSON.stringify(customEdits));
    
    // Also sync to custom additions array if this is a manually added row
    if (rowKey.startsWith('custom_')) {
        let additions = JSON.parse(localStorage.getItem(`recon_custom_additions_${partyKey}`) || '[]');
        const idx = additions.findIndex(a => a.key === rowKey);
        if (idx > -1) {
            additions[idx].date = dateVal;
            additions[idx].ref = refVal;
            additions[idx].docNo = docNoVal;
            additions[idx].amount = amountVal;
            additions[idx].category = categoryVal;
            localStorage.setItem(`recon_custom_additions_${partyKey}`, JSON.stringify(additions));
        }
    }

    document.getElementById('recon-row-edit-modal').style.display = 'none';
    showToast('Transaction details updated successfully', 'success');
    window.runReconMatch();
};

window.saveReconField = function(rowKey, field, value, isOurBooks) {
    const partyName = document.getElementById('recon-company-party-name').value || 'General';
    const partyKey = partyName.toLowerCase().replace(/[^a-z0-9]/g, '_');
    const customEdits = JSON.parse(localStorage.getItem(`recon_custom_edits_${partyKey}`) || '{}');

    if (!customEdits[rowKey]) {
        customEdits[rowKey] = {};
    }
    customEdits[rowKey][field] = value.trim();
    localStorage.setItem(`recon_custom_edits_${partyKey}`, JSON.stringify(customEdits));

    if (rowKey.startsWith('custom_')) {
        let additions = JSON.parse(localStorage.getItem(`recon_custom_additions_${partyKey}`) || '[]');
        const idx = additions.findIndex(a => a.key === rowKey);
        if (idx > -1) {
            additions[idx][field] = value.trim();
            localStorage.setItem(`recon_custom_additions_${partyKey}`, JSON.stringify(additions));
        }
    }
    window.runReconMatch();
};

window.saveReconFieldAmount = function(rowKey, type, value, isOurBooks) {
    const amountVal = parseFloat(value.replace(/[^0-9.]/g, '')) || 0;
    const partyName = document.getElementById('recon-company-party-name').value || 'General';
    const partyKey = partyName.toLowerCase().replace(/[^a-z0-9]/g, '_');
    const customEdits = JSON.parse(localStorage.getItem(`recon_custom_edits_${partyKey}`) || '{}');

    if (!customEdits[rowKey]) {
        customEdits[rowKey] = {};
    }
    customEdits[rowKey].amount = amountVal;
    customEdits[rowKey].type = type;
    localStorage.setItem(`recon_custom_edits_${partyKey}`, JSON.stringify(customEdits));

    if (rowKey.startsWith('custom_')) {
        let additions = JSON.parse(localStorage.getItem(`recon_custom_additions_${partyKey}`) || '[]');
        const idx = additions.findIndex(a => a.key === rowKey);
        if (idx > -1) {
            additions[idx].amount = amountVal;
            additions[idx].type = type;
            localStorage.setItem(`recon_custom_additions_${partyKey}`, JSON.stringify(additions));
        }
    }
    window.runReconMatch();
};

window.deleteReconRow = function(rowKey, isOurBooks) {
    const partyName = document.getElementById('recon-company-party-name').value || 'General';
    const partyKey = partyName.toLowerCase().replace(/[^a-z0-9]/g, '_');
    
    if (rowKey.startsWith('custom_')) {
        let additions = JSON.parse(localStorage.getItem(`recon_custom_additions_${partyKey}`) || '[]');
        additions = additions.filter(a => a.key !== rowKey);
        localStorage.setItem(`recon_custom_additions_${partyKey}`, JSON.stringify(additions));
        showToast('Custom transaction deleted successfully', 'success');
    } else {
        const excludedKeys = JSON.parse(localStorage.getItem(`recon_excluded_${partyKey}`) || '[]');
        if (!excludedKeys.includes(rowKey)) {
            excludedKeys.push(rowKey);
            localStorage.setItem(`recon_excluded_${partyKey}`, JSON.stringify(excludedKeys));
        }
        showToast('Transaction excluded successfully', 'info');
    }
    
    document.getElementById('recon-row-edit-modal').style.display = 'none';
    window.runReconMatch();
};

