window.printCurrentVoucher = function(type) {
    let editId = '';
    if (type === 'so') {
        editId = document.getElementById('so-edit-id').value;
        if (editId) printSO(editId);
    } else if (type === 'po') {
        editId = document.getElementById('po-edit-id').value;
        if (editId) printPO(editId);
    } else if (type === 'grn') {
        editId = document.getElementById('grn-edit-id').value;
        if (editId) printGRN(editId);
    } else if (type === 'outward') {
        editId = document.getElementById('outward-edit-id').value;
        if (editId) printOutward(editId);
    } else if (type === 'req') {
        editId = document.getElementById('req-edit-id').value;
        if (editId) window.printRequisition(editId);
    } else if (type === 'pur') {
        editId = document.getElementById('pur-edit-id').value;
        if (editId) window.printPurchase(editId);
    } else if (type === 'gtx') {
        editId = document.getElementById('gtx-edit-id').value;
        if (editId) window.printGenericTransaction(editId);
    } else if (type === 'gp') {
        editId = arguments[1] || document.getElementById('gp-edit-id').value;
        if (editId) window.printGatePass(editId);
    }
};

