window.openDepartmentModal = function(editId = null) {
    if (!checkPermission('manageUsers')) {
        showToast('Permission Denied', 'error');
        return;
    }
    
    document.getElementById('dept-edit-id').value = editId || '';
    document.getElementById('dept-code').value = '';
    document.getElementById('dept-code').readOnly = !!editId;
    document.getElementById('dept-name').value = '';
    document.getElementById('dept-rules').value = '';
    document.getElementById('dept-employees').value = '';
    document.getElementById('dept-manager').value = '';
    const inputEl = document.getElementById('dept-employee-input');
    if (inputEl) inputEl.value = '';
    
    const mgrSelect = document.getElementById('dept-manager-select');
    if (mgrSelect) {
        mgrSelect.innerHTML = '<option value="">-- Select Manager --</option>';
        (masterDB.users || [])
            .filter(u => u.username !== '__system_company_settings__')
            .forEach(u => {
                const opt = document.createElement('option');
                opt.value = u.username;
                opt.textContent = u.displayName || u.username;
                mgrSelect.appendChild(opt);
            });
    }
 
    document.getElementById('dept-parent').value = '';

    const parentSelect = document.getElementById('dept-parent-select');
    if (parentSelect) {
        parentSelect.innerHTML = '<option value="">-- Select Parent Department --</option>';
        (masterDB.departments || [])
            .filter(d => !editId || d.code !== editId)
            .forEach(d => {
                const opt = document.createElement('option');
                opt.value = d.code;
                opt.textContent = `${d.name} (${d.code})`;
                parentSelect.appendChild(opt);
            });
    }
 
    if (editId) {
        const d = (masterDB.departments || []).find(x => x.code === editId);
        if (d) {
            document.getElementById('dept-modal-title').textContent = 'Edit Department';
            document.getElementById('dept-code').value = d.code;
            document.getElementById('dept-name').value = d.name || '';
            document.getElementById('dept-rules').value = d.rules || '';
            document.getElementById('dept-employees').value = d.employees || '';
            document.getElementById('dept-manager').value = d.manager || '';
            document.getElementById('dept-parent').value = d.parent || '';
        }
    } else {
        document.getElementById('dept-modal-title').textContent = 'Add Department';
    }
 
    window.updateDeptManagersChips();
    window.updateDeptEmployeesChips();
    window.updateDeptParentsChips();
    openModal('department-modal');
};

window.updateDeptManagersChips = function() {
    const hiddenInput = document.getElementById('dept-manager');
    const container = document.getElementById('dept-managers-chips');
    if (!container || !hiddenInput) return;

    container.innerHTML = '';
    const val = hiddenInput.value || '';
    const managers = val.split(',').map(m => m.trim()).filter(Boolean);

    if (managers.length === 0) {
        container.innerHTML = `<span class="placeholder-text" style="color:var(--text-muted); font-size:13.5px;">No managers added yet.</span>`;
        return;
    }

    managers.forEach(mgr => {
        const u = (masterDB.users || []).find(x => x.username === mgr);
        const displayName = u ? (u.displayName || u.username) : mgr;
        const chip = document.createElement('span');
        chip.style.cssText = `
            display: inline-flex;
            align-items: center;
            gap: 6px;
            background: #e0e7ff;
            border: 1px solid #c7d2fe;
            padding: 4px 10px;
            border-radius: 6px;
            font-size: 13px;
            color: #3730a3;
            font-weight: 500;
        `;
        chip.innerHTML = `
            <span>${displayName}</span>
            <span onclick="window.removeDeptManager('${mgr.replace(/'/g, "\\'")}')" style="cursor:pointer; color:#818cf8; font-weight:bold; transition: color 0.15s ease;" onmouseover="this.style.color='#4f46e5'" onmouseout="this.style.color='#818cf8'"></span>
        `;
        container.appendChild(chip);
    });
};

window.addDeptManager = function() {
    const selectEl = document.getElementById('dept-manager-select');
    const hiddenInput = document.getElementById('dept-manager');
    if (!selectEl || !hiddenInput) return;

    const username = selectEl.value;
    if (!username) {
        showToast('Please select a manager first', 'warning');
        return;
    }

    let managers = hiddenInput.value.split(',').map(m => m.trim()).filter(Boolean);
    if (managers.includes(username)) {
        showToast('Manager already added', 'warning');
        return;
    }

    managers.push(username);
    hiddenInput.value = managers.join(', ');
    selectEl.value = '';
    window.updateDeptManagersChips();
};

