window.syncTempSectionsOrder = function() {
    const newActive = [];
    window.customizerFullSectionOrder.forEach(id => {
        if (window.customizerTempLayout.sections.includes(id)) {
            newActive.push(id);
        }
    });
    window.customizerTempLayout.sections = newActive;
};

window.saveDashboardLayoutSettings = async function() {
    const deptSelect = document.getElementById('dashboard-customizer-dept');
    if (!deptSelect) return;
    const dept = deptSelect.value;
    if (!dept) return;
    
    if (!masterDB.dashboardLayouts) {
        masterDB.dashboardLayouts = {};
    }

    const layoutData = {
        stats: window.customizerTempLayout.stats,
        sections: window.customizerTempLayout.sections,
        pendingTypes: window.customizerTempLayout.pendingTypes,
        verificationTypes: window.customizerTempLayout.verificationTypes || []
    };
    
    masterDB.dashboardLayouts[dept] = layoutData;
    if (dept.startsWith('user:')) {
        const rawUname = dept.replace('user:', '');
        masterDB.dashboardLayouts[rawUname] = layoutData;
        masterDB.dashboardLayouts[rawUname.toLowerCase()] = layoutData;
        masterDB.dashboardLayouts[rawUname.toUpperCase()] = layoutData;
    }
    
    showToast('Saving layout configuration...', 'info');
    await saveMasterDB();
    showToast('Dashboard layouts saved successfully!', 'success');
    
    // Keep customizer temp layout active so user selection stays intact
    window.customizerTempDept = dept;
    
    renderDashboard();
};

window.openFreightTab = function(subtab) {
    const sections = {
        'dashboard': 'freight-dashboard-grid',
        'transport': 'freight-transport-section',
        'local': 'freight-local-section',
        'reconciliation': 'freight-reconciliation-section',
        'rama_sync': 'freight-rama-sync-section',
        'jvs': 'freight-jvs-section',
        'billing_status': 'freight-billing-status-section'
    };

    for (const [k, id] of Object.entries(sections)) {
        const el = document.getElementById(id);
        if (el) el.style.display = k === subtab ? 'block' : 'none';
    }

    // Toggle visibility of the Rama Logistics Sync card on the freight dashboard based on active company type
    const isLogisticsCo = window.isLogisticsCompany ? window.isLogisticsCompany() : false;
    const ramaSyncCard = document.getElementById('freight-card-rama-sync');
    if (ramaSyncCard) {
        ramaSyncCard.style.display = !isLogisticsCo ? '' : 'none';
    }

    if (subtab === 'transport') {
        window.renderTransportLogs();
    } else if (subtab === 'local') {
        window.renderLocalFreightLogs();
    } else if (subtab === 'jvs') {
        window.renderFreightJvs();
    } else if (subtab === 'billing_status') {
        window.renderFreightBillingStatusLogs();
    } else if (subtab === 'rama_sync') {
        if (typeof window.setRamaFilter === 'function') window.setRamaFilter(window.ramaFilterState || 'all');
        else if (typeof window.renderRamaLogisticsSyncLogs === 'function') window.renderRamaLogisticsSyncLogs();
    } else if (subtab === 'reconciliation') {
        // Populate carrier selector
        const select = document.getElementById('reconcile-freight-carrier');
        if (select) {
            select.innerHTML = '<option value="">-- Select Transporter or Taxi --</option>';
            
            const logData = window.getAllLogisticsRecords ? window.getAllLogisticsRecords() : { grns: [], outwards: [] };
            const addedTransporterKeys = new Set();

            // 1. Add Transporters from Master DB
            const transporters = db.transporters || [];
            transporters.forEach(t => {
                if (t.name && t.contactPerson !== '__CO_SETTINGS__' && t.contactPerson !== '__CUSTOM_MASTERS__') {
                    const tid = (t.id || '').trim();
                    const tname = (t.name || '').trim();
                    const key = `${tid}:${tname.toLowerCase()}`;
                    if (!addedTransporterKeys.has(key)) {
                        addedTransporterKeys.add(key);
                        const opt = document.createElement('option');
                        opt.value = `transporter:${tid}:${tname}`;
                        opt.textContent = '=� ' + tname;
                        select.appendChild(opt);
                    }
                }
            });

            // 2. Extract any Transporter IDs and Names from GRNs & Outwards not in master table
            const extractTransportersFromRecord = (rec) => {
                if (!rec) return;
                const tid = (rec.transporterId || '').trim();
                let tname = (rec.transporterName || rec.transporter || '').trim();
                if (tname.toLowerCase() === 'transporter') tname = '';
                if (!tname && tid) {
                    const found = (db.transporters || []).find(x => String(x.id) === String(tid));
                    if (found) tname = found.name;
                }
                if (tname || tid) {
                    const key = `${tid}:${tname.toLowerCase()}`;
                    if (!addedTransporterKeys.has(key) && (tname || tid !== '-')) {
                        addedTransporterKeys.add(key);
                        const opt = document.createElement('option');
                        opt.value = `transporter:${tid}:${tname || tid}`;
                        opt.textContent = '=� ' + (tname || tid);
                        select.appendChild(opt);
                    }
                }
            };

            logData.grns.forEach(extractTransportersFromRecord);
            logData.outwards.forEach(extractTransportersFromRecord);

            // 3. Extract Taxi names from GRNs and Outwards to allow reconciling local freight
            const taxiNames = new Set();
            logData.grns.forEach(g => {
                const taxi = window.getTaxiNameFromRecord ? window.getTaxiNameFromRecord(g) : (g.taxiName || '');
                if (taxi && taxi !== '-' && taxi !== 'Local Taxi') taxiNames.add(taxi.trim());
                if (g.taxiName && g.taxiName.trim() && g.taxiName.trim() !== '-' && g.taxiName.trim() !== 'Local Taxi') taxiNames.add(g.taxiName.trim());
            });
            logData.outwards.forEach(o => {
                const taxi = window.getTaxiNameFromRecord ? window.getTaxiNameFromRecord(o) : (o.taxiName || '');
                if (taxi && taxi !== '-' && taxi !== 'Local Taxi') taxiNames.add(taxi.trim());
                if (o.taxiName && o.taxiName.trim() && o.taxiName.trim() !== '-' && o.taxiName.trim() !== 'Local Taxi') taxiNames.add(o.taxiName.trim());
            });

            taxiNames.forEach(name => {
                const opt = document.createElement('option');
                opt.value = 'taxi:' + name;
                opt.textContent = '=� ' + name + ' (Local Taxi)';
                select.appendChild(opt);
            });
        }
        window.renderFreightReconciliation();
    }
};

window.getLogisticsVoucherType = function(rec, fallbackType) {
    if (!rec) return fallbackType || 'GRN';
    if (fallbackType === 'Outward' || fallbackType === 'GRN') return fallbackType;
    if (rec.type === 'Outward' || rec.type === 'GRN') return rec.type;
    const num = String(rec.number || '').trim().toUpperCase();
    if (num.startsWith('FI') || num.startsWith('OUT') || num.startsWith('CHALLAN')) return 'Outward';
    if (num.startsWith('GRN')) return 'GRN';
    if (rec.grnNo && !rec.number) return 'GRN';
    return 'Outward';
};

window.getLogisticsVoucherDocNo = function(rec, fallbackType) {
    if (!rec) return fallbackType || '-';
    const type = window.getLogisticsVoucherType(rec, fallbackType);
    if (type === 'Outward') {
        return rec.number || rec.outwardNo || rec.outward_no || rec.challanNo || rec.challan_no || rec.grnNo || '-';
    }
    return rec.grnNo || rec.grn_no || rec.number || '-';
};

window.renderFreightBillingStatusLogs = async function() {
    if ((!window.ramaSyncMap || window.ramaSyncMap.size === 0) && typeof window.fetchRamaFreightBillingRecords === 'function') {
        await window.fetchRamaFreightBillingRecords();
    }
    if ((!window.crossCompanyInvoices || window.crossCompanyInvoices.length === 0) && typeof window.fetchCrossCompanyLogistics === 'function') {
        await window.fetchCrossCompanyLogistics();
    }
    const tbody = document.getElementById('freight-billing-status-tbody');
    if (!tbody) return;

    const { grns, outwards } = typeof window.getAllLogisticsRecords === 'function' 
        ? window.getAllLogisticsRecords() 
        : { grns: [], outwards: [] };

    const searchVal = (document.getElementById('billing-status-search')?.value || '').trim().toLowerCase();
    const dateFrom = document.getElementById('billing-status-date-from')?.value || '';
    const dateTo = document.getElementById('billing-status-date-to')?.value || '';
    const statusFilterVal = (document.getElementById('billing-status-filter-select')?.value || 'all').toLowerCase();

    const records = [];

    const getSourceCompanyName = (rec) => {
        if (!rec) return '-';
        const cObj = (masterDB?.companies || []).find(c => String(c.id) === String(rec.company_id));
        return cObj ? cObj.name : (rec.company_id || '-');
    };

    const processRecord = (rec, typeName) => {
        // Enforce 01/07/2026 cutoff date rule across all reports
        if (rec.date && rec.date < '2026-07-01') return;

        // Ignore cancelled
        if (window.isRecordCancelled && window.isRecordCancelled(rec)) return;

        const isBilledToCo = window.isBilledToCompany ? window.isBilledToCompany(rec) : false;
        const ramaInvInfo = window.getRamaInvoiceInfo ? window.getRamaInvoiceInfo(rec) : { invoiceNo: '-', invoiceDate: '-' };
        const isLinkedToInvoice = (ramaInvInfo.invoiceNo && ramaInvInfo.invoiceNo !== '-');
        const isSyncedToRama = window.isRamaSynced ? window.isRamaSynced(rec) : false;

        const parseTransportMeta = (rem) => {
            if (!rem) return {};
            const m = rem.match(/\[TRANSPORT:(\{.*?\})\]/);
            if (m) { try { return JSON.parse(m[1]); } catch(e){} }
            return {};
        };

        const docNum = window.getLogisticsVoucherDocNo(rec, typeName);
        const tMeta = parseTransportMeta(rec.remarks);
        const hasVehicle = !!(rec.vehicleNo && rec.vehicleNo.trim() && rec.vehicleNo !== '-');
        const isLocal = rec.isLocalFreight === 'Yes' || rec.isLocalFreight === true || (rec.taxiName && rec.taxiName.trim()) || hasVehicle || tMeta.isLocalFreight === 'Yes' || tMeta.isLocalFreight === true || !!(tMeta.taxiName && tMeta.taxiName.trim()) || String(docNum).startsWith('GRN') || String(docNum).startsWith('FI');

        const isTransporter = rec.hasTransporter === 'Yes' || rec.hasTransporter === true || !!(rec.transporterId && rec.transporterId.trim()) || !!(rec.lrNo && rec.lrNo.trim()) || !!(rec.transporterName && rec.transporterName.trim());
        if (isTransporter && !isLocal) return;

        // Date range filter
        if (dateFrom && rec.date && rec.date < dateFrom) return;
        if (dateTo && rec.date && rec.date > dateTo) return;
        const partyName = typeName === 'GRN' 
            ? (window.getGRNPartyName ? window.getGRNPartyName(rec) : (rec.partyName || '-'))
            : (window.getOutwardPartyName ? window.getOutwardPartyName(rec) : (rec.partyName || '-'));
        const sourceCo = getSourceCompanyName(rec);
        const isGirisonsImpex = sourceCo.toLowerCase().includes('girisons impex') || (rec.company_id && String(rec.company_id).toLowerCase().includes('girisons'));
        const taxiName = window.getTaxiNameFromRecord ? window.getTaxiNameFromRecord(rec) : (rec.taxiName || '-');
        const vehicle = rec.vehicleNo || '-';

        // Search filter
        if (searchVal) {
            const match = docNum.toLowerCase().includes(searchVal) ||
                partyName.toLowerCase().includes(searchVal) ||
                sourceCo.toLowerCase().includes(searchVal) ||
                taxiName.toLowerCase().includes(searchVal) ||
                vehicle.toLowerCase().includes(searchVal);
            if (!match) return;
        }

        const distStr = window.getRecordFreightDistanceStr ? window.getRecordFreightDistanceStr(rec, true) : (rec.distance ? `${rec.distance} km` : '-');
        const distVal = parseFloat(distStr) || 0;
        const rates = window.getFreightAndLabourRates ? window.getFreightAndLabourRates(rec) : { freightRate: 0, labourRate: 0 };
        let labourAmt = 0;
        if (typeof window.getRamaLabourAmount === 'function') {
            labourAmt = window.getRamaLabourAmount({ rawRecord: rec, type: typeName, id: rec.id });
        }
        if (labourAmt <= 0) {
            labourAmt = parseFloat(rates.labourRate || 0);
        }

        // Dynamically resolve Freight Amount using window.getRamaFreightAmount
        let freightAmt = 0;
        if (typeof window.getRamaFreightAmount === 'function') {
            freightAmt = window.getRamaFreightAmount({ rawRecord: rec, type: typeName, id: rec.id });
        }
        if (freightAmt <= 0) {
            let manualAmt = parseFloat(rates.freightRate || 0);
            if (manualAmt > 0) {
                freightAmt = manualAmt;
            } else {
                const agreement = window.getRateAgreementForCustomer ? window.getRateAgreementForCustomer(sourceCo) : null;
                const ratePerKm = agreement ? parseFloat(agreement.ratePerKm || 0) : parseFloat(rec.ratePerKm || 0);
                const minCharge = agreement ? parseFloat(agreement.minCharge || 0) : 0;
                const numericDist = distVal > 0 ? distVal : 10;
                if (agreement && (ratePerKm > 0 || minCharge > 0)) {
                    freightAmt = Math.max(numericDist * ratePerKm, minCharge);
                } else if (ratePerKm > 0) {
                    freightAmt = numericDist * ratePerKm;
                }
            }
        }

        // Must show record if it is Billed to Co, Linked to Invoice, Synced to Rama, OR has positive freight/labour amount
        if (!isBilledToCo && !isLinkedToInvoice && !isSyncedToRama && freightAmt <= 0 && labourAmt <= 0) {
            return;
        }

        records.push({
            id: String(rec.id),
            date: rec.date,
            type: typeName,
            docNum: docNum,
            sourceCo: sourceCo,
            partyName: partyName,
            distanceStr: distStr,
            freightAmt: freightAmt,
            labourAmt: labourAmt,
            vehicleInfo: `${taxiName} (${vehicle})`,
            rawRecord: rec
        });
    };

    grns.forEach(g => processRecord(g, 'GRN'));
    outwards.forEach(o => processRecord(o, 'Outward'));

    // Always sort DATE-WISE (newest date first)
    records.sort((a, b) => (b.date || '').localeCompare(a.date || ''));

    const filteredRecords = records.filter(rec => {
        if (statusFilterVal === 'all') return true;
        const ramaInvInfo = window.getRamaInvoiceInfo ? window.getRamaInvoiceInfo(rec.rawRecord) : { invoiceNo: '-', invoiceDate: '-' };
        const finalInvNo = (ramaInvInfo.invoiceNo !== '-' ? ramaInvInfo.invoiceNo : null);
        const isBilledToCo = window.isBilledToCompany ? window.isBilledToCompany(rec.rawRecord) : false;
        const isBilled = !!finalInvNo || isBilledToCo;

        if (statusFilterVal === 'billed' && !isBilled) return false;
        if (statusFilterVal === 'pending' && isBilled) return false;
        return true;
    });

    if (filteredRecords.length === 0) {
        tbody.innerHTML = `<tr><td colspan="10" style="text-align:center; padding:20px; color:var(--text-muted);">No records matching selected status filter.</td></tr>`;
        return;
    }

    tbody.innerHTML = filteredRecords.map(rec => {
        const ramaInvInfo = window.getRamaInvoiceInfo ? window.getRamaInvoiceInfo(rec.rawRecord) : { invoiceNo: '-', invoiceDate: '-' };
        const finalInvNo = (ramaInvInfo.invoiceNo !== '-' ? ramaInvInfo.invoiceNo : null);
        const finalInvDate = (ramaInvInfo.invoiceDate !== '-' ? ramaInvInfo.invoiceDate : null);

        const isBilledToCo = window.isBilledToCompany ? window.isBilledToCompany(rec.rawRecord) : false;

        let statusBadge = '';
        if (finalInvNo) {
            const formattedInvDate = finalInvDate ? formatDate(finalInvDate) : '';
            statusBadge = `<span class="badge" style="background:#ecfdf5; color:#059669; border:1px solid #a7f3d0; font-size:11px; padding:4px 10px; border-radius:12px; font-weight:600; display:inline-flex; align-items:center; gap:4px;"> Invoiced: ${finalInvNo} ${formattedInvDate ? `(${formattedInvDate})` : ''}</span>`;
        } else if (isBilledToCo) {
            statusBadge = `<span class="badge" style="background:#eff6ff; color:#1d4ed8; border:1px solid #bfdbfe; font-size:11px; padding:4px 10px; border-radius:12px; font-weight:600; display:inline-flex; align-items:center; gap:4px;">=� Billed to Co. (Pending Invoice)</span>`;
        } else {
            statusBadge = `<span class="badge" style="background:#fffbebf0; color:#b45309; border:1px solid #fde68a; font-size:11px; padding:4px 10px; border-radius:12px; font-weight:600; display:inline-flex; align-items:center; gap:4px;">� Pending to get billed</span>`;
        }

        let docLink = `<span style="font-weight:700; color:var(--text-primary);">${rec.docNum}</span>`;
        if (rec.type === 'GRN') {
            docLink = `<a href="javascript:void(0);" onclick="window.openGrnFromReport('${rec.id}', '${rec.docNum}')" style="font-weight:700; color:#2563eb; text-decoration:underline;">${rec.docNum}</a>`;
        } else if (rec.type === 'Outward') {
            docLink = `<a href="javascript:void(0);" onclick="window.openOutwardModal('${rec.id}')" style="font-weight:700; color:#2563eb; text-decoration:underline;">${rec.docNum}</a>`;
        }
        const sourceCompBadge = `<span class="badge" style="background:rgba(99,102,241,0.1); color:#4338ca; border:1px solid rgba(99,102,241,0.25); font-weight:600; font-size:11px; padding:3px 8px; border-radius:10px;"><� ${rec.sourceCo}</span>`;
        const typeBadge = rec.type === 'GRN'
            ? `<span class="badge" style="background:rgba(59,130,246,0.1); color:#2563eb; border:1px solid rgba(59,130,246,0.25); font-weight:600; font-size:11px; padding:3px 8px; border-radius:10px;">=� GRN</span>`
            : `<span class="badge" style="background:rgba(16,185,129,0.1); color:#059669; border:1px solid rgba(16,185,129,0.25); font-weight:600; font-size:11px; padding:3px 8px; border-radius:10px;">=� Outward</span>`;

        const isBilled = !!finalInvNo || isBilledToCo;
        const freightDisplay = rec.freightAmt > 0 ? `�${rec.freightAmt.toFixed(2)}` : '�0.00';
        const labourDisplay = rec.labourAmt > 0 ? `�${rec.labourAmt.toFixed(2)}` : '�0.00';

        return `<tr>
            <td style="font-size:12px; color:var(--text-muted);">${formatDate(rec.date)}</td>
            <td>${typeBadge}</td>
            <td class="cell-doc-number">${docLink}</td>
            <td>${sourceCompBadge}</td>
            <td style="font-weight:600; color:var(--text-primary);">${rec.partyName}</td>
            <td style="text-align:right; font-weight:600;">${rec.distanceStr}</td>
            <td style="text-align:right; font-weight:600; color:${isBilled ? '#059669' : 'var(--text-muted)'};">${freightDisplay}</td>
            <td style="text-align:right; font-weight:600; color:${isBilled ? 'var(--text-secondary)' : 'var(--text-muted)'};">${labourDisplay}</td>
            <td style="font-size:12px;">${rec.vehicleInfo}</td>
            <td style="text-align:center;">${statusBadge}</td>
        </tr>`;
    }).join('');
};

