        const isTransporter = rec.hasTransporter === 'Yes' || rec.hasTransporter === true || !!(rec.transporterId && rec.transporterId.trim()) || !!(rec.lrNo && rec.lrNo.trim()) || !!(rec.transporterName && rec.transporterName.trim());
        if (isTransporter && !isLocal) return;

