window.saveRamaInvoiceDetails = async function(type, id) {
    const invNo = (document.getElementById('edit-rama-inv-no')?.value || '').trim();
    const invDate = (document.getElementById('edit-rama-inv-date')?.value || '').trim();
    const amtVal = parseFloat(document.getElementById('edit-rama-inv-amt')?.value || 0);

    const isGrn = (type || '').toUpperCase() === 'GRN';
    const table = isGrn ? 'grns' : 'outwards';
    const list = isGrn ? [...(db.grns || []), ...(rawDB?.grns || [])] : [...(db.outwards || []), ...(rawDB?.outwards || [])];
    const rec = list.find(x => String(x.id) === String(id));

    if (!rec) {
        if (typeof showToast === 'function') showToast('Record not found', 'error');
        return;
    }

    const modalEl = document.getElementById('edit-rama-invoice-modal');
    if (modalEl) modalEl.style.display = 'none';

    const activeUser = (typeof currentUser !== 'undefined' && currentUser) ? (currentUser.displayName || currentUser.username || 'User') : 'Admin';
    const nowIso = new Date().toISOString();

    const invMeta = { no: invNo, date: invDate, amount: amtVal, by: activeUser, at: nowIso };
    const invTag = `[RAMA_INVOICE:${JSON.stringify(invMeta)}]`;

    let remarks = rec.remarks || '';
    if (remarks.includes('[RAMA_INVOICE:')) {
        remarks = remarks.replace(/\[RAMA_INVOICE:[\s\S]*?\]/, invTag);
    } else if (remarks.includes('[RAMA_BILLING:')) {
        remarks = remarks.replace(/\[RAMA_BILLING:[\s\S]*?\]/, invTag);
    } else {
        remarks = remarks ? (remarks + '\n' + invTag) : invTag;
    }

    rec.remarks = remarks;
    rec.ramaInvoiceNo = invNo;
    rec.ramaInvoiceDate = invDate;
    rec.ramaFreightAmount = amtVal;
    rec.billedToCompany = true;
    rec.isBilledToCompany = true;

    if (window.supabase) {
        try {
            const ramaTag = `[RAMA_INVOICE:${JSON.stringify({ number: invNo, date: invDate })}]`;
            const payload = {
                freight_amount: amtVal,
                freight_rate: amtVal,
                billing_status: 'billed_to_company',
                billed_to_company_at: nowIso,
                updated_at: nowIso,
                remarks: rec.remarks ? (rec.remarks.includes('[RAMA_INVOICE:') ? rec.remarks : rec.remarks + '\n' + ramaTag) : ramaTag
            };

            const { data: existing } = await window.supabase
                .from('rama_freight_billing')
                .select('id, remarks')
                .eq('voucher_type', type)
                .eq('voucher_id', String(id))
                .maybeSingle();

            if (existing && existing.id) {
                if (existing.remarks && !existing.remarks.includes('[RAMA_INVOICE:')) {
                    payload.remarks = existing.remarks + '\n' + ramaTag;
                }
                await window.supabase.from('rama_freight_billing').update(payload).eq('id', existing.id);
            } else {
                const srcCompId = String(rec.company_id || rec.companyId || (typeof currentCompanyId !== 'undefined' ? currentCompanyId : (window.currentCompanyId || 'co_1784194362981')));
                const srcCompName = (masterDB?.companies || []).find(c => String(c.id) === srcCompId)?.name || window.currentCompanyName || srcCompId;

                await window.supabase.from('rama_freight_billing').insert({
                    source_company_id: srcCompId,
                    source_company_name: srcCompName,
                    voucher_type: type,
                    voucher_id: String(id),
                    voucher_number: rec.grnNo || rec.number || type,
                    voucher_date: rec.date || nowIso.split('T')[0],
                    party_name: rec.partyName || '-',
                    transporter_taxi_name: rec.taxiName || 'Rama Logistics',
                    ...payload
                });
            }

            if (!window.ramaSyncMap) window.ramaSyncMap = new Map();
            const k1 = `${type}_${id}`.toLowerCase().trim();
            const k2 = String(rec.grnNo || rec.number || '').trim().toLowerCase();
            const cached = window.ramaSyncMap.get(k1) || {};
            const newObj = { ...cached, ...payload };
            window.ramaSyncMap.set(k1, newObj);
            if (k2) window.ramaSyncMap.set(k2, newObj);

            if (typeof saveToSupabase === 'function') {
                await saveToSupabase(table, rec);
            }
        } catch (e) {
            console.error('Error saving Rama invoice details:', e);
        }
    }

    if (typeof showToast === 'function') showToast(`Updated Rama Invoice details for ${rec.grnNo || rec.number || 'voucher'}!`, 'success');

    if (typeof window.renderRamaLogisticsSyncLogs === 'function') window.renderRamaLogisticsSyncLogs();
    if (typeof window.renderLocalFreightLogs === 'function') window.renderLocalFreightLogs();
    if (typeof window.renderFreightBillingStatusLogs === 'function') window.renderFreightBillingStatusLogs();
    if (typeof window.renderTransportLogs === 'function') window.renderTransportLogs();
};
