window.getFreightAndLabourRates = function(rec) {
    if (!rec) return { freightRate: 0, labourRate: 0 };
    let freightRate = 0;
    let labourRate = 0;
    
    // Parse transport state from remarks
    let tState = {};
    if (rec.remarks && rec.remarks.includes('[TRANSPORT:')) {
        const match = rec.remarks.match(/\[TRANSPORT:(\{.*?\})\]/);
        if (match) {
            try {
                tState = JSON.parse(match[1]);
            } catch (e) {}
        }
    }
    
    // Resolve Labour Rate / Cost
    labourRate = parseFloat(rec.transportLabour !== undefined && rec.transportLabour !== null ? rec.transportLabour : (rec.labour || tState.labour || 0));
    
    // Resolve Freight Rate
    if (tState.freightRate !== undefined) {
        freightRate = parseFloat(tState.freightRate || 0);
    } else if (tState.freightAmount !== undefined) {
        freightRate = parseFloat(tState.freightAmount || 0);
    } else {
        freightRate = parseFloat(rec.freightAmount || rec.freight_amount || 0);
    }
    
    return { freightRate, labourRate };
};

window.shouldPromptFreightDetails = function(data, type) {
    if (!data) return false;
    const hasTransporter = data.hasTransporter === 'Yes' || data.hasTransporter === true || !!(data.transporterId && data.transporterId !== '-');
    return hasTransporter;
};

window.onFreightPopModeChange = function() {
    const mode = document.getElementById('freight-pop-mode')?.value;
    const baleFields = document.getElementById('freight-pop-bale-fields');
    if (mode === 'per_bale') {
        if (baleFields) baleFields.style.display = 'grid';
    } else {
        if (baleFields) baleFields.style.display = 'none';
    }
    window.calculateFreightPopAmount();
};

window.calculateFreightPopAmount = function() {
    const mode = document.getElementById('freight-pop-mode')?.value;
    if (mode === 'per_bale') {
        const bales = parseFloat(document.getElementById('freight-pop-bales')?.value) || 0;
        const rate = parseFloat(document.getElementById('freight-pop-rate')?.value) || 0;
        const amtInput = document.getElementById('freight-pop-amount');
        if (amtInput && (bales > 0 || rate > 0)) {
            amtInput.value = (bales * rate).toFixed(2);
        }
    }
};

window.onFreightPopAmountInput = function() {
    // Intentionally no-op: editing total freight amount directly does not divide by bales
};

window.onFreightPopNoLaborChange = function() {
    const noLaborChk = document.getElementById('freight-pop-no-labor');
    const laborInput = document.getElementById('freight-pop-labor');
    if (noLaborChk && noLaborChk.checked) {
        if (laborInput) {
            laborInput.value = '0.00';
            laborInput.disabled = true;
        }
    } else {
        if (laborInput) {
            laborInput.disabled = false;
        }
    }
};

window.openFreightPopModal = function(docId, docType) {
    const docInput = document.getElementById('freight-pop-doc-id');
    const typeInput = document.getElementById('freight-pop-doc-type');
    if (docInput) docInput.value = docId;
    if (typeInput) typeInput.value = docType;

    let record = null;
    if (docType === 'grn') {
        record = (db.grns || []).find(x => String(x.id) === String(docId));
    } else {
        record = (db.outwards || []).find(x => String(x.id) === String(docId));
    }

    if (record) {
        document.getElementById('freight-pop-doc-no').textContent = record.grnNo || record.number || 'N/A';
        const partyName = record.customerName || record.vendorName || record.partyName || 'N/A';
        document.getElementById('freight-pop-party').textContent = partyName;

        let tState = {};
        if (record.remarks && record.remarks.includes('[TRANSPORT:')) {
            const match = record.remarks.match(/\[TRANSPORT:(\{.*?\})\]/);
            if (match) {
                try {
                    tState = JSON.parse(match[1]);
                } catch(e) {}
            }
        }

        const numBales = parseFloat(tState.bales !== undefined ? tState.bales : (record.transportPkgCount || record.pkgCount || record.bales || record.baleCount || 0)) || 0;
        const balesInput = document.getElementById('freight-pop-bales');
        if (balesInput) balesInput.value = numBales > 0 ? numBales : (tState.bales !== undefined ? tState.bales : '');

        const typeName = (docType === 'grn' || docType === 'GRN') ? 'GRN' : 'Outward';
        const distStr = window.getRecordFreightDistanceStr ? window.getRecordFreightDistanceStr(record, true) : (record.distance ? `${record.distance} km` : '-');
        const distVal = parseFloat(distStr) || 0;
        const rates = window.getFreightAndLabourRates ? window.getFreightAndLabourRates(record) : { freightRate: 0, labourRate: 0 };

        // Direct Report Calculation for Freight (Exact match with Freight Billing Status report)
        let autoFreight = 0;
        if (typeof window.getRamaFreightAmount === 'function') {
            autoFreight = window.getRamaFreightAmount({ rawRecord: record, type: typeName, id: record.id });
        }
        if (autoFreight <= 0) {
            let manualAmt = parseFloat(rates.freightRate || 0);
            if (manualAmt > 0) {
                autoFreight = manualAmt;
            } else {
                const sourceCo = (masterDB?.companies || []).find(c => String(c.id) === String(record.company_id))?.name || '';
                const agreement = window.getRateAgreementForCustomer ? (window.getRateAgreementForCustomer(sourceCo) || window.getRateAgreementForCustomer(partyName)) : null;
                const ratePerKm = agreement ? parseFloat(agreement.ratePerKm || 0) : parseFloat(record.ratePerKm || 0);
                const minCharge = agreement ? parseFloat(agreement.minCharge || 0) : 0;
                const numericDist = distVal > 0 ? distVal : 10;
                if (agreement && (ratePerKm > 0 || minCharge > 0)) {
                    autoFreight = Math.max(numericDist * ratePerKm, minCharge);
                } else if (ratePerKm > 0) {
                    autoFreight = numericDist * ratePerKm;
                }
            }
        }

        // Direct Report Calculation for Labour
        let autoLabour = 0;
        if (typeof window.getRamaLabourAmount === 'function') {
            autoLabour = window.getRamaLabourAmount({ rawRecord: record, type: typeName, id: record.id });
        }
        if (autoLabour <= 0) {
            autoLabour = parseFloat(rates.labourRate || 0);
        }

        let freightMode = tState.freightMode;
        let autoRate = 0;

        if (tState.freightRate !== undefined && parseFloat(tState.freightRate) > 0) {
            autoRate = parseFloat(tState.freightRate);
        } else if (record.freightRate && parseFloat(record.freightRate) > 0) {
            autoRate = parseFloat(record.freightRate);
        }

        if (autoRate > 0 && numBales > 0) {
            if (!freightMode) freightMode = 'per_bale';
            autoFreight = numBales * autoRate;
        } else {
            // Default mode to 'flat' so exact report Freight Amount is directly loaded without fake divisions
            if (!freightMode) freightMode = 'flat';
        }

        const modeSelect = document.getElementById('freight-pop-mode');
        if (modeSelect) modeSelect.value = freightMode;

        // Set inputs
        const rateInput = document.getElementById('freight-pop-rate');
        if (rateInput) rateInput.value = autoRate > 0 ? autoRate.toFixed(2) : (tState.freightRate !== undefined ? tState.freightRate : '');

        const amtInput = document.getElementById('freight-pop-amount');
        if (amtInput) amtInput.value = autoFreight > 0 ? autoFreight.toFixed(2) : '0.00';

        const laborInput = document.getElementById('freight-pop-labor');
        if (laborInput) laborInput.value = autoLabour >= 0 ? autoLabour.toFixed(2) : '0.00';

        const noLaborChk = document.getElementById('freight-pop-no-labor');
        if (noLaborChk) {
            noLaborChk.checked = (autoLabour === 0);
            if (noLaborChk.checked && laborInput) {
                laborInput.disabled = true;
            }
        }

        window.onFreightPopModeChange();
        window.onFreightPopNoLaborChange();
    }

    openModal('document-freight-entry-modal');
};

window.saveFreightPopDetails = async function() {
    const docId = document.getElementById('freight-pop-doc-id')?.value;
    const docType = document.getElementById('freight-pop-doc-type')?.value;
    if (!docId || !docType) return;

    const mode = document.getElementById('freight-pop-mode')?.value;
    const bales = parseFloat(document.getElementById('freight-pop-bales')?.value) || 0;
    const rate = parseFloat(document.getElementById('freight-pop-rate')?.value) || 0;
    const amount = parseFloat(document.getElementById('freight-pop-amount')?.value) || 0;
    const labour = parseFloat(document.getElementById('freight-pop-labor')?.value) || 0;

    let record = null;
    let dbTable = '';
    let dbList = [];
    if (docType === 'grn') {
        dbTable = 'grns';
        dbList = db.grns || [];
    } else {
        dbTable = 'outwards';
        dbList = db.outwards || [];
    }

    record = dbList.find(x => String(x.id) === String(docId));
    if (!record) {
        showToast('Record not found', 'error');
        return;
    }

    let currentTransport = {};
    let remarksText = record.remarks || '';
    if (remarksText.includes('[TRANSPORT:')) {
        const match = remarksText.match(/\[TRANSPORT:(\{.*?\})\]/);
        if (match) {
            try {
                currentTransport = JSON.parse(match[1]);
            } catch(e) {}
        }
        remarksText = remarksText.replace(/\[TRANSPORT:[\s\S]*?\]/g, '').trim();
    }

    const updatedTransport = {
        ...currentTransport,
        freightMode: mode,
        bales: bales,
        freightRate: rate,
        freightAmount: amount,
        labour: labour
    };

    const newTransportStr = `[TRANSPORT:${JSON.stringify(updatedTransport)}]`;
    const finalRemarks = remarksText ? (remarksText + '\n' + newTransportStr) : newTransportStr;

    record.remarks = finalRemarks;
    record.transportLabour = labour;
    record.freightAmount = amount;

    if (window.supabase) {
        try {
            await saveToSupabase(dbTable, record);
        } catch(e) {
            console.error('Error saving freight details:', e);
            showToast('Database save failed: ' + (e.message || e), 'error');
            return;
        }
    }

    showToast('Freight details saved successfully', 'success');
    closeModal('document-freight-entry-modal');

    if (typeof window.refreshAllLogisticsTables === 'function') {
        window.refreshAllLogisticsTables();
    }
};
window.sortVouchersByTypeAndSeries = function(a, b) {
    const numA = a.number || '';
    const numB = b.number || '';
    
    // Extract parts
    const partsA = numA.split('/');
    const partsB = numB.split('/');
    
    // 1. Group by main prefix (e.g. FI vs GRN)
    const prefixA = partsA[0] || '';
    const prefixB = partsB[0] || '';
    if (prefixA !== prefixB) {
        return prefixA.localeCompare(prefixB);
    }
    
    // 2. Group by middle series prefix (e.g. C/PF/26-27 vs C/EM/26-27)
    const seriesA = partsA.slice(0, -1).join('/');
    const seriesB = partsB.slice(0, -1).join('/');
    if (seriesA !== seriesB) {
        return seriesA.localeCompare(seriesB);
    }
    
    // 3. Sort by numeric serial number (last part)
    const serialA = parseInt(partsA[partsA.length - 1] || '0', 10);
    const serialB = parseInt(partsB[partsB.length - 1] || '0', 10);
    if (!isNaN(serialA) && !isNaN(serialB)) {
        return serialA - serialB;
    }
    
    // Fallback to alphabetical for the last part if not numeric
    const lastA = partsA[partsA.length - 1] || '';
    const lastB = partsB[partsB.length - 1] || '';
    return lastA.localeCompare(lastB);
};

window.renderTransportLogs = function() {
    const search = (document.getElementById('transport-search')?.value || '').toLowerCase();
    const dateFrom = document.getElementById('transport-date-from')?.value || '';
    const dateTo = document.getElementById('transport-date-to')?.value || '';

    const tbody = document.getElementById('transport-logs-body');
    if (!tbody) return;
    tbody.innerHTML = '';

    const isRamaCompany = window.isLogisticsCompany ? window.isLogisticsCompany() : false;
    const bulkBillBtn = document.getElementById('btn-bill-freight-transport');
    if (bulkBillBtn) bulkBillBtn.style.display = isRamaCompany ? 'inline-flex' : 'none';

    // Dynamically show/hide the Billing column header while keeping Action header visible
    document.querySelectorAll('.freight-billing-header').forEach(el => {
        el.style.display = isRamaCompany ? '' : 'none';
    });
    document.querySelectorAll('.freight-action-header').forEach(el => {
        el.style.display = '';
    });

    const { grns, outwards, getRecordPkgCount } = window.getAllLogisticsRecords();
    const shipments = [];

    const getTransporterName = (rec) => {
        if (!rec) return '';
        let name = rec.transporterName || rec.transporter || '';
        if (!name && rec.transporterId) {
            const t = (db.transporters || []).find(x => String(x.id) === String(rec.transporterId));
            if (t) name = t.name;
        }
        name = (name || '').trim();
        if (name.toLowerCase() === 'transporter') return '';
        return name;
    };

    const getLrNo = (rec) => {
        if (!rec) return '';
        const lr = (rec.lrNo || rec.lr_no || '').trim();
        return (lr === '-' || lr.toLowerCase() === 'null') ? '' : lr;
    };

    const getSourceCompanyName = (rec) => {
        if (!rec) return 'Faridabad Unit';
        const cObj = (masterDB?.companies || []).find(c => String(c.id) === String(rec.company_id));
        return cObj ? cObj.name : (rec.company_id || 'Faridabad Unit');
    };

    grns.forEach(g => {
        if (window.isRecordCancelled(g)) return;
        if (g.date < '2026-07-01') return;
        
        const tState = window.parseGrnTransportState ? window.parseGrnTransportState(g) : {};
        const transpName = getTransporterName(g) || (tState.transporterName && tState.transporterName.toLowerCase() !== 'transporter' ? tState.transporterName.trim() : '');
        const lrNo = getLrNo(g) || (tState.lrNo ? tState.lrNo.trim() : '');
        const transpId = (g.transporterId || '').trim();

        if (!window.isTransporterVoucher(g)) return;
        const isSynced = window.isRamaSynced(g);
        if (isRamaCompany && !isSynced) return;

        shipments.push({
            id: g.id,
            date: g.date,
            type: 'GRN',
            number: g.grnNo || g.number,
            sourceCompany: getSourceCompanyName(g),
            party: window.getGRNPartyName(g),
            distance: window.getRecordDistance(g),
            transporter: transpName || (transpId ? 'Transporter #' + transpId : '-'),
            lrNo: lrNo || '-',
            vehicleNo: g.vehicleNo || tState.vehicleNo || '-',
            pkgCount: getRecordPkgCount(g),
            status: g.status || 'Pending',
            isSynced: isSynced,
            rawRecord: g
        });
    });

    outwards.forEach(o => {
        if (window.isRecordCancelled(o)) return;
        if (o.date < '2026-07-01') return;

        const transpName = getTransporterName(o);
        const lrNo = getLrNo(o);
        const transpId = (o.transporterId || '').trim();

        if (!window.isTransporterVoucher(o)) return;
        const isSynced = window.isRamaSynced(o);
        if (isRamaCompany && !isSynced) return;

        shipments.push({
            id: o.id,
            date: o.date,
            type: 'Outward',
            number: o.number,
            sourceCompany: getSourceCompanyName(o),
            party: window.getOutwardPartyName(o),
            distance: window.getRecordDistance(o),
            transporter: transpName || (transpId ? 'Transporter #' + transpId : '-'),
            lrNo: lrNo || '-',
            vehicleNo: o.vehicleNo || '-',
            pkgCount: getRecordPkgCount(o),
            status: o.status || 'Issued',
            isSynced: isSynced,
            rawRecord: o
        });
    });

    shipments.sort(window.sortVouchersByTypeAndSeries);

    let renderedCount = 0;
    shipments.forEach(s => {
        const activeTab = window.currentTransportFreightTab || 'All';
        if (activeTab !== 'All' && s.type !== activeTab) return;

        // Subtab/Series filter
        if (activeTab === 'Outward') {
            const activeSubtab = window.currentTransportFreightOutwardSubTab || 'All';
            if (activeSubtab !== 'All') {
                const num = String(s.number || '').toUpperCase();
                if (activeSubtab === 'FI/C/EM' && !num.startsWith('FI/C/EM')) return;
                if ((activeSubtab === 'FI/C/PL' || activeSubtab === 'FI/C/PF') && !num.startsWith('FI/C/PL') && !num.startsWith('FI/C/PF')) return;
                if (activeSubtab === 'FI/V/EM' && !num.startsWith('FI/V/EM')) return;
                if ((activeSubtab === 'FI/V/PL' || activeSubtab === 'FI/V/PF') && !num.startsWith('FI/V/PL') && !num.startsWith('FI/V/PF')) return;
                if (activeSubtab === 'FI/JW' && !num.startsWith('FI/JW')) return;
                if (activeSubtab === 'FI/V/CON' && !num.startsWith('FI/V/CON') && !num.startsWith('FI/CON')) return;
            }
        } else if (activeTab === 'GRN') {
            const activeSubtab = window.currentTransportFreightGrnSubTab || 'All';
            if (activeSubtab !== 'All') {
                const num = String(s.number || '').toUpperCase();
                if (activeSubtab === 'GRN/C/EM' && !num.startsWith('GRN/C/EM')) return;
                if ((activeSubtab === 'GRN/C/PL' || activeSubtab === 'GRN/C/PF') && !num.startsWith('GRN/C/PL') && !num.startsWith('GRN/C/PF')) return;
                if (activeSubtab === 'GRN/V/EM' && !num.startsWith('GRN/V/EM')) return;
                if ((activeSubtab === 'GRN/V/PL' || activeSubtab === 'GRN/V/PF') && !num.startsWith('GRN/V/PL') && !num.startsWith('GRN/V/PF')) return;
                if (activeSubtab === 'GRN/CON' && !num.startsWith('GRN/CON')) return;
            }
        }

        const rates = window.getFreightAndLabourRates(s.rawRecord);
        if (dateFrom && s.date < dateFrom) return;
        if (dateTo && s.date > dateTo) return;

        if (search) {
            const match = s.number.toLowerCase().includes(search) ||
                          s.sourceCompany.toLowerCase().includes(search) ||
                          s.party.toLowerCase().includes(search) ||
                          String(s.distance).toLowerCase().includes(search) ||
                          s.transporter.toLowerCase().includes(search) ||
                          s.lrNo.toLowerCase().includes(search) ||
                          s.vehicleNo.toLowerCase().includes(search) ||
                          String(rates.freightRate).includes(search) ||
                          String(rates.labourRate).includes(search);
            if (!match) return;
        }

        renderedCount++;
        let docLink = `<span style="font-weight:700; color:var(--text-primary); word-break:break-word;">${s.number}</span>`;
        if (s.type === 'GRN') {
            docLink = `<a href="javascript:void(0);" onclick="window.openGrnFromReport('${s.id}', '${s.number}')" style="font-weight:700; color:#2563eb; text-decoration:underline; word-break:break-word;">${s.number}</a>`;
        } else if (s.type === 'Outward') {
            docLink = `<a href="javascript:void(0);" onclick="window.openOutwardModal('${s.id}')" style="font-weight:700; color:#2563eb; text-decoration:underline; word-break:break-word;">${s.number}</a>`;
        }
        const sourceCompBadge = `<span class="badge" style="background:rgba(99,102,241,0.1); color:#4338ca; border:1px solid rgba(99,102,241,0.25); font-weight:600; font-size:11px; padding:3px 8px; border-radius:10px;"><� ${s.sourceCompany}</span>`;

        let actionBtn = '';
        const isBilled = window.isBilledToCompany(s.rawRecord || s);
        const billedDate = window.getBilledToCompanyDate(s.rawRecord || s);
        const syncInfo = window.getRamaSyncInfo(s.rawRecord || s);

        const billingStatusHtml = isBilled
            ? `<span class="badge" style="background:#ecfdf5; color:#059669; border:1px solid #a7f3d0; font-size:11px; padding:4px 10px; border-radius:12px; font-weight:600; display:inline-flex; align-items:center; gap:4px;">=� Ready to get billed ${billedDate ? `(${billedDate})` : ''}</span>`
            : `<span style="color:var(--text-muted); font-size:12px;">-</span>`;

        if (isBilled) {
            actionBtn = `<span class="badge" style="background:#ecfdf5; color:#059669; border:1px solid #a7f3d0; font-size:11px; padding:4px 10px; border-radius:12px; font-weight:600;"> Billed to Company</span>`;
        } else if (isRamaCompany) {
            actionBtn = `<button class="btn btn-sm" style="background:#4f46e5; color:#fff; font-size:11px; padding:4px 10px; border-radius:6px; font-weight:600; border:none; cursor:pointer; display:inline-flex; align-items:center; gap:4px;" onclick="window.billFreightToCompany('${s.type}', '${s.id}')">>� Bill to Company</button>`;
        } else if (syncInfo.isSynced) {
            const byStr = syncInfo.syncedBy ? `by ${syncInfo.syncedBy}` : '';
            const dtStr = syncInfo.syncedAt ? new Date(syncInfo.syncedAt).toLocaleDateString('en-IN', {day:'2-digit', month:'2-digit', year:'numeric'}) : '';
            const subMeta = (byStr || dtStr) ? `<div style="font-size:10px; color:#059669; margin-top:2px; font-weight:500;">${byStr}${dtStr ? ' on ' + dtStr : ''}</div>` : '';

            actionBtn = `<div style="display:inline-flex; flex-direction:column; align-items:center;">
                <span class="badge" style="background:#ecfdf5; color:#059669; border:1px solid #a7f3d0; font-size:11px; padding:4px 10px; border-radius:12px; font-weight:600;"> Synced to Rama</span>
                ${subMeta}
            </div>`;
        } else {
            actionBtn = `<button class="btn btn-sm" style="background:#6366f1; color:#fff; font-size:11px; padding:4px 10px; border-radius:6px; font-weight:600; border:none; cursor:pointer;" onclick="window.syncFreightToRama('${s.type}', '${s.id}')">� Sync to Rama</button>`;
        }

        const row = document.createElement('tr');
        row.innerHTML = `
            <td style="text-align:center;"><input type="checkbox" class="chk-select-freight-transport" data-type="${s.type}" data-id="${s.id}" onchange="window.updateFreightBulkButtons('transport')"></td>
            <td>${formatDate(s.date)}</td>
            <td><span class="badge ${s.type === 'GRN' ? 'badge-info' : 'badge-success'}">${s.type}</span></td>
            <td class="cell-doc-number">${docLink}</td>
            <td>${sourceCompBadge}</td>
            <td>${s.party}</td>
            <td style="font-weight:600; color:var(--text-primary);">${s.distance}</td>
            <td>${s.transporter}</td>
            <td><code>${s.lrNo}</code></td>
            <td><code>${s.vehicleNo}</code></td>
            <td style="text-align:right; font-weight:600;">${rates.freightRate > 0 ? `�${rates.freightRate.toFixed(2)}` : '-'}</td>
            <td style="text-align:right; font-weight:600;">${rates.labourRate > 0 ? `�${rates.labourRate.toFixed(2)}` : '-'}</td>
            <td style="text-align:right; font-weight:600;">${s.pkgCount}</td>
            ${isRamaCompany ? `<td style="text-align:center;">${billingStatusHtml}</td>` : ''}
            ${isRamaCompany ? `<td style="text-align:center;">${actionBtn}</td>` : ''}
        `;
        tbody.appendChild(row);
    });

    if (renderedCount === 0) {
        tbody.innerHTML = `<tr><td colspan="${isRamaCompany ? 15 : 13}" style="text-align:center; padding:20px; color:var(--text-muted);">No long-distance transport records found.</td></tr>`;
    }
};

window.renderLocalFreightLogs = function() {
    const search = (document.getElementById('local-freight-search')?.value || '').toLowerCase();
    const dateFrom = document.getElementById('local-date-from')?.value || '';
    const dateTo = document.getElementById('local-date-to')?.value || '';

    const tbody = document.getElementById('local-logs-body');
    if (!tbody) return;
    tbody.innerHTML = '';

    const isRamaCompany = window.isLogisticsCompany ? window.isLogisticsCompany() : false;
    const bulkBillBtn = document.getElementById('btn-bill-freight-local');
    if (bulkBillBtn) bulkBillBtn.style.display = isRamaCompany ? 'inline-flex' : 'none';

    // Dynamically show/hide the Billing column header while keeping Action header visible
    document.querySelectorAll('.freight-billing-header').forEach(el => {
        el.style.display = isRamaCompany ? '' : 'none';
    });
    document.querySelectorAll('.freight-action-header').forEach(el => {
        el.style.display = '';
    });

    const { grns, outwards, getRecordPkgCount } = window.getAllLogisticsRecords();
    const shipments = [];

    const getSourceCompanyName = (rec) => {
        if (!rec) return 'Faridabad Unit';
        const cObj = (masterDB?.companies || []).find(c => String(c.id) === String(rec.company_id));
        return cObj ? cObj.name : (rec.company_id || 'Faridabad Unit');
    };

    grns.forEach(g => {
        if (window.isRecordCancelled(g)) return;
        if (g.date < '2026-07-01') return;
        if (g.poType === 'inhouse' || String(g.grnNo || g.number || '').startsWith('GRN/INH')) return;
        if (!window.isLocalFreightRecord(g)) return;
        const isSynced = window.isRamaSynced(g);
        if (isRamaCompany && !isSynced) return;

        const tState = window.parseGrnTransportState ? window.parseGrnTransportState(g) : {};
        const resolvedTaxi = window.getTaxiNameFromRecord ? window.getTaxiNameFromRecord(g) : (g.taxiName || '-');
        
        if (isRamaCompany && resolvedTaxi.trim().toLowerCase() !== 'rama logistics') return;

        shipments.push({
            id: g.id,
            date: g.date,
            type: 'GRN',
            number: g.grnNo || g.number,
            sourceCompany: getSourceCompanyName(g),
            party: window.getGRNPartyName(g),
            distance: window.getRecordDistance(g, true),
            taxiName: resolvedTaxi,
            vehicleNo: g.vehicleNo || tState.vehicleNo || '-',
            pkgCount: getRecordPkgCount(g),
            status: g.status || 'Pending',
            isSynced: isSynced,
            rawRecord: g
        });
    });

    outwards.forEach(o => {
        if (window.isRecordCancelled(o)) return;
        if (o.date < '2026-07-01') return;
        const state = window.parseOutwardWizardState ? window.parseOutwardWizardState(o) : {};
        if (!window.isLocalFreightRecord(o)) return;
        const isSynced = window.isRamaSynced(o);
        if (isRamaCompany && !isSynced) return;

        const resolvedTaxi = window.getTaxiNameFromRecord ? window.getTaxiNameFromRecord(o) : (o.taxiName || '-');
        
        if (isRamaCompany && resolvedTaxi.trim().toLowerCase() !== 'rama logistics') return;

        shipments.push({
            id: o.id,
            date: o.date,
            type: 'Outward',
            number: o.number,
            sourceCompany: getSourceCompanyName(o),
            party: window.getOutwardPartyName(o),
            distance: window.getRecordDistance(o, true),
            taxiName: resolvedTaxi,
            vehicleNo: o.vehicleNo || '-',
            pkgCount: getRecordPkgCount(o),
            status: o.status || 'Issued',
            isSynced: isSynced,
            rawRecord: o
        });
    });

    shipments.sort(window.sortVouchersByTypeAndSeries);

    let renderedCount = 0;
    shipments.forEach(s => {
        const activeTab = window.currentLocalFreightTab || 'All';
        if (activeTab !== 'All' && s.type !== activeTab) return;

        // Subtab/Series filter
        if (activeTab === 'Outward') {
            const activeSubtab = window.currentLocalFreightOutwardSubTab || 'All';
            if (activeSubtab !== 'All') {
                const num = String(s.number || '').toUpperCase();
                if (activeSubtab === 'FI/C/EM' && !num.startsWith('FI/C/EM')) return;
                if ((activeSubtab === 'FI/C/PL' || activeSubtab === 'FI/C/PF') && !num.startsWith('FI/C/PL') && !num.startsWith('FI/C/PF')) return;
                if (activeSubtab === 'FI/V/EM' && !num.startsWith('FI/V/EM')) return;
                if ((activeSubtab === 'FI/V/PL' || activeSubtab === 'FI/V/PF') && !num.startsWith('FI/V/PL') && !num.startsWith('FI/V/PF')) return;
                if (activeSubtab === 'FI/JW' && !num.startsWith('FI/JW')) return;
                if (activeSubtab === 'FI/V/CON' && !num.startsWith('FI/V/CON') && !num.startsWith('FI/CON')) return;
            }
        } else if (activeTab === 'GRN') {
            const activeSubtab = window.currentLocalFreightGrnSubTab || 'All';
            if (activeSubtab !== 'All') {
                const num = String(s.number || '').toUpperCase();
                if (activeSubtab === 'GRN/C/EM' && !num.startsWith('GRN/C/EM')) return;
                if ((activeSubtab === 'GRN/C/PL' || activeSubtab === 'GRN/C/PF') && !num.startsWith('GRN/C/PL') && !num.startsWith('GRN/C/PF')) return;
                if (activeSubtab === 'GRN/V/EM' && !num.startsWith('GRN/V/EM')) return;
                if ((activeSubtab === 'GRN/V/PL' || activeSubtab === 'GRN/V/PF') && !num.startsWith('GRN/V/PL') && !num.startsWith('GRN/V/PF')) return;
                if (activeSubtab === 'GRN/CON' && !num.startsWith('GRN/CON')) return;
            }
        }

        if (dateFrom && s.date < dateFrom) return;
        if (dateTo && s.date > dateTo) return;

        if (search) {
            const match = s.number.toLowerCase().includes(search) ||
                          s.sourceCompany.toLowerCase().includes(search) ||
                          s.party.toLowerCase().includes(search) ||
                          String(s.distance).toLowerCase().includes(search) ||
                          s.taxiName.toLowerCase().includes(search) ||
                          s.vehicleNo.toLowerCase().includes(search);
            if (!match) return;
        }

        renderedCount++;
        let docLink = `<span style="font-weight:700; color:var(--text-primary); word-break:break-word;">${s.number}</span>`;
        if (s.type === 'GRN') {
            docLink = `<a href="javascript:void(0);" onclick="window.openGrnFromReport('${s.id}', '${s.number}')" style="font-weight:700; color:#2563eb; text-decoration:underline; word-break:break-word;">${s.number}</a>`;
        } else if (s.type === 'Outward') {
            docLink = `<a href="javascript:void(0);" onclick="window.openOutwardModal('${s.id}')" style="font-weight:700; color:#2563eb; text-decoration:underline; word-break:break-word;">${s.number}</a>`;
        }
        const sourceCompBadge = `<span class="badge" style="background:rgba(99,102,241,0.1); color:#4338ca; border:1px solid rgba(99,102,241,0.25); font-weight:600; font-size:11px; padding:3px 8px; border-radius:10px;"><� ${s.sourceCompany}</span>`;

        let actionBtn = '';
        const isBilled = window.isBilledToCompany(s.rawRecord || s);
        const billedDate = window.getBilledToCompanyDate(s.rawRecord || s);
        const syncInfo = window.getRamaSyncInfo(s.rawRecord || s);

        const billingStatusHtml = isBilled
            ? `<span class="badge" style="background:#ecfdf5; color:#059669; border:1px solid #a7f3d0; font-size:11px; padding:4px 10px; border-radius:12px; font-weight:600; display:inline-flex; align-items:center; gap:4px;">=� Ready to get billed ${billedDate ? `(${billedDate})` : ''}</span>`
            : `<span style="color:var(--text-muted); font-size:12px;">-</span>`;

        if (isBilled) {
            actionBtn = `<span class="badge" style="background:#ecfdf5; color:#059669; border:1px solid #a7f3d0; font-size:11px; padding:4px 10px; border-radius:12px; font-weight:600;"> Billed to Company</span>`;
        } else if (isRamaCompany) {
            actionBtn = `<button class="btn btn-sm" style="background:#4f46e5; color:#fff; font-size:11px; padding:4px 10px; border-radius:6px; font-weight:600; border:none; cursor:pointer; display:inline-flex; align-items:center; gap:4px;" onclick="window.billFreightToCompany('${s.type}', '${s.id}')">>� Bill to Company</button>`;
        } else if (syncInfo.isSynced) {
            const byStr = syncInfo.syncedBy ? `by ${syncInfo.syncedBy}` : '';
            const dtStr = syncInfo.syncedAt ? new Date(syncInfo.syncedAt).toLocaleDateString('en-IN', {day:'2-digit', month:'2-digit', year:'numeric'}) : '';
            const subMeta = (byStr || dtStr) ? `<div style="font-size:10px; color:#059669; margin-top:2px; font-weight:500;">${byStr}${dtStr ? ' on ' + dtStr : ''}</div>` : '';

            actionBtn = `<div style="display:inline-flex; flex-direction:column; align-items:center;">
                <span class="badge" style="background:#ecfdf5; color:#059669; border:1px solid #a7f3d0; font-size:11px; padding:4px 10px; border-radius:12px; font-weight:600;"> Synced to Rama</span>
                ${subMeta}
            </div>`;
        } else {
            actionBtn = `<button class="btn btn-sm" style="background:#6366f1; color:#fff; font-size:11px; padding:4px 10px; border-radius:6px; font-weight:600; border:none; cursor:pointer;" onclick="window.syncFreightToRama('${s.type}', '${s.id}')">� Sync to Rama</button>`;
        }
        const row = document.createElement('tr');
        row.innerHTML = `
            <td style="text-align:center;"><input type="checkbox" class="chk-select-freight-local" data-type="${s.type}" data-id="${s.id}" onchange="window.updateFreightBulkButtons('local')"></td>
            <td>${formatDate(s.date)}</td>
            <td><span class="badge ${s.type === 'GRN' ? 'badge-info' : 'badge-success'}">${s.type}</span></td>
            <td class="cell-doc-number">${docLink}</td>
            <td>${sourceCompBadge}</td>
            <td>${s.party}</td>
            <td style="font-weight:600; color:var(--text-primary);">${window.getRecordActualDistanceStr(s.rawRecord || s, true)}</td>
            <td style="font-weight:600; color:var(--text-primary);">${window.getRecordFreightDistanceStr(s.rawRecord || s, true)}</td>
            <td>${s.taxiName}</td>
            <td><code>${s.vehicleNo}</code></td>
            <td style="text-align:right; font-weight:600;">${s.pkgCount}</td>
            ${isRamaCompany ? `<td style="text-align:center;">${billingStatusHtml}</td>` : ''}
            ${isRamaCompany ? `<td style="text-align:center;">${actionBtn}</td>` : ''}
        `;
        tbody.appendChild(row);
    });

    if (renderedCount === 0) {
        tbody.innerHTML = `<tr><td colspan="${isRamaCompany ? 13 : 11}" style="text-align:center; padding:20px; color:var(--text-muted);">No local taxi logs found.</td></tr>`;
    }
};

window.switchLocalFreightTab = function(tabType) {
    window.currentLocalFreightTab = tabType;
    document.querySelectorAll('[id^="local-freight-tab-"]').forEach(btn => {
        btn.classList.remove('active');
    });
    const activeBtn = document.getElementById('local-freight-tab-' + tabType.toLowerCase());
    if (activeBtn) activeBtn.classList.add('active');

    // Show/hide subtabs container
    const outSub = document.getElementById('local-freight-subtabs-outward');
    const grnSub = document.getElementById('local-freight-subtabs-grn');
    if (outSub) outSub.style.display = (tabType === 'Outward') ? 'flex' : 'none';
    if (grnSub) grnSub.style.display = (tabType === 'GRN') ? 'flex' : 'none';

    // Reset active subtab on switch
    window.currentLocalFreightOutwardSubTab = 'All';
    window.currentLocalFreightGrnSubTab = 'All';
    document.querySelectorAll('[id^="lf-subtab-"]').forEach(btn => {
        if (btn.id.endsWith('-all')) {
            btn.classList.add('active');
        } else {
            btn.classList.remove('active');
        }
    });

    if (typeof window.renderLocalFreightLogs === 'function') {
        window.renderLocalFreightLogs();
    }
};

