window.exportTransportLogs = function() {
    const search = (document.getElementById('transport-search')?.value || '').toLowerCase();
    const dateFrom = document.getElementById('transport-date-from')?.value || '';
    const dateTo = document.getElementById('transport-date-to')?.value || '';

    const isRamaCompany = window.isLogisticsCompany ? window.isLogisticsCompany() : false;
    const { grns, outwards, getRecordPkgCount } = window.getAllLogisticsRecords();
    const shipments = [];

    const getTransporterName = (rec) => {
        if (!rec) return '';
        let name = rec.transporterName || rec.transporter || '';
        if (!name && rec.transporterId) {
            const t = (db.transporters || []).find(x => String(x.id) === String(rec.transporterId));
            if (t) name = t.name;
        }
        name = (name || '').trim();
        if (name.toLowerCase() === 'transporter') return '';
        return name;
    };

    const getLrNo = (rec) => {
        if (!rec) return '';
        const lr = (rec.lrNo || rec.lr_no || '').trim();
        return (lr === '-' || lr.toLowerCase() === 'null') ? '' : lr;
    };

    const getSourceCompanyName = (rec) => {
        if (!rec) return 'Faridabad Unit';
        const cObj = (masterDB?.companies || []).find(c => String(c.id) === String(rec.company_id));
        return cObj ? cObj.name : (rec.company_id || 'Faridabad Unit');
    };

    grns.forEach(g => {
        if (window.isRecordCancelled(g)) return;
        if (g.date < '2026-07-01') return;
        
        const tState = window.parseGrnTransportState ? window.parseGrnTransportState(g) : {};
        const transpName = getTransporterName(g) || (tState.transporterName && tState.transporterName.toLowerCase() !== 'transporter' ? tState.transporterName.trim() : '');
        const lrNo = getLrNo(g) || (tState.lrNo ? tState.lrNo.trim() : '');
        const transpId = (g.transporterId || '').trim();

        if (!window.isTransporterVoucher(g)) return;
        const isSynced = window.isRamaSynced(g);
        if (!isRamaCompany || isSynced) {
            shipments.push({
                date: g.date,
                type: 'GRN',
                number: g.grnNo || g.number,
                sourceCompany: getSourceCompanyName(g),
                party: window.getGRNPartyName(g),
                distance: window.getRecordDistance(g),
                transporter: transpName || (transpId ? 'Transporter #' + transpId : '-'),
                lrNo: lrNo || '-',
                vehicleNo: g.vehicleNo || tState.vehicleNo || '-',
                pkgCount: getRecordPkgCount(g),
                rawRecord: g
            });
        }
    });

    outwards.forEach(o => {
        if (window.isRecordCancelled(o)) return;
        if (o.date < '2026-07-01') return;

        const transpName = getTransporterName(o);
        const lrNo = getLrNo(o);
        const transpId = (o.transporterId || '').trim();

        if (!window.isTransporterVoucher(o)) return;
        const isSynced = window.isRamaSynced(o);
        if (!isRamaCompany || isSynced) {
                shipments.push({
                    date: o.date,
                    type: 'Outward',
                    number: o.number,
                    sourceCompany: getSourceCompanyName(o),
                    party: window.getOutwardPartyName(o),
                    distance: window.getRecordDistance(o),
                    transporter: transpName || (transpId ? 'Transporter #' + transpId : '-'),
                    lrNo: lrNo || '-',
                    vehicleNo: o.vehicleNo || '-',
                    pkgCount: getRecordPkgCount(o),
                    rawRecord: o
                });
        }
    });

    shipments.sort(window.sortVouchersByTypeAndSeries);

    const headers = [
        "Date", "Doc Type", "Doc Number", "Source Company", "Party Name", 
        "Distance (km)", "Transporter", "LR Number", "Vehicle Number", 
        "Freight Rate (INR)", "Labour Rate (INR)", "Than / Pkg Count"
    ];

    const allRows = [headers];
    const outwardRows = [headers];
    const grnRows = [headers];

    shipments.forEach(s => {
        const activeTab = window.currentTransportFreightTab || 'All';
        if (activeTab !== 'All' && s.type !== activeTab) return;

        // Subtab/Series filter
        if (activeTab === 'Outward') {
            const activeSubtab = window.currentTransportFreightOutwardSubTab || 'All';
            if (activeSubtab !== 'All') {
                const num = String(s.number || '').toUpperCase();
                if (activeSubtab === 'FI/C/EM' && !num.startsWith('FI/C/EM')) return;
                if ((activeSubtab === 'FI/C/PL' || activeSubtab === 'FI/C/PF') && !num.startsWith('FI/C/PL') && !num.startsWith('FI/C/PF')) return;
                if (activeSubtab === 'FI/V/EM' && !num.startsWith('FI/V/EM')) return;
                if ((activeSubtab === 'FI/V/PL' || activeSubtab === 'FI/V/PF') && !num.startsWith('FI/V/PL') && !num.startsWith('FI/V/PF')) return;
                if (activeSubtab === 'FI/JW' && !num.startsWith('FI/JW')) return;
                if (activeSubtab === 'FI/V/CON' && !num.startsWith('FI/V/CON') && !num.startsWith('FI/CON')) return;
            }
        } else if (activeTab === 'GRN') {
            const activeSubtab = window.currentTransportFreightGrnSubTab || 'All';
            if (activeSubtab !== 'All') {
                const num = String(s.number || '').toUpperCase();
                if (activeSubtab === 'GRN/C/EM' && !num.startsWith('GRN/C/EM')) return;
                if ((activeSubtab === 'GRN/C/PL' || activeSubtab === 'GRN/C/PF') && !num.startsWith('GRN/C/PL') && !num.startsWith('GRN/C/PF')) return;
                if (activeSubtab === 'GRN/V/EM' && !num.startsWith('GRN/V/EM')) return;
                if ((activeSubtab === 'GRN/V/PL' || activeSubtab === 'GRN/V/PF') && !num.startsWith('GRN/V/PL') && !num.startsWith('GRN/V/PF')) return;
                if (activeSubtab === 'GRN/CON' && !num.startsWith('GRN/CON')) return;
            }
        }

        if (dateFrom && s.date < dateFrom) return;
        if (dateTo && s.date > dateTo) return;

        const rates = window.getFreightAndLabourRates(s.rawRecord);

        if (search) {
            const match = s.number.toLowerCase().includes(search) ||
                          s.sourceCompany.toLowerCase().includes(search) ||
                          s.party.toLowerCase().includes(search) ||
                          String(s.distance).toLowerCase().includes(search) ||
                          s.transporter.toLowerCase().includes(search) ||
                          s.lrNo.toLowerCase().includes(search) ||
                          s.vehicleNo.toLowerCase().includes(search) ||
                          String(rates.freightRate).includes(search) ||
                          String(rates.labourRate).includes(search);
            if (!match) return;
        }

        const formattedDate = s.date ? s.date.split('-').reverse().join('/') : '';
        const rowData = [
            formattedDate,
            s.type,
            s.number,
            s.sourceCompany,
            s.party,
            s.distance,
            s.transporter,
            s.lrNo,
            s.vehicleNo,
            rates.freightRate > 0 ? rates.freightRate : 0,
            rates.labourRate > 0 ? rates.labourRate : 0,
            s.pkgCount
        ];

        allRows.push(rowData);
        if (s.type === 'Outward') {
            outwardRows.push(rowData);
        } else {
            grnRows.push(rowData);
        }
    });

    if (allRows.length <= 1) {
        showToast("No records found to export.", "info");
        return;
    }

    const wb = XLSX.utils.book_new();

    // 1. "All" sheet
    const wsAll = XLSX.utils.aoa_to_sheet(allRows);
    XLSX.utils.book_append_sheet(wb, wsAll, "All");

    // 2. "Outwards" sheet
    if (outwardRows.length > 1) {
        const wsOut = XLSX.utils.aoa_to_sheet(outwardRows);
        XLSX.utils.book_append_sheet(wb, wsOut, "Outwards");
    }

    // 3. "GRNs" sheet
    if (grnRows.length > 1) {
        const wsGRN = XLSX.utils.aoa_to_sheet(grnRows);
        XLSX.utils.book_append_sheet(wb, wsGRN, "GRNs");
    }

    XLSX.writeFile(wb, `Long_Distance_Transport_Logs_${new Date().toISOString().slice(0,10)}.xlsx`);
};

// Export Local Freight Logs function follows

window.exportLocalFreightLogs = function() {
    const search = (document.getElementById('local-freight-search')?.value || '').toLowerCase();
    const dateFrom = document.getElementById('local-date-from')?.value || '';
    const dateTo = document.getElementById('local-date-to')?.value || '';

    const isRamaCompany = window.isLogisticsCompany ? window.isLogisticsCompany() : false;
    const { grns, outwards, getRecordPkgCount } = window.getAllLogisticsRecords();
    const shipments = [];

    const getSourceCompanyName = (rec) => {
        if (!rec) return 'Faridabad Unit';
        const cObj = (masterDB?.companies || []).find(c => String(c.id) === String(rec.company_id));
        return cObj ? cObj.name : (rec.company_id || 'Faridabad Unit');
    };

    grns.forEach(g => {
        if (window.isRecordCancelled(g)) return;
        if (g.date < '2026-07-01') return;
        if (g.poType === 'inhouse' || String(g.grnNo || g.number || '').startsWith('GRN/INH')) return;
        if (!window.isLocalFreightRecord(g)) return;

        const isSynced = window.isRamaSynced(g);
        if (isRamaCompany && !isSynced) return;

        const tState = window.parseGrnTransportState ? window.parseGrnTransportState(g) : {};
        const resolvedTaxi = window.getTaxiNameFromRecord ? window.getTaxiNameFromRecord(g) : (g.taxiName || '-');
        
        if (isRamaCompany && resolvedTaxi.trim().toLowerCase() !== 'rama logistics') return;

        shipments.push({
            date: g.date,
            type: 'GRN',
            number: g.grnNo || g.number,
            sourceCompany: getSourceCompanyName(g),
            party: window.getGRNPartyName(g),
            distance: window.getRecordDistance(g, true),
            taxiName: resolvedTaxi,
            vehicleNo: g.vehicleNo || tState.vehicleNo || '-',
            pkgCount: getRecordPkgCount(g),
            rawRecord: g
        });
    });

    outwards.forEach(o => {
        if (window.isRecordCancelled(o)) return;
        if (o.date < '2026-07-01') return;
        const state = window.parseOutwardWizardState ? window.parseOutwardWizardState(o) : {};
        if (o.poType === 'inhouse' || state.type === 'inhouse' || String(o.number || '').startsWith('FI/INH')) return;
        if (!window.isLocalFreightRecord(o)) return;

        const isSynced = window.isRamaSynced(o);
        if (isRamaCompany && !isSynced) return;

        const resolvedTaxi = window.getTaxiNameFromRecord ? window.getTaxiNameFromRecord(o) : (o.taxiName || '-');
        
        if (isRamaCompany && resolvedTaxi.trim().toLowerCase() !== 'rama logistics') return;

        shipments.push({
            date: o.date,
            type: 'Outward',
            number: o.number,
            sourceCompany: getSourceCompanyName(o),
            party: window.getOutwardPartyName(o),
            distance: window.getRecordDistance(o, true),
            taxiName: resolvedTaxi,
            vehicleNo: o.vehicleNo || '-',
            pkgCount: getRecordPkgCount(o),
            rawRecord: o
        });
    });

    if (typeof window.sortVouchersByTypeAndSeries === 'function') {
        shipments.sort(window.sortVouchersByTypeAndSeries);
    } else {
        shipments.sort((a, b) => new Date(b.date) - new Date(a.date));
    }

    const exportRows = [];
    exportRows.push([
        "Date",
        "Doc Type",
        "Doc Number",
        "Source Company",
        "Party Name",
        "Distance (km)",
        "Taxi / Vehicle Operator",
        "Vehicle Number",
        "Than / Pkg Count",
        "Company Billing Status"
    ]);

    shipments.forEach(s => {
        const activeTab = window.currentLocalFreightTab || 'All';
        if (activeTab !== 'All' && s.type !== activeTab) return;

        // Subtab/Series filter
        if (activeTab === 'Outward') {
            const activeSubtab = window.currentLocalFreightOutwardSubTab || 'All';
            if (activeSubtab !== 'All') {
                const num = String(s.number || '').toUpperCase();
                if (activeSubtab === 'FI/C/EM' && !num.startsWith('FI/C/EM')) return;
                if ((activeSubtab === 'FI/C/PL' || activeSubtab === 'FI/C/PF') && !num.startsWith('FI/C/PL') && !num.startsWith('FI/C/PF')) return;
                if (activeSubtab === 'FI/V/EM' && !num.startsWith('FI/V/EM')) return;
                if ((activeSubtab === 'FI/V/PL' || activeSubtab === 'FI/V/PF') && !num.startsWith('FI/V/PL') && !num.startsWith('FI/V/PF')) return;
                if (activeSubtab === 'FI/JW' && !num.startsWith('FI/JW')) return;
                if (activeSubtab === 'FI/V/CON' && !num.startsWith('FI/V/CON') && !num.startsWith('FI/CON')) return;
            }
        } else if (activeTab === 'GRN') {
            const activeSubtab = window.currentLocalFreightGrnSubTab || 'All';
            if (activeSubtab !== 'All') {
                const num = String(s.number || '').toUpperCase();
                if (activeSubtab === 'GRN/C/EM' && !num.startsWith('GRN/C/EM')) return;
                if ((activeSubtab === 'GRN/C/PL' || activeSubtab === 'GRN/C/PF') && !num.startsWith('GRN/C/PL') && !num.startsWith('GRN/C/PF')) return;
                if (activeSubtab === 'GRN/V/EM' && !num.startsWith('GRN/V/EM')) return;
                if ((activeSubtab === 'GRN/V/PL' || activeSubtab === 'GRN/V/PF') && !num.startsWith('GRN/V/PL') && !num.startsWith('GRN/V/PF')) return;
                if (activeSubtab === 'GRN/CON' && !num.startsWith('GRN/CON')) return;
            }
        }

        if (dateFrom && s.date < dateFrom) return;
        if (dateTo && s.date > dateTo) return;

        if (search) {
            const match = s.number.toLowerCase().includes(search) ||
                          s.sourceCompany.toLowerCase().includes(search) ||
                          s.party.toLowerCase().includes(search) ||
                          String(s.distance).toLowerCase().includes(search) ||
                          s.taxiName.toLowerCase().includes(search) ||
                          s.vehicleNo.toLowerCase().includes(search);
            if (!match) return;
        }

        const isBilled = window.isBilledToCompany ? window.isBilledToCompany(s.rawRecord || s) : false;
        const billingStatus = isBilled ? 'Billed to Company' : 'Pending Billing';

        exportRows.push([
            s.date ? formatDate(s.date) : '',
            s.type || '',
            s.number || '',
            s.sourceCompany || '',
            s.party || '',
            s.distance || '',
            s.taxiName || '',
            s.vehicleNo || '',
            s.pkgCount || 0,
            billingStatus
        ]);
    });

    if (exportRows.length <= 1) {
        showToast('No records found to export.', 'info');
        return;
    }

    try {
        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.aoa_to_sheet(exportRows);
        ws['!cols'] = [
            { wch: 12 },
            { wch: 10 },
            { wch: 22 },
            { wch: 25 },
            { wch: 30 },
            { wch: 15 },
            { wch: 22 },
            { wch: 18 },
            { wch: 15 },
            { wch: 20 }
        ];
        XLSX.utils.book_append_sheet(wb, ws, "Local Freight Logs");
        XLSX.writeFile(wb, `Local_Freight_Taxi_Logs_${new Date().toISOString().slice(0,10)}.xlsx`);
        showToast('Exported successfully!', 'success');
    } catch (e) {
        console.error(e);
        showToast('Failed to export: ' + e.message, 'error');
    }
};

window.exportRamaSyncLogs = function() {
    const search = (document.getElementById('rama-sync-search')?.value || '').toLowerCase().trim();
    const dateFrom = document.getElementById('rama-sync-date-from')?.value || '';
    const dateTo = document.getElementById('rama-sync-date-to')?.value || '';

    const { grns, outwards, getRecordPkgCount } = window.getAllLogisticsRecords 
        ? window.getAllLogisticsRecords() 
        : { grns: [], outwards: [], getRecordPkgCount: () => 0 };

    const items = [];

    const getTransporterOrTaxiName = (rec) => {
        if (!rec) return '-';
        let resolvedTaxi = (rec.taxiName || '').trim();
        if (!resolvedTaxi || resolvedTaxi === '-') {
            if (rec.remarks && rec.remarks.includes('[TRANSPORT:')) {
                const match = rec.remarks.match(/\[TRANSPORT:(\{.*?\})\]/);
                if (match) {
                    try {
                        const parsed = JSON.parse(match[1]);
                        if (parsed.taxiName && parsed.taxiName.trim()) {
                            resolvedTaxi = parsed.taxiName.trim();
                        }
                    } catch(e) {}
                }
            }
        }
        if (resolvedTaxi && resolvedTaxi !== '-') {
            return resolvedTaxi;
        }
        let name = rec.transporterName || rec.transporter || '';
        if (!name && rec.transporterId) {
            const t = (db.transporters || []).find(x => String(x.id) === String(rec.transporterId));
            if (t) name = t.name;
        }
        name = (name || '').trim();
        if (name && name.toLowerCase() !== 'transporter' && name !== '-') return name;
        return '-';
    };

    const getLrOrVehicleNo = (rec) => {
        if (!rec) return '-';
        const lr = (rec.lrNo || rec.lr_no || '').trim();
        const veh = (rec.vehicleNo || '').trim();
        if (lr && lr !== '-') return lr;
        if (veh && veh !== '-') return veh;
        return '-';
    };

    const getSourceCompanyName = (rec) => {
        if (!rec) return 'Faridabad Unit';
        const cObj = (masterDB?.companies || []).find(c => String(c.id) === String(rec.company_id));
        return cObj ? cObj.name : (rec.company_id || 'Faridabad Unit');
    };

    grns.forEach(g => {
        if (window.isRecordCancelled(g)) return;
        const isSynced = window.isRamaSynced ? window.isRamaSynced(g) : false;
        if (!isSynced) {
            if (!window.isLocalFreightRecord(g)) return;
            const taxi = window.getTaxiNameFromRecord ? window.getTaxiNameFromRecord(g) : (g.taxiName || '-');
            if (taxi.trim().toLowerCase() !== 'rama logistics') return;
        }

        items.push({
            id: g.id,
            date: g.grDate || g.date || '',
            type: 'GRN',
            number: g.grnNo || g.number || 'GRN',
            sourceCompany: getSourceCompanyName(g),
            party: window.getGRNPartyName(g),
            transporter: getTransporterOrTaxiName(g),
            lrOrVehicle: getLrOrVehicleNo(g),
            pkgCount: getRecordPkgCount(g),
            syncState: window.getRamaSyncState ? window.getRamaSyncState(g) : 'pending',
            rawRecord: g
        });
    });

    outwards.forEach(o => {
        if (window.isRecordCancelled(o)) return;
        const isSynced = window.isRamaSynced ? window.isRamaSynced(o) : false;
        if (!isSynced) {
            if (!window.isLocalFreightRecord(o)) return;
            const taxi = window.getTaxiNameFromRecord ? window.getTaxiNameFromRecord(o) : (o.taxiName || '-');
            if (taxi.trim().toLowerCase() !== 'rama logistics') return;
        }

        items.push({
            id: o.id,
            date: o.date || '',
            type: 'Outward',
            number: o.number || 'Outward',
            sourceCompany: getSourceCompanyName(o),
            party: window.getOutwardPartyName(o),
            transporter: getTransporterOrTaxiName(o),
            lrOrVehicle: getLrOrVehicleNo(o),
            pkgCount: getRecordPkgCount(o),
            syncState: window.getRamaSyncState ? window.getRamaSyncState(o) : 'pending',
            rawRecord: o
        });
    });

    // Merge standalone records from rama_freight_billing table in Supabase
    if (window.crossCompanyRamaFreight && Array.isArray(window.crossCompanyRamaFreight)) {
        const processedDocNos = new Set(items.map(it => String(it.number || '').trim().toLowerCase()));
        window.crossCompanyRamaFreight.forEach(r => {
            if (!r) return;
            const docNo = String(r.voucher_number || '').trim();
            if (!docNo || processedDocNos.has(docNo.toLowerCase())) return;

            items.push({
                id: r.voucher_id || r.id,
                date: r.voucher_date || r.synced_at || '',
                type: r.voucher_type || 'Outward',
                number: docNo,
                sourceCompany: r.source_company_name || r.source_company_id || 'Faridabad Unit',
                party: r.party_name || '-',
                transporter: r.transporter_taxi_name && r.transporter_taxi_name !== '-' ? r.transporter_taxi_name : 'Rama Logistics',
                lrOrVehicle: r.vehicle_no && r.vehicle_no !== '-' ? r.vehicle_no : (r.lr_no || '-'),
                pkgCount: parseFloat(r.pkg_count) || 0,
                syncState: 'synced',
                rawRecord: r
            });
            processedDocNos.add(docNo.toLowerCase());
        });
    }

    let filtered = items;
    if (window.currentRamaFilter === 'pending') {
        filtered = filtered.filter(it => it.syncState !== 'synced');
    } else if (window.currentRamaFilter === 'synced') {
        filtered = filtered.filter(it => it.syncState === 'synced');
    }

    filtered.sort((a, b) => new Date(b.date) - new Date(a.date));

    const exportRows = [];
    exportRows.push([
        "Type",
        "Voucher No",
        "Date",
        "Source Company",
        "Party Name",
        "Transporter / Taxi",
        "LR / Vehicle No",
        "Qty / Pkgs",
        "Sync Status"
    ]);

    filtered.forEach(it => {
        if (dateFrom && it.date < dateFrom) return;
        if (dateTo && it.date > dateTo) return;

        const ramaInvInfo = typeof window.getRamaInvoiceInfo === 'function' ? window.getRamaInvoiceInfo(it) : { invoiceNo: '-', invoiceDate: '-' };

        if (search) {
            const match = (it.number || '').toLowerCase().includes(search) ||
                          (it.party || '').toLowerCase().includes(search) ||
                          (it.sourceCompany || '').toLowerCase().includes(search) ||
                          (it.transporter || '').toLowerCase().includes(search) ||
                          (it.lrOrVehicle || '').toLowerCase().includes(search) ||
                          (ramaInvInfo.invoiceNo && ramaInvInfo.invoiceNo.toLowerCase().includes(search));
            if (!match) return;
        }

        const syncLabel = it.syncState === 'synced' ? 'Synced to Rama' : 'Pending Sync';

        exportRows.push([
            it.type || '',
            it.number || '',
            it.date ? formatDate(it.date) : '',
            it.sourceCompany || '',
            it.party || '',
            it.transporter || '',
            it.lrOrVehicle || '',
            it.pkgCount || 0,
            syncLabel
        ]);
    });

    if (exportRows.length <= 1) {
        showToast('No records found to export.', 'info');
        return;
    }

    try {
        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.aoa_to_sheet(exportRows);
        ws['!cols'] = [
            { wch: 10 },
            { wch: 22 },
            { wch: 12 },
            { wch: 25 },
            { wch: 30 },
            { wch: 25 },
            { wch: 18 },
            { wch: 12 },
            { wch: 18 }
        ];
        XLSX.utils.book_append_sheet(wb, ws, "Rama Sync Logs");
        XLSX.writeFile(wb, `Rama_Local_Freight_Sync_Logs_${new Date().toISOString().slice(0,10)}.xlsx`);
        showToast('Exported Rama Sync Logs successfully!', 'success');
    } catch (e) {
        console.error(e);
        showToast('Failed to export: ' + e.message, 'error');
    }
};

window.renderFreightReconciliation = function() {
    const carrierVal = document.getElementById('reconcile-freight-carrier')?.value || '';
    const shipmentsTbody = document.getElementById('reconcile-shipments-tbody');
    const vouchersTbody = document.getElementById('reconcile-vouchers-tbody');
    if (!shipmentsTbody || !vouchersTbody) return;

    if (!carrierVal) {
        shipmentsTbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:20px; color:var(--text-muted);">Select a carrier to load shipments.</td></tr>';
        vouchersTbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:20px; color:var(--text-muted);">Select a carrier to load payments.</td></tr>';
        document.getElementById('reconcile-selected-shipments-count').textContent = '0 Selected';
        return;
    }

    const parts = carrierVal.split(':');
    const carrierType = parts[0];
    const carrierId = parts[1] || '';
    const carrierNameFromVal = parts.slice(2).join(':') || '';
    
    let carrierName = '';
    if (carrierType === 'transporter') {
        const t = (db.transporters || []).find(x => String(x.id) === String(carrierId));
        carrierName = t ? t.name : (carrierNameFromVal || carrierId);
    } else {
        carrierName = carrierId; // Taxi name
    }

    const normCarrierId = String(carrierId || '').trim().toLowerCase();
    const normCarrierName = String(carrierName || '').trim().toLowerCase();

    // 1. Fetch pending shipments
    const { grns, outwards, getRecordPkgCount } = window.getAllLogisticsRecords();
    const shipments = [];

    const isRecordCarrierMatch = (rec) => {
        if (!rec) return false;
        const recTaxi = String(window.getTaxiNameFromRecord ? window.getTaxiNameFromRecord(rec) : (rec.taxiName || '')).trim().toLowerCase();
        
        if (carrierType === 'taxi') {
            return (recTaxi === normCarrierId || recTaxi === normCarrierName || (rec.taxiName && String(rec.taxiName).trim().toLowerCase() === normCarrierName));
        }

        const recTransId = String(rec.transporterId || '').trim().toLowerCase();
        let recTransName = String(rec.transporterName || rec.transporter || '').trim().toLowerCase();
        if (recTransName === 'transporter') recTransName = '';
        if (!recTransName && rec.transporterId) {
            const t = (db.transporters || []).find(x => String(x.id) === String(rec.transporterId));
            if (t) recTransName = String(t.name || '').trim().toLowerCase();
        }

        if (normCarrierId && recTransId && normCarrierId === recTransId) return true;
        if (normCarrierName && recTransName) {
            if (normCarrierName === recTransName || normCarrierName.includes(recTransName) || recTransName.includes(normCarrierName)) return true;
        }
        if (normCarrierName && rec.remarks && String(rec.remarks).toLowerCase().includes(normCarrierName)) return true;

        return false;
    };

    grns.forEach(g => {
        if (g.status !== 'Cancelled' && g.status !== 'cancelled' && isRecordCarrierMatch(g)) {
            shipments.push({
                id: g.id,
                dbTable: g.dbTable || 'grns',
                date: g.date,
                type: 'GRN',
                number: g.grnNo || g.number,
                party: g.customerName || g.partyName || g.vendorName || '-',
                pkgCount: getRecordPkgCount(g),
                reconciledVoucherId: g.reconciledVoucherId
            });
        }
    });

    outwards.forEach(o => {
        if (o.status !== 'Cancelled' && o.status !== 'cancelled' && isRecordCarrierMatch(o)) {
            shipments.push({
                id: o.id,
                dbTable: 'outwards',
                date: o.date,
                type: 'Outward',
                number: o.number,
                party: o.customerName || o.vendorName || o.partyName || '-',
                pkgCount: getRecordPkgCount(o),
                reconciledVoucherId: o.reconciledVoucherId
            });
        }
    });

    // Filter only unreconciled shipments
    const unreconciledShipments = shipments.filter(s => !s.reconciledVoucherId);

    // Sort descending
    unreconciledShipments.sort(window.sortVouchersByTypeAndSeries);

    shipmentsTbody.innerHTML = '';
    if (unreconciledShipments.length === 0) {
        shipmentsTbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:20px; color:var(--text-muted);">No pending shipments found.</td></tr>';
    } else {
        unreconciledShipments.forEach(s => {
            const docLink = `<span style="font-weight:700; color:var(--text-primary);">${s.number}</span>`;
            const tr = document.createElement('tr');
            tr.innerHTML = `
                <td><input type="checkbox" class="shipment-reconcile-chk" value="${s.id}" data-table="${s.dbTable}" onchange="window.updateFreightReconcileCount()"></td>
                <td>${formatDate(s.date)}</td>
                <td class="cell-doc-number">${docLink} (${s.type})</td>
                <td>${s.party}</td>
                <td style="text-align:right; font-weight:600;">${s.pkgCount}</td>
            `;
            shipmentsTbody.appendChild(tr);
        });
    }

    // 2. Fetch unlinked payment vouchers
    const allVouchers = (db.genericTransactions || []).filter(v => 
        (v.type === 'voucher' || v.type === 'payment' || v.voucherType === 'payment' || v.category === 'freight') && 
        v.status !== 'Cancelled' && v.status !== 'cancelled'
    );
    let filteredVouchers = allVouchers.filter(v => {
        const isNotReconciled = !v.reconciledShipments || v.reconciledShipments.length === 0;
        if (!isNotReconciled) return false;

        const partyStr = String(v.partyName || v.party || '').toLowerCase();
        const remarksStr = String(v.remarks || '').toLowerCase();
        const vTransId = String(v.transporterId || '').toLowerCase();

        const matchesParty = normCarrierName && (partyStr === normCarrierName || partyStr.includes(normCarrierName) || normCarrierName.includes(partyStr));
        const matchesRemarks = normCarrierName && remarksStr.includes(normCarrierName);
        const matchesId = normCarrierId && vTransId && normCarrierId === vTransId;

        return matchesParty || matchesRemarks || matchesId;
    });

    const searchInput = document.getElementById('reconcile-voucher-search');
    const searchVal = searchInput ? searchInput.value.toLowerCase().trim() : '';
    if (searchVal) {
        filteredVouchers = filteredVouchers.filter(v => 
            String(v.number || '').toLowerCase().includes(searchVal) ||
            String(v.remarks || '').toLowerCase().includes(searchVal) ||
            String(v.totalValue || v.totalAmount || '').includes(searchVal)
        );
    }

    filteredVouchers.sort((a, b) => new Date(b.date) - new Date(a.date));

    vouchersTbody.innerHTML = '';
    if (filteredVouchers.length === 0) {
        vouchersTbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:20px; color:var(--text-muted);">No unreconciled vouchers found for this carrier. Create a Payment Voucher first.</td></tr>';
    } else {
        filteredVouchers.forEach(v => {
            const tr = document.createElement('tr');
            const docLink = `<span style="font-weight:700; color:var(--text-primary);">${v.number}</span>`;
            tr.innerHTML = `
                <td><input type="radio" name="reconcile-voucher-radio" value="${v.id}"></td>
                <td>${formatDate(v.date)}</td>
                <td>${docLink}</td>
                <td style="text-align:right; font-weight:600; color:var(--accent-green);">�${parseFloat(v.totalValue || v.totalAmount || 0).toFixed(2)}</td>
                <td style="max-width:180px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;">${window.cleanRemarksForLog(v.remarks) || '-'}</td>
            `;
            vouchersTbody.appendChild(tr);
        });
    }
    
    document.getElementById('reconcile-selected-shipments-count').textContent = '0 Selected';
    const selectAll = document.getElementById('reconcile-select-all-shipments');
    if (selectAll) selectAll.checked = false;
};

window.updateFreightReconcileCount = function() {
    const chks = document.querySelectorAll('.shipment-reconcile-chk:checked');
    document.getElementById('reconcile-selected-shipments-count').textContent = `${chks.length} Selected`;
    const jvBtn = document.getElementById('btn-generate-freight-jv');
    if (jvBtn) {
        jvBtn.style.display = chks.length > 0 ? 'inline-block' : 'none';
    }
};

window.toggleAllReconcileShipments = function(master) {
    const chks = document.querySelectorAll('.shipment-reconcile-chk');
    chks.forEach(chk => { chk.checked = master.checked; });
    window.updateFreightReconcileCount();
};

window.reconcileFreightVoucher = async function() {
    const carrierVal = document.getElementById('reconcile-freight-carrier')?.value || '';
    if (!carrierVal) {
        showToast('Please select a carrier first', 'error');
        return;
    }

    const selectedChks = document.querySelectorAll('.shipment-reconcile-chk:checked');
    if (selectedChks.length === 0) {
        showToast('Please select at least one cargo shipment to reconcile', 'error');
        return;
    }

    const selectedRadio = document.querySelector('input[name="reconcile-voucher-radio"]:checked');
    if (!selectedRadio) {
        showToast('Please select a payment voucher to link', 'error');
        return;
    }

    const voucherId = selectedRadio.value;
    const voucher = (db.genericTransactions || []).find(v => v.id === voucherId);
    if (!voucher) {
        showToast('Selected voucher not found', 'error');
        return;
    }

    if (!(await window.showSmartConfirm('Reconcile Shipments', `Are you sure you want to reconcile the ${selectedChks.length} selected shipments against Voucher #${voucher.number}?`))) {
        return;
    }

    showImportLoadingOverlay();
    try {
        const shipmentIds = [];
        
        for (const chk of selectedChks) {
            const shipId = chk.value;
            const dbTable = chk.dataset.table;
            shipmentIds.push(shipId);

            let shipmentRecord = null;
            if (dbTable === 'grns') {
                const grns = [
                    ...(db.grn_cust_plain || []),
                    ...(db.grn_vend_emb || []),
                    ...(db.grn_consumable || [])
                ];
                shipmentRecord = grns.find(g => g.id === shipId);
            } else if (dbTable === 'outwards') {
                shipmentRecord = (db.outward || []).find(o => o.id === shipId);
            }

            if (shipmentRecord) {
                shipmentRecord.reconciledVoucherId = voucher.id;
                shipmentRecord.reconciledVoucherNumber = voucher.number;
                const dbName = dbTable === 'grns' ? 'grns' : 'outwards';
                await saveToSupabase(dbName, shipmentRecord);
            }
        }

        voucher.reconciledShipments = shipmentIds;
        await saveToSupabase('generic_transactions', voucher);

        hideImportLoadingOverlay();
        showToast('Reconciliation statement created successfully!', 'success');
        
        window.printFreightPaymentStatement(voucher.id);
        window.renderFreightReconciliation();

    } catch (err) {
        hideImportLoadingOverlay();
        console.error("Reconciliation error:", err);
        showToast('Failed to reconcile: ' + err.message, 'error');
    }
};

window.printFreightPaymentStatement = function(voucherId) {
    const voucher = (db.genericTransactions || []).find(v => v.id === voucherId);
    if (!voucher) return;

    const shipments = [];
    const grns = [
        ...(db.grn_cust_plain || []),
        ...(db.grn_vend_emb || []),
        ...(db.grn_consumable || [])
    ];

    const linkedIds = voucher.reconciledShipments || [];
    linkedIds.forEach(id => {
        const g = grns.find(x => x.id === id);
        if (g) {
            shipments.push({
                date: g.date,
                type: 'GRN',
                number: g.grnNo || g.number,
                party: g.customerName || g.partyName || '-',
                taxiName: g.taxiName || '',
                transporter: g.transporterName || '',
                lrNo: g.lrNo || '-',
                vehicleNo: g.vehicleNo || '-',
                pkgCount: g.pkgCount || g.qty || 0
            });
        }
        const o = (db.outward || []).find(x => x.id === id);
        if (o) {
            shipments.push({
                date: o.date,
                type: 'Outward',
                number: o.number,
                party: o.customerName || o.vendorName || o.partyName || '-',
                taxiName: o.taxiName || '',
                transporter: o.transporterName || '',
                lrNo: o.lrNo || '-',
                vehicleNo: o.vehicleNo || '-',
                pkgCount: o.transportPkgCount || o.pkgCount || 0
            });
        }
    });

    let printArea = document.getElementById('print-area');
    if (!printArea) {
        printArea = document.createElement('div');
        printArea.id = 'print-area';
        document.body.appendChild(printArea);
    }

    const rowsHtml = shipments.map((s, idx) => `
        <tr style="border-bottom:1px solid #e2e8f0;">
            <td style="padding:8px; text-align:left;">${idx + 1}</td>
            <td style="padding:8px; text-align:left;">${formatDate(s.date)}</td>
            <td style="padding:8px; text-align:left;"><strong>${s.number}</strong> (${s.type})</td>
            <td style="padding:8px; text-align:left;">${s.party}</td>
            <td style="padding:8px; text-align:left;"><code>${s.lrNo}</code></td>
            <td style="padding:8px; text-align:left;"><code>${s.vehicleNo}</code></td>
            <td style="padding:8px; text-align:right; font-weight:600;">${s.pkgCount}</td>
        </tr>
    `).join('');

    const carrierName = shipments[0] ? (shipments[0].transporter || shipments[0].taxiName || voucher.partyName) : voucher.partyName;

    printArea.innerHTML = `
        <div class="print-doc" style="font-family:'Segoe UI',sans-serif; color:#1e293b; padding:40px;">
            <div style="display:flex; justify-content:space-between; border-bottom:2px solid #1e293b; padding-bottom:15px; margin-bottom:25px;">
                <div>
                    <h1 style="margin:0; font-size:24px; font-weight:700;">${window.currentCompany || 'Girisons Impex'}</h1>
                    <p style="margin:4px 0 0 0; font-size:12px; color:#64748b;">Freight Payment Justification Statement</p>
                </div>
                <div style="text-align:right;">
                    <h2 style="margin:0; font-size:18px; color:#ef4444;">PAYMENT RECONCILIATION</h2>
                    <p style="margin:4px 0 0 0; font-size:12px; color:#64748b;">Statement Date: ${formatDate(new Date().toISOString().split('T')[0])}</p>
                </div>
            </div>

            <div style="display:grid; grid-template-columns:1fr 1fr; gap:30px; margin-bottom:30px; background:#f8fafc; padding:20px; border-radius:8px; border:1px solid #e2e8f0; font-size:13px;">
                <div>
                    <h3 style="margin:0 0 10px 0; font-size:14px; text-transform:uppercase; color:#64748b;">Carrier Details</h3>
                    <p style="margin:4px 0;"><strong>Carrier / Transporter:</strong> ${carrierName}</p>
                    <p style="margin:4px 0;"><strong>Paid Party Name:</strong> ${voucher.partyName}</p>
                </div>
                <div style="text-align:right;">
                    <h3 style="margin:0 0 10px 0; font-size:14px; text-transform:uppercase; color:#64748b;">Voucher Reference</h3>
                    <p style="margin:4px 0;"><strong>Voucher No:</strong> ${voucher.number}</p>
                    <p style="margin:4px 0;"><strong>Voucher Date:</strong> ${formatDate(voucher.date)}</p>
                    <p style="margin:4px 0; font-size:15px; color:#10b981;"><strong>Amount Paid:</strong> �${parseFloat(voucher.totalValue || voucher.totalAmount || 0).toFixed(2)}</p>
                </div>
            </div>

            <h3 style="font-size:14px; color:#1e293b; margin-bottom:12px; text-transform:uppercase; letter-spacing:0.5px;">Reconciled Shipments &amp; Cargo Deliveries</h3>
            <table class="print-table" style="width:100%; border-collapse:collapse; margin-bottom:30px; font-size:12px;">
                <thead>
                    <tr style="background:#e2e8f0; border-bottom:2px solid #cbd5e1;">
                        <th style="padding:10px; text-align:left;">S.No.</th>
                        <th style="padding:10px; text-align:left;">Shipment Date</th>
                        <th style="padding:10px; text-align:left;">Document / Challan</th>
                        <th style="padding:10px; text-align:left;">Party Name</th>
                        <th style="padding:10px; text-align:left;">LR Number</th>
                        <th style="padding:10px; text-align:left;">Vehicle Number</th>
                        <th style="padding:10px; text-align:right;">Than / Pkg Count</th>
                    </tr>
                </thead>
                <tbody>
                    ${rowsHtml}
                </tbody>
            </table>

            <div style="margin-top:20px; font-size:12px; background:#f1f5f9; padding:15px; border-radius:6px; border-left:4px solid #3b82f6;">
                <strong>Justification Notes &amp; Remarks:</strong><br>
                This payment statement reconciles Voucher #${voucher.number} against the ${shipments.length} cargo shipments listed above. These shipments were processed and verified by the logistics department as completed.
                ${voucher.remarks ? `<br><br><strong>Voucher Remarks:</strong> ${voucher.remarks}` : ''}
            </div>

            <div class="print-footer" style="margin-top:80px; display:flex; justify-content:space-between; font-size:12px;">
                <div style="border-top:1px solid #cbd5e1; width:200px; text-align:center; padding-top:8px;">Prepared By</div>
                <div style="border-top:1px solid #cbd5e1; width:200px; text-align:center; padding-top:8px;">Logistics Manager</div>
                <div style="border-top:1px solid #cbd5e1; width:200px; text-align:center; padding-top:8px;">Authorized Signatory</div>
            </div>
        </div>
    `;

    document.body.classList.add('print-voucher-only');
    printArea.style.display = 'block';
    window.print();
    printArea.style.display = 'none';
    document.body.classList.remove('print-voucher-only');
};

