let reorderTargetType = ''; // 'tabs' or 'cards'
let reorderTargetModule = ''; // e.g. 'transactions'
let tempReorderList = []; // Array of { id, label, icon }

window.assignDynamicCardIds = function() {
    const grids = document.querySelectorAll('.utility-grid');
    grids.forEach((grid, gridIdx) => {
        const parentModule = grid.closest('.module-container');
        const moduleName = parentModule ? parentModule.id.replace('module-', '') : `grid-${gridIdx}`;
        
        const cards = grid.querySelectorAll('.utility-card');
        cards.forEach(card => {
            if (!card.id) {
                const titleEl = card.querySelector('.utility-title');
                const titleText = titleEl ? titleEl.textContent.trim() : '';
                const cleanTitle = titleText.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
                card.id = `card-${moduleName}-${cleanTitle}`;
            }
        });
    });
};

window.applyNavigationTabOrder = function() {
    const bar = document.getElementById('module-tabs-bar');
    if (!bar) return;
    const orderStr = localStorage.getItem('app_nav_tab_order');
    if (orderStr) {
        try {
            const tabIds = JSON.parse(orderStr);
            const buttons = {};
            Array.from(bar.children).forEach(btn => {
                if (btn.id) {
                    buttons[btn.id] = btn;
                }
            });
            tabIds.forEach(id => {
                if (buttons[id]) {
                    bar.appendChild(buttons[id]);
                    delete buttons[id];
                }
            });
            // Append any leftover buttons
            Object.values(buttons).forEach(btn => {
                bar.appendChild(btn);
            });
        } catch (e) {
            console.error('Error applying nav tab order:', e);
        }
    }
};

window.applyModuleGridCardsOrder = function(moduleName) {
    const modEl = document.getElementById('module-' + moduleName);
    if (!modEl) return;
    const grid = modEl.querySelector('.utility-grid');
    if (!grid) return;
    const orderStr = localStorage.getItem(`app_cards_order_${moduleName}`);
    if (orderStr) {
        try {
            const cardIds = JSON.parse(orderStr);
            const cards = {};
            grid.querySelectorAll('.utility-card').forEach(card => {
                if (card.id) {
                    cards[card.id] = card;
                }
            });
            cardIds.forEach(id => {
                if (cards[id]) {
                    grid.appendChild(cards[id]);
                    delete cards[id];
                }
            });
            // Append any leftover cards
            Object.values(cards).forEach(card => {
                grid.appendChild(card);
            });
        } catch (e) {
            console.error(`Error applying cards order for ${moduleName}:`, e);
        }
    }
};

window.applyAllModuleGridCardsOrders = function() {
    const modules = ['masters', 'transactions', 'production', 'inventory', 'freight', 'costing', 'reports', 'utilities'];
    modules.forEach(mod => {
        window.applyModuleGridCardsOrder(mod);
    });
};

