window.checkBusyHealthStatus = async function() {
    const banner = document.getElementById('busy-health-banner');
    if (!banner) return;

    try {
        const companyId = (window.currentCompany && window.currentCompany.id) || 'co4';
        const { data, error } = await supabase
            .from('busy_sync_queue')
            .select('sc, status, error_message, synced_at, vch_xml')
            .eq('voucher_no', 'BUSY_HEALTH_STATUS')
            .eq('company_id', companyId)
            .maybeSingle();

        if (error) {
            console.warn("[BusyHealth] Error fetching health record:", error.message);
            return;
        }

        if (!data) {
            banner.style.background = 'var(--bg-card)';
            banner.style.borderColor = 'var(--border)';
            banner.innerHTML = `<div style="display:flex; align-items:center; gap:8px;"><span style="color:#64748b;">� Busy ERP Health Status:</span> <span style="font-weight:600; color:#64748b;">Awaiting health monitor agent check on Cloud Server...</span></div>`;
            return;
        }

        const isUp = data.sc === 'UP' && data.status === 'success';
        const lastChecked = data.synced_at ? new Date(data.synced_at).toLocaleTimeString() : '?';

        if (isUp) {
            banner.style.background = '#e8f5e9';
            banner.style.borderColor = '#a5d6a7';
            banner.innerHTML = `
                <div style="display:flex; align-items:center; justify-content:space-between; width:100%;">
                    <div style="display:flex; align-items:center; gap:8px;">
                        <span style="font-size:16px;"></span>
                        <strong style="color:#2e7d32; font-size:13.5px;">Busy ERP Connected & Active</strong>
                    </div>
                    <small style="color:#4caf50; font-weight:600;">(Port 981 OK � Checked ${lastChecked})</small>
                </div>`;
        } else {
            const errMsg = data.error_message || 'Port 981 not responding � Busy ERP may be down';
            banner.style.background = '#ffebee';
            banner.style.borderColor = '#ef9a9a';
            banner.innerHTML = `
                <div style="display:flex; flex-direction:column; gap:4px; width:100%;">
                    <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap;">
                        <div style="display:flex; align-items:center; gap:8px;">
                            <span style="font-size:16px;">=4</span>
                            <strong style="color:#c62828; font-size:13.5px;">Busy ERP OFFLINE � ${errMsg}</strong>
                        </div>
                        <small style="color:#e53935; font-weight:600;">(Last checked ${lastChecked})</small>
                    </div>
                    <div style="font-size:12px; color:#b71c1c; margin-left:24px;">
                        = Standalone cloud agent is attempting auto-reconnect/restart every 30 seconds. Sync queue is safely paused.
                    </div>
                </div>`;
        }
    } catch (e) {
        console.error("[BusyHealth] Exception checking health status:", e);
    }
};

