window.txSortState = window.txSortState || {};
window.txSortState['gatepass'] = { field: 'date', order: 'desc' };

window.onGpPartyTypeChange = function() {
    const type = document.getElementById('gp-party-type').value;
    const custGroup = document.getElementById('gp-customer-group');
    const vendGroup = document.getElementById('gp-vendor-group');
    const otherGroup = document.getElementById('gp-other-group');
    
    if (type === 'Customer') {
        if (custGroup) custGroup.style.display = 'block';
        if (vendGroup) vendGroup.style.display = 'none';
        if (otherGroup) otherGroup.style.display = 'none';
    } else if (type === 'Vendor') {
        if (custGroup) custGroup.style.display = 'none';
        if (vendGroup) vendGroup.style.display = 'block';
        if (otherGroup) otherGroup.style.display = 'none';
    } else {
        if (custGroup) custGroup.style.display = 'none';
        if (vendGroup) vendGroup.style.display = 'none';
        if (otherGroup) otherGroup.style.display = 'block';
    }
};

window.addGpRow = function(desc = '', qty = '', unit = 'Pcs') {
    const tbody = document.getElementById('gp-items-grid-body');
    if (!tbody) return;
    const index = tbody.rows.length;
    const tr = document.createElement('tr');
    tr.innerHTML = `
        <td>${index + 1}</td>
        <td><input type="text" class="form-input gp-desc-in" value="${desc}" placeholder="Description of goods *"></td>
        <td><input type="number" class="form-input gp-qty-in" value="${qty}" placeholder="0" step="any"></td>
        <td><input type="text" class="form-input gp-unit-in" value="${unit}" placeholder="e.g. Pcs, Mtr, Kg"></td>
        <td><button class="btn btn-sm btn-danger" onclick="this.closest('tr').remove(); recalculateGpRowSNo();"></button></td>
    `;
    tbody.appendChild(tr);
};

window.recalculateGpRowSNo = function() {
    const tbody = document.getElementById('gp-items-grid-body');
    if (!tbody) return;
    Array.from(tbody.rows).forEach((row, idx) => {
        row.cells[0].textContent = idx + 1;
    });
};

window.openGatePassModal = function(editId = null) {
    if (!editId) {
        if (!checkPermission('gate_pass', 'write')) {
            showToast('Permission Denied', 'error');
            return;
        }
    }
    if (!checkPermission('gate_pass', 'read')) {
        showToast('Permission Denied', 'error');
        return;
    }

    document.getElementById('gp-edit-id').value = editId || '';
    document.getElementById('gp-modal-title').textContent = editId ? 'Edit Gate Pass' : 'New Gate Pass';
    
    document.getElementById('gp-date').value = today();
    const now = new Date();
    const timeStr = String(now.getHours()).padStart(2, '0') + ':' + String(now.getMinutes()).padStart(2, '0');
    document.getElementById('gp-time').value = timeStr;
    document.getElementById('gp-party-type').value = 'Customer';
    document.getElementById('gp-customer').value = '';
    document.getElementById('gp-vendor').value = '';
    document.getElementById('gp-party-name').value = '';
    document.getElementById('gp-type').value = 'Returnable';
    document.getElementById('gp-vehicle').value = '';
    document.getElementById('gp-transporter').value = '';
    document.getElementById('gp-status').value = 'Pending';
    document.getElementById('gp-remarks').value = '';
    document.getElementById('gp-items-grid-body').innerHTML = '';
    
    window.onGpPartyTypeChange();
    window.populateAllDropdowns();
    
    const printBtn = document.getElementById('gp-print-btn');
    if (printBtn) printBtn.style.display = editId ? 'inline-block' : 'none';

    if (editId) {
        rawDB.gatePasses = rawDB.gatePasses || [];
        const gp = rawDB.gatePasses.find(x => x.id === editId);
        if (gp) {
            document.getElementById('gp-number').value = gp.number || '';
            document.getElementById('gp-date').value = gp.date || today();
            if (gp.time) document.getElementById('gp-time').value = gp.time;
            document.getElementById('gp-party-type').value = gp.partyType || 'Customer';
            window.onGpPartyTypeChange();
            
            if (gp.partyType === 'Customer') {
                document.getElementById('gp-customer').value = gp.partyId || '';
            } else if (gp.partyType === 'Vendor') {
                document.getElementById('gp-vendor').value = gp.partyId || '';
            } else {
                document.getElementById('gp-party-name').value = gp.partyName || '';
            }
            
            document.getElementById('gp-type').value = gp.gatepassType || 'Returnable';
            document.getElementById('gp-vehicle').value = gp.vehicleNo || '';
            document.getElementById('gp-transporter').value = gp.transporterId || '';
            document.getElementById('gp-status').value = gp.status || 'Pending';
            document.getElementById('gp-remarks').value = gp.remarks || '';
            
            if (gp.items && Array.isArray(gp.items)) {
                gp.items.forEach(it => {
                    window.addGpRow(it.description, it.qty, it.unit);
                });
            }
        }
    } else {
        let maxSeq = 0;
        (rawDB.gatePasses || []).forEach(gp => {
            const num = gp.number || '';
            const parts = num.split('/');
            if (parts.length >= 3) {
                const seq = parseInt(parts[parts.length - 1]);
                if (!isNaN(seq) && seq > maxSeq) maxSeq = seq;
            }
        });
        const nextNo = maxSeq + 1;
        document.getElementById('gp-number').value = getDocumentNumber('GP', nextNo);
        window.addGpRow();
    }
    
    ['gp-customer', 'gp-vendor', 'gp-transporter'].forEach(id => {
        const el = document.getElementById(id);
        if (el && typeof reinitSearchableSelect === 'function') {
            reinitSearchableSelect(el);
        }
    });

    openModal('gatepass-modal');
};

window.saveGatePass = async function() {
    if (!currentCompany) {
        showToast('Please select a company first', 'error');
        return;
    }

    const editId = document.getElementById('gp-edit-id').value;
    if (!editId) {
        if (!checkPermission('gate_pass', 'write')) {
            showToast('Permission Denied', 'error');
            return;
        }
    } else {
        if (!checkPermission('gate_pass', 'write')) {
            showToast('Permission Denied', 'error');
            return;
        }
    }

    const dateVal = document.getElementById('gp-date').value;
    if (!dateVal || !validateTransactionDate(dateVal)) {
        return;
    }

    const timeVal = document.getElementById('gp-time').value;
    const numberVal = document.getElementById('gp-number').value;
    const partyType = document.getElementById('gp-party-type').value;
    const gatepassType = document.getElementById('gp-type').value;
    const vehicleNo = document.getElementById('gp-vehicle').value.trim();
    const transporterId = document.getElementById('gp-transporter').value;
    const status = document.getElementById('gp-status').value;
    const remarks = document.getElementById('gp-remarks').value.trim();

    let partyId = '';
    let partyName = '';

    if (partyType === 'Customer') {
        partyId = document.getElementById('gp-customer').value;
        if (!partyId) {
            showToast('Please select a Customer', 'error');
            return;
        }
        const custObj = db.customers.find(c => c.id === partyId);
        partyName = custObj ? custObj.name : 'Unknown Customer';
    } else if (partyType === 'Vendor') {
        partyId = document.getElementById('gp-vendor').value;
        if (!partyId) {
            showToast('Please select a Vendor', 'error');
            return;
        }
        const vendObj = db.vendors.find(v => v.id === partyId);
        partyName = vendObj ? vendObj.name : 'Unknown Vendor';
    } else {
        partyName = document.getElementById('gp-party-name').value.trim();
        if (!partyName) {
            showToast('Please enter Party Name', 'error');
            return;
        }
    }

    const tbody = document.getElementById('gp-items-grid-body');
    const items = [];
    let hasError = false;

    Array.from(tbody.rows).forEach((row, idx) => {
        const descInput = row.querySelector('.gp-desc-in');
        const qtyInput = row.querySelector('.gp-qty-in');
        const unitInput = row.querySelector('.gp-unit-in');

        const desc = descInput ? descInput.value.trim() : '';
        const qty = qtyInput ? parseFloat(qtyInput.value) || 0 : 0;
        const unit = unitInput ? unitInput.value.trim() : '';

        if (!desc) {
            showToast(`Description is required on row ${idx + 1}`, 'error');
            hasError = true;
            return;
        }
        if (qty <= 0) {
            showToast(`Quantity must be greater than zero on row ${idx + 1}`, 'error');
            hasError = true;
            return;
        }

        items.push({
            sno: idx + 1,
            description: desc,
            qty: qty,
            unit: unit
        });
    });

    if (hasError) return;
    if (items.length === 0) {
        showToast('Please add at least one item', 'error');
        return;
    }

    const record = {
        id: editId || 'gp_' + uid(),
        company_id: currentCompany.id,
        number: numberVal,
        date: dateVal,
        time: timeVal,
        partyType: partyType,
        partyId: partyId,
        partyName: partyName,
        gatepassType: gatepassType,
        vehicleNo: vehicleNo,
        transporterId: transporterId,
        remarks: remarks,
        status: status,
        items: items
    };

    try {
        await saveToSupabase('gate_passes', record);
        
        rawDB.gatePasses = rawDB.gatePasses || [];
        if (editId) {
            const idx = rawDB.gatePasses.findIndex(x => x.id === editId);
            if (idx !== -1) rawDB.gatePasses[idx] = record;
        } else {
            rawDB.gatePasses.push(record);
        }

        showToast('Gate Pass saved successfully!', 'success');
        closeModal('gatepass-modal');
        renderGatePassTable();
        renderDashboard();
    } catch (e) {
        console.error("Failed to save gate pass:", e);
        showToast('Failed to save Gate Pass', 'error');
    }
};

window.deleteGatePass = async function(id) {
    if (!checkPermission('gate_pass', 'delete')) {
        showToast('Permission Denied', 'error');
        return;
    }

    const gp = rawDB.gatePasses.find(x => x.id === id);
    if (!gp) return;

    if (await window.showSmartConfirm('Delete Gate Pass', `Are you sure you want to delete Gate Pass ${gp.number}?`)) {
        try {
            await deleteFromSupabase('gate_passes', id);
            rawDB.gatePasses = rawDB.gatePasses.filter(x => x.id !== id);
            showToast('Gate Pass deleted successfully', 'success');
            renderGatePassTable();
            renderDashboard();
        } catch (e) {
            console.error("Failed to delete gate pass:", e);
            showToast('Failed to delete Gate Pass', 'error');
        }
    }
};

window.cancelGatePass = async function() {
    const editId = document.getElementById('gp-edit-id').value;
    if (!editId) {
        showToast('No active voucher to cancel', 'error');
        return;
    }
    if (!checkPermission('gate_pass', 'write')) {
        showToast('Permission Denied', 'error');
        return;
    }

    const gp = rawDB.gatePasses.find(x => x.id === editId);
    if (!gp) return;

    if (await window.showSmartConfirm('Cancel Gate Pass', `Are you sure you want to cancel Gate Pass ${gp.number}?`)) {
        try {
            gp.status = 'Cancelled';
            await saveToSupabase('gate_passes', gp);
            showToast('Gate Pass cancelled successfully', 'success');
            closeModal('gatepass-modal');
            renderGatePassTable();
            renderDashboard();
        } catch (e) {
            console.error("Failed to cancel gate pass:", e);
            showToast('Failed to cancel Gate Pass', 'error');
        }
    }
};

window.gatepassBulkDelete = async function() {
    if (!checkPermission('gate_pass', 'delete')) {
        showToast('Permission Denied', 'error');
        return;
    }

    const checkboxes = document.querySelectorAll('.chk-select-gatepass');
    const ids = Array.from(checkboxes).filter(cb => cb.checked).map(cb => cb.value);

    if (ids.length === 0) {
        showToast('No items selected.', 'info');
        return;
    }

    if (await window.showSmartConfirm('Bulk Delete', `Are you sure you want to delete the ${ids.length} selected Gate Passes?`)) {
        try {
            await deleteMultipleFromSupabase('gate_passes', ids);
            rawDB.gatePasses = rawDB.gatePasses.filter(x => !ids.includes(x.id));
            showToast('Selected Gate Passes deleted successfully', 'success');
            renderGatePassTable();
            renderDashboard();
        } catch (e) {
            console.error("Failed to bulk delete gate passes:", e);
            showToast('Bulk delete failed', 'error');
        }
    }
};

window.renderGatePassTable = function() {
    const tbody = document.getElementById('tx-gp-table-body');
    if (!tbody) return;

    rawDB.gatePasses = rawDB.gatePasses || [];
    
    const sortConf = window.txSortState?.['gatepass'] || { field: 'date', order: 'desc' };
    const sortField = sortConf.field;
    const sortOrder = sortConf.order === 'asc' ? 1 : -1;
    
    let list = [...rawDB.gatePasses];

    const searchVal = document.getElementById('tx-gp-search')?.value.toLowerCase().trim() || '';
    if (searchVal) {
        list = list.filter(gp => 
            (gp.number || '').toLowerCase().includes(searchVal) ||
            (gp.partyName || '').toLowerCase().includes(searchVal) ||
            (gp.remarks || '').toLowerCase().includes(searchVal) ||
            (gp.vehicleNo || '').toLowerCase().includes(searchVal)
        );
    }

    list = list.filter(gp => isDateInCurrentFY(gp.date, gp.number));

    list.sort((a, b) => {
        let valA = '';
        let valB = '';

        if (sortField === 'number') {
            const numA = getBaseNumber(a.number) || 0;
            const numB = getBaseNumber(b.number) || 0;
            return (numA - numB) * sortOrder;
        } else if (sortField === 'date') {
            valA = a.date ? new Date(a.date).getTime() : 0;
            valB = b.date ? new Date(b.date).getTime() : 0;
        } else if (sortField === 'partyType') {
            valA = a.partyType || '';
            valB = b.partyType || '';
        } else if (sortField === 'partyName') {
            valA = a.partyName || '';
            valB = b.partyName || '';
        } else if (sortField === 'gatepassType') {
            valA = a.gatepassType || '';
            valB = b.gatepassType || '';
        } else if (sortField === 'status') {
            valA = a.status || '';
            valB = b.status || '';
        }

        if (valA < valB) return -1 * sortOrder;
        if (valA > valB) return 1 * sortOrder;
        return 0;
    });

    const fields = ['number', 'date', 'partyType', 'partyName', 'gatepassType', 'status'];
    fields.forEach(f => {
        const iconEl = document.getElementById(`sort-icon-tx-gatepass-${f}`);
        if (iconEl) {
            if (sortConf.field === f) {
                iconEl.textContent = sortConf.order === 'asc' ? ' =<' : ' ==';
            } else {
                iconEl.textContent = '';
            }
        }
    });

    toggleBulkDeleteButton('gatepass');

    if (list.length === 0) {
        tbody.innerHTML = '<tr><td colspan="8" class="empty-row" style="text-align:center;">No Gate Passes found.</td></tr>';
        return;
    }

    tbody.innerHTML = list.map(gp => {
        const formattedDate = gp.date ? formatDate(gp.date) : '-';
        let statusBadge = 'badge-secondary';
        if (gp.status === 'Pending') statusBadge = 'badge-orange';
        else if (gp.status === 'Passed') statusBadge = 'badge-green';
        else if (gp.status === 'Cancelled') statusBadge = 'badge-red';

        const hasEditPerm = checkPermission('gate_pass', 'write');
        const hasDelPerm = checkPermission('gate_pass', 'delete');

        return `
            <tr>
                <td><input type="checkbox" class="chk-select-gatepass" value="${gp.id}" onchange="toggleBulkDeleteButton('gatepass')"></td>
                <td><strong><a href="#" onclick="event.preventDefault(); openGatePassModal('${gp.id}')" style="color:var(--accent-blue); text-decoration:none;">${gp.number}</a></strong></td>
                <td>${formattedDate}</td>
                <td>${gp.partyType}</td>
                <td>${gp.partyName}</td>
                <td><span class="badge" style="background:var(--bg-secondary); color:var(--text-primary); border:1px solid var(--border); font-weight:600;">${gp.gatepassType}</span></td>
                <td><span class="badge ${statusBadge}">${gp.status}</span></td>
                <td>
                    <div style="display:flex; gap:6px;">
                        ${hasEditPerm ? `<button class="btn btn-sm btn-secondary" onclick="openGatePassModal('${gp.id}')"> Edit</button>` : ''}
                        <button class="btn btn-sm btn-secondary" onclick="window.printCurrentVoucher('gp', '${gp.id}')">=� Print</button>
                        ${hasDelPerm ? `<button class="btn btn-sm btn-danger" onclick="deleteGatePass('${gp.id}')">=� Delete</button>` : ''}
                    </div>
                </td>
            </tr>
        `;
    }).join('');
};

