window.checkBOMSyncForProduction = async function(finishedItemName, finishedItemId) {
    db.boms = db.boms || [];
    let bom = db.boms.find(b => b.finishedItemName === finishedItemName || b.finishedItemId === finishedItemId);
    if (!bom) {
        const { data: dbBoms } = await supabase
            .from('boms')
            .select('*')
            .eq('finishedItemName', finishedItemName)
            .limit(1);
        if (dbBoms && dbBoms.length > 0) {
            bom = dbBoms[0];
            db.boms.push(bom);
        }
    }
    
    if (!bom) {
        showToast(`BOM not found for finished item "${finishedItemName}". Please create the BOM first.`, 'warning');
        return false;
    }

    const { data: syncedBoms } = await supabase
        .from('busy_sync_queue')
        .select('id')
        .eq('voucher_id', bom.id)
        .eq('status', 'success')
        .limit(1);

    if (!syncedBoms || syncedBoms.length === 0) {
        showToast(`The BOM "${bom.code} - ${bom.finishedItemName}" is not synced to Busy yet. Please sync the BOM first.`, 'warning');
        return false;
    }

    return true;
};

window.confirmAndSyncProductionSlip = async function(id) {
    if (window.isBusySyncPaused && window.isBusySyncPaused('production')) {
        showToast('Sync for Production is temporarily paused.', 'warning');
        return;
    }
    const slip = (db.productionSlips || []).find(x => x.id === id);
    if (!slip) {
        showToast('Production slip not found.', 'error');
        return;
    }

    const isSampling = slip.number && slip.number.startsWith('SMP');
    if (!isSampling) {
        const canSync = await window.checkBOMSyncForProduction(slip.finishedItemName, slip.finishedItemId);
        if (!canSync) return;
    }
    
    if (!(await window.showSmartConfirm('Sync to Busy ERP', `Do you want to sync Production Slip ${slip.number} to Busy ERP?`))) {
        return;
    }
    
    showToast('Queueing Production Slip for Busy...', 'info');
    
    try {
        const { data: synced } = await supabase
            .from('busy_sync_queue')
            .select('id')
            .eq('voucher_id', slip.id)
            .eq('status', 'success')
            .limit(1);
        
        const isEdit = synced && synced.length > 0;
        
        await window.queueProductionSlipForBusySync(slip, isEdit);
        showToast('Production Slip queued! Cloud agent will sync it shortly.', 'success');
        
        if (typeof renderProductionTable === 'function') renderProductionTable();
    } catch (err) {
        showToast('Failed to queue Production Slip: ' + err.message, 'error');
    }
};

window.queueProductionSlipForBusySync = async function(slipData, isEdit) {
    try {
        const formattedDate = formatDateToBusy(slipData.date);
        const finishedItemName = slipData.finishedItemName || 'Unknown Item';
        const qty = slipData.qty || 0;
        
        // Clean voucher number: strip leading zeros from the last numeric group to match Busy automatic numbering (e.g. PRD/26-27/005 -> PRD/26-27/5)
        const cleanVchNo = slipData.number.replace(/\/0+(\d+)$/, '/$1');
        
        const series = slipData.number.startsWith('SMP') ? 'SAM' : (slipData.number.startsWith('PRD') ? 'PROD' : 'Main');
        const bomName = slipData.number.startsWith('SMP') ? 'SAMPLE (JOB WORK)' : finishedItemName;
        
        const xmlPayload = `<Production>
            <VchSeriesName>${series}</VchSeriesName>
            <Date>${formattedDate}</Date>
            <VchType>6</VchType>
            <StockUpdationDate>${formattedDate}</StockUpdationDate>
            <VchNo>${escapeXml(cleanVchNo)}</VchNo>
            <ConMCName>Main Store</ConMCName>
            <MasterName1>Main Store</MasterName1>
            <MasterName2>${escapeXml(bomName)}</MasterName2>
            <TranCurName>Rs.</TranCurName>
            <BillingDetails>
                <tmpVchCode>0</tmpVchCode>
            </BillingDetails>
            <ItemEntries>
                <ItemDetail>
                    <Date>${formattedDate}</Date>
                    <VchType>6</VchType>
                    <VchNo>${escapeXml(cleanVchNo)}</VchNo>
                    <SrNo>1</SrNo>
                    <ItemName>${escapeXml(finishedItemName)}</ItemName>
                    <UnitName>Metre</UnitName>
                    <AltUnitName>Metre</AltUnitName>
                    <ConFactor>1</ConFactor>
                    <Qty>${qty}</Qty>
                    <QtyMainUnit>${qty}</QtyMainUnit>
                    <QtyAltUnit>${qty}</QtyAltUnit>
                    <RecType>2</RecType>
                </ItemDetail>
            </ItemEntries>
            <VchOtherInfoDetails>
                <Narration1>${escapeXml(slipData.remarks || '')}</Narration1>
            </VchOtherInfoDetails>
        </Production>`.replace(/\s+/g, ' ').trim();

        let scCode = isEdit ? '3' : '2';
        if (isEdit) {
            const { data: successCheck } = await supabase
                .from('busy_sync_queue')
                .select('id')
                .eq('voucher_id', slipData.id)
                .eq('status', 'success')
                .limit(1);
            if (!successCheck || successCheck.length === 0) {
                scCode = '2';
            }
        }

        const syncRecord = {
            company_id: slipData.company_id || (window.currentCompany ? window.currentCompany.id : 'co4'),
            voucher_id: slipData.id,
            voucher_no: slipData.number,
            voucher_type: '6',
            sc: scCode,
            vch_xml: xmlPayload,
            status: 'hold',
            created_at: new Date().toISOString()
        };

        const { data: existing } = await supabase
            .from('busy_sync_queue')
            .select('id')
            .eq('voucher_id', slipData.id)
            .limit(1);

        if (existing && existing.length > 0) {
            await supabase
                .from('busy_sync_queue')
                .update(syncRecord)
                .eq('voucher_id', slipData.id);
        } else {
            await supabase
                .from('busy_sync_queue')
                .insert(syncRecord);
        }
        console.log(`Production Slip ${slipData.number} queued for Busy sync.`);
    } catch (e) {
        console.error("Error queueing Production Slip for Busy sync:", e);
        throw e;
    }
};

