// ===== RATE AGREEMENTS (RAMA LOGISTICS) =====
window.calcRateAgreementEstimate = function() {
    const mode = document.getElementById('rateagreement-billing-mode') ? document.getElementById('rateagreement-billing-mode').value : 'Per KM';
    const rate = parseFloat(document.getElementById('rateagreement-rate') ? document.getElementById('rateagreement-rate').value : 0) || 0;
    const distVal = document.getElementById('rateagreement-fixed-distance') ? document.getElementById('rateagreement-fixed-distance').value : '';
    const textEl = document.getElementById('rateagreement-estimate-text');
    const estBox = document.getElementById('rateagreement-estimate-box');
    
    if (mode === 'Fixed Per Day') {
        if (estBox) estBox.style.display = 'block';
        if (distVal === 'User Defined') {
            if (textEl) {
                textEl.textContent = `� ${rate.toFixed(2)} / KM (User Defined) � Dynamic calculation based on shipment distance.`;
            }
        } else {
            const dist = parseFloat(distVal) || 0;
            const total = rate * dist;
            if (textEl) {
                textEl.textContent = `� ${total.toFixed(2)} / day (${rate} �/km � ${dist} km) � Unlimited shipments allowed per day for this party.`;
            }
        }
    } else {
        if (estBox) estBox.style.display = 'none';
    }
};

window.onRateAgreementDistanceSelectChange = function() {
    const sel = document.getElementById('rateagreement-fixed-distance-select');
    const input = document.getElementById('rateagreement-fixed-distance');
    if (!sel || !input) return;
    
    if (sel.value === 'custom') {
        input.style.display = 'block';
        if (input.value === 'User Defined' || !input.value) {
            input.value = '10';
        }
    } else if (sel.value === 'User Defined') {
        input.style.display = 'none';
        input.value = 'User Defined';
    } else {
        input.style.display = 'none';
        input.value = sel.value;
    }
    if (typeof window.calcRateAgreementEstimate === 'function') window.calcRateAgreementEstimate();
};

window.onRateAgreementBillingModeChange = function() {
    const modeSelect = document.getElementById('rateagreement-billing-mode');
    const mode = modeSelect ? modeSelect.value : 'Per KM';
    const distGroup = document.getElementById('group-fixed-distance');
    const distLabel = document.getElementById('label-fixed-distance');
    const distInput = document.getElementById('rateagreement-fixed-distance');
    const distSelect = document.getElementById('rateagreement-fixed-distance-select');
    const minGroup = document.getElementById('rateagreement-min-charge') ? document.getElementById('rateagreement-min-charge').parentElement : null;

    if (distGroup) distGroup.style.display = 'block';
    
    if (mode === 'Fixed Per Day') {
        if (distLabel) distLabel.textContent = 'Min Daily Route Distance (KM) *';
        if (distInput && (!distInput.value || parseFloat(distInput.value) === 0)) {
            distInput.value = '10';
            if (distSelect) distSelect.value = '10';
        }
        if (minGroup) minGroup.style.display = 'none';
    } else {
        if (distLabel) distLabel.textContent = 'Standard Route Distance (KM)';
        if (minGroup) minGroup.style.display = 'block';
    }
    
    if (typeof window.calcRateAgreementEstimate === 'function') window.calcRateAgreementEstimate();
};

window.populateRateAgreementCustomerDropdown = function() {
    const sel = document.getElementById('rateagreement-customer-id');
    if (!sel) return;
    sel.innerHTML = '<option value="">-- Select Customer --</option>';
    
    const list = [...(db.customers || []), ...(db.vendors || [])];
    const seen = new Set();
    
    list.forEach(c => {
        if (!c.name || seen.has(c.name.toLowerCase().trim())) return;
        seen.add(c.name.toLowerCase().trim());
        const opt = document.createElement('option');
        opt.value = c.id || c.name;
        opt.setAttribute('data-name', c.name);
        opt.textContent = c.name + (c.city ? ' (' + c.city + ')' : '');
        sel.appendChild(opt);
    });
};

window.syncRateAgreementCustomerName = function() {
    const sel = document.getElementById('rateagreement-customer-id');
    const nameInput = document.getElementById('rateagreement-customer-name');
    if (!sel || !nameInput) return;
    const selectedOpt = sel.options[sel.selectedIndex];
    if (selectedOpt && selectedOpt.value) {
        nameInput.value = selectedOpt.getAttribute('data-name') || selectedOpt.text;
    } else {
        nameInput.value = '';
    }
};

window.openRateAgreementModal = function(editId = null) {
    if (typeof checkPermission === 'function' && !checkPermission('masters', 'write')) {
        if (typeof showToast === 'function') showToast('Permission Denied', 'error');
        return;
    }

    window.populateRateAgreementCustomerDropdown();
    
    document.getElementById('rateagreement-edit-id').value = editId || '';
    document.getElementById('rateagreement-customer-id').value = '';
    document.getElementById('rateagreement-customer-name').value = '';
    document.getElementById('rateagreement-billing-mode').value = 'Per KM';
    document.getElementById('rateagreement-rate').value = '';
    document.getElementById('rateagreement-fixed-distance').value = '10';
    document.getElementById('rateagreement-min-charge').value = '';
    document.getElementById('rateagreement-vehicle-type').value = 'All / Standard';
    document.getElementById('rateagreement-effective-date').value = new Date().toISOString().split('T')[0];
    document.getElementById('rateagreement-remarks').value = '';
    
    const selectEl = document.getElementById('rateagreement-fixed-distance-select');
    if (selectEl) {
        selectEl.value = '10';
        document.getElementById('rateagreement-fixed-distance').style.display = 'none';
    }
        
    const titleEl = document.getElementById('rateagreement-modal-title');
    if (editId) {
        if (titleEl) titleEl.innerHTML = ' Edit Rate Agreement';
        db.rateAgreements = db.rateAgreements || [];
        const ra = db.rateAgreements.find(x => String(x.id) === String(editId));
        if (ra) {
            let custIdVal = ra.customerId || '';
            if (!custIdVal && ra.customerName) {
                const list = [...(db.customers || []), ...(db.vendors || [])];
                const matched = list.find(c => c.name && c.name.toLowerCase().trim() === ra.customerName.toLowerCase().trim());
                if (matched) {
                    custIdVal = matched.id || matched.name;
                }
            }
            document.getElementById('rateagreement-customer-id').value = custIdVal || ra.customerName || '';
            document.getElementById('rateagreement-customer-name').value = ra.customerName || '';
            document.getElementById('rateagreement-billing-mode').value = ra.billingMode || 'Per KM';
            document.getElementById('rateagreement-rate').value = ra.ratePerKm || '';
            document.getElementById('rateagreement-min-charge').value = ra.minCharge || '';
            document.getElementById('rateagreement-vehicle-type').value = ra.vehicleType || 'All / Standard';
            document.getElementById('rateagreement-effective-date').value = ra.effectiveFrom || '';
            document.getElementById('rateagreement-remarks').value = ra.remarks || '';
            
            const fd = ra.fixedDistance !== undefined ? ra.fixedDistance : '10';
            const inputEl = document.getElementById('rateagreement-fixed-distance');
            if (selectEl && inputEl) {
                inputEl.value = fd;
                if (fd === 'User Defined') {
                    selectEl.value = 'User Defined';
                    inputEl.style.display = 'none';
                } else if (['10', '15', '20', '25', '30', '40', '50'].includes(String(fd))) {
                    selectEl.value = String(fd);
                    inputEl.style.display = 'none';
                } else {
                    selectEl.value = 'custom';
                    inputEl.style.display = 'block';
                }
            }
        }
    } else {
        if (titleEl) titleEl.innerHTML = '� Add Rate Agreement';
    }
    
    window.onRateAgreementBillingModeChange();
    openModal('rateagreement-modal');
};

window.saveRateAgreement = async function() {
    if (typeof checkPermission === 'function' && !checkPermission('masters', 'write')) {
        if (typeof showToast === 'function') showToast('Permission Denied', 'error');
        return;
    }

    const editId = document.getElementById('rateagreement-edit-id').value;
    const custSel = document.getElementById('rateagreement-customer-id');
    const customerName = document.getElementById('rateagreement-customer-name').value || (custSel ? custSel.options[custSel.selectedIndex]?.text : '');
    const destinationParty = '';
    const billingMode = document.getElementById('rateagreement-billing-mode').value || 'Per KM';
    const ratePerKm = parseFloat(document.getElementById('rateagreement-rate').value) || 0;
    
    const fdVal = document.getElementById('rateagreement-fixed-distance').value;
    const fixedDistance = fdVal === 'User Defined' ? 'User Defined' : (parseFloat(fdVal) || 0);
    
    const minCharge = parseFloat(document.getElementById('rateagreement-min-charge').value) || 0;
    const vehicleType = document.getElementById('rateagreement-vehicle-type').value || 'All / Standard';
    const effectiveFrom = document.getElementById('rateagreement-effective-date').value || new Date().toISOString().split('T')[0];
    const remarks = document.getElementById('rateagreement-remarks').value.trim();
    const status = 'Active';

    if (!customerName || !customerName.trim()) {
        if (typeof showToast === 'function') showToast('Please select or enter Customer Name', 'error');
        return;
    }
    if (ratePerKm <= 0) {
        if (typeof showToast === 'function') showToast('Please enter a valid Rate per KM', 'error');
        return;
    }

    const dailyFixedRate = billingMode === 'Fixed Per Day' ? (ratePerKm * (fixedDistance === 'User Defined' ? 0 : fixedDistance)) : 0;

    db.rateAgreements = db.rateAgreements || [];
    const companyId = currentCompany ? currentCompany.id : 'co3';

    const raData = {
        id: editId || ('ra_' + Date.now()),
        company_id: companyId,
        customerId: custSel ? custSel.value : '',
        customerName: customerName.trim(),
        destinationParty: destinationParty,
        billingMode: billingMode,
        ratePerKm: ratePerKm,
        fixedDistance: fixedDistance,
        dailyFixedRate: dailyFixedRate,
        minCharge: minCharge,
        vehicleType: vehicleType,
        effectiveFrom: effectiveFrom,
        remarks: remarks,
        status: status,
        updated_at: new Date().toISOString()
    };

    if (editId) {
        const idx = db.rateAgreements.findIndex(x => String(x.id) === String(editId));
        if (idx >= 0) db.rateAgreements[idx] = raData;
        else db.rateAgreements.push(raData);
    } else {
        db.rateAgreements.push(raData);
    }

    try {
        localStorage.setItem('local_rate_agreements_' + companyId, JSON.stringify(db.rateAgreements));
    } catch(e) {}

    if (window.supabase) {
        try {
            await window.supabase.from('rate_agreements').upsert({
                id: raData.id,
                company_id: companyId,
                customer_id: raData.customerId,
                customer_name: raData.customerName,
                destination_party: raData.destinationParty,
                billing_mode: raData.billingMode,
                rate_per_km: raData.ratePerKm,
                fixed_distance: raData.fixedDistance,
                daily_fixed_rate: raData.dailyFixedRate,
                min_charge: raData.minCharge,
                vehicle_type: raData.vehicleType,
                effective_from: raData.effectiveFrom,
                remarks: raData.remarks,
                status: raData.status
            });
        } catch(e) {
            console.error('Error saving rate agreement to Supabase:', e);
        }
    }

    closeModal('rateagreement-modal');
    if (typeof showToast === 'function') showToast(editId ? 'Rate Agreement updated!' : 'Rate Agreement added successfully!', 'success');
    renderRateAgreementTable();
};

window.deleteRateAgreement = async function(id) {
    if (typeof checkPermission === 'function' && !checkPermission('masters', 'delete')) {
        if (typeof showToast === 'function') showToast('Permission Denied', 'error');
        return;
    }
    db.rateAgreements = db.rateAgreements || [];
    const ra = db.rateAgreements.find(x => String(x.id) === String(id));
    if (!ra) return;

    const confirmMsg = `Are you sure you want to delete Rate Agreement for ${ra.customerName}?`;
    if (window.showSmartConfirm) {
        if (!(await window.showSmartConfirm('Delete Rate Agreement', confirmMsg))) return;
    } else {
        if (!confirm(confirmMsg)) return;
    }

    db.rateAgreements = db.rateAgreements.filter(x => String(x.id) !== String(id));
    const companyId = currentCompany ? currentCompany.id : 'co3';
    try {
        localStorage.setItem('local_rate_agreements_' + companyId, JSON.stringify(db.rateAgreements));
    } catch(e) {}

    if (window.supabase) {
        try {
            await window.supabase.from('rate_agreements').delete().eq('id', id);
        } catch(e) {}
    }

    if (typeof showToast === 'function') showToast('Rate agreement deleted', 'info');
    renderRateAgreementTable();
};

window.renderRateAgreementTable = function() {
    db.rateAgreements = db.rateAgreements || [];

    if (!db.rateAgreements.length) {
        const companyId = currentCompany ? currentCompany.id : 'co3';
        try {
            const local = JSON.parse(localStorage.getItem('local_rate_agreements_' + companyId) || '[]');
            if (local.length) db.rateAgreements = local;
        } catch(e) {}
    }

    renderDynamicHeader('rateagreement', 'rateagreement-table-head');
    const config = window.getTableColumnConfig('rateagreement');
    const isVis = (k) => { const col = config.find(c => c.key === k); return col ? col.visible !== false : true; };

    const search = getMasterSearchQuery();
    const tbody = document.getElementById('rateagreement-table-body');
    if (!tbody) return;

    let data = db.rateAgreements.filter(r => 
        (r.customerName || '').toLowerCase().includes(search) ||
                (r.vehicleType || '').toLowerCase().includes(search) ||
        (r.remarks || '').toLowerCase().includes(search)
    );

    if (!data.length) {
        tbody.innerHTML = '<tr><td colspan="10" class="empty-row">No rate agreements defined yet. Click � Add to create one.</td></tr>';
        return;
    }

    const canWrite = typeof checkPermission === 'function' ? checkPermission('masters', 'write') : true;
    const canDelete = typeof checkPermission === 'function' ? checkPermission('masters', 'delete') : true;

    tbody.innerHTML = data.map((r, i) => {
        const isFixedDaily = r.billingMode === 'Fixed Per Day';
        const isUserDef = r.fixedDistance === 'User Defined';
        const dailyVal = isUserDef ? 0 : (r.dailyFixedRate || (r.ratePerKm * (parseFloat(r.fixedDistance) || 0)));
        const modeBadge = isFixedDaily 
            ? (isUserDef 
                ? `<span class="badge" style="background:#e0e7ff; color:#3730a3; border:1px solid #c7d2fe; font-weight:700;">=� Fixed � ${parseFloat(r.ratePerKm || 0).toFixed(2)} / KM (User Defined)</span>`
                : `<span class="badge" style="background:#e0e7ff; color:#3730a3; border:1px solid #c7d2fe; font-weight:700;">=� Fixed � ${dailyVal.toFixed(2)} / day</span>`
              )
            : `<span class="badge badge-purple">=� Per KM</span>`;

        return `
            <tr style="${r.status === 'Inactive' ? 'opacity: 0.6;' : ''}">
                <td><input type="checkbox" class="chk-select-mst" value="${r.id}" onchange="toggleBulkDeleteButton('mst')"></td>
                <td>${i + 1}</td>
                ${isVis('customerName') ? `<td><strong>${r.customerName}</strong></td>` : ''}
                
                ${isVis('billingMode') ? `<td>${modeBadge}</td>` : ''}
                ${isVis('ratePerKm') ? `<td><strong>� ${parseFloat(r.ratePerKm || 0).toFixed(2)}</strong> / km</td>` : ''}
                ${isVis('minCharge') ? `<td>${isFixedDaily ? (isUserDef ? `<strong>User Defined</strong>` : `<strong>${r.fixedDistance || 0} km</strong> (` + '� ' + dailyVal.toFixed(2) + '/day)') : (r.minCharge ? ('Min � ' + parseFloat(r.minCharge).toFixed(2)) : '-')}</td>` : ''}
                ${isVis('effectiveFrom') ? `<td>${r.effectiveFrom || '-'}</td>` : ''}
                                <td>
                    <div class="table-actions">
                        ${canWrite ? `<button class="btn btn-sm btn-secondary" onclick="openRateAgreementModal('${r.id}')"></button>` : ''}
                        ${canDelete ? `<button class="btn btn-sm btn-danger" onclick="deleteRateAgreement('${r.id}')">=�</button>` : ''}
                    </div>
                </td>
            </tr>
        `;
    }).join('');
};

window.getRateAgreementForCustomer = function(customerName, destinationParty = null) {
    if (!customerName) return null;
    db.rateAgreements = db.rateAgreements || [];
    const normCust = customerName.toLowerCase().trim();
    const normDest = destinationParty ? destinationParty.toLowerCase().trim() : '';

    // First try exact match on customer + destination party
    if (normDest) {
        const partyMatch = db.rateAgreements.find(r => 
            r.status === 'Active' && 
            r.customerName && 
            (r.customerName.toLowerCase().trim() === normCust || normCust.includes(r.customerName.toLowerCase().trim())) &&
            r.destinationParty &&
            (r.destinationParty.toLowerCase().trim() === normDest || normDest.includes(r.destinationParty.toLowerCase().trim()))
        );
        if (partyMatch) return partyMatch;
    }

    // Fallback to customer general agreement
    const genMatch = db.rateAgreements.find(r => 
        r.status === 'Active' && 
        r.customerName && 
        (r.customerName.toLowerCase().trim() === normCust || normCust.includes(r.customerName.toLowerCase().trim())) &&
        (!r.destinationParty || !r.destinationParty.trim())
    );

    return genMatch || null;
};




