let currentTermsVoucherType = 'outward';

window.openAISafeguardsModal = function() {
    openModal('ai-safeguards-modal');
};

window.openTermsConditionsModal = function() {
    currentTermsVoucherType = 'outward';
    window.selectTermsVoucherType('outward');
    openModal('terms-conditions-modal');
};

window.selectTermsVoucherType = function(type) {
    currentTermsVoucherType = type;
    document.querySelectorAll('.terms-voucher-btn').forEach(btn => {
        btn.classList.remove('btn-primary');
        btn.classList.add('btn-secondary');
    });
    const activeBtn = document.getElementById('tc-btn-' + type);
    if (activeBtn) {
        activeBtn.classList.remove('btn-secondary');
        activeBtn.classList.add('btn-primary');
    }

    const companyId = currentCompany ? currentCompany.id : 'co3';
    db.voucherTerms = db.voucherTerms || {};
    let termsObj = db.voucherTerms[companyId];
    if (!termsObj) {
        try {
            termsObj = JSON.parse(localStorage.getItem('voucher_terms_' + companyId) || '{}');
            db.voucherTerms[companyId] = termsObj;
        } catch(e) {
            termsObj = {};
        }
    }

    const defaultOutwardText = "1. Fabric issued for Job Work purposes only, not for sale.\n2. The job worker is responsible for any damage or loss of fabric during processing.\n3. Processed fabric must be returned within the agreed timeframe.";
    const val = (termsObj && termsObj[type] !== undefined) ? termsObj[type] : (type === 'outward' ? defaultOutwardText : "");
    const textarea = document.getElementById('tc-textarea');
    if (textarea) textarea.value = val;

    window.updateTermsStatusBadge(val);
};

window.updateTermsStatusBadge = function(val) {
    const badge = document.getElementById('tc-status-badge');
    if (!badge) return;
    if (val && val.trim()) {
        badge.style.background = '#ecfdf5';
        badge.style.color = '#059669';
        badge.style.border = '1px solid #a7f3d0';
        badge.textContent = ' Configured (Will Print)';
    } else {
        badge.style.background = '#fff7ed';
        badge.style.color = '#c2410c';
        badge.style.border = '1px solid #ffedd5';
        badge.textContent = '� Empty (Will NOT Print)';
    }
};

window.clearCurrentVoucherTerms = function() {
    const textarea = document.getElementById('tc-textarea');
    if (textarea) textarea.value = '';
    window.updateTermsStatusBadge('');
    if (typeof showToast === 'function') showToast('Terms cleared for current voucher. Click Save to confirm.', 'info');
};

window.saveVoucherTerms = async function() {
    const val = document.getElementById('tc-textarea').value.trim();
    const companyId = currentCompany ? currentCompany.id : 'co3';
    db.voucherTerms = db.voucherTerms || {};
    db.voucherTerms[companyId] = db.voucherTerms[companyId] || {};
    db.voucherTerms[companyId][currentTermsVoucherType] = val;

    try {
        localStorage.setItem('voucher_terms_' + companyId, JSON.stringify(db.voucherTerms[companyId]));
    } catch(e) {}

    if (window.supabase) {
        try {
            await window.supabase.from('voucher_terms').upsert({
                id: companyId + '_' + currentTermsVoucherType,
                company_id: companyId,
                voucher_type: currentTermsVoucherType,
                terms_content: val
            });
        } catch(e) {}
    }

    if (typeof showToast === 'function') showToast('Terms & Conditions saved successfully!', 'success');
    closeModal('terms-conditions-modal');
};

window.getVoucherTermsHTML = function(voucherType) {
    if (!voucherType) return '';
    const companyId = currentCompany ? currentCompany.id : 'co3';
    db.voucherTerms = db.voucherTerms || {};
    let termsObj = db.voucherTerms[companyId];
    if (!termsObj) {
        try {
            termsObj = JSON.parse(localStorage.getItem('voucher_terms_' + companyId) || '{}');
            db.voucherTerms[companyId] = termsObj;
        } catch(e) {
            termsObj = {};
        }
    }

    const defaultOutwardText = "1. Fabric issued for Job Work purposes only, not for sale.\n2. The job worker is responsible for any damage or loss of fabric during processing.\n3. Processed fabric must be returned within the agreed timeframe.";
    let text = (termsObj && termsObj[voucherType] !== undefined) ? termsObj[voucherType] : (voucherType === 'outward' ? defaultOutwardText : "");

    text = (text || '').trim();
    if (!text) {
        // "in the case in which it is not entered than dont print any thing"
        return '';
    }

    const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
    if (!lines.length) return '';

    const itemsHtml = lines.map(line => {
        const cleaned = line.replace(/^\d+[\.\)]\s*/, '');
        return `<li>${cleaned}</li>`;
    }).join('');

    return `
        <div style="margin-top:12px; font-size: 12px;">
            <strong>Terms &amp; Conditions:</strong>
            <ol style="margin-left: 20px; margin-top: 4px; line-height: 1.4;">
                ${itemsHtml}
            </ol>
        </div>
    `;
};


