// ===== FORMAT & DEDUPLICATE REPEATED ITEM NAMES =====
window.formatUniqueItemNames = function(val) {
    if (!val) return '-';
    if (Array.isArray(val)) {
        const clean = val.map(x => String(x || '').trim()).filter(Boolean);
        const unique = [...new Set(clean)];
        return unique.join(', ') || '-';
    }
    const str = String(val).trim();
    if (!str) return '-';
    if (str.includes(',')) {
        const parts = str.split(',').map(s => s.trim()).filter(Boolean);
        const unique = [...new Set(parts)];
        return unique.join(', ');
    }
    return str;
};


window.refreshUserModalDepartmentLists = function(selectedDeptCode = null) {
    const userDeptSelect = document.getElementById('user-department');
    if (userDeptSelect) {
        const currentVal = userDeptSelect.value;
        userDeptSelect.innerHTML = '<option value="">-- None / No Department --</option>';
        (masterDB.departments || []).forEach(d => {
            const opt = document.createElement('option');
            opt.value = d.code;
            opt.textContent = `${d.name} (${d.code})`;
            userDeptSelect.appendChild(opt);
        });
        if (selectedDeptCode) {
            userDeptSelect.value = selectedDeptCode;
        } else {
            userDeptSelect.value = currentVal;
        }
    }

    const allowedDeptContainer = document.getElementById('user-allowed-departments-list');
    if (allowedDeptContainer) {
        const currentlyChecked = Array.from(allowedDeptContainer.querySelectorAll('.user-allowed-dept-checkbox:checked')).map(c => c.value);
        allowedDeptContainer.innerHTML = '';
        (masterDB.departments || []).forEach(d => {
            const label = document.createElement('label');
            label.style.display = 'flex';
            label.style.alignItems = 'center';
            label.style.gap = '8px';
            label.style.fontSize = '13.5px';
            label.style.color = 'var(--text-primary)';
            label.style.cursor = 'pointer';
            label.style.fontWeight = '500';
            
            const chk = document.createElement('input');
            chk.type = 'checkbox';
            chk.value = d.code;
            chk.className = 'user-allowed-dept-checkbox';
            chk.style.width = '16px';
            chk.style.height = '16px';
            chk.style.cursor = 'pointer';
            if (currentlyChecked.includes(d.code)) {
                chk.checked = true;
            }
            
            label.appendChild(chk);
            label.appendChild(document.createTextNode(` ${d.name} (${d.code})`));
            allowedDeptContainer.appendChild(label);
        });
    }
};

window.addPORow = function(itemId = '', bomId = '', qty = '', rate = '', customName = '') {
    if (itemId && typeof itemId === 'object') {
        const obj = itemId;
        itemId = obj.itemId || obj.item_id || obj.id || '';
        bomId = obj.bomId || obj.bom_id || '';
        qty = obj.qty || obj.quantity || '';
        rate = obj.rate || obj.price || '';
        customName = obj.itemName || obj.customName || obj.processName || '';
    }
    const tbody = document.getElementById('po-items-grid-body');
    if (!tbody) return;
    const index = tbody.rows.length;
    const tr = document.createElement('tr');
    tr.setAttribute('data-bom-id', bomId || '');
    
    console.log("[addPORow DEBUG] called with itemId:", itemId, "qty:", qty, "rate:", rate, "customName:", customName);
    console.log("[addPORow DEBUG] db.items count:", (db.items || []).length);
    const inDb = (db.items || []).some(i => i.id === itemId);
    console.log("[addPORow DEBUG] itemId exists in db.items:", inDb);
    
    const type = document.getElementById('po-type').value || 'vendor';
    console.log("[addPORow DEBUG] po-type value in DOM:", type);
    
    let itemsToUse = (db.items || []).filter(i => i.status === 'Active' || i.id === itemId);
    console.log("[addPORow DEBUG] Active items count:", itemsToUse.length);
    if (itemsToUse.length > 0) {
        console.log("[addPORow DEBUG] First 5 active items sample:", itemsToUse.slice(0, 5).map(i => ({ name: i.name, category: i.category, status: i.status })));
    }
    
    if (type === 'consumable') {
        itemsToUse = itemsToUse.filter(i => {
            if (i.id === itemId) return true;
            const cat = (i.category || '').toLowerCase().trim();
            const consumableList = ['thread', 'accessories', 'packing material', 'raw material', 'consumable', 'consumables', 'needle', 'yarn', 'non wooven', 'nonwoven'];
            
            // Check direct category match
            if (consumableList.includes(cat)) return true;
            
            // Check parent/primary category match
            const itemGroup = (db.itemGroups || []).find(g => g.name.toLowerCase().trim() === cat);
            if (itemGroup && !itemGroup.isPrimary && itemGroup.underGroupId) {
                const parentGroup = (db.itemGroups || []).find(x => x.id === itemGroup.underGroupId);
                if (parentGroup) {
                    const parentCat = parentGroup.name.toLowerCase().trim();
                    if (consumableList.includes(parentCat)) return true;
                }
            }
            return false;
        });
        console.log("[addPORow DEBUG] filtered consumable count:", itemsToUse.length);
    } else if (type === 'other') {
        itemsToUse = itemsToUse.filter(i => {
            if (i.id === itemId) return true;
            const cat = (i.category || '').toLowerCase().trim();
            return cat === 'other' || cat === 'other item' || cat === 'other items' || cat === 'general' || cat === 'others';
        });
        console.log("[addPORow DEBUG] filtered other count:", itemsToUse.length);
    }
    
    console.log("[addPORow DEBUG] final itemsToUse count:", itemsToUse.length);
    let itemOptions = itemsToUse.map(i => `<option value="${i.id}" ${i.id === itemId ? 'selected' : ''}>${i.name}</option>`).join('');
    
    if (itemId && !inDb) {
        const displayName = customName || itemId;
        console.log("[addPORow DEBUG] Prepended custom option:", { itemId, displayName });
        itemOptions = `<option value="${itemId}" selected>${displayName}</option>` + itemOptions;
    }
    
    const isEditMode = !!(document.getElementById('po-edit-id') && document.getElementById('po-edit-id').value);
    const hasExistingPrice = isEditMode && (rate !== '' && parseFloat(rate) > 0);
    const isReadonly = !window.allowPriceChange() && hasExistingPrice;
    const readonlyAttr = isReadonly ? 'readonly style="background:#f1f5f9; cursor:not-allowed;"' : '';
    const rateTd = type !== 'inhouse' ? `<td><input type="number" class="form-input po-rate-in" value="${rate}" placeholder="0.00" step="any" ${readonlyAttr} oninput="window.recalculatePOTotal()"></td>` : '';
    
    tr.innerHTML = `
        <td>${index + 1}</td>
        <td><select class="form-input po-item-select" onchange="window.updatePOItemRowData(this); window.recalculatePOTotal();">
            <option value="">-- Item Name --</option>
            ${itemOptions}
        </select></td>
        <td><input type="number" class="form-input po-qty-in" value="${qty}" placeholder="0" step="any" oninput="window.recalculatePOTotal()"></td>
        <td><span class="unit-lbl">-</span></td>
        ${rateTd}
        <td><button class="btn btn-sm btn-danger" onclick="this.closest('tr').remove(); window.recalculatePORowSNo(); window.recalculatePOTotal();">=�</button></td>
    `;
    tbody.appendChild(tr);
    
    const selectEl = tr.querySelector('.po-item-select');
    if (selectEl) {
        makeSelectElementSearchable(selectEl);
        if (itemId) {
            window.updatePOItemRowData(selectEl, bomId);
        }
    }
    if (typeof window.filterPOHeaderBOMSelect === 'function') {
        window.filterPOHeaderBOMSelect();
    }
    console.log("[addPORow DEBUG] finished. tbody rows count:", tbody.rows.length);
};

window.recalculatePORowSNo = function() {
    Array.from(document.getElementById('po-items-grid-body').rows).forEach((row, i) => {
        row.cells[0].textContent = i + 1;
    });
};

window.recalculatePOTotal = function() {
    const tbody = document.getElementById('po-items-grid-body');
    if (!tbody) return;
    
    let grandTotal = 0;
    let itemsTaxDetails = [];

    const typeVal = document.getElementById('po-type').value;
    const purchaseTypeSelect = document.getElementById('po-purchase-type');
    const selectedPurchaseTypeName = purchaseTypeSelect ? purchaseTypeSelect.value : '';
    const purchaseTypeObj = (db.purchase_types || []).find(x => x.name === selectedPurchaseTypeName);
    const gstType = purchaseTypeObj ? (purchaseTypeObj.gst_type || 'CGST + SGST') : 'CGST + SGST';

    if (typeVal === 'finishing_jw') {
        const jobworkTypeName = document.getElementById('po-fjw-jobwork-type')?.value || '';
        const matchedItem = (db.items || []).find(i => i.name.toLowerCase() === jobworkTypeName.toLowerCase()) || 
                            (db.items || []).find(i => i.status === 'Active') || null;
        
        let totalCheckedQty = 0;
        let totalCheckedAmount = 0;
        
        const slipCards = document.querySelectorAll('#po-fjw-prod-slips-container .fjw-slip-card');
        slipCards.forEach(card => {
            const chk = card.querySelector('.fjw-slip-checkbox');
            if (chk && chk.checked) {
                const qtyIn = card.querySelector('.fjw-slip-qty-in');
                const rateIn = card.querySelector('.fjw-slip-rate-in');
                
                const qty = qtyIn ? parseFloat(qtyIn.value) || 0 : 0;
                const rate = rateIn ? parseFloat(rateIn.value) || 0 : 0;
                const amount = qty * rate;
                grandTotal += amount;
                totalCheckedQty += qty;
                totalCheckedAmount += amount;
                
                if (matchedItem) {
                    let taxRate = 5;
                    if (matchedItem.hsn) {
                        const hsnObj = (db.hsnCodes || []).find(h => h.code === matchedItem.hsn);
                        if (hsnObj) {
                            if (gstType === 'IGST') {
                                taxRate = parseFloat(hsnObj.igst) || (parseFloat(hsnObj.cgst) + parseFloat(hsnObj.sgst)) || 5;
                            } else {
                                taxRate = (parseFloat(hsnObj.cgst) + parseFloat(hsnObj.sgst)) || parseFloat(hsnObj.igst) || 5;
                            }
                        }
                    }
                    itemsTaxDetails.push({ amount, taxRate });
                }
            }
        });
        
        const summaryQty = document.getElementById('po-fjw-summary-qty');
        if (summaryQty) summaryQty.textContent = totalCheckedQty.toFixed(2);
        
        const summaryAmt = document.getElementById('po-fjw-summary-amount');
        if (summaryAmt) summaryAmt.textContent = '�' + totalCheckedAmount.toLocaleString('en-IN', { minimumFractionDigits: 2 });
    } else if (typeVal !== 'inhouse') {
        const rows = tbody.rows;
        for (let i = 0; i < rows.length; i++) {
            const row = rows[i];
            const select = row.querySelector('.po-item-select');
            const qtyIn = row.querySelector('.po-qty-in');
            const rateIn = row.querySelector('.po-rate-in');
            
            const qty = qtyIn ? parseFloat(qtyIn.value) || 0 : 0;
            const rate = rateIn ? (parseFloat(rateIn.dataset.origVal || rateIn.value) || 0) : 0;
            const amount = qty * rate;
            grandTotal += amount;

            if (select && select.value) {
                const itemId = select.value;
                const item = (db.items || []).find(x => x.id === itemId);
                let taxRate = 5; // Default HSN tax rate 5%
                if (item && item.hsn) {
                    const hsnObj = (db.hsnCodes || []).find(h => h.code === item.hsn);
                    if (hsnObj) {
                        if (gstType === 'IGST') {
                            taxRate = parseFloat(hsnObj.igst) || (parseFloat(hsnObj.cgst) + parseFloat(hsnObj.sgst)) || 5;
                        } else {
                            taxRate = (parseFloat(hsnObj.cgst) + parseFloat(hsnObj.sgst)) || parseFloat(hsnObj.igst) || 5;
                        }
                    }
                }
                itemsTaxDetails.push({ amount, taxRate });
            }
        }
    }

    const totalDisplay = document.getElementById('po-total-display');
    const totalContainer = document.getElementById('po-total-container');
    if (totalDisplay) {
        totalDisplay.textContent = grandTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 });
    }
    if (totalContainer) {
        totalContainer.style.display = (typeVal !== 'inhouse' && grandTotal > 0) ? 'block' : 'none';
    }

    const gstContainer = document.getElementById('po-gst-details-container');
    if (gstContainer) {
        if (typeVal !== 'inhouse' && grandTotal > 0 && selectedPurchaseTypeName) {
            gstContainer.style.display = 'block';
            document.getElementById('po-taxable-display').textContent = grandTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 });

            let gstSummary = {};
            itemsTaxDetails.forEach(detail => {
                const rate = detail.taxRate;
                if (!gstSummary[rate]) gstSummary[rate] = 0;
                gstSummary[rate] += detail.amount;
            });

            let gstHtml = '';
            let totalTaxAmount = 0;
            
            Object.keys(gstSummary).forEach(rate => {
                const basicAmt = gstSummary[rate];
                const r = parseFloat(rate);
                if (gstType === 'IGST') {
                    const igstAmt = (basicAmt * r) / 100;
                    totalTaxAmount += igstAmt;
                    gstHtml += `
                        <div style="display: flex; justify-content: space-between; margin-bottom: 4px; color: var(--text-secondary);">
                            <span>IGST (${r}%):</span>
                            <span>�${igstAmt.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
                        </div>
                    `;
                } else {
                    const cgstSgstRate = r / 2;
                    const cgstAmt = (basicAmt * cgstSgstRate) / 100;
                    const sgstAmt = (basicAmt * cgstSgstRate) / 100;
                    totalTaxAmount += (cgstAmt + sgstAmt);
                    gstHtml += `
                        <div style="display: flex; justify-content: space-between; margin-bottom: 4px; color: var(--text-secondary);">
                            <span>CGST (${cgstSgstRate}%):</span>
                            <span>�${cgstAmt.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
                        </div>
                        <div style="display: flex; justify-content: space-between; margin-bottom: 4px; color: var(--text-secondary);">
                            <span>SGST (${cgstSgstRate}%):</span>
                            <span>�${sgstAmt.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</span>
                        </div>
                    `;
                }
            });

            document.getElementById('po-gst-rows').innerHTML = gstHtml;
            const rawGrandTotal = grandTotal + totalTaxAmount;
            const roundOffInput = document.getElementById('po-round-off');
            let roundOffVal = 0;
            if (roundOffInput) {
                if (roundOffInput.dataset.manual === 'true') {
                    roundOffVal = parseFloat(roundOffInput.value) || 0;
                } else {
                    roundOffVal = Math.round(rawGrandTotal) - rawGrandTotal;
                    roundOffInput.value = roundOffVal.toFixed(2);
                }
            }
            const finalGrandTotal = rawGrandTotal + roundOffVal;
            document.getElementById('po-grand-total-display').textContent = finalGrandTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 });
        } else {
            gstContainer.style.display = 'none';
        }
    }
};

window.onPORoundOffInput = function() {
    const input = document.getElementById('po-round-off');
    if (input) {
        input.dataset.manual = 'true';
    }
    window.recalculatePOTotal();
};

window.updatePOItemRowData = function(selectEl, selectBomId = '') {
    const row = selectEl.closest('tr');
    const itemId = selectEl.value;
    const item = db.items.find(i => i.id === itemId);
    
    // Update Unit Label
    const unitLabel = row.querySelector('.unit-lbl');
    if (unitLabel) unitLabel.textContent = item ? window.getItemUnitSymbol(item) : '-';
};

window.filterPOHeaderBOMSelect = function() {
    const bomSel = document.getElementById('po-bom');
    if (!bomSel) return;
    
    const rows = document.getElementById('po-items-grid-body')?.rows || [];
    const selectedItemIds = [];
    for (let i = 0; i < rows.length; i++) {
        const select = rows[i].querySelector('.po-item-select');
        if (select && select.value) {
            selectedItemIds.push(select.value);
        }
    }
    
    const currentVal = bomSel.value;
    bomSel.innerHTML = '<option value="">-- Select BOM --</option>';
    
    (db.boms || []).forEach(b => {
        if (selectedItemIds.length > 0 && !selectedItemIds.includes(b.finishedItemId)) {
            return;
        }
        const finished = db.items.find(i => i.id === b.finishedItemId);
        const label = finished ? `${b.code} (${finished.name})` : b.code;
        const opt = new Option(label, b.id);
        if (b.id === currentVal) opt.selected = true;
        bomSel.appendChild(opt);
    });
    
    reinitSearchableSelect(bomSel);
};

window.onPoBomChange = function() {
    const bomId = document.getElementById('po-bom').value;
    if (!bomId) return; // Do not clear grid if no BOM is selected
    const bom = (db.boms || []).find(x => x.id === bomId);
    const tbody = document.getElementById('po-items-grid-body');
    if (tbody) tbody.innerHTML = '';
    if (bom) {
        window.addPORow(bom.finishedItemId, bom.id, bom.batchQty || 1);
    }
};

window.promptTdsPolicySelection = function(totalAmount, currentPolicyId = '') {
    return new Promise((resolve) => {
        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';
        overlay.style.zIndex = '10005';
        overlay.style.display = 'flex';
        overlay.style.alignItems = 'center';
        overlay.style.justifyContent = 'center';
        overlay.style.background = 'rgba(15, 23, 42, 0.6)';
        overlay.style.backdropFilter = 'blur(4px)';

        const policies = window.customMasters.tdspolicies || [];
        const policyOptions = policies.map(p => `<option value="${p.id}" ${p.id === currentPolicyId ? 'selected' : ''}>${p.name} (${p.rate}%)</option>`).join('');

        overlay.innerHTML = `
            <div class="modal" style="width: 450px; background: var(--bg-card, #ffffff); border-radius: 12px; box-shadow: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04); overflow: hidden; border: 1px solid var(--border, #e2e8f0);">
                <div class="modal-header" style="background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%); color: white; padding: 16px 20px; display: flex; justify-content: space-between; align-items: center;">
                    <h3 style="margin: 0; font-size: 16px; font-weight: 600;">TDS Applicability Check</h3>
                </div>
                <div class="modal-body" style="padding: 20px;">
                    <p style="margin-top: 0; margin-bottom: 15px; font-size: 13.5px; color: var(--text-secondary); line-height: 1.5;">
                        This is a <strong>Job Work</strong> Purchase Order. Select the appropriate TDS Policy:
                    </p>
                    <div class="form-group" style="margin-bottom: 15px;">
                        <label style="font-weight: 600; font-size: 12.5px; margin-bottom: 6px; display: block;">TDS Policy</label>
                        <select id="po-tds-select-prompt" class="form-input" style="width: 100%;">
                            <option value="">-- No TDS --</option>
                            ${policyOptions}
                        </select>
                    </div>
                    <div id="po-tds-warn-alert" style="display: none; background: #fffbeb; border: 1px solid #fef3c7; color: #b45309; padding: 10px; border-radius: 6px; font-size: 12px; line-height: 1.4; margin-top: 10px;">
                        � <strong>Statutory Alert (Sec 194C):</strong> This Job Work transaction amount (�${totalAmount.toLocaleString('en-IN')}) exceeds the statutory single-invoice limit of �30,000. TDS deduction is generally mandatory.
                    </div>
                </div>
                <div class="modal-footer" style="padding: 12px 20px; background: var(--bg-secondary, #f8fafc); border-top: 1px solid var(--border, #e2e8f0); display: flex; justify-content: flex-end; gap: 8px;">
                    <button id="po-tds-btn-cancel" class="btn btn-ghost">Cancel PO Save</button>
                    <button id="po-tds-btn-confirm" class="btn btn-primary">Confirm & Save</button>
                </div>
            </div>
        `;

        document.body.appendChild(overlay);

        const selectEl = overlay.querySelector('#po-tds-select-prompt');
        const warnEl = overlay.querySelector('#po-tds-warn-alert');
        const cancelBtn = overlay.querySelector('#po-tds-btn-cancel');
        const confirmBtn = overlay.querySelector('#po-tds-btn-confirm');

        if (totalAmount > 30000 && selectEl.value === '') {
            warnEl.style.display = 'block';
        }

        selectEl.onchange = function() {
            if (totalAmount > 30000 && selectEl.value === '') {
                warnEl.style.display = 'block';
            } else {
                warnEl.style.display = 'none';
            }
        };

        cancelBtn.onclick = function() {
            document.body.removeChild(overlay);
            resolve({ cancelled: true });
        };

        confirmBtn.onclick = async function() {
            const selectedVal = selectEl.value;
            if (totalAmount > 30000 && !selectedVal) {
                const proceed = await window.showSmartConfirm(
                    'Proceed without TDS?',
                    `Warning: Amount �${totalAmount.toLocaleString('en-IN')} exceeds the Section 194C threshold of �30,000. Are you absolutely sure you want to save this Job Work order without TDS?`
                );
                if (!proceed) return;
            }
            document.body.removeChild(overlay);
            resolve({ cancelled: false, tdsPolicyId: selectedVal });
        };
    });
};



window.openOutwardModalFromPO = function(po) {
    if (typeof window.openOutwardModal === 'function') {
        // Set wizard state based on PO type before opening the modal
        const isPOInhouse = po.poType === 'inhouse' || po.po_type === 'inhouse' || (po.number && String(po.number).toUpperCase().startsWith('PO/INH'));
        const isFinishingJw = po.poType === 'finishing_jw' || po.po_type === 'finishing_jw' || (po.number && String(po.number).toUpperCase().startsWith('PO/FJW'));
        
        if (isPOInhouse) {
            outwardWizardState.type = 'inhouse';
            outwardWizardState.source = null;
            outwardWizardState.subType = null;
        } else if (isFinishingJw) {
            outwardWizardState.type = 'jobworker';
            outwardWizardState.source = null;
            outwardWizardState.subType = null;
        } else {
            outwardWizardState.type = 'fabric_issue_challan';
            outwardWizardState.source = 'vendor';
            const isEmb = po.purchaseType && po.purchaseType.toLowerCase().includes('embro');
            outwardWizardState.subType = isEmb ? 'embroidered' : 'plain';
        }

        window.openOutwardModal();

        // Populate fields based on PO type
        if (isPOInhouse) {
            const customerEl = document.getElementById('outward-customer');
            if (customerEl) {
                customerEl.value = po.customerId || '';
                reinitSearchableSelect(customerEl);
                if (typeof window.onOutwardCustomerChange === 'function') {
                    window.onOutwardCustomerChange();
                }
            }
        } else if (isFinishingJw) {
            const vendorEl = document.getElementById('outward-vendor');
            if (vendorEl) {
                vendorEl.value = po.vendorId || po.vendor_id || '';
                reinitSearchableSelect(vendorEl);
            }
            const customerEl = document.getElementById('outward-customer');
            if (customerEl) {
                customerEl.value = po.customerId || '';
                reinitSearchableSelect(customerEl);
                if (typeof window.onOutwardCustomerChange === 'function') {
                    window.onOutwardCustomerChange();
                }
            }
        } else {
            const vendorEl = document.getElementById('outward-vendor');
            if (vendorEl) {
                vendorEl.value = po.vendorId || po.vendor_id || '';
                reinitSearchableSelect(vendorEl);
            }
        }

        if (typeof window.filterOutwardPOs === 'function') {
            window.filterOutwardPOs();
        }
        const poRefEl = document.getElementById('outward-po-ref');
        if (poRefEl) {
            poRefEl.value = po.id;
            reinitSearchableSelect(poRefEl);
        }
        if (typeof window.onOutwardPOChange === 'function') {
            window.onOutwardPOChange();
        }
    }
};

function parseFabricUsedState(remarks) {
    if (!remarks) return [];
    const match = remarks.match(/\[FABRIC_USED:(\[.*?\])\]/) || remarks.match(/\[FABRIC_USED:(\{.*?\})\]/);
    if (match && match[1]) {
        try {
            const parsed = JSON.parse(match[1]);
            return Array.isArray(parsed) ? parsed : [parsed];
        } catch (e) {
            console.error("Error parsing FABRIC_USED metadata:", e);
        }
    }
    return [];
}
window.parseFabricUsedState = parseFabricUsedState;

window.updatePODeliveryDate = function() {
    const poDateInput = document.getElementById('po-date');
    const poDaysInput = document.getElementById('po-delivery-days');
    const poReturnInput = document.getElementById('po-return-date');
    if (!poDateInput || !poDaysInput || !poReturnInput) return;
    
    const dateVal = poDateInput.value;
    const daysVal = parseInt(poDaysInput.value, 10);
    if (!dateVal || isNaN(daysVal)) {
        poReturnInput.value = '';
        return;
    }
    
};
window.updatePODeliveryDate = window.updatePODeliveryDate; // expose globally

