function buildJvXml(jvNo, date, debitLedger, creditLedger, amount, narration) {
    const formattedDate = formatDateToBusy(date);
    return `<Journal>
        <VchSeriesName>Main</VchSeriesName>
        <Date>${formattedDate}</Date>
        <VchType>7</VchType>
        <VchNo>${escapeXml(jvNo)}</VchNo>
        <Narr1>${escapeXml(narration || '')}</Narr1>
        <AccEntries>
            <AccDetail>
                <AccName>${escapeXml(debitLedger)}</AccName>
                <Amount>${parseFloat(amount).toFixed(2)}</Amount>
                <DrCr>1</DrCr>
            </AccDetail>
            <AccDetail>
                <AccName>${escapeXml(creditLedger)}</AccName>
                <Amount>${parseFloat(amount).toFixed(2)}</Amount>
                <DrCr>2</DrCr>
            </AccDetail>
        </AccEntries>
    </Journal>`.replace(/\s+/g, ' ').trim();
}

window.renderFreightJvs = async function() {
    const tbody = document.getElementById('freight-jvs-tbody');
    if (!tbody) return;
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center; padding:20px; color:var(--text-muted);">Loading JVs...</td></tr>';
    
    try {
        const { data, error } = await window.supabase
            .from('generic_transactions')
            .select('*')
            .eq('type', 'freight_jv')
            .order('date', { ascending: false });
            
        if (error) throw error;
        
        if (db) {
            db.genericTransactions = db.genericTransactions || [];
            db.genericTransactions = db.genericTransactions.filter(x => x.type !== 'freight_jv');
            db.genericTransactions.push(...(data || []));
        }
        
        const list = data || [];
        if (list.length === 0) {
            tbody.innerHTML = '<tr><td colspan="8" style="text-align:center; padding:20px; color:var(--text-muted);">No JVs found.</td></tr>';
            return;
        }
        
        const { data: queueData } = await window.supabase
            .from('busy_sync_queue')
            .select('voucher_no, status, error_message')
            .eq('voucher_type', '7');
            
        const queueMap = new Map();
        if (queueData) {
            queueData.forEach(q => queueMap.set(q.voucher_no, q));
        }
        
        tbody.innerHTML = list.map(jv => {
            const syncInfo = queueMap.get(jv.number);
            let syncStatusHtml = `<span class="badge" style="background:#f3f4f6; color:#4b5563; border:1px solid #e5e7eb;">Not Synced</span>`;
            let actionsHtml = `
                <button class="btn btn-sm" style="background:#4f46e5; color:#fff;" onclick="window.previewFreightJv('${jv.id}')">= Sync to Busy</button>
                <button class="btn btn-sm btn-danger" onclick="window.deleteFreightJv('${jv.id}')">=� Delete</button>
            `;
            
            if (syncInfo) {
                if (syncInfo.status === 'success') {
                    syncStatusHtml = `<span class="badge" style="background:#ecfdf5; color:#059669; border:1px solid #a7f3d0;"> Synced</span>`;
                    actionsHtml = `
                        <button class="btn btn-sm btn-secondary" onclick="window.printFreightJv('${jv.id}')">=� Print</button>
                        <button class="btn btn-sm btn-danger" onclick="window.deleteFreightJv('${jv.id}')">=� Delete</button>
                    `;
                } else if (syncInfo.status === 'failed') {
                    syncStatusHtml = `<span class="badge" style="background:#fef2f2; color:#dc2626; border:1px solid #fca5a5;" title="${escapeXml(syncInfo.error_message || '')}"> Failed</span>`;
                    actionsHtml = `
                        <button class="btn btn-sm" style="background:#6366f1; color:#fff;" onclick="window.previewFreightJv('${jv.id}')">= Retry</button>
                        <button class="btn btn-sm btn-danger" onclick="window.deleteFreightJv('${jv.id}')">=� Delete</button>
                    `;
                } else if (syncInfo.status === 'pending') {
                    syncStatusHtml = `<span class="badge" style="background:#fef3c7; color:#d97706; border:1px solid #fcd34d;">� Pending</span>`;
                    actionsHtml = `
                        <button class="btn btn-sm btn-ghost" disabled>� Syncing...</button>
                        <button class="btn btn-sm btn-danger" onclick="window.deleteFreightJv('${jv.id}')">=� Delete</button>
                    `;
                }
            }
            
            const linkedCount = (jv.reconciledShipments || []).length;
            
            return `
                <tr>
                    <td><strong>${jv.number}</strong></td>
                    <td>${formatDate(jv.date)}</td>
                    <td>${jv.partyName || '-'}</td>
                    <td style="font-size:11px;">
                        <div><strong style="color:var(--accent-red);">Dr:</strong> ${jv.debitLedger || ''}</div>
                        <div><strong style="color:var(--accent-green);">Cr:</strong> ${jv.creditLedger || ''}</div>
                    </td>
                    <td style="text-align:right; font-weight:600; color:var(--text-primary);">�${parseFloat(jv.totalAmount || 0).toFixed(2)}</td>
                    <td>${linkedCount} shipments</td>
                    <td style="text-align:center;">${syncStatusHtml}</td>
                    <td style="text-align:center; display:flex; gap:6px; justify-content:center;">${actionsHtml}</td>
                </tr>
            `;
        }).join('');
        
    } catch (e) {
        console.error("Error rendering Freight JVs:", e);
        tbody.innerHTML = `<tr><td colspan="8" style="text-align:center; padding:20px; color:var(--accent-red);">Failed to load JVs: ${e.message}</td></tr>`;
    }
};

window.openFreightJvModal = function() {
    const carrierVal = document.getElementById('reconcile-freight-carrier')?.value || '';
    if (!carrierVal) {
        showToast('Please select a carrier first', 'error');
        return;
    }
    
    const selectedChks = document.querySelectorAll('.shipment-reconcile-chk:checked');
    if (selectedChks.length === 0) {
        showToast('Please select at least one shipment to generate JV', 'error');
        return;
    }
    
    const parts = carrierVal.split(':');
    const carrierType = parts[0];
    const carrierId = parts[1] || '';
    const carrierNameFromVal = parts.slice(2).join(':') || '';
    
    let carrierName = '';
    if (carrierType === 'transporter') {
        const t = (db.transporters || []).find(x => String(x.id) === String(carrierId));
        carrierName = t ? t.name : (carrierNameFromVal || carrierId);
    } else {
        carrierName = carrierId;
    }
    
    const shipments = [];
    let totalAmt = 0;
    
    const { grns, outwards, getRecordPkgCount } = window.getAllLogisticsRecords();
    
    selectedChks.forEach(chk => {
        const shipId = chk.value;
        const dbTable = chk.dataset.table;
        
        let record = null;
        let type = '';
        let number = '';
        let party = '';
        let freight = 0;
        let labour = 0;
        let fMode = 'flat';
        let fRate = 0;
        
        if (dbTable === 'grns') {
            const gList = [
                ...(db.grn_cust_plain || []),
                ...(db.grn_vend_emb || []),
                ...(db.grn_consumable || []),
                ...(db.grns || []),
                ...(rawDB.grns || [])
            ];
            record = gList.find(x => x.id === shipId);
            if (record) {
                type = 'GRN';
                number = record.grnNo || record.number;
                party = record.customerName || record.partyName || record.vendorName || '-';
                
                let tState = {};
                if (record.remarks && record.remarks.includes('[TRANSPORT:')) {
                    const match = record.remarks.match(/\[TRANSPORT:(\{.*?\})\]/);
                    if (match) {
                        try { tState = JSON.parse(match[1]); } catch(e) {}
                    }
                }
                fMode = tState.freightMode || 'flat';
                fRate = parseFloat(tState.freightRate || 0);
                freight = parseFloat(tState.freightAmount !== undefined ? tState.freightAmount : (record.freightAmount || record.freight_amount || 0));
                labour = parseFloat(tState.labour !== undefined ? tState.labour : (record.transportLabour || record.labour || 0));
            }
        } else if (dbTable === 'outwards') {
            const oList = [
                ...(db.outward || []),
                ...(db.outwards || []),
                ...(rawDB.outwards || [])
            ];
            record = oList.find(x => x.id === shipId);
            if (record) {
                type = 'Outward';
                number = record.number;
                party = record.customerName || record.vendorName || record.partyName || '-';
                
                let tState = {};
                if (record.remarks && record.remarks.includes('[TRANSPORT:')) {
                    const match = record.remarks.match(/\[TRANSPORT:(\{.*?\})\]/);
                    if (match) {
                        try { tState = JSON.parse(match[1]); } catch(e) {}
                    }
                }
                fMode = tState.freightMode || 'flat';
                fRate = parseFloat(tState.freightRate || 0);
                freight = parseFloat(tState.freightAmount !== undefined ? tState.freightAmount : (record.freightAmount || record.freight_amount || 0));
                labour = parseFloat(tState.labour !== undefined ? tState.labour : (record.transportLabour || record.labour || 0));
            }
        }
        
        if (record) {
            shipments.push({
                id: shipId,
                dbTable,
                type,
                number,
                party,
                pkgCount: getRecordPkgCount(record),
                freightMode: fMode,
                freightRate: fRate,
                freight,
                labour,
                amount: freight + labour
            });
            totalAmt += (freight + labour);
        }
    });
    
    if (shipments.length === 0) {
        showToast('Selected shipments could not be loaded', 'error');
        return;
    }
    
    let debitLedger = 'Freight Outward A/c';
    let creditLedger = carrierName;
    
    const mappings = window.customMasters.freightJVs || [];
    const matchMap = mappings.find(m => 
        (m.expense_name || '').toLowerCase() === 'freight' || 
        (m.expense_name || '').toLowerCase() === carrierName.toLowerCase()
    );
    
    if (matchMap) {
        if (matchMap.jv_dr) debitLedger = matchMap.jv_dr;
        if (matchMap.jv_cr_type === 'static' && matchMap.jv_cr_static) {
            creditLedger = matchMap.jv_cr_static;
        }
    }
    
    // Populate Debit Account Datalist
    const debitDatalist = document.getElementById('jv-modal-debit-list');
    if (debitDatalist) {
        const uniqueDebits = new Set(['Freight Outward A/c', 'Freight Inward A/c', 'Freight Expense A/c']);
        const mappingsList = window.customMasters.freightJVs || [];
        mappingsList.forEach(m => {
            if (m.jv_dr) uniqueDebits.add(m.jv_dr);
        });
        debitDatalist.innerHTML = Array.from(uniqueDebits).map(d => `<option value="${d}"></option>`).join('');
    }

    // Populate Credit Account Datalist
    const creditDatalist = document.getElementById('jv-modal-credit-list');
    if (creditDatalist) {
        const uniqueCredits = new Set();
        if (carrierName) uniqueCredits.add(carrierName);
        const mappingsList = window.customMasters.freightJVs || [];
        mappingsList.forEach(m => {
            if (m.jv_cr_type === 'static' && m.jv_cr_static) uniqueCredits.add(m.jv_cr_static);
        });
        // Also add all transporters from database
        const transporters = db.transporters || [];
        transporters.forEach(t => {
            if (t.name && t.contactPerson !== '__CO_SETTINGS__' && t.contactPerson !== '__CUSTOM_MASTERS__') {
                uniqueCredits.add(t.name);
            }
        });
        creditDatalist.innerHTML = Array.from(uniqueCredits).map(c => `<option value="${c}"></option>`).join('');
    }

    // Populate GST Natures select
    const gstNatureSelect = document.getElementById('jv-modal-gst-nature');
    if (gstNatureSelect) {
        const gstNatures = window.customMasters.gstnatures || [];
        gstNatureSelect.innerHTML = '<option value="">-- Select GST Nature --</option>' + 
            gstNatures.map(g => {
                const name = typeof g === 'object' ? g.name : g;
                const code = typeof g === 'object' ? g.code : '';
                return `<option value="${name}">${name} (${code || 'No Code'})</option>`;
            }).join('');
    }

    document.getElementById('jv-modal-shipments').value = JSON.stringify(shipments);
    document.getElementById('jv-modal-date').value = new Date().toISOString().split('T')[0];
    document.getElementById('jv-modal-no').value = 'JV/FR/' + Math.floor(1000 + Math.random() * 9000);
    document.getElementById('jv-modal-debit').value = debitLedger;
    document.getElementById('jv-modal-credit').value = creditLedger;
    document.getElementById('jv-modal-gst-nature').value = '';
    document.getElementById('jv-modal-narration').value = `Freight JV generated for ${shipments.length} shipments via ${carrierName}. Total Amount: Rs.${totalAmt.toFixed(2)}`;
    
    const tbody = document.getElementById('jv-modal-shipments-tbody');
    if (tbody) {
        tbody.innerHTML = shipments.map((s, idx) => `
            <tr>
                <td><strong>${s.number}</strong> (${s.type})</td>
                <td>${s.party}</td>
                <td style="text-align:right;">${s.pkgCount}</td>
                <td>
                    <select class="form-input" style="width:100px; padding: 4px; font-size:12px; margin:0;" onchange="window.updateFreightJvRowMode(${idx}, this.value)">
                        <option value="per_bale" ${s.freightMode === 'per_bale' ? 'selected' : ''}>Bale-wise</option>
                        <option value="flat" ${s.freightMode !== 'per_bale' ? 'selected' : ''}>Flat Rate</option>
                    </select>
                </td>
                <td style="text-align:right;">
                    <input type="number" step="0.01" class="form-input jv-bale-rate-input-${idx}" style="width:80px; text-align:right; display:inline-block; padding: 4px 8px; font-size:12px; margin:0; ${s.freightMode !== 'per_bale' ? 'background:var(--bg-secondary);' : ''}" value="${s.freightRate || 0}" ${s.freightMode !== 'per_bale' ? 'disabled' : ''} onchange="window.updateFreightJvRowBaleRate(${idx}, this.value)">
                </td>
                <td style="text-align:right;">
                    <input type="number" step="0.01" class="form-input jv-freight-input-${idx}" style="width:90px; text-align:right; display:inline-block; padding: 4px 8px; font-size:12px; margin:0; ${s.freightMode === 'per_bale' ? 'background:var(--bg-secondary);' : ''}" value="${s.freight}" ${s.freightMode === 'per_bale' ? 'disabled' : ''} onchange="window.updateFreightJvRowFreightAmount(${idx}, this.value)">
                </td>
                <td style="text-align:right;">
                    <input type="number" step="0.01" class="form-input" style="width:90px; text-align:right; display:inline-block; padding: 4px 8px; font-size:12px; margin:0;" value="${s.labour}" onchange="window.updateFreightJvModalAmount(${idx}, 'labour', this.value)">
                </td>
            </tr>
        `).join('');
        tbody.innerHTML += `
            <tr style="background:var(--bg-secondary); font-weight:700;">
                <td colspan="5">TOTAL AMOUNT</td>
                <td colspan="2" id="jv-modal-total-amt" style="text-align:right; color:var(--primary); font-size:13px;">�${totalAmt.toFixed(2)}</td>
            </tr>
        `;
    }
    
    openModal('freight-jv-modal');
};

window.updateFreightJvRowMode = function(idx, val) {
    const shipmentsInput = document.getElementById('jv-modal-shipments');
    if (!shipmentsInput) return;
    try {
        const shipments = JSON.parse(shipmentsInput.value);
        if (shipments[idx]) {
            shipments[idx].freightMode = val;
            if (val === 'per_bale') {
                const bales = parseFloat(shipments[idx].pkgCount) || 0;
                const rate = parseFloat(shipments[idx].freightRate) || 0;
                shipments[idx].freight = bales * rate;
            }
            shipments[idx].amount = (shipments[idx].freight || 0) + (shipments[idx].labour || 0);
        }
        shipmentsInput.value = JSON.stringify(shipments);
        
        const baleRateInput = document.querySelector(`.jv-bale-rate-input-${idx}`);
        const freightInput = document.querySelector(`.jv-freight-input-${idx}`);
        if (val === 'per_bale') {
            if (baleRateInput) {
                baleRateInput.disabled = false;
                baleRateInput.style.backgroundColor = '';
            }
            if (freightInput) {
                freightInput.disabled = true;
                freightInput.style.backgroundColor = 'var(--bg-secondary)';
                freightInput.value = shipments[idx].freight.toFixed(2);
            }
        } else {
            if (baleRateInput) {
                baleRateInput.disabled = true;
                baleRateInput.style.backgroundColor = 'var(--bg-secondary)';
            }
            if (freightInput) {
                freightInput.disabled = false;
                freightInput.style.backgroundColor = '';
            }
        }
        
        window.recalcFreightJvTotal();
    } catch(e) {
        console.error(e);
    }
};

window.updateFreightJvRowBaleRate = function(idx, val) {
    const rate = parseFloat(val) || 0;
    const shipmentsInput = document.getElementById('jv-modal-shipments');
    if (!shipmentsInput) return;
    try {
        const shipments = JSON.parse(shipmentsInput.value);
        if (shipments[idx]) {
            shipments[idx].freightRate = rate;
            if (shipments[idx].freightMode === 'per_bale') {
                const bales = parseFloat(shipments[idx].pkgCount) || 0;
                shipments[idx].freight = bales * rate;
                const freightInput = document.querySelector(`.jv-freight-input-${idx}`);
                if (freightInput) {
                    freightInput.value = shipments[idx].freight.toFixed(2);
                }
            }
            shipments[idx].amount = (shipments[idx].freight || 0) + (shipments[idx].labour || 0);
        }
        shipmentsInput.value = JSON.stringify(shipments);
        window.recalcFreightJvTotal();
    } catch(e) {
        console.error(e);
    }
};

window.updateFreightJvRowFreightAmount = function(idx, val) {
    const amt = parseFloat(val) || 0;
    const shipmentsInput = document.getElementById('jv-modal-shipments');
    if (!shipmentsInput) return;
    try {
        const shipments = JSON.parse(shipmentsInput.value);
        if (shipments[idx]) {
            shipments[idx].freight = amt;
            shipments[idx].amount = amt + (shipments[idx].labour || 0);
        }
        shipmentsInput.value = JSON.stringify(shipments);
        window.recalcFreightJvTotal();
    } catch(e) {
        console.error(e);
    }
};

window.recalcFreightJvTotal = function() {
    const shipmentsInput = document.getElementById('jv-modal-shipments');
    if (!shipmentsInput) return;
    try {
        const shipments = JSON.parse(shipmentsInput.value);
        let totalAmt = 0;
        shipments.forEach(s => {
            totalAmt += (s.freight || 0) + (s.labour || 0);
        });
        
        const totalCell = document.getElementById('jv-modal-total-amt');
        if (totalCell) {
            totalCell.textContent = '�' + totalAmt.toFixed(2);
        }
        
        const creditLedger = document.getElementById('jv-modal-credit')?.value || '';
        const narrationInput = document.getElementById('jv-modal-narration');
        if (narrationInput) {
            narrationInput.value = `Freight JV generated for ${shipments.length} shipments via ${creditLedger}. Total Amount: Rs.${totalAmt.toFixed(2)}`;
        }
    } catch(e) {
        console.error(e);
    }
};

window.updateFreightJvModalAmount = function(idx, field, value) {
    const val = parseFloat(value) || 0;
    const shipmentsInput = document.getElementById('jv-modal-shipments');
    if (!shipmentsInput) return;
    try {
        const shipments = JSON.parse(shipmentsInput.value);
        if (shipments[idx]) {
            shipments[idx][field] = val;
            shipments[idx].amount = (shipments[idx].freight || 0) + (shipments[idx].labour || 0);
        }
        shipmentsInput.value = JSON.stringify(shipments);
        window.recalcFreightJvTotal();
    } catch(e) {
        console.error("Error updating JV modal amount:", e);
    }
};

window.saveFreightJvDraft = async function() {
    const shipmentsJson = document.getElementById('jv-modal-shipments').value;
    const jvDate = document.getElementById('jv-modal-date').value;
    const jvNo = document.getElementById('jv-modal-no').value.trim();
    const debitLedger = document.getElementById('jv-modal-debit').value.trim();
    const creditLedger = document.getElementById('jv-modal-credit').value.trim();
    const narration = document.getElementById('jv-modal-narration').value.trim();
    
    if (!jvDate || !jvNo || !debitLedger || !creditLedger) {
        showToast('JV Date, Number, Debit Account and Credit Account are required', 'error');
        return;
    }
    
    let shipments = [];
    try {
        shipments = JSON.parse(shipmentsJson);
    } catch (e) {
        showToast('Invalid shipments payload', 'error');
        return;
    }
    
    const totalAmount = shipments.reduce((sum, s) => sum + s.amount, 0);
    const shipmentIds = shipments.map(s => s.id);
    
    showImportLoadingOverlay();
    try {
        const carrierVal = document.getElementById('reconcile-freight-carrier')?.value || '';
        const parts = carrierVal.split(':');
        const carrierName = parts[2] || parts[1] || 'Unknown';
        
        const jvRecord = {
            id: 'jv_' + Math.random().toString(36).substr(2, 9),
            company_id: window.currentCompanyId || 'co4',
            type: 'freight_jv',
            category: 'freight',
            number: jvNo,
            date: jvDate,
            partyName: carrierName,
            debitLedger: debitLedger,
            creditLedger: creditLedger,
            totalAmount: totalAmount,
            remarks: narration,
            reconciledShipments: shipmentIds,
            status: 'Draft',
            created_at: new Date().toISOString()
        };
        
        await saveToSupabase('generic_transactions', jvRecord);
        
        for (const ship of shipments) {
            let shipmentRecord = null;
            let dbTable = '';
            if (ship.dbTable === 'grns') {
                dbTable = 'grns';
                const grns = [
                    ...(db.grn_cust_plain || []),
                    ...(db.grn_vend_emb || []),
                    ...(db.grn_consumable || [])
                ];
                shipmentRecord = grns.find(g => g.id === ship.id);
            } else if (ship.dbTable === 'outwards') {
                dbTable = 'outwards';
                shipmentRecord = (db.outward || []).find(o => o.id === ship.id);
            }
            if (shipmentRecord) {
                shipmentRecord.reconciledVoucherId = jvRecord.id;
                shipmentRecord.reconciledVoucherNumber = jvRecord.number;
                
                let currentTransport = {};
                let remarksText = shipmentRecord.remarks || '';
                if (remarksText.includes('[TRANSPORT:')) {
                    const match = remarksText.match(/\[TRANSPORT:(\{.*?\})\]/);
                    if (match) {
                        try {
                            currentTransport = JSON.parse(match[1]);
                        } catch(e) {}
                    }
                    remarksText = remarksText.replace(/\[TRANSPORT:[\s\S]*?\]/g, '').trim();
                }
                
                const updatedTransport = {
                    ...currentTransport,
                    freightMode: ship.freightMode || 'flat',
                    bales: parseFloat(ship.pkgCount) || 0,
                    freightRate: parseFloat(ship.freightRate) || 0,
                    freightAmount: parseFloat(ship.freight) || 0,
                    labour: parseFloat(ship.labour) || 0
                };
                
                const newTransportStr = `[TRANSPORT:${JSON.stringify(updatedTransport)}]`;
                const finalRemarks = remarksText ? (remarksText + '\n' + newTransportStr) : newTransportStr;
                
                shipmentRecord.remarks = finalRemarks;
                if (ship.dbTable === 'outwards') {
                    shipmentRecord.transportLabour = parseFloat(ship.labour) || 0;
                }
                
                if (window.supabase) {
                    await saveToSupabase(dbTable, shipmentRecord);
                }
            }
        }
        
        hideImportLoadingOverlay();
        closeModal('freight-jv-modal');
        showToast('Freight JV Draft saved successfully!', 'success');
        
        const chks = document.querySelectorAll('.shipment-reconcile-chk:checked');
        chks.forEach(chk => { chk.checked = false; });
        window.updateFreightReconcileCount();
        
        window.openFreightTab('jvs');
        
    } catch (err) {
        hideImportLoadingOverlay();
        console.error("Error saving JV Draft:", err);
        showToast('Failed to save JV Draft: ' + err.message, 'error');
    }
};

window.previewFreightJv = function(jvId) {
    const list = db.genericTransactions || [];
    const jv = list.find(x => x.id === jvId);
    if (!jv) {
        showToast('JV not found', 'error');
        return;
    }
    
    const xml = buildJvXml(jv.number, jv.date, jv.debitLedger, jv.creditLedger, jv.totalAmount, jv.remarks);
    
    document.getElementById('jv-preview-id').value = jvId;
    document.getElementById('jv-preview-xml').value = xml;
    
    openModal('freight-jv-preview-modal');
};

window.confirmSyncFreightJv = async function() {
    const jvId = document.getElementById('jv-preview-id').value;
    const xml = document.getElementById('jv-preview-xml').value;
    
    const list = db.genericTransactions || [];
    const jv = list.find(x => x.id === jvId);
    if (!jv) {
        showToast('JV not found', 'error');
        return;
    }
    
    showImportLoadingOverlay();
    try {
        const syncRecord = {
            company_id: jv.company_id || 'co4',
            voucher_type: '7',
            voucher_id: jv.id,
            voucher_no: jv.number,
            sc: '2',
            vch_xml: xml,
            status: 'pending',
            created_at: new Date().toISOString()
        };
        
        const { data: existing } = await window.supabase
            .from('busy_sync_queue')
            .select('id')
            .eq('voucher_id', jv.id)
            .limit(1);

        if (existing && existing.length > 0) {
            await window.supabase
                .from('busy_sync_queue')
                .update(syncRecord)
                .eq('id', existing[0].id);
        } else {
            await window.supabase
                .from('busy_sync_queue')
                .insert(syncRecord);
        }
        
        jv.status = 'Synced';
        await saveToSupabase('generic_transactions', jv);
        
        hideImportLoadingOverlay();
        closeModal('freight-jv-preview-modal');
        showToast('JV queued for Busy Sync successfully!', 'success');
        
        window.renderFreightJvs();
    } catch (err) {
        hideImportLoadingOverlay();
        console.error("Error queueing JV for sync:", err);
        showToast('Failed to queue JV: ' + err.message, 'error');
    }
};

window.deleteFreightJv = async function(jvId) {
    const list = db.genericTransactions || [];
    const jv = list.find(x => x.id === jvId);
    if (!jv) return;
    
    if (!(await window.showSmartConfirm('Delete JV', `Are you sure you want to delete Freight JV "${jv.number}"? This will unlink the shipments.`))) {
        return;
    }
    
    showImportLoadingOverlay();
    try {
        const linkedIds = jv.reconciledShipments || [];
        for (const shipId of linkedIds) {
            let shipmentRecord = null;
            let dbName = '';
            
            const grns = [
                ...(db.grn_cust_plain || []),
                ...(db.grn_vend_emb || []),
                ...(db.grn_consumable || [])
            ];
            shipmentRecord = grns.find(g => g.id === shipId);
            if (shipmentRecord) {
                dbName = 'grns';
            } else {
                shipmentRecord = (db.outward || []).find(o => o.id === shipId);
                if (shipmentRecord) dbName = 'outwards';
            }
            
            if (shipmentRecord) {
                shipmentRecord.reconciledVoucherId = null;
                shipmentRecord.reconciledVoucherNumber = null;
                await saveToSupabase(dbName, shipmentRecord);
            }
        }
        
        await window.supabase
            .from('busy_sync_queue')
            .delete()
            .eq('voucher_id', jvId);
            
        await window.supabase
            .from('generic_transactions')
            .delete()
            .eq('id', jvId);
            
        if (db && db.genericTransactions) {
            db.genericTransactions = db.genericTransactions.filter(x => x.id !== jvId);
        }
        
        hideImportLoadingOverlay();
        showToast('Freight JV deleted successfully', 'success');
        window.renderFreightJvs();
        
    } catch (e) {
        hideImportLoadingOverlay();
        console.error("Error deleting JV:", e);
        showToast("Delete failed: " + e.message, "error");
    }
};

