window.makeJvFromSelectedLogs = function(section) {
    const selected = window.getSelectedFreightVouchers(section);
    if (!selected.length) {
        showToast('Please select at least one shipment voucher using checkboxes.', 'warning');
        return;
    }
    
    const { grns, outwards, getRecordPkgCount } = window.getAllLogisticsRecords();
    const shipments = [];
    const carriers = new Set();
    
    selected.forEach(item => {
        let record = null;
        let dbTable = '';
        let type = '';
        
        if (item.type === 'GRN') {
            dbTable = 'grns';
            type = 'GRN';
            record = grns.find(g => g.id === item.id);
        } else {
            dbTable = 'outwards';
            type = 'Outward';
            record = outwards.find(o => o.id === item.id);
        }
        
        if (record) {
            let name = record.transporterName || record.transporter || '';
            let tid = (record.transporterId || '').trim();
            let carrierType = 'transporter';
            
            if (!name && tid) {
                const t = (db.transporters || []).find(x => String(x.id) === String(tid));
                if (t) name = t.name;
            }
            name = (name || '').trim();
            if (name.toLowerCase() === 'transporter') name = '';
            
            if (!name && (record.taxiName && record.taxiName !== '-')) {
                name = record.taxiName;
                tid = record.taxiName;
                carrierType = 'taxi';
            }
            
            if (!name) {
                name = 'Unknown';
            }
            
            carriers.add(`${carrierType}:${tid}:${name}`);
            
            const freight = parseFloat(record.freightAmount || record.freight_amount || 0);
            const labour = parseFloat(record.transportLabour || record.labour || 0);
            
            shipments.push({
                id: record.id,
                dbTable: dbTable,
                type: type,
                number: record.grnNo || record.number,
                party: record.customerName || record.partyName || record.vendorName || '-',
                pkgCount: getRecordPkgCount(record),
                freight: freight,
                labour: labour,
                amount: freight + labour,
                carrierKey: `${carrierType}:${tid}:${name}`
            });
        }
    });
    
    if (carriers.size > 1) {
        showToast('All selected shipments must belong to the same Transporter/Carrier.', 'error');
        return;
    }
    
    if (shipments.length === 0) {
        showToast('Could not load selected shipments.', 'error');
        return;
    }
    
    const carrierKey = Array.from(carriers)[0];
    
    window.openFreightTab('reconciliation');
    
    setTimeout(() => {
        const select = document.getElementById('reconcile-freight-carrier');
        if (select) {
            let exists = false;
            for (let i = 0; i < select.options.length; i++) {
                if (select.options[i].value === carrierKey) {
                    exists = true;
                    select.selectedIndex = i;
                    break;
                }
            }
            if (!exists) {
                const parts = carrierKey.split(':');
                const opt = document.createElement('option');
                opt.value = carrierKey;
                opt.textContent = (parts[0] === 'taxi' ? '=� ' : '=� ') + parts[2];
                select.appendChild(opt);
                select.value = carrierKey;
            }
        }

        window.renderFreightReconciliation();
        
        const chks = document.querySelectorAll('.shipment-reconcile-chk');
        chks.forEach(chk => {
            const isSelected = shipments.some(s => s.id === chk.value);
            chk.checked = isSelected;
        });
        
        window.updateFreightReconcileCount();
        window.openFreightJvModal();
    }, 150);
};

function renderFinishingTable() {
    const activeEl = document.activeElement;
    if (activeEl && (
        activeEl.classList.contains('group-mending-rate-input') || 
        activeEl.classList.contains('slip-mending-input') ||
        activeEl.classList.contains('group-other-jw-rate-input') ||
        activeEl.classList.contains('slip-other-jw-input')
    )) {
        return;
    }
    const tbody = document.getElementById('tx-finishing-table-body');
    if (!tbody) return;

    // Save expanded states before re-rendering
    const expandedIds = [];
    document.querySelectorAll('tr[id^="child-row-"]').forEach(tr => {
        if (tr.style.display !== 'none') {
            expandedIds.push(tr.id.replace('child-row-', ''));
        }
    });

    db.productionSlips = db.productionSlips || [];

    const search = (document.getElementById('tx-finishing-search')?.value || '').toLowerCase();

    // Group production slips by PO Number (poNumber or poId)
    const groups = {};

    db.productionSlips.forEach(p => {
        if (p.status?.trim().toLowerCase() === 'cancelled') return;

        // Use poNumber if available, fallback to poId or 'Direct'
        const poKey = p.poNumber || p.poId || 'Direct';
        if (!groups[poKey]) {
            groups[poKey] = {
                poNumber: p.poNumber || 'Direct / None',
                poId: p.poId,
                finishedItemName: p.finishedItemName || p.design || 'Fabric',
                totalThan: 0,
                totalQty: 0,
                totalEmbroideryMtr: 0,
                totalMendingCharges: 0,
                totalOtherJwCharges: 0,
                remarksList: [],
                slipIds: []
            };
        }

        const g = groups[poKey];
        
        // Sum top-level values
        g.totalThan += parseFloat(p.than || 0);
        g.totalQty += parseFloat(p.qty || 0);
        g.totalEmbroideryMtr += parseFloat(p.embroideryMtr || 0);

        // Sum mending charges from top-level and item rows (links)
        let slipMending = 0;
        if (p.links && Array.isArray(p.links) && p.links.length > 0) {
            p.links.forEach(lnk => {
                slipMending += parseFloat(lnk.mendingCharges || 0);
            });
        } else {
            slipMending = parseFloat(p.mendingCharges || 0);
        }
        g.totalMendingCharges += slipMending;

        // Sum other JW charges from top-level and item rows (links)
        let slipOtherJw = 0;
        if (p.links && Array.isArray(p.links) && p.links.length > 0) {
            p.links.forEach(lnk => {
                slipOtherJw += parseFloat(lnk.otherJwCharges || 0);
            });
        } else {
            slipOtherJw = parseFloat(p.otherJwCharges || 0);
        }
        g.totalOtherJwCharges += slipOtherJw;

        if (p.remarks && p.remarks.trim()) {
            g.remarksList.push(window.cleanRemarksForLog(p.remarks));
        }
        g.slipIds.push(p.id);
    });

    // Convert groups object to array and filter by search
    let data = Object.values(groups);
    if (search) {
        data = data.filter(g => 
            g.poNumber.toLowerCase().includes(search) ||
            g.finishedItemName.toLowerCase().includes(search)
        );
    }

    // Sort by PO Number descending
    data.sort((a, b) => b.poNumber.localeCompare(a.poNumber));

    if (data.length === 0) {
        tbody.innerHTML = `<tr><td colspan="8" class="empty-row">${search ? 'No matching PO records found.' : 'No production records found.'}</td></tr>`;
        return;
    }

    tbody.innerHTML = data.map(g => {
        const uniqueRemarks = [...new Set(g.remarksList)].join(', ') || '-';
        const uniqueId = g.poNumber.replace(/[^a-zA-Z0-9]/g, '_');

        // Build child slips rows
        const slips = db.productionSlips.filter(p => (p.poNumber === g.poNumber || p.poId === g.poNumber) && p.status?.trim().toLowerCase() !== 'cancelled');
        slips.sort((a, b) => {
            const numA = parseInt((a.number || '').replace(/\D/g, '')) || 0;
            const numB = parseInt((b.number || '').replace(/\D/g, '')) || 0;
            return numB - numA;
        });

        const childRowsHtml = slips.map(s => {
            let slipMending = 0;
            if (s.links && Array.isArray(s.links) && s.links.length > 0) {
                s.links.forEach(lnk => {
                    slipMending += parseFloat(lnk.mendingCharges || 0);
                });
            } else {
                slipMending = parseFloat(s.mendingCharges || 0);
            }
            
            let slipOtherJw = 0;
            if (s.links && Array.isArray(s.links) && s.links.length > 0) {
                s.links.forEach(lnk => {
                    slipOtherJw += parseFloat(lnk.otherJwCharges || 0);
                });
            } else {
                slipOtherJw = parseFloat(s.otherJwCharges || 0);
            }

            return `
                <tr style="background: #ffffff; border-bottom: 1px solid #cbd5e1;">
                    <td style="padding: 8px 10px;"><a href="javascript:void(0)" onclick="openProductionModal('${s.id}', 'production')" style="color: var(--accent-blue); text-decoration: none; font-weight: 700; cursor: pointer;">${s.number}</a></td>
                    <td style="padding: 8px 10px;">${s.planNumber ? `<span class="badge badge-blue">${s.planNumber}</span>` : '<span class="text-muted">Direct</span>'}</td>
                    <td style="padding: 8px 10px;">${formatDate(s.date)}</td>
                    <td style="padding: 8px 10px;">${parseFloat(s.than || 0).toFixed(2)}</td>
                    <td style="padding: 8px 10px;"><strong>${parseFloat(s.embroideryMtr || 0).toFixed(2)} m</strong></td>
                    <td style="padding: 8px 10px;"><strong>${parseFloat(s.qty || 0).toFixed(2)} m</strong></td>
                    <td style="padding: 4px 10px;">
                        <input type="number" class="form-input slip-mending-input" data-slip-id="${s.id}" value="${slipMending || ''}" placeholder="0.00" step="0.01" style="width: 100px; height: 26px; padding: 2px 6px; font-size: 12px; border: 1px solid var(--border); background: #ffffff; color: var(--text-primary); font-weight: 700;" onchange="window.updateSlipMendingChargesInline(this)">
                    </td>
                    <td style="padding: 4px 10px;">
                        <input type="number" class="form-input slip-other-jw-input" data-slip-id="${s.id}" value="${slipOtherJw || ''}" placeholder="0.00" step="0.01" style="width: 100px; height: 26px; padding: 2px 6px; font-size: 12px; border: 1px solid var(--border); background: #ffffff; color: var(--text-primary); font-weight: 700;" onchange="window.updateSlipOtherJwChargesInline(this)">
                    </td>
                    <td style="padding: 8px 10px;">
                        <button class="btn btn-sm btn-secondary" onclick="openProductionModal('${s.id}', 'production')" style="font-size: 10px; padding: 2px 6px;"> Edit</button>
                    </td>
                </tr>
            `;
        }).join('');

        // Read values from first slip for parent group row inputs
        const firstSlip = slips[0];
        let mendingPerMeter = 0;
        let distributeInProd = true;
        let otherJwPerMeter = 0;
        let otherJwDistribute = true;
        if (firstSlip) {
            mendingPerMeter = firstSlip.mendingPerMeter !== undefined ? firstSlip.mendingPerMeter : (firstSlip.links?.[0]?.mendingPerMeter || 0);
            distributeInProd = firstSlip.distributeInProd !== undefined ? firstSlip.distributeInProd : (firstSlip.links?.[0]?.distributeInProd !== undefined ? firstSlip.links[0].distributeInProd : true);
            otherJwPerMeter = firstSlip.otherJwPerMeter !== undefined ? firstSlip.otherJwPerMeter : (firstSlip.links?.[0]?.otherJwPerMeter || 0);
            otherJwDistribute = firstSlip.otherJwDistribute !== undefined ? firstSlip.otherJwDistribute : (firstSlip.links?.[0]?.otherJwDistribute !== undefined ? firstSlip.links[0].otherJwDistribute : true);
        }

        return `
            <tr style="background: #f8fafc; border-bottom: 2px solid #e2e8f0;">
                <td>
                    <button id="btn-collapse-${uniqueId}" class="btn btn-sm btn-link" onclick="window.toggleFinishingRowCollapse('${uniqueId}')" style="margin-right: 8px; text-decoration: none; font-weight: bold; font-size: 14px; padding: 0 4px; border: none; background: transparent; cursor: pointer; color: var(--accent-blue);">�</button>
                    <strong style="color: var(--accent-blue); cursor: pointer;" onclick="window.toggleFinishingRowCollapse('${uniqueId}')">${g.poNumber}</strong>
                </td>
                <td><strong>${g.finishedItemName}</strong></td>
                <td><strong>${g.totalThan.toFixed(2)}</strong></td>
                <td><strong>${parseFloat(firstSlip?.embroideryMtr || 0).toFixed(2)} m</strong></td>
                <td><strong>${g.totalQty.toFixed(2)} m</strong></td>
                <td style="padding: 4px 10px;">
                    <input type="number" class="form-input group-mending-rate-input" value="${mendingPerMeter || ''}" placeholder="0.00" step="0.01" style="width: 80px; height: 26px; padding: 2px 6px; font-size: 12px; border: 1px solid var(--border); background: #ffffff; color: var(--text-primary); font-weight: 700;" onchange="window.updateGroupMendingCalculationInline(this, '${g.poNumber.replace(/'/g, "\\'")}')">
                </td>
                <td style="padding: 4px 10px; text-align: center;">
                    <input type="checkbox" class="group-mending-distribute-input" ${distributeInProd ? 'checked' : ''} style="width: 16px; height: 16px; cursor: pointer; vertical-align: middle;" onchange="window.updateGroupMendingCalculationInline(this, '${g.poNumber.replace(/'/g, "\\'")}')">
                </td>
                <td style="color: var(--accent-purple); font-weight: 700;">�${g.totalMendingCharges.toLocaleString('en-IN', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
                <td style="padding: 4px 10px;">
                    <input type="number" class="form-input group-other-jw-rate-input" value="${otherJwPerMeter || ''}" placeholder="0.00" step="0.01" style="width: 80px; height: 26px; padding: 2px 6px; font-size: 12px; border: 1px solid var(--border); background: #ffffff; color: var(--text-primary); font-weight: 700;" onchange="window.updateGroupOtherJwCalculationInline(this, '${g.poNumber.replace(/'/g, "\\'")}')">
                </td>
                <td style="padding: 4px 10px; text-align: center;">
                    <input type="checkbox" class="group-other-jw-distribute-input" ${otherJwDistribute ? 'checked' : ''} style="width: 16px; height: 16px; cursor: pointer; vertical-align: middle;" onchange="window.updateGroupOtherJwCalculationInline(this, '${g.poNumber.replace(/'/g, "\\'")}')">
                </td>
                <td style="color: var(--accent-purple); font-weight: 700;">�${g.totalOtherJwCharges.toLocaleString('en-IN', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
                <td>
                    <div class="table-actions">
                        <button class="btn btn-sm btn-secondary" onclick="window.toggleFinishingRowCollapse('${uniqueId}')" style="font-size: 11px; padding: 4px 8px; border-radius: 4px;">=A Details</button>
                    </div>
                </td>
            </tr>
            <tr id="child-row-${uniqueId}" style="display: none; background: #f1f5f9;">
                <td colspan="12" style="padding: 12px 20px;">
                    <div style="border: 1px solid #cbd5e1; border-radius: 8px; overflow: hidden; box-shadow: inset 0 2px 4px rgba(0,0,0,0.02);">
                        <table class="data-table" style="width: 100%; font-size: 12px; margin: 0; background: #ffffff;">
                            <thead style="background: #f8fafc; border-bottom: 1px solid #cbd5e1;">
                                <tr>
                                    <th style="padding: 8px 10px; width: 15%;">Slip No.</th>
                                    <th style="padding: 8px 10px; width: 15%;">Plan No.</th>
                                    <th style="padding: 8px 10px; width: 15%;">Date</th>
                                    <th style="padding: 8px 10px; width: 10%;">Than</th>
                                    <th style="padding: 8px 10px; width: 10%;">Emb. Mtr</th>
                                    <th style="padding: 8px 10px; width: 10%;">Qty</th>
                                    <th style="padding: 8px 10px; width: 15%;">Mending Charges</th>
                                    <th style="padding: 8px 10px; width: 15%;">Other JW Charges</th>
                                    <th style="padding: 8px 10px; width: 5%;">Action</th>
                                </tr>
                            </thead>
                            <tbody>
                                ${childRowsHtml}
                            </tbody>
                        </table>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    // Restore expanded states after rendering HTML
    expandedIds.forEach(id => {
        const childRow = document.getElementById('child-row-' + id);
        const btn = document.getElementById('btn-collapse-' + id);
        if (childRow) childRow.style.display = 'table-row';
        if (btn) btn.textContent = '�';
    });
}
window.renderFinishingTable = renderFinishingTable;

window.toggleFinishingRowCollapse = function(uniqueId) {
    const childRow = document.getElementById('child-row-' + uniqueId);
    const btn = document.getElementById('btn-collapse-' + uniqueId);
    if (!childRow) return;

    if (childRow.style.display === 'none') {
        childRow.style.display = 'table-row';
        if (btn) btn.textContent = '�';
    } else {
        childRow.style.display = 'none';
        if (btn) btn.textContent = '�';
    }
};

window.updateSlipMendingChargesInline = async function(input) {
    const slipId = input.dataset.slipId;
    const val = parseFloat(input.value) || 0;

    db.productionSlips = db.productionSlips || [];
    const slip = db.productionSlips.find(s => s.id === slipId);
    if (!slip) return;

    // Save expanded states
    const expandedIds = [];
    document.querySelectorAll('tr[id^="child-row-"]').forEach(tr => {
        if (tr.style.display !== 'none') {
            expandedIds.push(tr.id.replace('child-row-', ''));
        }
    });

    slip.mendingCharges = val;
    if (slip.links && Array.isArray(slip.links) && slip.links.length > 0) {
        slip.links.forEach(lnk => {
            lnk.mendingCharges = val;
        });
    }

    try {
        await saveToSupabase('production_slips', slip);

        // Re-render and restore expanded states
        window.renderFinishingTable();
        expandedIds.forEach(id => {
            const childRow = document.getElementById('child-row-' + id);
            const btn = document.getElementById('btn-collapse-' + id);
            if (childRow) childRow.style.display = 'table-row';
            if (btn) btn.textContent = '�';
        });
    } catch (e) {
        console.error(e);
        showToast('Failed to save mending charges', 'error');
    }
};

window.updateGroupMendingCalculationInline = async function(input, poNumber) {
    const parentRow = input.closest('tr');
    if (!parentRow) return;

    const rateInp = parentRow.querySelector('.group-mending-rate-input');
    const distInp = parentRow.querySelector('.group-mending-distribute-input');

    const rate = rateInp ? (parseFloat(rateInp.value) || 0) : 0;
    const distribute = distInp ? distInp.checked : false;

    db.productionSlips = db.productionSlips || [];
    const slips = db.productionSlips.filter(p => (p.poNumber === poNumber || p.poId === poNumber) && p.status?.trim().toLowerCase() !== 'cancelled');

    if (slips.length === 0) return;

    // Save expanded states
    const expandedIds = [];
    document.querySelectorAll('tr[id^="child-row-"]').forEach(tr => {
        if (tr.style.display !== 'none') {
            expandedIds.push(tr.id.replace('child-row-', ''));
        }
    });

    try {
        for (const slip of slips) {
            slip.mendingPerMeter = rate;
            slip.distributeInProd = distribute;
            const qty = parseFloat(slip.qty || 0);
            const calculatedCharges = distribute ? (rate * qty) : rate;
            slip.mendingCharges = calculatedCharges;

            if (slip.links && Array.isArray(slip.links)) {
                slip.links.forEach(lnk => {
                    lnk.mendingPerMeter = rate;
                    lnk.distributeInProd = distribute;
                    lnk.mendingCharges = calculatedCharges;
                });
            }
            await saveToSupabase('production_slips', slip);
        }

        // Re-render and restore expanded states
        window.renderFinishingTable();
        expandedIds.forEach(id => {
            const childRow = document.getElementById('child-row-' + id);
            const btn = document.getElementById('btn-collapse-' + id);
            if (childRow) childRow.style.display = 'table-row';
            if (btn) btn.textContent = '�';
        });
    } catch (e) {
        console.error(e);
        showToast('Failed to save group mending calculation', 'error');
    }
};

