// ===== SEMI FINISHED GOODS DASHBOARD & COSTING LOGIC =====
window.currentSemiFinishedSection = 'inhouse';
try {
    const savedMending = localStorage.getItem('semifinished_mending_costs');
    window.semifinishedMendingCosts = savedMending ? JSON.parse(savedMending) : {};
} catch(e) {
    window.semifinishedMendingCosts = {};
}

window.switchSemiFinishedSection = function(section) {
    window.currentSemiFinishedSection = section;
    const btnInhouse = document.getElementById('semifinished-tab-inhouse');
    const btnVendor = document.getElementById('semifinished-tab-vendor');
    const secInhouse = document.getElementById('semifinished-section-inhouse');
    const secVendor = document.getElementById('semifinished-section-vendor');

    if (btnInhouse && btnVendor) {
        if (section === 'inhouse') {
            btnInhouse.classList.add('active');
            btnVendor.classList.remove('active');
        } else {
            btnVendor.classList.add('active');
            btnInhouse.classList.remove('active');
        }
    }
    if (secInhouse && secVendor) {
        secInhouse.style.display = section === 'inhouse' ? 'block' : 'none';
        secVendor.style.display = section === 'vendor' ? 'block' : 'none';
    }
    window.renderSemiFinishedTable();
};

window.updateSemiFinishedMendingCost = function(id, val) {
    const num = parseFloat(val) || 0;
    window.semifinishedMendingCosts = window.semifinishedMendingCosts || {};
    window.semifinishedMendingCosts[id] = num;
    try {
        localStorage.setItem('semifinished_mending_costs', JSON.stringify(window.semifinishedMendingCosts));
    } catch(e){}

    const row = document.querySelector(`[data-sf-id="${id}"]`);
    if (row) {
        const qty = parseFloat(row.getAttribute('data-sf-qty')) || 0;
        const otherJwCost = parseFloat(row.getAttribute('data-sf-other-jw')) || 0;
        const totalCost = num + otherJwCost;
        const totalAmount = totalCost * qty;

        const cellTotalCost = row.querySelector('.sf-total-cost-cell');
        const cellTotalAmt = row.querySelector('.sf-total-amt-cell');
        if (cellTotalCost) cellTotalCost.textContent = `�${totalCost.toFixed(2)}/m`;
        if (cellTotalAmt) cellTotalAmt.textContent = `�${totalAmount.toLocaleString('en-IN', {minimumFractionDigits: 2, maximumFractionDigits: 2})}`;
    }
};

window.renderSemiFinishedTable = function() {
    const searchVal = (document.getElementById('tx-semifinished-search')?.value || '').trim().toLowerCase();
    const section = window.currentSemiFinishedSection || 'inhouse';

    if (section === 'inhouse') {
        const tbody = document.getElementById('semifinished-inhouse-table-body');
        if (!tbody) return;

        const inhousePOs = (db.pos || []).filter(p => {
            if (p.status === 'Cancelled') return false;
            const pType = (p.poType || p.po_type || '').toLowerCase();
            const pNum = (p.number || '').toUpperCase();
            return pType === 'inhouse' || pNum.startsWith('PO/INH');
        });

        const rows = [];
        inhousePOs.forEach(po => {
            const poNo = po.number || po.poNo || 'PO/INH';
            const custName = po.customerName || (db.customers ? db.customers.find(c => String(c.id) === String(po.customerId))?.name : null) || 'Internal';
            const itemName = (po.items && po.items[0]?.itemName) || po.design || (po.items && po.items[0]?.processName) || 'Plain Fabric';
            const qty = parseFloat(po.qty || po.items?.reduce((s, r) => s + (parseFloat(r.qty) || 0), 0) || 0);

            if (searchVal) {
                const match = poNo.toLowerCase().includes(searchVal) ||
                              custName.toLowerCase().includes(searchVal) ||
                              itemName.toLowerCase().includes(searchVal);
                if (!match) return;
            }

            let otherJwCost = 0;
            const linkedFjwPOs = (db.pos || []).filter(f => {
                if (f.status === 'Cancelled') return false;
                const fType = (f.poType || f.po_type || '').toLowerCase();
                const fNum = (f.number || '').toUpperCase();
                const isFjw = fType === 'finishing_jw' || fNum.startsWith('PO/FJW') || fNum.startsWith('PO/FIN');
                return isFjw && (f.linkedPoId === po.id || f.linkedPoNumber === poNo || f.inhousePoId === po.id || f.inhousePoNumber === poNo);
            });
            linkedFjwPOs.forEach(fjw => {
                const fjwRate = parseFloat(fjw.rate || (fjw.items && fjw.items[0]?.rate) || 0);
                otherJwCost += fjwRate;
            });

            if (otherJwCost === 0) {
                const linkedOuts = (db.outwards || []).filter(o => o.poRefId === po.id || o.poRefId === poNo || o.linked_po_id === po.id);
                linkedOuts.forEach(out => {
                    const outRate = parseFloat(out.rate || 0);
                    if (outRate > 0) otherJwCost += outRate;
                });
            }

            const mendingCost = window.semifinishedMendingCosts[po.id] !== undefined ? window.semifinishedMendingCosts[po.id] : 0;
            const totalCost = mendingCost + otherJwCost;
            const totalAmount = totalCost * qty;

            rows.push(`
                <tr data-sf-id="${po.id}" data-sf-qty="${qty}" data-sf-other-jw="${otherJwCost}">
                    <td style="font-weight:700; color:var(--primary, #4338ca);">${poNo}</td>
                    <td>${custName}</td>
                    <td><strong>${itemName}</strong></td>
                    <td style="text-align:right; font-weight:600;">${qty.toLocaleString()} m</td>
                    <td style="text-align:right;">
                        <input type="number" class="form-input" value="${mendingCost || ''}" placeholder="0.00" step="any"
                            style="width:100px; height:28px; padding:2px 8px; font-size:12.5px; text-align:right; font-weight:700; border:1px solid #cbd5e1; background:#ffffff !important; color:#0f172a;"
                            oninput="window.updateSemiFinishedMendingCost('${po.id}', this.value)">
                    </td>
                    <td style="text-align:right; font-weight:600; color:#059669;">�${otherJwCost.toFixed(2)}/m</td>
                    <td style="text-align:right; font-weight:700; color:var(--accent-purple, #6366f1);" class="sf-total-cost-cell">�${totalCost.toFixed(2)}/m</td>
                    <td style="text-align:right; font-weight:700; color:var(--text-primary);" class="sf-total-amt-cell">�${totalAmount.toLocaleString('en-IN', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
                    <td style="text-align:center;">
                        <button class="btn btn-sm btn-secondary" onclick="window.openFjwFromSemiFinished('inhouse', '${po.id}')" title="Create Finishing Job Work">+ Create PO/FJW</button>
                    </td>
                </tr>
            `);
        });

        if (rows.length === 0) {
            tbody.innerHTML = `<tr><td colspan="9" class="empty-row">${searchVal ? 'No matching In-House PO records found.' : 'No In-House PO production records found.'}</td></tr>`;
        } else {
            tbody.innerHTML = rows.join('');
        }
    }
};

window.switchSemiFinishedSection = function(section) {
    window.currentSemiFinishedSection = section;
    const tabAll = document.getElementById('semifinished-tab-all');
    const tabInhouse = document.getElementById('semifinished-tab-inhouse');
    const tabVendor = document.getElementById('semifinished-tab-vendor');

    const secAll = document.getElementById('semifinished-section-all');
    const secInhouse = document.getElementById('semifinished-section-inhouse');
    const secVendor = document.getElementById('semifinished-section-vendor');

    if (tabAll) tabAll.classList.toggle('active', section === 'all');
    if (tabInhouse) tabInhouse.classList.toggle('active', section === 'inhouse');
    if (tabVendor) tabVendor.classList.toggle('active', section === 'vendor');

    if (secAll) secAll.style.display = section === 'all' ? 'block' : 'none';
    if (secInhouse) secInhouse.style.display = section === 'inhouse' ? 'block' : 'none';
    if (secVendor) secVendor.style.display = section === 'vendor' ? 'block' : 'none';

    window.renderSemiFinishedTable();
};

window.openFjwFromSemiFinished = function(sourceType, targetId) {
    if (typeof window.openPOModal === 'function') {
        window.openPOModal(null, 'finishing_jw');
    } else if (typeof window.selectPoType === 'function') {
        window.selectPoType('finishing_jw');
    }

    setTimeout(() => {
        const targetPo = (db.pos || []).find(p => String(p.id) === String(targetId) || String(p.number || '').toUpperCase() === String(targetId).toUpperCase());
        const matchedPoId = targetPo ? targetPo.id : targetId;

        if (targetPo) {
            const custId = targetPo.customerId || targetPo.customer_id || targetPo.customer || '';
            const custSelect = document.getElementById('po-customer');
            if (custSelect && custId) {
                custSelect.value = custId;
                if (typeof window.onPoCustomerChange === 'function') window.onPoCustomerChange();
                if (typeof reinitSearchableSelect === 'function') reinitSearchableSelect(custSelect);
            }
        }

        if (sourceType === 'vendor') {
            const radVendor = document.getElementById('po-fjw-source-vendor');
            if (radVendor) {
                radVendor.checked = true;
                if (typeof window.onPoFjwGoodsSourceChange === 'function') window.onPoFjwGoodsSourceChange();
            }
            if (typeof window.populateFjwVendorPoDropdown === 'function') window.populateFjwVendorPoDropdown();
            const selPo = document.getElementById('po-fjw-vendor-po-select');
            if (selPo) {
                selPo.value = matchedPoId || '';
                if (typeof window.onPoFjwVendorPoChange === 'function') window.onPoFjwVendorPoChange();
                if (typeof reinitSearchableSelect === 'function') reinitSearchableSelect(selPo);
            }
        } else {
            const radInhouse = document.getElementById('po-fjw-source-inhouse');
            if (radInhouse) {
                radInhouse.checked = true;
                if (typeof window.onPoFjwGoodsSourceChange === 'function') window.onPoFjwGoodsSourceChange();
            }
            if (typeof window.populateFjwInhouseDropdown === 'function') window.populateFjwInhouseDropdown();
            const selInhouse = document.getElementById('po-fjw-inhouse-select');
            if (selInhouse) {
                selInhouse.value = matchedPoId || '';
                if (typeof window.onPoFjwInhouseChange === 'function') window.onPoFjwInhouseChange();
                if (typeof reinitSearchableSelect === 'function') reinitSearchableSelect(selInhouse);
            }
        }
    }, 200);
};

window.renderSemiFinishedTable = function() {
    const searchVal = (document.getElementById('tx-semifinished-search')?.value || '').trim().toLowerCase();
    const section = window.currentSemiFinishedSection || 'all';

    const getOtherJwCost = function(po, isVendor) {
        const poNo = po.number || po.poNo || '';
        let otherJwCost = 0;
        const linkedFjwPOs = (db.pos || []).filter(f => {
            if (f.status === 'Cancelled') return false;
            const fType = (f.poType || f.po_type || '').toLowerCase();
            const fNum = (f.number || '').toUpperCase();
            const isFjw = fType === 'finishing_jw' || fNum.startsWith('PO/FJW') || fNum.startsWith('PO/FIN');
            if (!isFjw) return false;
            if (isVendor) {
                return f.vendorPoId === po.id || f.vendorPoNumber === poNo || f.linkedPoId === po.id || f.linkedPoNumber === poNo;
            } else {
                return f.linkedPoId === po.id || f.linkedPoNumber === poNo || f.inhousePoId === po.id || f.inhousePoNumber === poNo;
            }
        });
        linkedFjwPOs.forEach(fjw => {
            const fjwRate = parseFloat(fjw.rate || (fjw.items && fjw.items[0]?.rate) || 0);
            otherJwCost += fjwRate;
        });

        if (otherJwCost === 0) {
            const linkedOuts = (db.outwards || []).filter(o => o.poRefId === po.id || o.poRefId === poNo || o.linked_po_id === po.id);
            linkedOuts.forEach(out => {
                const outRate = parseFloat(out.rate || 0);
                if (outRate > 0) otherJwCost += outRate;
            });
        }
        return otherJwCost;
    };

    if (section === 'all') {
        const tbody = document.getElementById('semifinished-all-table-body');
        if (!tbody) return;

        const allPOs = (db.pos || []).filter(p => {
            if (p.status === 'Cancelled') return false;
            const pType = (p.poType || p.po_type || '').toLowerCase();
            const pNum = (p.number || '').toUpperCase();
            return !pNum.startsWith('PO/FJW') && !pNum.startsWith('PO/FIN') && pType !== 'finishing_jw';
        });

        const rows = [];
        allPOs.forEach(po => {
            const poNo = po.number || po.poNo || 'PO';
            const pType = (po.poType || po.po_type || '').toLowerCase();
            const pNum = (po.number || '').toUpperCase();
            const isInhouse = pType === 'inhouse' || pNum.startsWith('PO/INH');
            
            const partyName = isInhouse 
                ? (po.customerName || (db.customers ? db.customers.find(c => String(c.id) === String(po.customerId))?.name : null) || 'Internal')
                : (po.vendorName || (db.vendors ? db.vendors.find(v => String(v.id) === String(po.vendorId))?.name : null) || 'Vendor');
                
            const itemName = (po.items && po.items[0]?.itemName) || po.design || (po.items && po.items[0]?.processName) || 'Fabric';
            const poDate = po.date || '-';
            const qty = parseFloat(po.qty || po.items?.reduce((s, r) => s + (parseFloat(r.qty) || 0), 0) || 0);

            if (searchVal) {
                const match = poNo.toLowerCase().includes(searchVal) ||
                              partyName.toLowerCase().includes(searchVal) ||
                              itemName.toLowerCase().includes(searchVal);
                if (!match) return;
            }

            const otherJwCost = getOtherJwCost(po, !isInhouse);
            const mendingCost = window.semifinishedMendingCosts[po.id] !== undefined ? window.semifinishedMendingCosts[po.id] : 0;
            const totalCost = mendingCost + otherJwCost;
            const totalAmount = totalCost * qty;
            const sourceTypeStr = isInhouse ? 'inhouse' : 'vendor';

            rows.push(`
                <tr data-sf-id="${po.id}" data-sf-qty="${qty}" data-sf-other-jw="${otherJwCost}">
                    <td style="font-weight:700; color:var(--primary, #4338ca);">${poNo}</td>
                    <td>
                        <span class="badge ${isInhouse ? 'badge-primary' : 'badge-info'}" style="padding:3px 8px; font-size:11.5px; border-radius:4px; font-weight:600; background:${isInhouse ? '#e0e7ff' : '#e0f2fe'}; color:${isInhouse ? '#3730a3' : '#0369a1'};">
                            ${isInhouse ? '<� In-House' : '<� Vendor'}
                        </span>
                    </td>
                    <td>${partyName}</td>
                    <td><strong>${itemName}</strong></td>
                    <td>${poDate}</td>
                    <td style="text-align:right; font-weight:600;">${qty.toLocaleString()} m</td>
                    <td style="text-align:right;">
                        <input type="number" class="form-input" value="${mendingCost || ''}" placeholder="0.00" step="any"
                            style="width:100px; height:28px; padding:2px 8px; font-size:12.5px; text-align:right; font-weight:700; border:1px solid #cbd5e1; background:#ffffff !important; color:#0f172a;"
                            oninput="window.updateSemiFinishedMendingCost('${po.id}', this.value)">
                    </td>
                    <td style="text-align:right; font-weight:600; color:#059669;">�${otherJwCost.toFixed(2)}/m</td>
                    <td style="text-align:right; font-weight:700; color:var(--accent-purple, #6366f1);" class="sf-total-cost-cell">�${totalCost.toFixed(2)}/m</td>
                    <td style="text-align:right; font-weight:700; color:var(--text-primary);" class="sf-total-amt-cell">�${totalAmount.toLocaleString('en-IN', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
                    <td style="text-align:center;">
                        <button class="btn btn-sm btn-secondary" onclick="window.openFjwFromSemiFinished('${sourceTypeStr}', '${po.id}')" title="Issue Finishing Job Work Challan">+ Issue Job Work</button>
                    </td>
                </tr>
            `);
        });

        if (rows.length === 0) {
            tbody.innerHTML = `<tr><td colspan="11" class="empty-row">${searchVal ? 'No matching semi finished goods records found.' : 'No semi finished goods records found.'}</td></tr>`;
        } else {
            tbody.innerHTML = rows.join('');
        }

    } else if (section === 'inhouse') {
        const tbody = document.getElementById('semifinished-inhouse-table-body');
        if (!tbody) return;

        const inhousePOs = (db.pos || []).filter(p => {
            if (p.status === 'Cancelled') return false;
            const pType = (p.poType || p.po_type || '').toLowerCase();
            const pNum = (p.number || '').toUpperCase();
            return pType === 'inhouse' || pNum.startsWith('PO/INH');
        });

        const rows = [];
        inhousePOs.forEach(po => {
            const poNo = po.number || po.poNo || 'PO/INH';
            const custName = po.customerName || (db.customers ? db.customers.find(c => String(c.id) === String(po.customerId))?.name : null) || 'Internal';
            const itemName = (po.items && po.items[0]?.itemName) || po.design || (po.items && po.items[0]?.processName) || 'Plain Fabric';
            const qty = parseFloat(po.qty || po.items?.reduce((s, r) => s + (parseFloat(r.qty) || 0), 0) || 0);

            if (searchVal) {
                const match = poNo.toLowerCase().includes(searchVal) ||
                              custName.toLowerCase().includes(searchVal) ||
                              itemName.toLowerCase().includes(searchVal);
                if (!match) return;
            }

            const otherJwCost = getOtherJwCost(po, false);
            const mendingCost = window.semifinishedMendingCosts[po.id] !== undefined ? window.semifinishedMendingCosts[po.id] : 0;
            const totalCost = mendingCost + otherJwCost;
            const totalAmount = totalCost * qty;

            rows.push(`
                <tr data-sf-id="${po.id}" data-sf-qty="${qty}" data-sf-other-jw="${otherJwCost}">
                    <td style="font-weight:700; color:var(--primary, #4338ca);">${poNo}</td>
                    <td>${custName}</td>
                    <td><strong>${itemName}</strong></td>
                    <td style="text-align:right; font-weight:600;">${qty.toLocaleString()} m</td>
                    <td style="text-align:right;">
                        <input type="number" class="form-input" value="${mendingCost || ''}" placeholder="0.00" step="any"
                            style="width:100px; height:28px; padding:2px 8px; font-size:12.5px; text-align:right; font-weight:700; border:1px solid #cbd5e1; background:#ffffff !important; color:#0f172a;"
                            oninput="window.updateSemiFinishedMendingCost('${po.id}', this.value)">
                    </td>
                    <td style="text-align:right; font-weight:600; color:#059669;">\u20B9${otherJwCost.toFixed(2)}/m</td>
                    <td style="text-align:right; font-weight:700; color:var(--accent-purple, #6366f1);" class="sf-total-cost-cell">\u20B9${totalCost.toFixed(2)}/m</td>
                    <td style="text-align:right; font-weight:700; color:var(--text-primary);" class="sf-total-amt-cell">\u20B9${totalAmount.toLocaleString('en-IN', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
                    <td style="text-align:center;">
                        <button class="btn btn-sm btn-secondary" onclick="window.openFjwFromSemiFinished('inhouse', '${po.id}')" title="Create Finishing Job Work">+ Create PO/FJW</button>
                    </td>
                </tr>
            `);
        });

        if (rows.length === 0) {
            tbody.innerHTML = `<tr><td colspan="9" class="empty-row">${searchVal ? 'No matching In-House PO records found.' : 'No In-House PO production records found.'}</td></tr>`;
        } else {
            tbody.innerHTML = rows.join('');
        }

    } else {
        const tbody = document.getElementById('semifinished-vendor-table-body');
        if (!tbody) return;

        const vendorPOs = (db.pos || []).filter(p => {
            if (p.status === 'Cancelled') return false;
            const pType = (p.poType || p.po_type || '').toLowerCase();
            const pNum = (p.number || '').toUpperCase();
            return (pType === 'vendor' || pNum.startsWith('PO/V') || (!pNum.startsWith('PO/INH') && !pNum.startsWith('PO/FJW') && !pNum.startsWith('PO/FIN')));
        });

        const rows = [];
        vendorPOs.forEach(po => {
            const poNo = po.number || po.poNo || 'PO/V';
            const vendorName = po.vendorName || (db.vendors ? db.vendors.find(v => String(v.id) === String(po.vendorId))?.name : null) || 'Vendor';
            const itemName = (po.items && po.items[0]?.itemName) || po.design || (po.items && po.items[0]?.processName) || 'Fabric';
            const poDate = po.date || '-';
            const qty = parseFloat(po.qty || po.items?.reduce((s, r) => s + (parseFloat(r.qty) || 0), 0) || 0);

            if (searchVal) {
                const match = poNo.toLowerCase().includes(searchVal) ||
                              vendorName.toLowerCase().includes(searchVal) ||
                              itemName.toLowerCase().includes(searchVal);
                if (!match) return;
            }

            const otherJwCost = getOtherJwCost(po, true);
            const mendingCost = window.semifinishedMendingCosts[po.id] !== undefined ? window.semifinishedMendingCosts[po.id] : 0;
            const totalCost = mendingCost + otherJwCost;
            const totalAmount = totalCost * qty;

            rows.push(`
                <tr data-sf-id="${po.id}" data-sf-qty="${qty}" data-sf-other-jw="${otherJwCost}">
                    <td style="font-weight:700; color:var(--primary, #4338ca);">${poNo}</td>
                    <td>${vendorName}</td>
                    <td><strong>${itemName}</strong></td>
                    <td>${poDate}</td>
                    <td style="text-align:right; font-weight:600;">${qty.toLocaleString()} m</td>
                    <td style="text-align:right;">
                        <input type="number" class="form-input" value="${mendingCost || ''}" placeholder="0.00" step="any"
                            style="width:100px; height:28px; padding:2px 8px; font-size:12.5px; text-align:right; font-weight:700; border:1px solid #cbd5e1; background:#ffffff !important; color:#0f172a;"
                            oninput="window.updateSemiFinishedMendingCost('${po.id}', this.value)">
                    </td>
                    <td style="text-align:right; font-weight:600; color:#059669;">\u20B9${otherJwCost.toFixed(2)}/m</td>
                    <td style="text-align:right; font-weight:700; color:var(--accent-purple, #6366f1);" class="sf-total-cost-cell">\u20B9${totalCost.toFixed(2)}/m</td>
                    <td style="text-align:right; font-weight:700; color:var(--text-primary);" class="sf-total-amt-cell">\u20B9${totalAmount.toLocaleString('en-IN', {minimumFractionDigits: 2, maximumFractionDigits: 2})}</td>
                    <td style="text-align:center;">
                        <button class="btn btn-sm btn-secondary" onclick="window.openFjwFromSemiFinished('vendor', '${po.id}')" title="Issue Finishing Job Work Challan">+ Issue Job Work</button>
                    </td>
                </tr>
            `);
        });

        if (rows.length === 0) {
            tbody.innerHTML = `<tr><td colspan="10" class="empty-row">${searchVal ? 'No matching vendor PO records found.' : 'No vendor PO records found.'}</td></tr>`;
        } else {
            tbody.innerHTML = rows.join('');
        }
    }
};
// End of app.js

